window.DC=window.DC||{};DC.curriculum=JSON.parse('[{"n":1,"pos":1,"level":"A1","title":"Sich vorstellen: Personalpronomen, sein & haben","theme":"Ich und meine Familie","scene":"family","rec":[],"expl":["**Personalpronomen** ersetzen Namen: ich, du, er, sie, es, wir, ihr, sie, Sie (formell). **Sie** mit großem S benutzt man für fremde Erwachsene, Ärzte, Behörden.","**sein** (to be) und **haben** (to have) sind unregelmäßig und die wichtigsten Verben im Deutschen. Du brauchst sie für Name, Alter, Herkunft, Beruf, Familie und später für das Perfekt.","Achtung: Alter sagt man mit **sein**: __Ich bin 28 Jahre alt__ (nicht: ich habe 28 Jahre)."],"use":"Prüfung Teil 1 (Kontaktaufnahme): Name, Herkunft, Alter, Familie, Beruf.","table":[["Person","sein","haben","Beispiel"],["ich","bin","habe","Ich bin Ravi. Ich habe einen Bruder."],["du","bist","hast","Bist du müde? Hast du Zeit?"],["er / sie / es","ist","hat","Sie ist Lehrerin. Er hat Hunger."],["wir","sind","haben","Wir sind aus Indien."],["ihr","seid","habt","Seid ihr Studenten?"],["sie / Sie","sind","haben","Haben Sie Kinder?"]],"examples":[{"de":"Ich bin Ravi Sharma.","en":"I am Ravi Sharma."},{"de":"Ich bin 28 Jahre alt.","en":"I am 28 years old."},{"de":"Ich komme aus Indien.","en":"I come from India."},{"de":"Meine Schwester ist Ärztin.","en":"My sister is a doctor."},{"de":"Wir haben zwei Kinder.","en":"We have two children."},{"de":"Du bist sehr nett.","en":"You are very nice."},{"de":"Haben Sie ein Handy?","en":"Do you have a mobile phone?"},{"de":"Ihr seid neu hier, oder?","en":"You (pl.) are new here, right?"},{"de":"Er hat heute keine Zeit.","en":"He has no time today."},{"de":"Sind Sie Frau Weber?","en":"Are you Mrs. Weber?"},{"de":"Wie heißen Sie? – Ich heiße Leila Ahmadi.","en":"What is your name? – My name is Leila Ahmadi."},{"de":"Woher kommst du? – Aus Spanien.","en":"Where are you from? – From Spain."},{"de":"Ich spreche Hindi, Englisch und ein bisschen Deutsch.","en":"I speak Hindi, English and a little German."},{"de":"Das ist mein Mann. Er heißt Jonas.","en":"This is my husband. His name is Jonas."},{"de":"Wir sind nicht verheiratet.","en":"We are not married."},{"de":"Hast du Geschwister? – Ja, einen Bruder.","en":"Do you have siblings? – Yes, a brother."},{"de":"Meine Eltern sind schon alt.","en":"My parents are already old."},{"de":"Ihr habt eine schöne Wohnung.","en":"You (pl.) have a nice flat."},{"de":"Die Kinder sind in der Schule.","en":"The children are at school."},{"de":"Freut mich, Frau Weber!","en":"Nice to meet you, Mrs Weber!"}],"vocab":[{"de":"der Name, -n","en":"name"},{"de":"das Alter","en":"age"},{"de":"die Familie, -n","en":"family"},{"de":"der Vater, ¨","en":"father"},{"de":"die Mutter, ¨","en":"mother"},{"de":"der Bruder, ¨","en":"brother"},{"de":"die Schwester, -n","en":"sister"},{"de":"verheiratet / ledig","en":"married / single"},{"de":"der Beruf, -e","en":"profession"},{"de":"das Land, ¨er","en":"country"},{"de":"wohnen","en":"to live (reside)"},{"de":"kommen aus","en":"to come from"},{"de":"die Eltern (Pl.)","en":"parents"},{"de":"das Kind, -er","en":"child"},{"de":"der Sohn, ¨e","en":"son"},{"de":"die Tochter, ¨","en":"daughter"},{"de":"der Mann, ¨er","en":"man, husband"},{"de":"die Frau, -en","en":"woman, wife, Mrs"},{"de":"heißen","en":"to be called"},{"de":"sprechen (spricht)","en":"to speak"},{"de":"die Stadt, ¨e","en":"city, town"},{"de":"die Adresse, -n","en":"address"},{"de":"die Telefonnummer, -n","en":"phone number"},{"de":"geboren","en":"born"},{"de":"alt / jung","en":"old / young"},{"de":"geschieden","en":"divorced"},{"de":"der Ingenieur, -e / die Ingenieurin, -nen","en":"engineer"},{"de":"der Student, -en / die Studentin, -nen","en":"student"},{"de":"Herr / Frau","en":"Mr / Mrs"},{"de":"Freut mich!","en":"Nice to meet you!"}],"reading":"Hallo! Ich bin Ravi Sharma. Ich bin 28 Jahre alt und komme aus Mumbai, Indien. Ich bin Ingenieur. Jetzt wohne ich in Berlin. Ich bin ledig. Meine Familie ist in Mumbai: Mein Vater ist Lehrer, meine Mutter ist Ärztin. Ich habe eine Schwester. Sie heißt Priya und ist 24. Meine Nachbarin heißt Anna Weber. Sie ist sehr nett. Sie hat einen Sohn und eine Tochter.","tasks":[{"q":"Ich ___ Ravi. (sein)","a":"bin"},{"q":"Du ___ aus Mumbai, oder? (kommen)","a":"kommst"},{"q":"Anna ___ zwei Kinder. (haben)","a":"hat"},{"q":"Wir ___ Nachbarn. (sein)","a":"sind"},{"q":"___ ihr Hunger? (haben)","a":"Habt"},{"q":"___ Sie Herr Müller? (sein)","a":"Sind"},{"q":"Priya ___ 24 Jahre alt. (sein)","a":"ist"},{"q":"Ersetze durch ein Pronomen: __Anna und Ravi__ sind Nachbarn.","a":"Sie sind Nachbarn."},{"q":"Ersetze: __Das Kind__ ist müde.","a":"Es ist müde."},{"q":"Fehler? „Ich habe 28 Jahre.“","a":"Ich bin 28 Jahre alt."},{"q":"Wie ___ du? – Ich heiße Tomás. (heißen)","a":"heißt"},{"q":"Leila ___ Ärztin. (sein)","a":"ist"},{"q":"___ ihr Kinder? (haben)","a":"Habt"},{"q":"Ich ___ Deutsch und Englisch. (sprechen)","a":"spreche"},{"q":"Er ___ Persisch. (sprechen)","a":"spricht"},{"q":"Wir ___ aus Brasilien. (kommen)","a":"kommen"},{"q":"Formell: „Woher kommst du?“ →","a":"Woher kommen Sie?"},{"q":"Ersetze: __Tomás__ ist Student.","a":"Er ist Student."},{"q":"Ersetze: __Leila und ich__ sind Freunde.","a":"Wir sind Freunde."},{"q":"Fehler? „Er hat 25 Jahre alt.“","a":"Er ist 25 Jahre alt."}],"exam":[{"q":"Wie alt ist Ravi?","a":"28 Jahre."},{"q":"Was ist Ravis Mutter von Beruf?","a":"Ärztin."},{"q":"Richtig oder falsch: Ravis Familie wohnt in Berlin.","a":"Falsch (in Mumbai)."},{"q":"Ergänze: ___ du verheiratet?","a":"Bist"},{"q":"Ergänze: Meine Eltern ___ ein Haus.","a":"haben"},{"q":"Formell fragen: „Wie heißt du?“ → Sie-Form","a":"Wie heißen Sie?"},{"q":"Frage zur Antwort: „Ich komme aus Indien.“","a":"Woher kommst du / kommen Sie?"},{"q":"Stellen Sie sich vor: Name, Alter, Land, Wohnort, Beruf, Sprachen.","a":"","m":"Ich heiße Ravi Sharma. Ich bin 28 Jahre alt. Ich komme aus Indien und wohne jetzt in Berlin. Ich bin Ingenieur. Ich spreche Hindi, Englisch und ein bisschen Deutsch."},{"q":"Erzählen Sie über Ihre Familie (5 Sätze).","a":"","m":"Meine Familie ist nicht groß. Mein Vater ist Lehrer und meine Mutter ist Ärztin. Ich habe eine Schwester. Sie heißt Priya und ist 24 Jahre alt. Meine Eltern wohnen in Mumbai."},{"q":"Buchstabieren Sie Ihren Namen laut.","a":"","m":"R – A – V – I. S – H – A – R – M – A. (Say each letter in German: er, a, vau, i …)"}],"speak":["Wer ist auf dem Bild? Gib den Personen Namen: __Das ist … Er/Sie ist …__","Wie alt sind die Personen? Was sind sie von Beruf? (Vermutung)","Stell deine eigene Familie vor: __Ich habe … Mein Vater ist …__","Frage einen Partner: __Hast du Geschwister? Bist du verheiratet?__"],"reading2":{"title":"Ein Formular im Sprachkurs","text":"Heute ist der erste Tag im Deutschkurs. Die Lehrerin heißt Frau Krüger. Sie sagt: „Bitte füllen Sie das Formular aus.“ Leila schreibt: Name: Ahmadi. Vorname: Leila. Alter: 31 Jahre. Land: Iran. Wohnort: Berlin. Beruf: Ärztin. Familienstand: verheiratet. Kinder: eine Tochter. Sprachen: Persisch, Englisch, ein bisschen Deutsch. Neben Leila sitzt ein Mann. Er heißt Tomás und kommt aus Brasilien. Er ist 25 und Student. Er hat keine Kinder, aber er hat drei Schwestern. Tomás fragt: „Bist du auch neu hier?“ Leila sagt: „Ja. Ich bin seit zwei Monaten in Berlin.“ Die beiden sind sofort Freunde. Nach dem Kurs trinken sie zusammen einen Kaffee."},"dialog":[{"who":"Frau Krüger","de":"Guten Morgen! Ich bin Frau Krüger, Ihre Lehrerin. Wie heißen Sie?"},{"who":"Tomás","de":"Guten Morgen. Ich heiße Tomás Silva."},{"who":"Frau Krüger","de":"Woher kommen Sie, Herr Silva?"},{"who":"Tomás","de":"Ich komme aus Brasilien, aus São Paulo."},{"who":"Frau Krüger","de":"Und was machen Sie hier in Berlin?"},{"who":"Tomás","de":"Ich bin Student. Ich studiere Informatik."},{"who":"Frau Krüger","de":"Sehr schön. Welche Sprachen sprechen Sie?"},{"who":"Tomás","de":"Portugiesisch, Englisch und jetzt ein bisschen Deutsch."},{"who":"Frau Krüger","de":"Sehr gut! Herzlich willkommen im Kurs."}],"dq":[{"q":"Woher kommt Tomás?","a":"Aus Brasilien (São Paulo)."},{"q":"Was studiert Tomás?","a":"Informatik."},{"q":"Welche Sprachen spricht er?","a":"Portugiesisch, Englisch und ein bisschen Deutsch."}],"en":{"title":"Introducing yourself: personal pronouns, sein (to be) & haben (to have)","theme":"Me and my family","expl":["**Personal pronouns** replace names: ich (I), du (you, informal), er (he), sie (she), es (it), wir (we), ihr (you, plural), sie (they) and **Sie** (you, formal). Use **Sie** with a capital S for adults you don\'t know, doctors, officials – use **du** for friends, family and children.","**sein** (to be) and **haben** (to have) are irregular – you have to learn their forms by heart – and they are the most important verbs in German. You need them for your name, age, origin, job and family, and later for the past tense.","Careful: age uses **sein**, not haben: __Ich bin 28 Jahre alt.__ = I am 28 years old (not \\"ich habe 28 Jahre\\")."],"use":"Exam part 1 (getting to know someone): name, origin, age, family, job."},"check":[{"re":"\\\\b(bin|bist|ist|sind|seid)\\\\b","label":"a form of sein (bin, ist, sind …)"},{"re":"\\\\b(habe|hast|hat|haben|habt)\\\\b","label":"a form of haben (habe, hat …)"}]},{"n":2,"pos":2,"level":"A1","title":"Präsens: regelmäßige und unregelmäßige Verben","theme":"Alltag und Hobbys","scene":"park","rec":[1],"expl":["Im Präsens nimmst du den **Stamm** (Infinitiv ohne -en) und hängst Endungen an: **-e, -st, -t, -en, -t, -en**.","Stamm auf **-t/-d** (arbeiten, finden): du arbeit**est**, er arbeit**et**. Stamm auf **-s/-ß/-z** (heißen, tanzen): du hei**ßt**.","**Unregelmäßige Verben** ändern den Vokal nur bei **du** und **er/sie/es**: e → i (sprechen → spricht), e → ie (lesen → liest), a → ä (fahren → fährt).","Das Präsens benutzt man auch für die **Zukunft**: __Morgen fahre ich nach Hamburg.__"],"use":"Über Gewohnheiten, Hobbys und Pläne sprechen.","table":[["Person","spielen","arbeiten","fahren (a→ä)","sprechen (e→i)","lesen (e→ie)"],["ich","spiel**e**","arbeit**e**","fahr**e**","sprech**e**","les**e**"],["du","spiel**st**","arbeit**est**","f**ä**hr**st**","spr**i**ch**st**","l**ie**st"],["er/sie/es","spiel**t**","arbeit**et**","f**ä**hr**t**","spr**i**ch**t**","l**ie**st"],["wir","spiel**en**","arbeit**en**","fahr**en**","sprech**en**","les**en**"],["ihr","spiel**t**","arbeit**et**","fahr**t**","sprech**t**","les**t**"],["sie/Sie","spiel**en**","arbeit**en**","fahr**en**","sprech**en**","les**en**"]],"examples":[{"de":"Ich spiele gern Cricket.","en":"I like playing cricket."},{"de":"Du arbeitest viel.","en":"You work a lot."},{"de":"Anna liest jeden Abend.","en":"Anna reads every evening."},{"de":"Ravi spricht Hindi, Englisch und ein bisschen Deutsch.","en":"Ravi speaks Hindi, English and a bit of German."},{"de":"Fährst du mit dem Fahrrad?","en":"Do you go by bike?"},{"de":"Wir kochen am Sonntag zusammen.","en":"We cook together on Sunday."},{"de":"Er isst gern scharf.","en":"He likes eating spicy food."},{"de":"Was machst du am Wochenende?","en":"What are you doing at the weekend?"},{"de":"Sie schläft lange.","en":"She sleeps long."},{"de":"Morgen treffe ich Jonas.","en":"Tomorrow I\'m meeting Jonas."},{"de":"Was machst du am Wochenende?","en":"What are you doing at the weekend?"},{"de":"Ich höre gern Musik.","en":"I like listening to music."},{"de":"Er fährt jeden Tag mit dem Fahrrad.","en":"He cycles every day."},{"de":"Sie liest abends ein Buch.","en":"She reads a book in the evenings."},{"de":"Am Sonntag schläft Jonas lange.","en":"On Sunday Jonas sleeps in."},{"de":"Isst du gern Pizza?","en":"Do you like eating pizza?"},{"de":"Wir spielen zusammen Fußball.","en":"We play football together."},{"de":"Du sprichst sehr gut Deutsch!","en":"You speak German very well!"},{"de":"Ihr arbeitet viel.","en":"You (pl.) work a lot."},{"de":"Nimmst du einen Tee?","en":"Will you have a tea?"}],"vocab":[{"de":"das Hobby, -s","en":"hobby"},{"de":"spielen","en":"to play"},{"de":"kochen","en":"to cook"},{"de":"lesen (liest)","en":"to read"},{"de":"schwimmen","en":"to swim"},{"de":"laufen (läuft)","en":"to run"},{"de":"tanzen","en":"to dance"},{"de":"die Musik","en":"music"},{"de":"das Wochenende, -n","en":"weekend"},{"de":"gern","en":"gladly (like doing)"},{"de":"oft / manchmal / nie","en":"often / sometimes / never"},{"de":"treffen (trifft)","en":"to meet"},{"de":"machen","en":"to do, to make"},{"de":"hören","en":"to listen, to hear"},{"de":"lernen","en":"to learn, to study"},{"de":"arbeiten","en":"to work"},{"de":"fahren (fährt)","en":"to drive, to go (by vehicle)"},{"de":"schlafen (schläft)","en":"to sleep"},{"de":"essen (isst)","en":"to eat"},{"de":"sehen (sieht)","en":"to see"},{"de":"nehmen (nimmt)","en":"to take"},{"de":"das Fahrrad, ¨er","en":"bicycle"},{"de":"der Sport","en":"sport"},{"de":"der Fußball","en":"football"},{"de":"die Gitarre, -n","en":"guitar"},{"de":"das Buch, ¨er","en":"book"},{"de":"der Film, -e","en":"film"},{"de":"zusammen","en":"together"},{"de":"am Abend","en":"in the evening"},{"de":"jeden Tag","en":"every day"}],"reading":"Ravi arbeitet von Montag bis Freitag. Am Wochenende hat er Zeit. Er spielt gern Cricket, aber in Berlin spielt kaum jemand Cricket. Deshalb läuft er jetzt im Park. Seine Nachbarin Anna liest viel und tanzt gern. Ihr Sohn Max spielt Fußball. Anna fragt: „Was machst du gern, Ravi?“ Ravi sagt: „Ich koche gern indisch. Isst du gern scharf?“ Anna lacht: „Nicht so gern!“","tasks":[{"q":"Ravi ___ gern. (kochen)","a":"kocht"},{"q":"Du ___ gut Deutsch. (sprechen)","a":"sprichst"},{"q":"Anna ___ ein Buch. (lesen)","a":"liest"},{"q":"___ du am Montag? (arbeiten)","a":"Arbeitest"},{"q":"Max ___ mit dem Bus. (fahren)","a":"fährt"},{"q":"Wie ___ du? (heißen)","a":"heißt"},{"q":"Er ___ Jonas im Café. (treffen)","a":"trifft"},{"q":"[Mix] ___ du Zeit? Ich ___ heute frei. (haben / sein)","a":"Hast / bin"},{"q":"[Mix] Wir ___ aus Indien und ___ Hindi. (kommen / sprechen)","a":"kommen / sprechen"},{"q":"[Mix] Ersetze: __Anna__ läuft gern. → ___ läuft gern.","a":"Sie"},{"q":"Er ___ jeden Tag Fahrrad. (fahren)","a":"fährt"},{"q":"Du ___ gern Bücher. (lesen)","a":"liest"},{"q":"Mia ___ am Sonntag lange. (schlafen)","a":"schläft"},{"q":"___ du Fleisch? (essen)","a":"Isst"},{"q":"Wir ___ heute Abend zusammen. (kochen)","a":"kochen"},{"q":"Ihr ___ zu viel. (arbeiten)","a":"arbeitet"},{"q":"Sie (Sg.) ___ einen Film. (sehen)","a":"sieht"},{"q":"Er ___ einen Kaffee. (nehmen)","a":"nimmt"},{"q":"Du ___ in einer Bank. (arbeiten)","a":"arbeitest"},{"q":"Fehler? „Jonas fahrt zur Arbeit.“","a":"Jonas fährt zur Arbeit."}],"exam":[{"q":"Warum läuft Ravi jetzt im Park?","a":"Weil in Berlin kaum jemand Cricket spielt."},{"q":"Was macht Anna gern?","a":"Lesen und tanzen."},{"q":"Richtig oder falsch: Anna isst gern scharf.","a":"Falsch."},{"q":"Ergänze: ___ du gern Tee? (trinken)","a":"Trinkst"},{"q":"Ergänze: Sie ___ (Sg.) jeden Tag Zeitung. (lesen)","a":"liest"},{"q":"Ergänze: Der Zug ___ um 8 Uhr. (fahren)","a":"fährt"},{"q":"Frage zu: „Ich schwimme gern.“","a":"Was machst du gern?"},{"q":"Erzählen Sie über Ihre Hobbys (6 Sätze, mit oft/manchmal/nie).","a":"","m":"Ich habe viele Hobbys. Ich lese oft Bücher. Am Wochenende koche ich gern. Manchmal spiele ich Cricket mit Freunden. Ich tanze nie, denn ich tanze schlecht. Ich laufe oft im Park."},{"q":"Was machen Sie am Wochenende?","a":"","m":"Am Wochenende schlafe ich lange. Dann frühstücke ich mit meiner Familie. Am Nachmittag treffe ich Freunde. Am Abend sehe ich einen Film."},{"q":"Fragen Sie Ihren Partner nach drei Hobbys.","a":"","m":"Was machst du gern? Spielst du Fußball? Liest du gern? Kochst du oft?"}],"speak":["Was machen die Leute im Park? __Der Mann … Die Frau …__","Was machst du gern im Park?","Wie oft machst du Sport? __Ich laufe …-mal pro Woche.__","Vergleiche: Was machen die Leute in Indien am Wochenende?"],"reading2":{"title":"Die WG in der Goethestraße","text":"In einer Wohnung in der Goethestraße wohnen drei Personen zusammen: Jonas, Mia und Ravi. Das ist eine WG, eine Wohngemeinschaft. Jonas ist 29 und arbeitet in einer Bank. Er fährt jeden Morgen mit dem Fahrrad zur Arbeit. Am Abend spielt er Gitarre. Mia ist Studentin. Sie lernt viel und liest gern. Am Wochenende arbeitet sie in einem Café. Ravi kocht sehr gern, am liebsten indisch. Er isst kein Fleisch. Am Samstag kocht er für alle. Dann essen sie zusammen und sprechen über die Woche. Mia sagt: „Ravi, du kochst fantastisch!“ Am Sonntag schlafen alle lange. Am Nachmittag sehen sie oft zusammen einen Film. Manchmal spielen Jonas und Ravi Fußball im Park. Mia spielt nie mit. Sie findet Fußball langweilig."},"dialog":[{"who":"Mia","de":"Hallo Ravi! Was machst du heute Abend?"},{"who":"Ravi","de":"Ich koche. Isst du mit?"},{"who":"Mia","de":"Gern! Was kochst du denn?"},{"who":"Ravi","de":"Gemüsecurry mit Reis. Und Jonas bringt Brot mit."},{"who":"Mia","de":"Super. Ich lerne noch bis sieben Uhr."},{"who":"Ravi","de":"Kein Problem. Wir essen um halb acht."},{"who":"Mia","de":"Und danach? Sehen wir einen Film?"},{"who":"Ravi","de":"Ja, aber Jonas spielt danach Gitarre. Er übt für ein Konzert."},{"who":"Mia","de":"Oh nein! Dann lese ich lieber ein Buch."}],"dq":[{"q":"Was kocht Ravi?","a":"Gemüsecurry mit Reis."},{"q":"Wann essen sie?","a":"Um halb acht."},{"q":"Was macht Jonas nach dem Essen?","a":"Er spielt Gitarre / übt für ein Konzert."}],"en":{"title":"Present tense: regular and irregular verbs","theme":"Everyday life and hobbies","expl":["To make the present tense, take the **stem** (the infinitive without -en: wohn-en → **wohn**) and add the endings **-e, -st, -t, -en, -t, -en**: __ich wohne, du wohnst, er wohnt, wir wohnen, ihr wohnt, sie wohnen__.","Stems ending in **-t/-d** add an extra e so you can pronounce them: __du arbeitest, er arbeitet__. Stems ending in **-s/-ß/-z** only add -t for du: __du heißt, du tanzt__.","Irregular verbs change their vowel **only for du and er/sie/es**: e → i (__sprechen → du sprichst, er spricht__), e → ie (__lesen → er liest__), a → ä (__fahren → er fährt__). All other forms stay regular.","German has only one present tense: __Ich lerne__ means \\"I learn\\", \\"I am learning\\" and often \\"I will learn\\"."],"use":""},"check":[{"re":"\\\\b(oft|manchmal|nie|immer|selten)\\\\b","label":"oft / manchmal / nie"},{"re":"\\\\b(spiele|lese|koche|tanze|laufe|schwimme|höre|fahre|mache|treffe|sehe|spielst|liest|kochst|machst)\\\\b","label":"a present-tense verb with the right ending"}]},{"n":3,"pos":3,"level":"A1","title":"Satzbau: Das Verb steht auf Position 2","theme":"Mein Tag","scene":"city","rec":[1,2],"expl":["Im deutschen Hauptsatz steht das **konjugierte Verb immer auf Position 2**. Position 1 kann das Subjekt sein – oder eine Zeit, ein Ort, ein Objekt.","Steht etwas anderes auf Position 1, kommt das **Subjekt direkt nach dem Verb** (Inversion): __Heute **gehe ich** ins Kino.__","Eine Position kann aus mehreren Wörtern bestehen: __Am Montagmorgen um 8 Uhr__ = eine Position."],"use":"Abwechslungsreich sprechen: Sätze mit Zeit beginnen (Zuerst…, Dann…, Am Abend…).","table":[["Position 1","Position 2 (Verb)","Rest"],["Ich","fahre","morgen nach Hamburg."],["Morgen","fahre","ich nach Hamburg."],["Nach Hamburg","fahre","ich morgen."],["Am Montagmorgen","trinke","ich immer Chai."],["In Berlin","wohnt","Ravi seit März."]],"examples":[{"de":"Ich stehe um 7 Uhr auf.","en":"I get up at 7."},{"de":"Um 7 Uhr stehe ich auf.","en":"At 7 I get up."},{"de":"Morgens trinke ich Chai.","en":"In the morning I drink chai."},{"de":"Dann fahre ich ins Büro.","en":"Then I go to the office."},{"de":"Im Büro arbeite ich bis 17 Uhr.","en":"In the office I work until 5 pm."},{"de":"Am Abend koche ich.","en":"In the evening I cook."},{"de":"Heute hat Anna Geburtstag.","en":"Today it\'s Anna\'s birthday."},{"de":"Leider habe ich keine Zeit.","en":"Unfortunately I have no time."},{"de":"Am Wochenende spielt Max Fußball.","en":"At the weekend Max plays football."},{"de":"Danach lese ich ein bisschen.","en":"After that I read a little."},{"de":"Um sieben Uhr klingelt der Wecker.","en":"At seven the alarm clock rings."},{"de":"Dann dusche ich schnell.","en":"Then I take a quick shower."},{"de":"Im Büro trinke ich zuerst einen Kaffee.","en":"In the office I first drink a coffee."},{"de":"Heute arbeitet Ravi bis fünf Uhr.","en":"Today Ravi works until five."},{"de":"Am Mittag macht er eine Pause.","en":"At midday he takes a break."},{"de":"Nach der Arbeit fährt er nach Hause.","en":"After work he goes home."},{"de":"Abends ist er sehr müde.","en":"In the evenings he is very tired."},{"de":"Leider habe ich heute keine Zeit.","en":"Unfortunately I have no time today."},{"de":"Morgen schreibe ich die E-Mail.","en":"Tomorrow I will write the email."},{"de":"Am Wochenende schläft Mia lange.","en":"At the weekend Mia sleeps for a long time."}],"vocab":[{"de":"der Morgen / morgens","en":"morning / in the mornings"},{"de":"der Mittag / mittags","en":"noon"},{"de":"der Abend / abends","en":"evening"},{"de":"die Nacht / nachts","en":"night"},{"de":"heute / morgen / gestern","en":"today / tomorrow / yesterday"},{"de":"zuerst","en":"first"},{"de":"dann / danach","en":"then / after that"},{"de":"aufstehen","en":"to get up"},{"de":"frühstücken","en":"to have breakfast"},{"de":"das Büro, -s","en":"office"},{"de":"die U-Bahn","en":"underground train"},{"de":"leider","en":"unfortunately"},{"de":"der Wecker, -","en":"alarm clock"},{"de":"duschen","en":"to shower"},{"de":"der Kaffee","en":"coffee"},{"de":"die Arbeit","en":"work"},{"de":"die Pause, -n","en":"break"},{"de":"das Mittagessen","en":"lunch"},{"de":"das Abendessen","en":"dinner"},{"de":"nach Hause","en":"(to) home"},{"de":"zu Hause","en":"at home"},{"de":"spät / früh","en":"late / early"},{"de":"um sieben Uhr","en":"at seven o\'clock"},{"de":"endlich","en":"finally"},{"de":"müde","en":"tired"},{"de":"schnell","en":"quickly, fast"},{"de":"lange","en":"for a long time"},{"de":"am Wochenende","en":"at the weekend"},{"de":"das Handy, -s","en":"mobile phone"},{"de":"die E-Mail, -s","en":"email"}],"reading":"Ravis Tag ist voll. Um 6:30 Uhr klingelt der Wecker. Zuerst trinkt er Chai. Dann frühstückt er. Um 7:45 Uhr nimmt er die U-Bahn. Im Büro arbeitet er mit Jonas. Mittags essen sie zusammen. Am Nachmittag hat Ravi Meetings. Um 17 Uhr fährt er nach Hause. Am Abend lernt er Deutsch. Um 23 Uhr schläft er.","tasks":[{"q":"Stelle um (Beginne mit „Heute“): Ich lerne Deutsch.","a":"Heute lerne ich Deutsch."},{"q":"Stelle um (Beginne mit „Um 8 Uhr“): Ravi nimmt die U-Bahn.","a":"Um 8 Uhr nimmt Ravi die U-Bahn."},{"q":"Ordne: arbeitet / im Büro / Jonas / heute","a":"Heute arbeitet Jonas im Büro."},{"q":"Ordne: ich / abends / koche","a":"Abends koche ich."},{"q":"Ordne: dann / wir / Kaffee / trinken","a":"Dann trinken wir Kaffee."},{"q":"Fehler? „Morgen ich fahre nach Hamburg.“","a":"Morgen fahre ich nach Hamburg."},{"q":"Fehler? „Am Sonntag Anna liest.“","a":"Am Sonntag liest Anna."},{"q":"[Mix] Leider ___ ich keine Zeit. (haben)","a":"habe"},{"q":"[Mix] Am Wochenende ___ Max Fußball. (spielen)","a":"spielt"},{"q":"[Mix] Mittags ___ du mit Jonas? (essen)","a":"isst"},{"q":"Satz mit „Heute“ beginnen: Ich arbeite bis fünf.","a":"Heute arbeite ich bis fünf."},{"q":"Satz mit „Dann“ beginnen: Sie duscht.","a":"Dann duscht sie."},{"q":"Satz mit „Am Abend“ beginnen: Wir sehen fern.","a":"Am Abend sehen wir fern."},{"q":"Satz mit „Leider“ beginnen: Ich habe keine Zeit.","a":"Leider habe ich keine Zeit."},{"q":"Satz mit „Um sieben Uhr“ beginnen: Der Wecker klingelt.","a":"Um sieben Uhr klingelt der Wecker."},{"q":"Satz mit „Morgen“ beginnen: Er fährt nach Hamburg.","a":"Morgen fährt er nach Hamburg."},{"q":"Fehler? „Am Mittag er isst in der Kantine.“","a":"Am Mittag isst er in der Kantine."},{"q":"Fehler? „Zuerst ich trinke Kaffee.“","a":"Zuerst trinke ich Kaffee."},{"q":"Ordne: um acht / beginnt / die Arbeit","a":"Die Arbeit beginnt um acht."},{"q":"Ordne: nach Hause / fährt / Leila / um vier","a":"Leila fährt um vier nach Hause."}],"exam":[{"q":"Was macht Ravi zuerst?","a":"Er trinkt Chai."},{"q":"Mit wem isst Ravi mittags?","a":"Mit Jonas."},{"q":"Wann lernt Ravi Deutsch?","a":"Am Abend."},{"q":"Beginne mit „Am Abend“: Wir sehen fern.","a":"Am Abend sehen wir fern."},{"q":"Beginne mit „Leider“: Ich kann nicht kommen.","a":"Leider kann ich nicht kommen."},{"q":"Ordne: um 9 Uhr / der Kurs / beginnt","a":"Um 9 Uhr beginnt der Kurs."},{"q":"Ordne: gestern / Anna / war / krank","a":"Gestern war Anna krank."},{"q":"Beschreiben Sie Ihren Tagesablauf mit zuerst, dann, danach, am Abend.","a":"","m":"Zuerst stehe ich um 7 Uhr auf. Dann dusche ich und frühstücke. Danach fahre ich mit dem Bus zur Arbeit. Am Abend koche ich und sehe fern."},{"q":"Was machen Sie am Montag anders als am Sonntag?","a":"","m":"Am Montag stehe ich früh auf und arbeite. Am Sonntag schlafe ich lange. Am Montag habe ich wenig Zeit, aber am Sonntag treffe ich Freunde."},{"q":"Fragen Sie: Wann stehst du auf?","a":"","m":"Wann stehst du auf? – Ich stehe um halb sieben auf."}],"speak":["Beschreibe die Stadt: __Links sehe ich … Rechts steht …__","Was macht der Mann? Wohin fährt der Bus? (Vermutung)","Beschreibe deinen Weg zur Arbeit / zur Schule. Beginne jeden Satz anders.","Wie ist ein Tag in Mumbai? __In Mumbai fahren viele Leute …__"],"reading2":{"title":"Ein Montag von Leila","text":"Leila ist Ärztin in einem Krankenhaus. Ihr Tag beginnt sehr früh. Um halb sechs klingelt der Wecker. Zuerst duscht Leila, dann frühstückt sie mit ihrem Mann. Um Viertel nach sechs fährt sie mit der U-Bahn zur Arbeit. Im Krankenhaus trinkt sie zuerst einen Kaffee. Dann sieht sie die Patienten. Am Mittag isst sie in der Kantine. Die Pause ist kurz, nur zwanzig Minuten. Am Nachmittag hat sie viele Termine. Um vier Uhr ist die Arbeit zu Ende. Danach holt sie ihre Tochter vom Kindergarten ab. Zu Hause spielen sie zusammen. Um acht Uhr schläft die Tochter. Leila liest noch ein bisschen. Um zehn Uhr ist sie sehr müde. Montags ist ihr Tag immer lang."},"dialog":[{"who":"Jonas","de":"Morgen, Ravi! Du bist ja schon wach!"},{"who":"Ravi","de":"Ja, heute beginnt meine Arbeit um acht."},{"who":"Jonas","de":"Um acht? Das ist früh. Frühstückst du noch?"},{"who":"Ravi","de":"Nein, keine Zeit. Ich trinke nur schnell einen Kaffee."},{"who":"Jonas","de":"Und wann kommst du nach Hause?"},{"who":"Ravi","de":"Heute spät, so um sieben. Wir haben ein Meeting."},{"who":"Jonas","de":"Dann koche ich heute. Okay?"},{"who":"Ravi","de":"Super, danke! Bis heute Abend!"}],"dq":[{"q":"Wann beginnt Ravis Arbeit?","a":"Um acht Uhr."},{"q":"Was macht Ravi zum Frühstück?","a":"Er trinkt nur einen Kaffee."},{"q":"Wer kocht heute?","a":"Jonas."}],"en":{"title":"Word order: the verb is in position 2","theme":"My day","expl":["In a normal German sentence the **conjugated verb is always in position 2**. Position 1 can be the subject – or a time, a place or an object.","If something other than the subject is in position 1, the subject moves **directly after the verb**: __Heute gehe ich ins Kino.__ = Today I\'m going to the cinema (literally \\"Today go I to the cinema\\").","One position can be several words: __Am Montagmorgen um 8 Uhr__ is all position 1, so the verb still comes next: __Am Montagmorgen um 8 Uhr beginnt der Kurs.__","Typical order in the middle of the sentence: time – manner – place (**te-ka-mo-lo**): __Ich fahre morgen mit dem Bus nach Berlin.__"],"use":""},"check":[{"re":"\\\\b(zuerst|dann|danach|am abend|am morgen|um \\\\d+ uhr)\\\\b","label":"time words (zuerst, dann, danach …)"},{"re":"\\\\b(zuerst|dann|danach|heute|morgen|am \\\\w+|um \\\\d+ uhr) (stehe|gehe|frühstücke|fahre|arbeite|esse|trinke|komme|lerne|mache|sehe|dusche|koche|lese|bin|habe)\\\\b","label":"verb right after the time word (position 2)"}]},{"n":4,"pos":4,"level":"A1","title":"Fragen: Ja/Nein-Fragen und W-Fragen","theme":"Kennenlernen","scene":"classroom","rec":[1,2,3],"expl":["**W-Frage:** W-Wort auf Position 1, Verb auf Position 2: __**Wo wohnst** du?__","**Ja/Nein-Frage:** Das Verb steht auf **Position 1**: __**Wohnst** du in Berlin?__","Antwort auf eine **negative** Frage mit **doch** (= ja): __Kommst du nicht? – **Doch**, ich komme!__","Höflich mit Sie: __Können Sie mir helfen? Woher kommen Sie?__"],"use":"In der Prüfung stellst du deinem Partner Fragen (Teil 1 und nach der Präsentation).","table":[["Fragetyp","Position 1","Position 2","Rest","Antwort"],["W-Frage","Woher","kommst","du?","Aus Indien."],["W-Frage","Wie lange","wohnst","du schon hier?","Seit drei Monaten."],["Ja/Nein","Sprichst","du","Deutsch?","Ja / Nein, nur ein bisschen."],["Ja/Nein negativ","Hast","du","keinen Hunger?","Doch! / Nein."],["Höflich","Wie","heißen","Sie?","Ich heiße …"]],"examples":[{"de":"Wie heißt du?","en":"What\'s your name?"},{"de":"Woher kommen Sie?","en":"Where do you come from?"},{"de":"Was bist du von Beruf?","en":"What\'s your job?"},{"de":"Welche Sprachen sprichst du?","en":"Which languages do you speak?"},{"de":"Wie lange lernst du schon Deutsch?","en":"How long have you been learning German?"},{"de":"Hast du Geschwister?","en":"Do you have siblings?"},{"de":"Wohnst du allein?","en":"Do you live alone?"},{"de":"Warum lernst du Deutsch?","en":"Why are you learning German?"},{"de":"Wie oft machst du Sport?","en":"How often do you do sport?"},{"de":"Bist du nicht müde? – Doch!","en":"Aren\'t you tired? – Yes, I am!"},{"de":"Wie lange wohnst du schon hier?","en":"How long have you lived here?"},{"de":"Was bedeutet das Wort „Feierabend“?","en":"What does the word \\"Feierabend\\" mean?"},{"de":"Können Sie das bitte wiederholen?","en":"Can you repeat that, please?"},{"de":"Wie schreibt man das?","en":"How do you write that?"},{"de":"Sprechen Sie bitte langsam!","en":"Please speak slowly!"},{"de":"Verstehst du die Frage?","en":"Do you understand the question?"},{"de":"Wo ist hier die Toilette?","en":"Where is the toilet here?"},{"de":"Wann beginnt der Kurs?","en":"When does the course start?"},{"de":"Wohin fährst du am Wochenende?","en":"Where are you going at the weekend?"},{"de":"Hast du keine Zeit? – Doch, ich habe Zeit.","en":"Don\'t you have time? – Yes, I do have time."}],"vocab":[{"de":"wer","en":"who"},{"de":"was","en":"what"},{"de":"wo / woher / wohin","en":"where / from where / to where"},{"de":"wann","en":"when"},{"de":"warum","en":"why"},{"de":"wie","en":"how"},{"de":"wie viel(e)","en":"how much / many"},{"de":"welch-","en":"which"},{"de":"seit","en":"since / for"},{"de":"der Kurs, -e","en":"course"},{"de":"die Sprache, -n","en":"language"},{"de":"doch","en":"yes (to negative question)"},{"de":"wie lange","en":"how long"},{"de":"wie alt","en":"how old"},{"de":"wie spät","en":"what time"},{"de":"fragen","en":"to ask"},{"de":"antworten","en":"to answer"},{"de":"die Frage, -n","en":"question"},{"de":"die Antwort, -en","en":"answer"},{"de":"verstehen","en":"to understand"},{"de":"wiederholen","en":"to repeat"},{"de":"buchstabieren","en":"to spell"},{"de":"langsam","en":"slowly"},{"de":"noch einmal","en":"once more, again"},{"de":"das Wort, ¨er","en":"word"},{"de":"bedeuten","en":"to mean"},{"de":"die Hausaufgabe, -n","en":"homework"},{"de":"die Lehrerin, -nen","en":"teacher (f)"},{"de":"richtig / falsch","en":"right / wrong"},{"de":"Entschuldigung!","en":"Excuse me! / Sorry!"}],"reading":"Im Deutschkurs fragt Frau Klein: „Wer ist neu hier?“ Ravi sagt: „Ich.“ Leila fragt ihn: „Woher kommst du?“ – „Aus Indien. Und du?“ – „Aus dem Iran. Wie lange bist du schon in Berlin?“ – „Seit drei Monaten.“ – „Und warum lernst du Deutsch?“ – „Für meine Arbeit. Sprichst du auch Englisch?“ – „Ja, ein bisschen.“ – „Hast du keinen Hunger? Die Pause beginnt!“ – „Doch! Gehen wir.“","tasks":[{"q":"___ kommst du? – Aus dem Iran.","a":"Woher"},{"q":"___ heißt die Lehrerin? – Frau Klein.","a":"Wie"},{"q":"___ beginnt der Kurs? – Um 9 Uhr.","a":"Wann"},{"q":"___ Sprachen sprichst du? – Hindi und Englisch.","a":"Welche"},{"q":"___ Geschwister hast du? – Zwei.","a":"Wie viele"},{"q":"Mache eine Ja/Nein-Frage: Du wohnst in Berlin.","a":"Wohnst du in Berlin?"},{"q":"Mache eine Sie-Frage: Sie haben Zeit.","a":"Haben Sie Zeit?"},{"q":"Antworte positiv: Hast du keine Zeit?","a":"Doch, ich habe Zeit."},{"q":"[Mix] Frage mit „wann“: Ravi steht um 6:30 Uhr auf.","a":"Wann steht Ravi auf?"},{"q":"[Mix] Frage: Anna liest gern. (Was …?)","a":"Was macht Anna gern?"},{"q":"Ja/Nein-Frage: Du kommst aus Japan.","a":"Kommst du aus Japan?"},{"q":"Ja/Nein-Frage: Sie wohnt in Berlin.","a":"Wohnt sie in Berlin?"},{"q":"W-Frage zur Antwort: „Ich wohne in Köln.“","a":"Wo wohnst du?"},{"q":"W-Frage zur Antwort: „Ich komme aus Polen.“","a":"Woher kommst du?"},{"q":"W-Frage zur Antwort: „Der Kurs beginnt um neun.“","a":"Wann beginnt der Kurs?"},{"q":"W-Frage zur Antwort: „Ich bin 30.“","a":"Wie alt bist du?"},{"q":"W-Frage zur Antwort: „Das kostet zwei Euro.“","a":"Wie viel kostet das?"},{"q":"Antworte positiv: Hast du keinen Hunger? – ___, ich habe Hunger.","a":"Doch"},{"q":"Antworte: Kommst du nicht mit? – Doch, ich ___ mit.","a":"komme"},{"q":"Fehler? „Wo du wohnst?“","a":"Wo wohnst du?"}],"exam":[{"q":"Woher kommt Leila?","a":"Aus dem Iran."},{"q":"Seit wann ist Ravi in Berlin?","a":"Seit drei Monaten."},{"q":"Warum lernt Ravi Deutsch?","a":"Für seine Arbeit."},{"q":"Frage zur Antwort: „Ich bin Ingenieur.“","a":"Was bist du von Beruf?"},{"q":"Frage zur Antwort: „Ich wohne in Pankow.“","a":"Wo wohnst du?"},{"q":"Frage zur Antwort: „Nein, ich bin ledig.“","a":"Bist du verheiratet?"},{"q":"Antworte: „Kommst du nicht mit?“ (positiv)","a":"Doch, ich komme mit."},{"q":"Stellen Sie Ihrem Partner 6 Fragen (Name, Land, Wohnort, Beruf, Sprachen, Hobby).","a":"","m":"Wie heißt du? Woher kommst du? Wo wohnst du? Was bist du von Beruf? Welche Sprachen sprichst du? Was ist dein Hobby?"},{"q":"Sie treffen einen neuen Kollegen. Stellen Sie 3 höfliche Fragen mit Sie.","a":"","m":"Wie heißen Sie? Woher kommen Sie? Arbeiten Sie schon lange hier?"},{"q":"Welche Fragen stellt man beim ersten Treffen nicht? Warum?","a":"","m":"Beim ersten Treffen fragt man nicht: Wie viel verdienen Sie? Wie alt sind Sie? Das ist zu privat."}],"speak":["Wer ist die Frau vorne? Was macht sie?","Stelle 5 Fragen zum Bild: __Wie viele Schüler …? Was steht an der Tafel?__","Rollenspiel: Du bist neu im Kurs. Stelle dich vor und frage den Nachbarn.","Warum lernen die Leute im Kurs Deutsch? (Vermutung)"],"reading2":{"title":"Fragen in der Pause","text":"In der Pause sitzen die Kursteilnehmer zusammen. Sie fragen und antworten. Tomás fragt Aiko: „Woher kommst du?“ Aiko antwortet: „Aus Japan, aus Osaka.“ – „Und wie lange bist du schon in Berlin?“ – „Seit drei Wochen.“ Dann fragt Aiko: „Was machst du in Berlin?“ Tomás sagt: „Ich studiere. Und du?“ – „Ich arbeite als Designerin.“ Leila hat eine Frage für die Lehrerin: „Frau Krüger, was bedeutet ‚Feierabend‘?“ Frau Krüger erklärt: „Feierabend ist das Ende der Arbeit. Um fünf Uhr habe ich Feierabend.“ Leila versteht das Wort nicht sofort. Sie fragt: „Können Sie das bitte noch einmal sagen?“ Frau Krüger wiederholt es langsam. Jetzt ist alles klar. Feierabend ist ein schönes Wort."},"dialog":[{"who":"Aiko","de":"Entschuldigung, ist der Platz hier frei?"},{"who":"Leila","de":"Ja, natürlich. Bist du neu im Kurs?"},{"who":"Aiko","de":"Ja, heute ist mein erster Tag. Ich heiße Aiko."},{"who":"Leila","de":"Ich bin Leila. Woher kommst du, Aiko?"},{"who":"Aiko","de":"Aus Japan. Und du?"},{"who":"Leila","de":"Aus dem Iran. Wie lange bist du schon in Deutschland?"},{"who":"Aiko","de":"Erst drei Wochen. Wie spät ist es jetzt?"},{"who":"Leila","de":"Kurz vor zehn. Die Pause ist gleich zu Ende."},{"who":"Aiko","de":"Wann ist der Kurs zu Ende?"},{"who":"Leila","de":"Um halb eins."}],"dq":[{"q":"Woher kommt Aiko?","a":"Aus Japan."},{"q":"Wie lange ist Aiko schon in Deutschland?","a":"Drei Wochen."},{"q":"Wann ist der Kurs zu Ende?","a":"Um halb eins."}],"en":{"title":"Questions: yes/no questions and W-questions","theme":"Getting to know people","expl":["**W-questions** start with a question word (wer = who, was = what, wo = where, woher = where from, wohin = where to, wann = when, wie = how, warum = why). The question word is in position 1 and the verb in position 2: __Wo wohnst du?__ = Where do you live?","**Yes/no questions** start with the verb: __Wohnst du in Berlin?__ = Do you live in Berlin? German has no \\"do\\" for questions – you simply put the verb first.","To answer **yes** to a negative question, say **doch**: __Kommst du nicht? – Doch, ich komme!__ = Aren\'t you coming? – Yes, I am!","Polite with Sie: __Können Sie mir helfen? Woher kommen Sie?__"],"use":""},"check":[{"re":"\\\\?\\\\s*$|\\\\?","label":"questions with a question mark"},{"re":"\\\\b(wie|wo|woher|wohin|was|wann|warum|wer)\\\\b","label":"W-words (wie, wo, woher …)"}]},{"n":5,"pos":5,"level":"A1","title":"Nomen: Genus, Artikel, Plural (Nominativ)","theme":"Wohnung und Möbel","scene":"apartment","rec":[1,2,3,4],"expl":["Jedes Nomen hat ein **Genus**: **der** (maskulin), **die** (feminin), **das** (neutral). Lerne jedes Nomen **immer mit Artikel und Plural**.","**Tipps:** -ung, -heit, -keit, -ion, -schaft, -e → meistens **die**. -chen, -lein, -ment, -um → **das**. Tage, Monate, Jahreszeiten, -er (Personen), -ismus → **der**.","**Plural:** Der Artikel im Plural ist immer **die**. Endungen: -e, -¨e, -er, -¨er, -n/-en, -s, oder keine Endung.","**Unbestimmt:** ein (der/das), eine (die), Plural ohne Artikel. Der **Nominativ** ist der Fall für das **Subjekt**."],"use":"Wohnung beschreiben, Dinge benennen, Bilder beschreiben.","table":[["Genus","bestimmt","unbestimmt","Beispiel","Plural"],["maskulin","der","ein","der Tisch","die Tisch**e**"],["feminin","die","eine","die Lampe","die Lampe**n**"],["neutral","das","ein","das Bett","die Bett**en**"],["neutral","das","ein","das Zimmer","die Zimmer (–)"],["maskulin","der","ein","der Stuhl","die St**ü**hl**e**"],["neutral","das","ein","das Sofa","die Sofa**s**"]],"examples":[{"de":"Das ist ein Sofa. Das Sofa ist neu.","en":"This is a sofa. The sofa is new."},{"de":"Die Wohnung hat zwei Zimmer.","en":"The flat has two rooms."},{"de":"Der Schrank ist groß.","en":"The wardrobe is big."},{"de":"Die Lampe ist kaputt.","en":"The lamp is broken."},{"de":"Das Bett steht im Schlafzimmer.","en":"The bed is in the bedroom."},{"de":"Die Stühle sind bequem.","en":"The chairs are comfortable."},{"de":"Ist das ein Regal? – Ja, das ist ein Regal.","en":"Is that a shelf? – Yes."},{"de":"Die Bücher sind im Regal.","en":"The books are on the shelf."},{"de":"Wie viel kostet der Teppich?","en":"How much is the carpet?"},{"de":"Die Küche ist klein, aber hell.","en":"The kitchen is small but bright."},{"de":"Das ist der Kühlschrank. Er ist neu.","en":"This is the fridge. It is new."},{"de":"Die Küche ist klein, aber hell.","en":"The kitchen is small but bright."},{"de":"Das Wohnzimmer hat zwei Fenster.","en":"The living room has two windows."},{"de":"Die Stühle sind alt.","en":"The chairs are old."},{"de":"Wo ist das Bad? – Das Bad ist links.","en":"Where is the bathroom? – The bathroom is on the left."},{"de":"Der Balkon ist sehr schön.","en":"The balcony is very nice."},{"de":"Die Lampen sind modern.","en":"The lamps are modern."},{"de":"Ist das ein Sofa oder ein Bett?","en":"Is that a sofa or a bed?"},{"de":"Das sind keine Regale, das sind Schränke.","en":"Those aren\'t shelves, those are cupboards."},{"de":"Die Wohnung ist gemütlich.","en":"The flat is cosy."}],"vocab":[{"de":"die Wohnung, -en","en":"flat"},{"de":"das Zimmer, -","en":"room"},{"de":"die Küche, -n","en":"kitchen"},{"de":"das Bad, ¨er","en":"bathroom"},{"de":"der Tisch, -e","en":"table"},{"de":"der Stuhl, ¨e","en":"chair"},{"de":"das Bett, -en","en":"bed"},{"de":"der Schrank, ¨e","en":"wardrobe"},{"de":"das Regal, -e","en":"shelf"},{"de":"die Lampe, -n","en":"lamp"},{"de":"der Teppich, -e","en":"carpet"},{"de":"die Miete, -n","en":"rent"},{"de":"das Sofa, -s","en":"sofa"},{"de":"der Kühlschrank, ¨e","en":"fridge"},{"de":"der Herd, -e","en":"cooker, stove"},{"de":"die Waschmaschine, -n","en":"washing machine"},{"de":"das Fenster, -","en":"window"},{"de":"die Tür, -en","en":"door"},{"de":"der Balkon, -e","en":"balcony"},{"de":"der Flur, -e","en":"hallway"},{"de":"das Wohnzimmer, -","en":"living room"},{"de":"das Schlafzimmer, -","en":"bedroom"},{"de":"der Garten, ¨","en":"garden"},{"de":"das Haus, ¨er","en":"house"},{"de":"der Spiegel, -","en":"mirror"},{"de":"die Uhr, -en","en":"clock, watch"},{"de":"hell / dunkel","en":"bright / dark"},{"de":"groß / klein","en":"big / small"},{"de":"neu / alt","en":"new / old"},{"de":"gemütlich","en":"cosy"}],"reading":"Ravi hat jetzt eine Wohnung in Pankow. Die Wohnung hat zwei Zimmer, eine Küche und ein Bad. Das Wohnzimmer ist hell. Dort stehen ein Sofa und ein Regal. Das Regal ist voll: Die Bücher sind aus Indien. Im Schlafzimmer steht ein Bett. Die Lampe ist leider kaputt. Die Küche ist klein. Die Miete ist nicht billig, aber die Wohnung ist schön.","tasks":[{"q":"___ Wohnung (der/die/das)","a":"die"},{"q":"___ Zimmer","a":"das"},{"q":"___ Tisch","a":"der"},{"q":"___ Zeitung (Tipp: -ung)","a":"die"},{"q":"___ Mädchen (Tipp: -chen)","a":"das"},{"q":"Plural: der Stuhl → die ___","a":"Stühle"},{"q":"Plural: das Buch → die ___","a":"Bücher"},{"q":"[Mix] Das ist ___ Lampe. ___ Lampe ___ kaputt. (ein/e, der/die/das, sein)","a":"eine / Die / ist"},{"q":"[Mix] Frage: ___ kostet das Sofa?","a":"Wie viel / Was"},{"q":"[Mix] Ordne: steht / im Zimmer / ein Bett","a":"Im Zimmer steht ein Bett."},{"q":"___ Kühlschrank ist neu. (der/die/das)","a":"Der"},{"q":"___ Küche ist klein. (der/die/das)","a":"Die"},{"q":"___ Fenster ist groß. (der/die/das)","a":"Das"},{"q":"Plural: der Stuhl → die ___","a":"Stühle"},{"q":"Plural: das Zimmer → die ___","a":"Zimmer"},{"q":"Plural: die Lampe → die ___","a":"Lampen"},{"q":"Plural: das Bett → die ___","a":"Betten"},{"q":"Plural: der Schrank → die ___","a":"Schränke"},{"q":"Ersetze mit Pronomen: __Die Wohnung__ ist hell.","a":"Sie ist hell."},{"q":"Ersetze mit Pronomen: __Der Balkon__ ist groß.","a":"Er ist groß."}],"exam":[{"q":"Wo wohnt Ravi?","a":"In Pankow."},{"q":"Wie viele Zimmer hat die Wohnung?","a":"Zwei."},{"q":"Was ist kaputt?","a":"Die Lampe."},{"q":"Artikel + Plural: Küche","a":"die Küche, die Küchen"},{"q":"Artikel + Plural: Bad","a":"das Bad, die Bäder"},{"q":"Artikel + Plural: Schrank","a":"der Schrank, die Schränke"},{"q":"Artikel: Freiheit / Dokument / Montag","a":"die / das / der"},{"q":"Beschreiben Sie Ihre Wohnung: Wie viele Zimmer? Was steht wo?","a":"","m":"Meine Wohnung hat drei Zimmer, eine Küche und ein Bad. Im Wohnzimmer steht ein Sofa. Das Bett steht im Schlafzimmer. Die Küche ist klein, aber hell."},{"q":"Was ist Ihr Lieblingszimmer? Warum?","a":"","m":"Mein Lieblingszimmer ist das Wohnzimmer. Es ist groß und hell. Dort ist mein Sofa, und ich lese da gern."},{"q":"Wie wohnt man in Indien? Vergleichen Sie kurz.","a":"","m":"In Indien wohnen oft viele Personen zusammen. Die Familie ist groß. In Deutschland wohnen viele Leute allein. Die Wohnungen sind oft klein."}],"speak":["Welche Zimmer siehst du? __Links ist das …, rechts ist das …__","Nenne 8 Möbel mit Artikel.","Wie findest du die Wohnung? __Das Sofa ist … Die Lampe ist …__","Beschreibe dein Traumhaus."],"reading2":{"title":"Eine Wohnung zu vermieten","text":"Anzeige: Schöne 3-Zimmer-Wohnung in Berlin-Pankow, 72 Quadratmeter, 2. Stock. Die Wohnung hat ein Wohnzimmer, zwei Schlafzimmer, eine Küche, ein Bad und einen Balkon. Die Küche ist neu: Herd, Kühlschrank und Spülmaschine sind da. Das Bad hat eine Dusche und ein Fenster. Die Zimmer sind hell und ruhig. Der Balkon ist groß, perfekt für Pflanzen. Die Miete ist 980 Euro warm. Die Wohnung ist frei ab dem 1. März. Haustiere sind leider nicht erlaubt. Die U-Bahn ist nur fünf Minuten entfernt. Ein Supermarkt und ein Park sind auch in der Nähe. Interesse? Rufen Sie an: Hausverwaltung Schmidt, Telefon 030 4455 6677."},"dialog":[{"who":"Ravi","de":"Guten Tag, ich rufe wegen der Wohnung in Pankow an."},{"who":"Frau Schmidt","de":"Guten Tag. Ja, die Wohnung ist noch frei."},{"who":"Ravi","de":"Wie groß ist die Wohnung?"},{"who":"Frau Schmidt","de":"Zweiundsiebzig Quadratmeter, drei Zimmer."},{"who":"Ravi","de":"Ist die Küche möbliert?"},{"who":"Frau Schmidt","de":"Ja, die Küche ist neu, mit Herd und Kühlschrank."},{"who":"Ravi","de":"Und wie hoch ist die Miete?"},{"who":"Frau Schmidt","de":"Neunhundertachtzig Euro warm."},{"who":"Ravi","de":"Kann ich die Wohnung sehen?"},{"who":"Frau Schmidt","de":"Natürlich. Am Donnerstag um fünf?"},{"who":"Ravi","de":"Ja, das passt. Vielen Dank!"}],"dq":[{"q":"Wie viele Zimmer hat die Wohnung?","a":"Drei."},{"q":"Wie hoch ist die Miete?","a":"980 Euro warm."},{"q":"Wann sieht Ravi die Wohnung?","a":"Am Donnerstag um fünf."}],"en":{"title":"Nouns: gender, articles and plural","theme":"Flat and furniture","expl":["Every German noun has a **gender**: **der** (masculine), **die** (feminine) or **das** (neuter). It is often not logical (__das Mädchen__ = the girl), so **always learn a noun with its article and plural**. All nouns are written with a **capital letter**.","Useful tips: words ending in -ung, -heit, -keit, -ion, -schaft and most words ending in -e are **die**. Words ending in -chen, -lein, -ment, -um are **das**. Days, months, seasons, people ending in -er and words ending in -ismus are **der**.","In the plural the article is always **die**: __der Tisch → die Tische, das Bett → die Betten__. Plural endings vary (-e, -en, -n, -er, -s or none, sometimes with an umlaut), so learn them with the word.","**ein / eine** = a, an: __ein Tisch (der), eine Lampe (die), ein Sofa (das)__. There is no plural of ein: __Tische__."],"use":""},"check":[{"re":"\\\\b(der|die|das|ein|eine)\\\\s+[A-ZÄÖÜ]","label":"nouns with der / die / das or ein / eine"}]},{"n":6,"pos":6,"level":"A1","title":"Der Akkusativ","theme":"Einkaufen","scene":"shop","rec":[1,2,3,5],"expl":["Der **Akkusativ** ist das **direkte Objekt**: Wen oder was? __Ich kaufe **den** Apfel.__","**Nur maskulin ändert sich**: der → **den**, ein → **einen**. Feminin, neutral und Plural bleiben gleich.","Verben mit Akkusativ: haben, kaufen, brauchen, möchten, nehmen, essen, trinken, sehen, suchen, finden, besuchen, es gibt.","**es gibt + Akkusativ**: __Es gibt **einen** Supermarkt hier.__"],"use":"Einkaufen, bestellen, sagen, was man braucht oder hat.","table":[["Fall","maskulin","feminin","neutral","Plural"],["Nominativ","der / ein Käse","die / eine Milch","das / ein Brot","die / – Äpfel"],["Akkusativ","**den / einen** Käse","die / eine Milch","das / ein Brot","die / – Äpfel"],["Pronomen Nom.","er","sie","es","sie"],["Pronomen Akk.","**ihn**","sie","es","sie"]],"examples":[{"de":"Ich brauche einen Einkaufswagen.","en":"I need a shopping trolley."},{"de":"Ravi kauft den Reis.","en":"Ravi buys the rice."},{"de":"Möchtest du eine Tüte?","en":"Would you like a bag?"},{"de":"Wir nehmen das Brot.","en":"We\'ll take the bread."},{"de":"Es gibt hier einen Markt.","en":"There is a market here."},{"de":"Ich suche den Joghurt. – Er ist dort.","en":"I\'m looking for the yoghurt. – It\'s there."},{"de":"Den Käse finde ich lecker.","en":"I find the cheese tasty."},{"de":"Kaufst du den Tee? – Ja, ich kaufe ihn.","en":"Are you buying the tea? – Yes, I\'m buying it."},{"de":"Sie trinkt einen Kaffee.","en":"She drinks a coffee."},{"de":"Wir haben keine Zeit, aber einen Plan.","en":"We have no time but a plan."},{"de":"Ich brauche ein Kilo Kartoffeln.","en":"I need a kilo of potatoes."},{"de":"Wir kaufen einen Saft und zwei Flaschen Wasser.","en":"We are buying a juice and two bottles of water."},{"de":"Hast du einen Stift? Ich schreibe eine Einkaufsliste.","en":"Do you have a pen? I\'m writing a shopping list."},{"de":"Er sucht den Käse.","en":"He is looking for the cheese."},{"de":"Möchten Sie eine Tüte?","en":"Would you like a bag?"},{"de":"Ich nehme den Joghurt und die Butter.","en":"I\'ll take the yoghurt and the butter."},{"de":"Sie bezahlt an der Kasse.","en":"She pays at the till."},{"de":"Die Tomaten kosten 2,50 Euro das Kilo.","en":"The tomatoes cost 2.50 euros a kilo."},{"de":"Das Brot ist heute im Angebot.","en":"The bread is on special offer today."},{"de":"Kennst du den Supermarkt hier?","en":"Do you know the supermarket here?"}],"vocab":[{"de":"der Supermarkt, ¨e","en":"supermarket"},{"de":"der Apfel, ¨","en":"apple"},{"de":"der Reis","en":"rice"},{"de":"der Käse","en":"cheese"},{"de":"die Milch","en":"milk"},{"de":"das Brot, -e","en":"bread"},{"de":"das Ei, -er","en":"egg"},{"de":"die Tomate, -n","en":"tomato"},{"de":"die Tüte, -n","en":"bag"},{"de":"die Kasse, -n","en":"checkout"},{"de":"kosten","en":"to cost"},{"de":"das Angebot, -e","en":"special offer"},{"de":"die Banane, -n","en":"banana"},{"de":"die Kartoffel, -n","en":"potato"},{"de":"die Zwiebel, -n","en":"onion"},{"de":"die Butter","en":"butter"},{"de":"der Joghurt, -s","en":"yoghurt"},{"de":"das Wasser","en":"water"},{"de":"der Saft, ¨e","en":"juice"},{"de":"die Flasche, -n","en":"bottle"},{"de":"das Kilo, -s","en":"kilo"},{"de":"das Gramm","en":"gram"},{"de":"das Stück, -e","en":"piece"},{"de":"der Euro, -s","en":"euro"},{"de":"kaufen","en":"to buy"},{"de":"brauchen","en":"to need"},{"de":"suchen","en":"to look for"},{"de":"bezahlen","en":"to pay"},{"de":"billig / teuer","en":"cheap / expensive"},{"de":"die Einkaufsliste, -n","en":"shopping list"}],"reading":"Am Samstag geht Ravi in den Supermarkt. Er braucht einen Liter Milch, ein Brot, einen Käse und Tomaten. Er sucht auch den Basmatireis, aber er findet ihn nicht. Er fragt eine Verkäuferin. Sie sagt: „Den Reis haben wir dort hinten.“ An der Kasse sieht Ravi ein Angebot: Äpfel für 1,99 €. Er nimmt ein Kilo. Die Kassiererin fragt: „Brauchen Sie eine Tüte?“ – „Nein danke, ich habe einen Rucksack.“","tasks":[{"q":"Ich brauche ___ Apfel. (ein)","a":"einen"},{"q":"Ravi kauft ___ Milch. (die)","a":"die"},{"q":"Wir nehmen ___ Käse. (der)","a":"den"},{"q":"Hast du ___ Tüte? (ein)","a":"eine"},{"q":"Es gibt hier ___ Bäcker. (ein)","a":"einen"},{"q":"Siehst du den Mann? – Ja, ich sehe ___.","a":"ihn"},{"q":"Wo ist die Butter? Ich finde ___ nicht.","a":"sie"},{"q":"[Mix] ___ Kinder brauchen neue Stühle. (Artikel Plural)","a":"Die"},{"q":"[Mix] Ordne: kauft / am Samstag / Ravi / einen Käse","a":"Am Samstag kauft Ravi einen Käse."},{"q":"[Mix] Frage: Ich suche den Reis. (Was …?)","a":"Was suchst du?"},{"q":"Ich kaufe ___ Apfel. (ein)","a":"einen"},{"q":"Sie braucht ___ Tüte. (ein)","a":"eine"},{"q":"Wir nehmen ___ Brot. (das)","a":"das"},{"q":"Er sucht ___ Supermarkt. (der)","a":"den"},{"q":"Hast du ___ Stift? (ein)","a":"einen"},{"q":"Ich möchte ___ Kaffee. (ein)","a":"einen"},{"q":"Kennst du ___ Verkäufer? (der)","a":"den"},{"q":"Akkusativ? „Der Käse ist teuer.“ – Ich kaufe ___ Käse.","a":"den"},{"q":"Fehler? „Ich brauche ein Salat.“","a":"Ich brauche einen Salat."},{"q":"Fehler? „Er kauft der Saft.“","a":"Er kauft den Saft."}],"exam":[{"q":"Was braucht Ravi?","a":"Milch, Brot, Käse, Tomaten (und Reis)."},{"q":"Wo ist der Reis?","a":"Dort hinten."},{"q":"Warum braucht Ravi keine Tüte?","a":"Er hat einen Rucksack."},{"q":"Nominativ oder Akkusativ? „Der Mann kauft den Tee.“ – der Mann = ?","a":"Nominativ"},{"q":"Ergänze: Ich möchte ___ Kaffee und ___ Wasser. (ein)","a":"einen / ein"},{"q":"Ersetze: Ich kaufe __den Apfel__.","a":"Ich kaufe ihn."},{"q":"Ergänze: Gibt es hier ___ Bank? (ein)","a":"eine"},{"q":"Sie planen eine Party. Was kaufen Sie? Machen Sie eine Liste mit Artikeln.","a":"","m":"Ich kaufe einen Kuchen, eine Pizza, ein Brot, einen Käse und zwei Flaschen Saft. Ich brauche auch Gläser und Teller."},{"q":"Was kaufen Sie jede Woche? Was kaufen Sie nie?","a":"","m":"Jede Woche kaufe ich Milch, Brot, Eier und einen Salat. Ich kaufe nie Fleisch."},{"q":"Rollenspiel: Sie suchen im Supermarkt etwas und fragen einen Verkäufer.","a":"","m":"Entschuldigung, ich suche den Reis. – Der Reis ist dort hinten. – Und haben Sie auch einen Mangosaft? – Ja, im Regal links. – Danke!"}],"speak":["Was siehst du im Supermarkt? __Ich sehe einen Mann, einen Wagen …__","Was kauft der Mann? Was kostet das Angebot?","Was brauchst du heute? Nenne 6 Sachen mit ein/eine/einen.","Wo kaufst du lieber ein: Markt oder Supermarkt? Warum?"],"reading2":{"title":"Einkaufen auf dem Markt","text":"Jeden Samstag geht Anna Weber auf den Markt. Sie hat immer eine Einkaufsliste. Heute braucht sie ein Kilo Äpfel, einen Salat, sechs Eier und einen Käse. Zuerst kauft sie das Obst. Der Verkäufer sagt: „Die Äpfel sind heute im Angebot, nur 1,99 Euro das Kilo.“ Anna nimmt zwei Kilo. Dann sucht sie den Käse. Am Käsestand gibt es viele Sorten. Anna probiert einen Bergkäse. Er ist sehr gut, aber teuer. Sie kauft nur 200 Gramm. Die Eier kauft sie bei einem Bauern. Er hat auch frische Milch. Anna braucht keine Milch, aber sie kauft einen Joghurt. Am Ende hat sie eine schwere Tasche. Sie bezahlt fast überall bar. Zu Hause kocht sie eine Suppe."},"dialog":[{"who":"Verkäufer","de":"Guten Morgen! Was darf es sein?"},{"who":"Anna","de":"Guten Morgen. Ich brauche Tomaten. Was kosten die?"},{"who":"Verkäufer","de":"Drei Euro das Kilo. Sie sind ganz frisch."},{"who":"Anna","de":"Gut, dann nehme ich ein Kilo. Haben Sie auch Zwiebeln?"},{"who":"Verkäufer","de":"Ja, natürlich. Wie viele möchten Sie?"},{"who":"Anna","de":"Fünf Stück, bitte."},{"who":"Verkäufer","de":"Sonst noch etwas?"},{"who":"Anna","de":"Nein, danke. Das ist alles. Was macht das?"},{"who":"Verkäufer","de":"Das macht vier Euro zwanzig."},{"who":"Anna","de":"Hier, bitte. Stimmt so."}],"dq":[{"q":"Was kostet ein Kilo Tomaten?","a":"Drei Euro."},{"q":"Wie viele Zwiebeln kauft Anna?","a":"Fünf."},{"q":"Wie viel bezahlt Anna?","a":"Vier Euro zwanzig."}],"en":{"title":"The accusative case","theme":"Shopping","expl":["The **accusative** is the direct object – the person or thing the action is done to. Ask \\"who or what?\\" (Wen oder was?): __Ich kaufe den Apfel.__ = I buy the apple.","Good news: **only the masculine changes**: der → **den**, ein → **einen**, kein → **keinen**. Feminine (die/eine), neuter (das/ein) and plural (die) stay the same.","Verbs that take an accusative object: haben, kaufen, brauchen, möchten, nehmen, essen, trinken, sehen, suchen, finden, besuchen and **es gibt** (there is / there are): __Es gibt einen Supermarkt hier.__","Pronouns change too: ich → mich, du → dich, er → ihn, sie → sie, es → es, wir → uns, ihr → euch, sie/Sie → sie/Sie."],"use":""},"check":[{"re":"\\\\b(einen|den|keinen|meinen)\\\\b","label":"accusative masculine: einen / den"},{"re":"\\\\b(kaufe|brauche|nehme|möchte|suche|esse|trinke|gibt)\\\\b","label":"an accusative verb (kaufen, brauchen …)"}]},{"n":7,"pos":7,"level":"A1","title":"Negation: nicht und kein","theme":"Essen und Trinken","scene":"kitchen","rec":[2,3,5,6],"expl":["**kein** verneint ein **Nomen ohne Artikel oder mit ein**: __Ich habe **keine** Zeit. Das ist **kein** Tee.__ Kein hat die Endungen von ein (+ Plural: keine).","**nicht** verneint **alles andere**: Verben, Adjektive, Nomen mit der/mein, Orte, Zeiten.","Position von nicht: meistens **am Ende**, aber **vor** Adjektiv, Ort, Präposition und zweitem Verbteil: __Ich komme **nicht** aus Berlin. Das ist **nicht** gut.__","**sondern** nach nicht/kein: __Ich trinke keinen Kaffee, **sondern** Tee.__"],"use":"Etwas ablehnen, Vorlieben sagen, im Restaurant bestellen.","table":[["Positiv","Negativ","Regel"],["Ich habe einen Hund.","Ich habe **keinen** Hund.","ein → kein (Akk. m. keinen)"],["Ich trinke Milch.","Ich trinke **keine** Milch.","ohne Artikel → kein"],["Ich esse das Fleisch.","Ich esse das Fleisch **nicht**.","der/die/das → nicht"],["Das Essen ist scharf.","Das Essen ist **nicht** scharf.","vor Adjektiv"],["Er wohnt in Berlin.","Er wohnt **nicht** in Berlin.","vor Ort"],["Ich koche heute.","Ich koche heute **nicht**.","am Ende"]],"examples":[{"de":"Ich esse kein Fleisch.","en":"I don\'t eat meat."},{"de":"Das ist nicht mein Teller.","en":"That\'s not my plate."},{"de":"Wir haben keine Eier mehr.","en":"We have no more eggs."},{"de":"Die Suppe ist nicht heiß.","en":"The soup isn\'t hot."},{"de":"Ravi trinkt keinen Alkohol.","en":"Ravi doesn\'t drink alcohol."},{"de":"Anna kocht heute nicht.","en":"Anna isn\'t cooking today."},{"de":"Das ist kein Curry, sondern ein Dal.","en":"That\'s not a curry but a dal."},{"de":"Ich mag Fisch nicht.","en":"I don\'t like fish."},{"de":"Er isst nicht gern süß.","en":"He doesn\'t like eating sweet things."},{"de":"Haben Sie keinen Hunger? – Doch.","en":"Aren\'t you hungry? – Yes, I am."},{"de":"Ich esse kein Fleisch.","en":"I don\'t eat meat."},{"de":"Er trinkt keinen Alkohol.","en":"He doesn\'t drink alcohol."},{"de":"Die Suppe ist nicht scharf.","en":"The soup is not spicy."},{"de":"Wir haben keine Milch mehr.","en":"We have no more milk."},{"de":"Das schmeckt nicht gut.","en":"That doesn\'t taste good."},{"de":"Ich trinke den Kaffee ohne Zucker.","en":"I drink the coffee without sugar."},{"de":"Sie isst heute nicht im Restaurant.","en":"She is not eating at the restaurant today."},{"de":"Möchtest du noch etwas? – Nein, danke, ich bin satt.","en":"Would you like anything else? – No thanks, I\'m full."},{"de":"Hier ist kein Messer.","en":"There is no knife here."},{"de":"Die Rechnung, bitte!","en":"The bill, please!"}],"vocab":[{"de":"das Fleisch","en":"meat"},{"de":"der Fisch, -e","en":"fish"},{"de":"das Gemüse","en":"vegetables"},{"de":"das Obst","en":"fruit"},{"de":"die Suppe, -n","en":"soup"},{"de":"der Teller, -","en":"plate"},{"de":"scharf","en":"spicy"},{"de":"süß / salzig","en":"sweet / salty"},{"de":"mögen (mag)","en":"to like"},{"de":"vegetarisch","en":"vegetarian"},{"de":"der Hunger / der Durst","en":"hunger / thirst"},{"de":"schmecken","en":"to taste (good)"},{"de":"das Frühstück","en":"breakfast"},{"de":"das Brötchen, -","en":"bread roll"},{"de":"die Marmelade, -n","en":"jam"},{"de":"der Tee, -s","en":"tea"},{"de":"das Bier, -e","en":"beer"},{"de":"der Wein, -e","en":"wine"},{"de":"das Restaurant, -s","en":"restaurant"},{"de":"die Speisekarte, -n","en":"menu"},{"de":"bestellen","en":"to order"},{"de":"die Rechnung, -en","en":"bill"},{"de":"lecker","en":"tasty"},{"de":"satt","en":"full (after eating)"},{"de":"das Messer, -","en":"knife"},{"de":"die Gabel, -n","en":"fork"},{"de":"der Löffel, -","en":"spoon"},{"de":"das Glas, ¨er","en":"glass"},{"de":"der Zucker","en":"sugar"},{"de":"das Salz","en":"salt"}],"reading":"Anna und Max essen bei Ravi. Ravi kocht Dal und Reis. Anna fragt: „Ist das Essen scharf?“ Ravi sagt: „Nein, es ist nicht scharf. Heute koche ich nicht so scharf.“ Max isst kein Gemüse, aber er mag den Reis. Anna trinkt keinen Wein, sondern Wasser. „Hast du keinen Nachtisch?“, fragt Max. „Doch! Es gibt Gulab Jamun. Aber sie sind sehr süß.“ Max sagt: „Das ist kein Problem!“","tasks":[{"q":"Ich habe ___ Hunger.","a":"keinen"},{"q":"Das ist ___ Suppe, sondern Soße.","a":"keine"},{"q":"Das Essen schmeckt ___.","a":"nicht"},{"q":"Ravi isst ___ Fleisch.","a":"kein"},{"q":"Ich mag den Fisch ___.","a":"nicht"},{"q":"Max ist ___ müde.","a":"nicht"},{"q":"Wir haben ___ Eier.","a":"keine"},{"q":"[Mix] Verneine: Ich kaufe einen Apfel.","a":"Ich kaufe keinen Apfel."},{"q":"[Mix] Verneine: Heute kocht Anna.","a":"Heute kocht Anna nicht."},{"q":"[Mix] Antworte positiv: Isst du kein Gemüse?","a":"Doch, ich esse Gemüse."},{"q":"Verneine mit kein: Ich habe einen Löffel.","a":"Ich habe keinen Löffel."},{"q":"Verneine mit kein: Das ist eine Gabel.","a":"Das ist keine Gabel."},{"q":"Verneine mit kein: Wir trinken Wein.","a":"Wir trinken keinen Wein."},{"q":"Verneine mit nicht: Die Suppe ist warm.","a":"Die Suppe ist nicht warm."},{"q":"Verneine mit nicht: Er kommt heute.","a":"Er kommt heute nicht."},{"q":"Verneine mit nicht: Ich mag den Käse.","a":"Ich mag den Käse nicht."},{"q":"Verneine mit kein: Sie isst Fleisch.","a":"Sie isst kein Fleisch."},{"q":"nicht oder kein? Das ist ___ Restaurant, das ist ein Café.","a":"kein"},{"q":"nicht oder kein? Das Restaurant ist ___ teuer.","a":"nicht"},{"q":"Fehler? „Ich habe nicht Zeit.“","a":"Ich habe keine Zeit."}],"exam":[{"q":"Was kocht Ravi?","a":"Dal und Reis."},{"q":"Was trinkt Anna?","a":"Wasser."},{"q":"Was isst Max nicht?","a":"Gemüse."},{"q":"Verneine: Das ist ein Problem.","a":"Das ist kein Problem."},{"q":"Verneine: Ich wohne in München.","a":"Ich wohne nicht in München."},{"q":"Verneine: Er hat Kinder.","a":"Er hat keine Kinder."},{"q":"Ergänze: Ich trinke keinen Kaffee, ___ Tee.","a":"sondern"},{"q":"Was essen Sie gern, was nicht? Nennen Sie 6 Beispiele.","a":"","m":"Ich esse gern Reis, Gemüse und Obst. Ich esse gern Pizza. Ich esse kein Fleisch. Ich trinke keinen Alkohol. Ich mag keinen Fisch. Scharfes Essen finde ich nicht schlecht."},{"q":"Sie sind im Restaurant. Sagen Sie, was Sie nicht essen, und bestellen Sie.","a":"","m":"Entschuldigung, ich esse kein Fleisch. Ich nehme die Gemüsesuppe und einen Salat, bitte. Und ein Wasser, aber nicht zu kalt."},{"q":"Was ist typisch für das Essen in Ihrem Land?","a":"","m":"In Indien isst man oft Reis und Curry. Das Essen ist scharf. Viele Menschen essen kein Fleisch."}],"speak":["Was machen die Personen in der Küche?","Was ist im Kühlschrank? Was ist nicht da? __Es gibt keine …__","Du kochst für Gäste. Frag: __Essen Sie kein Fleisch? Mögen Sie …?__","Was isst du nie? Warum nicht?"],"reading2":{"title":"Ein Abend im Restaurant","text":"Am Freitag gehen Ravi, Leila und Jonas in ein italienisches Restaurant. Der Kellner bringt die Speisekarte. Ravi ist Vegetarier. Er isst kein Fleisch und keinen Fisch. Er bestellt eine Pizza mit Gemüse. Leila isst gern Fisch, aber heute nimmt sie keinen. Sie bestellt Spaghetti mit Tomatensoße. Jonas hat großen Hunger. Er nimmt ein Schnitzel mit Pommes. Zum Trinken bestellen sie Wasser und Saft. Jonas trinkt ein Bier. Ravi trinkt nie Alkohol. Das Essen ist sehr lecker. Nur Leilas Soße ist nicht warm. Der Kellner ist sehr nett und bringt eine neue Soße. Am Ende sind alle satt. Zum Nachtisch bestellen sie nichts. Sie bezahlen zusammen: 58 Euro."},"dialog":[{"who":"Kellner","de":"Guten Abend! Möchten Sie schon bestellen?"},{"who":"Leila","de":"Ja. Ich nehme die Spaghetti mit Tomatensoße."},{"who":"Kellner","de":"Und was möchten Sie trinken?"},{"who":"Leila","de":"Ein Wasser, bitte. Ohne Kohlensäure."},{"who":"Ravi","de":"Ist die Gemüsesuppe vegetarisch?"},{"who":"Kellner","de":"Nein, leider nicht. Sie ist mit Fleischbrühe."},{"who":"Ravi","de":"Dann nehme ich keine Suppe. Ich nehme die Pizza mit Gemüse."},{"who":"Kellner","de":"Sehr gern. Möchten Sie auch einen Salat?"},{"who":"Ravi","de":"Nein, danke. Keinen Salat."}],"dq":[{"q":"Was trinkt Leila?","a":"Wasser ohne Kohlensäure."},{"q":"Warum nimmt Ravi die Suppe nicht?","a":"Sie ist mit Fleischbrühe / nicht vegetarisch."},{"q":"Was bestellt Ravi?","a":"Die Pizza mit Gemüse."}],"en":{"title":"Negation: nicht and kein","theme":"Food and drink","expl":["Use **kein** to negate a noun that has **ein** or no article: __Ich habe keine Zeit.__ = I have no time. __Das ist kein Tee.__ = That isn\'t tea. kein has the same endings as ein (plural: keine).","Use **nicht** for everything else: verbs, adjectives, nouns with der/die/das or mein, places and times: __Ich komme nicht. Das ist nicht gut. Das ist nicht mein Kaffee.__","Position of **nicht**: usually at the end, but **before** an adjective, a place, a preposition and the second part of the verb: __Ich komme nicht aus Berlin. Ich kann heute nicht kommen.__"],"use":""},"check":[{"re":"\\\\b(nicht|kein|keine|keinen)\\\\b","label":"nicht or kein"}]},{"n":8,"pos":8,"level":"A1","title":"Possessivartikel (Nominativ und Akkusativ)","theme":"Familie und Freunde","scene":"family","rec":[1,5,6,7],"expl":["Possessivartikel zeigen, **wem** etwas gehört: mein, dein, sein, ihr, unser, euer, ihr/Ihr.","Sie haben **dieselben Endungen wie ein/kein**: mein Bruder, mein**e** Schwester, mein Kind, mein**e** Kinder. Akkusativ maskulin: mein**en** Bruder.","**sein** = von ihm (er/es), **ihr** = von ihr (sie) oder von ihnen (Plural). **Ihr** (groß) = formell.","**euer** verliert das e mit Endung: eu**re** Mutter."],"use":"Über Familie und Besitz sprechen: __Das ist meine Mutter. Ich besuche meinen Onkel.__","table":[["Person","m. Nom.","m. Akk.","f. Nom./Akk.","n. Nom./Akk.","Plural"],["ich","mein","mein**en**","mein**e**","mein","mein**e**"],["du","dein","dein**en**","dein**e**","dein","dein**e**"],["er / es","sein","sein**en**","sein**e**","sein","sein**e**"],["sie","ihr","ihr**en**","ihr**e**","ihr","ihr**e**"],["wir","unser","unser**en**","unser**e**","unser","unser**e**"],["ihr","euer","eur**en**","eur**e**","euer","eur**e**"],["sie / Sie","ihr / Ihr","ihr**en** / Ihr**en**","ihr**e** / Ihr**e**","ihr / Ihr","ihr**e** / Ihr**e**"]],"examples":[{"de":"Das ist meine Schwester Priya.","en":"This is my sister Priya."},{"de":"Mein Vater ist Lehrer.","en":"My father is a teacher."},{"de":"Ich vermisse meinen Bruder.","en":"I miss my brother."},{"de":"Anna liebt ihren Sohn.","en":"Anna loves her son."},{"de":"Max sucht seine Schuhe.","en":"Max is looking for his shoes."},{"de":"Wo ist dein Handy?","en":"Where\'s your phone?"},{"de":"Unsere Oma wohnt in Pune.","en":"Our grandma lives in Pune."},{"de":"Besucht ihr eure Eltern?","en":"Are you visiting your parents?"},{"de":"Ist das Ihr Koffer?","en":"Is that your suitcase? (formal)"},{"de":"Die Kinder spielen mit ihrem Hund.","en":"The children play with their dog."},{"de":"Das ist meine Oma. Sie ist 82.","en":"This is my grandma. She is 82."},{"de":"Ist das dein Bruder?","en":"Is that your brother?"},{"de":"Sein Vater wohnt in Hamburg.","en":"His father lives in Hamburg."},{"de":"Ihre Tochter heißt Sara.","en":"Her daughter is called Sara."},{"de":"Unsere Eltern feiern heute ihren Hochzeitstag.","en":"Our parents are celebrating their wedding anniversary today."},{"de":"Wo ist euer Auto?","en":"Where is your (pl.) car?"},{"de":"Ich besuche meinen Onkel in Köln.","en":"I\'m visiting my uncle in Cologne."},{"de":"Er liebt seine Frau.","en":"He loves his wife."},{"de":"Haben Sie Ihren Ausweis?","en":"Do you have your ID?"},{"de":"Ich vermisse meine Familie sehr.","en":"I miss my family a lot."}],"vocab":[{"de":"die Eltern (Pl.)","en":"parents"},{"de":"die Großeltern (Pl.)","en":"grandparents"},{"de":"der Onkel, -","en":"uncle"},{"de":"die Tante, -n","en":"aunt"},{"de":"der Cousin / die Cousine","en":"cousin"},{"de":"der Sohn, ¨e","en":"son"},{"de":"die Tochter, ¨","en":"daughter"},{"de":"der Freund, -e / die Freundin, -nen","en":"friend / boyfriend, girlfriend"},{"de":"vermissen","en":"to miss"},{"de":"besuchen","en":"to visit"},{"de":"lieben","en":"to love"},{"de":"das Foto, -s","en":"photo"},{"de":"mein / meine","en":"my"},{"de":"dein / deine","en":"your (informal)"},{"de":"sein / seine","en":"his, its"},{"de":"ihr / ihre","en":"her, their"},{"de":"unser / unsere","en":"our"},{"de":"euer / eure","en":"your (pl.)"},{"de":"Ihr / Ihre (formell)","en":"your (formal)"},{"de":"der Opa, -s","en":"grandpa"},{"de":"die Oma, -s","en":"grandma"},{"de":"der Enkel, -","en":"grandson"},{"de":"die Enkelin, -nen","en":"granddaughter"},{"de":"die Geschwister (Pl.)","en":"siblings"},{"de":"der Neffe, -n","en":"nephew"},{"de":"die Nichte, -n","en":"niece"},{"de":"die Hochzeit, -en","en":"wedding"},{"de":"der Geburtstag, -e","en":"birthday"},{"de":"feiern","en":"to celebrate"},{"de":"ähnlich","en":"similar"}],"reading":"Ravi zeigt Anna ein Foto. „Das ist meine Familie. Das ist mein Vater, und das ist meine Mutter. Das hier ist mein Onkel. Seine Frau ist auch auf dem Foto.“ Anna fragt: „Und wer ist das Mädchen?“ – „Das ist meine Schwester Priya. Ihr Hund heißt Moti.“ Anna sagt: „Eure Familie ist groß! Vermisst du deine Eltern?“ – „Ja, sehr. Ich besuche meine Eltern im Dezember.“","tasks":[{"q":"Das ist ___ Mutter. (ich)","a":"meine"},{"q":"Wie heißt ___ Bruder? (du)","a":"dein"},{"q":"Anna liebt ___ Sohn. (sie)","a":"ihren"},{"q":"Max sucht ___ Ball. (er)","a":"seinen"},{"q":"Wir besuchen ___ Großeltern. (wir)","a":"unsere"},{"q":"Wo ist ___ Auto? (ihr)","a":"euer"},{"q":"Ist das ___ Tasche, Frau Weber? (Sie)","a":"Ihre"},{"q":"[Mix] Ich habe ___ Auto. (kein)","a":"kein"},{"q":"[Mix] Verneine: Das ist mein Stift.","a":"Das ist nicht mein Stift."},{"q":"[Mix] Frage: ___ ist das? – Das ist meine Tante.","a":"Wer"},{"q":"Das ist Ravi. Das ist ___ Schwester. (sein)","a":"seine"},{"q":"Das ist Anna. Das ist ___ Sohn. (ihr)","a":"ihr"},{"q":"Ich suche ___ Schlüssel. (mein)","a":"meinen"},{"q":"Wir besuchen ___ Großeltern. (unser)","a":"unsere"},{"q":"Hast du ___ Handy? (dein)","a":"dein"},{"q":"Herr Müller, ist das ___ Tasche? (Ihr)","a":"Ihre"},{"q":"Kinder, wo ist ___ Lehrerin? (euer)","a":"eure"},{"q":"Er liebt ___ Frau. (sein)","a":"seine"},{"q":"Sie ruft ___ Vater an. (ihr)","a":"ihren"},{"q":"Fehler? „Ich besuche mein Onkel.“","a":"Ich besuche meinen Onkel."}],"exam":[{"q":"Wen zeigt Ravi auf dem Foto?","a":"Seine Familie (Vater, Mutter, Onkel, Tante, Schwester)."},{"q":"Wie heißt Priyas Hund?","a":"Moti."},{"q":"Wann besucht Ravi seine Eltern?","a":"Im Dezember."},{"q":"Ergänze: Priya und ___ Freund (sie) gehen ins Kino.","a":"ihr"},{"q":"Ergänze: Ravi ruft ___ Mutter an. (er)","a":"seine"},{"q":"Ergänze: Kinder, wo sind ___ Jacken? (ihr)","a":"eure"},{"q":"sein oder ihr? Max und ___ Schwester.","a":"seine"},{"q":"Zeigen Sie ein Familienfoto (oder erfinden Sie eins) und beschreiben Sie es.","a":"","m":"Das ist meine Familie. Links ist mein Vater, rechts ist meine Mutter. In der Mitte sitzt meine Schwester. Ihr Mann steht hinter ihr. Unser Hund heißt Bobby."},{"q":"Wer ist Ihr bester Freund / Ihre beste Freundin? Erzählen Sie.","a":"","m":"Mein bester Freund heißt Jonas. Er wohnt in Hamburg. Seine Frau heißt Mia. Wir telefonieren jede Woche. Sein Hobby ist Fußball."},{"q":"Wen vermissen Sie? Warum?","a":"","m":"Ich vermisse meine Mutter und meinen Vater. Sie wohnen in Indien. Ich vermisse auch ihr Essen!"}],"speak":["Stell dir vor, das ist deine Familie: __Das ist mein …, das ist meine …__","Was isst die Familie? Wer sitzt neben wem?","Frag den Partner: __Wie heißt dein …? Was macht deine …?__","Wie groß ist deine Familie? Wo wohnen deine Verwandten?"],"reading2":{"title":"Ein Fotoalbum","text":"Ravi zeigt Mia ein Foto von seiner Familie in Mumbai. „Das ist mein Vater, Arjun. Er ist Lehrer. Und das ist meine Mutter, Sunita. Sie ist Ärztin.“ Mia fragt: „Und wer ist das Mädchen?“ – „Das ist meine Schwester Priya. Ihr Mann heißt Vikram. Sie haben einen Sohn. Er ist mein Neffe und heißt Arun.“ Auf dem Foto sind auch Ravis Großeltern. Sein Opa ist 85, seine Oma ist 80. „Deine Familie ist groß!“, sagt Mia. „Ja, und das ist nur ein Teil. Meine Tante und mein Onkel wohnen in Delhi.“ Mia zeigt dann ihr Foto. „Das ist unser Haus in Freiburg. Hier sind meine Eltern und unser Hund Bello.“ Ravi lacht: „Euer Hund ist auch auf dem Familienfoto?“ – „Natürlich! Er ist ein Familienmitglied.“"},"dialog":[{"who":"Anna","de":"Ravi, wer ist das auf deinem Handy?"},{"who":"Ravi","de":"Das ist meine Schwester Priya. Sie hat heute Geburtstag."},{"who":"Anna","de":"Oh, wie schön! Wie alt ist sie?"},{"who":"Ravi","de":"Vierundzwanzig. Ich rufe sie gleich an."},{"who":"Anna","de":"Wohnt deine Schwester auch in Berlin?"},{"who":"Ravi","de":"Nein, sie wohnt in Mumbai, mit ihrem Mann."},{"who":"Anna","de":"Vermisst du deine Familie?"},{"who":"Ravi","de":"Ja, sehr. Aber im Dezember besuche ich meine Eltern."}],"dq":[{"q":"Wer hat heute Geburtstag?","a":"Ravis Schwester Priya."},{"q":"Wo wohnt Priya?","a":"In Mumbai."},{"q":"Wann besucht Ravi seine Eltern?","a":"Im Dezember."}],"en":{"title":"Possessive articles (my, your, his …)","theme":"Family and friends","expl":["Possessive articles show who something belongs to: **mein** (my), **dein** (your), **sein** (his/its), **ihr** (her/their), **unser** (our), **euer** (your, plural), **Ihr** (your, formal).","They take the same endings as ein/kein: __mein Bruder, meine Schwester, mein Kind, meine Kinder__. In the accusative only the masculine changes: __Ich besuche meinen Bruder.__","**sein** = belonging to him (er) or it (es); **ihr** = belonging to her (sie) or to them. **Ihr** with a capital I = your (formal). **euer** loses an e when it gets an ending: __eure Wohnung__."],"use":""},"check":[{"re":"\\\\b(mein|meine|meinen|dein|sein|seine|ihr|ihre|unser|unsere)\\\\b","label":"possessive articles (mein, seine, ihr …)"}]},{"n":9,"pos":9,"level":"A1","title":"Zahlen, Uhrzeit und Zeitangaben (am, um, im)","theme":"Termine","scene":"office","rec":[2,3,4,6],"expl":["**Uhrzeit offiziell:** 14:30 = vierzehn Uhr dreißig. **Inoffiziell:** halb drei (= 2:30!), Viertel nach zwei (2:15), Viertel vor drei (2:45), fünf nach zwei.","**Achtung:** __halb drei__ = 2:30 (eine halbe Stunde **vor** drei).","**Präpositionen:** **um** + Uhrzeit, **am** + Tag/Datum/Tageszeit, **im** + Monat/Jahreszeit, **von … bis**, Jahr ohne Präposition (__2026__ oder __im Jahr 2026__).","**Datum:** am ersten (1.) Mai, am dritten (3.) Juni, am zwanzigsten (20.)."],"use":"Termine machen, Öffnungszeiten, Verabredungen, Arzttermine.","table":[["Frage","Präposition","Beispiel"],["Um wie viel Uhr?","um","um 8 Uhr, um halb neun"],["Wann? (Tag)","am","am Montag, am Wochenende, am Abend"],["Wann? (Datum)","am","am 3. Oktober (am dritten Oktober)"],["Wann? (Monat/Jahreszeit)","im","im Mai, im Sommer"],["Wie lange?","von … bis","von 9 bis 17 Uhr"],["Wie spät ist es?","–","Es ist Viertel nach drei (15:15)."]],"examples":[{"de":"Wie spät ist es? – Es ist halb neun.","en":"What time is it? – It\'s half past eight."},{"de":"Der Kurs beginnt um 18 Uhr.","en":"The course starts at 6 pm."},{"de":"Am Montag habe ich einen Termin.","en":"On Monday I have an appointment."},{"de":"Im Winter ist es kalt.","en":"In winter it\'s cold."},{"de":"Mein Geburtstag ist am 12. April.","en":"My birthday is on 12th April."},{"de":"Das Büro ist von 9 bis 17 Uhr geöffnet.","en":"The office is open 9 to 5."},{"de":"Um Viertel vor acht nehme ich den Bus.","en":"At quarter to eight I take the bus."},{"de":"Hast du am Freitagabend Zeit?","en":"Do you have time on Friday evening?"},{"de":"Ravi kommt 2025 nach Deutschland.","en":"Ravi comes to Germany in 2025."},{"de":"Das Meeting dauert eine Stunde.","en":"The meeting lasts one hour."},{"de":"Es ist halb acht.","en":"It\'s half past seven."},{"de":"Der Kurs beginnt um Viertel nach neun.","en":"The course starts at a quarter past nine."},{"de":"Am Montag habe ich einen Arzttermin.","en":"On Monday I have a doctor\'s appointment."},{"de":"Im Sommer fahren wir nach Italien.","en":"In summer we\'re going to Italy."},{"de":"Die Bank ist von neun bis sechzehn Uhr geöffnet.","en":"The bank is open from nine to four."},{"de":"Der Film dauert zwei Stunden.","en":"The film lasts two hours."},{"de":"Kann ich den Termin auf Freitag verschieben?","en":"Can I move the appointment to Friday?"},{"de":"Mein Geburtstag ist im Mai.","en":"My birthday is in May."},{"de":"Um Mitternacht schlafe ich schon.","en":"At midnight I\'m already asleep."},{"de":"Bitte sei pünktlich!","en":"Please be on time!"}],"vocab":[{"de":"die Uhr, -en","en":"clock / o\'clock"},{"de":"die Stunde, -n","en":"hour"},{"de":"die Minute, -n","en":"minute"},{"de":"der Termin, -e","en":"appointment"},{"de":"der Tag, -e","en":"day"},{"de":"die Woche, -n","en":"week"},{"de":"der Monat, -e","en":"month"},{"de":"das Jahr, -e","en":"year"},{"de":"geöffnet / geschlossen","en":"open / closed"},{"de":"dauern","en":"to last"},{"de":"beginnen","en":"to begin"},{"de":"pünktlich","en":"on time"},{"de":"der Montag","en":"Monday"},{"de":"der Dienstag","en":"Tuesday"},{"de":"der Mittwoch","en":"Wednesday"},{"de":"der Donnerstag","en":"Thursday"},{"de":"der Freitag","en":"Friday"},{"de":"der Samstag","en":"Saturday"},{"de":"der Sonntag","en":"Sunday"},{"de":"der Januar","en":"January"},{"de":"der Sommer","en":"summer"},{"de":"der Winter","en":"winter"},{"de":"halb","en":"half (past)"},{"de":"Viertel nach / vor","en":"quarter past / to"},{"de":"die Öffnungszeiten (Pl.)","en":"opening hours"},{"de":"der Arzttermin, -e","en":"doctor\'s appointment"},{"de":"vereinbaren","en":"to arrange"},{"de":"absagen","en":"to cancel"},{"de":"früher / später","en":"earlier / later"},{"de":"um Mitternacht","en":"at midnight"}],"reading":"Jonas fragt Ravi: „Hast du am Donnerstag Zeit? Wir haben ein Meeting mit dem Chef.“ – „Um wie viel Uhr?“ – „Um halb zehn. Es dauert bis elf Uhr.“ – „Am Donnerstag um 9:30 Uhr? Das geht. Aber um 12 Uhr habe ich einen Arzttermin.“ – „Kein Problem. Und im Oktober haben wir ein Teamessen, am 17.“ Ravi schreibt den Termin in seinen Kalender. Er ist immer pünktlich.","tasks":[{"q":"Es ist 7:30 Uhr = Es ist ___ acht.","a":"halb"},{"q":"Es ist 4:15 = Es ist Viertel ___ vier.","a":"nach"},{"q":"Es ist 10:45 = Es ist Viertel ___ elf.","a":"vor"},{"q":"Wir treffen uns ___ 8 Uhr.","a":"um"},{"q":"___ Sonntag schlafe ich lange.","a":"Am"},{"q":"___ August fliege ich nach Indien.","a":"Im"},{"q":"Das Geschäft ist ___ 8 ___ 20 Uhr geöffnet.","a":"von / bis"},{"q":"[Mix] Ordne: habe / am Montag / ich / einen Termin","a":"Am Montag habe ich einen Termin."},{"q":"[Mix] Frage zur Antwort: „Um 9 Uhr.“","a":"Um wie viel Uhr / Wann beginnt …?"},{"q":"[Mix] Verneine: Ich habe am Freitag Zeit.","a":"Ich habe am Freitag keine Zeit."},{"q":"am, um oder im? ___ Montag","a":"am"},{"q":"am, um oder im? ___ acht Uhr","a":"um"},{"q":"am, um oder im? ___ Juli","a":"im"},{"q":"am, um oder im? ___ Wochenende","a":"am"},{"q":"am, um oder im? ___ Winter","a":"im"},{"q":"am, um oder im? ___ Abend","a":"am"},{"q":"Uhrzeit informell: 7:30 →","a":"halb acht"},{"q":"Uhrzeit informell: 9:15 →","a":"Viertel nach neun"},{"q":"Uhrzeit informell: 10:45 →","a":"Viertel vor elf"},{"q":"Wie lange? Der Film beginnt um 20 Uhr und endet um 22 Uhr. Er dauert ___ Stunden.","a":"zwei"}],"exam":[{"q":"Wann ist das Meeting?","a":"Am Donnerstag um 9:30 Uhr."},{"q":"Was hat Ravi um 12 Uhr?","a":"Einen Arzttermin."},{"q":"Wann ist das Teamessen?","a":"Am 17. Oktober."},{"q":"Schreibe inoffiziell: 18:30","a":"halb sieben"},{"q":"Schreibe inoffiziell: 9:45","a":"Viertel vor zehn"},{"q":"Ergänze: ___ Frühling fahre ich nach Wien.","a":"Im"},{"q":"Lies laut: 1.487 / 2026 / 23,50 €","a":"tausendvierhundertsiebenundachtzig / zweitausendsechsundzwanzig / dreiundzwanzig Euro fünfzig"},{"q":"Rufen Sie beim Arzt an und machen Sie einen Termin.","a":"","m":"Guten Tag, hier ist Ravi Sharma. Ich möchte einen Termin machen. Haben Sie am Dienstag Zeit? – Ja, um 10 Uhr. – Das passt gut. Vielen Dank, auf Wiederhören!"},{"q":"Wann haben Sie Geburtstag? Wie feiern Sie?","a":"","m":"Ich habe am 12. Mai Geburtstag. Ich feiere mit meiner Familie und meinen Freunden. Wir essen Kuchen."},{"q":"Sagen Sie Ihrem Partner, wann Sie diese Woche Zeit haben.","a":"","m":"Am Montag habe ich keine Zeit. Am Mittwoch habe ich ab 17 Uhr Zeit. Am Freitag um halb acht geht es auch."}],"speak":["Wie spät ist es vielleicht im Büro? Was machen die Leute?","Mach einen Termin mit der Kollegin: __Hast du am … um … Zeit?__","Was machst du um 7 Uhr, um 13 Uhr, um 20 Uhr?","Wann sind die Geschäfte in Indien geöffnet? Und in Deutschland?"],"reading2":{"title":"Leilas Woche","text":"Leila hat eine volle Woche. Am Montag arbeitet sie von sieben bis fünfzehn Uhr. Am Dienstag hat sie frei. Um zehn Uhr hat sie einen Termin beim Bürgeramt. Am Nachmittag geht sie mit ihrer Tochter schwimmen. Am Mittwoch und am Donnerstag arbeitet sie wieder, aber erst ab Mittag. Am Donnerstagabend um halb acht ist ihr Deutschkurs. Der Kurs dauert neunzig Minuten. Am Freitag hat ihr Mann Geburtstag. Sie essen zusammen im Restaurant, der Tisch ist für acht Uhr reserviert. Am Samstag kommen Freunde zum Frühstück, um elf Uhr. Am Sonntag macht die Familie nichts. Das ist der beste Tag! Im Juli hat Leila drei Wochen Urlaub. Dann fliegt die Familie nach Teheran."},"dialog":[{"who":"Praxis","de":"Praxis Dr. Becker, guten Tag."},{"who":"Ravi","de":"Guten Tag, mein Name ist Sharma. Ich brauche einen Termin."},{"who":"Praxis","de":"Was haben Sie denn für Beschwerden?"},{"who":"Ravi","de":"Ich habe seit drei Tagen Halsschmerzen."},{"who":"Praxis","de":"Können Sie morgen um zehn Uhr kommen?"},{"who":"Ravi","de":"Morgen um zehn arbeite ich leider. Geht es auch am Nachmittag?"},{"who":"Praxis","de":"Um Viertel nach vier ist noch ein Termin frei."},{"who":"Ravi","de":"Das passt sehr gut."},{"who":"Praxis","de":"Gut, dann morgen um sechzehn Uhr fünfzehn. Bringen Sie bitte Ihre Versichertenkarte mit."}],"dq":[{"q":"Warum braucht Ravi einen Termin?","a":"Er hat seit drei Tagen Halsschmerzen."},{"q":"Warum kann Ravi nicht um zehn Uhr kommen?","a":"Er arbeitet."},{"q":"Wann ist der Termin?","a":"Morgen um Viertel nach vier (16:15)."}],"en":{"title":"Numbers, the time and time expressions (am, um, im)","theme":"Appointments","expl":["Official time (stations, radio): 14:30 = __vierzehn Uhr dreißig__. Everyday time: __Viertel nach zwei__ (2:15), __Viertel vor drei__ (2:45), __fünf nach zwei__ (2:05).","Careful: **halb drei** = **2:30**, not 3:30! Germans say \\"half (on the way to) three\\".","Prepositions of time: **um** + clock time (__um 8 Uhr__), **am** + day, date or part of the day (__am Montag, am Abend__), **im** + month or season (__im Mai, im Winter__), **von … bis** (from … to). Years have no preposition: __2026 ziehe ich um.__","Numbers 21–99 are said \\"backwards\\": 24 = __vierundzwanzig__ (\\"four-and-twenty\\")."],"use":""},"check":[{"re":"\\\\b(um \\\\d|am (montag|dienstag|mittwoch|donnerstag|freitag|samstag|sonntag|wochenende|abend|morgen|nachmittag)|im (januar|februar|märz|april|mai|juni|juli|august|september|oktober|november|dezember|sommer|winter|frühling|herbst)|uhr|halb)\\\\b","label":"time words: um … Uhr, am Montag, im Mai"}]},{"n":10,"pos":10,"level":"A1","title":"Trennbare Verben","theme":"Tagesablauf","scene":"apartment","rec":[2,3,9],"expl":["Viele Verben haben eine **Vorsilbe**, die sich im Satz **trennt** und **ans Ende** geht: auf|stehen → __Ich **stehe** um 7 Uhr **auf**.__","Trennbar sind z. B.: **ab-, an-, auf-, aus-, ein-, mit-, nach-, vor-, weg-, zu-, zurück-, fern-**. Die Betonung liegt auf der Vorsilbe: __AUFstehen__.","**Nicht trennbar**: **be-, ver-, er-, ent-, ge-, zer-, emp-, miss-** (besuchen, verstehen, erklären).","Im Nebensatz und mit Modalverb bleibt das Verb zusammen (später: __weil ich früh aufstehe__)."],"use":"Tagesablauf beschreiben, telefonieren, einkaufen, Termine.","table":[["Infinitiv","Satz","Frage"],["aufstehen","Ich **stehe** um 7 Uhr **auf**.","Wann **stehst** du **auf**?"],["einkaufen","Ravi **kauft** am Samstag **ein**.","**Kaufst** du heute **ein**?"],["anrufen","Ich **rufe** dich morgen **an**.","**Rufst** du mich **an**?"],["fernsehen","Anna **sieht** abends **fern**.","**Siehst** du oft **fern**?"],["mitkommen","**Kommst** du **mit**?","Wer **kommt mit**?"],["besuchen (untrennbar)","Ich **besuche** meine Oma.","–"]],"examples":[{"de":"Ich stehe um 6:30 Uhr auf.","en":"I get up at 6:30."},{"de":"Der Zug fährt um 8 Uhr ab.","en":"The train leaves at 8."},{"de":"Ruf mich bitte heute Abend an!","en":"Please call me tonight."},{"de":"Wir kaufen im Supermarkt ein.","en":"We shop at the supermarket."},{"de":"Der Film fängt um 20 Uhr an.","en":"The film starts at 8 pm."},{"de":"Ravi räumt am Sonntag die Wohnung auf.","en":"Ravi tidies the flat on Sunday."},{"de":"Kommst du mit ins Kino?","en":"Are you coming to the cinema?"},{"de":"Ich lade dich zum Essen ein.","en":"I\'m inviting you to dinner."},{"de":"Wann kommst du zurück?","en":"When are you coming back?"},{"de":"Ich verstehe die Frage nicht.","en":"I don\'t understand the question."},{"de":"Ich stehe um halb sieben auf.","en":"I get up at half past six."},{"de":"Machst du bitte das Fenster zu?","en":"Will you close the window, please?"},{"de":"Wann kommst du zurück?","en":"When are you coming back?"},{"de":"Er räumt sein Zimmer nie auf.","en":"He never tidies his room."},{"de":"Wir laden unsere Nachbarn zum Essen ein.","en":"We are inviting our neighbours to dinner."},{"de":"Ich hole dich um acht ab.","en":"I\'ll pick you up at eight."},{"de":"Mach bitte das Licht aus!","en":"Please switch off the light!"},{"de":"Kommst du heute Abend mit?","en":"Are you coming along this evening?"},{"de":"Sie bringt einen Kuchen mit.","en":"She is bringing a cake."},{"de":"Der Film fängt um 20 Uhr an.","en":"The film starts at 8 pm."}],"vocab":[{"de":"aufstehen","en":"to get up"},{"de":"einschlafen","en":"to fall asleep"},{"de":"anrufen","en":"to call"},{"de":"einkaufen","en":"to shop"},{"de":"aufräumen","en":"to tidy up"},{"de":"anfangen (fängt an)","en":"to begin"},{"de":"aufhören","en":"to stop"},{"de":"mitkommen","en":"to come along"},{"de":"einladen (lädt ein)","en":"to invite"},{"de":"fernsehen (sieht fern)","en":"to watch TV"},{"de":"zurückkommen","en":"to come back"},{"de":"abholen","en":"to pick up"},{"de":"aufwachen","en":"to wake up"},{"de":"ausgehen","en":"to go out"},{"de":"mitbringen","en":"to bring along"},{"de":"vorbereiten","en":"to prepare"},{"de":"abwaschen","en":"to wash up"},{"de":"ausmachen","en":"to switch off"},{"de":"anmachen","en":"to switch on"},{"de":"aufschreiben","en":"to write down"},{"de":"anziehen","en":"to put on (clothes)"},{"de":"ausziehen","en":"to take off; to move out"},{"de":"weggehen","en":"to leave, to go away"},{"de":"zumachen / aufmachen","en":"to close / to open"},{"de":"spazieren gehen","en":"to go for a walk"},{"de":"der Müll","en":"rubbish"},{"de":"das Licht, -er","en":"light"},{"de":"der Fernseher, -","en":"TV set"},{"de":"das Essen","en":"food, meal"},{"de":"die Wäsche","en":"laundry"}],"reading":"Am Sonntag steht Ravi spät auf. Zuerst ruft er seine Mutter in Mumbai an. Dann räumt er die Wohnung auf. Mittags kauft er ein. Um 15 Uhr holt er Leila ab. Sie gehen zusammen spazieren. Leila fragt: „Kommst du am Mittwoch mit ins Kino? Der Film fängt um 19 Uhr an.“ – „Gern!“ Abends sieht Ravi ein bisschen fern. Um 23 Uhr schläft er ein.","tasks":[{"q":"Ich ___ um 7 Uhr ___. (aufstehen)","a":"stehe / auf"},{"q":"Ravi ___ seine Mutter ___. (anrufen)","a":"ruft / an"},{"q":"Wann ___ der Kurs ___? (anfangen)","a":"fängt / an"},{"q":"___ du mit? (mitkommen)","a":"Kommst"},{"q":"Anna ___ abends ___. (fernsehen)","a":"sieht / fern"},{"q":"Ich ___ dich am Bahnhof ___. (abholen)","a":"hole / ab"},{"q":"Ich ___ meine Tante. (besuchen)","a":"besuche"},{"q":"[Mix] Beginne mit „Am Samstag“: Wir kaufen ein.","a":"Am Samstag kaufen wir ein."},{"q":"[Mix] Verneine: Ich rufe dich an.","a":"Ich rufe dich nicht an."},{"q":"[Mix] Um ___ Uhr (7:30 inoffiziell) stehe ich auf.","a":"halb acht"},{"q":"Ich ___ um sieben ___. (aufstehen)","a":"stehe / auf"},{"q":"Er ___ seine Mutter ___. (anrufen)","a":"ruft / an"},{"q":"Wir ___ heute ___. (einkaufen)","a":"kaufen / ein"},{"q":"___ du ___? (mitkommen)","a":"Kommst / mit"},{"q":"Sie ___ den Fernseher ___. (ausmachen)","a":"macht / aus"},{"q":"Der Kurs ___ um neun ___. (anfangen)","a":"fängt / an"},{"q":"Ich ___ dich um acht ___. (abholen)","a":"hole / ab"},{"q":"Mia ___ die Küche ___. (aufräumen)","a":"räumt / auf"},{"q":"Ordne: am Abend / fern / sieht / Paul","a":"Paul sieht am Abend fern."},{"q":"Fehler? „Ich anrufe meine Mutter.“","a":"Ich rufe meine Mutter an."}],"exam":[{"q":"Wen ruft Ravi zuerst an?","a":"Seine Mutter."},{"q":"Wann holt Ravi Leila ab?","a":"Um 15 Uhr."},{"q":"Wann beginnt der Film?","a":"Um 19 Uhr (am Mittwoch)."},{"q":"Bilde einen Satz: einladen / Anna / Ravi / zum Essen","a":"Anna lädt Ravi zum Essen ein."},{"q":"Bilde eine Frage: du / aufräumen / heute?","a":"Räumst du heute auf?"},{"q":"Trennbar oder nicht? verkaufen / einkaufen","a":"verkaufen: nicht trennbar; einkaufen: trennbar"},{"q":"Ergänze: Der Bus ___ um 9 Uhr ___. (abfahren)","a":"fährt / ab"},{"q":"Beschreiben Sie Ihren Sonntag mit mindestens 5 trennbaren Verben.","a":"","m":"Am Sonntag stehe ich spät auf. Dann rufe ich meine Mutter an. Am Mittag kaufe ich nicht ein, denn die Geschäfte sind zu. Am Nachmittag räume ich auf. Am Abend sehe ich fern."},{"q":"Laden Sie einen Freund zu etwas ein.","a":"","m":"Hast du am Samstag Zeit? Ich lade dich zum Essen ein. Kommst du mit?"},{"q":"Was machen Sie am Abend, bevor Sie schlafen?","a":"","m":"Am Abend räume ich die Küche auf. Dann sehe ich fern oder lese. Um elf Uhr mache ich das Licht aus."}],"speak":["Was macht man im Schlafzimmer, was im Wohnzimmer? __Im Wohnzimmer sieht man fern…__","Beschreibe deinen Morgen: __Ich stehe … auf, dann …__","Lade deinen Partner ein: __Kommst du am … mit …?__","Wer räumt bei dir zu Hause auf?"],"reading2":{"title":"Ein Samstag in der WG","text":"Am Samstag ist in der WG viel los. Jonas wacht um acht Uhr auf, aber er steht erst um neun auf. Zuerst macht er Musik an. Mia schläft noch, sie findet das gar nicht lustig. Um zehn Uhr kaufen Jonas und Ravi im Supermarkt ein. Mia räumt die Küche auf und wäscht ab. Am Nachmittag bereitet Ravi das Abendessen vor, denn heute Abend kommen Gäste. Die WG lädt die Nachbarn ein: Anna Weber und ihren Sohn Paul. Anna bringt einen Kuchen mit. Paul ist zwölf und sieht gern fern. Nach dem Essen spielen alle zusammen Karten. Um elf Uhr gehen Anna und Paul nach Hause. Jonas macht den Fernseher aus. Mia bringt den Müll weg. Um Mitternacht schlafen alle. Morgen ist Sonntag, da stehen sie spät auf."},"dialog":[{"who":"Mia","de":"Jonas, stehst du bitte auf? Es ist schon zehn!"},{"who":"Jonas","de":"Ja, ja … ich stehe gleich auf."},{"who":"Mia","de":"Wir kaufen heute ein. Kommst du mit?"},{"who":"Jonas","de":"Wann fahrt ihr los?"},{"who":"Mia","de":"In einer halben Stunde. Und dann räumen wir auf."},{"who":"Jonas","de":"Oh nein. Muss ich auch aufräumen?"},{"who":"Mia","de":"Natürlich! Heute Abend kommen Gäste. Ravi kocht, du wäschst ab."},{"who":"Jonas","de":"Okay. Und was machst du?"},{"who":"Mia","de":"Ich bringe den Müll weg und kaufe Blumen."}],"dq":[{"q":"Wann fahren Mia und Ravi los?","a":"In einer halben Stunde."},{"q":"Was macht Jonas heute Abend?","a":"Er wäscht ab."},{"q":"Was macht Mia?","a":"Sie bringt den Müll weg und kauft Blumen."}],"en":{"title":"Separable verbs","theme":"Daily routine","expl":["Many verbs have a prefix that **separates** and goes to the **end of the sentence**: auf|stehen (to get up) → __Ich stehe um 7 Uhr auf.__ = I get up at 7.","Separable prefixes include ab-, an-, auf-, aus-, ein-, mit-, nach-, vor-, weg-, zu-, zurück-, fern-. The stress is on the prefix: __AUFstehen, FERNsehen__.","These prefixes **never** separate: be-, ver-, er-, ent-, ge-, zer-, emp-, miss-: __Ich besuche dich. Ich verstehe das.__","With a modal verb the separable verb stays together at the end: __Ich muss früh aufstehen.__"],"use":""},"check":[{"re":"\\\\b(auf|an|ein|aus|mit|fern|ab|zu|vor|zurück|los)\\\\b[.!?]?\\\\s*$|\\\\b(stehe|rufe|kaufe|sehe|räume|komme|fange|höre|lade|mache|ziehe|gehe) \\\\w+.*\\\\b(auf|an|ein|aus|mit|fern|ab|zu|vor|zurück|los)\\\\b","label":"a separable verb with the prefix at the end"}]},{"n":11,"pos":11,"level":"A1","title":"Modalverben","theme":"Regeln und Wünsche","scene":"station","rec":[2,3,6,7,9,10],"expl":["Modalverben: **können** (can), **müssen** (must), **wollen** (want), **sollen** (should, Auftrag), **dürfen** (may, erlaubt), **möchten** (would like).","Das **Modalverb** steht auf **Position 2**, das **Infinitiv** am **Ende**: __Ich **muss** heute **arbeiten**.__ Trennbare Verben bleiben am Ende zusammen: __Ich muss früh **aufstehen**.__","Ich und er/sie/es haben **keine Endung**: ich kann, er kann.","**nicht müssen** = not have to. **nicht dürfen** = must not! __Hier darf man nicht rauchen.__"],"use":"Planen, erlauben, verbieten, Wünsche äußern, Pflichten nennen.","table":[["Person","können","müssen","wollen","dürfen","sollen","möchten"],["ich","kann","muss","will","darf","soll","möchte"],["du","kannst","musst","willst","darfst","sollst","möchtest"],["er/sie/es","kann","muss","will","darf","soll","möchte"],["wir","können","müssen","wollen","dürfen","sollen","möchten"],["ihr","könnt","müsst","wollt","dürft","sollt","möchtet"],["sie/Sie","können","müssen","wollen","dürfen","sollen","möchten"]],"examples":[{"de":"Ich möchte eine Fahrkarte nach München.","en":"I\'d like a ticket to Munich."},{"de":"Kann ich mit Karte zahlen?","en":"Can I pay by card?"},{"de":"Du musst am Gleis 7 einsteigen.","en":"You have to board at platform 7."},{"de":"Hier darf man nicht rauchen.","en":"You\'re not allowed to smoke here."},{"de":"Ravi will im Sommer nach Wien fahren.","en":"Ravi wants to go to Vienna in summer."},{"de":"Wir müssen in Hamburg umsteigen.","en":"We have to change in Hamburg."},{"de":"Der Arzt sagt, ich soll viel trinken.","en":"The doctor says I should drink a lot."},{"de":"Darf ich hier sitzen?","en":"May I sit here?"},{"de":"Du musst nicht kommen.","en":"You don\'t have to come."},{"de":"Kannst du mich vom Bahnhof abholen?","en":"Can you pick me up from the station?"},{"de":"Kann ich hier ein Ticket kaufen?","en":"Can I buy a ticket here?"},{"de":"Sie müssen in Hannover umsteigen.","en":"You have to change trains in Hanover."},{"de":"Hier darf man nicht rauchen.","en":"You aren\'t allowed to smoke here."},{"de":"Ich möchte einen Platz am Fenster reservieren.","en":"I\'d like to reserve a window seat."},{"de":"Der Zug soll um 14:10 Uhr ankommen.","en":"The train is supposed to arrive at 2:10 pm."},{"de":"Wir wollen morgen nach München fahren.","en":"We want to go to Munich tomorrow."},{"de":"Kannst du mir helfen? Der Automat funktioniert nicht.","en":"Can you help me? The machine isn\'t working."},{"de":"Du musst dein Ticket entwerten.","en":"You have to validate your ticket."},{"de":"Darf ich meinen Hund mitnehmen?","en":"May I take my dog with me?"},{"de":"Der Zug hat zwanzig Minuten Verspätung.","en":"The train is twenty minutes late."}],"vocab":[{"de":"der Bahnhof, ¨e","en":"station"},{"de":"der Zug, ¨e","en":"train"},{"de":"das Gleis, -e","en":"platform"},{"de":"die Fahrkarte, -n","en":"ticket"},{"de":"einsteigen / aussteigen","en":"to get on / off"},{"de":"umsteigen","en":"to change (trains)"},{"de":"die Verspätung, -en","en":"delay"},{"de":"abfahren / ankommen","en":"to depart / arrive"},{"de":"reservieren","en":"to reserve"},{"de":"der Koffer, -","en":"suitcase"},{"de":"rauchen","en":"to smoke"},{"de":"erlaubt / verboten","en":"allowed / forbidden"},{"de":"können (kann)","en":"can, to be able to"},{"de":"müssen (muss)","en":"must, to have to"},{"de":"wollen (will)","en":"to want"},{"de":"dürfen (darf)","en":"may, to be allowed to"},{"de":"sollen (soll)","en":"should, to be supposed to"},{"de":"möchten","en":"would like"},{"de":"die Regel, -n","en":"rule"},{"de":"das Ticket, -s","en":"ticket"},{"de":"der Fahrplan, ¨e","en":"timetable"},{"de":"der Automat, -en","en":"(ticket) machine"},{"de":"die Abfahrt","en":"departure"},{"de":"die Ankunft","en":"arrival"},{"de":"der Bahnsteig, -e","en":"platform"},{"de":"der Platz, ¨e","en":"seat, place"},{"de":"die Durchsage, -n","en":"announcement"},{"de":"pünktlich","en":"on time"},{"de":"spät","en":"late"},{"de":"die Klasse, -n","en":"class"}],"reading":"Ravi will am Freitag nach München fahren. Er möchte seinen Freund Arjun besuchen. Am Schalter fragt er: „Ich möchte eine Fahrkarte nach München. Muss ich umsteigen?“ – „Nein, der ICE fährt direkt. Sie können auch einen Platz reservieren.“ – „Kann ich mit Karte zahlen?“ – „Ja, natürlich.“ Am Bahnhof sieht Ravi ein Schild: „Rauchen verboten.“ Der Zug hat Verspätung. Ravi muss 20 Minuten warten.","tasks":[{"q":"Ich ___ nach München fahren. (wollen)","a":"will"},{"q":"___ du mir helfen? (können)","a":"Kannst"},{"q":"Hier ___ man nicht parken. (dürfen)","a":"darf"},{"q":"Wir ___ in Köln umsteigen. (müssen)","a":"müssen"},{"q":"Ich ___ einen Tee, bitte. (möchten)","a":"möchte"},{"q":"Ordne: muss / früh / ich / aufstehen / morgen","a":"Morgen muss ich früh aufstehen."},{"q":"„Du musst nicht kommen“ bedeutet: a) verboten b) nicht nötig","a":"b) nicht nötig"},{"q":"[Mix] Ich ___ dich morgen ___. (können + anrufen)","a":"kann / anrufen"},{"q":"[Mix] Du ___ keinen Alkohol trinken. (dürfen)","a":"darfst"},{"q":"[Mix] Um ___ Uhr (14:15 inoffiziell: Viertel nach …) muss ich los.","a":"Viertel nach zwei"},{"q":"Ich ___ heute nicht kommen. (können)","a":"kann"},{"q":"Du ___ in Köln umsteigen. (müssen)","a":"musst"},{"q":"Hier ___ man nicht rauchen. (dürfen)","a":"darf"},{"q":"Er ___ nach Hamburg fahren. (wollen)","a":"will"},{"q":"Ich ___ einen Kaffee, bitte. (möchten)","a":"möchte"},{"q":"Wir ___ um acht da sein. (sollen)","a":"sollen"},{"q":"___ ihr mitkommen? (wollen)","a":"Wollt"},{"q":"Baue den Satz: ich / müssen / früh / aufstehen","a":"Ich muss früh aufstehen."},{"q":"Baue den Satz: man / dürfen / hier / nicht / parken","a":"Man darf hier nicht parken."},{"q":"Fehler? „Ich kann nicht kommen heute.“","a":"Ich kann heute nicht kommen."}],"exam":[{"q":"Wen will Ravi besuchen?","a":"Seinen Freund Arjun."},{"q":"Muss Ravi umsteigen?","a":"Nein."},{"q":"Wie lange muss Ravi warten?","a":"20 Minuten."},{"q":"Umformen mit „können“: Ich spreche Deutsch.","a":"Ich kann Deutsch sprechen."},{"q":"Umformen mit „müssen“: Er räumt auf.","a":"Er muss aufräumen."},{"q":"Frage höflich mit „dürfen“: hier / telefonieren","a":"Darf ich hier telefonieren?"},{"q":"Welches Modalverb? Der Chef sagt: „Schreiben Sie den Bericht!“ → Ich ___ den Bericht schreiben.","a":"soll"},{"q":"Was dürfen Kinder in Ihrem Land (nicht)? Nennen Sie 4 Regeln.","a":"","m":"Kinder dürfen nicht allein Auto fahren. Sie müssen in die Schule gehen. Sie dürfen nicht rauchen. Sie sollen früh ins Bett gehen."},{"q":"Sie kaufen am Schalter eine Fahrkarte. Spielen Sie das Gespräch.","a":"","m":"Guten Tag, ich möchte eine Fahrkarte nach Hamburg. – Einfach oder hin und zurück? – Hin und zurück, bitte. Kann ich mit Karte zahlen? – Ja, natürlich."},{"q":"Was möchten Sie in Deutschland machen? Was müssen Sie noch lernen?","a":"","m":"Ich möchte in Deutschland arbeiten. Ich muss noch viel Deutsch lernen. Ich will auch Freunde finden."}],"speak":["Wohin fährt der Zug? Was müssen die Leute machen?","Was darf man im Zug (nicht) machen?","Du willst nach Hamburg. Frag am Schalter: __Ich möchte … Muss ich …?__","Was kann man in Berlin am Wochenende machen?"],"reading2":{"title":"Eine Reise nach Hamburg","text":"Ravi will am Wochenende nach Hamburg fahren. Dort wohnt sein Freund Daniel. Er kauft das Ticket online, denn am Automaten ist es teurer. Der ICE fährt am Samstag um 8:36 Uhr ab. Ravi muss früh aufstehen. Am Bahnhof sieht er auf die Anzeige: Gleis 12. Dann hört er eine Durchsage: „Der ICE nach Hamburg hat etwa fünfzehn Minuten Verspätung.“ Ravi kauft einen Kaffee und wartet. Im Zug hat er einen reservierten Platz am Fenster. Im ICE darf man nicht rauchen, aber man kann im Bordrestaurant essen. Der Schaffner kontrolliert die Tickets. Ravi muss seinen Ausweis zeigen. Um 10:55 Uhr kommt der Zug in Hamburg an. Daniel wartet schon am Bahnsteig. „Willkommen in Hamburg! Du sollst unbedingt den Hafen sehen!“"},"dialog":[{"who":"Durchsage","de":"Achtung an Gleis 12: Der ICE 802 nach Hamburg fährt heute von Gleis 14 ab."},{"who":"Ravi","de":"Entschuldigung, wo ist Gleis 14?"},{"who":"Frau","de":"Da hinten, die Treppe hoch."},{"who":"Ravi","de":"Danke! Muss ich ein neues Ticket kaufen?"},{"who":"Frau","de":"Nein, Ihr Ticket gilt. Nur das Gleis ist anders."},{"who":"Ravi","de":"Und hat der Zug Verspätung?"},{"who":"Frau","de":"Ja, zehn Minuten. Sie können noch einen Kaffee kaufen."},{"who":"Ravi","de":"Super, vielen Dank!"}],"dq":[{"q":"Von welchem Gleis fährt der ICE heute ab?","a":"Von Gleis 14."},{"q":"Muss Ravi ein neues Ticket kaufen?","a":"Nein, sein Ticket gilt."},{"q":"Wie viel Verspätung hat der Zug?","a":"Zehn Minuten."}],"en":{"title":"Modal verbs (can, must, want …)","theme":"Rules and wishes","expl":["Modal verbs: **können** (can), **müssen** (must, have to), **wollen** (want), **sollen** (should – someone else wants it), **dürfen** (may, be allowed), **möchten** (would like).","The modal verb is in position 2 and the main verb goes to the **end in the infinitive**: __Ich muss heute arbeiten.__ = I have to work today.","For ich and er/sie/es modal verbs have **no ending** and often a different vowel: __ich kann, er kann; ich muss, er muss; ich will, er will__.","Careful: **nicht müssen** = don\'t have to; **nicht dürfen** = mustn\'t: __Du musst nicht kommen__ (it\'s optional) vs. __Du darfst nicht rauchen__ (it\'s forbidden)."],"use":""},"check":[{"re":"\\\\b(kann|kannst|können|muss|musst|müssen|darf|darfst|dürfen|will|willst|wollen|soll|sollst|sollen|möchte|möchtest|möchten)\\\\b","label":"a modal verb (kann, muss, darf …)"}]},{"n":12,"pos":12,"level":"A1","title":"Imperativ","theme":"Tipps und Anweisungen","scene":"doctor","rec":[2,6,7,10,11],"expl":["Mit dem **Imperativ** gibt man Bitten, Tipps und Anweisungen. Drei Formen:","**du:** Stamm ohne -st und ohne du: du kommst → **Komm!** Vokal e→i bleibt: du sprichst → **Sprich!** Aber a→ä nicht: du fährst → **Fahr!**","**ihr:** ihr-Form ohne ihr: **Kommt!** · **Sie:** Verb + Sie: **Kommen Sie!**","**sein:** Sei! Seid! Seien Sie! Mit **bitte**, **doch**, **mal** klingt es freundlicher. Trennbare Vorsilbe am Ende: **Ruf** mich **an**!"],"use":"Tipps geben, Wege erklären, Rezepte, beim Arzt.","table":[["Infinitiv","du","ihr","Sie"],["kommen","Komm!","Kommt!","Kommen Sie!"],["nehmen","Nimm!","Nehmt!","Nehmen Sie!"],["fahren","Fahr!","Fahrt!","Fahren Sie!"],["anrufen","Ruf an!","Ruft an!","Rufen Sie an!"],["arbeiten","Arbeite!","Arbeitet!","Arbeiten Sie!"],["sein","Sei!","Seid!","Seien Sie!"]],"examples":[{"de":"Nehmen Sie die Tabletten dreimal am Tag.","en":"Take the tablets three times a day."},{"de":"Trink viel Wasser!","en":"Drink a lot of water!"},{"de":"Bleib im Bett!","en":"Stay in bed!"},{"de":"Ruf mich bitte an!","en":"Please call me!"},{"de":"Seien Sie bitte pünktlich.","en":"Please be on time."},{"de":"Macht die Hausaufgaben!","en":"Do your homework! (pl.)"},{"de":"Iss nicht so viel Zucker!","en":"Don\'t eat so much sugar!"},{"de":"Geh doch mal zum Arzt!","en":"Why don\'t you go to the doctor!"},{"de":"Warten Sie bitte einen Moment.","en":"Please wait a moment."},{"de":"Sprich bitte langsam!","en":"Please speak slowly!"},{"de":"Bleib im Bett und trink viel Tee!","en":"Stay in bed and drink lots of tea!"},{"de":"Nehmen Sie die Tabletten dreimal täglich.","en":"Take the tablets three times a day."},{"de":"Geh zum Arzt!","en":"Go to the doctor!"},{"de":"Mach das Fenster auf!","en":"Open the window!"},{"de":"Seid bitte leise!","en":"Please be quiet! (to several people)"},{"de":"Ruf mich morgen an!","en":"Call me tomorrow!"},{"de":"Iss nicht so viel Schokolade!","en":"Don\'t eat so much chocolate!"},{"de":"Sprechen Sie bitte langsamer!","en":"Please speak more slowly!"},{"de":"Lies die Packungsbeilage!","en":"Read the package leaflet!"},{"de":"Gute Besserung!","en":"Get well soon!"}],"vocab":[{"de":"der Arzt, ¨e / die Ärztin, -nen","en":"doctor"},{"de":"die Praxis, Praxen","en":"practice"},{"de":"krank / gesund","en":"ill / healthy"},{"de":"der Kopf / Kopfschmerzen","en":"head / headache"},{"de":"der Bauch / Bauchschmerzen","en":"belly / stomach ache"},{"de":"das Fieber","en":"fever"},{"de":"die Erkältung, -en","en":"cold"},{"de":"die Tablette, -n","en":"tablet"},{"de":"das Rezept, -e","en":"prescription / recipe"},{"de":"die Apotheke, -n","en":"pharmacy"},{"de":"sich ausruhen","en":"to rest"},{"de":"die Krankmeldung","en":"sick note"},{"de":"der Hals, ¨e","en":"throat, neck"},{"de":"der Rücken, -","en":"back"},{"de":"der Arm, -e","en":"arm"},{"de":"das Bein, -e","en":"leg"},{"de":"der Fuß, ¨e","en":"foot"},{"de":"das Auge, -n","en":"eye"},{"de":"das Ohr, -en","en":"ear"},{"de":"der Zahn, ¨e","en":"tooth"},{"de":"der Husten","en":"cough"},{"de":"der Schnupfen","en":"runny nose"},{"de":"wehtun","en":"to hurt"},{"de":"trinken","en":"to drink"},{"de":"nehmen (nimmt)","en":"to take"},{"de":"bleiben","en":"to stay"},{"de":"das Bett","en":"bed"},{"de":"die Salbe, -n","en":"ointment"},{"de":"dreimal täglich","en":"three times a day"},{"de":"gute Besserung!","en":"get well soon!"}],"reading":"Ravi hat Fieber und Halsschmerzen. Er geht zur Ärztin. Die Ärztin sagt: „Machen Sie bitte den Mund auf. Sie haben eine Erkältung. Bleiben Sie drei Tage zu Hause und ruhen Sie sich aus. Trinken Sie viel Tee. Nehmen Sie diese Tabletten zweimal am Tag.“ Ravi ruft Jonas an. Jonas sagt: „Werd schnell gesund! Und arbeite nicht von zu Hause!“ Anna bringt Suppe: „Iss die Suppe, solange sie heiß ist!“","tasks":[{"q":"du: (trinken) ___ viel Wasser!","a":"Trink"},{"q":"du: (nehmen) ___ die Tablette!","a":"Nimm"},{"q":"Sie: (warten) ___ bitte!","a":"Warten Sie"},{"q":"ihr: (sein) ___ leise!","a":"Seid"},{"q":"du: (anrufen) ___ mich morgen ___!","a":"Ruf / an"},{"q":"du: (fahren) ___ vorsichtig!","a":"Fahr"},{"q":"du: (sein) ___ nicht traurig!","a":"Sei"},{"q":"[Mix] Umformen: Du musst im Bett bleiben. → Imperativ","a":"Bleib im Bett!"},{"q":"[Mix] Verneine: Iss Fleisch!","a":"Iss kein Fleisch!"},{"q":"[Mix] Sie-Form: Kannst du langsam sprechen?","a":"Sprechen Sie bitte langsam!"},{"q":"Imperativ (du): trinken → ___ viel Wasser!","a":"Trink"},{"q":"Imperativ (du): schlafen → ___ viel!","a":"Schlaf"},{"q":"Imperativ (du): nehmen → ___ eine Tablette!","a":"Nimm"},{"q":"Imperativ (du): lesen → ___ den Text!","a":"Lies"},{"q":"Imperativ (ihr): kommen → ___ bitte pünktlich!","a":"Kommt"},{"q":"Imperativ (Sie): warten → ___ Sie bitte hier!","a":"Warten"},{"q":"Imperativ (du): aufstehen → ___ jetzt ___!","a":"Steh / auf"},{"q":"Imperativ (du): sein → ___ bitte leise!","a":"Sei"},{"q":"Imperativ (Sie): anrufen → ___ Sie morgen ___!","a":"Rufen / an"},{"q":"Fehler? „Nehmst du die Tablette!“","a":"Nimm die Tablette!"}],"exam":[{"q":"Was hat Ravi?","a":"Eine Erkältung (Fieber, Halsschmerzen)."},{"q":"Wie oft soll er die Tabletten nehmen?","a":"Zweimal am Tag."},{"q":"Was bringt Anna?","a":"Suppe."},{"q":"du-Imperativ: lesen","a":"Lies!"},{"q":"ihr-Imperativ: aufräumen","a":"Räumt auf!"},{"q":"Sie-Imperativ: sich setzen","a":"Setzen Sie sich!"},{"q":"Mach höflich: „Tür zu!“ (Sie)","a":"Machen Sie bitte die Tür zu!"},{"q":"Ihr Freund hat Kopfschmerzen. Geben Sie 4 Tipps im Imperativ.","a":"","m":"Trink viel Wasser! Nimm eine Tablette! Geh früh ins Bett! Mach eine Pause vom Handy!"},{"q":"Erklären Sie ein einfaches Rezept aus Ihrem Land.","a":"","m":"Nimm Reis und Linsen. Koch die Linsen mit Wasser. Schneid eine Zwiebel und brate sie in Öl. Gib Salz und Gewürze dazu. Iss das Dal mit Reis."},{"q":"Welche Tipps geben Sie einem neuen Deutschlerner?","a":"","m":"Lern jeden Tag zehn Minuten. Sprich viel, auch mit Fehlern. Hör deutsche Podcasts. Hab keine Angst!"}],"speak":["Was sagt die Ärztin zum Patienten? __Nehmen Sie … Bleiben Sie …__","Was fehlt dem Patienten vielleicht?","Gib einem Freund Tipps gegen Stress (du-Form).","Was macht man in Indien bei einer Erkältung? __Trink … mit Ingwer!__"],"reading2":{"title":"Tipps gegen eine Erkältung","text":"Im Herbst sind viele Menschen erkältet. Sie haben Husten, Schnupfen und manchmal Fieber. Was hilft? Hier sind ein paar Tipps von Doktor Becker. Erstens: Trinken Sie viel, am besten Wasser oder Tee. Zweitens: Schlafen Sie viel und bleiben Sie zu Hause. Gehen Sie mit Fieber nicht zur Arbeit! Drittens: Essen Sie Obst und Gemüse. Viertens: Waschen Sie oft die Hände. So bekommt Ihre Familie die Erkältung nicht. Und für Kinder: Spielt lieber drinnen und zieht eine warme Jacke an! Nehmen Sie Tabletten nur nach Plan. Lesen Sie immer die Packungsbeilage. Haben Sie nach drei Tagen noch Fieber? Dann rufen Sie bitte in der Praxis an. In Deutschland brauchen Sie ab dem vierten Tag eine Krankmeldung für den Arbeitgeber."},"dialog":[{"who":"Dr. Becker","de":"Guten Tag, Herr Sharma. Was fehlt Ihnen denn?"},{"who":"Ravi","de":"Ich habe Halsschmerzen und Husten. Und mein Kopf tut weh."},{"who":"Dr. Becker","de":"Haben Sie Fieber?"},{"who":"Ravi","de":"Ja, gestern Abend achtunddreißig Grad."},{"who":"Dr. Becker","de":"Machen Sie bitte den Mund auf. … Ja, der Hals ist rot. Das ist eine Erkältung."},{"who":"Ravi","de":"Muss ich Tabletten nehmen?"},{"who":"Dr. Becker","de":"Nehmen Sie diese Tabletten dreimal täglich nach dem Essen. Und trinken Sie viel Tee."},{"who":"Ravi","de":"Kann ich morgen arbeiten?"},{"who":"Dr. Becker","de":"Nein, bleiben Sie drei Tage zu Hause. Hier ist Ihre Krankmeldung. Gute Besserung!"}],"dq":[{"q":"Welche Beschwerden hat Ravi?","a":"Halsschmerzen, Husten und Kopfschmerzen (und Fieber)."},{"q":"Wie oft soll er die Tabletten nehmen?","a":"Dreimal täglich nach dem Essen."},{"q":"Wie lange soll Ravi zu Hause bleiben?","a":"Drei Tage."}],"en":{"title":"The imperative (giving instructions)","theme":"Tips and instructions","expl":["Use the imperative for requests, tips and instructions. There are three forms.","**du**: the du-form without -st and without du: __du kommst → Komm!__ An e→i change stays: __du sprichst → Sprich!__ but a→ä does not: __du fährst → Fahr!__","**ihr**: the ihr-form without ihr: __Kommt!__ · **Sie**: verb + Sie: __Kommen Sie!__ · Irregular **sein**: __Sei! Seid! Seien Sie!__","Add **bitte**, **doch** or **mal** to sound friendlier: __Komm doch mal vorbei!__ = Why don\'t you drop by?"],"use":""},"check":[{"re":"^\\\\s*(trink|nimm|geh|schlaf|mach|iss|lies|sprich|hör|komm|sei|bleib|lern|wiederhole|schreib|seht|trinkt|nehmen sie|gehen sie)\\\\b|[.!]\\\\s*(trink|nimm|geh|schlaf|mach|iss|lies|sprich|hör|komm|sei|bleib|lern|schreib)\\\\b","label":"imperative (Trink …! Geh …!)"}]},{"n":61,"pos":13,"level":"A1","title":"Das Perfekt – erste Schritte","theme":"Mein Wochenende","scene":"park","rec":[10],"expl":["Über die **Vergangenheit** spricht man im Alltag fast immer mit dem **Perfekt**: __Ich habe gearbeitet.__ __Wir sind nach Hause gegangen.__ Die Prüfung A1 erwartet das schon für einfache Sätze über gestern und das Wochenende.","Das Perfekt hat zwei Teile: **haben** oder **sein** auf **Position 2** und das **Partizip II** am **Ende**. Regelmäßig: **ge- … -t** (machen → gemacht, kaufen → gekauft). Viele häufige Verben sind unregelmäßig: **ge- … -en** (essen → gegessen, sehen → gesehen, schlafen → geschlafen).","Die meisten Verben nehmen **haben**. Mit **sein** stehen Verben der **Bewegung** (gehen, fahren, kommen, fliegen) und **sein** und **bleiben**. Hier lernst du die 20 wichtigsten Formen; die ganze Regel kommt in Lektion 17."],"use":"Prüfung A1, Sprechen und Schreiben: über gestern, das Wochenende oder den Urlaub berichten.","table":[["Infinitiv","haben/sein","Partizip II","Beispiel"],["machen","haben","gemacht","Ich **habe** Sport **gemacht**."],["kaufen","haben","gekauft","Wir **haben** Brot **gekauft**."],["essen","haben","gegessen","Hast du schon **gegessen**?"],["trinken","haben","getrunken","Er **hat** Tee **getrunken**."],["sehen","haben","gesehen","Ich **habe** einen Film **gesehen**."],["gehen","sein","gegangen","Sie **ist** ins Kino **gegangen**."],["fahren","sein","gefahren","Wir **sind** nach Köln **gefahren**."],["bleiben","sein","geblieben","Ich **bin** zu Hause **geblieben**."]],"examples":[{"de":"Gestern habe ich viel gearbeitet.","en":"Yesterday I worked a lot."},{"de":"Am Samstag habe ich eingekauft.","en":"On Saturday I went shopping."},{"de":"Wir haben Pizza gegessen.","en":"We ate pizza."},{"de":"Hast du gut geschlafen?","en":"Did you sleep well?"},{"de":"Er hat ein Buch gelesen.","en":"He read a book."},{"de":"Ich habe meine Mutter angerufen.","en":"I called my mother."},{"de":"Sie ist mit dem Bus gefahren.","en":"She went by bus."},{"de":"Wir sind in den Park gegangen.","en":"We went to the park."},{"de":"Am Sonntag bin ich zu Hause geblieben.","en":"On Sunday I stayed at home."},{"de":"Was hast du am Wochenende gemacht?","en":"What did you do at the weekend?"},{"de":"Ich habe Fußball gespielt.","en":"I played football."},{"de":"Habt ihr den Film gesehen?","en":"Did you see the film?"},{"de":"Ravi ist spät nach Hause gekommen.","en":"Ravi came home late."},{"de":"Ich habe Kaffee getrunken.","en":"I drank coffee."},{"de":"Wir haben Musik gehört.","en":"We listened to music."}],"vocab":[{"de":"gestern","en":"yesterday"},{"de":"am Wochenende","en":"at the weekend"},{"de":"letzten Samstag","en":"last Saturday"},{"de":"gemacht (machen)","en":"done, made"},{"de":"gekauft (kaufen)","en":"bought"},{"de":"gegessen (essen)","en":"eaten"},{"de":"getrunken (trinken)","en":"drunk"},{"de":"gesehen (sehen)","en":"seen"},{"de":"gelesen (lesen)","en":"read"},{"de":"geschlafen (schlafen)","en":"slept"},{"de":"gespielt (spielen)","en":"played"},{"de":"gehört (hören)","en":"heard"},{"de":"gearbeitet (arbeiten)","en":"worked"},{"de":"gekocht (kochen)","en":"cooked"},{"de":"angerufen (anrufen)","en":"called"},{"de":"eingekauft (einkaufen)","en":"shopped"},{"de":"gegangen (gehen)","en":"gone"},{"de":"gefahren (fahren)","en":"driven, gone"},{"de":"gekommen (kommen)","en":"come"},{"de":"geblieben (bleiben)","en":"stayed"}],"reading":"Am Samstag hat Mia lange geschlafen. Um zehn Uhr hat sie gefrühstückt und Kaffee getrunken. Dann ist sie mit dem Fahrrad zum Markt gefahren. Dort hat sie Obst und Gemüse gekauft. Am Nachmittag hat sie für die Uni gelernt. Am Abend ist sie mit Tomás ins Kino gegangen. Sie haben eine Komödie gesehen. Danach haben sie in einem Restaurant gegessen. Am Sonntag ist Mia zu Hause geblieben. Sie hat ein Buch gelesen, Musik gehört und ihre Eltern angerufen. Am Abend hat sie gekocht: Nudeln mit Tomatensoße. Es war ein schönes Wochenende.","tasks":[{"q":"Ich ___ Pizza ___. (essen)","a":"habe / gegessen"},{"q":"Wir ___ ins Kino ___. (gehen)","a":"sind / gegangen"},{"q":"Er ___ einen Film ___. (sehen)","a":"hat / gesehen"},{"q":"___ du gut ___? (schlafen)","a":"Hast / geschlafen"},{"q":"Sie ___ zu Hause ___. (bleiben)","a":"ist / geblieben"},{"q":"Ich ___ Brot ___. (kaufen)","a":"habe / gekauft"},{"q":"Ihr ___ nach Berlin ___. (fahren)","a":"seid / gefahren"},{"q":"Wir ___ Musik ___. (hören)","a":"haben / gehört"},{"q":"Partizip II: machen →","a":"gemacht"},{"q":"Partizip II: trinken →","a":"getrunken"},{"q":"haben oder sein? Ich ___ nach Hause gekommen.","a":"bin"},{"q":"Fehler? „Ich habe ins Kino gegangen.“","a":"Ich bin ins Kino gegangen."}],"exam":[{"q":"Wann hat Mia gefrühstückt?","a":"Um zehn Uhr."},{"q":"Wie ist Mia zum Markt gefahren?","a":"Mit dem Fahrrad."},{"q":"Was hat Mia auf dem Markt gekauft?","a":"Obst und Gemüse."},{"q":"Was haben Mia und Tomás im Kino gesehen?","a":"Eine Komödie."},{"q":"Was hat Mia am Sonntagabend gekocht?","a":"Nudeln mit Tomatensoße."},{"q":"Perfekt: Ich trinke Tee.","a":"Ich habe Tee getrunken."},{"q":"Perfekt: Wir gehen in den Park.","a":"Wir sind in den Park gegangen."},{"q":"Was haben Sie gestern gemacht? (4 Sätze)","a":"","m":"Gestern habe ich gearbeitet. Am Abend habe ich gekocht. Dann habe ich einen Film gesehen. Ich bin um elf Uhr ins Bett gegangen."},{"q":"Erzählen Sie von Ihrem Wochenende.","a":"","m":"Am Samstag habe ich lange geschlafen. Dann habe ich Freunde getroffen. Wir sind in die Stadt gefahren und haben Kaffee getrunken. Am Sonntag habe ich meine Mutter angerufen."},{"q":"Schreiben Sie einer Freundin eine SMS: Was haben Sie heute gemacht?","a":"","m":"Hallo Mia! Heute habe ich viel gemacht: Ich habe Deutsch gelernt und eingekauft. Am Abend habe ich Pizza gegessen. Und du?"}],"speak":["Was haben die Leute im Park gemacht? __Ein Mann hat … Eine Frau ist …__","Was hast du gestern gemacht? Fünf Sätze mit haben oder sein.","Frag deinen Partner: __Was hast du am Wochenende gemacht?__","Erzähl: Wohin bist du gefahren? Was hast du gegessen?"],"dialog":[{"who":"Jonas","de":"Hallo Mia! Wie war dein Wochenende?"},{"who":"Mia","de":"Schön! Am Samstag bin ich mit Tomás ins Kino gegangen."},{"who":"Jonas","de":"Was habt ihr gesehen?"},{"who":"Mia","de":"Eine Komödie. Und danach haben wir italienisch gegessen."},{"who":"Jonas","de":"Und am Sonntag?"},{"who":"Mia","de":"Da bin ich zu Hause geblieben. Ich habe gelesen und gekocht. Und du?"},{"who":"Jonas","de":"Ich habe gearbeitet. Leider."}],"dq":[{"q":"Wohin ist Mia am Samstag gegangen?","a":"Ins Kino."},{"q":"Was hat Mia am Sonntag gemacht?","a":"Sie ist zu Hause geblieben, hat gelesen und gekocht."},{"q":"Was hat Jonas am Wochenende gemacht?","a":"Er hat gearbeitet."}],"en":{"title":"The perfect tense – first steps","theme":"My weekend","expl":["In everyday speech Germans talk about the past almost always with the **Perfekt**: __Ich habe gearbeitet.__ = I worked / I have worked. __Wir sind nach Hause gegangen.__ = We went home.","It has two parts: **haben or sein** in position 2 and the **past participle** at the end.","Regular participle: **ge- … -t**: machen → __gemacht__, kaufen → __gekauft__. Many common irregular verbs: **ge- … -en**: essen → __gegessen__, sehen → __gesehen__.","Most verbs use **haben**. Verbs of movement from A to B (gehen, fahren, kommen, fliegen) and change of state use **sein**: __Ich bin nach Berlin gefahren.__"],"use":"The A1 exam already expects simple sentences about yesterday and the weekend."},"check":[{"re":"\\\\b(habe|hast|hat|haben|habt|bin|bist|ist|sind|seid)\\\\b.*\\\\bge\\\\w+(t|en)\\\\b","label":"Perfekt: haben/sein + ge…t / ge…en"}]},{"n":13,"pos":14,"level":"A2","title":"Der Dativ: Artikel, Pronomen und Dativ-Verben","theme":"Hilfe und Gefallen","scene":"office","rec":[1,6,8,11],"expl":["Der **Dativ** antwortet auf **Wem?** Er zeigt meistens die **Person**, die etwas bekommt oder für die etwas passiert.","Artikel: der → **dem**, die → **der**, das → **dem**, Plural die → **den + n** (den Kinder**n**). ein → **einem/einer**, mein → **meinem/meiner**.","**Dativ-Verben** (nur Dativ-Objekt!): helfen, danken, gefallen, gehören, schmecken, passen, stehen (Kleidung), antworten, gratulieren, zuhören, fehlen, wehtun.","Wichtige Ausdrücke: __Wie geht es **dir**? **Mir** ist kalt. Das ist **mir** egal. Es tut **mir** leid.__"],"use":"Hilfe anbieten, Gefallen/Meinung ausdrücken, Befinden sagen.","table":[["Fall","maskulin","feminin","neutral","Plural","Pronomen"],["Nominativ","der / ein","die / eine","das / ein","die","ich, du, er, sie, wir, ihr, sie"],["Akkusativ","den / einen","die / eine","das / ein","die","mich, dich, ihn, sie, uns, euch, sie"],["Dativ","**dem / einem**","**der / einer**","**dem / einem**","**den … -n**","**mir, dir, ihm, ihr, uns, euch, ihnen**"]],"examples":[{"de":"Kannst du mir helfen?","en":"Can you help me?"},{"de":"Ravi hilft dem Kollegen.","en":"Ravi helps the colleague."},{"de":"Das Büro gefällt ihm.","en":"He likes the office."},{"de":"Gehört der Laptop dir?","en":"Does the laptop belong to you?"},{"de":"Ich danke Ihnen für die Hilfe.","en":"Thank you for the help."},{"de":"Die Jacke passt meiner Schwester nicht.","en":"The jacket doesn\'t fit my sister."},{"de":"Wie geht es Ihnen? – Mir geht es gut.","en":"How are you? – I\'m fine."},{"de":"Das Essen schmeckt den Kindern.","en":"The children like the food."},{"de":"Wir gratulieren unserer Chefin.","en":"We congratulate our boss."},{"de":"Mir ist kalt. Dir auch?","en":"I\'m cold. You too?"},{"de":"Kannst du mir einen Gefallen tun?","en":"Can you do me a favour?"},{"de":"Das Paket gehört meinem Nachbarn.","en":"The parcel belongs to my neighbour."},{"de":"Wie geht es Ihnen? – Danke, mir geht es gut.","en":"How are you? – Thanks, I\'m fine."},{"de":"Die Jacke steht dir super!","en":"The jacket really suits you!"},{"de":"Das Essen schmeckt den Kindern nicht.","en":"The children don\'t like the food."},{"de":"Hör mir bitte zu!","en":"Please listen to me!"},{"de":"Ich glaube dir kein Wort.","en":"I don\'t believe a word you say."},{"de":"Mir ist kalt.","en":"I\'m cold."},{"de":"Was fehlt dir?","en":"What\'s wrong with you?"},{"de":"Es tut mir leid, ich habe keine Zeit.","en":"I\'m sorry, I don\'t have time."}],"vocab":[{"de":"der Kollege, -n / die Kollegin, -nen","en":"colleague"},{"de":"der Chef, -s / die Chefin, -nen","en":"boss"},{"de":"helfen (hilft)","en":"to help"},{"de":"gefallen (gefällt)","en":"to please (like)"},{"de":"gehören","en":"to belong"},{"de":"danken","en":"to thank"},{"de":"passen","en":"to fit / suit"},{"de":"antworten","en":"to answer"},{"de":"gratulieren","en":"to congratulate"},{"de":"wehtun","en":"to hurt"},{"de":"leidtun","en":"to be sorry"},{"de":"egal","en":"doesn\'t matter"},{"de":"der Nachbar, -n / die Nachbarin, -nen","en":"neighbour"},{"de":"die Hilfe","en":"help"},{"de":"der Gefallen, -","en":"favour"},{"de":"bitten um","en":"to ask for"},{"de":"zuhören","en":"to listen to"},{"de":"glauben","en":"to believe"},{"de":"vertrauen","en":"to trust"},{"de":"folgen","en":"to follow"},{"de":"fehlen","en":"to be missing; to miss"},{"de":"schmecken","en":"to taste (good)"},{"de":"stehen (+ Dat.)","en":"to suit"},{"de":"die Schlüssel (Pl.)","en":"keys"},{"de":"das Paket, -e","en":"parcel"},{"de":"die Pflanze, -n","en":"plant"},{"de":"gießen","en":"to water"},{"de":"der Briefkasten, ¨","en":"letterbox"},{"de":"kaputt","en":"broken"},{"de":"zum Glück","en":"luckily"}],"reading":"Ravi ist neu im Team. Jonas hilft ihm viel. Er zeigt ihm das System und antwortet ihm immer schnell. Die neue Arbeit gefällt Ravi sehr. Heute hat die Chefin, Frau Berger, Geburtstag. Alle gratulieren ihr. Ravi schenkt ihr indischen Tee. Der Tee schmeckt der Chefin. Sie dankt ihm: „Das ist sehr nett von Ihnen!“ Später fragt Jonas: „Gehört die Tasse dir?“ – „Nein, sie gehört meiner Kollegin Mia.“","tasks":[{"q":"Ich helfe ___ Mann. (der)","a":"dem"},{"q":"Das Kleid gefällt ___ Frau. (die)","a":"der"},{"q":"Der Ball gehört ___ Kind. (das)","a":"dem"},{"q":"Wir danken ___ Kinder___. (die, Pl.)","a":"den / Kindern"},{"q":"Kannst du ___ helfen? (ich)","a":"mir"},{"q":"Wie geht es ___? (du)","a":"dir"},{"q":"Die Schuhe passen ___ nicht. (er)","a":"ihm"},{"q":"[Mix] Ich kaufe ___ Tee und schenke ___ Chefin ___ Tee. (der, meine, der)","a":"den / meiner / den"},{"q":"[Mix] ___ mir bitte! (helfen, du-Imperativ)","a":"Hilf"},{"q":"[Mix] Ich ___ dir morgen helfen. (können)","a":"kann"},{"q":"Ich helfe ___ Nachbarin. (die)","a":"der"},{"q":"Das Buch gehört ___ Lehrer. (der)","a":"dem"},{"q":"Wie geht es ___? (du)","a":"dir"},{"q":"Die Jacke gefällt ___. (ich)","a":"mir"},{"q":"Kannst du ___ helfen? (wir)","a":"uns"},{"q":"Ich danke ___ für die Blumen. (Sie)","a":"Ihnen"},{"q":"Das Auto gehört ___ Eltern. (meine)","a":"meinen"},{"q":"Hör ___ bitte zu! (ich)","a":"mir"},{"q":"Fehler? „Ich helfe dich.“","a":"Ich helfe dir."},{"q":"Fehler? „Das gefällt mich.“","a":"Das gefällt mir."}],"exam":[{"q":"Wer hilft Ravi?","a":"Jonas."},{"q":"Was schenkt Ravi der Chefin?","a":"Indischen Tee."},{"q":"Wem gehört die Tasse?","a":"Mias (seiner Kollegin Mia)."},{"q":"Akk. oder Dat.? „Ich sehe den Mann.“ / „Ich helfe dem Mann.“","a":"Akkusativ / Dativ"},{"q":"Ergänze: Das Buch gehört ___ Lehrerin.","a":"der"},{"q":"Ersetze: Ich danke __meinem Vater__.","a":"Ich danke ihm."},{"q":"Ergänze: Es tut ___ leid. (ich)","a":"mir"},{"q":"Was gefällt Ihnen in Deutschland? Was gefällt Ihnen nicht?","a":"","m":"Mir gefällt die Natur in Deutschland. Die Parks gefallen mir sehr. Das Wetter gefällt mir nicht, es ist oft kalt. Auch die Bürokratie gefällt mir nicht."},{"q":"Wem helfen Sie oft? Wie?","a":"","m":"Ich helfe oft meiner Nachbarin. Sie ist alt, und ich trage ihr die Einkaufstaschen. Ich helfe auch meinem Bruder bei den Hausaufgaben."},{"q":"Ihr Kollege ist neu. Bieten Sie ihm Hilfe an.","a":"","m":"Hallo, ich bin Ravi. Kann ich dir helfen? Ich zeige dir gern das Büro. Wenn du Fragen hast, sag es mir einfach."}],"speak":["Wer hilft wem im Büro? __Die Kollegin hilft dem Mann …__","Gefällt dir das Büro? Warum (nicht)?","Frag deinen Partner: __Wem gehört …? Kannst du mir … helfen?__","Wie geht es dir heute? Antworte mit __Mir ist … / Mir geht es …__"],"reading2":{"title":"Nachbarschaftshilfe","text":"Anna Weber fährt für eine Woche zu ihrer Schwester nach München. Vorher klingelt sie bei der WG. Ravi öffnet die Tür. „Hallo Ravi, kannst du mir einen Gefallen tun?“ – „Klar, wie kann ich dir helfen?“ Anna erklärt: „Meine Pflanzen brauchen Wasser. Kannst du sie zweimal gießen? Hier sind meine Schlüssel.“ Ravi nimmt die Schlüssel. „Kein Problem. Gehört dir auch das Fahrrad im Hof?“ – „Nein, das gehört Paul, meinem Sohn. Er bleibt bei seinem Vater.“ Anna gibt Ravi noch ihre Telefonnummer. „Und bitte nimm meine Post aus dem Briefkasten.“ Am Mittwoch kommt ein großes Paket für Anna. Der Paketbote fragt Ravi: „Können Sie das Paket für Ihre Nachbarin annehmen?“ Ravi unterschreibt. Am Sonntag kommt Anna zurück. Sie dankt Ravi und schenkt ihm eine Flasche Wein. „Ich trinke doch keinen Alkohol!“, lacht Ravi. „Oh, das tut mir leid! Dann bekommst du Schokolade.“"},"dialog":[{"who":"Ravi","de":"Hallo, Herr Kaya! Kann ich Ihnen helfen? Die Tasche sieht schwer aus."},{"who":"Herr Kaya","de":"Oh, danke, das ist sehr nett von Ihnen. Mir tut der Rücken weh."},{"who":"Ravi","de":"Wohin soll ich die Tasche bringen?"},{"who":"Herr Kaya","de":"In den dritten Stock. Der Aufzug ist leider kaputt."},{"who":"Ravi","de":"Kein Problem. Gehört Ihnen auch der Karton hier?"},{"who":"Herr Kaya","de":"Nein, der gehört Frau Weber, glaube ich."},{"who":"Ravi","de":"Gut, dann frage ich sie später."},{"who":"Herr Kaya","de":"Ich danke Ihnen sehr! Möchten Sie einen Tee?"}],"dq":[{"q":"Warum braucht Herr Kaya Hilfe?","a":"Ihm tut der Rücken weh und der Aufzug ist kaputt."},{"q":"Wohin bringt Ravi die Tasche?","a":"In den dritten Stock."},{"q":"Wem gehört der Karton?","a":"Frau Weber (vermutlich)."}],"en":{"title":"The dative: articles, pronouns and dative verbs","theme":"Help and favours","expl":["The **dative** answers \\"to whom? / for whom?\\" (Wem?). It usually marks the person who receives something or for whom something happens.","Articles: der → **dem**, die → **der**, das → **dem**, plural die → **den** + -n on the noun (__den Kindern__). ein → **einem/einer**, mein → **meinem/meiner**.","Some verbs take **only a dative object**: helfen, danken, gefallen, gehören, schmecken, passen, stehen (clothes), gratulieren: __Ich helfe dir. Das Buch gehört mir.__","Dative pronouns: mir, dir, ihm, ihr, ihm, uns, euch, ihnen/Ihnen: __Wie geht es Ihnen?__ = How are you?"],"use":""},"check":[{"re":"\\\\b(mir|dir|ihm|ihr|uns|euch|ihnen|dem|der|den \\\\w+n)\\\\b","label":"a dative form (mir, ihm, dem …)"},{"re":"\\\\b(gefällt|gefallen|hilft|helfe|helfen|gehört|danke|schmeckt|passt)\\\\b","label":"a dative verb (gefallen, helfen …)"}]},{"n":14,"pos":15,"level":"A2","title":"Dativ und Akkusativ im selben Satz","theme":"Geschenke","scene":"party","rec":[6,8,13],"expl":["Verben wie **geben, schenken, zeigen, bringen, schicken, erklären, empfehlen, kaufen, leihen** haben zwei Objekte: **Person (Dativ)** und **Sache (Akkusativ)**.","**Reihenfolge:** Zwei Nomen → **Dativ vor Akkusativ**: __Ich schenke **meiner Mutter** **einen Schal**.__","Ein Pronomen → **Pronomen zuerst**: __Ich schenke **ihn** meiner Mutter. / Ich schenke **ihr** einen Schal.__","Zwei Pronomen → **Akkusativ vor Dativ**: __Ich schenke **ihn ihr**.__"],"use":"Über Geschenke, Empfehlungen, Erklärungen sprechen (Teil 1 Planung: Geschenk kaufen!).","table":[["Fall","Satz","Regel"],["Nomen + Nomen","Ich gebe **dem Kind** **den Ball**.","Dativ → Akkusativ"],["Pronomen + Nomen","Ich gebe **ihm** **den Ball**.","Pronomen zuerst"],["Nomen + Pronomen","Ich gebe **ihn** **dem Kind**.","Pronomen zuerst"],["Pronomen + Pronomen","Ich gebe **ihn ihm**.","Akkusativ → Dativ"]],"examples":[{"de":"Ich schenke meinem Vater ein Buch.","en":"I give my father a book."},{"de":"Ich schenke es ihm zum Geburtstag.","en":"I give it to him for his birthday."},{"de":"Zeig mir bitte das Foto!","en":"Show me the photo, please."},{"de":"Kannst du mir den Weg erklären?","en":"Can you explain the way to me?"},{"de":"Anna bringt den Kindern Kuchen.","en":"Anna brings the children cake."},{"de":"Ich empfehle dir diesen Film.","en":"I recommend this film to you."},{"de":"Schick ihn mir bitte per E-Mail!","en":"Please send it to me by email."},{"de":"Er leiht seiner Freundin das Fahrrad.","en":"He lends his girlfriend the bike."},{"de":"Wir kaufen unserer Oma eine Blume.","en":"We buy our grandma a flower."},{"de":"Gib es ihr!","en":"Give it to her!"},{"de":"Ich schenke meiner Mutter Blumen.","en":"I\'m giving my mother flowers."},{"de":"Ich schenke sie ihr.","en":"I\'m giving them to her."},{"de":"Kannst du mir das Salz geben?","en":"Can you pass me the salt?"},{"de":"Er zeigt den Gästen die Wohnung.","en":"He shows the guests the flat."},{"de":"Er zeigt sie ihnen.","en":"He shows it to them."},{"de":"Wir kaufen unserem Sohn ein Fahrrad.","en":"We are buying our son a bike."},{"de":"Leihst du mir dein Auto?","en":"Will you lend me your car?"},{"de":"Ich erkläre dir die Aufgabe.","en":"I\'ll explain the task to you."},{"de":"Kannst du es mir erklären?","en":"Can you explain it to me?"},{"de":"Ich wünsche dir alles Gute zum Geburtstag!","en":"I wish you a happy birthday!"}],"vocab":[{"de":"das Geschenk, -e","en":"present"},{"de":"der Geburtstag, -e","en":"birthday"},{"de":"schenken","en":"to give (as present)"},{"de":"geben (gibt)","en":"to give"},{"de":"zeigen","en":"to show"},{"de":"schicken","en":"to send"},{"de":"erklären","en":"to explain"},{"de":"leihen","en":"to lend"},{"de":"empfehlen (empfiehlt)","en":"to recommend"},{"de":"der Gutschein, -e","en":"voucher"},{"de":"die Kerze, -n","en":"candle"},{"de":"der Blumenstrauß, ¨e","en":"bouquet"},{"de":"bringen","en":"to bring"},{"de":"kaufen","en":"to buy"},{"de":"schreiben","en":"to write"},{"de":"bestellen","en":"to order"},{"de":"wünschen","en":"to wish"},{"de":"überraschen","en":"to surprise"},{"de":"einpacken","en":"to wrap"},{"de":"das Geschenkpapier","en":"wrapping paper"},{"de":"die Karte, -n","en":"card"},{"de":"die Schokolade, -n","en":"chocolate"},{"de":"das Parfüm, -s","en":"perfume"},{"de":"der Schmuck","en":"jewellery"},{"de":"die Kette, -n","en":"necklace"},{"de":"das Spiel, -e","en":"game"},{"de":"der Gast, ¨e","en":"guest"},{"de":"die Idee, -n","en":"idea"},{"de":"umtauschen","en":"to exchange (goods)"},{"de":"zurückgeben","en":"to give back"}],"reading":"Anna hat am Samstag Geburtstag. Ravi und Leila überlegen: „Was schenken wir ihr?“ Leila sagt: „Wir können ihr einen Gutschein schenken.“ Ravi zeigt Leila einen schönen Schal im Internet. „Kaufen wir ihn ihr?“ – „Ja! Und Max, ihrem Sohn, bringen wir ein kleines Spiel mit.“ Am Samstag gibt Ravi Anna den Schal. Anna freut sich sehr: „Danke! Wer hat ihn euch empfohlen?“ – „Niemand. Wir haben gute Ideen!“","tasks":[{"q":"Ich schenke ___ Mutter ___ Kette. (meine, eine)","a":"meiner / eine"},{"q":"Er gibt ___ Kind ___ Apfel. (das, ein)","a":"dem / einen"},{"q":"Zeig ___ (ich) das Handy!","a":"mir"},{"q":"Ordne: dem Lehrer / ich / das Heft / gebe","a":"Ich gebe dem Lehrer das Heft."},{"q":"Ersetze das Heft: Ich gebe ___ dem Lehrer.","a":"es"},{"q":"Ersetze beides: Ich gebe ___ ___.","a":"es ihm"},{"q":"Ordne: erklärt / ihr / die Chefin / den Plan","a":"Die Chefin erklärt ihr den Plan."},{"q":"[Mix] Wir müssen ___ Oma ___ Geschenk kaufen. (unsere, ein)","a":"unserer / ein"},{"q":"[Mix] Kannst du ___ ___ schicken? (es, ich)","a":"es mir"},{"q":"[Mix] Imperativ (Sie): mir / zeigen / den Pass","a":"Zeigen Sie mir den Pass!"},{"q":"Ich gebe ___ Kind ___ Ball. (das / der)","a":"dem / den"},{"q":"Sie schenkt ___ Freundin ___ Kette. (ihre / eine)","a":"ihrer / eine"},{"q":"Er zeigt ___ Gästen ___ Garten. (die / der)","a":"den / den"},{"q":"Pronomen: Ich schenke meiner Mutter die Blumen. → Ich schenke ___ ___.","a":"sie ihr"},{"q":"Pronomen: Er gibt dem Kind das Buch. → Er gibt ___ ___.","a":"es ihm"},{"q":"Pronomen: Wir zeigen den Gästen die Stadt. → Wir zeigen ___ ___.","a":"sie ihnen"},{"q":"Ordne: dir / ich / leihe / mein Fahrrad","a":"Ich leihe dir mein Fahrrad."},{"q":"Ordne: es / ich / dir / erkläre","a":"Ich erkläre es dir."},{"q":"Ordne: ihm / ich / es / gebe","a":"Ich gebe es ihm."},{"q":"Fehler? „Sie schenkt ihr ihn.“","a":"Sie schenkt ihn ihr."}],"exam":[{"q":"Wer hat Geburtstag?","a":"Anna."},{"q":"Was bekommt Anna?","a":"Einen Schal."},{"q":"Was bringen sie Max mit?","a":"Ein kleines Spiel."},{"q":"Ersetze: Ich schenke __meiner Schwester__ __die Blumen__.","a":"Ich schenke sie ihr."},{"q":"Ergänze: Kannst du ___ (wir) ___ Weg erklären?","a":"uns / den"},{"q":"Ordne: ihm / ihn / gebe / ich","a":"Ich gebe ihn ihm."},{"q":"Ergänze: Ich empfehle ___ Gästen ___ Restaurant. (die, das)","a":"den / das"},{"q":"Planen Sie mit Ihrem Partner ein Geschenk für eine Kollegin. Was, wie teuer, wer kauft es?","a":"","m":"Wir schenken Anna einen Gutschein. Er kostet 30 Euro. Ich kaufe ihn morgen, und du schreibst ihr eine Karte. Wir geben ihr das Geschenk am Freitag."},{"q":"Was war Ihr schönstes Geschenk? Wer hat es Ihnen geschenkt?","a":"","m":"Mein schönstes Geschenk war eine Uhr. Meine Eltern haben sie mir zum Abitur geschenkt."},{"q":"Was schenkt man in Ihrem Land zur Hochzeit?","a":"","m":"In Indien schenkt man dem Brautpaar oft Geld oder Gold. Man gibt ihnen auch Kleidung."}],"speak":["Was schenken die Personen? Wem?","Was ist im Paket? (Vermutung) __Vielleicht schenkt sie ihm …__","Plane eine Überraschung für einen Freund. __Wir kaufen ihm … und geben es ihm …__","Welche Geschenke findest du gut, welche nicht?"],"reading2":{"title":"Was schenken wir Jonas?","text":"Nächsten Samstag hat Jonas Geburtstag. Er wird dreißig. Mia und Ravi wollen ihm etwas Besonderes schenken. Mia hat eine Idee: „Wir schenken ihm ein Konzertticket. Er liebt doch Jazz.“ Ravi findet die Idee gut, aber das Ticket ist teuer. „Dann fragen wir auch Leila und Tomás. Zusammen ist es billiger.“ Leila findet die Idee super. Sie kauft noch eine Karte und schreibt Jonas ein Gedicht. Tomás bringt ihm einen Kuchen aus einer brasilianischen Bäckerei. Am Samstagmorgen packt Mia das Geschenk ein. Um zehn Uhr stehen alle vor Jonas’ Tür und singen. Jonas öffnet das Geschenk. Er freut sich sehr. „Wer hat euch die Idee gegeben?“ – „Mia!“ Jonas umarmt sie. Am Abend zeigt er seinen Eltern das Ticket. Seine Mutter sagt: „Du hast wirklich gute Freunde.“"},"dialog":[{"who":"Verkäuferin","de":"Guten Tag! Suchen Sie etwas Bestimmtes?"},{"who":"Leila","de":"Ja, ein Geschenk für meine Schwiegermutter. Sie hat Geburtstag."},{"who":"Verkäuferin","de":"Was mag sie denn? Schmuck, Parfüm, ein Buch?"},{"who":"Leila","de":"Sie liest gern. Können Sie mir ein Buch empfehlen?"},{"who":"Verkäuferin","de":"Dieser Roman ist gerade sehr beliebt. Ich zeige ihn Ihnen."},{"who":"Leila","de":"Schön. Und wenn sie das Buch schon hat?"},{"who":"Verkäuferin","de":"Dann kann sie es innerhalb von vierzehn Tagen umtauschen."},{"who":"Leila","de":"Perfekt. Können Sie es mir als Geschenk einpacken?"},{"who":"Verkäuferin","de":"Natürlich, sehr gern."}],"dq":[{"q":"Für wen sucht Leila ein Geschenk?","a":"Für ihre Schwiegermutter."},{"q":"Was empfiehlt die Verkäuferin?","a":"Einen Roman / ein Buch."},{"q":"Wie lange kann man das Buch umtauschen?","a":"Vierzehn Tage."}],"en":{"title":"Dative and accusative in the same sentence","theme":"Presents","expl":["Verbs like geben, schenken, zeigen, bringen, schicken, erklären, empfehlen, kaufen and leihen have two objects: the **person (dative)** and the **thing (accusative)**: __Ich schenke meiner Mutter einen Schal.__ = I give my mother a scarf.","Order: two nouns → **dative before accusative**. One pronoun → **the pronoun first**: __Ich schenke ihn meiner Mutter. / Ich schenke ihr einen Schal.__ Two pronouns → **accusative before dative**: __Ich schenke ihn ihr.__"],"use":""},"check":[{"re":"\\\\b(mir|dir|ihm|ihr|uns|ihnen|meiner|meinem|der|dem)\\\\b.*\\\\b(einen|eine|ein|den|die|das|es|ihn)\\\\b","label":"person (dative) + thing (accusative)"}]},{"n":15,"pos":16,"level":"A2","title":"Präpositionen mit Akkusativ und mit Dativ","theme":"Wege in der Stadt","scene":"city","rec":[6,9,11,13],"expl":["**Immer Akkusativ:** durch, für, gegen, ohne, um, bis (Merke: **DOGFU** = durch, ohne, gegen, für, um).","**Immer Dativ:** aus, bei, mit, nach, seit, von, zu, gegenüber (Merke: **aus-bei-mit-nach-von-seit-zu**).","**Wichtig:** __nach__ + Städte/Länder ohne Artikel (__nach Berlin__), __zu__ + Personen/Orte (__zum Arzt, zu Anna__), __nach Hause__ (Richtung) / __zu Hause__ (Ort).","Kontraktionen: zu dem → **zum**, zu der → **zur**, bei dem → **beim**, von dem → **vom**."],"use":"Wege beschreiben, Verkehrsmittel nennen, Herkunft und Zeit angeben.","table":[["Präposition","Fall","Beispiel","Bedeutung"],["für","Akk.","für den Chef","for"],["ohne","Akk.","ohne meinen Schlüssel","without"],["durch","Akk.","durch den Park","through"],["mit","Dat.","mit dem Bus","with / by"],["zu","Dat.","zum Bahnhof, zur Post","to"],["bei","Dat.","beim Arzt, bei meiner Tante","at (someone\'s)"],["aus","Dat.","aus dem Haus, aus Indien","out of / from"],["seit","Dat.","seit einem Jahr","since / for"]],"examples":[{"de":"Ich fahre mit der U-Bahn zur Arbeit.","en":"I go to work by underground."},{"de":"Gehen Sie durch den Park!","en":"Go through the park!"},{"de":"Das Geschenk ist für meinen Bruder.","en":"The present is for my brother."},{"de":"Ravi wohnt seit einem Jahr in Berlin.","en":"Ravi has lived in Berlin for a year."},{"de":"Ich komme gerade vom Arzt.","en":"I\'m just coming from the doctor."},{"de":"Heute Abend bin ich bei Leila.","en":"Tonight I\'m at Leila\'s."},{"de":"Gegenüber der Bank ist ein Café.","en":"Opposite the bank is a café."},{"de":"Ohne dich gehe ich nicht.","en":"I\'m not going without you."},{"de":"Nach dem Kurs fahre ich nach Hause.","en":"After the course I go home."},{"de":"Wir gehen um den See.","en":"We walk around the lake."},{"de":"Gehen Sie hier geradeaus und dann links.","en":"Go straight on here and then left."},{"de":"Die Post ist gegenüber vom Bahnhof.","en":"The post office is opposite the station."},{"de":"Ich fahre mit dem Bus zur Arbeit.","en":"I go to work by bus."},{"de":"Wir gehen durch den Park.","en":"We walk through the park."},{"de":"Das Geschenk ist für dich.","en":"The present is for you."},{"de":"Er kommt gerade aus der Bank.","en":"He\'s just coming out of the bank."},{"de":"Ich wohne bei meiner Tante.","en":"I\'m staying with my aunt."},{"de":"Nach dem Kino gehen wir essen.","en":"After the cinema we\'ll go and eat."},{"de":"Seit einem Jahr lerne ich Deutsch.","en":"I\'ve been learning German for a year."},{"de":"Wie komme ich zum Rathaus?","en":"How do I get to the town hall?"}],"vocab":[{"de":"die Haltestelle, -n","en":"stop"},{"de":"die Straße, -n","en":"street"},{"de":"die Ampel, -n","en":"traffic light"},{"de":"die Kreuzung, -en","en":"crossing"},{"de":"geradeaus","en":"straight ahead"},{"de":"links / rechts","en":"left / right"},{"de":"abbiegen","en":"to turn"},{"de":"die Post","en":"post office"},{"de":"die Bank, -en","en":"bank"},{"de":"das Rathaus, ¨er","en":"town hall"},{"de":"das Fahrrad, ¨er","en":"bike"},{"de":"zu Fuß","en":"on foot"},{"de":"durch","en":"through"},{"de":"für","en":"for"},{"de":"gegen","en":"against"},{"de":"ohne","en":"without"},{"de":"um","en":"around"},{"de":"aus","en":"out of, from"},{"de":"bei","en":"at, near"},{"de":"mit","en":"with"},{"de":"nach","en":"to, after"},{"de":"seit","en":"since, for"},{"de":"von","en":"from, of"},{"de":"zu","en":"to"},{"de":"gegenüber","en":"opposite"},{"de":"die Apotheke, -n","en":"pharmacy"},{"de":"die Kirche, -n","en":"church"},{"de":"der Platz, ¨e","en":"square"},{"de":"die Brücke, -n","en":"bridge"},{"de":"der Weg, -e","en":"way, path"}],"reading":"Leila besucht Ravi zum ersten Mal. Sie ruft ihn an: „Ich bin am Bahnhof. Wie komme ich zu dir?“ – „Nimm den Bus 100. Fahr bis zur Haltestelle Rathaus. Dann geh zu Fuß durch den Park. Gegenüber dem Park ist eine Bäckerei. Mein Haus ist neben der Bäckerei.“ – „Ohne Stadtplan ist das schwer!“ – „Kein Problem, ich hole dich von der Haltestelle ab.“ Nach zehn Minuten sind sie zusammen bei Ravi.","tasks":[{"q":"Ich fahre ___ Bus. (mit + der)","a":"mit dem"},{"q":"Das ist ___ meine Mutter. (für)","a":"für"},{"q":"Ravi kommt ___ Indien.","a":"aus"},{"q":"Ich gehe ___ Arzt. (zu + der)","a":"zum"},{"q":"Sie wohnt ___ drei Jahren hier.","a":"seit"},{"q":"Wir gehen ___ Park. (durch + der)","a":"durch den"},{"q":"Er arbeitet ___ Siemens.","a":"bei"},{"q":"[Mix] Ich fahre heute ___ Hause, ich bin nicht gern ___ Hause.","a":"nach / zu"},{"q":"[Mix] Kannst du ___ (ich) ___ Hause bringen?","a":"mich / nach"},{"q":"[Mix] ___ geradeaus bis ___ Ampel! (gehen, du; zu + die)","a":"Geh / zur"},{"q":"Ich fahre mit ___ Bus. (der)","a":"dem"},{"q":"Das Geschenk ist für ___ Chef. (der)","a":"den"},{"q":"Wir gehen durch ___ Park. (der)","a":"den"},{"q":"Sie kommt aus ___ Küche. (die)","a":"der"},{"q":"Er geht zu ___ Arzt. (der)","a":"zum"},{"q":"Ich gehe zu ___ Post. (die)","a":"zur"},{"q":"Seit ___ Woche ist er krank. (eine)","a":"einer"},{"q":"Nach ___ Arbeit gehe ich einkaufen. (die)","a":"der"},{"q":"Ich trinke Kaffee ohne ___ Zucker. (der)","a":"den"},{"q":"Fehler? „Ich fahre mit den Zug.“","a":"Ich fahre mit dem Zug."}],"exam":[{"q":"Welchen Bus nimmt Leila?","a":"Den Bus 100."},{"q":"Wo ist Ravis Haus?","a":"Neben der Bäckerei (gegenüber dem Park)."},{"q":"Wer holt Leila ab?","a":"Ravi."},{"q":"Ergänze: Wir treffen uns ___ Bahnhof. (an + dem)","a":"am"},{"q":"Ergänze: Wir fliegen ___ Mumbai.","a":"nach"},{"q":"Ergänze: Ich gehe ___ Freundin. (zu + meine)","a":"zu meiner"},{"q":"Ergänze: Das ist ein Film ___ Kinder.","a":"für"},{"q":"Beschreiben Sie den Weg von Ihrer Wohnung zum Supermarkt.","a":"","m":"Ich gehe aus dem Haus und dann links. Ich gehe durch den Park und über die Straße. Der Supermarkt ist gegenüber der Bank, direkt neben der Apotheke."},{"q":"Wie fahren Sie zur Arbeit / zum Kurs? Wie lange dauert das?","a":"","m":"Ich fahre mit dem Bus zur Arbeit. Die Fahrt dauert zwanzig Minuten. Manchmal fahre ich mit dem Fahrrad."},{"q":"Ein Tourist fragt Sie nach dem Weg zum Bahnhof. Helfen Sie.","a":"","m":"Zum Bahnhof? Gehen Sie hier geradeaus bis zur Ampel. Dann gehen Sie rechts. Der Bahnhof ist nach 200 Metern auf der linken Seite."}],"speak":["Wohin fährt der Bus? Wie kommt der Mann zum Bahnhof?","Erkläre den Weg: __Geh geradeaus bis zur …, dann …__","Womit fährst du lieber: mit dem Bus, mit dem Rad oder mit dem Auto? Warum?","Wie ist der Verkehr in Mumbai im Vergleich zu Berlin?"],"reading2":{"title":"Der Weg zum Bürgeramt","text":"Leila hat morgen um neun Uhr einen Termin beim Bürgeramt. Sie kennt den Weg noch nicht und fragt Anna. Anna erklärt: „Das ist ganz einfach. Du fährst mit der U-Bahn bis zum Alexanderplatz. Dort steigst du aus. Dann gehst du durch den Bahnhof und am Ausgang links. Du gehst geradeaus bis zur Ampel. An der Kreuzung gehst du über die Straße. Das Bürgeramt ist gegenüber von einer Apotheke, neben einem Café.“ Leila schreibt alles auf. Am nächsten Morgen fährt sie mit der U-Bahn. Aber am Alexanderplatz gibt es viele Ausgänge. Sie nimmt den falschen Ausgang und steht plötzlich vor dem Fernsehturm. Sie fragt einen Mann nach dem Weg. „Zum Bürgeramt? Gehen Sie um den Turm herum und dann die zweite Straße rechts.“ Leila kommt fünf Minuten zu spät, aber die Mitarbeiterin ist freundlich. „Kein Problem, Sie sind ja jetzt da.“"},"dialog":[{"who":"Tourist","de":"Entschuldigung, wie komme ich zum Museum?"},{"who":"Ravi","de":"Zum Museum? Das ist nicht weit. Gehen Sie hier geradeaus bis zur Brücke."},{"who":"Tourist","de":"Bis zur Brücke, okay."},{"who":"Ravi","de":"Dann gehen Sie über die Brücke und biegen Sie rechts ab."},{"who":"Tourist","de":"Und dann?"},{"who":"Ravi","de":"Dann sehen Sie eine Kirche. Das Museum ist gleich neben der Kirche."},{"who":"Tourist","de":"Kann ich auch mit dem Bus fahren?"},{"who":"Ravi","de":"Ja, mit der Linie 100. Aber zu Fuß sind es nur zehn Minuten."},{"who":"Tourist","de":"Vielen Dank!"}],"dq":[{"q":"Wo ist das Museum?","a":"Neben der Kirche."},{"q":"Was macht der Tourist nach der Brücke?","a":"Er biegt rechts ab."},{"q":"Wie lange dauert es zu Fuß?","a":"Zehn Minuten."}],"en":{"title":"Prepositions with the accusative and with the dative","theme":"Getting around town","expl":["**Always accusative**: durch (through), für (for), gegen (against), ohne (without), um (around), bis (until).","**Always dative**: aus (from, out of), bei (at, near), mit (with), nach (to, after), seit (since), von (from, of), zu (to), gegenüber (opposite).","Important: **nach** + cities and countries without an article (__nach Berlin__), **zu** + people and places (__zum Arzt, zu Anna__), **nach Hause** = (going) home, **zu Hause** = (being) at home.","Short forms: zu dem → **zum**, zu der → **zur**, bei dem → **beim**, von dem → **vom**."],"use":""},"check":[{"re":"\\\\b(mit|nach|zu|zum|zur|aus|bei|beim|von|vom|seit|durch|für|ohne|um|gegen|bis)\\\\b","label":"prepositions (mit, zum, durch …)"}]},{"n":16,"pos":17,"level":"A2","title":"Wechselpräpositionen: Wo? (Dativ) und Wohin? (Akkusativ)","theme":"Umzug und Einrichten","scene":"moving","rec":[5,6,13,15],"expl":["**an, auf, hinter, in, neben, über, unter, vor, zwischen** können Dativ oder Akkusativ haben.","**Wo?** (Position, keine Bewegung) → **Dativ**: __Das Buch liegt **auf dem** Tisch.__","**Wohin?** (Richtung, Bewegung zum Ziel) → **Akkusativ**: __Ich lege das Buch **auf den** Tisch.__","Verbpaare: **stellen → stehen**, **legen → liegen**, **setzen → sitzen**, **hängen → hängen**. Die Verben mit Bewegung (stellen, legen, setzen, hängen) = Akkusativ."],"use":"Umzug, Zimmer beschreiben, Bildbeschreibung (Wo ist was?).","table":[["Präp.","Wo? (Dativ)","Wohin? (Akkusativ)"],["in","Ich bin **im** Büro.","Ich gehe **ins** Büro."],["auf","Die Tasse steht **auf dem** Tisch.","Ich stelle die Tasse **auf den** Tisch."],["an","Das Bild hängt **an der** Wand.","Ich hänge das Bild **an die** Wand."],["neben","Der Stuhl steht **neben dem** Bett.","Ich stelle den Stuhl **neben das** Bett."],["unter","Die Katze liegt **unter dem** Sofa.","Die Katze läuft **unter das** Sofa."],["zwischen","Die Lampe steht **zwischen den** Sesseln.","Ich stelle sie **zwischen die** Sessel."]],"examples":[{"de":"Stell den Karton in die Küche!","en":"Put the box in the kitchen!"},{"de":"Der Karton steht in der Küche.","en":"The box is in the kitchen."},{"de":"Ich lege die Bücher ins Regal.","en":"I put the books on the shelf."},{"de":"Die Bücher liegen im Regal.","en":"The books are on the shelf."},{"de":"Wir hängen die Lampe über den Tisch.","en":"We hang the lamp above the table."},{"de":"Die Lampe hängt über dem Tisch.","en":"The lamp hangs above the table."},{"de":"Setz dich auf das Sofa!","en":"Sit down on the sofa!"},{"de":"Max sitzt auf dem Sofa.","en":"Max is sitting on the sofa."},{"de":"Der Schlüssel liegt unter der Zeitung.","en":"The key is under the newspaper."},{"de":"Wir fahren morgen in die Stadt.","en":"Tomorrow we\'re going into town."},{"de":"Das Bild hängt an der Wand.","en":"The picture is hanging on the wall."},{"de":"Ich hänge das Bild an die Wand.","en":"I hang the picture on the wall."},{"de":"Die Bücher stehen im Regal.","en":"The books are on the shelf."},{"de":"Stell die Bücher bitte ins Regal!","en":"Put the books on the shelf, please!"},{"de":"Die Katze liegt unter dem Sofa.","en":"The cat is lying under the sofa."},{"de":"Leg die Decke auf das Sofa!","en":"Put the blanket on the sofa!"},{"de":"Der Sessel steht zwischen dem Fenster und der Tür.","en":"The armchair is between the window and the door."},{"de":"Wohin kommt die Lampe? – Über den Tisch.","en":"Where does the lamp go? – Above the table."},{"de":"Die Kartons sind noch im Keller.","en":"The boxes are still in the cellar."},{"de":"Setz dich doch auf den Stuhl!","en":"Do sit down on the chair!"}],"vocab":[{"de":"der Umzug, ¨e","en":"house move"},{"de":"umziehen","en":"to move house"},{"de":"der Karton, -s","en":"cardboard box"},{"de":"die Wand, ¨e","en":"wall"},{"de":"der Boden, ¨","en":"floor"},{"de":"die Ecke, -n","en":"corner"},{"de":"stellen / stehen","en":"to put (upright) / to stand"},{"de":"legen / liegen","en":"to lay / to lie"},{"de":"hängen","en":"to hang"},{"de":"setzen / sitzen","en":"to seat / to sit"},{"de":"der Sessel, -","en":"armchair"},{"de":"die Möbel (Pl.)","en":"furniture"},{"de":"das Regal, -e","en":"shelf"},{"de":"die Kommode, -n","en":"chest of drawers"},{"de":"das Bild, -er","en":"picture"},{"de":"der Vorhang, ¨e","en":"curtain"},{"de":"die Decke, -n","en":"ceiling; blanket"},{"de":"an","en":"at, on (vertical)"},{"de":"auf","en":"on (horizontal)"},{"de":"hinter","en":"behind"},{"de":"in","en":"in, into"},{"de":"neben","en":"next to"},{"de":"über","en":"above, over"},{"de":"unter","en":"under"},{"de":"vor","en":"in front of"},{"de":"zwischen","en":"between"},{"de":"der Hof, ¨e","en":"courtyard"},{"de":"der Keller, -","en":"cellar"},{"de":"der Stock / die Etage","en":"floor, storey"},{"de":"tragen (trägt)","en":"to carry"}],"reading":"Ravi zieht um. Jonas und Anna helfen ihm. Ravi sagt: „Stellt die Kartons bitte ins Wohnzimmer.“ Jonas stellt das Sofa an die Wand. Anna legt die Bücher ins Regal. „Wohin hängen wir das Bild?“ – „Über das Sofa.“ Am Abend ist alles fertig: Das Sofa steht an der Wand, das Bild hängt über dem Sofa, die Bücher liegen im Regal. Nur der Schlüssel fehlt! Endlich findet Ravi ihn: Er liegt unter einem Karton.","tasks":[{"q":"Ich stelle die Vase auf ___ Tisch.","a":"den"},{"q":"Die Vase steht auf ___ Tisch.","a":"dem"},{"q":"Das Bild hängt an ___ Wand.","a":"der"},{"q":"Leg das Handy in ___ Tasche!","a":"die"},{"q":"Ich gehe ___ Kino. (in + das)","a":"ins"},{"q":"Die Katze liegt unter ___ Bett.","a":"dem"},{"q":"Wählen: Ich ___ den Teller auf den Tisch. (stelle/stehe)","a":"stelle"},{"q":"[Mix] Wo ist das Buch? – ___ liegt ___ Regal. (es, in + das)","a":"Es / im"},{"q":"[Mix] Stell ___ (er = der Stuhl) neben ___ Tür!","a":"ihn / die"},{"q":"[Mix] Wir müssen die Kartons ___ Keller bringen. (in + der)","a":"in den"},{"q":"Wo? Das Buch liegt auf ___ Tisch. (der)","a":"dem"},{"q":"Wohin? Ich lege das Buch auf ___ Tisch. (der)","a":"den"},{"q":"Wo? Der Hund schläft unter ___ Bett. (das)","a":"dem"},{"q":"Wohin? Ich stelle die Vase in ___ Küche. (die)","a":"die"},{"q":"Wo? Die Lampe hängt über ___ Sofa. (das)","a":"dem"},{"q":"Wohin? Er hängt das Bild an ___ Wand. (die)","a":"die"},{"q":"stehen oder stellen? Ich ___ die Flasche in den Kühlschrank.","a":"stelle"},{"q":"liegen oder legen? Das Handy ___ auf dem Bett.","a":"liegt"},{"q":"hängen: Das Bild ___ schon an der Wand.","a":"hängt"},{"q":"Fehler? „Ich lege das Buch auf dem Tisch.“","a":"Ich lege das Buch auf den Tisch."}],"exam":[{"q":"Wer hilft Ravi beim Umzug?","a":"Jonas und Anna."},{"q":"Wo hängt das Bild?","a":"Über dem Sofa."},{"q":"Wo ist der Schlüssel?","a":"Unter einem Karton."},{"q":"Wo oder wohin? „Ich fahre in die Stadt.“","a":"Wohin → Akkusativ"},{"q":"Ergänze: Das Auto steht vor ___ Haus.","a":"dem"},{"q":"Ergänze: Setz dich neben ___ (ich)!","a":"mich"},{"q":"Ergänze: Ich hänge die Jacke in ___ Schrank.","a":"den"},{"q":"Beschreiben Sie Ihr Zimmer genau: Was steht / liegt / hängt wo?","a":"","m":"Mein Bett steht am Fenster. Neben dem Bett steht ein kleiner Tisch. Auf dem Tisch liegt ein Buch. An der Wand hängt ein Bild. Der Schrank steht zwischen der Tür und dem Fenster."},{"q":"Sie ziehen um. Geben Sie Ihren Freunden Anweisungen.","a":"","m":"Stellt das Sofa bitte an die Wand! Legt die Bücher in den Schrank! Hängt die Lampe über den Tisch! Und stellt die Kisten in die Küche."},{"q":"Was war schwierig bei Ihrem letzten Umzug?","a":"","m":"Mein letzter Umzug war schwierig. Der Schrank hat nicht in den Aufzug gepasst. Wir mussten ihn in den vierten Stock tragen."}],"speak":["Wo stehen die Kartons? Wo steht das Sofa? __Links neben dem …__","Was machen die Männer? Wohin tragen sie den Karton?","Gib Anweisungen: __Stell den Karton in … Leg die Bücher auf …__","Beschreibe ein Bild in deinem Zimmer: Wo hängt es?"],"reading2":{"title":"Umzug in die neue Wohnung","text":"Ravi zieht um. Er hat endlich eine eigene Wohnung gefunden, zwei Zimmer in Pankow. Am Samstag helfen Jonas, Tomás und Mia. Morgens um acht steht der Transporter vor dem Haus. Die Freunde tragen die Kartons in den zweiten Stock. „Wohin kommen die Bücher?“, fragt Tomás. „Ins Wohnzimmer, neben das Regal“, sagt Ravi. Das Sofa stellen sie an die Wand, gegenüber vom Fenster. Der Teppich liegt bald vor dem Sofa. Mia hängt die Vorhänge auf. Jonas baut das Bett im Schlafzimmer auf. „Wo ist der Schraubenzieher?“ – „Er liegt auf dem Tisch in der Küche.“ Am Nachmittag sind fast alle Kartons leer. Nur die Lampe fehlt. Sie ist noch im Auto, unter einer Decke. Ravi hängt sie über den Esstisch. Am Abend sitzen alle müde auf dem Boden und essen Pizza. „Deine Wohnung ist wirklich schön“, sagt Mia. „Aber wo ist dein Fernseher?“ – „Den kaufe ich nächste Woche.“"},"dialog":[{"who":"Jonas","de":"Ravi, wohin soll ich den Spiegel hängen?"},{"who":"Ravi","de":"Ins Bad, bitte. Über das Waschbecken."},{"who":"Jonas","de":"Okay. Und die Kiste mit den Schuhen?"},{"who":"Ravi","de":"Die stellst du in den Flur, neben die Tür."},{"who":"Jonas","de":"Wo sind eigentlich die Nägel?"},{"who":"Ravi","de":"Sie liegen in der kleinen Kiste auf dem Stuhl."},{"who":"Jonas","de":"Ich sehe sie nicht. Auf welchem Stuhl?"},{"who":"Ravi","de":"Auf dem Stuhl in der Küche. Ah nein, warte, sie sind in meiner Jackentasche!"}],"dq":[{"q":"Wohin kommt der Spiegel?","a":"Ins Bad, über das Waschbecken."},{"q":"Wohin stellt Jonas die Schuhkiste?","a":"In den Flur, neben die Tür."},{"q":"Wo sind die Nägel am Ende?","a":"In Ravis Jackentasche."}],"en":{"title":"Two-way prepositions: Where? (dative) and Where to? (accusative)","theme":"Moving and furnishing","expl":["an, auf, hinter, in, neben, über, unter, vor and zwischen can take **dative or accusative**.","**Wo?** (where – position, no movement) → **dative**: __Das Buch liegt auf dem Tisch.__ = The book is lying on the table.","**Wohin?** (where to – direction, movement to a goal) → **accusative**: __Ich lege das Buch auf den Tisch.__ = I put the book on the table.","Verb pairs: stellen (put upright, acc.) → stehen (stand, dat.), legen (lay, acc.) → liegen (lie, dat.), setzen → sitzen, hängen → hängen."],"use":""},"check":[{"re":"\\\\b(auf|in|an|neben|unter|über|vor|hinter|zwischen) (dem|der|den|die|das|einem|einer|im|am)\\\\b|\\\\b(im|am)\\\\b","label":"two-way prepositions (auf dem Tisch / auf den Tisch)"},{"re":"\\\\b(steht|liegt|hängt|stellt|legt|hängen|stellen|legen|stell|leg|häng)\\\\b","label":"stehen/liegen/hängen or stellen/legen/hängen"}]},{"n":17,"pos":18,"level":"A2","title":"Das Perfekt","theme":"Erlebnisse und Wochenende","scene":"park","rec":[2,9,10,15,16],"expl":["Das **Perfekt** ist die wichtigste Vergangenheit **beim Sprechen**. Form: **haben/sein (Position 2) + Partizip II (Ende)**.","**Partizip II:** regelmäßig **ge-…-t** (gemacht, gekauft), unregelmäßig **ge-…-en** oft mit Vokalwechsel (gegessen, getrunken, geschrieben).","**Trennbare Verben:** ge in der Mitte: auf**ge**standen, ein**ge**kauft. **Ohne ge-:** Verben auf **-ieren** (studiert) und mit untrennbarer Vorsilbe be-/ver-/er-… (besucht, verstanden).","**sein** bei Bewegung (fahren, gehen, fliegen, kommen) und Veränderung (aufstehen, einschlafen, werden) + sein, bleiben, passieren. Sonst **haben**."],"use":"Prüfung: Erfahrungen erzählen („Ich habe schon … gemacht“), Wochenende, Reisen.","table":[["Typ","Infinitiv","Perfekt"],["regelmäßig","machen","Ich **habe** Sport **gemacht**."],["unregelmäßig","essen","Wir **haben** Pizza **gegessen**."],["trennbar","einkaufen","Er **hat** **eingekauft**."],["-ieren","telefonieren","Sie **hat** lange **telefoniert**."],["untrennbar","besuchen","Ich **habe** Oma **besucht**."],["sein: Bewegung","fahren","Wir **sind** nach Potsdam **gefahren**."],["sein: Veränderung","aufstehen","Ich **bin** spät **aufgestanden**."]],"examples":[{"de":"Am Wochenende habe ich viel gelesen.","en":"At the weekend I read a lot."},{"de":"Wir sind in den Park gegangen.","en":"We went to the park."},{"de":"Hast du schon gegessen?","en":"Have you eaten already?"},{"de":"Ravi ist nach Potsdam gefahren.","en":"Ravi went to Potsdam."},{"de":"Ich habe dich gestern angerufen.","en":"I called you yesterday."},{"de":"Leila hat in Teheran Medizin studiert.","en":"Leila studied medicine in Tehran."},{"de":"Was ist passiert?","en":"What happened?"},{"de":"Ich habe die Frage nicht verstanden.","en":"I didn\'t understand the question."},{"de":"Max ist beim Film eingeschlafen.","en":"Max fell asleep during the film."},{"de":"Seid ihr schon mal geflogen?","en":"Have you ever flown?"},{"de":"Was hast du am Wochenende gemacht?","en":"What did you do at the weekend?"},{"de":"Ich bin zu Hause geblieben.","en":"I stayed at home."},{"de":"Hast du schon mal Sushi gegessen?","en":"Have you ever eaten sushi?"},{"de":"Ich habe meinen Schlüssel verloren.","en":"I\'ve lost my key."},{"de":"Wir sind am Samstag gewandert.","en":"We went hiking on Saturday."},{"de":"Sie hat eine E-Mail von ihrem Chef bekommen.","en":"She got an email from her boss."},{"de":"Er ist noch nie geflogen.","en":"He has never flown."},{"de":"Wann bist du nach Hause gekommen?","en":"When did you get home?"},{"de":"Ich habe es vergessen. Entschuldigung!","en":"I forgot it. Sorry!"},{"de":"Gestern hat es den ganzen Tag geregnet.","en":"Yesterday it rained all day."}],"vocab":[{"de":"gestern / vorgestern","en":"yesterday / day before yesterday"},{"de":"letzte Woche","en":"last week"},{"de":"schon / noch nicht","en":"already / not yet"},{"de":"der Ausflug, ¨e","en":"trip, outing"},{"de":"spazieren gehen","en":"to go for a walk"},{"de":"das Picknick, -s","en":"picnic"},{"de":"der See, -n","en":"lake"},{"de":"passieren","en":"to happen"},{"de":"erleben","en":"to experience"},{"de":"fotografieren","en":"to take photos"},{"de":"grillen","en":"to barbecue"},{"de":"Spaß machen","en":"to be fun"},{"de":"das Wochenende, -n","en":"weekend"},{"de":"der Strand, ¨e","en":"beach"},{"de":"das Wetter","en":"weather"},{"de":"der Regen","en":"rain"},{"de":"die Sonne","en":"sun"},{"de":"wandern","en":"to hike"},{"de":"schwimmen","en":"to swim"},{"de":"besichtigen","en":"to visit (sights)"},{"de":"treffen (getroffen)","en":"to meet"},{"de":"bleiben (geblieben)","en":"to stay"},{"de":"schreiben (geschrieben)","en":"to write"},{"de":"finden (gefunden)","en":"to find"},{"de":"vergessen (vergessen)","en":"to forget"},{"de":"verlieren (verloren)","en":"to lose"},{"de":"bekommen (bekommen)","en":"to receive"},{"de":"einschlafen (eingeschlafen)","en":"to fall asleep"},{"de":"zum ersten Mal","en":"for the first time"},{"de":"noch nie","en":"never (yet)"}],"reading":"Letztes Wochenende hat Ravi viel erlebt. Am Samstag ist er früh aufgestanden und mit Leila und Jonas nach Potsdam gefahren. Sie haben ein Picknick am See gemacht und viel fotografiert. Jonas hat Würstchen gegrillt, aber Ravi hat nur Gemüse gegessen. Am Nachmittag sind sie im Park spazieren gegangen. Am Sonntag hat Ravi seine Eltern angerufen und ihnen alles erzählt. Am Abend ist er vor dem Fernseher eingeschlafen.","tasks":[{"q":"Ich ___ gestern Fußball ___. (spielen)","a":"habe / gespielt"},{"q":"Wir ___ nach Hamburg ___. (fahren)","a":"sind / gefahren"},{"q":"Anna ___ ein Buch ___. (lesen)","a":"hat / gelesen"},{"q":"___ du schon ___? (frühstücken)","a":"Hast / gefrühstückt"},{"q":"Er ___ um 6 Uhr ___. (aufstehen)","a":"ist / aufgestanden"},{"q":"Ich ___ im Supermarkt ___. (einkaufen)","a":"habe / eingekauft"},{"q":"Sie ___ in Köln ___. (studieren)","a":"hat / studiert"},{"q":"[Mix] Ich ___ meiner Mutter Blumen ___. (schenken)","a":"habe / geschenkt"},{"q":"[Mix] Wir ___ in den Park ___. (gehen)","a":"sind / gegangen"},{"q":"[Mix] Wo hast du den Schlüssel hingelegt? – Ich habe ihn auf ___ Tisch gelegt.","a":"den"},{"q":"Wir ___ ins Kino ___. (gehen)","a":"sind / gegangen"},{"q":"Ich ___ einen Brief ___. (schreiben)","a":"habe / geschrieben"},{"q":"Er ___ lange ___. (schlafen)","a":"hat / geschlafen"},{"q":"___ du deinen Schlüssel ___? (finden)","a":"Hast / gefunden"},{"q":"Sie ___ zu Hause ___. (bleiben)","a":"ist / geblieben"},{"q":"Ich ___ mein Handy ___. (verlieren)","a":"habe / verloren"},{"q":"Wann ___ ihr ___? (aufstehen)","a":"seid / aufgestanden"},{"q":"Partizip II: einkaufen →","a":"eingekauft"},{"q":"Partizip II: verstehen →","a":"verstanden"},{"q":"Fehler? „Ich habe nach Berlin gefahren.“","a":"Ich bin nach Berlin gefahren."}],"exam":[{"q":"Wohin ist Ravi am Samstag gefahren?","a":"Nach Potsdam."},{"q":"Was hat Jonas gemacht?","a":"Er hat Würstchen gegrillt."},{"q":"Wen hat Ravi am Sonntag angerufen?","a":"Seine Eltern."},{"q":"Perfekt: Ich trinke Kaffee.","a":"Ich habe Kaffee getrunken."},{"q":"Perfekt: Er kommt spät nach Hause.","a":"Er ist spät nach Hause gekommen."},{"q":"Perfekt: Wir verstehen alles.","a":"Wir haben alles verstanden."},{"q":"haben oder sein? Ich ___ zu Hause geblieben.","a":"bin"},{"q":"Was haben Sie letztes Wochenende gemacht? (8 Sätze)","a":"","m":"Letztes Wochenende habe ich viel gemacht. Am Samstag bin ich früh aufgestanden. Ich habe eingekauft und dann gekocht. Am Nachmittag habe ich Freunde besucht. Wir sind spazieren gegangen. Am Abend haben wir zusammen gegessen. Am Sonntag habe ich lange geschlafen. Danach habe ich Deutsch gelernt."},{"q":"Erzählen Sie von Ihrer schönsten Reise.","a":"","m":"Meine schönste Reise war nach Kerala. Ich bin mit meiner Familie geflogen. Wir haben am Strand gewohnt und viel Fisch gegessen. Wir sind mit einem Boot gefahren. Das war wunderbar."},{"q":"Was haben Sie in Deutschland zum ersten Mal gemacht?","a":"","m":"In Deutschland habe ich zum ersten Mal Schnee gesehen. Ich habe auch zum ersten Mal Sauerkraut gegessen."}],"speak":["Was haben die Leute im Park gemacht? __Der Mann ist gejoggt …__","Erzähl die Geschichte vom Hund: Was ist passiert?","Was hast du gestern gemacht? Mindestens 6 Verben im Perfekt.","Frag deinen Partner: __Bist du schon mal …? Hast du schon mal …?__"],"reading2":{"title":"Ein Wochenende an der Ostsee","text":"Letztes Wochenende ist Leila mit ihrer Familie an die Ostsee gefahren. Am Freitagabend haben sie die Koffer gepackt. Am Samstag sind sie um sieben Uhr losgefahren. Die Fahrt hat drei Stunden gedauert. Ihre Tochter hat im Auto geschlafen. In Warnemünde haben sie zuerst ein Hotel gesucht. Dann sind sie zum Strand gegangen. Das Wasser war kalt, aber Leilas Mann ist trotzdem geschwommen. Leila hat lieber Fotos gemacht. Zum Mittagessen haben sie Fisch gegessen. Am Nachmittag hat es plötzlich geregnet. Sie sind in ein Café gegangen und haben Kuchen bestellt. Am Abend sind sie am Hafen spazieren gegangen und haben die großen Schiffe gesehen. Am Sonntag haben sie ein Museum besichtigt. Auf dem Rückweg hat die Tochter gefragt: „Wann fahren wir wieder ans Meer?“ Leila hat gelacht: „Bald, versprochen!“"},"dialog":[{"who":"Mia","de":"Hallo Tomás! Wie war dein Wochenende?"},{"who":"Tomás","de":"Super! Ich bin mit Freunden nach Dresden gefahren."},{"who":"Mia","de":"Oh, schön! Was habt ihr gemacht?"},{"who":"Tomás","de":"Wir haben die Altstadt besichtigt und sind an der Elbe spazieren gegangen."},{"who":"Mia","de":"Und das Wetter?"},{"who":"Tomás","de":"Am Samstag hat die Sonne geschienen, am Sonntag hat es geregnet."},{"who":"Mia","de":"Habt ihr auch etwas Typisches gegessen?"},{"who":"Tomás","de":"Ja, ich habe zum ersten Mal Eierschecke probiert. Ein sächsischer Kuchen. Sehr lecker!"},{"who":"Mia","de":"Und ich? Ich habe das ganze Wochenende für meine Prüfung gelernt."}],"dq":[{"q":"Wohin ist Tomás gefahren?","a":"Nach Dresden."},{"q":"Wie war das Wetter am Sonntag?","a":"Es hat geregnet."},{"q":"Was hat Mia am Wochenende gemacht?","a":"Sie hat für ihre Prüfung gelernt."}],"en":{"title":"The perfect tense (Perfekt)","theme":"Experiences and weekends","expl":["The **Perfekt** is the most important past tense in speech. Form: **haben/sein** (position 2) + **past participle** (end).","Participles: regular **ge-…-t** (gemacht, gekauft); irregular **ge-…-en**, often with a vowel change (gegessen, getrunken, geschrieben). Separable verbs put **ge** in the middle: __aufgestanden, eingekauft__.","No ge-: verbs ending in -ieren (__studiert, telefoniert__) and verbs with be-, ver-, er-, ent- (__besucht, verstanden__).","**sein** for movement from A to B and change of state (gehen, fahren, kommen, aufstehen, einschlafen, werden) and for sein and bleiben: __Ich bin geblieben.__ Everything else uses haben."],"use":""},"check":[{"re":"\\\\b(habe|hast|hat|haben|habt|bin|bist|ist|sind|seid)\\\\b.*\\\\b(ge\\\\w+(t|en)|\\\\w+iert|be\\\\w+t|ver\\\\w+(t|en))\\\\b","label":"Perfekt: haben/sein + Partizip II"}]},{"n":18,"pos":19,"level":"A2","title":"Präteritum von sein, haben und Modalverben","theme":"Früher und heute","scene":"family","rec":[1,8,11,17],"expl":["Beim Sprechen benutzt man für **sein, haben** und **Modalverben** fast immer das **Präteritum** (nicht das Perfekt): __Ich **war** krank.__ (statt: Ich bin krank gewesen.)","**sein:** war, warst, war, waren, wart, waren. **haben:** hatte, hattest, hatte, hatten, hattet, hatten.","**Modalverben:** Stamm ohne Umlaut + **-te**: konnte, musste, durfte, wollte, sollte. **möchten → wollte**.","Auch häufig: **es gab** (there was), **wusste** (wissen)."],"use":"Über die Kindheit, früher und heute sprechen; Entschuldigungen: __Ich konnte nicht kommen, ich hatte keine Zeit.__","table":[["Person","sein","haben","können","müssen","wollen","dürfen"],["ich","war","hatte","konnte","musste","wollte","durfte"],["du","warst","hattest","konntest","musstest","wolltest","durftest"],["er/sie/es","war","hatte","konnte","musste","wollte","durfte"],["wir","waren","hatten","konnten","mussten","wollten","durften"],["ihr","wart","hattet","konntet","musstet","wolltet","durftet"],["sie/Sie","waren","hatten","konnten","mussten","wollten","durften"]],"examples":[{"de":"Gestern war ich müde.","en":"Yesterday I was tired."},{"de":"Als Kind hatte ich einen Hund.","en":"As a child I had a dog."},{"de":"Ich konnte nicht kommen.","en":"I couldn\'t come."},{"de":"Wir mussten lange warten.","en":"We had to wait a long time."},{"de":"Früher wollte ich Pilot werden.","en":"I used to want to be a pilot."},{"de":"Als Kinder durften wir nicht allein ausgehen.","en":"As children we weren\'t allowed out alone."},{"de":"Wo warst du?","en":"Where were you?"},{"de":"Früher gab es kein Internet.","en":"In the past there was no internet."},{"de":"Hattet ihr einen schönen Urlaub?","en":"Did you have a nice holiday?"},{"de":"Ich wusste das nicht.","en":"I didn\'t know that."},{"de":"Als Kind war ich sehr schüchtern.","en":"As a child I was very shy."},{"de":"Früher hatten wir keinen Fernseher.","en":"We didn\'t have a TV in the past."},{"de":"Ich musste jeden Tag zu Fuß zur Schule gehen.","en":"I had to walk to school every day."},{"de":"Wir durften abends nicht lange draußen bleiben.","en":"We weren\'t allowed to stay outside long in the evening."},{"de":"Er wollte Pilot werden.","en":"He wanted to become a pilot."},{"de":"Konntest du schon mit fünf Jahren lesen?","en":"Could you already read at five?"},{"de":"Damals gab es keine Handys.","en":"Back then there were no mobile phones."},{"de":"Wo warst du gestern?","en":"Where were you yesterday?"},{"de":"Ihr wart sehr laut!","en":"You (pl.) were very loud!"},{"de":"Meine Oma hatte einen großen Garten.","en":"My grandma had a big garden."}],"vocab":[{"de":"früher","en":"in the past"},{"de":"heute","en":"today, nowadays"},{"de":"die Kindheit","en":"childhood"},{"de":"als Kind","en":"as a child"},{"de":"die Schule, -n","en":"school"},{"de":"der Lehrer, -","en":"teacher"},{"de":"streng","en":"strict"},{"de":"das Dorf, ¨er","en":"village"},{"de":"die Großstadt, ¨e","en":"big city"},{"de":"es gab","en":"there was / were"},{"de":"werden (wurde)","en":"to become"},{"de":"damals","en":"back then"},{"de":"war (sein)","en":"was"},{"de":"hatte (haben)","en":"had"},{"de":"konnte (können)","en":"could"},{"de":"musste (müssen)","en":"had to"},{"de":"wollte (wollen)","en":"wanted"},{"de":"durfte (dürfen)","en":"was allowed to"},{"de":"sollte (sollen)","en":"was supposed to"},{"de":"das Spielzeug, -e","en":"toy"},{"de":"der Spielplatz, ¨e","en":"playground"},{"de":"der Kindergarten, ¨","en":"nursery school"},{"de":"die Hausaufgaben (Pl.)","en":"homework"},{"de":"der Fernseher, -","en":"TV set"},{"de":"das Handy, -s","en":"mobile phone"},{"de":"der Brief, -e","en":"letter"},{"de":"schüchtern","en":"shy"},{"de":"frech","en":"cheeky"},{"de":"früher war alles anders","en":"everything used to be different"},{"de":"heutzutage","en":"nowadays"}],"reading":"Ravis Vater erzählt am Telefon: „Früher war alles anders. Als Kind hatte ich kein eigenes Zimmer. Wir waren sechs Kinder. Wir wollten immer draußen spielen, aber wir mussten zuerst unseren Eltern helfen. Es gab kein Handy und keinen Fernseher. Mein Lehrer war sehr streng. Ich durfte nie zu spät kommen.“ Ravi sagt: „Heute habe ich ein Handy, eine Wohnung und keine strengen Lehrer. Aber ich konnte als Kind auch nicht so viel spielen!“","tasks":[{"q":"Gestern ___ ich krank. (sein)","a":"war"},{"q":"Wir ___ keine Zeit. (haben)","a":"hatten"},{"q":"Ich ___ nicht kommen. (können)","a":"konnte"},{"q":"Er ___ lange arbeiten. (müssen)","a":"musste"},{"q":"___ du gestern im Kurs? (sein)","a":"Warst"},{"q":"Als Kind ___ ich nicht fernsehen. (dürfen)","a":"durfte"},{"q":"Ihr ___ ins Kino gehen, oder? (wollen)","a":"wolltet"},{"q":"[Mix] Früher ___ es hier keinen Supermarkt. (geben)","a":"gab"},{"q":"[Mix] Letztes Jahr ___ ich nach Indien geflogen.","a":"bin"},{"q":"[Mix] Als Kind ___ meine Schwester ___ Katze. (haben, eine)","a":"hatte / eine"},{"q":"Präteritum: Ich ___ gestern krank. (sein)","a":"war"},{"q":"Präteritum: Wir ___ keine Zeit. (haben)","a":"hatten"},{"q":"Präteritum: Du ___ nicht kommen. (können)","a":"konntest"},{"q":"Präteritum: Er ___ lange arbeiten. (müssen)","a":"musste"},{"q":"Präteritum: Ihr ___ ins Kino gehen. (wollen)","a":"wolltet"},{"q":"Präteritum: Sie (Pl.) ___ nicht rauchen. (dürfen)","a":"durften"},{"q":"Präteritum: ___ du gestern zu Hause? (sein)","a":"Warst"},{"q":"Präteritum: Ich ___ eine Katze. (haben)","a":"hatte"},{"q":"Präteritum: Damals ___ es kein Internet. (es gibt)","a":"gab"},{"q":"Fehler? „Als Kind ich war schüchtern.“","a":"Als Kind war ich schüchtern."}],"exam":[{"q":"Wie viele Kinder waren sie in der Familie von Ravis Vater?","a":"Sechs."},{"q":"Was mussten die Kinder zuerst machen?","a":"Den Eltern helfen."},{"q":"Wie war der Lehrer?","a":"Sehr streng."},{"q":"Präteritum: Ich bin im Urlaub.","a":"Ich war im Urlaub."},{"q":"Präteritum: Wir müssen früh aufstehen.","a":"Wir mussten früh aufstehen."},{"q":"Präteritum: Hast du Glück?","a":"Hattest du Glück?"},{"q":"Präteritum: Sie können gut schwimmen.","a":"Sie konnten gut schwimmen."},{"q":"Wie war Ihre Kindheit? Was durften / mussten Sie machen?","a":"","m":"Meine Kindheit war schön. Wir hatten ein großes Haus. Ich musste viel für die Schule lernen. Ich durfte nicht lange draußen spielen. Am Sonntag konnten wir ins Kino gehen."},{"q":"Früher und heute: Was ist in Ihrer Stadt anders?","a":"","m":"Früher war meine Stadt klein. Es gab nur wenige Autos. Heute ist die Stadt groß und laut. Früher hatten wir keinen Supermarkt, heute gibt es viele."},{"q":"Sie waren nicht im Kurs. Entschuldigen Sie sich und erklären Sie warum.","a":"","m":"Liebe Frau Krüger, es tut mir leid, ich war gestern nicht im Kurs. Ich war krank und musste zum Arzt gehen. Ich hole die Aufgaben nach."}],"speak":["Stell dir vor, das ist die Familie vor 30 Jahren. Wie war das Leben?","Was durftest du als Kind nicht? Was musstest du machen?","Vergleiche: __Früher hatten wir … heute haben wir …__","Was wolltest du als Kind werden?"],"reading2":{"title":"Früher und heute","text":"Ravis Großvater erzählt gern von früher. „Als ich ein Kind war, hatten wir kein Auto und keinen Fernseher. Unser Dorf war klein. Es gab nur eine Schule, einen Laden und einen Tempel. Ich musste jeden Morgen um fünf Uhr aufstehen und meinem Vater auf dem Feld helfen. Danach ging ich zu Fuß zur Schule, vier Kilometer! Wir durften im Unterricht nicht sprechen. Die Lehrer waren sehr streng. Am Abend wollte ich spielen, aber ich musste Hausaufgaben machen. Wir hatten kein Licht, nur eine Öllampe.“ Ravi hört zu und denkt an seine Kindheit in Mumbai. Er hatte schon einen Computer, und er konnte mit dem Bus zur Schule fahren. Heute ist alles noch einmal anders: Seine Nichte hat mit acht Jahren schon ein Handy. „Früher war das Leben schwer“, sagt der Großvater, „aber wir waren auch glücklich.“"},"dialog":[{"who":"Paul","de":"Mama, wie war es früher in der Schule?"},{"who":"Anna","de":"Ach, ganz anders. Wir hatten keine Computer im Klassenzimmer."},{"who":"Paul","de":"Echt? Und wie konntet ihr dann lernen?"},{"who":"Anna","de":"Mit Büchern und Heften. Wir mussten viel schreiben."},{"who":"Paul","de":"Durftet ihr Handys mitnehmen?"},{"who":"Anna","de":"Es gab noch keine Handys! Wir hatten nur ein Telefon zu Hause."},{"who":"Paul","de":"Und was wolltest du als Kind werden?"},{"who":"Anna","de":"Ich wollte Tierärztin werden. Ich hatte zwei Katzen und einen Hasen."}],"dq":[{"q":"Was gab es früher nicht im Klassenzimmer?","a":"Computer."},{"q":"Was hatte Anna zu Hause zum Telefonieren?","a":"Nur ein Telefon (zu Hause)."},{"q":"Was wollte Anna als Kind werden?","a":"Tierärztin."}],"en":{"title":"Simple past of sein, haben and modal verbs","theme":"Then and now","expl":["When speaking, Germans use the **simple past (Präteritum)** – not the Perfekt – for sein, haben and the modal verbs: __Ich war krank.__ (instead of \\"Ich bin krank gewesen\\").","sein: **war, warst, war, waren, wart, waren**. haben: **hatte, hattest, hatte, hatten, hattet, hatten**.","Modal verbs: stem without umlaut + -te: __konnte, musste, durfte, wollte, sollte__ (and möchten → __wollte__ in the past)."],"use":""},"check":[{"re":"\\\\b(war|warst|waren|wart|hatte|hattest|hatten|konnte|musste|durfte|wollte|sollte|konnten|mussten|durften|wollten)\\\\b","label":"Präteritum: war, hatte, konnte, musste …"}]},{"n":19,"pos":20,"level":"A2","title":"Reflexive Verben","theme":"Gesundheit und Körper","scene":"doctor","rec":[12,13,17,18],"expl":["Bei **reflexiven Verben** zeigt ein **Reflexivpronomen** zurück auf das Subjekt: __Ich wasche **mich**.__","**Akkusativ** (normal): mich, dich, **sich**, uns, euch, **sich**.","**Dativ**, wenn es schon ein Akkusativ-Objekt gibt: __Ich wasche **mir** die Hände. Ich putze **mir** die Zähne.__ (mir, dir, sich, uns, euch, sich)","Viele reflexive Verben haben eine feste **Präposition**: sich freuen **auf/über**, sich interessieren **für**, sich ärgern **über**, sich kümmern **um**. Im Perfekt immer **haben**: __Ich habe mich gefreut.__"],"use":"Gefühle, Körperpflege, Gesundheit, Interessen ausdrücken.","table":[["Person","Akkusativ","Dativ","Beispiel"],["ich","mich","mir","Ich ziehe **mich** an. / Ich ziehe **mir** die Jacke an."],["du","dich","dir","Beeil **dich**! / Wasch **dir** die Hände!"],["er/sie/es","sich","sich","Er rasiert **sich**."],["wir","uns","uns","Wir treffen **uns** um 8."],["ihr","euch","euch","Habt ihr **euch** erholt?"],["sie/Sie","sich","sich","Setzen Sie **sich** bitte!"]],"examples":[{"de":"Ich fühle mich nicht gut.","en":"I don\'t feel well."},{"de":"Du musst dich ausruhen.","en":"You must rest."},{"de":"Ich putze mir zweimal am Tag die Zähne.","en":"I brush my teeth twice a day."},{"de":"Ravi hat sich erkältet.","en":"Ravi has caught a cold."},{"de":"Wir freuen uns auf den Urlaub.","en":"We\'re looking forward to the holiday."},{"de":"Interessierst du dich für Sport?","en":"Are you interested in sport?"},{"de":"Setzen Sie sich bitte!","en":"Please sit down."},{"de":"Ich habe mich über das Geschenk gefreut.","en":"I was happy about the present."},{"de":"Beeil dich, der Bus kommt!","en":"Hurry up, the bus is coming!"},{"de":"Er kümmert sich um seine Mutter.","en":"He takes care of his mother."},{"de":"Ich fühle mich heute nicht gut.","en":"I don\'t feel well today."},{"de":"Wir treffen uns um acht vor dem Kino.","en":"We\'ll meet at eight in front of the cinema."},{"de":"Er hat sich beim Fußball verletzt.","en":"He hurt himself playing football."},{"de":"Setz dich bitte!","en":"Please sit down!"},{"de":"Beeil dich, der Zug fährt gleich!","en":"Hurry up, the train is about to leave!"},{"de":"Ich putze mir die Zähne.","en":"I brush my teeth."},{"de":"Kannst du dich nicht konzentrieren?","en":"Can\'t you concentrate?"},{"de":"Sie freut sich auf den Urlaub.","en":"She is looking forward to the holiday."},{"de":"Mach dir keine Sorgen!","en":"Don\'t worry!"},{"de":"Ihr müsst euch mehr bewegen.","en":"You (pl.) need to exercise more."}],"vocab":[{"de":"sich fühlen","en":"to feel"},{"de":"sich erkälten","en":"to catch a cold"},{"de":"sich ausruhen","en":"to rest"},{"de":"sich waschen","en":"to wash (oneself)"},{"de":"sich die Zähne putzen","en":"to brush one\'s teeth"},{"de":"sich anziehen","en":"to get dressed"},{"de":"sich beeilen","en":"to hurry"},{"de":"sich freuen auf / über","en":"to look forward to / be happy about"},{"de":"sich interessieren für","en":"to be interested in"},{"de":"sich ärgern über","en":"to be annoyed about"},{"de":"sich kümmern um","en":"to take care of"},{"de":"sich erholen","en":"to recover"},{"de":"sich setzen","en":"to sit down"},{"de":"sich treffen","en":"to meet (each other)"},{"de":"sich duschen","en":"to shower"},{"de":"sich kämmen","en":"to comb one\'s hair"},{"de":"sich rasieren","en":"to shave"},{"de":"sich schminken","en":"to put on make-up"},{"de":"sich verletzen","en":"to injure oneself"},{"de":"sich bewegen","en":"to move, to exercise"},{"de":"sich entspannen","en":"to relax"},{"de":"sich konzentrieren","en":"to concentrate"},{"de":"sich langweilen","en":"to be bored"},{"de":"sich verspäten","en":"to be late"},{"de":"sich unterhalten","en":"to chat"},{"de":"sich verlieben","en":"to fall in love"},{"de":"sich Sorgen machen","en":"to worry"},{"de":"die Gesundheit","en":"health"},{"de":"der Körper, -","en":"body"},{"de":"die Erkältung, -en","en":"cold"}],"reading":"Nach dem Ausflug hat sich Ravi erkältet. Er fühlt sich schlecht und muss sich ausruhen. Die Ärztin sagt: „Setzen Sie sich bitte. Waschen Sie sich oft die Hände und ziehen Sie sich warm an.“ Ravi ärgert sich: Am Samstag wollte er zum Konzert gehen. Er hatte sich so darauf gefreut! Aber Leila kümmert sich um ihn und bringt ihm Tee. Nach vier Tagen hat er sich erholt und freut sich auf das nächste Wochenende.","tasks":[{"q":"Ich fühle ___ nicht gut.","a":"mich"},{"q":"Wasch ___ die Hände! (du)","a":"dir"},{"q":"Er hat ___ erkältet.","a":"sich"},{"q":"Wir treffen ___ im Café.","a":"uns"},{"q":"Ich putze ___ die Zähne.","a":"mir"},{"q":"Interessierst du ___ für Musik?","a":"dich"},{"q":"Setzen Sie ___!","a":"sich"},{"q":"[Mix] Perfekt: Ich freue mich über den Brief.","a":"Ich habe mich über den Brief gefreut."},{"q":"[Mix] Ihr müsst ___ beeilen!","a":"euch"},{"q":"[Mix] Imperativ (du): sich warm anziehen","a":"Zieh dich warm an!"},{"q":"Ich wasche ___. (mich/mir)","a":"mich"},{"q":"Ich wasche ___ die Hände. (mich/mir)","a":"mir"},{"q":"Du musst ___ beeilen.","a":"dich"},{"q":"Er rasiert ___ jeden Morgen.","a":"sich"},{"q":"Wir treffen ___ morgen.","a":"uns"},{"q":"Habt ihr ___ gut erholt?","a":"euch"},{"q":"Ich putze ___ die Zähne.","a":"mir"},{"q":"Sie interessiert ___ für Musik.","a":"sich"},{"q":"Freust du ___ auf das Wochenende?","a":"dich"},{"q":"Fehler? „Ich fühle mir nicht gut.“","a":"Ich fühle mich nicht gut."}],"exam":[{"q":"Warum geht Ravi zur Ärztin?","a":"Er hat sich erkältet."},{"q":"Warum ärgert sich Ravi?","a":"Er kann nicht zum Konzert gehen."},{"q":"Wer kümmert sich um Ravi?","a":"Leila."},{"q":"Ergänze: Ich ziehe ___ die Schuhe an.","a":"mir"},{"q":"Ergänze: Anna freut ___ ___ den Sommer.","a":"sich / auf"},{"q":"Ergänze: Kümmerst du ___ ___ die Katze?","a":"dich / um"},{"q":"Perfekt: Wir erholen uns gut.","a":"Wir haben uns gut erholt."},{"q":"Was machen Sie, wenn Sie sich nicht gut fühlen?","a":"","m":"Wenn ich mich nicht gut fühle, lege ich mich ins Bett. Ich ruhe mich aus und trinke Tee. Manchmal erkälte ich mich im Winter."},{"q":"Worauf freuen Sie sich? Worüber ärgern Sie sich?","a":"","m":"Ich freue mich auf den Urlaub. Ich ärgere mich über den Verkehr und über lange Wartezeiten."},{"q":"Wofür interessieren Sie sich? Erzählen Sie.","a":"","m":"Ich interessiere mich für Musik und Technik. Ich interessiere mich auch für Geschichte und lese viel darüber."}],"speak":["Wie fühlt sich der Patient? Was sagt die Ärztin?","Was macht man jeden Morgen? __Ich wasche mich, ich putze mir …__","Worüber freust du dich diese Woche?","Rollenspiel beim Arzt: __Ich fühle mich … Ich habe mich …__"],"reading2":{"title":"Gesund durch den Winter","text":"Im Winter erkälten sich viele Menschen. Wie kann man sich schützen? Die Krankenkasse gibt Tipps. Bewegen Sie sich jeden Tag an der frischen Luft, auch bei Kälte. Ziehen Sie sich warm an und vergessen Sie Mütze und Schal nicht. Waschen Sie sich oft die Hände, besonders nach der U-Bahn. Ernähren Sie sich gesund mit viel Obst und Gemüse. Schlafen Sie genug, denn im Schlaf erholt sich der Körper. Stress ist auch ein Problem: Wer sich ständig ärgert oder sich Sorgen macht, wird schneller krank. Nehmen Sie sich also Zeit für sich. Treffen Sie sich mit Freunden, lesen Sie ein Buch oder entspannen Sie sich in der Sauna. Und wenn Sie sich doch krank fühlen? Dann ruhen Sie sich aus und bleiben Sie zu Hause. So stecken Sie Ihre Kollegen nicht an."},"dialog":[{"who":"Leila","de":"Hallo Jonas, was ist los? Du siehst müde aus."},{"who":"Jonas","de":"Ich fühle mich nicht so gut. Ich glaube, ich habe mich erkältet."},{"who":"Leila","de":"Oh je. Hast du Fieber?"},{"who":"Jonas","de":"Nein, aber Halsschmerzen. Und ich kann mich nicht konzentrieren."},{"who":"Leila","de":"Dann geh nach Hause und ruh dich aus!"},{"who":"Jonas","de":"Ich kann nicht. Ich muss mich noch um das Projekt kümmern."},{"who":"Leila","de":"Das Projekt kann warten. Du musst dich erholen."},{"who":"Jonas","de":"Du hast recht. Ich melde mich beim Chef ab."}],"dq":[{"q":"Wie fühlt sich Jonas?","a":"Nicht gut, er hat sich erkältet."},{"q":"Welche Beschwerden hat er?","a":"Halsschmerzen, er kann sich nicht konzentrieren."},{"q":"Was macht Jonas am Ende?","a":"Er meldet sich beim Chef ab (und geht nach Hause)."}],"en":{"title":"Reflexive verbs","theme":"Health and the body","expl":["With reflexive verbs a **reflexive pronoun** points back to the subject: __Ich wasche mich.__ = I wash (myself).","Normally accusative: **mich, dich, sich, uns, euch, sich**. If there is already an accusative object, use the dative: __Ich wasche mir die Hände. Ich putze mir die Zähne.__ (mir, dir, sich, uns, euch, sich)","Many reflexive verbs have a fixed preposition: sich freuen auf/über, sich interessieren für, sich ärgern über, sich erinnern an."],"use":""},"check":[{"re":"\\\\b(mich|dich|sich|uns|euch|mir|dir)\\\\b","label":"a reflexive pronoun (mich, dich, sich …)"}]},{"n":20,"pos":21,"level":"A2","title":"Konjunktionen: und, aber, oder, denn, sondern","theme":"Freizeit und Meinung","scene":"park","rec":[3,7,17,19],"expl":["Diese Konjunktionen stehen auf **Position 0** – sie zählen nicht mit. Danach kommt ein **normaler Hauptsatz** (Verb auf Position 2).","**und** (and), **aber** (but), **oder** (or), **denn** (because – wie weil, aber mit Hauptsatz!), **sondern** (but rather – nur nach Negation).","Vor aber, denn, sondern steht ein **Komma**. Bei und/oder kann das Subjekt wegfallen: __Ich gehe nach Hause und (ich) koche.__","Merke **ADUSO**: aber, denn, und, sondern, oder."],"use":"Sätze verbinden, Gründe geben, Kontraste zeigen – mehr Punkte für „Kohärenz“ in der Prüfung.","table":[["Satz 1","Pos. 0","Pos. 1","Pos. 2","Rest"],["Ich bleibe zu Hause,","denn","ich","bin","krank."],["Ich mag Tee,","aber","Kaffee","trinke","ich nicht."],["Gehen wir ins Kino","oder","bleiben","wir","zu Hause? (Frage)"],["Er fährt nicht mit dem Bus,","sondern","er","geht","zu Fuß."],["Ich koche","und","du","deckst","den Tisch."]],"examples":[{"de":"Ich gehe joggen, denn ich will fit bleiben.","en":"I go jogging because I want to stay fit."},{"de":"Das Wetter ist schön, aber es ist kalt.","en":"The weather is nice but it\'s cold."},{"de":"Spielen wir Tennis oder gehen wir schwimmen?","en":"Shall we play tennis or go swimming?"},{"de":"Ich wohne nicht in München, sondern in Berlin.","en":"I don\'t live in Munich but in Berlin."},{"de":"Ravi kocht und Leila macht den Salat.","en":"Ravi cooks and Leila makes the salad."},{"de":"Ich habe keine Zeit, denn ich muss arbeiten.","en":"I have no time because I have to work."},{"de":"Er ist müde, aber er geht noch ins Kino.","en":"He\'s tired but still goes to the cinema."},{"de":"Wir sind nicht gefahren, sondern (wir sind) gelaufen.","en":"We didn\'t drive, we walked."},{"de":"Ich mag Yoga, denn es entspannt mich.","en":"I like yoga because it relaxes me."},{"de":"Möchtest du Wasser oder lieber Saft?","en":"Would you like water or rather juice?"},{"de":"Ich gehe gern schwimmen, aber ich mag kein Tennis.","en":"I like swimming, but I don\'t like tennis."},{"de":"Wir fahren nicht ans Meer, sondern in die Berge.","en":"We\'re not going to the sea but to the mountains."},{"de":"Er bleibt zu Hause, denn er ist müde.","en":"He\'s staying at home because he is tired."},{"de":"Möchtest du Fußball spielen oder ins Kino gehen?","en":"Would you like to play football or go to the cinema?"},{"de":"Sie trainiert dreimal pro Woche und spielt am Wochenende.","en":"She trains three times a week and plays at weekends."},{"de":"Das Konzert war nicht langweilig, sondern total spannend.","en":"The concert wasn\'t boring but really exciting."},{"de":"Ich komme mit, aber ich habe nur eine Stunde Zeit.","en":"I\'ll come along, but I only have an hour."},{"de":"Meiner Meinung nach ist Yoga sehr gesund.","en":"In my opinion yoga is very healthy."},{"de":"Ich finde Museen langweilig.","en":"I find museums boring."},{"de":"Lieber gehe ich ins Theater.","en":"I\'d rather go to the theatre."}],"vocab":[{"de":"die Freizeit","en":"free time"},{"de":"das Fitnessstudio, -s","en":"gym"},{"de":"joggen","en":"to jog"},{"de":"das Yoga","en":"yoga"},{"de":"wandern","en":"to hike"},{"de":"fit / entspannt","en":"fit / relaxed"},{"de":"die Mannschaft, -en","en":"team"},{"de":"der Verein, -e","en":"club"},{"de":"das Konzert, -e","en":"concert"},{"de":"langweilig / spannend","en":"boring / exciting"},{"de":"lieber","en":"rather"},{"de":"die Meinung, -en","en":"opinion"},{"de":"und","en":"and"},{"de":"aber","en":"but"},{"de":"oder","en":"or"},{"de":"denn","en":"because, for"},{"de":"sondern","en":"but (rather)"},{"de":"die Sportart, -en","en":"type of sport"},{"de":"der Tennisschläger, -","en":"tennis racket"},{"de":"das Schwimmbad, ¨er","en":"swimming pool"},{"de":"das Training","en":"training"},{"de":"trainieren","en":"to train"},{"de":"gewinnen","en":"to win"},{"de":"verlieren","en":"to lose"},{"de":"das Spiel, -e","en":"game, match"},{"de":"der Fan, -s","en":"fan"},{"de":"der Ausflug, ¨e","en":"trip"},{"de":"das Theater, -","en":"theatre"},{"de":"die Ausstellung, -en","en":"exhibition"},{"de":"das Gesellschaftsspiel, -e","en":"board game"}],"reading":"Ravi und Leila sprechen über ihre Freizeit. Ravi joggt dreimal pro Woche, denn er will fit bleiben. Er möchte auch in einen Cricket-Verein gehen, aber in Berlin gibt es nicht viele. Leila macht kein Joggen, sondern Yoga. Sie sagt: „Yoga ist nicht langweilig, sondern sehr entspannend.“ Am Wochenende wandern sie zusammen oder sie gehen auf ein Konzert. Letzten Samstag waren sie im Konzert, aber Ravi ist fast eingeschlafen!","tasks":[{"q":"Ich lerne Deutsch, ___ ich will hier arbeiten.","a":"denn"},{"q":"Das Essen ist gut, ___ teuer.","a":"aber"},{"q":"Trinkst du Tee ___ Kaffee?","a":"oder"},{"q":"Er ist nicht Arzt, ___ Lehrer.","a":"sondern"},{"q":"Verbinde mit denn: Ich bleibe zu Hause. Ich bin müde.","a":"Ich bleibe zu Hause, denn ich bin müde."},{"q":"Verbinde mit aber: Ich möchte kommen. Ich habe keine Zeit.","a":"Ich möchte kommen, aber ich habe keine Zeit."},{"q":"Fehler? „…, denn ich bin müde bin.“","a":"…, denn ich bin müde."},{"q":"[Mix] Ich habe nicht gekocht, ___ ich ___ im Restaurant ___. (sondern, essen – Perfekt)","a":"sondern / habe / gegessen"},{"q":"[Mix] Leila ärgert ___, denn der Bus ___ zu spät. (sich, kommen)","a":"sich / kommt"},{"q":"[Mix] Ich wollte kommen, aber ich ___ nicht. (können, Präteritum)","a":"konnte"},{"q":"Ich trinke Tee, ___ ich mag keinen Kaffee. (aber/denn)","a":"aber"},{"q":"Er geht nicht ins Kino, ___ ins Theater. (aber/sondern)","a":"sondern"},{"q":"Wir bleiben zu Hause, ___ es regnet. (denn/oder)","a":"denn"},{"q":"Spielst du Gitarre ___ Klavier?","a":"oder"},{"q":"Sie ist nicht müde, ___ hungrig.","a":"sondern"},{"q":"Verbinde mit denn: Ich lerne viel. Ich habe eine Prüfung.","a":"Ich lerne viel, denn ich habe eine Prüfung."},{"q":"Verbinde mit aber: Das Hotel ist teuer. Es ist schön.","a":"Das Hotel ist teuer, aber es ist schön."},{"q":"Verbinde mit sondern: Er kommt nicht heute. Er kommt morgen.","a":"Er kommt nicht heute, sondern morgen."},{"q":"Fehler? „Ich bleibe zu Hause, denn ich bin krank bin.“","a":"Ich bleibe zu Hause, denn ich bin krank."},{"q":"Fehler? „Ich komme nicht, denn habe ich keine Zeit.“","a":"Ich komme nicht, denn ich habe keine Zeit."}],"exam":[{"q":"Warum joggt Ravi?","a":"Er will fit bleiben."},{"q":"Was macht Leila?","a":"Yoga."},{"q":"Was ist beim Konzert passiert?","a":"Ravi ist fast eingeschlafen."},{"q":"Verbinde mit sondern: Ich trinke keinen Wein. Ich trinke Saft.","a":"Ich trinke keinen Wein, sondern Saft."},{"q":"Verbinde mit oder: Wir gehen ins Kino. Wir bleiben zu Hause.","a":"Wir gehen ins Kino oder (wir) bleiben zu Hause."},{"q":"Verbinde mit denn: Er kommt nicht. Er ist krank.","a":"Er kommt nicht, denn er ist krank."},{"q":"Ergänze: Das ist nicht mein Handy, ___ deins.","a":"sondern"},{"q":"Was machen Sie in der Freizeit und warum? (mit denn, aber)","a":"","m":"In der Freizeit spiele ich Cricket, denn das macht mir Spaß. Ich lese auch gern, aber ich habe wenig Zeit. Am Wochenende koche ich oder ich treffe Freunde."},{"q":"Ist Sport wichtig für Sie? Begründen Sie Ihre Meinung.","a":"","m":"Ja, Sport ist wichtig für mich, denn er ist gut für die Gesundheit. Ich mache nicht viel Sport, aber ich gehe jeden Tag spazieren."},{"q":"Sie möchten mit Ihrem Partner etwas unternehmen. Machen Sie zwei Vorschläge (oder).","a":"","m":"Wollen wir ins Kino gehen oder wollen wir lieber im Park spazieren gehen? Wir können auch essen gehen oder zu Hause kochen."}],"speak":["Was machen die Leute im Park und warum? (mit denn)","Möchtest du lieber joggen oder auf der Bank sitzen? Warum?","Beschreibe das Bild mit und / aber / oder.","Was ist besser: Sport allein oder in der Gruppe?"],"reading2":{"title":"Freizeit in Deutschland – eine Umfrage","text":"Was machen die Deutschen in ihrer Freizeit? Eine Umfrage zeigt: Fernsehen und Internet sind auf Platz eins. Aber viele Menschen wollen auch aktiv sein. Etwa ein Drittel macht regelmäßig Sport. Sehr beliebt sind Fußball, Radfahren und Schwimmen. Viele Deutsche sind Mitglied in einem Verein, denn dort trifft man Freunde. Es gibt Sportvereine, aber auch Musikvereine, Schachvereine und sogar Kleingartenvereine. Junge Menschen treffen ihre Freunde oft im Café oder im Park, ältere Menschen gehen lieber wandern oder arbeiten im Garten. Am Wochenende machen Familien gern Ausflüge, zum Beispiel in den Zoo oder an einen See. Ins Theater oder in die Oper gehen nicht so viele Menschen, aber Konzerte und Festivals sind sehr populär. Und was ist die Lieblingsbeschäftigung? Nicht Sport, sondern … Schlafen! Viele Befragte sagen: „Am Wochenende will ich mich vor allem ausruhen.“"},"dialog":[{"who":"Tomás","de":"Mia, hast du Lust auf Tennis am Samstag?"},{"who":"Mia","de":"Tennis? Nein, danke. Ich spiele nicht gern Tennis, denn ich bin total schlecht."},{"who":"Tomás","de":"Dann gehen wir schwimmen oder Rad fahren?"},{"who":"Mia","de":"Schwimmen ist gut, aber nicht am Vormittag. Da arbeite ich im Café."},{"who":"Tomás","de":"Kein Problem. Wir gehen am Nachmittag."},{"who":"Mia","de":"Und am Abend? Gehen wir ins Konzert oder bleiben wir zu Hause?"},{"who":"Tomás","de":"Nicht ins Konzert, sondern zu Leila. Sie macht einen Spieleabend."},{"who":"Mia","de":"Oh, super! Ich liebe Gesellschaftsspiele."}],"dq":[{"q":"Warum will Mia nicht Tennis spielen?","a":"Sie ist total schlecht."},{"q":"Wann gehen Mia und Tomás schwimmen?","a":"Am Nachmittag."},{"q":"Was machen sie am Abend?","a":"Sie gehen zu Leilas Spieleabend."}],"en":{"title":"Conjunctions: und, aber, oder, denn, sondern","theme":"Free time and opinions","expl":["These conjunctions are in **position 0** – they don\'t count. After them comes a normal main clause with the verb in position 2: __Ich bleibe zu Hause, denn ich bin müde.__","**und** (and), **aber** (but), **oder** (or), **denn** (because – like weil, but with normal word order), **sondern** (but rather – only after a negation: __nicht Tee, sondern Kaffee__).","Put a comma before aber, denn and sondern. With und/oder you can leave out a repeated subject: __Ich koche und (ich) esse.__"],"use":""},"check":[{"re":"\\\\b(und|aber|oder|denn|sondern)\\\\b","label":"und, aber, oder, denn, sondern"},{"re":",\\\\s*(aber|denn|sondern)\\\\b","label":"a comma before aber / denn / sondern"}]},{"n":21,"pos":22,"level":"A2","title":"Nebensätze mit weil, dass, wenn, ob","theme":"Arbeit und Beruf","scene":"office","rec":[11,17,18,20],"expl":["Im **Nebensatz** steht das **konjugierte Verb am Ende**: __…, **weil** ich müde **bin**.__","**weil** = Grund (because). **dass** = Inhalt nach Verben wie denken, glauben, finden, wissen, hoffen, sagen. **wenn** = Bedingung (if) / Wiederholung (whenever). **ob** = indirekte Ja/Nein-Frage (whether).","Mit Modalverb / Perfekt: Hilfsverb ganz am Ende: __…, weil ich arbeiten **muss** / weil ich lange gearbeitet **habe**.__ Trennbare Verben zusammen: __…, wenn ich früh **aufstehe**.__","**Nebensatz zuerst** → Hauptsatz beginnt mit **Verb**: __Wenn ich Zeit habe, **komme** ich.__"],"use":"In der Prüfung: Meinung (Ich finde, dass…), Gründe (weil…), Bedingungen (wenn…). Sehr wichtig!","table":[["Hauptsatz","Konj.","Subjekt","Mitte","Verb (Ende)"],["Ich komme nicht,","weil","ich","keine Zeit","habe."],["Ich glaube,","dass","er","heute","kommt."],["Ich weiß nicht,","ob","der Chef","heute im Büro","ist."],["Ich rufe dich an,","wenn","ich","morgen früh","aufstehe."],["Ravi ist müde,","weil","er","lange","gearbeitet hat."],["—","Wenn","ich","Zeit","habe, **komme** ich."]],"examples":[{"de":"Ich lerne Deutsch, weil ich hier arbeiten möchte.","en":"I learn German because I\'d like to work here."},{"de":"Ich finde, dass die Arbeit interessant ist.","en":"I think the work is interesting."},{"de":"Wenn ich Zeit habe, gehe ich schwimmen.","en":"When I have time, I go swimming."},{"de":"Weißt du, ob Jonas heute kommt?","en":"Do you know whether Jonas is coming today?"},{"de":"Ravi hofft, dass er die Stelle bekommt.","en":"Ravi hopes he gets the job."},{"de":"Ich bin müde, weil ich spät eingeschlafen bin.","en":"I\'m tired because I fell asleep late."},{"de":"Wenn es regnet, nehme ich die U-Bahn.","en":"If it rains, I take the underground."},{"de":"Die Chefin fragt, ob wir morgen arbeiten können.","en":"The boss asks whether we can work tomorrow."},{"de":"Es ist wichtig, dass man pünktlich ist.","en":"It\'s important to be punctual."},{"de":"Weil der Zug Verspätung hatte, bin ich zu spät gekommen.","en":"Because the train was late, I came late."},{"de":"Ich bewerbe mich, weil die Stelle interessant ist.","en":"I\'m applying because the job is interesting."},{"de":"Ich glaube, dass ich gute Chancen habe.","en":"I think that I have a good chance."},{"de":"Wenn ich die Stelle bekomme, ziehe ich nach München.","en":"If I get the job, I\'ll move to Munich."},{"de":"Ich weiß nicht, ob ich morgen arbeiten muss.","en":"I don\'t know whether I have to work tomorrow."},{"de":"Er kommt nicht, weil er krank ist.","en":"He isn\'t coming because he is ill."},{"de":"Sie sagt, dass das Gehalt gut ist.","en":"She says the salary is good."},{"de":"Kannst du mich anrufen, wenn du Zeit hast?","en":"Can you call me when you have time?"},{"de":"Weißt du, ob die Firma Leute sucht?","en":"Do you know whether the company is looking for people?"},{"de":"Ich hoffe, dass das Vorstellungsgespräch gut läuft.","en":"I hope the interview goes well."},{"de":"Weil ich Erfahrung habe, bekomme ich die Stelle.","en":"Because I have experience, I\'ll get the job."}],"vocab":[{"de":"die Stelle, -n","en":"job, position"},{"de":"sich bewerben","en":"to apply"},{"de":"die Bewerbung, -en","en":"application"},{"de":"das Vorstellungsgespräch, -e","en":"job interview"},{"de":"der Lebenslauf, ¨e","en":"CV"},{"de":"die Erfahrung, -en","en":"experience"},{"de":"verdienen","en":"to earn"},{"de":"das Gehalt, ¨er","en":"salary"},{"de":"die Überstunde, -n","en":"overtime"},{"de":"der Vertrag, ¨e","en":"contract"},{"de":"kündigen","en":"to quit"},{"de":"hoffen","en":"to hope"},{"de":"die Firma, Firmen","en":"company"},{"de":"der Arbeitgeber, -","en":"employer"},{"de":"der Arbeitnehmer, -","en":"employee"},{"de":"die Anzeige, -n","en":"advertisement"},{"de":"die Voraussetzung, -en","en":"requirement"},{"de":"die Kenntnisse (Pl.)","en":"knowledge, skills"},{"de":"die Teamarbeit","en":"teamwork"},{"de":"zuverlässig","en":"reliable"},{"de":"die Arbeitszeit, -en","en":"working hours"},{"de":"der Urlaubstag, -e","en":"day of holiday"},{"de":"die Probezeit","en":"probation period"},{"de":"der Kollege, -n / die Kollegin, -nen","en":"colleague"},{"de":"das Team, -s","en":"team"},{"de":"die Besprechung, -en","en":"meeting"},{"de":"krank sein","en":"to be ill"},{"de":"ob","en":"whether"},{"de":"wissen (weiß)","en":"to know"},{"de":"die Absage, -n","en":"rejection"}],"reading":"Jonas erzählt Ravi, dass er eine neue Stelle sucht. „Ich möchte wechseln, weil ich zu viele Überstunden mache.“ Ravi fragt, ob er schon eine Bewerbung geschrieben hat. „Ja, und ich hoffe, dass ich bald ein Vorstellungsgespräch habe.“ Ravi sagt: „Wenn du Hilfe beim Lebenslauf brauchst, sag Bescheid. Aber ich finde es schade, dass du gehst!“ Jonas lacht: „Keine Sorge. Wenn ich die Stelle bekomme, lade ich dich zum Essen ein.“","tasks":[{"q":"Ich komme nicht, weil ich krank ___. (sein)","a":"bin"},{"q":"Ich glaube, dass er Recht ___. (haben)","a":"hat"},{"q":"Ich weiß nicht, ___ sie verheiratet ist.","a":"ob"},{"q":"___ ich Hunger habe, esse ich.","a":"Wenn"},{"q":"Verbinde mit weil: Ich bleibe zu Hause. Ich muss lernen.","a":"Ich bleibe zu Hause, weil ich lernen muss."},{"q":"Verbinde mit dass: Ich finde. Deutsch ist schwer.","a":"Ich finde, dass Deutsch schwer ist."},{"q":"Verbinde (Nebensatz zuerst): wenn / das Wetter schön ist / wir gehen in den Park","a":"Wenn das Wetter schön ist, gehen wir in den Park."},{"q":"[Mix] Er ist müde, weil er gestern spät ___ ___. (einschlafen, Perfekt)","a":"eingeschlafen ist"},{"q":"[Mix] Weißt du, ob er ___ ___ hilft? (wir, Dativ)","a":"uns"},{"q":"[Mix] denn → weil: Ich komme nicht, denn ich habe keine Zeit.","a":"Ich komme nicht, weil ich keine Zeit habe."},{"q":"Verbinde mit weil: Ich bleibe zu Hause. Ich bin krank.","a":"Ich bleibe zu Hause, weil ich krank bin."},{"q":"Verbinde mit dass: Ich glaube. Er kommt heute.","a":"Ich glaube, dass er heute kommt."},{"q":"Verbinde mit wenn: Ich habe Zeit. Ich rufe dich an. (Wenn …)","a":"Wenn ich Zeit habe, rufe ich dich an."},{"q":"Verbinde mit ob: Ich weiß nicht. Die Bank ist offen.","a":"Ich weiß nicht, ob die Bank offen ist."},{"q":"Verbinde mit weil: Sie lernt Deutsch. Sie möchte in Berlin arbeiten.","a":"Sie lernt Deutsch, weil sie in Berlin arbeiten möchte."},{"q":"Verbinde mit dass: Er sagt. Er hat keine Zeit.","a":"Er sagt, dass er keine Zeit hat."},{"q":"Verbinde mit ob: Weißt du? Der Zug hat Verspätung.","a":"Weißt du, ob der Zug Verspätung hat?"},{"q":"weil oder denn? Ich komme nicht, ___ ich muss arbeiten.","a":"denn"},{"q":"weil oder denn? Ich komme nicht, ___ ich arbeiten muss.","a":"weil"},{"q":"Fehler? „Ich lerne Deutsch, weil ich will in Deutschland studieren.“","a":"Ich lerne Deutsch, weil ich in Deutschland studieren will."}],"exam":[{"q":"Warum will Jonas wechseln?","a":"Weil er zu viele Überstunden macht."},{"q":"Was hofft Jonas?","a":"Dass er bald ein Vorstellungsgespräch hat."},{"q":"Was macht Jonas, wenn er die Stelle bekommt?","a":"Er lädt Ravi zum Essen ein."},{"q":"Indirekte Frage: „Kommst du morgen?“ → Ich frage dich, …","a":"ob du morgen kommst."},{"q":"Verbinde: Ich bin froh. Du bist hier. (dass)","a":"Ich bin froh, dass du hier bist."},{"q":"Verbinde: Ich kann nicht kommen. Ich muss arbeiten. (weil)","a":"Ich kann nicht kommen, weil ich arbeiten muss."},{"q":"Beginne mit „Wenn“: Ich trinke Tee, wenn ich krank bin.","a":"Wenn ich krank bin, trinke ich Tee."},{"q":"Was ist Ihnen bei der Arbeit wichtig? (Ich finde es wichtig, dass …)","a":"","m":"Ich finde es wichtig, dass die Kollegen nett sind. Mir ist auch wichtig, dass die Arbeit interessant ist. Es ist gut, wenn ich flexibel arbeiten kann."},{"q":"Warum lernen Sie Deutsch? Nennen Sie 3 Gründe mit weil.","a":"","m":"Ich lerne Deutsch, weil ich in Deutschland arbeite. Ich lerne Deutsch, weil ich deutsche Freunde habe. Und ich lerne Deutsch, weil ich die B1-Prüfung machen möchte."},{"q":"Was machen Sie, wenn Sie Stress bei der Arbeit haben?","a":"","m":"Wenn ich Stress bei der Arbeit habe, mache ich eine Pause. Ich gehe spazieren, wenn ich Zeit habe. Ich spreche mit Kollegen, wenn ich ein Problem habe."}],"speak":["Warum arbeiten die zwei zusammen? __Ich glaube, dass …__","Was machst du, wenn du im Büro müde bist?","Ist Homeoffice gut? __Ich finde, dass … weil …__","Frag den Partner indirekt: __Ich möchte wissen, ob …__"],"reading2":{"title":"Eine Stellenanzeige","text":"Die Firma GreenTech GmbH in Berlin sucht ab sofort eine Softwareentwicklerin oder einen Softwareentwickler in Vollzeit. Ihre Aufgaben: Sie entwickeln Apps für unsere Kunden und arbeiten in einem internationalen Team. Voraussetzungen: ein abgeschlossenes Studium in Informatik, zwei Jahre Berufserfahrung und gute Englischkenntnisse. Deutschkenntnisse auf B1-Niveau sind von Vorteil. Wir bieten: flexible Arbeitszeiten, die Möglichkeit, zwei Tage pro Woche im Homeoffice zu arbeiten, 30 Urlaubstage und ein gutes Gehalt. Die Probezeit dauert sechs Monate. Wenn Sie zuverlässig sind und gern im Team arbeiten, freuen wir uns auf Ihre Bewerbung. Schicken Sie bitte Ihren Lebenslauf und Ihre Zeugnisse per E-Mail an Frau Lange. Ravi liest die Anzeige zweimal. Er denkt, dass die Stelle perfekt ist. Er hofft, dass seine Deutschkenntnisse reichen."},"dialog":[{"who":"Frau Lange","de":"Herr Sharma, warum möchten Sie bei uns arbeiten?"},{"who":"Ravi","de":"Weil Ihre Firma umweltfreundliche Technik entwickelt. Das finde ich sehr wichtig."},{"who":"Frau Lange","de":"Was sind Ihre Stärken?"},{"who":"Ravi","de":"Ich glaube, dass ich sehr zuverlässig bin. Und ich arbeite gern im Team."},{"who":"Frau Lange","de":"Sie wissen, dass wir viel auf Deutsch kommunizieren?"},{"who":"Ravi","de":"Ja. Ich lerne jeden Tag, und ich mache bald die B1-Prüfung."},{"who":"Frau Lange","de":"Sehr gut. Haben Sie noch Fragen?"},{"who":"Ravi","de":"Ja. Ich möchte wissen, ob ich auch im Homeoffice arbeiten kann."},{"who":"Frau Lange","de":"Ja, zwei Tage pro Woche. Wir melden uns nächste Woche bei Ihnen."}],"dq":[{"q":"Warum möchte Ravi bei der Firma arbeiten?","a":"Weil sie umweltfreundliche Technik entwickelt."},{"q":"Was sagt Ravi über seine Stärken?","a":"Er ist zuverlässig und arbeitet gern im Team."},{"q":"Was möchte Ravi wissen?","a":"Ob er im Homeoffice arbeiten kann."}],"en":{"title":"Subordinate clauses with weil, dass, wenn, ob","theme":"Work and jobs","expl":["In a subordinate clause the **conjugated verb goes to the end**: __…, weil ich müde bin.__ = … because I am tired.","**weil** = because (reason). **dass** = that (after verbs like denken, glauben, finden, wissen, hoffen, sagen). **wenn** = if / whenever. **ob** = whether (an indirect yes/no question).","With a modal verb or the Perfekt, the helping verb is the very last word: __…, weil ich arbeiten muss. …, dass er gekommen ist.__","If the subordinate clause comes first, the main clause starts with the verb: __Wenn ich Zeit habe, komme ich.__"],"use":""},"check":[{"re":",\\\\s*(weil|dass|wenn|ob)\\\\b","label":"weil / dass / wenn / ob with a comma"},{"re":"\\\\b(weil|dass|wenn|ob)\\\\b[^.!?,]*\\\\b(bin|ist|sind|habe|hat|haben|kann|muss|will|möchte|lerne|arbeite|gibt|macht|mag|finde|brauche|wohne|spreche)[.!?]?","label":"the verb at the end of the weil/dass clause"}]},{"n":22,"pos":23,"level":"A2","title":"Komparativ und Superlativ","theme":"Vergleichen: Städte und Wohnen","scene":"city","rec":[5,17,20,21],"expl":["**Komparativ:** Adjektiv + **-er** (+ **als**): __Berlin ist groß**er als** München.__ Gleichheit: **so … wie**: __so groß wie__.","**Superlativ:** **am** + Adjektiv + **-sten**: __am schönsten__. Vor Nomen: __der schönst**e** Park__.","Einsilbige Adjektive mit a/o/u bekommen oft **Umlaut**: alt → älter → am ältesten, groß → größer → am größten.","**Unregelmäßig:** gut – besser – am besten · viel – mehr – am meisten · gern – lieber – am liebsten · hoch – höher – am höchsten · nah – näher – am nächsten."],"use":"Prüfung Teil 2: Vorteile/Nachteile, Heimatland vergleichen. Bilder vergleichen.","table":[["Grundform","Komparativ","Superlativ","Beispiel"],["klein","kleiner","am kleinsten","Mein Zimmer ist kleiner als deins."],["alt","älter","am ältesten","Mumbai ist älter als …"],["teuer","teurer","am teuersten","München ist am teuersten."],["gut","besser","am besten","Tee finde ich besser als Kaffee."],["viel","mehr","am meisten","In Mumbai wohnen mehr Menschen."],["gern","lieber","am liebsten","Am liebsten fahre ich Rad."]],"examples":[{"de":"Berlin ist kleiner als Mumbai.","en":"Berlin is smaller than Mumbai."},{"de":"Im Sommer ist es in Mumbai heißer als in Berlin.","en":"In summer it\'s hotter in Mumbai than in Berlin."},{"de":"Die Miete ist hier nicht so hoch wie in München.","en":"The rent here isn\'t as high as in Munich."},{"de":"Das Fahrrad ist schneller als der Bus.","en":"The bike is faster than the bus."},{"de":"Ich trinke lieber Chai als Kaffee.","en":"I prefer chai to coffee."},{"de":"Am liebsten esse ich Biryani.","en":"Most of all I like eating biryani."},{"de":"Das ist das beste Restaurant in der Stadt.","en":"That\'s the best restaurant in town."},{"de":"Welche Stadt findest du am schönsten?","en":"Which city do you find most beautiful?"},{"de":"Heute arbeite ich mehr als gestern.","en":"Today I\'m working more than yesterday."},{"de":"Der Bahnhof ist näher, als ich dachte.","en":"The station is closer than I thought."},{"de":"Berlin ist größer als München.","en":"Berlin is bigger than Munich."},{"de":"Auf dem Land ist die Miete billiger als in der Stadt.","en":"In the country the rent is cheaper than in the city."},{"de":"Hamburg ist genauso schön wie Berlin.","en":"Hamburg is just as beautiful as Berlin."},{"de":"Mit dem Fahrrad bin ich schneller als mit dem Bus.","en":"I\'m faster by bike than by bus."},{"de":"Ich wohne lieber in der Stadt.","en":"I prefer living in the city."},{"de":"Am liebsten trinke ich Tee.","en":"Most of all I like drinking tea."},{"de":"Die Zugspitze ist der höchste Berg Deutschlands.","en":"The Zugspitze is Germany\'s highest mountain."},{"de":"Welche Stadt gefällt dir am besten?","en":"Which city do you like best?"},{"de":"Im Dorf ist es ruhiger und die Luft ist sauberer.","en":"In the village it\'s quieter and the air is cleaner."},{"de":"Das ist die teuerste Wohnung, die ich kenne.","en":"That\'s the most expensive flat I know."}],"vocab":[{"de":"die Stadt, ¨e","en":"city"},{"de":"das Land","en":"countryside"},{"de":"laut / ruhig","en":"loud / quiet"},{"de":"teuer / billig (günstig)","en":"expensive / cheap"},{"de":"sauber / schmutzig","en":"clean / dirty"},{"de":"modern / alt","en":"modern / old"},{"de":"schnell / langsam","en":"fast / slow"},{"de":"der Verkehr","en":"traffic"},{"de":"die Luft","en":"air"},{"de":"die Einwohner (Pl.)","en":"inhabitants"},{"de":"der Vorteil / der Nachteil","en":"advantage / disadvantage"},{"de":"vergleichen","en":"to compare"},{"de":"groß – größer – am größten","en":"big – bigger – biggest"},{"de":"gut – besser – am besten","en":"good – better – best"},{"de":"viel – mehr – am meisten","en":"much – more – most"},{"de":"gern – lieber – am liebsten","en":"gladly – rather – most of all"},{"de":"hoch – höher – am höchsten","en":"high – higher – highest"},{"de":"nah – näher – am nächsten","en":"near – nearer – nearest"},{"de":"als","en":"than"},{"de":"genauso … wie","en":"just as … as"},{"de":"das Dorf, ¨er","en":"village"},{"de":"die Großstadt, ¨e","en":"big city"},{"de":"die Natur","en":"nature"},{"de":"die Nachbarschaft","en":"neighbourhood"},{"de":"die Miete, -n","en":"rent"},{"de":"das Angebot, -e","en":"offer, range"},{"de":"die Lebensqualität","en":"quality of life"},{"de":"gefährlich","en":"dangerous"},{"de":"sicher","en":"safe"},{"de":"bequem","en":"comfortable"}],"reading":"Leila fragt Ravi: „Wo lebst du lieber, in Mumbai oder in Berlin?“ Ravi denkt nach: „Mumbai ist größer und lauter als Berlin. Dort wohnen viel mehr Menschen. In Berlin ist die Luft sauberer und der Verkehr ist nicht so schlimm wie in Mumbai. Aber das Essen in Mumbai ist am besten! Und im Winter ist Berlin viel kälter.“ Leila lacht: „Also, was magst du am liebsten?“ – „Am liebsten wohne ich in Berlin und esse in Mumbai!“","tasks":[{"q":"Berlin ist ___ als Hamburg. (groß)","a":"größer"},{"q":"Der Zug ist ___ als das Auto. (schnell)","a":"schneller"},{"q":"Mein Bruder ist so ___ wie ich. (alt)","a":"alt"},{"q":"Ich trinke ___ Tee als Kaffee. (gern)","a":"lieber"},{"q":"Das ist das ___ Hotel. (gut, Superlativ)","a":"beste"},{"q":"Im Juli ist es am ___. (heiß)","a":"heißesten"},{"q":"Hier ist es nicht so ___ wie in München. (teuer)","a":"teuer"},{"q":"[Mix] Ich finde, dass Berlin ___ ist als Köln. (interessant)","a":"interessanter"},{"q":"[Mix] Früher war die Miete ___ als heute. (niedrig)","a":"niedriger"},{"q":"[Mix] Ich fahre lieber mit ___ Rad, denn es ist ___. (das, schnell – Komparativ)","a":"dem / schneller"},{"q":"Komparativ: Der Zug ist ___ als das Auto. (schnell)","a":"schneller"},{"q":"Komparativ: Im Sommer ist es ___ als im Winter. (warm)","a":"wärmer"},{"q":"Komparativ: Mein Bruder ist ___ als ich. (alt)","a":"älter"},{"q":"Komparativ: Tee trinke ich ___ als Kaffee. (gern)","a":"lieber"},{"q":"Superlativ: Der Mount Everest ist am ___. (hoch)","a":"höchsten"},{"q":"Superlativ: Mein Opa erzählt die ___ Geschichten. (gut, Plural)","a":"besten"},{"q":"als oder wie? Er ist größer ___ ich.","a":"als"},{"q":"als oder wie? Sie ist genauso alt ___ ihr Mann.","a":"wie"},{"q":"Komparativ: Berlin hat ___ Einwohner als Hamburg. (viel)","a":"mehr"},{"q":"Fehler? „Mein Auto ist schneller wie dein Auto.“","a":"Mein Auto ist schneller als dein Auto."}],"exam":[{"q":"Welche Stadt ist lauter?","a":"Mumbai."},{"q":"Wo ist die Luft sauberer?","a":"In Berlin."},{"q":"Wo ist das Essen am besten (für Ravi)?","a":"In Mumbai."},{"q":"Vergleiche: Zug / Bus / schnell","a":"Der Zug ist schneller als der Bus."},{"q":"Superlativ: Das Wetter ist im Mai ___ (schön).","a":"am schönsten"},{"q":"Ergänze: Ich esse ___ (viel) Reis als Brot.","a":"mehr"},{"q":"Ergänze: Sie spricht so gut ___ ein Deutscher.","a":"wie"},{"q":"Vergleichen Sie Ihre Heimatstadt mit Ihrer Stadt in Deutschland.","a":"","m":"Mumbai ist viel größer als Berlin. In Mumbai ist es wärmer und lauter. Berlin ist grüner und ruhiger. Das Essen in Mumbai ist besser, aber die Busse in Berlin sind pünktlicher."},{"q":"Stadt oder Land: Wo lebt man besser? Nennen Sie Vor- und Nachteile.","a":"","m":"Auf dem Land ist es ruhiger und die Luft ist besser. In der Stadt gibt es mehr Arbeit und mehr Kultur. Die Mieten auf dem Land sind billiger. Ich lebe lieber in der Stadt."},{"q":"Was ist Ihr liebstes Essen, Ihr liebster Ort, Ihre liebste Jahreszeit?","a":"","m":"Mein liebstes Essen ist Biryani. Mein liebster Ort ist der Strand in Goa. Meine liebste Jahreszeit ist der Frühling, denn er ist am schönsten."}],"speak":["Vergleiche die Häuser: __Das rote Haus ist kleiner als …__","Was ist schneller: der Bus oder der Mann zu Fuß?","Vergleiche Berlin und deine Stadt (5 Sätze).","Was machst du am liebsten in einer Stadt?"],"reading2":{"title":"Stadt oder Land?","text":"Mia kommt aus einem kleinen Dorf im Schwarzwald. Seit zwei Jahren studiert sie in Berlin. Was gefällt ihr besser? „In Berlin gibt es mehr Kultur, mehr Cafés und mehr junge Leute. Die Stadt ist viel lebendiger als mein Dorf. Aber sie ist auch lauter und schmutziger.“ In ihrem Dorf kennt jeder jeden. Das ist schön, aber manchmal auch anstrengend. In Berlin ist man freier. Die Mieten sind in Berlin natürlich höher. Für ein kleines Zimmer bezahlt Mia 550 Euro, im Dorf zahlt man für eine ganze Wohnung weniger. Auch die Natur fehlt ihr. „Im Schwarzwald ist die Luft sauberer und der Wald ist direkt vor der Tür.“ Am liebsten möchte Mia später in einer mittelgroßen Stadt wohnen, zum Beispiel in Freiburg. „Freiburg ist kleiner als Berlin, aber genauso jung. Und die Berge sind ganz nah. Für mich ist das die beste Mischung.“"},"dialog":[{"who":"Jonas","de":"Ravi, du suchst doch eine Wohnung. Was ist dir am wichtigsten?"},{"who":"Ravi","de":"Am wichtigsten ist die Lage. Ich will nicht länger als dreißig Minuten zur Arbeit fahren."},{"who":"Jonas","de":"Und lieber Altbau oder Neubau?"},{"who":"Ravi","de":"Ein Altbau ist schöner, aber ein Neubau ist moderner und wärmer im Winter."},{"who":"Jonas","de":"Die Wohnung in Pankow ist billiger als die in Mitte, oder?"},{"who":"Ravi","de":"Ja, sie kostet zweihundert Euro weniger. Aber sie ist auch kleiner."},{"who":"Jonas","de":"Und Pankow ist ruhiger. Für dich ist das besser, glaube ich."},{"who":"Ravi","de":"Stimmt. Ich nehme die Wohnung in Pankow."}],"dq":[{"q":"Was ist Ravi am wichtigsten?","a":"Die Lage (nicht länger als 30 Minuten zur Arbeit)."},{"q":"Welche Wohnung ist billiger?","a":"Die Wohnung in Pankow."},{"q":"Welche Wohnung nimmt Ravi?","a":"Die Wohnung in Pankow."}],"en":{"title":"Comparative and superlative","theme":"Comparing cities and homes","expl":["Comparative: adjective + **-er** (+ **als** = than): __Berlin ist größer als München.__ Equal: **so … wie**: __so groß wie__ = as big as.","Superlative: **am** + adjective + **-sten**: __am schönsten__. Before a noun: __der schönste Park__.","Short adjectives with a/o/u often get an umlaut: alt → älter → am ältesten, groß → größer → am größten.","Irregular: gut – besser – am besten, viel – mehr – am meisten, gern – lieber – am liebsten, hoch – höher – am höchsten."],"use":""},"check":[{"re":"\\\\b\\\\w+er als\\\\b|\\\\bso \\\\w+ wie\\\\b|\\\\bam \\\\w+sten\\\\b|\\\\b(besser|mehr|lieber|größer|kleiner|älter|teurer|billiger)\\\\b","label":"comparative (-er als) or superlative (am …sten)"}]},{"n":23,"pos":24,"level":"A2","title":"Adjektivdeklination (Endungen)","theme":"Kleidung und Aussehen","scene":"shop","rec":[5,6,13,14,22],"expl":["Steht ein Adjektiv **vor einem Nomen**, bekommt es eine Endung. Nach **sein** hat es **keine** Endung: __Die Jacke ist **blau**.__ aber __die blau**e** Jacke__.","**Typ 1 (der/die/das):** nur -e oder -en. Nominativ Singular + Akkusativ fem./neutr. = **-e**, sonst **-en**.","**Typ 2 (ein/kein/mein):** wie Typ 1, aber wo „ein“ keine Endung hat: mask. Nom. **-er**, neutr. Nom./Akk. **-es**.","**Typ 3 (ohne Artikel):** Das Adjektiv zeigt den Fall wie der Artikel: kalt**er** Kaffee, heiß**e** Suppe, frisch**es** Brot. Siehe Referenz 2."],"use":"Kleidung, Personen, Dinge, Bilder beschreiben – macht dein Deutsch genauer.","table":[["Fall","mask.","fem.","neutr.","Plural"],["Nom. (der)","der rote Pulli","die rote Jacke","das rote Hemd","die roten Schuhe"],["Akk. (der)","den rot**en** Pulli","die rote Jacke","das rote Hemd","die roten Schuhe"],["Dat. (der)","dem rot**en** Pulli","der rot**en** Jacke","dem rot**en** Hemd","den rot**en** Schuhen"],["Nom. (ein)","ein rot**er** Pulli","eine rote Jacke","ein rot**es** Hemd","rote Schuhe"],["Akk. (ein)","einen rot**en** Pulli","eine rote Jacke","ein rot**es** Hemd","rote Schuhe"],["Dat. (ein)","einem rot**en** Pulli","einer rot**en** Jacke","einem rot**en** Hemd","rot**en** Schuhen"]],"examples":[{"de":"Ich suche eine warme Jacke.","en":"I\'m looking for a warm jacket."},{"de":"Der blaue Pulli gefällt mir.","en":"I like the blue jumper."},{"de":"Hast du einen schwarzen Gürtel?","en":"Do you have a black belt?"},{"de":"Ravi trägt ein weißes Hemd.","en":"Ravi is wearing a white shirt."},{"de":"Mit dem neuen Mantel ist mir nicht kalt.","en":"With the new coat I\'m not cold."},{"de":"Anna hat lange, braune Haare.","en":"Anna has long brown hair."},{"de":"Ich trinke gern heißen Tee.","en":"I like drinking hot tea."},{"de":"Die grünen Schuhe sind zu klein.","en":"The green shoes are too small."},{"de":"Das ist ein schönes Geschenk für meine kleine Schwester.","en":"That\'s a nice present for my little sister."},{"de":"Ich wohne in einer großen Wohnung.","en":"I live in a big flat."},{"de":"Ich suche einen warmen Mantel.","en":"I\'m looking for a warm coat."},{"de":"Die blaue Jacke gefällt mir.","en":"I like the blue jacket."},{"de":"Hast du ein schwarzes Kleid?","en":"Do you have a black dress?"},{"de":"Er trägt heute ein weißes Hemd und eine rote Krawatte.","en":"Today he\'s wearing a white shirt and a red tie."},{"de":"Die neuen Schuhe sind sehr bequem.","en":"The new shoes are very comfortable."},{"de":"Kann ich die grüne Hose anprobieren?","en":"Can I try on the green trousers?"},{"de":"Die Hose ist zu eng. Haben Sie eine größere?","en":"The trousers are too tight. Do you have a bigger pair?"},{"de":"Mit dem neuen Schal siehst du toll aus.","en":"You look great with the new scarf."},{"de":"Sie hat lange, braune Haare.","en":"She has long brown hair."},{"de":"Ich nehme den gestreiften Pullover.","en":"I\'ll take the striped jumper."}],"vocab":[{"de":"die Kleidung","en":"clothes"},{"de":"die Hose, -n","en":"trousers"},{"de":"der Pullover (Pulli), -","en":"jumper"},{"de":"die Jacke, -n","en":"jacket"},{"de":"der Mantel, ¨","en":"coat"},{"de":"das Hemd, -en","en":"shirt"},{"de":"das Kleid, -er","en":"dress"},{"de":"der Schuh, -e","en":"shoe"},{"de":"anprobieren","en":"to try on"},{"de":"die Größe, -n","en":"size"},{"de":"tragen (trägt)","en":"to wear / carry"},{"de":"die Farbe, -n","en":"colour"},{"de":"der Rock, ¨e","en":"skirt"},{"de":"die Bluse, -n","en":"blouse"},{"de":"das T-Shirt, -s","en":"T-shirt"},{"de":"die Jeans, -","en":"jeans"},{"de":"der Anzug, ¨e","en":"suit"},{"de":"die Mütze, -n","en":"woollen hat"},{"de":"der Schal, -s","en":"scarf"},{"de":"die Stiefel (Pl.)","en":"boots"},{"de":"die Handschuhe (Pl.)","en":"gloves"},{"de":"die Umkleidekabine, -n","en":"changing room"},{"de":"eng / weit","en":"tight / loose"},{"de":"kurz / lang","en":"short / long"},{"de":"bunt","en":"colourful"},{"de":"gestreift / kariert","en":"striped / checked"},{"de":"schick","en":"smart, chic"},{"de":"bequem","en":"comfortable"},{"de":"passen","en":"to fit"},{"de":"das Sonderangebot, -e","en":"special offer"}],"reading":"Der Winter kommt, und Ravi braucht warme Kleidung. Mit Anna geht er in ein großes Kaufhaus. „Ich suche einen dicken Mantel“, sagt er. Die Verkäuferin zeigt ihm einen schwarzen Mantel und einen blauen Mantel. Ravi probiert den blauen Mantel an. Anna sagt: „Die blaue Farbe steht dir gut!“ Er kauft auch warme Handschuhe und einen roten Schal. Mit der neuen Kleidung freut er sich sogar auf den kalten Berliner Winter.","tasks":[{"q":"Ich kaufe einen ___ Pulli. (warm)","a":"warmen"},{"q":"Das ist ein ___ Kleid. (schön)","a":"schönes"},{"q":"Die ___ Hose ist zu lang. (grau)","a":"graue"},{"q":"Ich suche den ___ Schal. (rot)","a":"roten"},{"q":"Er wohnt mit einer ___ Freundin zusammen. (nett)","a":"netten"},{"q":"Ich trinke ___ Kaffee. (schwarz, ohne Artikel)","a":"schwarzen"},{"q":"Das ist ein ___ Mann. (alt)","a":"alter"},{"q":"[Mix] Ich schenke meiner ___ Schwester einen ___ Rock. (klein, kurz)","a":"kleinen / kurzen"},{"q":"[Mix] Dieser Mantel ist ___ als der ___ Mantel. (warm – Komp., blau)","a":"wärmer / blaue"},{"q":"[Mix] Ich habe mir ___ ___ Schuhe gekauft. (neu, ohne Artikel, Pl.)","a":"neue"},{"q":"Ich kaufe einen ___ Pullover. (warm)","a":"warmen"},{"q":"Das ist eine ___ Bluse. (schön)","a":"schöne"},{"q":"Er trägt ein ___ Hemd. (weiß)","a":"weißes"},{"q":"Die ___ Schuhe sind bequem. (neu)","a":"neuen"},{"q":"Ich suche den ___ Schal. (rot)","a":"roten"},{"q":"Hast du eine ___ Jacke? (schwarz)","a":"schwarze"},{"q":"Mit dem ___ Mantel siehst du toll aus. (lang)","a":"langen"},{"q":"Sie hat ___ Haare. (lang, ohne Artikel)","a":"lange"},{"q":"Das ___ Kleid gefällt mir. (blau)","a":"blaue"},{"q":"Fehler? „Ich habe einen neue Hose.“","a":"Ich habe eine neue Hose."}],"exam":[{"q":"Was sucht Ravi?","a":"Einen dicken Mantel."},{"q":"Welchen Mantel probiert er an?","a":"Den blauen Mantel."},{"q":"Was kauft er noch?","a":"Warme Handschuhe und einen roten Schal."},{"q":"Ergänze: Ich brauche ___ neu___ Handy. (ein)","a":"ein neues"},{"q":"Ergänze: Wir wohnen in ___ klein___ Stadt. (eine)","a":"einer kleinen"},{"q":"Ergänze: Sie trägt ___ gelb___ Rock. (der, Akk.)","a":"den gelben"},{"q":"Ergänze: Mit gut___ Freunden ist alles leichter.","a":"guten"},{"q":"Beschreiben Sie, was Sie heute tragen.","a":"","m":"Heute trage ich eine blaue Jeans und ein weißes Hemd. Darüber trage ich einen grauen Pullover. Ich trage schwarze Schuhe und eine kleine Uhr."},{"q":"Beschreiben Sie eine Person aus Ihrer Familie genau.","a":"","m":"Meine Schwester hat lange, schwarze Haare und braune Augen. Sie trägt gern bunte Kleider. Sie ist eine fröhliche und freundliche Person."},{"q":"Sie kaufen im Geschäft eine Hose. Spielen Sie das Gespräch.","a":"","m":"Guten Tag, ich suche eine schwarze Hose. – Welche Größe? – Größe 32. – Hier ist eine schöne Hose aus Baumwolle. – Kann ich sie anprobieren? – Natürlich, die Kabine ist dort."}],"speak":["Beschreibe die Personen: __Der Mann trägt eine blaue …__","Was liegt in den Regalen? __Es gibt rote, grüne …__","Was ist dein Lieblingskleidungsstück?","Beschreibe dein Traumoutfit für eine Party."],"reading2":{"title":"Was ziehe ich an?","text":"Leila hat am Freitag ein wichtiges Vorstellungsgespräch in einem großen Krankenhaus. Was soll sie anziehen? Sie öffnet ihren Kleiderschrank. Das rote Kleid ist zu elegant, die alte Jeans zu locker. Ihre Freundin Aiko ist Designerin und hilft ihr gern. „Für ein Vorstellungsgespräch brauchst du ein klassisches Outfit“, sagt sie. Am Samstag gehen die beiden in ein großes Kaufhaus. Leila probiert eine dunkelblaue Hose und eine weiße Bluse an. Die Bluse passt perfekt, aber die Hose ist zu lang. Die Verkäuferin bringt eine kürzere Hose. Dazu nimmt Leila einen grauen Blazer. „Du siehst sehr professionell aus“, sagt Aiko. Für die Füße kauft Leila bequeme schwarze Schuhe, denn sie muss vielleicht lange stehen. Am Ende bezahlt sie 189 Euro. Das ist viel Geld, aber die Kleidung kann sie auch bei der Arbeit tragen. Am Freitag fühlt sie sich sicher und schick."},"dialog":[{"who":"Verkäufer","de":"Kann ich Ihnen helfen?"},{"who":"Jonas","de":"Ja, ich suche eine Jacke für den Winter."},{"who":"Verkäufer","de":"Welche Größe haben Sie?"},{"who":"Jonas","de":"Größe L, glaube ich."},{"who":"Verkäufer","de":"Hier haben wir eine warme Jacke in Schwarz und eine in Dunkelgrün."},{"who":"Jonas","de":"Die dunkelgrüne gefällt mir. Kann ich sie anprobieren?"},{"who":"Verkäufer","de":"Natürlich, die Umkleidekabine ist dort hinten."},{"who":"Jonas","de":"Hm, sie ist ein bisschen zu eng. Haben Sie die Jacke eine Nummer größer?"},{"who":"Verkäufer","de":"Ja, in XL. Und sie ist gerade im Sonderangebot: nur 99 Euro."}],"dq":[{"q":"Was sucht Jonas?","a":"Eine Jacke für den Winter."},{"q":"Welche Farbe gefällt ihm?","a":"Dunkelgrün."},{"q":"Was kostet die Jacke im Angebot?","a":"99 Euro."}],"en":{"title":"Adjective endings","theme":"Clothes and appearance","expl":["An adjective **before a noun** gets an ending; after sein it has none: __Die Jacke ist blau.__ but __die blaue Jacke__.","After **der/die/das**: only **-e** or **-en**. Nominative singular and feminine/neuter accusative = -e, everything else = -en: __der blaue Mantel, den blauen Mantel__.","After **ein/kein/mein**: the same, except where ein has no ending – then the adjective shows the gender: masculine nominative **-er** (__ein blauer Mantel__), neuter nominative/accusative **-es** (__ein blaues Hemd__).","Without an article the adjective takes the ending of der/die/das: __kalter Kaffee, frische Milch, kaltes Wasser__."],"use":""},"check":[{"re":"\\\\b\\\\w+(e|en|er|es|em)\\\\s+[A-ZÄÖÜ]\\\\w+","label":"adjective endings before a noun (eine blaue Jacke)"}]},{"n":24,"pos":25,"level":"A2","title":"Zeit: seit, vor, nach, ab, bis + Reihenfolge (zuerst, dann, danach)","theme":"Reisen und Urlaub","scene":"station","rec":[9,15,17,18,21],"expl":["Temporale Präpositionen mit **Dativ**: **seit** (seit einem Jahr – dauert noch an, Präsens!), **vor** (vor zwei Tagen = ago), **nach** (nach dem Essen), **ab** (ab Montag), **bei** (beim Frühstück).","Mit **Akkusativ**: **für** (für eine Woche), **bis** (bis nächsten Freitag), **über** (über das Wochenende).","**Reihenfolge-Adverbien** (Position 1 → Inversion!): **zuerst, dann, danach, später, anschließend, am Ende / zum Schluss**.","Achtung: __Ich wohne **seit** drei Jahren hier__ (nicht: habe gewohnt)."],"use":"Reisen erzählen, Pläne machen, Präsentation strukturieren.","table":[["Präposition","Fall","Beispiel","English"],["seit","Dat.","seit einem Monat","for / since (still now)"],["vor","Dat.","vor einer Woche","ago"],["nach","Dat.","nach der Arbeit","after"],["ab","Dat.","ab nächster Woche","from … on"],["für","Akk.","für zwei Wochen","for (planned)"],["bis","Akk.","bis nächsten Montag","until"]],"examples":[{"de":"Ich lerne seit sechs Monaten Deutsch.","en":"I have been learning German for six months."},{"de":"Vor zwei Wochen war ich in Wien.","en":"Two weeks ago I was in Vienna."},{"de":"Nach dem Frühstück sind wir losgefahren.","en":"After breakfast we set off."},{"de":"Ab Montag habe ich Urlaub.","en":"From Monday I\'m on holiday."},{"de":"Wir fahren für eine Woche an die Ostsee.","en":"We\'re going to the Baltic Sea for a week."},{"de":"Das Hotel ist bis Sonntag gebucht.","en":"The hotel is booked until Sunday."},{"de":"Zuerst haben wir den Dom besichtigt.","en":"First we visited the cathedral."},{"de":"Danach sind wir mit dem Schiff gefahren.","en":"After that we went by boat."},{"de":"Zum Schluss haben wir Sachertorte gegessen.","en":"Finally we ate Sachertorte."},{"de":"Beim Packen hört Ravi Musik.","en":"While packing Ravi listens to music."},{"de":"Ich wohne seit drei Jahren in Berlin.","en":"I\'ve been living in Berlin for three years."},{"de":"Vor zwei Wochen war ich in Wien.","en":"Two weeks ago I was in Vienna."},{"de":"Nach dem Frühstück besichtigen wir die Altstadt.","en":"After breakfast we\'ll visit the old town."},{"de":"Ab Montag habe ich Urlaub.","en":"I\'m on holiday from Monday."},{"de":"Das Hotel ist bis Sonntag ausgebucht.","en":"The hotel is fully booked until Sunday."},{"de":"Zuerst checken wir ein, danach gehen wir an den Strand.","en":"First we check in, then we go to the beach."},{"de":"Der Flug dauert neun Stunden.","en":"The flight takes nine hours."},{"de":"Haben Sie noch ein Doppelzimmer frei?","en":"Do you still have a double room available?"},{"de":"Die Übernachtung kostet 80 Euro mit Frühstück.","en":"The night costs 80 euros with breakfast."},{"de":"Ich muss die Reise leider stornieren.","en":"Unfortunately I have to cancel the trip."}],"vocab":[{"de":"der Urlaub, -e","en":"holiday"},{"de":"die Reise, -n","en":"journey"},{"de":"buchen","en":"to book"},{"de":"das Hotel, -s","en":"hotel"},{"de":"die Unterkunft, ¨e","en":"accommodation"},{"de":"packen","en":"to pack"},{"de":"besichtigen","en":"to visit (sights)"},{"de":"die Sehenswürdigkeit, -en","en":"sight"},{"de":"das Schiff, -e","en":"ship"},{"de":"der Strand, ¨e","en":"beach"},{"de":"das Gepäck","en":"luggage"},{"de":"anschließend","en":"subsequently"},{"de":"seit","en":"since, for (duration up to now)"},{"de":"vor","en":"ago"},{"de":"nach","en":"after"},{"de":"ab","en":"from (on)"},{"de":"bis","en":"until"},{"de":"während","en":"during"},{"de":"zuerst","en":"first"},{"de":"danach","en":"after that"},{"de":"zum Schluss","en":"finally"},{"de":"der Flug, ¨e","en":"flight"},{"de":"der Flughafen, ¨","en":"airport"},{"de":"das Visum, Visa","en":"visa"},{"de":"der Reisepass, ¨e","en":"passport"},{"de":"die Rezeption, -en","en":"reception"},{"de":"das Einzelzimmer / Doppelzimmer","en":"single / double room"},{"de":"die Übernachtung, -en","en":"overnight stay"},{"de":"die Halbpension","en":"half board"},{"de":"stornieren","en":"to cancel (a booking)"}],"reading":"Vor drei Wochen hat Ravi eine Reise nach Wien gemacht. Er hat für vier Tage ein Hotel gebucht. Zuerst ist er mit dem Zug nach Wien gefahren. Die Fahrt hat acht Stunden gedauert. Nach der Ankunft hat er sich ausgeruht. Am nächsten Tag hat er zuerst das Schloss Schönbrunn besichtigt, danach ist er in ein Café gegangen. Zum Schluss hat er eine Schifffahrt auf der Donau gemacht. Seit dieser Reise liebt er Wien. Ab Januar spart er für die nächste Reise.","tasks":[{"q":"Ich wohne ___ zwei Jahren in Berlin.","a":"seit"},{"q":"___ einer Woche war ich krank. (ago)","a":"Vor"},{"q":"___ dem Kurs gehe ich einkaufen. (after)","a":"Nach"},{"q":"Ich fahre ___ drei Tage nach Paris.","a":"für"},{"q":"Das Angebot gilt ___ Freitag. (until)","a":"bis"},{"q":"___ nächstem Monat arbeite ich Teilzeit. (from)","a":"Ab"},{"q":"Ordne: zuerst / wir / haben / gefrühstückt","a":"Zuerst haben wir gefrühstückt."},{"q":"[Mix] Danach ___ wir ins Museum ___. (gehen, Perfekt)","a":"sind / gegangen"},{"q":"[Mix] Seit ___ Umzug fühle ich ___ wohler. (mein, sich)","a":"meinem / mich"},{"q":"[Mix] Ich weiß nicht, ob das Hotel ___ Sonntag frei ___. (bis, sein)","a":"bis / ist"},{"q":"Ich lerne ___ zwei Jahren Deutsch. (seit/vor)","a":"seit"},{"q":"___ drei Tagen war ich beim Arzt. (seit/vor)","a":"Vor"},{"q":"___ dem Essen trinken wir Kaffee. (nach/seit)","a":"Nach"},{"q":"Das Geschäft ist ___ 20 Uhr geöffnet. (bis/ab)","a":"bis"},{"q":"___ nächster Woche arbeite ich wieder. (ab/vor)","a":"Ab"},{"q":"Er wohnt ___ einem Monat in Wien. (seit/vor)","a":"seit"},{"q":"___ des Urlaubs habe ich viel gelesen. (während/seit)","a":"Während"},{"q":"Ordne mit „Zuerst“: frühstücken wir","a":"Zuerst frühstücken wir."},{"q":"Ordne mit „Danach“: gehen wir an den Strand","a":"Danach gehen wir an den Strand."},{"q":"Fehler? „Ich wohne hier vor zwei Jahren.“","a":"Ich wohne hier seit zwei Jahren."}],"exam":[{"q":"Wann war Ravi in Wien?","a":"Vor drei Wochen."},{"q":"Wie lange hat die Zugfahrt gedauert?","a":"Acht Stunden."},{"q":"Was hat er zum Schluss gemacht?","a":"Eine Schifffahrt auf der Donau."},{"q":"Ergänze: Ich warte ___ einer Stunde! (still waiting)","a":"seit"},{"q":"Ergänze: Wir haben uns ___ fünf Jahren kennengelernt. (ago)","a":"vor"},{"q":"Ergänze: ___ dem Essen putze ich mir die Zähne.","a":"Nach"},{"q":"Korrigiere: Ich habe seit 2023 in Berlin gewohnt (wohne immer noch).","a":"Ich wohne seit 2023 in Berlin."},{"q":"Erzählen Sie von Ihrer letzten Reise: zuerst, dann, danach, zum Schluss.","a":"","m":"Letzten Sommer war ich in München. Zuerst habe ich das Hotel gesucht. Dann habe ich die Altstadt besichtigt. Danach habe ich Weißwurst gegessen. Zum Schluss bin ich in den Englischen Garten gegangen."},{"q":"Planen Sie einen Wochenendausflug mit Ihrem Partner.","a":"","m":"Wir fahren am Samstag ab acht Uhr mit dem Zug nach Potsdam. Zuerst besuchen wir das Schloss. Danach essen wir im Park. Bis Sonntagabend bleiben wir dort."},{"q":"Wie lange lernen Sie schon Deutsch? Was war vor einem Jahr anders?","a":"","m":"Ich lerne seit acht Monaten Deutsch. Vor einem Jahr konnte ich nur „Hallo“ sagen. Jetzt kann ich einfache Gespräche führen."}],"speak":["Wohin fahren die Leute? Wie lange bleiben sie? (Vermutung)","Erzähl eine Reise mit zuerst – dann – danach – zum Schluss.","Was packst du für eine Woche Urlaub ein?","Wo warst du vor einem Jahr? Seit wann bist du hier?"],"reading2":{"title":"Eine Reise nach Wien","text":"Vor einem Monat haben Tomás und Mia eine Reise nach Wien gebucht. Seit Wochen freuen sie sich darauf. Am Freitag fahren sie ab. Zuerst nehmen sie den Nachtzug von Berlin, denn er ist umweltfreundlicher als das Flugzeug. Die Fahrt dauert elf Stunden. Nach der Ankunft frühstücken sie in einem typischen Wiener Kaffeehaus. Danach checken sie im Hotel ein. Das Zimmer ist erst ab 14 Uhr frei, deshalb lassen sie das Gepäck an der Rezeption. Am Vormittag besichtigen sie den Stephansdom. Mia steigt bis ganz nach oben, über 300 Stufen! Am Nachmittag fahren sie mit dem Riesenrad im Prater. Am Abend gehen sie in ein Konzert. Am Samstag besuchen sie das Schloss Schönbrunn, und während der Führung lernen sie viel über die Kaiserin Sisi. Zum Schluss essen sie natürlich ein Wiener Schnitzel. Am Sonntag fahren sie müde, aber glücklich zurück. „Bis bald, Wien!“, sagt Mia."},"dialog":[{"who":"Rezeption","de":"Hotel Am Park, guten Tag. Was kann ich für Sie tun?"},{"who":"Tomás","de":"Guten Tag. Haben Sie vom 14. bis zum 16. Mai ein Doppelzimmer frei?"},{"who":"Rezeption","de":"Einen Moment … Ja, wir haben noch ein Zimmer mit Balkon."},{"who":"Tomás","de":"Wie viel kostet die Übernachtung?"},{"who":"Rezeption","de":"Hundertzehn Euro pro Nacht, mit Frühstück."},{"who":"Tomás","de":"Ab wann können wir am Freitag einchecken?"},{"who":"Rezeption","de":"Ab vierzehn Uhr. Ihr Gepäck können Sie aber schon früher bei uns lassen."},{"who":"Tomás","de":"Super. Kann ich bis zum Mittwoch kostenlos stornieren?"},{"who":"Rezeption","de":"Ja, bis achtundvierzig Stunden vor der Ankunft."}],"dq":[{"q":"Von wann bis wann bucht Tomás das Zimmer?","a":"Vom 14. bis zum 16. Mai."},{"q":"Was kostet eine Nacht?","a":"110 Euro mit Frühstück."},{"q":"Bis wann kann man kostenlos stornieren?","a":"Bis 48 Stunden vor der Ankunft."}],"en":{"title":"Time: seit, vor, nach, ab, bis + sequence (zuerst, dann, danach)","theme":"Travel and holidays","expl":["Time prepositions with the dative: **seit** (since/for – still going on, so use the present: __Ich wohne seit einem Jahr hier.__), **vor** (ago: __vor zwei Tagen__), **nach** (after), **ab** (from … on), **bei** (during: __beim Frühstück__).","With the accusative: **für** (for a planned period: __für eine Woche__), **bis** (until), **über** (over: __über das Wochenende__).","Sequence words (they take position 1, so the verb comes next): __zuerst, dann, danach, später, zum Schluss__: __Zuerst frühstücke ich, dann gehe ich los.__"],"use":""},"check":[{"re":"\\\\b(zuerst|dann|danach|zum schluss|später|seit|vor|nach|ab|bis)\\\\b","label":"zuerst, dann, danach / seit, vor, nach"}]},{"n":25,"pos":26,"level":"B1","title":"Konjunktiv II: würde, hätte, wäre, könnte","theme":"Wünsche und Träume","scene":"party","rec":[11,18,21,22],"expl":["Der **Konjunktiv II** drückt **Wünsche, Träume, irreale Situationen** und **Höflichkeit** aus.","Form: meistens **würde + Infinitiv**: __Ich **würde** gern reisen.__ Bei **sein, haben** und **Modalverben** nimmt man eigene Formen: **wäre, hätte, könnte, müsste, dürfte, sollte**.","**Irreale Bedingung:** __**Wenn** ich Zeit **hätte**, **würde** ich mehr Sport machen.__ (Ich habe keine Zeit.)","**Höflich:** __**Könnten** Sie mir helfen? Ich **hätte** gern einen Kaffee. **Wäre** es möglich, …?__"],"use":"Prüfung Teil 1: höflich vorschlagen. Teil 2: Wünsche/Meinung. Sehr häufig in B1!","table":[["Person","werden → würde","haben → hätte","sein → wäre","können → könnte"],["ich","würde","hätte","wäre","könnte"],["du","würdest","hättest","wär(e)st","könntest"],["er/sie/es","würde","hätte","wäre","könnte"],["wir","würden","hätten","wären","könnten"],["ihr","würdet","hättet","wär(e)t","könntet"],["sie/Sie","würden","hätten","wären","könnten"]],"examples":[{"de":"Ich würde gern eine Weltreise machen.","en":"I\'d like to travel around the world."},{"de":"Wenn ich reich wäre, würde ich ein Haus am Meer kaufen.","en":"If I were rich, I\'d buy a house by the sea."},{"de":"Könnten Sie das bitte wiederholen?","en":"Could you repeat that, please?"},{"de":"Ich hätte gern ein Glas Wasser.","en":"I\'d like a glass of water."},{"de":"Wenn ich mehr Zeit hätte, würde ich Gitarre lernen.","en":"If I had more time, I\'d learn guitar."},{"de":"Wäre es möglich, den Termin zu verschieben?","en":"Would it be possible to postpone the appointment?"},{"de":"An deiner Stelle würde ich zum Arzt gehen.","en":"If I were you, I\'d go to the doctor."},{"de":"Wir könnten am Samstag grillen.","en":"We could have a barbecue on Saturday."},{"de":"Ich wünschte, meine Familie wäre hier.","en":"I wish my family were here."},{"de":"Würdest du mir kurz helfen?","en":"Would you help me for a moment?"},{"de":"Wenn ich mehr Zeit hätte, würde ich ein Instrument lernen.","en":"If I had more time, I would learn an instrument."},{"de":"Wenn ich reich wäre, würde ich um die Welt reisen.","en":"If I were rich, I would travel around the world."},{"de":"An deiner Stelle würde ich die Stelle annehmen.","en":"In your place I would accept the job."},{"de":"Könnten Sie mir bitte helfen?","en":"Could you help me, please?"},{"de":"Ich hätte gern einen Cappuccino.","en":"I\'d like a cappuccino."},{"de":"Es wäre schön, wenn du mitkommen könntest.","en":"It would be nice if you could come along."},{"de":"Du solltest mehr schlafen.","en":"You should sleep more."},{"de":"Wie wäre es mit einem Spaziergang?","en":"How about a walk?"},{"de":"Ich wünschte, ich wäre am Meer.","en":"I wish I were at the seaside."},{"de":"Würden Sie das Fenster schließen?","en":"Would you close the window?"}],"vocab":[{"de":"der Wunsch, ¨e","en":"wish"},{"de":"der Traum, ¨e","en":"dream"},{"de":"träumen von","en":"to dream of"},{"de":"sich wünschen","en":"to wish for"},{"de":"reich","en":"rich"},{"de":"die Weltreise, -n","en":"world trip"},{"de":"möglich","en":"possible"},{"de":"verschieben","en":"to postpone"},{"de":"höflich","en":"polite"},{"de":"die Feier, -n","en":"celebration"},{"de":"die Überraschung, -en","en":"surprise"},{"de":"das Glück","en":"luck / happiness"},{"de":"würde","en":"would"},{"de":"hätte","en":"would have"},{"de":"wäre","en":"would be"},{"de":"könnte","en":"could"},{"de":"sollte","en":"should"},{"de":"müsste","en":"would have to"},{"de":"dürfte","en":"might, would be allowed to"},{"de":"der Lottogewinn, -e","en":"lottery win"},{"de":"die Insel, -n","en":"island"},{"de":"das Abenteuer, -","en":"adventure"},{"de":"kündigen","en":"to quit (a job)"},{"de":"das Gehalt erhöhen","en":"to raise the salary"},{"de":"die Fantasie","en":"imagination"},{"de":"unbedingt","en":"absolutely"},{"de":"vielleicht","en":"perhaps"},{"de":"an deiner Stelle","en":"in your place"},{"de":"Wie wäre es mit …?","en":"How about …?"},{"de":"Hätten Sie einen Moment Zeit?","en":"Would you have a moment?"}],"reading":"Auf Annas Geburtstagsfeier fragt Leila: „Was würdet ihr machen, wenn ihr eine Million Euro hättet?“ Jonas sagt: „Ich würde sofort kündigen und eine Weltreise machen.“ Anna meint: „Ich hätte gern ein Haus mit Garten. Dann könnten die Kinder draußen spielen.“ Ravi denkt nach: „Wenn ich reich wäre, würde ich meine Eltern nach Berlin einladen. Und ich würde eine kleine Schule in Mumbai bauen.“ Leila lächelt: „Das wäre wirklich schön.“","tasks":[{"q":"Ich ___ gern nach Japan fliegen. (werden)","a":"würde"},{"q":"Wenn ich Zeit ___, würde ich kommen. (haben)","a":"hätte"},{"q":"Wenn er hier ___, wäre alles leichter. (sein)","a":"wäre"},{"q":"___ Sie mir bitte helfen? (können)","a":"Könnten"},{"q":"Ich ___ gern ein Stück Kuchen. (haben)","a":"hätte"},{"q":"Umformen (irreal): Ich habe kein Auto. Ich fahre nicht ans Meer.","a":"Wenn ich ein Auto hätte, würde ich ans Meer fahren."},{"q":"Höflich: Gib mir das Salz!","a":"Könntest du mir bitte das Salz geben?"},{"q":"[Mix] Wenn ich ___ Chef wäre, würde ich ___ Mitarbeitern mehr Urlaub geben. (der, die – Dativ)","a":"der / den"},{"q":"[Mix] Ich würde ___ gern mit dir treffen. (sich)","a":"mich"},{"q":"[Mix] Es wäre schön, wenn du am Samstag ___. (mitkommen)","a":"mitkommen würdest / mitkämst"},{"q":"Wenn ich Zeit ___, ___ ich dich besuchen. (haben / werden)","a":"hätte / würde"},{"q":"Wenn er reich ___, ___ er ein Haus kaufen. (sein / werden)","a":"wäre / würde"},{"q":"___ Sie mir bitte das Salz geben? (können)","a":"Könnten"},{"q":"Ich ___ gern ein Glas Wasser. (haben)","a":"hätte"},{"q":"Du ___ mehr Sport machen. (sollen, Rat)","a":"solltest"},{"q":"Höflich: Gib mir den Stift! → ___ du mir den Stift geben?","a":"Würdest"},{"q":"Irreal: Ich habe kein Auto. → Wenn ich ein Auto ___, …","a":"hätte"},{"q":"Irreal: Sie ist nicht hier. → Wenn sie hier ___, …","a":"wäre"},{"q":"Wunsch: Ich bin nicht am Meer. → Ich wünschte, ich ___ am Meer.","a":"wäre"},{"q":"Fehler? „Wenn ich hätte Zeit, ich würde kommen.“","a":"Wenn ich Zeit hätte, würde ich kommen."}],"exam":[{"q":"Was würde Jonas mit einer Million machen?","a":"Kündigen und eine Weltreise machen."},{"q":"Was hätte Anna gern?","a":"Ein Haus mit Garten."},{"q":"Wen würde Ravi einladen?","a":"Seine Eltern."},{"q":"Höflich: Haben Sie Zeit?","a":"Hätten Sie Zeit?"},{"q":"Irreal: Ich bin nicht krank, ich gehe zur Arbeit. → Wenn …","a":"Wenn ich krank wäre, würde ich nicht zur Arbeit gehen."},{"q":"Ergänze: ___ es möglich, früher zu kommen?","a":"Wäre"},{"q":"Ergänze: Wir ___ uns am Montag treffen. (können, höflich)","a":"könnten"},{"q":"Was würden Sie machen, wenn Sie Bundeskanzler(in) wären?","a":"","m":"Wenn ich Bundeskanzlerin wäre, würde ich mehr Geld für Schulen ausgeben. Ich würde die Bahn billiger machen. Außerdem würde ich mehr für den Klimaschutz tun."},{"q":"Wovon träumen Sie? Beschreiben Sie Ihr Traumleben in 10 Jahren.","a":"","m":"Ich träume von einem kleinen Haus mit Garten. In zehn Jahren hätte ich gern eine eigene Firma. Ich würde viel reisen und meine Familie öfter besuchen."},{"q":"Bitten Sie im Hotel höflich um drei Dinge.","a":"","m":"Könnten Sie mir bitte ein zweites Kissen bringen? Ich hätte gern ein ruhigeres Zimmer. Wäre es möglich, morgen später auszuchecken?"}],"speak":["Was würdest du auf dieser Party machen?","Wenn du Geburtstag hättest, wie würdest du feiern?","Die Party ist zu laut. Bitte die Nachbarn höflich: __Könnten Sie …?__","Wenn du einen Wunsch frei hättest, …"],"reading2":{"title":"Was wäre, wenn …?","text":"Im Deutschkurs spricht Frau Krüger heute über Träume. Sie fragt: „Was würden Sie machen, wenn Sie eine Million Euro gewinnen würden?“ Tomás antwortet sofort: „Ich würde meiner Familie in Brasilien ein Haus kaufen. Dann würde ich ein Jahr lang reisen, zuerst nach Asien, dann nach Australien.“ Aiko ist vorsichtiger. „Ich würde den größten Teil sparen. Aber ich hätte gern ein eigenes Designstudio. Das wäre mein Traum.“ Leila lacht: „Ich würde meinen Job nicht kündigen, denn ich liebe meine Arbeit. Aber ich würde weniger arbeiten und mehr Zeit mit meiner Tochter verbringen.“ Ravi denkt lange nach. „Ehrlich gesagt würde ich mir nicht viel kaufen. Wenn ich so viel Geld hätte, würde ich eine Schule in meinem Heimatdorf bauen. Mein Großvater hatte keine richtige Schule.“ Alle sind still. Dann sagt Frau Krüger: „Das wäre ein wunderbares Projekt. Und wissen Sie was? Für manche Träume braucht man gar keine Million.“ Am Ende der Stunde schreibt jeder einen Text: „Wenn ich ein Jahr frei hätte …“"},"dialog":[{"who":"Jonas","de":"Mia, du siehst gestresst aus. Was ist los?"},{"who":"Mia","de":"Ich habe nächste Woche drei Prüfungen. Ich wünschte, ich hätte mehr Zeit."},{"who":"Jonas","de":"An deiner Stelle würde ich einen Lernplan machen."},{"who":"Mia","de":"Das wäre gut, aber ich weiß nicht, wo ich anfangen soll."},{"who":"Jonas","de":"Wie wäre es, wenn wir den Plan zusammen machen? Ich hätte heute Abend Zeit."},{"who":"Mia","de":"Wirklich? Das wäre super! Könntest du mir auch bei Statistik helfen?"},{"who":"Jonas","de":"Klar. Statistik würde ich sogar gern wiederholen."},{"who":"Mia","de":"Du bist der Beste. Ich würde dich zum Essen einladen, aber ich bin pleite."}],"dq":[{"q":"Warum ist Mia gestresst?","a":"Sie hat nächste Woche drei Prüfungen."},{"q":"Was schlägt Jonas vor?","a":"Einen Lernplan (zusammen) zu machen."},{"q":"Warum lädt Mia Jonas nicht zum Essen ein?","a":"Sie hat kein Geld (ist pleite)."}],"en":{"title":"Subjunctive II: würde, hätte, wäre, könnte","theme":"Wishes and dreams","expl":["The **Konjunktiv II** expresses wishes, dreams, unreal situations and politeness. Usually: **würde + infinitive**: __Ich würde gern reisen.__ = I would like to travel.","sein, haben and the modal verbs have their own forms: **wäre, hätte, könnte, müsste, dürfte, sollte**.","Unreal condition: __Wenn ich Zeit hätte, würde ich mehr Sport machen.__ = If I had time, I would do more sport (but I don\'t have time).","Polite requests: __Könnten Sie mir helfen? Ich hätte gern einen Kaffee.__"],"use":""},"check":[{"re":"\\\\b(würde|würdest|würden|wäre|wären|hätte|hätten|könnte|könnten)\\\\b","label":"Konjunktiv II (würde, wäre, hätte, könnte)"}]},{"n":26,"pos":27,"level":"B1","title":"Ratschläge und Empfehlungen geben","theme":"Probleme lösen","scene":"doctor","rec":[12,19,21,25],"expl":["Für **Ratschläge** gibt es mehrere Strukturen. Von direkt bis höflich:","**Imperativ:** __Geh zum Arzt!__ → **sollte (Konj. II)**: __Du **solltest** zum Arzt gehen.__ → **An deiner Stelle würde ich …** → **Ich empfehle / rate dir, … zu …** → **Es wäre gut / besser, wenn du …** → **Wie wäre es, wenn du …?**","**sollen (Präsens)** = Auftrag von anderen: __Der Arzt sagt, ich **soll** …__. **sollte (Konj. II)** = Rat: __Du **solltest** …__","Nachfragen/Reagieren: __Das ist ein guter Tipp. Das habe ich schon versucht. Meinst du wirklich?__"],"use":"Prüfung (Goethe Teil 3 / telc): Feedback, Tipps geben; Forumsbeitrag schreiben; Alltag.","table":[["Struktur","Beispiel","Stärke"],["Imperativ","Mach eine Pause!","direkt"],["du solltest + Inf.","Du solltest mehr schlafen.","normal"],["An deiner Stelle würde ich …","An deiner Stelle würde ich früher ins Bett gehen.","höflich"],["Ich empfehle dir, … zu + Inf.","Ich empfehle dir, Yoga zu machen.","höflich"],["Es wäre besser, wenn …","Es wäre besser, wenn du weniger Kaffee trinken würdest.","sehr höflich"],["Wie wäre es mit …? / Warum … nicht …?","Wie wäre es mit einem Spaziergang?","Vorschlag"]],"examples":[{"de":"Du solltest mehr Wasser trinken.","en":"You should drink more water."},{"de":"An deiner Stelle würde ich mit dem Chef sprechen.","en":"If I were you, I\'d talk to the boss."},{"de":"Ich empfehle Ihnen, einen Termin zu machen.","en":"I recommend you make an appointment."},{"de":"Es wäre gut, wenn du dich ausruhen würdest.","en":"It would be good if you rested."},{"de":"Warum machst du nicht einen Deutschkurs?","en":"Why don\'t you take a German course?"},{"de":"Ihr solltet nicht so spät ins Bett gehen.","en":"You shouldn\'t go to bed so late."},{"de":"Wie wäre es mit einem Tandempartner?","en":"How about a tandem partner?"},{"de":"Mein Tipp: Hör jeden Tag deutsche Podcasts.","en":"My tip: listen to German podcasts every day."},{"de":"Der Arzt sagt, ich soll weniger Zucker essen.","en":"The doctor says I should eat less sugar."},{"de":"Das ist ein guter Rat, danke!","en":"That\'s good advice, thanks!"},{"de":"Du solltest öfter Pausen machen.","en":"You should take breaks more often."},{"de":"Ich empfehle dir, früher ins Bett zu gehen.","en":"I recommend you go to bed earlier."},{"de":"An deiner Stelle würde ich mit dem Chef sprechen.","en":"If I were you, I\'d talk to the boss."},{"de":"Es wäre besser, wenn du weniger Kaffee trinken würdest.","en":"It would be better if you drank less coffee."},{"de":"Hast du schon mal versucht, ohne Handy einzuschlafen?","en":"Have you ever tried falling asleep without your phone?"},{"de":"Mein Tipp: Mach jeden Tag einen kurzen Spaziergang.","en":"My tip: take a short walk every day."},{"de":"Warum sprichst du nicht offen mit ihm?","en":"Why don\'t you talk to him openly?"},{"de":"Sie sollten Ihren Arzt fragen.","en":"You should ask your doctor."},{"de":"Ich rate dir, die Rechnung sofort zu bezahlen.","en":"I advise you to pay the bill immediately."},{"de":"Das ist eine gute Idee, aber das habe ich schon probiert.","en":"That\'s a good idea, but I\'ve already tried that."}],"vocab":[{"de":"der Rat / der Ratschlag, ¨e","en":"advice"},{"de":"der Tipp, -s","en":"tip"},{"de":"raten (rät)","en":"to advise"},{"de":"empfehlen","en":"to recommend"},{"de":"das Problem, -e","en":"problem"},{"de":"der Stress","en":"stress"},{"de":"schlafen / der Schlaf","en":"to sleep / sleep"},{"de":"die Ernährung","en":"diet, nutrition"},{"de":"sich bewegen","en":"to exercise, move"},{"de":"versuchen","en":"to try"},{"de":"aufhören mit","en":"to stop doing"},{"de":"nützlich","en":"useful"},{"de":"der Ratgeber, -","en":"advice guide"},{"de":"die Lösung, -en","en":"solution"},{"de":"lösen","en":"to solve"},{"de":"vorschlagen","en":"to suggest"},{"de":"probieren","en":"to try"},{"de":"sich Zeit nehmen","en":"to take time"},{"de":"die Pause, -n","en":"break"},{"de":"ausreichend","en":"sufficient"},{"de":"regelmäßig","en":"regularly"},{"de":"der Ärger","en":"trouble, annoyance"},{"de":"der Streit","en":"argument"},{"de":"sich streiten","en":"to argue"},{"de":"sich beruhigen","en":"to calm down"},{"de":"offen sprechen","en":"to speak openly"},{"de":"an deiner Stelle","en":"if I were you"},{"de":"es wäre besser, wenn …","en":"it would be better if …"},{"de":"Ich empfehle dir, … zu …","en":"I recommend you …"},{"de":"Hast du schon mal versucht, …?","en":"Have you ever tried …?"}],"reading":"Jonas schläft schlecht und hat viel Stress. Er fragt Ravi um Rat. Ravi sagt: „Du solltest abends nicht so lange am Handy sein. An deiner Stelle würde ich eine Stunde vor dem Schlafen lesen.“ Leila ist Ärztin und gibt auch Tipps: „Ich empfehle dir, dich mehr zu bewegen. Und es wäre besser, wenn du nach 16 Uhr keinen Kaffee mehr trinken würdest.“ Jonas lacht: „Kein Kaffee? Das ist schwer! Aber ich versuche es.“","tasks":[{"q":"Du ___ mehr schlafen. (sollen, Rat)","a":"solltest"},{"q":"An deiner Stelle ___ ich zu Hause bleiben.","a":"würde"},{"q":"Ich empfehle dir, früher ___ ___. (aufstehen)","a":"aufzustehen"},{"q":"Es wäre besser, wenn du weniger ___ ___. (arbeiten)","a":"arbeiten würdest"},{"q":"Wie wäre es ___ einem Spaziergang?","a":"mit"},{"q":"Umformen (sollte): Geh zum Arzt!","a":"Du solltest zum Arzt gehen."},{"q":"Umformen (An deiner Stelle): Du solltest das Angebot annehmen.","a":"An deiner Stelle würde ich das Angebot annehmen."},{"q":"[Mix] Du solltest ___ nicht so viel ärgern. (sich)","a":"dich"},{"q":"[Mix] Wenn ich du ___, ___ ich mehr Deutsch sprechen. (sein, werden)","a":"wäre / würde"},{"q":"[Mix] Ihr solltet ___ ___ Gesundheit kümmern. (sich, um, eure)","a":"euch / um eure"},{"q":"Rat mit sollen: Du ___ zum Arzt gehen.","a":"solltest"},{"q":"Rat mit sollen: Ihr ___ mehr schlafen.","a":"solltet"},{"q":"Rat mit sollen: Sie (formell) ___ weniger arbeiten.","a":"sollten"},{"q":"An deiner Stelle ___ ich mit ihm sprechen. (werden)","a":"würde"},{"q":"Ich empfehle dir, mehr Wasser ___ trinken.","a":"zu"},{"q":"Ich rate Ihnen, den Termin ___. (absagen)","a":"abzusagen"},{"q":"Es wäre besser, wenn du früher ___ würdest. (aufstehen)","a":"aufstehen"},{"q":"Umformen: Mach mehr Pausen! → Du solltest ___ ___ machen.","a":"mehr Pausen"},{"q":"Umformen: Trink weniger Kaffee! → An deiner Stelle würde ich weniger Kaffee ___.","a":"trinken"},{"q":"Fehler? „Du solltest zu schlafen mehr.“","a":"Du solltest mehr schlafen."}],"exam":[{"q":"Welche Probleme hat Jonas?","a":"Er schläft schlecht und hat Stress."},{"q":"Was soll Jonas vor dem Schlafen machen (Ravi)?","a":"Eine Stunde lesen."},{"q":"Was ist für Jonas schwer?","a":"Nach 16 Uhr keinen Kaffee zu trinken."},{"q":"Gib einen Rat mit „sollte“: Mein Deutsch ist schlecht.","a":"Du solltest jeden Tag üben."},{"q":"Gib einen Rat mit „An deiner Stelle“: Ich habe Zahnschmerzen.","a":"An deiner Stelle würde ich zum Zahnarzt gehen."},{"q":"sollen oder sollte? Der Chef sagt, ich ___ den Bericht schreiben.","a":"soll"},{"q":"Ergänze: Ich rate dir, mehr Obst ___ ___.","a":"zu essen"},{"q":"Ein Freund findet keine Wohnung. Geben Sie 4 Ratschläge.","a":"","m":"Du solltest jeden Tag die Anzeigen lesen. An deiner Stelle würde ich auch Freunde fragen. Es wäre gut, wenn du eine Mappe mit allen Dokumenten hast. Wie wäre es mit einer WG für den Anfang?"},{"q":"Schreiben Sie einen Forumsbeitrag: Tipps für neue Deutschlerner.","a":"","m":"Hallo zusammen! Mein Tipp: Lernt jeden Tag ein bisschen, nicht einmal pro Woche viel. Ihr solltet viel sprechen, auch mit Fehlern. Ich empfehle euch, deutsche Serien mit Untertiteln zu sehen."},{"q":"Welchen Rat würden Sie jemandem geben, der nach Deutschland ziehen möchte?","a":"","m":"Ich würde ihm raten, schon vor dem Umzug Deutsch zu lernen. Er sollte früh eine Wohnung suchen. Außerdem wäre es gut, eine Krankenversicherung abzuschließen."}],"speak":["Welchen Rat gibt die Ärztin dem Patienten?","Der Patient hat Stress. Gib ihm 3 Tipps mit verschiedenen Strukturen.","Was rätst du jemandem, der nicht schlafen kann?","Welcher Rat war für dich im Leben am wichtigsten?"],"reading2":{"title":"Leserbriefe: Frag Frau Doktor","text":"Liebe Frau Doktor Brandt, ich bin 34 Jahre alt und arbeite in einem Callcenter. Seit einigen Monaten schlafe ich sehr schlecht. Ich wache nachts oft auf und denke an die Arbeit. Morgens bin ich müde und tagsüber trinke ich viel Kaffee. Was soll ich tun? Ihr Stefan K. Lieber Stefan, Sie sind nicht allein: Viele Menschen haben Schlafprobleme, besonders wenn sie viel Stress haben. Zuerst sollten Sie nach 15 Uhr keinen Kaffee mehr trinken. Koffein bleibt viele Stunden im Körper. Außerdem empfehle ich Ihnen, jeden Tag zur gleichen Zeit ins Bett zu gehen und aufzustehen, auch am Wochenende. Eine Stunde vor dem Schlafen sollten Sie Handy und Laptop ausmachen. Das blaue Licht macht wach. Hilfreich ist auch, die Gedanken aufzuschreiben: Legen Sie einen Block neben das Bett und notieren Sie, was Sie morgen erledigen müssen. Dann muss Ihr Kopf es nicht mehr behalten. Bewegung am Tag hilft ebenfalls, aber nicht direkt vor dem Schlafen. Wenn das alles nicht hilft, sollten Sie mit Ihrem Hausarzt sprechen. Vielleicht wäre auch ein Gespräch mit Ihrem Arbeitgeber sinnvoll. Ich wünsche Ihnen gute Nächte! Ihre Dr. Brandt"},"dialog":[{"who":"Tomás","de":"Leila, ich habe ein Problem mit meinem Mitbewohner. Er ist total unordentlich."},{"who":"Leila","de":"Was genau macht er denn?"},{"who":"Tomás","de":"Er wäscht nie ab, und seine Sachen liegen überall."},{"who":"Leila","de":"Hast du schon mal mit ihm darüber gesprochen?"},{"who":"Tomás","de":"Nein, ich will keinen Streit."},{"who":"Leila","de":"An deiner Stelle würde ich trotzdem offen mit ihm reden. Ganz ruhig."},{"who":"Tomás","de":"Und wenn das nichts bringt?"},{"who":"Leila","de":"Dann solltet ihr einen Putzplan machen. Jeder hat feste Aufgaben."},{"who":"Tomás","de":"Ein Putzplan … Das ist eine gute Idee. Ich probiere es."}],"dq":[{"q":"Was ist Tomás\' Problem?","a":"Sein Mitbewohner ist unordentlich (wäscht nie ab, lässt Sachen liegen)."},{"q":"Was rät Leila zuerst?","a":"Offen und ruhig mit ihm reden."},{"q":"Was sollen sie machen, wenn das nicht hilft?","a":"Einen Putzplan machen."}],"en":{"title":"Giving advice and recommendations","theme":"Solving problems","expl":["From direct to polite: imperative (__Geh zum Arzt!__) → **solltest** (__Du solltest zum Arzt gehen.__) → __An deiner Stelle würde ich …__ (If I were you …) → __Ich empfehle dir, … zu …__ → __Es wäre besser, wenn du …__ → __Wie wäre es, wenn du …?__","**sollen** in the present = an instruction from someone else: __Der Arzt sagt, ich soll mehr schlafen.__"],"use":""},"check":[{"re":"\\\\b(solltest|sollten|würde ich|an deiner stelle|empfehle|rate|wäre es|wie wäre es)\\\\b","label":"advice structures (du solltest, an deiner Stelle …)"}]},{"n":27,"pos":28,"level":"B1","title":"Vorschläge machen und gemeinsam planen","theme":"Eine Feier organisieren","scene":"party","rec":[13,14,21,25,26],"expl":["Das ist **Prüfungsteil „Gemeinsam etwas planen“**. Du musst **vorschlagen, reagieren, zustimmen/ablehnen, Alternativen nennen** und am Ende **eine Lösung** finden.","**Vorschlagen:** Wie wäre es mit … / wenn wir …? · Was hältst du davon, wenn …? · Wir könnten … · Lass uns … · Sollen wir …? · Ich schlage vor, dass …","**Zustimmen:** Gute Idee! · Einverstanden. · Das machen wir so. **Ablehnen:** Das finde ich nicht so gut, weil … · Ich weiß nicht … · Lieber …","**Einigen:** Also, wir machen es so: … · Wer kümmert sich um …? · Ich übernehme …"],"use":"Goethe Sprechen Teil 1, telc Teil 3: Party, Ausflug, Besuch, Geschenk planen.","table":[["Funktion","Redemittel","Grammatik"],["Vorschlag","Wie wäre es, wenn wir am Samstag feiern würden?","Konj. II + wenn"],["Vorschlag","Was hältst du davon, wenn wir im Park grillen?","wenn-Satz"],["Vorschlag","Lass uns / Wir könnten einen Kuchen backen.","Imperativ / Konj. II"],["Zustimmen","Die Idee gefällt mir, denn …","Dativ + denn"],["Ablehnen","Das finde ich keine gute Idee, weil …","weil-Satz"],["Einigen","Also: Du kaufst die Getränke und ich kümmere mich um das Essen.","Reflexiv + um"]],"examples":[{"de":"Wie wäre es, wenn wir eine Überraschungsparty machen?","en":"How about we throw a surprise party?"},{"de":"Was hältst du davon, wenn wir im Garten feiern?","en":"What do you think about celebrating in the garden?"},{"de":"Lass uns zuerst die Gästeliste schreiben.","en":"Let\'s write the guest list first."},{"de":"Wir könnten Pizza bestellen.","en":"We could order pizza."},{"de":"Das ist eine gute Idee, aber das ist zu teuer.","en":"That\'s a good idea but it\'s too expensive."},{"de":"Ich schlage vor, dass jeder etwas mitbringt.","en":"I suggest everyone brings something."},{"de":"Wer kümmert sich um die Musik?","en":"Who takes care of the music?"},{"de":"Ich übernehme die Einladungen.","en":"I\'ll take care of the invitations."},{"de":"Sollen wir uns um 18 Uhr treffen?","en":"Shall we meet at 6 pm?"},{"de":"Also, dann machen wir es so!","en":"OK, then let\'s do it that way!"},{"de":"Lass uns am Samstag grillen!","en":"Let\'s have a barbecue on Saturday!"},{"de":"Wollen wir zusammen kochen?","en":"Shall we cook together?"},{"de":"Was hältst du davon, wenn jeder etwas mitbringt?","en":"What do you think about everyone bringing something?"},{"de":"Ich schlage vor, dass wir die Kosten teilen.","en":"I suggest that we split the costs."},{"de":"Das klingt gut, aber Samstag passt mir nicht.","en":"That sounds good, but Saturday doesn\'t suit me."},{"de":"Wie wäre es mit Sonntagnachmittag?","en":"How about Sunday afternoon?"},{"de":"Ich kümmere mich um die Getränke.","en":"I\'ll take care of the drinks."},{"de":"Wer übernimmt die Musik?","en":"Who will take care of the music?"},{"de":"Dann machen wir es so.","en":"Then let\'s do it that way."},{"de":"Leider muss ich absagen.","en":"Unfortunately I have to decline."}],"vocab":[{"de":"die Party, -s","en":"party"},{"de":"organisieren","en":"to organise"},{"de":"die Gästeliste, -n","en":"guest list"},{"de":"die Einladung, -en","en":"invitation"},{"de":"die Getränke (Pl.)","en":"drinks"},{"de":"dekorieren","en":"to decorate"},{"de":"mitbringen","en":"to bring along"},{"de":"übernehmen (übernimmt)","en":"to take on"},{"de":"sich kümmern um","en":"to take care of"},{"de":"einverstanden","en":"agreed"},{"de":"der Vorschlag, ¨e","en":"suggestion"},{"de":"die Aufgabe, -n","en":"task"},{"de":"Lass uns …","en":"Let\'s …"},{"de":"Wollen wir …?","en":"Shall we …?"},{"de":"Was hältst du von …?","en":"What do you think of …?"},{"de":"Ich schlage vor, dass …","en":"I suggest that …"},{"de":"Das klingt gut.","en":"That sounds good."},{"de":"Ich bin dagegen.","en":"I\'m against it."},{"de":"einen Kompromiss finden","en":"to find a compromise"},{"de":"sich einigen auf","en":"to agree on"},{"de":"abstimmen über","en":"to vote on"},{"de":"die Stimmung","en":"mood, atmosphere"},{"de":"die Musikanlage, -n","en":"sound system"},{"de":"das Buffet, -s","en":"buffet"},{"de":"der Termin passt","en":"the date suits"},{"de":"absprechen","en":"to coordinate"},{"de":"verteilen","en":"to distribute"},{"de":"die Kosten teilen","en":"to split the costs"},{"de":"zusagen / absagen","en":"to accept / decline (an invitation)"},{"de":"die Überraschungsparty, -s","en":"surprise party"}],"reading":"Frau Berger geht in Rente. Ravi und Mia planen eine Feier im Büro. Mia: „Wie wäre es, wenn wir am Freitagnachmittag feiern?“ – Ravi: „Gute Idee. Was hältst du davon, wenn wir ein Buffet machen?“ – Mia: „Hm, das ist viel Arbeit. Wir könnten doch Essen bestellen.“ – Ravi: „Einverstanden. Und ein Geschenk?“ – Mia: „Ich schlage vor, dass alle Kollegen zehn Euro geben.“ – Ravi: „Gut. Also: Du kümmerst dich um das Geschenk, ich übernehme das Essen und die Einladungen.“","tasks":[{"q":"Wie ___ es mit einem Picknick?","a":"wäre"},{"q":"Was ___ du davon, wenn wir ins Kino gehen?","a":"hältst"},{"q":"___ uns morgen früh losfahren!","a":"Lass"},{"q":"Wir ___ einen Kuchen backen. (können, Vorschlag)","a":"könnten"},{"q":"Ich schlage vor, dass wir den Bus ___. (nehmen)","a":"nehmen"},{"q":"Wer kümmert sich ___ ___ Getränke?","a":"um die"},{"q":"Ablehnen mit weil: Grillen? (es regnet)","a":"Das finde ich nicht so gut, weil es regnet."},{"q":"[Mix] Ich ___ die Einladungen. (übernehmen, Präsens)","a":"übernehme"},{"q":"[Mix] Wir könnten ___ Chefin ___ Blumenstrauß schenken. (die, ein)","a":"der / einen"},{"q":"[Mix] Wie wäre es, wenn wir die Party ___ Samstag ___ 19 Uhr machen würden?","a":"am / um"},{"q":"Vorschlag: ___ uns ins Kino gehen! (lassen)","a":"Lass"},{"q":"Vorschlag mit „Wollen“: Wir kochen zusammen. →","a":"Wollen wir zusammen kochen?"},{"q":"Was hältst du ___, wenn wir früher anfangen?","a":"davon"},{"q":"Ich schlage vor, ___ wir den Bus nehmen.","a":"dass"},{"q":"Ich kümmere mich ___ die Einladungen.","a":"um"},{"q":"Wie wäre es ___ einem Picknick?","a":"mit"},{"q":"Zustimmen: „Das ___ gut!“ (klingen)","a":"klingt"},{"q":"Ablehnen: „Tut mir leid, Samstag ___ mir nicht.“ (passen)","a":"passt"},{"q":"Wir haben uns ___ Sonntag geeinigt.","a":"auf"},{"q":"Fehler? „Ich schlage vor, dass wir gehen ins Restaurant.“","a":"Ich schlage vor, dass wir ins Restaurant gehen."}],"exam":[{"q":"Warum machen Ravi und Mia eine Feier?","a":"Frau Berger geht in Rente."},{"q":"Warum wollen sie kein Buffet machen?","a":"Das ist viel Arbeit."},{"q":"Wer kümmert sich um das Geschenk?","a":"Mia."},{"q":"Mache einen Vorschlag mit „Wie wäre es, wenn …“: zusammen kochen","a":"Wie wäre es, wenn wir zusammen kochen würden?"},{"q":"Reagiere positiv und gib einen Grund.","a":"z. B. Gute Idee, denn das macht Spaß."},{"q":"Reagiere negativ und mache eine Alternative.","a":"z. B. Das finde ich nicht so gut. Lieber …"},{"q":"Formuliere eine Einigung mit zwei Aufgaben.","a":"z. B. Also: Du kaufst …, ich kümmere mich um …"},{"q":"Planen Sie mit Ihrem Partner: Ein Kollege hat ein Baby bekommen. Was schenken Sie? (Geschenk, Kosten, wer kauft, wann übergeben)","a":"","m":"Wir könnten einen Gutschein für einen Babyladen schenken. – Gute Idee! Wie viel soll er kosten? – Vielleicht 50 Euro, jeder gibt 5 Euro. – Einverstanden. Ich kaufe ihn morgen, und du schreibst die Karte. – Super, wir übergeben ihn am Freitag."},{"q":"Planen Sie einen Ausflug mit dem Deutschkurs (Ziel, Datum, Fahrt, Essen).","a":"","m":"Wie wäre es mit einem Ausflug nach Potsdam? – Gute Idee, aber lieber im Mai, dann ist es wärmer. – Einverstanden. Wir fahren mit dem Zug. – Und jeder bringt etwas zu essen mit."},{"q":"Planen Sie einen Besuch bei einer kranken Freundin.","a":"","m":"Sollen wir Mia am Samstag besuchen? – Am Samstag kann ich nicht, lieber am Sonntag. – Gut. Ich bringe Suppe mit. – Und ich kaufe Blumen."}],"speak":["Die Feier ist morgen. Plant zu zweit: Essen, Musik, Deko, Geschenk.","Was fehlt noch auf dem Bild? Mach Vorschläge.","Lehne zwei Vorschläge deines Partners höflich ab und nenne Alternativen.","Fasst am Ende zusammen: __Also, wir machen es so: …__"],"reading2":{"title":"Die Überraschungsparty","text":"Frau Krüger, die Lehrerin des Deutschkurses, geht im Juni in Rente. Die Teilnehmer wollen ihr eine Überraschungsparty organisieren. Aber das ist gar nicht so einfach, denn alle haben andere Ideen. Tomás schlägt vor, in einem Restaurant zu feiern. Aiko ist dagegen: „Das ist zu teuer, und dann können wir nicht frei sprechen.“ Leila hat eine andere Idee: „Lasst uns die Party im Kursraum machen. Jeder bringt ein Gericht aus seinem Land mit. Das wäre ein internationales Buffet!“ Alle finden die Idee toll. Dann müssen die Aufgaben verteilt werden. Ravi übernimmt die Getränke, Tomás kümmert sich um die Musik, Aiko gestaltet eine Karte und ein Fotoalbum. Mia, Leilas Freundin, backt einen Kuchen. Schwierig ist nur der Termin. Frau Krüger darf nichts merken. Leila spricht deshalb heimlich mit der Schulleiterin. Sie einigen sich auf den letzten Kurstag. Die Schulleiterin verspricht, Frau Krüger um zehn Uhr in ihr Büro zu bitten. In dieser Zeit können die Teilnehmer den Raum dekorieren. Am Ende teilen sich alle die Kosten: zwölf Euro pro Person. „Hoffentlich weint sie nicht“, sagt Tomás. „Doch“, sagt Leila, „bestimmt. Aber vor Freude.“"},"dialog":[{"who":"Ravi","de":"Also, Leute, wann wollen wir die Party machen?"},{"who":"Aiko","de":"Wie wäre es mit Freitag, dem letzten Kurstag?"},{"who":"Tomás","de":"Freitag passt mir nicht. Da habe ich eine Prüfung an der Uni."},{"who":"Leila","de":"Und wenn wir nach dem Unterricht feiern, so ab eins? Hast du dann Zeit?"},{"who":"Tomás","de":"Meine Prüfung ist um zwei. Das wird knapp."},{"who":"Ravi","de":"Dann schlage ich vor, dass wir in der großen Pause feiern, um halb elf."},{"who":"Tomás","de":"Das klingt gut. Dann bin ich dabei."},{"who":"Aiko","de":"Einverstanden. Wer spricht mit der Schulleiterin?"},{"who":"Leila","de":"Das übernehme ich."}],"dq":[{"q":"Warum passt Tomás der Freitagnachmittag nicht?","a":"Er hat um zwei Uhr eine Prüfung an der Uni."},{"q":"Wann feiern sie am Ende?","a":"In der großen Pause um halb elf."},{"q":"Wer spricht mit der Schulleiterin?","a":"Leila."}],"en":{"title":"Making suggestions and planning together","theme":"Organising a party","expl":["This is the exam task \\"planning something together\\": suggest, react, agree or disagree, offer alternatives and reach a decision.","Suggest: __Wie wäre es mit …? Wir könnten … Lass uns … Sollen wir …? Ich schlage vor, dass …__ Agree: __Gute Idee! Einverstanden. Das passt mir gut.__ Disagree politely: __Das finde ich nicht so gut, weil … Lieber …__","Always finish with a clear result: __Also, wir machen …__"],"use":""},"check":[{"re":"\\\\b(wie wäre es|was hältst du|wir könnten|lass uns|sollen wir|ich schlage vor|gute idee|einverstanden|lieber)\\\\b","label":"suggesting and reacting (Wir könnten …, Gute Idee!)"}]},{"n":28,"pos":29,"level":"B1","title":"Infinitiv mit zu","theme":"Lernen und Weiterbildung","scene":"classroom","rec":[21,25,26,27],"expl":["Nach vielen Verben, Nomen und Adjektiven folgt ein **Infinitiv mit zu** am **Satzende**: __Ich habe keine Lust, **zu kochen**.__","**Nach Verben:** anfangen, aufhören, versuchen, vergessen, vorhaben, hoffen, beschließen, sich freuen, empfehlen, bitten, erlauben, verbieten.","**Nach Nomen + haben:** Lust, Zeit, Angst, Spaß, die Möglichkeit. **Nach es ist + Adjektiv:** wichtig, schwer, leicht, schön, verboten.","**Trennbare Verben:** zu in der Mitte: an**zu**rufen, auf**zu**stehen. Mit Modalverb **kein zu**: __Ich muss lernen.__","Wenn Subjekt gleich ist → zu-Infinitiv statt dass-Satz: __Ich hoffe, dass ich bestehe = Ich hoffe, die Prüfung **zu bestehen**.__"],"use":"Prüfung: Meinung (Es ist wichtig, … zu …), Pläne (Ich habe vor, …), Gefühle.","table":[["Auslöser","Hauptsatz","zu-Infinitiv (Ende)"],["Verb","Ich versuche,","jeden Tag Deutsch **zu sprechen**."],["Verb (trennbar)","Vergiss nicht,","mich **anzurufen**."],["Nomen","Ich habe keine Zeit,","ins Kino **zu gehen**."],["Adjektiv","Es ist wichtig,","pünktlich **zu sein**."],["Perfekt-Inhalt","Ich freue mich,","dich kennengelernt **zu haben**."]],"examples":[{"de":"Ich habe vor, die B1-Prüfung im Dezember zu machen.","en":"I plan to take the B1 exam in December."},{"de":"Es ist nicht leicht, eine neue Sprache zu lernen.","en":"It\'s not easy to learn a new language."},{"de":"Ravi hat angefangen, deutsche Bücher zu lesen.","en":"Ravi has started reading German books."},{"de":"Vergiss nicht, die Hausaufgaben zu machen!","en":"Don\'t forget to do the homework!"},{"de":"Ich habe keine Lust, heute zu lernen.","en":"I don\'t feel like studying today."},{"de":"Es macht Spaß, mit Leila Deutsch zu sprechen.","en":"It\'s fun to speak German with Leila."},{"de":"Hast du Zeit, mir kurz zu helfen?","en":"Do you have time to help me quickly?"},{"de":"Die Lehrerin empfiehlt uns, Filme auf Deutsch anzusehen.","en":"The teacher recommends we watch films in German."},{"de":"Ich hoffe, die Prüfung zu bestehen.","en":"I hope to pass the exam."},{"de":"Er hat Angst, Fehler zu machen.","en":"He\'s afraid of making mistakes."},{"de":"Ich habe angefangen, Spanisch zu lernen.","en":"I\'ve started learning Spanish."},{"de":"Vergiss nicht, dich für den Kurs anzumelden!","en":"Don\'t forget to register for the course!"},{"de":"Es ist wichtig, jeden Tag zu üben.","en":"It\'s important to practise every day."},{"de":"Hast du Lust, mit mir ins Museum zu gehen?","en":"Do you feel like going to the museum with me?"},{"de":"Er versucht, jeden Tag zehn neue Wörter zu lernen.","en":"He tries to learn ten new words every day."},{"de":"Ich habe keine Zeit, die Hausaufgaben zu machen.","en":"I have no time to do the homework."},{"de":"Sie hat aufgehört zu rauchen.","en":"She has stopped smoking."},{"de":"Es macht Spaß, mit anderen zusammen zu lernen.","en":"It\'s fun to learn together with others."},{"de":"Ich habe vor, im Herbst die B1-Prüfung zu machen.","en":"I\'m planning to take the B1 exam in autumn."},{"de":"Es ist nicht leicht, nach der Arbeit noch zu lernen.","en":"It isn\'t easy to study after work."}],"vocab":[{"de":"die Weiterbildung, -en","en":"further training"},{"de":"die Prüfung, -en","en":"exam"},{"de":"bestehen","en":"to pass"},{"de":"durchfallen","en":"to fail"},{"de":"üben","en":"to practise"},{"de":"wiederholen","en":"to revise, repeat"},{"de":"der Fehler, -","en":"mistake"},{"de":"vorhaben","en":"to plan"},{"de":"beschließen","en":"to decide"},{"de":"die Lust","en":"desire, mood"},{"de":"die Möglichkeit, -en","en":"possibility"},{"de":"das Zertifikat, -e","en":"certificate"},{"de":"anfangen zu","en":"to begin to"},{"de":"versuchen zu","en":"to try to"},{"de":"vergessen zu","en":"to forget to"},{"de":"aufhören zu","en":"to stop (doing)"},{"de":"es ist wichtig, … zu …","en":"it is important to …"},{"de":"es ist schwer, … zu …","en":"it is hard to …"},{"de":"Lust haben, … zu …","en":"to feel like …"},{"de":"Zeit haben, … zu …","en":"to have time to …"},{"de":"die Gelegenheit, -en","en":"opportunity"},{"de":"der Abendkurs, -e","en":"evening class"},{"de":"die Volkshochschule (VHS)","en":"adult education centre"},{"de":"die Anmeldung, -en","en":"registration"},{"de":"die Kursgebühr, -en","en":"course fee"},{"de":"die Teilnahmebescheinigung, -en","en":"certificate of attendance"},{"de":"sich anmelden für","en":"to register for"},{"de":"fördern","en":"to support, to promote"},{"de":"der Fortschritt, -e","en":"progress"},{"de":"motiviert","en":"motivated"}],"reading":"Ravi hat beschlossen, im Dezember die B1-Prüfung zu machen. Es ist wichtig für ihn, das Zertifikat zu bekommen, denn er hat vor, sich später um eine bessere Stelle zu bewerben. Frau Klein empfiehlt ihm, jeden Tag zu üben. Manchmal hat Ravi keine Lust, nach der Arbeit noch zu lernen. Aber er versucht, jeden Abend eine halbe Stunde Deutsch zu hören. Leila hilft ihm. Es macht ihm Spaß, mit ihr zu sprechen, und er hat keine Angst mehr, Fehler zu machen.","tasks":[{"q":"Ich versuche, mehr ___ ___. (lesen)","a":"zu lesen"},{"q":"Vergiss nicht, das Fenster ___. (zumachen)","a":"zuzumachen"},{"q":"Es ist wichtig, genug Wasser ___ ___. (trinken)","a":"zu trinken"},{"q":"Ich habe keine Zeit, ___. (einkaufen)","a":"einzukaufen"},{"q":"Wir haben vor, nach Italien ___ ___. (fahren)","a":"zu fahren"},{"q":"zu oder nicht? Ich möchte ___ schwimmen.","a":"(kein zu)"},{"q":"Umformen: Ich hoffe, dass ich die Prüfung bestehe.","a":"Ich hoffe, die Prüfung zu bestehen."},{"q":"[Mix] Es macht mir Spaß, ___ ___ Freunden ___ ___. (mit, meine, kochen)","a":"mit meinen / zu kochen"},{"q":"[Mix] Ich habe angefangen, ___ jeden Morgen ___ ___. (sich, bewegen)","a":"mich / zu bewegen"},{"q":"[Mix] Es wäre schön, dich wieder ___ ___. (sehen)","a":"zu sehen"},{"q":"Ich habe keine Lust, heute ___ kochen.","a":"zu"},{"q":"Es ist wichtig, pünktlich ___ sein.","a":"zu"},{"q":"Vergiss nicht, den Müll ___. (rausbringen)","a":"rauszubringen"},{"q":"Er versucht, früher ___. (aufstehen)","a":"aufzustehen"},{"q":"Ich habe vor, nach Wien ___. (fahren)","a":"zu fahren"},{"q":"Sie hat angefangen, Gitarre ___ spielen.","a":"zu"},{"q":"Mit Modalverb kein zu: Ich muss heute ___. (arbeiten)","a":"arbeiten"},{"q":"Umformen: Ich lerne Deutsch. Es macht mir Spaß. → Es macht mir Spaß, Deutsch ___ ___.","a":"zu lernen"},{"q":"Umformen: Ich rufe dich an. Ich vergesse es nicht. → Ich vergesse nicht, dich ___.","a":"anzurufen"},{"q":"Fehler? „Ich habe keine Zeit zu ins Kino gehen.“","a":"Ich habe keine Zeit, ins Kino zu gehen."}],"exam":[{"q":"Warum will Ravi das Zertifikat?","a":"Er will sich später um eine bessere Stelle bewerben."},{"q":"Was empfiehlt Frau Klein?","a":"Jeden Tag zu üben."},{"q":"Wovor hat Ravi keine Angst mehr?","a":"Fehler zu machen."},{"q":"Ergänze: Hast du Lust, heute Abend ___ ___? (ausgehen)","a":"auszugehen"},{"q":"Umformen: Ich freue mich, dass ich dich sehe.","a":"Ich freue mich, dich zu sehen."},{"q":"Ergänze: Es ist verboten, hier ___ ___. (rauchen)","a":"zu rauchen"},{"q":"Fehler? „Ich kann gut zu kochen.“","a":"Ich kann gut kochen."},{"q":"Was ist für Sie wichtig beim Deutschlernen? (Es ist wichtig, … zu …)","a":"","m":"Es ist wichtig, jeden Tag zu üben. Es ist auch wichtig, keine Angst vor Fehlern zu haben. Ich versuche, viel mit Deutschen zu sprechen."},{"q":"Was haben Sie für das nächste Jahr vor?","a":"","m":"Ich habe vor, die B1-Prüfung zu machen. Außerdem plane ich, eine neue Wohnung zu suchen. Ich hoffe, mehr Zeit für meine Familie zu haben."},{"q":"Wozu haben Sie manchmal keine Lust? Was machen Sie dann?","a":"","m":"Manchmal habe ich keine Lust, Hausaufgaben zu machen. Dann versuche ich, nur zehn Minuten zu lernen. Oft mache ich danach weiter."}],"speak":["Was haben die Leute im Kurs vor? __Sie haben vor, …__","Was ist schwer / leicht beim Deutschlernen? __Es ist schwer, … zu …__","Was hast du vergessen zu machen?","Was macht dir Spaß zu lernen?"],"reading2":{"title":"Lernen ein Leben lang","text":"In Deutschland ist es ganz normal, auch nach der Schule und der Ausbildung weiterzulernen. Viele Menschen besuchen Kurse an der Volkshochschule, kurz VHS. Dort kann man fast alles lernen: Sprachen, Kochen, Fotografieren, Computerprogramme oder Yoga. Die Kurse finden meistens abends oder am Wochenende statt, damit auch Berufstätige teilnehmen können. Die Gebühren sind relativ niedrig. Auch viele Arbeitgeber fördern die Weiterbildung ihrer Mitarbeiter. Sie bezahlen zum Beispiel einen Sprachkurs oder geben den Angestellten frei, um ein Seminar zu besuchen. Herr Petrović ist 52 und arbeitet als Busfahrer. Vor einem Jahr hat er angefangen, Englisch zu lernen. „Ich hatte schon lange vor, Englisch zu lernen, aber ich hatte nie Zeit“, erzählt er. „Jetzt sind meine Kinder groß, und ich habe endlich die Gelegenheit.“ Am Anfang war es nicht leicht, nach einem langen Arbeitstag noch Vokabeln zu wiederholen. „Aber es macht mir Spaß, mit anderen Menschen zu lernen. Und letzten Sommer habe ich zum ersten Mal versucht, in London nach dem Weg zu fragen. Es hat funktioniert!“ Herr Petrović plant schon den nächsten Kurs. Er hat Lust, auch noch Italienisch zu lernen."},"dialog":[{"who":"Mitarbeiterin","de":"Volkshochschule Mitte, guten Tag."},{"who":"Ravi","de":"Guten Tag. Ich möchte mich für einen Deutschkurs anmelden. Ist es noch möglich, in den B1-Abendkurs zu kommen?"},{"who":"Mitarbeiterin","de":"Einen Moment … Ja, es gibt noch drei freie Plätze."},{"who":"Ravi","de":"Wann findet der Kurs statt?"},{"who":"Mitarbeiterin","de":"Dienstags und donnerstags von 18 bis 20:15 Uhr."},{"who":"Ravi","de":"Und wie hoch ist die Kursgebühr?"},{"who":"Mitarbeiterin","de":"240 Euro für zwölf Wochen. Vergessen Sie nicht, sich online zu registrieren."},{"who":"Ravi","de":"Bekomme ich am Ende eine Bescheinigung?"},{"who":"Mitarbeiterin","de":"Ja, wenn Sie an mindestens achtzig Prozent der Termine teilnehmen."}],"dq":[{"q":"Wann findet der Kurs statt?","a":"Dienstags und donnerstags von 18 bis 20:15 Uhr."},{"q":"Was kostet der Kurs?","a":"240 Euro für zwölf Wochen."},{"q":"Wann bekommt man eine Bescheinigung?","a":"Wenn man an mindestens 80 % der Termine teilnimmt."}],"en":{"title":"Infinitive with zu","theme":"Learning and further education","expl":["After many verbs, nouns and adjectives comes an **infinitive with zu** at the end of the sentence: __Ich habe keine Lust zu kochen.__ = I don\'t feel like cooking.","After verbs like anfangen, aufhören, versuchen, vergessen, vorhaben, hoffen, beschließen; after nouns with haben (Lust, Zeit, Angst, Spaß); after __es ist wichtig/schwer/schön__.","Separable verbs put zu in the middle: __anzurufen, aufzustehen__. Modal verbs never take zu: __Ich muss arbeiten.__"],"use":""},"check":[{"re":"\\\\bzu \\\\w+(en|n)\\\\b|\\\\b\\\\w+zu\\\\w+en\\\\b","label":"zu + infinitive"}]},{"n":29,"pos":30,"level":"B1","title":"Finalsätze: um … zu und damit","theme":"Ziele und Zwecke","scene":"office","rec":[21,24,28],"expl":["**Finalsätze** nennen das **Ziel** (Wozu? / Warum?).","**um … zu + Infinitiv** – wenn das **Subjekt in beiden Teilen gleich** ist: __**Ich** lerne Deutsch, **um** in Deutschland **zu arbeiten**.__","**damit + Nebensatz** – wenn die **Subjekte verschieden** sind (bei gleichen Subjekten auch möglich): __Ich erkläre es langsam, **damit du** es **verstehst**.__","Im damit-Satz **kein Modalverb** wollen/sollen/können nötig. Frage: **Wozu?** Auch: **für + Nomen**: __für die Prüfung__."],"use":"Pläne und Motivation begründen (Präsentation, Bewerbung).","table":[["Subjekte","Hauptsatz","Finalsatz"],["gleich","Ravi spart Geld,","**um** nach Indien **zu fliegen**."],["gleich (trennbar)","Ich gehe früh ins Bett,","**um** früh **aufzustehen**."],["verschieden","Ravi spart Geld,","**damit** seine Eltern ihn **besuchen** können."],["verschieden","Sprich langsam,","**damit** ich dich **verstehe**."],["Nomen","Ich lerne","**für** die Prüfung."]],"examples":[{"de":"Ich lerne Deutsch, um bessere Chancen zu haben.","en":"I learn German to have better chances."},{"de":"Ravi macht Überstunden, um mehr Geld zu verdienen.","en":"Ravi works overtime to earn more money."},{"de":"Ich schreibe alles auf, damit ich nichts vergesse.","en":"I write everything down so that I don\'t forget anything."},{"de":"Die Chefin erklärt es noch einmal, damit alle es verstehen.","en":"The boss explains it again so everyone understands."},{"de":"Wozu brauchst du den Laptop? – Um zu arbeiten.","en":"What do you need the laptop for? – To work."},{"de":"Wir fahren früh los, um den Zug nicht zu verpassen.","en":"We leave early so as not to miss the train."},{"de":"Ich rufe dich an, damit du Bescheid weißt.","en":"I\'ll call you so you know."},{"de":"Er geht ins Fitnessstudio, um abzunehmen.","en":"He goes to the gym to lose weight."},{"de":"Anna kocht vor, damit die Kinder etwas essen können.","en":"Anna prepares food so the kids can eat."},{"de":"Ich brauche das Zertifikat für meine Bewerbung.","en":"I need the certificate for my application."},{"de":"Ich lerne Deutsch, um in Deutschland zu studieren.","en":"I\'m learning German in order to study in Germany."},{"de":"Er spart Geld, damit seine Kinder studieren können.","en":"He\'s saving money so that his children can study."},{"de":"Sie macht eine Fortbildung, um befördert zu werden.","en":"She\'s doing a training course in order to be promoted."},{"de":"Wozu brauchst du einen Führerschein? – Um aufs Land zu fahren.","en":"What do you need a driving licence for? – To drive to the countryside."},{"de":"Ich schreibe es auf, damit ich es nicht vergesse.","en":"I\'m writing it down so that I don\'t forget it."},{"de":"Wir gehen früh los, um den Zug nicht zu verpassen.","en":"We\'re leaving early so as not to miss the train."},{"de":"Er erklärt es langsam, damit alle es verstehen.","en":"He explains it slowly so that everyone understands it."},{"de":"Um ein Konto zu eröffnen, braucht man einen Ausweis.","en":"To open an account you need an ID."},{"de":"Ich rufe an, um mich über den Kurs zu informieren.","en":"I\'m calling to find out about the course."},{"de":"Sie gibt ihm den Schlüssel, damit er die Pflanzen gießen kann.","en":"She gives him the key so that he can water the plants."}],"vocab":[{"de":"das Ziel, -e","en":"goal"},{"de":"der Zweck, -e","en":"purpose"},{"de":"wozu","en":"what for"},{"de":"die Chance, -n","en":"chance"},{"de":"sparen","en":"to save"},{"de":"verpassen","en":"to miss"},{"de":"Bescheid wissen / sagen","en":"to know / let know"},{"de":"aufschreiben","en":"to write down"},{"de":"die Karriere, -n","en":"career"},{"de":"die Beförderung, -en","en":"promotion"},{"de":"sich vorbereiten auf","en":"to prepare for"},{"de":"erreichen","en":"to reach, achieve"},{"de":"um … zu","en":"in order to"},{"de":"damit","en":"so that"},{"de":"die Absicht, -en","en":"intention"},{"de":"der Grund, ¨e","en":"reason"},{"de":"die Fortbildung, -en","en":"training course"},{"de":"der Führerschein, -e","en":"driving licence"},{"de":"die Fahrschule, -n","en":"driving school"},{"de":"das Konto, Konten","en":"(bank) account"},{"de":"eröffnen","en":"to open (an account)"},{"de":"sich erkundigen","en":"to enquire"},{"de":"sich informieren über","en":"to find out about"},{"de":"überweisen","en":"to transfer (money)"},{"de":"die Wohnungssuche","en":"flat hunting"},{"de":"der Nachweis, -e","en":"proof"},{"de":"die Kaution, -en","en":"deposit"},{"de":"der Mietvertrag, ¨e","en":"tenancy agreement"},{"de":"dafür","en":"for that (purpose)"},{"de":"zu diesem Zweck","en":"for this purpose"}],"reading":"Ravi hat ein großes Ziel: Er möchte Teamleiter werden. Um dieses Ziel zu erreichen, macht er einen Managementkurs. Er lernt auch weiter Deutsch, damit er besser mit den Kunden sprechen kann. Seine neue Kollegin Mia hilft ihm, damit er die Präsentationen gut vorbereitet. Ravi spart auch Geld, um im Dezember nach Mumbai zu fliegen. Er ruft seine Eltern jede Woche an, damit sie sich keine Sorgen machen.","tasks":[{"q":"Ich lerne viel, ___ die Prüfung ___ ___. (bestehen)","a":"um / zu bestehen"},{"q":"Ich spreche laut, ___ alle mich hören.","a":"damit"},{"q":"Er spart, ___ ein Auto ___ ___. (kaufen)","a":"um / zu kaufen"},{"q":"Wir helfen ihm, ___ er schneller fertig ist.","a":"damit"},{"q":"Sie steht früh auf, um pünktlich ___ ___. (sein)","a":"zu sein"},{"q":"Verbinde (um…zu): Ich gehe zum Bäcker. Ich kaufe Brot.","a":"Ich gehe zum Bäcker, um Brot zu kaufen."},{"q":"Verbinde (damit): Ich gebe dir meine Nummer. Du kannst mich anrufen.","a":"Ich gebe dir meine Nummer, damit du mich anrufen kannst."},{"q":"[Mix] Ich fahre ___ Bahnhof, um meine Mutter ___. (zu + der, abholen)","a":"zum / abzuholen"},{"q":"[Mix] Wir müssen früh losfahren, damit wir den Zug nicht ___. (verpassen)","a":"verpassen"},{"q":"[Mix] Es ist wichtig, Geld zu sparen, ___ man im Urlaub mehr hat.","a":"damit"},{"q":"Ich gehe zur Bank, ___ Geld abzuheben. (um/damit)","a":"um"},{"q":"Er spricht laut, ___ alle ihn hören. (um/damit)","a":"damit"},{"q":"Wir nehmen ein Taxi, um pünktlich ___ sein.","a":"zu"},{"q":"Verbinde mit um … zu: Ich lerne viel. Ich will die Prüfung bestehen.","a":"Ich lerne viel, um die Prüfung zu bestehen."},{"q":"Verbinde mit damit: Ich gebe dir meine Nummer. Du kannst mich anrufen.","a":"Ich gebe dir meine Nummer, damit du mich anrufen kannst."},{"q":"Verbinde mit um … zu: Sie fährt nach Berlin. Sie besucht ihre Freundin.","a":"Sie fährt nach Berlin, um ihre Freundin zu besuchen."},{"q":"Verbinde mit damit: Die Mutter kocht. Die Kinder haben etwas zu essen.","a":"Die Mutter kocht, damit die Kinder etwas zu essen haben."},{"q":"Frage nach dem Zweck: ___ brauchst du das Geld?","a":"Wozu"},{"q":"Trennbares Verb: Ich komme früher, um dir ___. (helfen)","a":"zu helfen"},{"q":"Fehler? „Ich spare Geld, um ich ein Auto kaufe.“","a":"Ich spare Geld, um ein Auto zu kaufen."}],"exam":[{"q":"Welches Ziel hat Ravi?","a":"Teamleiter werden."},{"q":"Warum lernt er weiter Deutsch?","a":"Damit er besser mit den Kunden sprechen kann."},{"q":"Warum ruft er seine Eltern an?","a":"Damit sie sich keine Sorgen machen."},{"q":"um…zu oder damit? Ich trinke Kaffee, ___ wach ___ ___.","a":"um / zu bleiben"},{"q":"um…zu oder damit? Ich mache das Licht an, ___ du lesen kannst.","a":"damit"},{"q":"Frage: „Um Deutsch zu lernen.“ → ?","a":"Wozu / Warum … ?"},{"q":"Umformen: Ich lerne, damit ich die Prüfung bestehe. (um…zu)","a":"Ich lerne, um die Prüfung zu bestehen."},{"q":"Welche Ziele haben Sie für die nächsten 5 Jahre? Wie wollen Sie sie erreichen?","a":"","m":"In den nächsten fünf Jahren möchte ich C1 erreichen. Um das zu schaffen, lerne ich jeden Tag. Ich spare Geld, damit ich eine Wohnung kaufen kann."},{"q":"Wozu braucht man heute ein Smartphone? Nennen Sie 5 Zwecke.","a":"","m":"Man braucht ein Smartphone, um zu telefonieren, um Nachrichten zu schreiben, um Fotos zu machen, um im Internet zu suchen und um den Weg zu finden."},{"q":"Was machen Sie, damit Ihre Familie glücklich ist?","a":"","m":"Ich arbeite viel, damit meine Kinder eine gute Ausbildung bekommen. Ich koche am Wochenende, damit wir zusammen essen."}],"speak":["Wozu sitzt die Frau am Computer? (Vermutung)","Wozu gehen Menschen ins Büro, statt zu Hause zu arbeiten?","Was tust du, um gesund zu bleiben?","Was machst du, damit deine Kollegen / Freunde dich mögen?"],"reading2":{"title":"Ein neues Leben in Leipzig","text":"Aiko hat eine neue Stelle in Leipzig bekommen. Um dort anzufangen, muss sie viel organisieren. Zuerst sucht sie eine Wohnung. Um schneller etwas zu finden, schaut sie jeden Morgen auf drei Internetportalen. Sie schreibt den Vermietern sofort, damit sie zu den ersten Bewerbern gehört. Für die Bewerbung braucht sie mehrere Unterlagen: einen Gehaltsnachweis, damit der Vermieter weiß, dass sie die Miete bezahlen kann, und eine Bescheinigung von ihrem alten Vermieter. Nach drei Wochen hat sie Glück: eine kleine Zweizimmerwohnung in der Südvorstadt. Um den Mietvertrag zu unterschreiben, fährt sie extra nach Leipzig. Die Kaution beträgt drei Monatsmieten. Damit sie die Kaution bezahlen kann, leiht ihr Vater ihr etwas Geld. Dann muss sie sich beim Bürgeramt anmelden. Um einen Termin zu bekommen, ruft sie schon zwei Wochen vorher an. Außerdem eröffnet sie ein Konto bei einer Bank in Leipzig, damit ihr neuer Arbeitgeber das Gehalt überweisen kann. Zum Schluss meldet sie sich in einem Sportverein an, um schnell neue Leute kennenzulernen. „Umziehen ist anstrengend“, sagt Aiko, „aber ich freue mich auf den Neuanfang.“"},"dialog":[{"who":"Bankberaterin","de":"Guten Tag, was kann ich für Sie tun?"},{"who":"Aiko","de":"Ich möchte ein Girokonto eröffnen, damit mein Arbeitgeber mein Gehalt überweisen kann."},{"who":"Bankberaterin","de":"Gern. Haben Sie Ihren Ausweis dabei?"},{"who":"Aiko","de":"Ja, hier ist mein Reisepass. Und meine Meldebescheinigung."},{"who":"Bankberaterin","de":"Sehr gut. Um das Konto online zu nutzen, brauchen Sie noch unsere App."},{"who":"Aiko","de":"Kostet das Konto etwas?"},{"who":"Bankberaterin","de":"Fünf Euro im Monat. Damit Sie es kostenlos bekommen, müssen jeden Monat mindestens tausend Euro eingehen."},{"who":"Aiko","de":"Das ist kein Problem. Mein Gehalt ist höher."}],"dq":[{"q":"Warum möchte Aiko ein Konto eröffnen?","a":"Damit ihr Arbeitgeber das Gehalt überweisen kann."},{"q":"Welche Dokumente hat sie dabei?","a":"Ihren Reisepass und ihre Meldebescheinigung."},{"q":"Wann ist das Konto kostenlos?","a":"Wenn jeden Monat mindestens 1000 Euro eingehen."}],"en":{"title":"Purpose clauses: um … zu and damit","theme":"Goals and purposes","expl":["Purpose clauses answer \\"what for?\\" (Wozu?). **um … zu** + infinitive when both parts have the **same subject**: __Ich lerne Deutsch, um in Deutschland zu arbeiten.__ = I learn German (in order) to work in Germany.","**damit** + subordinate clause when the subjects are **different**: __Ich erkläre es langsam, damit du es verstehst.__ Don\'t use a modal verb like wollen in a damit-clause."],"use":""},"check":[{"re":"\\\\bum\\\\b[^.!?]*\\\\bzu \\\\w+en\\\\b|\\\\bdamit\\\\b","label":"um … zu or damit"}]},{"n":30,"pos":31,"level":"B1","title":"ohne … zu / (an)statt … zu","theme":"Gewohnheiten","scene":"kitchen","rec":[28,29],"expl":["**ohne … zu + Infinitiv** = etwas passiert nicht (without doing): __Er geht, **ohne** tschüss **zu sagen**.__","**(an)statt … zu + Infinitiv** = etwas passiert statt einer anderen Sache (instead of doing): __**Statt** zu kochen, bestellt er Pizza.__","Bei **verschiedenen Subjekten**: **ohne dass / statt dass** + Nebensatz: __Er nimmt das Auto, **ohne dass** sein Vater es **weiß**.__","Das Komma steht vor ohne/statt. Trennbare Verben: ohne an**zu**rufen."],"use":"Gewohnheiten kritisieren, Alternativen nennen, Geschichten erzählen.","table":[["Struktur","Beispiel","Bedeutung"],["ohne … zu","Sie isst, ohne zu sprechen.","without speaking"],["ohne … zu (trennbar)","Er kommt, ohne vorher anzurufen.","without calling"],["statt … zu","Statt zu lernen, sieht er fern.","instead of learning"],["ohne dass","Ich bin gegangen, ohne dass es jemand gemerkt hat.","without anyone noticing"],["statt dass","Statt dass er hilft, schläft er.","instead of him helping"]],"examples":[{"de":"Max isst, ohne die Hände zu waschen.","en":"Max eats without washing his hands."},{"de":"Statt zu kochen, bestellen wir Essen.","en":"Instead of cooking, we order food."},{"de":"Ravi ist ins Büro gegangen, ohne zu frühstücken.","en":"Ravi went to the office without having breakfast."},{"de":"Man sollte nicht einkaufen, ohne eine Liste zu schreiben.","en":"You shouldn\'t shop without writing a list."},{"de":"Anstatt den Bus zu nehmen, fahre ich Rad.","en":"Instead of taking the bus I cycle."},{"de":"Er hat den Kuchen gegessen, ohne dass ich es gesehen habe.","en":"He ate the cake without me seeing."},{"de":"Statt Fleisch zu essen, isst Ravi Linsen.","en":"Instead of eating meat, Ravi eats lentils."},{"de":"Sie hat das Handy gekauft, ohne den Preis zu vergleichen.","en":"She bought the phone without comparing prices."},{"de":"Statt im Bett zu liegen, geh doch spazieren!","en":"Instead of lying in bed, go for a walk!"},{"de":"Ohne zu üben, kann man kein Instrument lernen.","en":"Without practising you can\'t learn an instrument."},{"de":"Er geht aus dem Haus, ohne zu frühstücken.","en":"He leaves the house without having breakfast."},{"de":"Statt den Aufzug zu nehmen, gehe ich die Treppe hoch.","en":"Instead of taking the lift, I walk up the stairs."},{"de":"Sie hat das Formular unterschrieben, ohne es zu lesen.","en":"She signed the form without reading it."},{"de":"Anstatt zu lernen, hat er den ganzen Abend gespielt.","en":"Instead of studying, he played all evening."},{"de":"Ich habe mir angewöhnt, jeden Morgen Wasser zu trinken.","en":"I\'ve got into the habit of drinking water every morning."},{"de":"Er möchte sich das Rauchen abgewöhnen.","en":"He wants to give up smoking."},{"de":"Statt Chips zu essen, nimm doch einen Apfel!","en":"Instead of eating crisps, why not take an apple!"},{"de":"Wir sind losgefahren, ohne die Tür abzuschließen.","en":"We drove off without locking the door."},{"de":"Mein Vorsatz: weniger Bildschirmzeit, mehr Schlaf.","en":"My resolution: less screen time, more sleep."},{"de":"Es ist schwer, durchzuhalten.","en":"It\'s hard to keep it up."}],"vocab":[{"de":"die Gewohnheit, -en","en":"habit"},{"de":"gesund / ungesund","en":"healthy / unhealthy"},{"de":"bestellen","en":"to order"},{"de":"das Fertiggericht, -e","en":"ready meal"},{"de":"die Liste, -n","en":"list"},{"de":"merken","en":"to notice"},{"de":"vergleichen","en":"to compare"},{"de":"der Preis, -e","en":"price"},{"de":"die Linsen (Pl.)","en":"lentils"},{"de":"vorbereiten","en":"to prepare"},{"de":"frisch","en":"fresh"},{"de":"selbst","en":"oneself"},{"de":"ohne … zu","en":"without (doing)"},{"de":"statt … zu / anstatt … zu","en":"instead of (doing)"},{"de":"die Angewohnheit, -en","en":"habit (often bad)"},{"de":"der Vorsatz, ¨e","en":"resolution"},{"de":"der Alltag","en":"everyday life"},{"de":"die Routine, -n","en":"routine"},{"de":"das Handy weglegen","en":"to put the phone away"},{"de":"der Bildschirm, -e","en":"screen"},{"de":"die Bildschirmzeit","en":"screen time"},{"de":"der Snack, -s","en":"snack"},{"de":"naschen","en":"to nibble sweets"},{"de":"die Treppe, -n","en":"stairs"},{"de":"der Aufzug, ¨e","en":"lift"},{"de":"zu Fuß gehen","en":"to walk"},{"de":"sich angewöhnen","en":"to get into the habit of"},{"de":"sich abgewöhnen","en":"to break the habit of"},{"de":"durchhalten","en":"to persevere"},{"de":"rückfällig werden","en":"to relapse"}],"reading":"Jonas hat schlechte Gewohnheiten. Oft geht er ins Büro, ohne zu frühstücken. Statt frisch zu kochen, isst er Fertiggerichte. Ravi sagt: „Statt jeden Tag Pizza zu bestellen, könntest du mit mir kochen!“ Am Samstag kochen sie zusammen. Jonas probiert das Curry, ohne zu fragen, wie scharf es ist. Sein Gesicht wird rot! Ravi gibt ihm Joghurt, ohne dass Jonas etwas sagen muss. Seitdem kocht Jonas öfter selbst.","tasks":[{"q":"Er geht, ___ tschüss ___ ___. (sagen)","a":"ohne / zu sagen"},{"q":"___ zu arbeiten, spielt er am Handy.","a":"Statt"},{"q":"Sie kauft ein, ohne eine Liste ___ ___. (schreiben)","a":"zu schreiben"},{"q":"Er kommt, ohne vorher ___. (anrufen)","a":"anzurufen"},{"q":"Statt ___ Bus ___ ___, gehe ich zu Fuß. (der, nehmen)","a":"den / zu nehmen"},{"q":"Verbinde (ohne…zu): Er fährt weg. Er tankt nicht.","a":"Er fährt weg, ohne zu tanken."},{"q":"Verbinde (ohne dass): Sie geht. Ihr Mann merkt es nicht.","a":"Sie geht, ohne dass ihr Mann es merkt."},{"q":"[Mix] Statt ___ ___ ärgern, solltest du ___ entspannen. (sich ×2, du)","a":"dich zu / dich"},{"q":"[Mix] Ich habe das Buch gelesen, um ___ ___ Prüfung vorzubereiten. (sich, auf die)","a":"mich auf die"},{"q":"[Mix] Er ist gegangen, ohne ___ Kollegen ___ ___. (seine, helfen – Dativ!)","a":"seinen Kollegen zu helfen"},{"q":"Er geht weg, ___ sich zu verabschieden. (ohne/statt)","a":"ohne"},{"q":"___ zu arbeiten, schläft er. (Ohne/Statt)","a":"Statt"},{"q":"Verbinde mit ohne … zu: Sie fährt los. Sie tankt nicht.","a":"Sie fährt los, ohne zu tanken."},{"q":"Verbinde mit statt … zu: Ich nehme die Treppe. Ich nehme nicht den Aufzug.","a":"Ich nehme die Treppe, statt den Aufzug zu nehmen."},{"q":"Verbinde mit ohne … zu: Er antwortet. Er überlegt nicht.","a":"Er antwortet, ohne zu überlegen."},{"q":"Verbinde mit anstatt … zu: Wir gehen spazieren. Wir sehen nicht fern.","a":"Wir gehen spazieren, anstatt fernzusehen."},{"q":"Trennbar: Sie ging, ohne die Tür ___. (zumachen)","a":"zuzumachen"},{"q":"Ich möchte mir das Naschen ___. (abgewöhnen)","a":"abgewöhnen"},{"q":"Ich habe mir ___, früh aufzustehen. (angewöhnen, Perfekt)","a":"angewöhnt"},{"q":"Fehler? „Er hat gegessen ohne zu bezahlen er.“","a":"Er hat gegessen, ohne zu bezahlen."}],"exam":[{"q":"Was macht Jonas oft falsch?","a":"Er geht ohne Frühstück ins Büro / isst Fertiggerichte."},{"q":"Was schlägt Ravi vor?","a":"Zusammen kochen statt Pizza zu bestellen."},{"q":"Was passiert beim Curry?","a":"Es ist zu scharf, Jonas\' Gesicht wird rot."},{"q":"Umformen: Er lernt nicht. Er schläft. (statt … zu)","a":"Statt zu lernen, schläft er."},{"q":"Umformen: Sie kauft das Kleid. Sie probiert es nicht an. (ohne … zu)","a":"Sie kauft das Kleid, ohne es anzuprobieren."},{"q":"ohne zu oder ohne dass? Ich habe gegessen, ___ die Kinder etwas ___.","a":"ohne dass / gemerkt haben"},{"q":"Ergänze: Statt ___ Auto ___ ___, fahre ich Rad. (das, nehmen)","a":"das Auto zu nehmen"},{"q":"Welche Gewohnheiten möchten Sie ändern? Was machen Sie statt …?","a":"","m":"Ich möchte weniger am Handy sein. Statt abends Serien zu sehen, möchte ich lesen. Statt mit dem Auto zu fahren, nehme ich öfter das Fahrrad."},{"q":"Was machen viele Menschen, ohne nachzudenken?","a":"","m":"Viele Menschen kaufen Dinge, ohne nachzudenken. Sie essen schnell, ohne zu schmecken. Viele klicken auf „Akzeptieren“, ohne die Bedingungen zu lesen."},{"q":"Was sollte man nie tun, ohne vorher zu fragen?","a":"","m":"Man sollte nie das Handy von anderen nehmen, ohne vorher zu fragen. Man sollte auch nie Fotos von Menschen posten, ohne zu fragen."}],"speak":["Was machen die Personen in der Küche? Kochen sie oder bestellen sie?","Was machst du oft, ohne zu überlegen?","Was machst du lieber, statt fernzusehen?","Gesund leben: Was sollte man statt … tun?"],"reading2":{"title":"Neue Gewohnheiten – so klappt es","text":"Jedes Jahr im Januar fassen Millionen Menschen gute Vorsätze: mehr Sport, gesünder essen, weniger Zeit am Handy. Doch schon im Februar haben die meisten wieder aufgegeben. Warum ist es so schwer, Gewohnheiten zu ändern? Unser Gehirn liebt Routinen. Viele Dinge tun wir automatisch, ohne darüber nachzudenken: Wir greifen zum Handy, statt aus dem Fenster zu schauen, oder wir nehmen den Aufzug, ohne an die Treppe zu denken. Experten empfehlen deshalb, klein anzufangen. Statt sich vorzunehmen, jeden Tag eine Stunde zu joggen, sollte man lieber mit zehn Minuten beginnen. Hilfreich ist es auch, eine neue Gewohnheit an eine alte zu koppeln: Nach dem Zähneputzen macht man zum Beispiel fünf Kniebeugen. Wer sich etwas abgewöhnen will, sollte es sich schwer machen. Wer abends weniger am Handy sein möchte, kann es in die Küche legen, statt es mit ins Schlafzimmer zu nehmen. Und wenn man doch einmal rückfällig wird? „Kein Problem“, sagt die Psychologin Dr. Lena Vogt. „Wichtig ist, nicht gleich aufzugeben. Ein schlechter Tag macht keine schlechte Gewohnheit.“ Nach etwa zwei Monaten, so die Forschung, läuft eine neue Gewohnheit fast automatisch."},"dialog":[{"who":"Mia","de":"Jonas, du isst schon wieder Chips, statt zu kochen?"},{"who":"Jonas","de":"Ich hatte keine Zeit. Ich bin direkt vom Büro zum Sofa."},{"who":"Mia","de":"Du wolltest doch gesünder leben. Das war dein Vorsatz!"},{"who":"Jonas","de":"Ich weiß. Aber ich komme nach Hause und esse, ohne nachzudenken."},{"who":"Mia","de":"Dann kauf einfach keine Chips mehr. Leg stattdessen Obst auf den Tisch."},{"who":"Jonas","de":"Und wenn ich trotzdem Lust auf Chips habe?"},{"who":"Mia","de":"Dann gehst du zum Kiosk. Zu Fuß. Das ist gleichzeitig Sport."},{"who":"Jonas","de":"Sehr witzig. Aber vielleicht hast du recht."}],"dq":[{"q":"Was macht Jonas, statt zu kochen?","a":"Er isst Chips."},{"q":"Was war Jonas\' Vorsatz?","a":"Gesünder zu leben."},{"q":"Was soll Jonas statt Chips auf den Tisch legen?","a":"Obst."}],"en":{"title":"ohne … zu / (an)statt … zu","theme":"Habits","expl":["**ohne … zu** = without doing something: __Er geht, ohne tschüss zu sagen.__ = He leaves without saying goodbye.","**(an)statt … zu** = instead of doing something: __Statt zu kochen, bestellt er Pizza.__ = Instead of cooking, he orders pizza.","With different subjects: **ohne dass / statt dass** + subordinate clause: __Er nimmt das Auto, ohne dass sein Vater es weiß.__"],"use":""},"check":[{"re":"\\\\b(ohne|statt|anstatt)\\\\b[^.!?]*\\\\bzu\\\\b|\\\\b(ohne|statt) dass\\\\b","label":"ohne … zu / statt … zu"}]},{"n":31,"pos":32,"level":"B1","title":"Verben mit Präpositionen + da- und wo-Wörter","theme":"Gefühle und Interessen","scene":"classroom","rec":[6,13,16,19,21,28],"expl":["Viele Verben haben eine **feste Präposition** mit festem Fall. Lerne sie als Einheit: **warten auf + Akk.**, **denken an + Akk.**, **sich freuen auf/über + Akk.**, **Angst haben vor + Dat.**, **träumen von + Dat.**, **teilnehmen an + Dat.**, **sprechen mit + Dat. über + Akk.**","**Frage:** Person → Präposition + **Pronomen** (__Auf **wen** wartest du?__). Sache → **wo(r)** + Präposition (__**Worauf** wartest du?__).","**Antwort/Verweis:** Person → Präp. + Pronomen (__auf **ihn**__). Sache → **da(r)** + Präp. (__**darauf**__). **r** wenn die Präposition mit Vokal beginnt: wo**r**an, da**r**über.","**da-Wort + dass/zu:** __Ich freue mich **darauf**, **dass** du kommst / dich **zu** sehen.__"],"use":"Interessen, Gefühle, Meinungen – und Nachfragen in der Prüfung (Worüber sprichst du?).","table":[["Verb + Präp.","Fall","Frage (Sache / Person)","Antwort (Sache / Person)"],["warten auf","Akk.","Worauf? / Auf wen?","darauf / auf ihn"],["sich interessieren für","Akk.","Wofür? / Für wen?","dafür / für sie"],["denken an","Akk.","Woran? / An wen?","daran / an ihn"],["sprechen über","Akk.","Worüber? / Über wen?","darüber / über ihn"],["Angst haben vor","Dat.","Wovor? / Vor wem?","davor / vor ihm"],["träumen von","Dat.","Wovon? / Von wem?","davon / von ihr"]],"examples":[{"de":"Ich warte auf den Bus. – Ich warte schon lange darauf.","en":"I\'m waiting for the bus. – I\'ve been waiting for it a long time."},{"de":"Worüber habt ihr gesprochen?","en":"What did you talk about?"},{"de":"Ravi denkt oft an seine Eltern.","en":"Ravi often thinks of his parents."},{"de":"Ich interessiere mich für Geschichte.","en":"I\'m interested in history."},{"de":"Hast du Angst vor der Prüfung? – Nein, keine Angst davor.","en":"Are you afraid of the exam? – No."},{"de":"Leila träumt von einer eigenen Praxis.","en":"Leila dreams of her own practice."},{"de":"Mit wem hast du telefoniert?","en":"Who did you talk to on the phone?"},{"de":"Ich freue mich darauf, dich zu sehen.","en":"I\'m looking forward to seeing you."},{"de":"Er nimmt an einem Kurs teil.","en":"He\'s taking part in a course."},{"de":"Kannst du dich um die Blumen kümmern? – Ja, ich kümmere mich darum.","en":"Can you look after the flowers? – Yes, I\'ll take care of it."},{"de":"Worauf freust du dich am meisten? – Auf die Ferien.","en":"What are you looking forward to most? – The holidays."},{"de":"Ich freue mich darauf, dich zu sehen.","en":"I\'m looking forward to seeing you."},{"de":"Wofür interessierst du dich? – Für Politik.","en":"What are you interested in? – Politics."},{"de":"An wen denkst du? – An meine Oma.","en":"Who are you thinking of? – My grandma."},{"de":"Ich ärgere mich über den Lärm. Du ärgerst dich auch darüber?","en":"I\'m annoyed about the noise. You\'re annoyed about it too?"},{"de":"Kann ich mich auf dich verlassen?","en":"Can I rely on you?"},{"de":"Der Film handelt von einer Familie in Berlin.","en":"The film is about a family in Berlin."},{"de":"Es hängt vom Wetter ab, ob wir grillen.","en":"It depends on the weather whether we have a barbecue."},{"de":"Sie ist sehr stolz auf ihren Sohn.","en":"She is very proud of her son."},{"de":"Worüber habt ihr gesprochen?","en":"What did you talk about?"}],"vocab":[{"de":"warten auf","en":"to wait for"},{"de":"denken an","en":"to think of"},{"de":"sich erinnern an","en":"to remember"},{"de":"sprechen über","en":"to talk about"},{"de":"sich beschweren über","en":"to complain about"},{"de":"Angst haben vor","en":"to be afraid of"},{"de":"träumen von","en":"to dream of"},{"de":"teilnehmen an","en":"to take part in"},{"de":"sich verabreden mit","en":"to arrange to meet"},{"de":"sich entschuldigen bei / für","en":"to apologise to / for"},{"de":"bitten um","en":"to ask for"},{"de":"sich gewöhnen an","en":"to get used to"},{"de":"sich interessieren für","en":"to be interested in"},{"de":"sich freuen auf","en":"to look forward to"},{"de":"sich freuen über","en":"to be pleased about"},{"de":"sich ärgern über","en":"to be annoyed about"},{"de":"sich kümmern um","en":"to take care of"},{"de":"sich verlassen auf","en":"to rely on"},{"de":"sich bedanken für","en":"to say thank you for"},{"de":"sich bewerben um","en":"to apply for"},{"de":"sich konzentrieren auf","en":"to concentrate on"},{"de":"sich sorgen um","en":"to worry about"},{"de":"achten auf","en":"to pay attention to"},{"de":"abhängen von","en":"to depend on"},{"de":"gehören zu","en":"to be part of"},{"de":"handeln von","en":"to be about"},{"de":"nachdenken über","en":"to think about"},{"de":"reagieren auf","en":"to react to"},{"de":"stolz sein auf","en":"to be proud of"},{"de":"zufrieden sein mit","en":"to be satisfied with"}],"reading":"Im Kurs sprechen die Teilnehmer über ihre Gefühle. Frau Klein fragt: „Woran denkt ihr, wenn ihr an eure Heimat denkt?“ Ravi sagt: „Ich denke an das Essen und an meine Familie. Ich träume oft davon, mit ihnen am Strand zu sitzen.“ Leila erzählt: „Am Anfang hatte ich Angst vor dem Winter. Aber ich habe mich daran gewöhnt.“ Frau Klein fragt: „Und worauf freut ihr euch?“ Ravi: „Ich freue mich auf Dezember, denn da besuche ich meine Eltern.“","tasks":[{"q":"Ich warte ___ ___ Zug.","a":"auf den"},{"q":"Er interessiert sich ___ Musik.","a":"für"},{"q":"___ denkst du? – An meinen Urlaub.","a":"Woran"},{"q":"___ wem sprichst du? – Mit Anna.","a":"Mit"},{"q":"Hast du Angst vor Spinnen? – Ja, ich habe Angst ___.","a":"davor"},{"q":"Freust du dich auf die Reise? – Ja, ich freue mich sehr ___.","a":"darauf"},{"q":"Denkst du an deinen Bruder? – Ja, ich denke oft an ___.","a":"ihn"},{"q":"[Mix] Ich habe mich ___ ___ Nachbarn über den Lärm beschwert. (bei, der)","a":"bei dem / beim"},{"q":"[Mix] Ich erinnere mich gern ___, wie wir als Kinder gespielt haben.","a":"daran"},{"q":"[Mix] Wir haben ___ ___ Prüfung gesprochen. (über, die)","a":"über die"},{"q":"Ich warte ___ den Bus.","a":"auf"},{"q":"Sie denkt oft ___ ihre Familie.","a":"an"},{"q":"Wir sprechen ___ das Wetter.","a":"über"},{"q":"Er interessiert sich ___ Kunst.","a":"für"},{"q":"Frage nach Sache: Ich freue mich auf das Wochenende. → ___ freust du dich?","a":"Worauf"},{"q":"Frage nach Person: Ich denke an meinen Bruder. → ___ ___ denkst du?","a":"An wen"},{"q":"da-Wort: Ärgerst du dich über den Lärm? – Ja, ich ärgere mich ___.","a":"darüber"},{"q":"da-Wort: Interessierst du dich für Fußball? – Nein, ich interessiere mich nicht ___.","a":"dafür"},{"q":"Das hängt ___ dir ab.","a":"von"},{"q":"Fehler? „Ich freue mich für die Ferien im Sommer.“","a":"Ich freue mich auf die Ferien im Sommer."}],"exam":[{"q":"Woran denkt Ravi, wenn er an seine Heimat denkt?","a":"An das Essen und seine Familie."},{"q":"Wovor hatte Leila Angst?","a":"Vor dem Winter."},{"q":"Worauf freut sich Ravi?","a":"Auf Dezember (Besuch bei seinen Eltern)."},{"q":"Frage: Ich spreche über das Wetter.","a":"Worüber sprichst du?"},{"q":"Frage: Ich warte auf meine Freundin.","a":"Auf wen wartest du?"},{"q":"Antwort mit da-: Interessierst du dich für Politik?","a":"Ja, ich interessiere mich dafür. / Nein, …"},{"q":"Ergänze: Er träumt ___ ___ großen Haus.","a":"von einem"},{"q":"Wofür interessieren Sie sich? Worüber ärgern Sie sich?","a":"","m":"Ich interessiere mich für Technik und für Fußball. Ich ärgere mich über unpünktliche Züge. Darüber spreche ich oft mit meinen Kollegen."},{"q":"Woran erinnern Sie sich gern aus Ihrer Kindheit?","a":"","m":"Ich erinnere mich gern an die Sommerferien bei meinen Großeltern. Ich denke oft an die Mangos aus ihrem Garten."},{"q":"Wovor haben viele Menschen Angst? Und Sie?","a":"","m":"Viele Menschen haben Angst vor Krankheiten oder vor der Zukunft. Ich habe ein bisschen Angst vor Prüfungen."}],"speak":["Worüber sprechen die Leute im Kurs? (Vermutung)","Frag den Partner mit wo-Wörtern: __Wofür …? Worauf …? Woran …?__","Worauf freust du dich nach der Prüfung?","An was musstest du dich in einem neuen Land / einer neuen Stadt gewöhnen?"],"reading2":{"title":"Was uns glücklich macht","text":"Eine Zeitschrift hat Menschen gefragt: Worüber freuen Sie sich im Alltag? Worüber ärgern Sie sich? Hier einige Antworten. Monika, 67, Rentnerin: „Ich freue mich jeden Tag über meinen Garten. Und ich freue mich auf die Wochenenden, wenn meine Enkel kommen. Ärgern? Ich ärgere mich über Leute, die ihren Müll in den Park werfen.“ Deniz, 24, Student: „Ich interessiere mich sehr für Musik und spiele in einer Band. Ich bin stolz darauf, dass wir bald unser erstes Konzert haben. Was mich ärgert? Wenn die Bahn wieder Verspätung hat. Darüber rege ich mich fast jeden Tag auf.“ Petra, 45, Krankenschwester: „Ich kümmere mich den ganzen Tag um andere Menschen. Deshalb freue ich mich über ruhige Abende mit einem Buch. Ich ärgere mich darüber, dass Pflegekräfte so wenig verdienen.“ Karim, 38, Taxifahrer: „Mein Glück hängt nicht von Geld ab. Ich bin zufrieden mit meinem Leben, wenn meine Familie gesund ist. Ich denke oft an meine Eltern in Marokko und telefoniere jeden Sonntag mit ihnen. Darauf freue ich mich die ganze Woche.“ Die Umfrage zeigt: Es sind oft die kleinen Dinge, die zählen."},"dialog":[{"who":"Leila","de":"Ravi, du siehst so glücklich aus! Worüber freust du dich?"},{"who":"Ravi","de":"Ich habe die Zusage von GreenTech bekommen!"},{"who":"Leila","de":"Wirklich? Herzlichen Glückwunsch! Darauf hast du so lange gewartet."},{"who":"Ravi","de":"Ja, ich kann es noch gar nicht glauben. Ich habe mich um die Stelle beworben und jetzt …"},{"who":"Leila","de":"Und worauf freust du dich am meisten?"},{"who":"Ravi","de":"Auf das Team. Und darauf, dass ich endlich in meinem Bereich arbeiten kann."},{"who":"Leila","de":"Wann fängst du an?"},{"who":"Ravi","de":"Am ersten Oktober. Aber ich muss mich noch um viele Dinge kümmern."}],"dq":[{"q":"Worüber freut sich Ravi?","a":"Über die Zusage von GreenTech."},{"q":"Worauf freut er sich am meisten?","a":"Auf das Team (und darauf, in seinem Bereich zu arbeiten)."},{"q":"Wann fängt Ravi an?","a":"Am ersten Oktober."}],"en":{"title":"Verbs with prepositions + da- and wo- words","theme":"Feelings and interests","expl":["Many verbs have a **fixed preposition with a fixed case** – learn them as one unit: warten auf + acc. (wait for), denken an + acc. (think of), sich freuen auf + acc. (look forward to), Angst haben vor + dat. (be afraid of), träumen von + dat. (dream of).","Asking about a **person**: preposition + wen/wem: __Auf wen wartest du?__ About a **thing**: **wo(r)** + preposition: __Worauf wartest du?__","Referring back to a thing: **da(r)** + preposition: __Ich warte darauf.__ = I\'m waiting for it."],"use":""},"check":[{"re":"\\\\b(wo|da)r?(auf|an|über|für|von|mit|vor|nach|um)\\\\b|\\\\b(interessiere|freue|ärgere|erinnere|denke|warte|träume|habe angst)\\\\b","label":"verb + preposition (sich interessieren für, sich erinnern an …)"}]},{"n":32,"pos":33,"level":"B1","title":"Indirekte Fragen","theme":"Behörden und Informationen","scene":"office","rec":[4,21,25,31],"expl":["Indirekte Fragen sind **Nebensätze**: Das Verb steht **am Ende**. Sie sind **höflicher** als direkte Fragen.","**W-Frage** → das W-Wort bleibt: __Wann kommt der Bus?__ → __Können Sie mir sagen, **wann** der Bus **kommt**?__","**Ja/Nein-Frage** → **ob**: __Ist das Büro offen?__ → __Wissen Sie, **ob** das Büro offen **ist**?__","Einleitungen: Können Sie mir sagen, … · Wissen Sie, … · Ich möchte wissen, … · Ich frage mich, … · Weißt du zufällig, … Nach „Ich weiß nicht, …“ steht ein **Punkt**, keine Frage."],"use":"Bei Behörden, am Telefon, Informationen erfragen – sehr höflich.","table":[["Direkte Frage","Indirekte Frage"],["Wo ist das Bürgeramt?","Können Sie mir sagen, wo das Bürgeramt **ist**?"],["Welche Unterlagen brauche ich?","Ich möchte wissen, welche Unterlagen ich **brauche**."],["Muss ich einen Termin machen?","Wissen Sie, ob ich einen Termin machen **muss**?"],["Wann hat das Amt geöffnet?","Könnten Sie mir sagen, wann das Amt geöffnet **hat**?"],["Hat er angerufen?","Ich weiß nicht, ob er angerufen **hat**."]],"examples":[{"de":"Können Sie mir sagen, wo die Toiletten sind?","en":"Can you tell me where the toilets are?"},{"de":"Wissen Sie, ob ich hier parken darf?","en":"Do you know whether I can park here?"},{"de":"Ich möchte wissen, wie lange die Anmeldung dauert.","en":"I\'d like to know how long registration takes."},{"de":"Weißt du zufällig, wann der Kurs anfängt?","en":"Do you happen to know when the course starts?"},{"de":"Ich frage mich, warum er nicht gekommen ist.","en":"I wonder why he didn\'t come."},{"de":"Könnten Sie mir erklären, was ich hier ausfüllen muss?","en":"Could you explain what I have to fill in here?"},{"de":"Ich weiß nicht, ob ich Zeit habe.","en":"I don\'t know whether I have time."},{"de":"Darf ich fragen, wie viel das kostet?","en":"May I ask how much that costs?"},{"de":"Sie hat gefragt, wer mitkommt.","en":"She asked who\'s coming along."},{"de":"Wissen Sie, welcher Bus zum Rathaus fährt?","en":"Do you know which bus goes to the town hall?"},{"de":"Können Sie mir sagen, wo das Bürgeramt ist?","en":"Can you tell me where the citizens\' office is?"},{"de":"Wissen Sie, wann die Behörde geöffnet hat?","en":"Do you know when the office is open?"},{"de":"Ich möchte wissen, ob ich einen Termin brauche.","en":"I\'d like to know whether I need an appointment."},{"de":"Weißt du, wie viel der Ausweis kostet?","en":"Do you know how much the ID card costs?"},{"de":"Ich frage mich, warum das so lange dauert.","en":"I wonder why it takes so long."},{"de":"Könnten Sie mir erklären, welche Unterlagen ich mitbringen muss?","en":"Could you explain which documents I need to bring?"},{"de":"Er hat gefragt, ob wir das Formular schon ausgefüllt haben.","en":"He asked whether we\'ve already filled in the form."},{"de":"Wer ist für Aufenthaltstitel zuständig?","en":"Who is responsible for residence permits?"},{"de":"Ich weiß nicht, an wen ich mich wenden soll.","en":"I don\'t know who to turn to."},{"de":"Können Sie mir sagen, wie lange die Bearbeitung dauert?","en":"Can you tell me how long processing takes?"}],"vocab":[{"de":"die Behörde, -n","en":"authority"},{"de":"das Amt, ¨er","en":"office (public)"},{"de":"das Bürgeramt","en":"citizens\' office"},{"de":"die Anmeldung, -en","en":"registration"},{"de":"das Formular, -e","en":"form"},{"de":"ausfüllen","en":"to fill in"},{"de":"die Unterlagen (Pl.)","en":"documents"},{"de":"der Ausweis, -e","en":"ID card"},{"de":"der Reisepass, ¨e","en":"passport"},{"de":"die Aufenthaltserlaubnis","en":"residence permit"},{"de":"unterschreiben","en":"to sign"},{"de":"die Wartenummer, -n","en":"queue number"},{"de":"wissen, ob","en":"to know whether"},{"de":"fragen, wann/wo/wie","en":"to ask when/where/how"},{"de":"Können Sie mir sagen, …?","en":"Can you tell me …?"},{"de":"Wissen Sie, …?","en":"Do you know …?"},{"de":"Ich möchte wissen, …","en":"I would like to know …"},{"de":"Ich frage mich, …","en":"I wonder …"},{"de":"die Meldebescheinigung, -en","en":"registration certificate"},{"de":"die Steuer-ID","en":"tax ID"},{"de":"die Krankenversicherung, -en","en":"health insurance"},{"de":"der Antrag, ¨e","en":"application (form)"},{"de":"einen Antrag stellen","en":"to submit an application"},{"de":"die Gebühr, -en","en":"fee"},{"de":"der Schalter, -","en":"counter"},{"de":"zuständig sein für","en":"to be responsible for"},{"de":"die Öffnungszeiten (Pl.)","en":"opening hours"},{"de":"verlängern","en":"to extend"},{"de":"die Bescheinigung, -en","en":"certificate"},{"de":"beglaubigt","en":"certified"}],"reading":"Ravi muss sich ummelden. Er ruft beim Bürgeramt an: „Guten Tag. Können Sie mir sagen, wann Sie geöffnet haben? Und ich möchte wissen, ob ich einen Termin brauche.“ – „Ja, Sie brauchen einen Termin. Den können Sie online buchen.“ – „Wissen Sie auch, welche Unterlagen ich mitbringen muss?“ – „Ihren Reisepass und die Bestätigung vom Vermieter.“ – „Darf ich noch fragen, wie lange es dauert?“ – „Ungefähr zehn Minuten.“ – „Vielen Dank!“","tasks":[{"q":"Wo ist die Post? → Wissen Sie, wo die Post ___?","a":"ist"},{"q":"Wann beginnt der Film? → Weißt du, wann der Film ___?","a":"beginnt"},{"q":"Ist Herr Weber da? → Können Sie mir sagen, ___ Herr Weber da ist?","a":"ob"},{"q":"Wie viel kostet das? → Ich möchte wissen, ___ ___ das kostet.","a":"wie viel"},{"q":"Kommt er mit? → Ich frage mich, ___ er ___.","a":"ob / mitkommt"},{"q":"Wo hast du das gekauft? → Sag mir, wo du das ___ ___.","a":"gekauft hast"},{"q":"Muss ich zahlen? → Wissen Sie, ob ich ___ ___?","a":"zahlen muss"},{"q":"[Mix] Können Sie mir sagen, ___ ___ Formular ich ausfüllen muss? (welch-, das)","a":"welches"},{"q":"[Mix] Ich weiß nicht, ___ ___ ich mich wenden soll. (an, wer)","a":"an wen"},{"q":"[Mix] Wissen Sie, ___ ich mich beschweren kann? (bei wem / wo)","a":"bei wem / wo"},{"q":"Indirekte Frage: Wo ist der Bahnhof? → Können Sie mir sagen, ___ ___ ___ ___?","a":"wo der Bahnhof ist"},{"q":"Indirekte Frage: Wann beginnt der Kurs? → Wissen Sie, ___ ___ ___ ___?","a":"wann der Kurs beginnt"},{"q":"Indirekte Frage: Hat die Bank geöffnet? → Ich weiß nicht, ___ ___ ___ ___ ___.","a":"ob die Bank geöffnet hat"},{"q":"Indirekte Frage: Wie viel kostet das? → Weißt du, ___ ___ ___ ___?","a":"wie viel das kostet"},{"q":"Indirekte Frage: Brauche ich einen Termin? → Ich möchte wissen, ob ich einen Termin ___.","a":"brauche"},{"q":"Indirekte Frage: Wer ist zuständig? → Können Sie mir sagen, wer ___ ___?","a":"zuständig ist"},{"q":"ob oder wenn? Ich weiß nicht, ___ er heute kommt.","a":"ob"},{"q":"Trennbar: Wann kommt der Zug an? → Wissen Sie, wann der Zug ___?","a":"ankommt"},{"q":"Modalverb: Wo kann ich parken? → Können Sie mir sagen, wo ich ___ ___?","a":"parken kann"},{"q":"Fehler? „Können Sie mir sagen, wo ist die Toilette?“","a":"Können Sie mir sagen, wo die Toilette ist?"}],"exam":[{"q":"Warum ruft Ravi an?","a":"Er muss sich ummelden."},{"q":"Braucht er einen Termin?","a":"Ja."},{"q":"Welche Unterlagen braucht er?","a":"Reisepass und Bestätigung vom Vermieter."},{"q":"Indirekt: Wo wohnen Sie? (Darf ich fragen, …)","a":"Darf ich fragen, wo Sie wohnen?"},{"q":"Indirekt: Fährt dieser Bus zum Zoo? (Wissen Sie, …)","a":"Wissen Sie, ob dieser Bus zum Zoo fährt?"},{"q":"Indirekt: Warum ist der Zug zu spät? (Ich möchte wissen, …)","a":"Ich möchte wissen, warum der Zug zu spät ist."},{"q":"Fehler? „Können Sie mir sagen, wo ist der Bahnhof?“","a":"…, wo der Bahnhof ist?"},{"q":"Rufen Sie bei einer Sprachschule an und fragen Sie indirekt nach 4 Informationen.","a":"","m":"Guten Tag, können Sie mir sagen, wann der nächste Kurs beginnt? Ich möchte auch wissen, wie viel der Kurs kostet. Wissen Sie, ob man dort eine Prüfung machen kann? Und könnten Sie mir sagen, wie groß die Gruppen sind?"},{"q":"Sie sind im Bürgeramt. Fragen Sie höflich, was Sie tun müssen.","a":"","m":"Entschuldigung, können Sie mir sagen, was ich für die Anmeldung brauche? Wissen Sie, ob ich einen Termin machen muss?"},{"q":"Welche Erfahrungen haben Sie mit Behörden gemacht?","a":"","m":"Meine Erfahrungen mit Behörden sind gemischt. Die Mitarbeiter waren meistens freundlich, aber ich musste lange warten. Ich wusste oft nicht, welche Formulare ich brauche."}],"speak":["Die Frau arbeitet im Amt. Stelle ihr 4 indirekte Fragen.","Was möchtest du über das Leben in Deutschland wissen? __Ich möchte wissen, ob …__","Ich frage mich oft, … (3 Sätze)","Frag deinen Partner indirekt nach seinem Wochenende."],"reading2":{"title":"Anmeldung in Deutschland – was man wissen muss","text":"Wer nach Deutschland zieht, muss sich innerhalb von zwei Wochen beim Bürgeramt anmelden. Viele Neuankömmlinge fragen sich, wie das funktioniert und welche Unterlagen sie brauchen. Zuerst sollte man herausfinden, welches Bürgeramt zuständig ist. In großen Städten kann man meistens jedes Bürgeramt der Stadt wählen. Man braucht fast immer einen Termin, den man online buchen kann. In Berlin ist es manchmal schwierig, schnell einen Termin zu bekommen. Ein Tipp: Morgens früh nachsehen, ob neue Termine freigeschaltet wurden. Zur Anmeldung muss man den Pass oder Personalausweis mitbringen, das ausgefüllte Anmeldeformular und die Wohnungsgeberbestätigung. Das ist ein Dokument vom Vermieter, das bestätigt, dass man wirklich dort wohnt. Viele wissen nicht, dass die Anmeldung kostenlos ist. Nach der Anmeldung bekommt man eine Meldebescheinigung. Diese braucht man später für viele andere Dinge: um ein Bankkonto zu eröffnen, einen Handyvertrag abzuschließen oder sich bei der Krankenversicherung anzumelden. Einige Wochen später kommt außerdem ein Brief mit der Steuer-Identifikationsnummer per Post. Wer nicht weiß, ob alle Unterlagen vollständig sind, kann vorher bei der Behörde anrufen und nachfragen."},"dialog":[{"who":"Mitarbeiter","de":"Guten Tag, die Wartenummer 147? Bitte nehmen Sie Platz."},{"who":"Leila","de":"Guten Tag. Ich möchte wissen, ob ich hier meine Aufenthaltserlaubnis verlängern kann."},{"who":"Mitarbeiter","de":"Nein, dafür ist die Ausländerbehörde zuständig, nicht das Bürgeramt."},{"who":"Leila","de":"Ach so. Können Sie mir sagen, wo die Ausländerbehörde ist?"},{"who":"Mitarbeiter","de":"In der Friedrich-Krause-Straße. Aber Sie brauchen dort auch einen Termin."},{"who":"Leila","de":"Wissen Sie, wie lange man auf einen Termin warten muss?"},{"who":"Mitarbeiter","de":"Das kann ich Ihnen leider nicht sagen. Manchmal mehrere Wochen."},{"who":"Leila","de":"Und wissen Sie, welche Unterlagen ich brauche?"},{"who":"Mitarbeiter","de":"Das steht auf der Webseite. Ihr Pass, ein biometrisches Foto und Ihr Arbeitsvertrag, glaube ich."}],"dq":[{"q":"Was möchte Leila verlängern?","a":"Ihre Aufenthaltserlaubnis."},{"q":"Wer ist dafür zuständig?","a":"Die Ausländerbehörde."},{"q":"Welche Unterlagen braucht sie wahrscheinlich?","a":"Pass, biometrisches Foto und Arbeitsvertrag."}],"en":{"title":"Indirect questions","theme":"Offices and information","expl":["Indirect questions are subordinate clauses – **the verb goes to the end**. They are more polite than direct questions.","W-question → keep the question word: __Wann kommt der Bus?__ → __Können Sie mir sagen, wann der Bus kommt?__","Yes/no question → use **ob** (whether): __Ist das Büro offen?__ → __Wissen Sie, ob das Büro offen ist?__"],"use":""},"check":[{"re":"\\\\b(können sie mir sagen|wissen sie|ich möchte wissen|ich würde gern wissen|könnten sie mir sagen)\\\\b","label":"an indirect question opener (Können Sie mir sagen, …)"},{"re":",\\\\s*(ob|wann|wo|wie|was|wie viel|welche\\\\w*)\\\\b","label":"ob / W-word + verb at the end"}]},{"n":33,"pos":34,"level":"B1","title":"Relativsätze","theme":"Menschen und Dinge beschreiben","scene":"family","rec":[5,6,13,15,21,23],"expl":["Ein **Relativsatz** beschreibt ein Nomen genauer. Er ist ein **Nebensatz** (Verb am Ende) und steht direkt **nach dem Nomen**.","Das **Relativpronomen** hat das **Genus/Numerus des Nomens**, aber den **Fall aus dem Relativsatz**: __Der Mann, **den** ich kenne (kennen + Akk.)__.","Formen = bestimmter Artikel, **außer**: Dativ Plural **denen**, Genitiv **dessen / deren**.","Mit Präposition: Präposition steht **vor** dem Relativpronomen: __die Freundin, **mit der** ich wohne__. Nach Orten auch **wo**: __die Stadt, **wo** (in der) ich wohne__."],"use":"Personen und Dinge genau beschreiben, Bildbeschreibung, Definitionen.","table":[["Fall","maskulin","feminin","neutral","Plural"],["Nominativ","der","die","das","die"],["Akkusativ","den","die","das","die"],["Dativ","dem","der","dem","**denen**"],["Genitiv","**dessen**","**deren**","**dessen**","**deren**"],["Beispiel","Der Mann, **der** dort steht, …","Die Frau, **der** ich helfe, …","Das Kind, **das** ich sehe, …","Die Leute, **mit denen** ich arbeite, …"]],"examples":[{"de":"Das ist der Kollege, der aus Hamburg kommt.","en":"That\'s the colleague who comes from Hamburg."},{"de":"Das ist die Frau, die ich im Kurs kennengelernt habe.","en":"That\'s the woman I met in the course."},{"de":"Der Mann, dem ich geholfen habe, war sehr nett.","en":"The man I helped was very nice."},{"de":"Das Buch, das du mir geschenkt hast, ist super.","en":"The book you gave me is great."},{"de":"Die Freunde, mit denen ich reise, kommen aus Indien.","en":"The friends I travel with come from India."},{"de":"Berlin ist eine Stadt, in der viele Nationen leben.","en":"Berlin is a city where many nations live."},{"de":"Das ist Anna, deren Sohn Fußball spielt.","en":"That\'s Anna, whose son plays football."},{"de":"Ich suche eine Wohnung, die nicht so teuer ist.","en":"I\'m looking for a flat that isn\'t so expensive."},{"de":"Der Film, über den alle sprechen, ist langweilig.","en":"The film everyone talks about is boring."},{"de":"Mumbai ist die Stadt, wo ich geboren bin.","en":"Mumbai is the city where I was born."},{"de":"Das ist der Mann, der neben uns wohnt.","en":"That\'s the man who lives next to us."},{"de":"Die Frau, die ich gestern getroffen habe, ist Ärztin.","en":"The woman I met yesterday is a doctor."},{"de":"Das ist das Buch, von dem ich dir erzählt habe.","en":"That\'s the book I told you about."},{"de":"Ich habe einen Freund, dem ich alles erzählen kann.","en":"I have a friend I can tell everything to."},{"de":"Die Kollegin, deren Mann Koch ist, bringt oft Kuchen mit.","en":"The colleague whose husband is a cook often brings cake."},{"de":"Das ist die Stadt, in der ich geboren bin.","en":"That\'s the city where I was born."},{"de":"Das Café, wo wir uns kennengelernt haben, gibt es nicht mehr.","en":"The café where we met no longer exists."},{"de":"Alles, was er sagt, ist interessant.","en":"Everything he says is interesting."},{"de":"Die Leute, mit denen ich arbeite, sind sehr nett.","en":"The people I work with are very nice."},{"de":"Mein Vorbild ist meine Oma, die nie aufgegeben hat.","en":"My role model is my grandma, who never gave up."}],"vocab":[{"de":"die Person, -en","en":"person"},{"de":"der Mensch, -en","en":"human"},{"de":"freundlich / unfreundlich","en":"friendly / unfriendly"},{"de":"hilfsbereit","en":"helpful"},{"de":"lustig","en":"funny"},{"de":"ehrlich","en":"honest"},{"de":"geduldig","en":"patient"},{"de":"der Charakter, -e","en":"character"},{"de":"die Eigenschaft, -en","en":"quality"},{"de":"kennenlernen","en":"to get to know"},{"de":"sich verstehen mit","en":"to get on with"},{"de":"der Mitbewohner, -","en":"flatmate"},{"de":"der, die, das (Relativpronomen)","en":"who, which, that"},{"de":"dessen / deren","en":"whose"},{"de":"wo (Relativadverb)","en":"where"},{"de":"was (nach alles, etwas, nichts)","en":"that, which"},{"de":"die Nachbarschaft, -en","en":"neighbourhood"},{"de":"zuverlässig","en":"reliable"},{"de":"neugierig","en":"curious"},{"de":"großzügig","en":"generous"},{"de":"egoistisch","en":"selfish"},{"de":"schüchtern","en":"shy"},{"de":"selbstbewusst","en":"self-confident"},{"de":"humorvoll","en":"humorous"},{"de":"ordentlich","en":"tidy"},{"de":"die Persönlichkeit, -en","en":"personality"},{"de":"das Vorbild, -er","en":"role model"},{"de":"beschreiben","en":"to describe"},{"de":"der Eindruck, ¨e","en":"impression"}],"reading":"Ravi schreibt seiner Schwester eine E-Mail: „In Berlin habe ich Menschen kennengelernt, die mir sehr wichtig sind. Anna ist die Nachbarin, die mir immer hilft. Jonas ist der Kollege, mit dem ich am besten zusammenarbeite. Leila ist die Freundin, die ich im Deutschkurs kennengelernt habe und mit der ich oft spazieren gehe. Max, dessen Mutter Anna ist, ist ein Junge, der nur an Fußball denkt. Das sind die Leute, denen ich viel zu verdanken habe.“","tasks":[{"q":"Das ist der Mann, ___ neben mir wohnt.","a":"der"},{"q":"Das ist die Frau, ___ ich liebe.","a":"die"},{"q":"Das ist das Kind, ___ ich geholfen habe.","a":"dem"},{"q":"Hier ist der Stuhl, ___ ich gekauft habe.","a":"den"},{"q":"Das sind die Kinder, mit ___ ich spiele.","a":"denen"},{"q":"Das ist die Lehrerin, ___ Kurs ich besuche.","a":"deren"},{"q":"Verbinde: Ich habe einen Freund. Er wohnt in Wien.","a":"Ich habe einen Freund, der in Wien wohnt."},{"q":"[Mix] Das ist die Kollegin, ___ ich ___ Blumen geschenkt habe. (Dativ, die)","a":"der / die"},{"q":"[Mix] Die Wohnung, in ___ wir wohnen, ist größer ___ die alte.","a":"der / als"},{"q":"[Mix] Der Film, ___ ___ ich mich interessiere, läuft heute. (für)","a":"für den"},{"q":"Das ist der Kollege, ___ mir geholfen hat.","a":"der"},{"q":"Das ist die Frau, ___ ich gestern gesehen habe.","a":"die"},{"q":"Das ist das Kind, ___ ich ein Buch geschenkt habe.","a":"dem"},{"q":"Das ist der Mann, ___ Auto vor der Tür steht.","a":"dessen"},{"q":"Das sind die Freunde, mit ___ ich in Urlaub fahre.","a":"denen"},{"q":"Das ist die Stadt, in ___ ich wohne.","a":"der"},{"q":"Alles, ___ du sagst, stimmt.","a":"was"},{"q":"Das ist der Film, von ___ ich dir erzählt habe.","a":"dem"},{"q":"Verbinde: Ich kenne eine Frau. Die Frau spricht fünf Sprachen.","a":"Ich kenne eine Frau, die fünf Sprachen spricht."},{"q":"Fehler? „Das ist der Mann, der ich gestern getroffen habe.“","a":"Das ist der Mann, den ich gestern getroffen habe."}],"exam":[{"q":"Wer ist Anna?","a":"Die Nachbarin, die Ravi immer hilft."},{"q":"Wo hat Ravi Leila kennengelernt?","a":"Im Deutschkurs."},{"q":"Wer ist Max?","a":"Annas Sohn, der nur an Fußball denkt."},{"q":"Verbinde: Das ist der Bus. Ich fahre mit dem Bus zur Arbeit.","a":"Das ist der Bus, mit dem ich zur Arbeit fahre."},{"q":"Verbinde: Ich kenne eine Frau. Ihr Mann ist Koch.","a":"Ich kenne eine Frau, deren Mann Koch ist."},{"q":"Verbinde: Die Leute sind nett. Ich arbeite für die Leute.","a":"Die Leute, für die ich arbeite, sind nett."},{"q":"Definiere mit Relativsatz: ein Bäcker","a":"Ein Bäcker ist ein Mann, der Brot backt."},{"q":"Beschreiben Sie eine Person, die für Sie wichtig ist.","a":"","m":"Eine Person, die für mich wichtig ist, ist meine Großmutter. Sie ist eine Frau, die immer Zeit für mich hat. Sie hat mir Dinge beigebracht, die ich nie vergesse."},{"q":"Wie ist ein guter Freund? (Ein guter Freund ist jemand, der …)","a":"","m":"Ein guter Freund ist jemand, der zuhört. Er ist ein Mensch, dem man vertrauen kann. Ein guter Freund ist jemand, der auch in schweren Zeiten da ist."},{"q":"Beschreiben Sie die Stadt, in der Sie aufgewachsen sind.","a":"","m":"Die Stadt, in der ich aufgewachsen bin, heißt Pune. Es ist eine Stadt, die viele Universitäten hat. Der Markt, auf dem ich mit meiner Mutter eingekauft habe, ist sehr alt."}],"speak":["Beschreibe die Personen mit Relativsätzen: __Die Frau, die links sitzt, …__","Rätsel: Beschreibe ein Ding, ohne den Namen zu sagen: __Das ist etwas, das …__","Beschreibe den Nachbarn, den du am liebsten magst.","Was für ein Mensch möchtest du sein?"],"reading2":{"title":"Menschen in unserem Haus","text":"Im Haus in der Goethestraße wohnen ganz unterschiedliche Menschen. Im Erdgeschoss wohnt Herr Kaya, der seit vierzig Jahren in Berlin lebt und früher einen Gemüseladen hatte. Er ist ein Mann, dem man sofort vertraut. Jeden Morgen gießt er die Blumen, die vor dem Haus stehen. Im ersten Stock lebt Anna Weber, deren Sohn Paul gern Fußball spielt. Anna ist Grafikerin und arbeitet oft zu Hause. Sie ist die Person, an die sich alle wenden, wenn es Probleme gibt. Neben ihr wohnt Frau Lindner, eine alte Dame, die sehr neugierig ist. Es gibt nichts, was sie nicht weiß. Im zweiten Stock ist die WG, in der Jonas, Mia und früher Ravi gewohnt haben. Ganz oben wohnt ein junges Paar, das erst vor Kurzem eingezogen ist. Die beiden, über die Frau Lindner natürlich schon alles weiß, kommen aus Spanien. Einmal im Jahr gibt es ein Hoffest, bei dem jeder etwas mitbringt. Herr Kaya macht Börek, Anna bringt Salat mit, und die WG kümmert sich um die Musik. „Ein Haus, in dem man sich kennt, ist ein Zuhause“, sagt Herr Kaya."},"dialog":[{"who":"Mia","de":"Kennst du schon die Leute, die oben eingezogen sind?"},{"who":"Jonas","de":"Meinst du das Paar, das immer so laut Musik hört?"},{"who":"Mia","de":"Genau. Die Frau, mit der ich im Treppenhaus gesprochen habe, heißt Carmen."},{"who":"Jonas","de":"Ist das die Frau, deren Fahrrad immer im Flur steht?"},{"who":"Mia","de":"Ja, aber sie ist sehr nett. Sie hat uns zu ihrer Einweihungsparty eingeladen."},{"who":"Jonas","de":"Eine Party? Dann ist das die Musik, über die sich Frau Lindner beschwert."},{"who":"Mia","de":"Wahrscheinlich. Aber alles, was Frau Lindner sagt, muss man nicht glauben."}],"dq":[{"q":"Wer ist oben eingezogen?","a":"Ein Paar (Carmen und ihr Partner)."},{"q":"Wo steht Carmens Fahrrad?","a":"Im Flur."},{"q":"Worüber beschwert sich Frau Lindner?","a":"Über die (laute) Musik."}],"en":{"title":"Relative clauses","theme":"Describing people and things","expl":["A relative clause describes a noun more precisely (who / which / that). It is a subordinate clause (verb at the end) and comes right after the noun.","The relative pronoun takes its **gender and number from the noun** but its **case from the relative clause**: __der Mann, den ich kenne__ (kennen + acc.) = the man (whom) I know.","The forms are like der/die/das, except dative plural **denen** and genitive **dessen / deren**. With a preposition: __die Frau, mit der ich arbeite__."],"use":""},"check":[{"re":",\\\\s*(der|die|das|den|dem|denen|dessen|deren)\\\\b[^.!?]*\\\\b\\\\w+[.!?]?|,\\\\s*(in|mit|bei|von|für|an|auf) (der|dem|den|die|das)\\\\b","label":"a relative clause (…, der/die/das …)"}]},{"n":34,"pos":35,"level":"B1","title":"Temporalsätze: als, wenn, bevor, nachdem, während, seit, bis","theme":"Lebenslauf und Erinnerungen","scene":"family","rec":[17,18,21,24,33],"expl":["Temporalsätze sind Nebensätze (Verb am Ende) und sagen, **wann** etwas passiert.","**als** = **einmal** in der **Vergangenheit**: __**Als** ich 18 war, …__ · **wenn** = Gegenwart/Zukunft oder **wiederholt** (immer wenn) in der Vergangenheit.","**bevor** = vorher · **nachdem** = nachher (+ **Plusquamperfekt**/Perfekt, siehe L35) · **während** = gleichzeitig · **seit(dem)** = von damals bis jetzt · **bis** = Endpunkt."],"use":"Lebenslauf erzählen, Erfahrungen, Präsentation („Als ich nach Deutschland kam, …“).","table":[["Konj.","Bedeutung","Beispiel"],["als","einmal, Vergangenheit","**Als** ich nach Berlin kam, war es kalt."],["wenn","immer / Zukunft","**Wenn** ich in Mumbai war, bin ich immer ans Meer gegangen."],["bevor","before","Ich trinke Chai, **bevor** ich arbeite."],["nachdem","after","**Nachdem** ich gegessen hatte, bin ich gegangen."],["während","while","**Während** ich koche, höre ich Musik."],["seit(dem)","since","**Seit** ich hier wohne, fahre ich Rad."],["bis","until","Warte, **bis** ich komme!"]],"examples":[{"de":"Als ich ein Kind war, wohnten wir in Pune.","en":"When I was a child we lived in Pune."},{"de":"Wenn ich traurig bin, rufe ich meine Mutter an.","en":"When I\'m sad I call my mother."},{"de":"Immer wenn es regnete, spielten wir drinnen.","en":"Whenever it rained we played inside."},{"de":"Bevor ich nach Deutschland kam, habe ich Deutsch gelernt.","en":"Before I came to Germany I learned German."},{"de":"Nachdem ich die Schule beendet hatte, studierte ich.","en":"After I had finished school, I studied."},{"de":"Während Ravi kocht, telefoniert er mit Leila.","en":"While Ravi cooks, he talks to Leila on the phone."},{"de":"Seit ich in Berlin wohne, spreche ich jeden Tag Deutsch.","en":"Since I\'ve lived in Berlin I speak German every day."},{"de":"Ich bleibe hier, bis der Regen aufhört.","en":"I\'ll stay here until the rain stops."},{"de":"Als ich die Stelle bekam, war ich sehr glücklich.","en":"When I got the job I was very happy."},{"de":"Wenn ich die Prüfung bestanden habe, feiern wir.","en":"When I\'ve passed the exam, we\'ll celebrate."},{"de":"Als ich zehn Jahre alt war, sind wir nach Pune gezogen.","en":"When I was ten, we moved to Pune."},{"de":"Immer wenn ich meine Oma besuchte, backte sie Kuchen.","en":"Whenever I visited my grandma, she baked cake."},{"de":"Bevor ich nach Deutschland kam, habe ich ein Jahr Deutsch gelernt.","en":"Before I came to Germany, I learned German for a year."},{"de":"Nachdem er das Abitur gemacht hatte, machte er eine Weltreise.","en":"After he had finished school, he travelled around the world."},{"de":"Während ich studierte, arbeitete ich in einem Café.","en":"While I was studying, I worked in a café."},{"de":"Seitdem ich in Berlin wohne, fahre ich nur noch Fahrrad.","en":"Since I\'ve been living in Berlin, I only cycle."},{"de":"Warte, bis ich zurück bin!","en":"Wait until I\'m back!"},{"de":"Sobald ich die Ergebnisse habe, rufe ich dich an.","en":"As soon as I have the results, I\'ll call you."},{"de":"Als ich in Deutschland ankam, hatte ich großes Heimweh.","en":"When I arrived in Germany, I was very homesick."},{"de":"Wenn ich Heimweh habe, koche ich indisches Essen.","en":"When I feel homesick, I cook Indian food."}],"vocab":[{"de":"der Lebenslauf, ¨e","en":"CV / life story"},{"de":"geboren","en":"born"},{"de":"aufwachsen","en":"to grow up"},{"de":"die Schule beenden","en":"to finish school"},{"de":"das Studium","en":"university studies"},{"de":"studieren","en":"to study"},{"de":"der Abschluss, ¨e","en":"degree"},{"de":"das Praktikum, Praktika","en":"internship"},{"de":"sich erinnern an","en":"to remember"},{"de":"die Erinnerung, -en","en":"memory"},{"de":"damals","en":"back then"},{"de":"die Jugend","en":"youth"},{"de":"als","en":"when (single event in the past)"},{"de":"wenn","en":"when, whenever"},{"de":"bevor","en":"before"},{"de":"nachdem","en":"after"},{"de":"während","en":"while"},{"de":"seitdem","en":"since"},{"de":"bis","en":"until"},{"de":"sobald","en":"as soon as"},{"de":"die Grundschule, -n","en":"primary school"},{"de":"das Gymnasium, Gymnasien","en":"grammar school"},{"de":"das Abitur","en":"school-leaving exam (A levels)"},{"de":"die Ausbildung, -en","en":"vocational training"},{"de":"der Berufseinstieg","en":"entry into working life"},{"de":"der Wendepunkt, -e","en":"turning point"},{"de":"auswandern","en":"to emigrate"},{"de":"die Heimat","en":"home(land)"},{"de":"das Heimweh","en":"homesickness"},{"de":"sich verändern","en":"to change"}],"reading":"Ravi wurde 1998 in Mumbai geboren. Als er zehn war, zog die Familie nach Pune. Wenn er Ferien hatte, besuchte er immer seine Großeltern am Meer. Nachdem er die Schule beendet hatte, studierte er Maschinenbau. Während er studierte, machte er ein Praktikum bei einer deutschen Firma. Bevor er nach Berlin kam, lernte er ein Jahr Deutsch. Seit er hier lebt, ist sein Leben ganz anders. Er bleibt in Berlin, bis er Teamleiter ist – mindestens!","tasks":[{"q":"___ ich 20 war, bin ich nach Delhi gezogen.","a":"Als"},{"q":"___ ich Zeit habe, lese ich.","a":"Wenn"},{"q":"Immer ___ Oma kam, brachte sie Süßigkeiten mit.","a":"wenn"},{"q":"Putz dir die Zähne, ___ du schlafen gehst!","a":"bevor"},{"q":"___ ich wohne hier, habe ich viele Freunde. → korrigiere","a":"Seit ich hier wohne, habe ich viele Freunde."},{"q":"___ du duschst, mache ich das Frühstück.","a":"Während"},{"q":"Warte hier, ___ ich zurückkomme!","a":"bis"},{"q":"[Mix] Als ich klein ___, ___ ich keinen Computer. (sein, haben – Prät.)","a":"war / hatte"},{"q":"[Mix] Bevor ich ___ Haus verlasse, ziehe ich ___ die Jacke an. (das, sich – Dat.)","a":"das / mir"},{"q":"[Mix] Seitdem ich ___ Leila spreche, ist mein Deutsch ___. (mit, gut – Komp.)","a":"mit / besser"},{"q":"___ ich ein Kind war, wohnte ich auf dem Land. (als/wenn)","a":"Als"},{"q":"Immer ___ es regnet, bleibe ich zu Hause. (als/wenn)","a":"wenn"},{"q":"___ du gehst, mach bitte das Licht aus. (bevor/nachdem)","a":"Bevor"},{"q":"___ er gegessen hatte, ging er spazieren. (bevor/nachdem)","a":"Nachdem"},{"q":"___ ich koche, höre ich Radio. (während/bis)","a":"Während"},{"q":"Warte hier, ___ ich zurückkomme. (bis/seit)","a":"bis"},{"q":"___ ich in Berlin wohne, fahre ich Fahrrad. (seitdem/bevor)","a":"Seitdem"},{"q":"___ ich Zeit habe, rufe ich dich an. (sobald/als)","a":"Sobald"},{"q":"Verbinde mit als: Ich kam in Deutschland an. Es war kalt.","a":"Als ich in Deutschland ankam, war es kalt."},{"q":"Fehler? „Wenn ich gestern nach Hause kam, war niemand da.“","a":"Als ich gestern nach Hause kam, war niemand da."}],"exam":[{"q":"Wohin zog die Familie, als Ravi zehn war?","a":"Nach Pune."},{"q":"Was machte Ravi, wenn er Ferien hatte?","a":"Er besuchte seine Großeltern am Meer."},{"q":"Was machte er, bevor er nach Berlin kam?","a":"Er lernte ein Jahr Deutsch."},{"q":"als oder wenn? ___ ich gestern nach Hause kam, war niemand da.","a":"Als"},{"q":"als oder wenn? ___ ich nach Hause komme, koche ich immer.","a":"Wenn"},{"q":"Verbinde (während): Ich fahre Bus. Ich lese.","a":"Während ich Bus fahre, lese ich."},{"q":"Verbinde (bevor): Ich gehe ins Bett. Ich lese.","a":"Bevor ich ins Bett gehe, lese ich."},{"q":"Erzählen Sie Ihren Lebenslauf mit als, nachdem, bevor, seit.","a":"","m":"Als ich sechs war, kam ich in die Schule. Nachdem ich das Abitur gemacht hatte, studierte ich Informatik. Bevor ich nach Deutschland kam, arbeitete ich in Mumbai. Seit ich in Berlin wohne, lerne ich Deutsch."},{"q":"Woran erinnern Sie sich, wenn Sie an Ihre Schulzeit denken?","a":"","m":"Wenn ich an meine Schulzeit denke, erinnere ich mich an meine Freunde. Als ich zwölf war, hatte ich einen sehr guten Mathelehrer."},{"q":"Was machen Sie immer, wenn Sie Stress haben?","a":"","m":"Wenn ich Stress habe, gehe ich immer joggen. Bevor ich schlafe, höre ich ruhige Musik."}],"speak":["Erzähle eine Geschichte zur Familie: __Als die Kinder klein waren, …__","Was machst du, während du isst?","Was war, als du zum ersten Mal in einem neuen Land warst?","Was hat sich geändert, seit du Deutsch lernst?"],"reading2":{"title":"Lebensstationen: Leila erzählt","text":"„Ich bin 1993 in Schiras geboren, einer Stadt im Süden des Iran. Als ich klein war, wohnten wir bei meinen Großeltern. Immer wenn mein Großvater von der Arbeit kam, erzählte er mir Geschichten aus der persischen Literatur. Bevor ich in die Schule kam, konnte ich deshalb schon viele Gedichte auswendig. Nachdem ich das Abitur bestanden hatte, studierte ich Medizin in Teheran. Während ich studierte, lernte ich meinen Mann kennen. Er war damals Ingenieurstudent. Als unsere Tochter geboren wurde, arbeitete ich schon als Ärztin im Krankenhaus. Vor vier Jahren bekam mein Mann ein Angebot von einer Firma in Berlin. Das war ein großer Wendepunkt. Bevor wir auswanderten, lernte ich ein Jahr lang Deutsch, abends nach der Arbeit. Als wir in Berlin ankamen, war alles neu und fremd. Meine Approbation, also die Erlaubnis, in Deutschland als Ärztin zu arbeiten, dauerte fast zwei Jahre. Seitdem arbeite ich wieder im Krankenhaus. Manchmal habe ich Heimweh, besonders wenn ich an das Essen meiner Mutter denke. Aber sobald ich mit meiner Tochter durch den Park gehe und sie Deutsch mit anderen Kindern spricht, weiß ich: Hier ist jetzt auch unser Zuhause.“"},"dialog":[{"who":"Paul","de":"Herr Kaya, wie war das, als Sie nach Deutschland gekommen sind?"},{"who":"Herr Kaya","de":"Das ist lange her. Als ich ankam, war ich zweiundzwanzig und sprach kein Wort Deutsch."},{"who":"Paul","de":"Und wie haben Sie Deutsch gelernt?"},{"who":"Herr Kaya","de":"Während ich in der Fabrik arbeitete, habe ich von den Kollegen gelernt. Einen Kurs gab es nicht."},{"who":"Paul","de":"Hatten Sie Heimweh?"},{"who":"Herr Kaya","de":"Am Anfang sehr. Immer wenn ein Brief von meiner Mutter kam, habe ich geweint."},{"who":"Paul","de":"Und wann haben Sie den Gemüseladen aufgemacht?"},{"who":"Herr Kaya","de":"Nachdem ich zehn Jahre gespart hatte. Seitdem ist Berlin meine zweite Heimat."}],"dq":[{"q":"Wie alt war Herr Kaya, als er nach Deutschland kam?","a":"Zweiundzwanzig."},{"q":"Wie hat er Deutsch gelernt?","a":"Bei der Arbeit in der Fabrik, von den Kollegen."},{"q":"Wann hat er den Gemüseladen aufgemacht?","a":"Nachdem er zehn Jahre gespart hatte."}],"en":{"title":"Time clauses: als, wenn, bevor, nachdem, während, seit, bis","theme":"CV and memories","expl":["Time clauses are subordinate clauses (verb at the end) that say when something happens.","**als** = when (one occasion in the past: __Als ich 18 war, …__) · **wenn** = when (present/future, or \\"whenever\\" in the past) · **bevor** = before · **nachdem** = after (+ past perfect) · **während** = while · **seit(dem)** = since · **bis** = until."],"use":""},"check":[{"re":"\\\\b(als|nachdem|bevor|seit|seitdem|während|bis|wenn)\\\\b","label":"als, nachdem, bevor, seit …"}]},{"n":35,"pos":36,"level":"B1","title":"Präteritum (alle Verben) und Plusquamperfekt","theme":"Geschichten erzählen","scene":"station","rec":[17,18,24,34],"expl":["**Präteritum** benutzt man vor allem **schriftlich** (Geschichten, Zeitung, Märchen). Regelmäßig: Stamm + **-te**: machte, wohnte. Unregelmäßig: eigener Stamm: ging, kam, fuhr, sah, fand (siehe Referenz 3). ich und er/sie/es haben **keine Endung**: ich ging, er ging.","**Plusquamperfekt** = die Vergangenheit **vor** der Vergangenheit: **hatte/war + Partizip II**: __Als ich ankam, **war** der Zug schon **abgefahren**.__","Typisch mit **nachdem**: Plusquamperfekt im nachdem-Satz, Präteritum/Perfekt im Hauptsatz."],"use":"Lesetexte in der Prüfung verstehen, Geschichten/E-Mails schreiben.","table":[["Zeit","regelmäßig (reisen)","unregelmäßig (fahren)","Funktion"],["Präsens","er reist","er fährt","jetzt"],["Präteritum","er reis**te**","er **fuhr**","Vergangenheit (schriftlich)"],["Perfekt","er ist gereist","er ist gefahren","Vergangenheit (mündlich)"],["Plusquamperfekt","er **war** gereist","er **war** gefahren","vor der Vergangenheit"],["Plusquamperfekt (haben)","er **hatte** gewartet","er **hatte** gegessen","vor der Vergangenheit"]],"examples":[{"de":"Letzten Winter fuhr Ravi nach Hamburg.","en":"Last winter Ravi went to Hamburg."},{"de":"Der Zug kam mit einer Stunde Verspätung an.","en":"The train arrived an hour late."},{"de":"Ravi wartete am Gleis und fror.","en":"Ravi waited on the platform and was freezing."},{"de":"Er hatte seine Handschuhe zu Hause vergessen.","en":"He had forgotten his gloves at home."},{"de":"Als er ankam, war das Museum schon geschlossen.","en":"When he arrived, the museum had already closed."},{"de":"Nachdem er gegessen hatte, ging er zum Hafen.","en":"After he had eaten he went to the harbour."},{"de":"Es war einmal ein König, der drei Töchter hatte.","en":"Once upon a time there was a king who had three daughters."},{"de":"Sie las den Brief und weinte.","en":"She read the letter and cried."},{"de":"Wir waren schon eingeschlafen, als das Telefon klingelte.","en":"We had already fallen asleep when the phone rang."},{"de":"Er fand die Adresse nicht, weil er den Zettel verloren hatte.","en":"He couldn\'t find the address because he had lost the note."},{"de":"Es war einmal ein König, der drei Töchter hatte.","en":"Once upon a time there was a king who had three daughters."},{"de":"Plötzlich klingelte das Telefon.","en":"Suddenly the phone rang."},{"de":"Er nahm seine Jacke und ging hinaus.","en":"He took his jacket and went out."},{"de":"Als sie nach Hause kam, war ihr Mann schon gegangen.","en":"When she came home, her husband had already left."},{"de":"Nachdem wir gegessen hatten, spielten wir Karten.","en":"After we had eaten, we played cards."},{"de":"Ich wusste nicht, was ich sagen sollte.","en":"I didn\'t know what I should say."},{"de":"Sie dachte lange nach.","en":"She thought for a long time."},{"de":"Zum Glück fand er den Schlüssel unter der Matte.","en":"Luckily he found the key under the mat."},{"de":"Das Kind lief schnell zu seiner Mutter.","en":"The child ran quickly to its mother."},{"de":"Der Zug war schon abgefahren, als wir ankamen.","en":"The train had already left when we arrived."}],"vocab":[{"de":"die Geschichte, -n","en":"story / history"},{"de":"das Märchen, -","en":"fairy tale"},{"de":"plötzlich","en":"suddenly"},{"de":"zum Glück","en":"luckily"},{"de":"leider","en":"unfortunately"},{"de":"verlieren (verlor)","en":"to lose"},{"de":"frieren (fror)","en":"to freeze"},{"de":"klingeln","en":"to ring"},{"de":"der Hafen, ¨","en":"harbour"},{"de":"das Museum, Museen","en":"museum"},{"de":"ankommen (kam an)","en":"to arrive"},{"de":"weinen","en":"to cry"},{"de":"ging (gehen)","en":"went"},{"de":"kam (kommen)","en":"came"},{"de":"sah (sehen)","en":"saw"},{"de":"fand (finden)","en":"found"},{"de":"lief (laufen)","en":"ran"},{"de":"rief (rufen)","en":"called"},{"de":"stand (stehen)","en":"stood"},{"de":"saß (sitzen)","en":"sat"},{"de":"nahm (nehmen)","en":"took"},{"de":"gab (geben)","en":"gave"},{"de":"dachte (denken)","en":"thought"},{"de":"wusste (wissen)","en":"knew"},{"de":"brachte (bringen)","en":"brought"},{"de":"hatte … gemacht","en":"had done (Plusquamperfekt)"},{"de":"war … gegangen","en":"had gone (Plusquamperfekt)"},{"de":"der Wald, ¨er","en":"forest"},{"de":"die Hexe, -n","en":"witch"},{"de":"erschrecken (erschrak)","en":"to be frightened"}],"reading":"Letzten Winter fuhr Ravi nach Hamburg. Er hatte die Fahrkarte schon vor Wochen gekauft. Leider hatte der Zug eine Stunde Verspätung. Ravi wartete am Gleis und fror, denn er hatte seine Handschuhe vergessen. Als er endlich in Hamburg ankam, war das Museum schon geschlossen. Zum Glück fand er ein kleines Café am Hafen. Nachdem er einen heißen Tee getrunken hatte, ging er am Wasser spazieren. Plötzlich sah er ein riesiges Schiff. Es war ein schöner Abend.","tasks":[{"q":"Präteritum: Ich (wohnen) ___ in Pune.","a":"wohnte"},{"q":"Präteritum: Er (gehen) ___ nach Hause.","a":"ging"},{"q":"Präteritum: Wir (sehen) ___ einen Film.","a":"sahen"},{"q":"Präteritum: Sie (kommen, Sg.) ___ spät an.","a":"kam"},{"q":"Plusquamperfekt: Ich ___ schon ___. (essen)","a":"hatte / gegessen"},{"q":"Plusquamperfekt: Der Bus ___ schon ___. (abfahren)","a":"war / abgefahren"},{"q":"Nachdem er die Arbeit beendet ___, ___ er nach Hause. (haben, fahren – Prät.)","a":"hatte / fuhr"},{"q":"[Mix] Als ich ___ Bahnhof ankam, war der Zug schon weg. (an + der)","a":"am"},{"q":"[Mix] Er konnte nicht bezahlen, weil er ___ Geldbeutel verloren ___. (sein, haben)","a":"seinen / hatte"},{"q":"[Mix] Präteritum: Sie (sich freuen) ___ ___ über das Geschenk.","a":"freute sich"},{"q":"Präteritum: Er ___ nach Hause. (gehen)","a":"ging"},{"q":"Präteritum: Wir ___ einen Film. (sehen)","a":"sahen"},{"q":"Präteritum: Sie ___ spät. (kommen)","a":"kam"},{"q":"Präteritum: Ich ___ den Schlüssel nicht. (finden)","a":"fand"},{"q":"Präteritum: Du ___ mir ein Geschenk. (geben)","a":"gabst"},{"q":"Präteritum: Ich ___ nicht, was ich tun sollte. (wissen)","a":"wusste"},{"q":"Plusquamperfekt: Nachdem er ___ ___, ging er ins Bett. (essen)","a":"gegessen hatte"},{"q":"Plusquamperfekt: Als ich ankam, ___ der Zug schon ___. (abfahren)","a":"war / abgefahren"},{"q":"Plusquamperfekt: Sie war müde, weil sie schlecht ___ ___. (schlafen)","a":"geschlafen hatte"},{"q":"Fehler? „Nachdem sie gegessen hat, ging sie spazieren.“","a":"Nachdem sie gegessen hatte, ging sie spazieren."}],"exam":[{"q":"Warum fror Ravi?","a":"Er hatte seine Handschuhe vergessen."},{"q":"Warum konnte er nicht ins Museum?","a":"Es war schon geschlossen."},{"q":"Was machte er, nachdem er Tee getrunken hatte?","a":"Er ging am Wasser spazieren."},{"q":"Perfekt → Präteritum: Wir sind nach Rom gefahren.","a":"Wir fuhren nach Rom."},{"q":"Perfekt → Präteritum: Sie hat einen Brief geschrieben.","a":"Sie schrieb einen Brief."},{"q":"Plusquamperfekt: Ich kam an. Der Film (beginnen) … schon.","a":"Der Film hatte schon begonnen."},{"q":"Verbinde mit nachdem: Er frühstückte. Dann ging er los.","a":"Nachdem er gefrühstückt hatte, ging er los."},{"q":"Schreiben Sie eine kurze Geschichte (8 Sätze) im Präteritum: Ein Tag, an dem alles schiefging.","a":"","m":"Am Montag ging alles schief. Zuerst klingelte mein Wecker nicht. Ich stand zu spät auf und verpasste den Bus. Im Büro merkte ich, dass ich mein Handy vergessen hatte. Mittags fiel mir der Kaffee auf die Hose. Am Nachmittag stürzte mein Computer ab. Abends regnete es, und ich hatte keinen Schirm. Zu Hause schlief ich sofort ein."},{"q":"Erzählen Sie ein Märchen aus Ihrem Land.","a":"","m":"Es war einmal ein König, der drei Söhne hatte. Er wollte wissen, wer am klügsten war. Er gab jedem eine Münze. Der jüngste Sohn kaufte Kerzen und füllte den Palast mit Licht. So wurde er König."},{"q":"Was war schon passiert, als Sie heute aufgewacht sind?","a":"","m":"Als ich heute aufgewacht bin, hatte meine Frau schon Kaffee gekocht. Es hatte in der Nacht geregnet."}],"speak":["Erzähle eine Geschichte zum Bahnhof im Präteritum: __Der Mann wartete …__","Was war vorher passiert? (Plusquamperfekt)","Erzähle, was dir auf einer Reise einmal passiert ist.","Erfinde ein Ende für Ravis Hamburg-Geschichte."],"reading2":{"title":"Hänsel und Gretel – nacherzählt","text":"Vor langer Zeit lebte an einem großen Wald ein armer Holzfäller mit seiner Frau und seinen zwei Kindern, Hänsel und Gretel. Die Familie hatte kaum etwas zu essen. Eines Abends sagte die Stiefmutter: „Morgen bringen wir die Kinder in den Wald und lassen sie dort allein.“ Hänsel hatte alles gehört. In der Nacht ging er hinaus und sammelte weiße Steine. Am nächsten Tag warf er die Steine auf den Weg, und so fanden die Kinder im Mondlicht nach Hause zurück. Doch beim zweiten Mal hatte Hänsel nur Brot dabei, und die Vögel fraßen die Krümel. Drei Tage liefen die Kinder durch den Wald. Plötzlich standen sie vor einem Haus aus Lebkuchen und Zucker. Weil sie so hungrig waren, aßen sie davon. Da kam eine alte Frau heraus. Sie war freundlich und gab ihnen zu essen. Aber sie war eine böse Hexe! Sie sperrte Hänsel in einen Stall, denn sie wollte ihn dick machen und dann essen. Gretel musste für sie arbeiten. Als die Hexe eines Tages den Ofen geheizt hatte, sagte Gretel: „Ich weiß nicht, wie man hineinkommt.“ Die Hexe zeigte es ihr, und Gretel stieß sie in den Ofen. Dann befreite sie ihren Bruder. Mit den Schätzen der Hexe kehrten sie nach Hause zurück. Die Stiefmutter war inzwischen gestorben, und der Vater war überglücklich."},"dialog":[{"who":"Tomás","de":"Du wirst nicht glauben, was mir gestern passiert ist!"},{"who":"Mia","de":"Erzähl!"},{"who":"Tomás","de":"Ich wollte nach dem Kurs nach Hause fahren. Ich ging zur U-Bahn, aber sie fuhr nicht."},{"who":"Mia","de":"Ein Streik?"},{"who":"Tomás","de":"Nein, eine Störung. Also nahm ich den Bus. Im Bus merkte ich, dass ich mein Handy im Kursraum vergessen hatte."},{"who":"Mia","de":"Oh nein! Bist du zurückgefahren?"},{"who":"Tomás","de":"Ja. Aber als ich ankam, hatte der Hausmeister schon abgeschlossen."},{"who":"Mia","de":"Und dann?"},{"who":"Tomás","de":"Zum Glück wohnte er im Haus. Ich klingelte, und er gab mir das Handy. Er hatte es schon gefunden!"}],"dq":[{"q":"Warum fuhr die U-Bahn nicht?","a":"Es gab eine Störung."},{"q":"Was hatte Tomás vergessen?","a":"Sein Handy (im Kursraum)."},{"q":"Wer gab ihm das Handy?","a":"Der Hausmeister."}],"en":{"title":"Simple past (all verbs) and past perfect","theme":"Telling stories","expl":["The **Präteritum** is used mainly in writing (stories, newspapers, fairy tales). Regular: stem + **-te**: __machte, wohnte__. Irregular verbs have their own stem: __ging, kam, fuhr, sah, fand__. ich and er/sie/es have no ending: __ich ging, er ging__.","The **Plusquamperfekt** (past perfect) is the past before the past: **hatte/war + participle**: __Nachdem ich gegessen hatte, ging ich los.__ = After I had eaten, I left."],"use":""},"check":[{"re":"\\\\b(ging|kam|fuhr|sah|fand|nahm|stand|saß|lief|rief|schlief|aß|trank|wollte|musste|war|hatte|\\\\w+te)\\\\b","label":"Präteritum (ging, kam, machte …)"},{"re":"\\\\b(hatte|war)\\\\b[^.!?]*\\\\bge\\\\w+(t|en)\\\\b","label":"Plusquamperfekt (hatte/war + Partizip II)"}]},{"n":36,"pos":37,"level":"B1","title":"Gegensätze: obwohl und trotzdem","theme":"Arbeit und Freizeit im Gleichgewicht","scene":"office","rec":[20,21,34],"expl":["**obwohl** (although) leitet einen **Nebensatz** ein – Verb am Ende: __Ich gehe joggen, **obwohl** es **regnet**.__","**trotzdem** (nevertheless) ist ein **Adverb** – im Hauptsatz auf **Position 1** (Verb danach) oder in der Mitte: __Es regnet. **Trotzdem gehe** ich joggen. / Ich gehe **trotzdem** joggen.__","Beide zeigen einen **unerwarteten Gegensatz** (Gegenteil von weil/deshalb). Vergleiche: __weil__ = Grund, __obwohl__ = Gegengrund.","Auch: **aber** (Pos. 0) und **trotz + Genitiv** (L40)."],"use":"Differenziert argumentieren – bringt Punkte bei „Spektrum“ in der Prüfung.","table":[["Typ","Satz 1","Satz 2"],["obwohl (Nebensatz)","Ravi arbeitet,","**obwohl** er krank **ist**."],["obwohl zuerst","**Obwohl** er krank ist,","**arbeitet** er."],["trotzdem Pos. 1","Er ist krank.","**Trotzdem arbeitet** er."],["trotzdem Mitte","Er ist krank.","Er arbeitet **trotzdem**."],["aber (Pos. 0)","Er ist krank,","**aber** er arbeitet."]],"examples":[{"de":"Obwohl ich müde bin, lerne ich noch.","en":"Although I\'m tired, I\'m still studying."},{"de":"Jonas hat viel Arbeit. Trotzdem macht er pünktlich Feierabend.","en":"Jonas has a lot of work. Nevertheless he finishes on time."},{"de":"Ich esse Schokolade, obwohl ich eine Diät mache.","en":"I eat chocolate although I\'m on a diet."},{"de":"Es war kalt, trotzdem sind wir geschwommen.","en":"It was cold; we swam anyway."},{"de":"Obwohl Ravi wenig Zeit hat, geht er jede Woche joggen.","en":"Although Ravi has little time, he goes jogging every week."},{"de":"Das Gehalt ist gut. Trotzdem ist sie nicht zufrieden.","en":"The salary is good. Nevertheless she\'s not satisfied."},{"de":"Er kam zur Arbeit, obwohl er Fieber hatte.","en":"He came to work although he had a fever."},{"de":"Ich habe gut geschlafen und bin trotzdem müde.","en":"I slept well and am still tired."},{"de":"Obwohl die Wohnung teuer ist, haben wir sie genommen.","en":"Although the flat is expensive, we took it."},{"de":"Sie lernt nie – trotzdem besteht sie jede Prüfung.","en":"She never studies – yet she passes every exam."},{"de":"Obwohl er müde ist, arbeitet er weiter.","en":"Although he is tired, he keeps working."},{"de":"Er ist müde. Trotzdem arbeitet er weiter.","en":"He is tired. He keeps working nevertheless."},{"de":"Obwohl es regnete, sind wir spazieren gegangen.","en":"Although it was raining, we went for a walk."},{"de":"Das Gehalt ist zwar gut, aber die Arbeitszeiten sind schlecht.","en":"The salary is good, admittedly, but the hours are bad."},{"de":"Trotz des Stresses ist sie zufrieden.","en":"Despite the stress she is satisfied."},{"de":"Ich hatte keine Zeit. Dennoch habe ich ihm geholfen.","en":"I had no time. Nevertheless I helped him."},{"de":"Obwohl sie Teilzeit arbeitet, hat sie viel zu tun.","en":"Although she works part-time, she has a lot to do."},{"de":"Nach Feierabend kann ich nicht abschalten.","en":"I can\'t switch off after work."},{"de":"Er macht viele Überstunden, obwohl er nicht muss.","en":"He does a lot of overtime although he doesn\'t have to."},{"de":"Es ist schwer, Nein zu sagen. Trotzdem muss ich es lernen.","en":"It\'s hard to say no. Still, I have to learn it."}],"vocab":[{"de":"das Gleichgewicht","en":"balance"},{"de":"die Work-Life-Balance","en":"work-life balance"},{"de":"der Feierabend","en":"end of the working day"},{"de":"zufrieden / unzufrieden","en":"satisfied / unsatisfied"},{"de":"die Diät, -en","en":"diet"},{"de":"erschöpft","en":"exhausted"},{"de":"die Belastung, -en","en":"strain"},{"de":"entspannen","en":"to relax"},{"de":"die Teilzeit / Vollzeit","en":"part-time / full-time"},{"de":"flexibel","en":"flexible"},{"de":"der Druck","en":"pressure"},{"de":"sich leisten","en":"to afford"},{"de":"obwohl","en":"although"},{"de":"trotzdem","en":"nevertheless, still"},{"de":"dennoch","en":"nevertheless"},{"de":"trotz (+ Gen.)","en":"despite"},{"de":"zwar … aber","en":"admittedly … but"},{"de":"die Überstunden (Pl.)","en":"overtime"},{"de":"die Erschöpfung","en":"exhaustion"},{"de":"das Burn-out","en":"burnout"},{"de":"das Homeoffice","en":"working from home"},{"de":"die Erreichbarkeit","en":"availability (being reachable)"},{"de":"abschalten","en":"to switch off (mentally)"},{"de":"der Ausgleich","en":"balance, compensation"},{"de":"das Ehrenamt, ¨er","en":"volunteer work"},{"de":"die Elternzeit","en":"parental leave"},{"de":"die Gleitzeit","en":"flexitime"},{"de":"priorisieren","en":"to prioritise"},{"de":"Nein sagen","en":"to say no"},{"de":"sich überfordert fühlen","en":"to feel overwhelmed"}],"reading":"Mia arbeitet Vollzeit, obwohl sie zwei kleine Kinder hat. Sie ist oft erschöpft. Trotzdem ist sie mit ihrer Arbeit zufrieden, denn ihre Arbeitszeiten sind flexibel. Jonas dagegen hat keine Kinder, aber er macht viele Überstunden. Obwohl sein Gehalt gut ist, möchte er weniger arbeiten. Ravi sagt: „Ich arbeite gern viel. Trotzdem nehme ich mir am Wochenende immer Zeit für Freunde.“ Mia antwortet: „Das ist klug. Obwohl die Arbeit wichtig ist, ist das Leben wichtiger.“","tasks":[{"q":"Ich gehe spazieren, ___ es kalt ist.","a":"obwohl"},{"q":"Es ist kalt. ___ gehe ich spazieren.","a":"Trotzdem"},{"q":"Er ist nicht gekommen, ___ er Zeit hatte.","a":"obwohl"},{"q":"Verbinde (obwohl): Sie ist krank. Sie arbeitet.","a":"Obwohl sie krank ist, arbeitet sie. / Sie arbeitet, obwohl sie krank ist."},{"q":"Verbinde (trotzdem): Das Hotel war teuer. Wir haben es gebucht.","a":"Das Hotel war teuer. Trotzdem haben wir es gebucht."},{"q":"weil oder obwohl? Ich trinke Kaffee, ___ ich müde bin.","a":"weil"},{"q":"weil oder obwohl? Ich kann nicht schlafen, ___ ich müde bin.","a":"obwohl"},{"q":"[Mix] Obwohl ich ___ gestern früh ins Bett gegangen ___, bin ich müde. (sein)","a":"bin"},{"q":"[Mix] Er hat ___ ___ Kollegen geholfen, obwohl er keine Zeit hatte. (sein, Dativ)","a":"seinem"},{"q":"[Mix] Obwohl es teuer ___, ___ ich gern eine größere Wohnung. (sein, haben – Konj. II)","a":"ist / hätte"},{"q":"___ es kalt ist, geht er schwimmen. (obwohl/trotzdem)","a":"Obwohl"},{"q":"Es ist kalt. ___ geht er schwimmen. (obwohl/trotzdem)","a":"Trotzdem"},{"q":"Verbinde mit obwohl: Sie ist krank. Sie geht zur Arbeit.","a":"Obwohl sie krank ist, geht sie zur Arbeit."},{"q":"Verbinde mit trotzdem: Er hat wenig Geld. Er fährt in Urlaub.","a":"Er hat wenig Geld. Trotzdem fährt er in Urlaub."},{"q":"Verbinde mit obwohl (Satz 2): Wir gingen spazieren. Es regnete.","a":"Wir gingen spazieren, obwohl es regnete."},{"q":"Genitiv: ___ des Regens gingen wir spazieren.","a":"Trotz"},{"q":"zwar … aber: Die Wohnung ist ___ klein, ___ sie ist günstig.","a":"zwar / aber"},{"q":"Satzstellung: Trotzdem ___ ich mitkommen. (wollen)","a":"will"},{"q":"weil oder obwohl? Er ist glücklich, ___ er wenig verdient.","a":"obwohl"},{"q":"Fehler? „Obwohl er ist müde, er arbeitet.“","a":"Obwohl er müde ist, arbeitet er."}],"exam":[{"q":"Warum ist Mia zufrieden?","a":"Weil ihre Arbeitszeiten flexibel sind."},{"q":"Was möchte Jonas, obwohl sein Gehalt gut ist?","a":"Weniger arbeiten."},{"q":"Wofür nimmt sich Ravi Zeit?","a":"Für Freunde am Wochenende."},{"q":"Umformen (trotzdem → obwohl): Er hat Geld. Trotzdem kauft er nichts.","a":"Obwohl er Geld hat, kauft er nichts."},{"q":"Umformen (obwohl → trotzdem): Obwohl es regnet, fahren wir los.","a":"Es regnet. Trotzdem fahren wir los."},{"q":"Ergänze: Sie ist zufrieden, ___ sie wenig verdient.","a":"obwohl"},{"q":"Fehler? „Trotzdem ich arbeite viel.“","a":"Trotzdem arbeite ich viel."},{"q":"Was machen Sie, obwohl Sie wissen, dass es nicht gut ist?","a":"","m":"Ich esse oft Schokolade, obwohl ich weiß, dass sie ungesund ist. Ich schlafe zu wenig. Trotzdem sehe ich abends lange Serien."},{"q":"Ist eine gute Work-Life-Balance wichtig? Argumentieren Sie mit obwohl/trotzdem.","a":"","m":"Eine gute Work-Life-Balance ist sehr wichtig. Obwohl viele Menschen gern arbeiten, brauchen sie Freizeit. Die Arbeit ist manchmal stressig, trotzdem sollte man Pausen machen."},{"q":"Vollzeit oder Teilzeit: Nennen Sie Vor- und Nachteile.","a":"","m":"Vollzeit bringt mehr Geld und bessere Chancen im Beruf. Obwohl man in Teilzeit weniger verdient, hat man mehr Zeit für die Familie. Trotzdem können sich nicht alle Teilzeit leisten."}],"speak":["Die Frau arbeitet noch, obwohl …? (Vermutung)","Beschreibe das Bild mit trotzdem: __Es ist schon spät. Trotzdem …__","Was hast du gemacht, obwohl du keine Lust hattest?","Sollte man im Urlaub E-Mails lesen? Pro/Contra."],"reading2":{"title":"Immer erreichbar?","text":"Durch Smartphones und Homeoffice hat sich die Arbeitswelt stark verändert. Viele Beschäftigte lesen ihre E-Mails, obwohl sie längst Feierabend haben. Eine Studie zeigt: Fast die Hälfte der Angestellten in Deutschland ist auch in der Freizeit für den Arbeitgeber erreichbar. Zwar finden viele die Flexibilität gut, aber sie fühlen sich trotzdem häufiger gestresst. „Obwohl ich zu Hause bin, bin ich nicht wirklich zu Hause“, sagt Katrin, 41, Projektmanagerin. „Mein Kopf ist immer im Büro.“ Ärzte warnen: Wer nie abschalten kann, riskiert Schlafstörungen und im schlimmsten Fall ein Burn-out. Einige Firmen reagieren darauf. Bei manchen großen Unternehmen werden abends keine E-Mails mehr an die Mitarbeiter weitergeleitet. Andere haben feste Regeln: Nach 19 Uhr erwartet niemand eine Antwort. Trotz dieser Maßnahmen bleibt die Verantwortung oft beim Einzelnen. Experten raten, das Diensthandy am Abend bewusst auszuschalten und klare Grenzen zu setzen. Wichtig ist auch ein Ausgleich: Sport, Hobbys, ein Ehrenamt oder einfach Zeit mit der Familie. Katrin hat inzwischen eine Regel für sich gefunden: „Obwohl es mir am Anfang schwerfiel, lasse ich das Diensthandy jetzt am Wochenende im Schrank. Und die Firma existiert trotzdem noch.“"},"dialog":[{"who":"Leila","de":"Ravi, es ist schon zehn Uhr abends. Warum arbeitest du noch?"},{"who":"Ravi","de":"Obwohl ich den ganzen Tag gearbeitet habe, bin ich nicht fertig geworden."},{"who":"Leila","de":"Du bist doch erst seit drei Wochen in der neuen Firma. Erwartet dein Chef das?"},{"who":"Ravi","de":"Nein, eigentlich nicht. Trotzdem will ich einen guten Eindruck machen."},{"who":"Leila","de":"Das verstehe ich. Aber wenn du jetzt schon jeden Abend arbeitest, wird das zur Gewohnheit."},{"who":"Ravi","de":"Du hast zwar recht, aber das Projekt ist wirklich wichtig."},{"who":"Leila","de":"Dann sprich mit deinem Chef darüber. Obwohl es schwer ist: Du musst lernen, Prioritäten zu setzen."}],"dq":[{"q":"Warum arbeitet Ravi noch um zehn Uhr abends?","a":"Er ist nicht fertig geworden (und will einen guten Eindruck machen)."},{"q":"Erwartet der Chef, dass Ravi abends arbeitet?","a":"Nein, eigentlich nicht."},{"q":"Was rät Leila ihm?","a":"Mit dem Chef zu sprechen und Prioritäten zu setzen."}],"en":{"title":"Contrasts: obwohl and trotzdem","theme":"Work–life balance","expl":["**obwohl** (although) starts a subordinate clause – verb at the end: __Ich gehe joggen, obwohl es regnet.__","**trotzdem** (nevertheless, still) is an adverb – in position 1 (verb right after it) or in the middle: __Es regnet. Trotzdem gehe ich joggen. / Ich gehe trotzdem joggen.__","Both show an unexpected contrast – the opposite of weil/deshalb."],"use":""},"check":[{"re":"\\\\bobwohl\\\\b|\\\\btrotzdem\\\\b","label":"obwohl or trotzdem"}]},{"n":37,"pos":38,"level":"B1","title":"Konsequenzen: deshalb, deswegen, darum, sonst","theme":"Umwelt und Verkehr","scene":"city","rec":[20,21,29,36],"expl":["**deshalb, deswegen, darum** (therefore) zeigen eine **Folge**. Sie sind **Adverbien**: Position 1 → Verb danach (**Inversion**): __Es regnet, **deshalb nehme** ich den Bus.__","Vergleiche: **weil** (Grund, Nebensatz) ↔ **deshalb** (Folge, Hauptsatz): __Ich nehme den Bus, **weil** es **regnet**. = Es regnet, **deshalb nehme** ich den Bus.__","**sonst** (otherwise) zeigt eine negative Folge: __Beeil dich, **sonst verpassen** wir den Zug.__","Auch **also** (so) und **daher** funktionieren gleich."],"use":"Argumentieren (Umwelt, Verkehr, Gesundheit), Präsentation: Vorteile/Nachteile.","table":[["Konnektor","Satz 1 (Grund)","Satz 2 (Folge)"],["deshalb","Die Luft ist schlecht,","**deshalb fahre** ich Rad."],["deswegen","Ich will Geld sparen.","**Deswegen kaufe** ich kein Auto."],["darum","Der Bus ist voll,","**darum gehen** wir zu Fuß."],["sonst","Wir müssen Energie sparen,","**sonst wird** der Strom teurer."],["weil (Vergleich)","Ich fahre Rad,","**weil** die Luft schlecht **ist**."]],"examples":[{"de":"Ich will die Umwelt schützen, deshalb fahre ich Fahrrad.","en":"I want to protect the environment, so I cycle."},{"de":"Die Mieten in der Stadt sind hoch, deswegen ziehen viele aufs Land.","en":"City rents are high, so many move to the country."},{"de":"Es gibt oft Stau, darum nehme ich die S-Bahn.","en":"There are often traffic jams, so I take the S-Bahn."},{"de":"Mach das Licht aus, sonst verbrauchen wir zu viel Strom.","en":"Turn off the light, otherwise we use too much electricity."},{"de":"Ravi hat kein Auto, deshalb ist er flexibel mit dem Zug.","en":"Ravi has no car, so he\'s flexible by train."},{"de":"Plastik ist schlecht für das Meer, deshalb benutzen wir Stofftaschen.","en":"Plastic is bad for the sea, so we use cloth bags."},{"de":"Wir müssen den Müll trennen, sonst gibt es Ärger mit dem Vermieter.","en":"We must separate rubbish, otherwise there\'s trouble with the landlord."},{"de":"Der Zug war billig, darum sind wir nicht geflogen.","en":"The train was cheap, so we didn\'t fly."},{"de":"Er hat den Bus verpasst, deswegen ist er zu spät gekommen.","en":"He missed the bus, so he came late."},{"de":"Beeil dich, sonst ist der Markt geschlossen!","en":"Hurry up or the market will be closed!"},{"de":"Der Bus ist billiger. Deshalb fahre ich mit dem Bus.","en":"The bus is cheaper. That\'s why I take the bus."},{"de":"Es gibt oft Stau, deswegen fahre ich mit dem Fahrrad.","en":"There are often traffic jams, so I cycle."},{"de":"Beeil dich, sonst verpassen wir den Zug!","en":"Hurry up, otherwise we\'ll miss the train!"},{"de":"Plastik ist schlecht für die Umwelt, darum kaufe ich Mehrwegflaschen.","en":"Plastic is bad for the environment, that\'s why I buy returnable bottles."},{"de":"Wir trennen den Müll, sonst müssen wir mehr bezahlen.","en":"We separate our rubbish, otherwise we have to pay more."},{"de":"Die Preise sind gestiegen, daher fahren viele weniger Auto.","en":"Prices have risen, hence many people drive less."},{"de":"Ich habe kein Auto, also nehme ich die Bahn.","en":"I don\'t have a car, so I take the train."},{"de":"Der Klimawandel hat viele Ursachen.","en":"Climate change has many causes."},{"de":"Auf Mehrwegflaschen gibt es Pfand.","en":"There\'s a deposit on returnable bottles."},{"de":"Wir sollten nachhaltiger leben.","en":"We should live more sustainably."}],"vocab":[{"de":"die Umwelt","en":"environment"},{"de":"schützen","en":"to protect"},{"de":"der Müll","en":"rubbish"},{"de":"trennen","en":"to separate"},{"de":"der Stau, -s","en":"traffic jam"},{"de":"die Energie","en":"energy"},{"de":"der Strom","en":"electricity"},{"de":"verbrauchen","en":"to consume"},{"de":"das Plastik","en":"plastic"},{"de":"der Klimawandel","en":"climate change"},{"de":"öffentliche Verkehrsmittel","en":"public transport"},{"de":"umweltfreundlich","en":"eco-friendly"},{"de":"deshalb","en":"therefore"},{"de":"deswegen","en":"that\'s why"},{"de":"darum","en":"that\'s why"},{"de":"daher","en":"hence"},{"de":"sonst","en":"otherwise"},{"de":"also","en":"so, therefore"},{"de":"folglich","en":"consequently"},{"de":"die Folge, -n","en":"consequence"},{"de":"die Ursache, -n","en":"cause"},{"de":"der Treibhauseffekt","en":"greenhouse effect"},{"de":"die Emission, -en","en":"emission"},{"de":"erneuerbare Energien (Pl.)","en":"renewable energy"},{"de":"die Solaranlage, -n","en":"solar system (panels)"},{"de":"das Elektroauto, -s","en":"electric car"},{"de":"der Fleischkonsum","en":"meat consumption"},{"de":"die Mehrwegflasche, -n","en":"returnable bottle"},{"de":"das Pfand","en":"deposit (on bottles)"},{"de":"nachhaltig","en":"sustainable"}],"reading":"In Berlin fahren viele Menschen mit dem Fahrrad, denn die Stadt hat viele Radwege. Ravi hatte in Mumbai ein Motorrad. In Berlin gibt es gute öffentliche Verkehrsmittel, deshalb braucht er kein Fahrzeug. Er möchte die Umwelt schützen, darum trennt er seinen Müll genau. Am Anfang war das schwer: „Gelbe Tonne, blaue Tonne, Biotonne – das ist kompliziert!“ Anna hat es ihm erklärt: „Du musst den Müll richtig trennen, sonst ärgert sich der Hausmeister.“","tasks":[{"q":"Es regnet, ___ bleibe ich zu Hause. (Folge)","a":"deshalb"},{"q":"Ich bin krank. ___ ___ ich nicht zur Arbeit. (deswegen, gehen)","a":"Deswegen gehe"},{"q":"Zieh eine Jacke an, ___ frierst du.","a":"sonst"},{"q":"Umformen (deshalb): Ich lerne, weil ich eine Prüfung habe.","a":"Ich habe eine Prüfung, deshalb lerne ich."},{"q":"Umformen (weil): Der Zug ist teuer, darum fahre ich mit dem Bus.","a":"Ich fahre mit dem Bus, weil der Zug teuer ist."},{"q":"Fehler? „Ich habe Hunger, deshalb ich esse.“","a":"…, deshalb esse ich."},{"q":"Verbinde (sonst): Wir müssen jetzt gehen. Wir kommen zu spät.","a":"Wir müssen jetzt gehen, sonst kommen wir zu spät."},{"q":"[Mix] Ravi möchte fit bleiben, deshalb ___ er jeden Tag ___ Fahrrad. (fahren, mit dem)","a":"fährt / mit dem"},{"q":"[Mix] Obwohl Autos praktisch sind, ___ ich keins. (wollen)","a":"will"},{"q":"[Mix] Der Müll wird getrennt, ___ er recycelt werden kann. (Zweck)","a":"damit"},{"q":"Es regnet. ___ nehme ich einen Schirm. (deshalb/obwohl)","a":"Deshalb"},{"q":"Beeil dich, ___ kommen wir zu spät! (sonst/deshalb)","a":"sonst"},{"q":"Verbinde mit deshalb: Ich bin krank. Ich bleibe zu Hause.","a":"Ich bin krank, deshalb bleibe ich zu Hause."},{"q":"Verbinde mit sonst: Du musst lernen. Du bestehst die Prüfung nicht.","a":"Du musst lernen, sonst bestehst du die Prüfung nicht."},{"q":"Verbinde mit darum: Er hat keine Zeit. Er kommt nicht mit.","a":"Er hat keine Zeit, darum kommt er nicht mit."},{"q":"Satzstellung: Deswegen ___ wir mit dem Zug. (fahren)","a":"fahren"},{"q":"weil → deshalb: Ich fahre Fahrrad, weil es gesund ist. → Es ist gesund, ___ ___ ich Fahrrad.","a":"deshalb fahre"},{"q":"Pfand: Wo bekommt man das Pfand zurück? Im ___.","a":"Supermarkt"},{"q":"also oder sonst? Ich habe Hunger, ___ koche ich jetzt.","a":"also"},{"q":"Fehler? „Ich habe kein Geld, deshalb ich bleibe zu Hause.“","a":"Ich habe kein Geld, deshalb bleibe ich zu Hause."}],"exam":[{"q":"Warum braucht Ravi in Berlin kein Fahrzeug?","a":"Es gibt gute öffentliche Verkehrsmittel."},{"q":"Warum trennt er den Müll?","a":"Er möchte die Umwelt schützen."},{"q":"Was passiert, wenn man den Müll nicht trennt?","a":"Der Hausmeister ärgert sich."},{"q":"weil oder deshalb? Ich spare Energie, ___ Strom teuer ist.","a":"weil"},{"q":"weil oder deshalb? Strom ist teuer, ___ spare ich Energie.","a":"deshalb"},{"q":"Ergänze: Fahr langsam, ___ bekommst du eine Strafe.","a":"sonst"},{"q":"Verbinde (darum): Die Luft ist schmutzig. Viele Leute tragen Masken.","a":"Die Luft ist schmutzig, darum tragen viele Leute Masken."},{"q":"Was tun Sie für die Umwelt? Begründen Sie mit deshalb/weil.","a":"","m":"Ich fahre mit dem Fahrrad, weil das gut für die Umwelt ist. Ich kaufe wenig Plastik, deshalb nehme ich immer eine Tasche mit. Ich esse wenig Fleisch, deswegen ist mein CO2-Fußabdruck kleiner."},{"q":"Auto oder Fahrrad in der Stadt? Präsentieren Sie Vor- und Nachteile.","a":"","m":"Mit dem Fahrrad ist man in der Stadt oft schneller, deshalb fahren viele Leute Rad. Man braucht keinen Parkplatz. Mit dem Auto kann man mehr transportieren, aber man steht oft im Stau. Darum finde ich das Fahrrad besser."},{"q":"Wie ist die Umweltsituation in Ihrem Heimatland?","a":"","m":"In meinem Heimatland ist die Luft in den Großstädten sehr schlecht. Es gibt viele Autos, deshalb gibt es viel Smog. Die Regierung pflanzt jetzt mehr Bäume."}],"speak":["Beschreibe den Verkehr auf dem Bild: Was ist gut / schlecht für die Umwelt?","Der Bus ist voll, deshalb …? Mach 3 Folgen.","Was passiert, wenn wir nichts tun? __Wir müssen … sonst …__","Wie kommst du zur Arbeit und warum? (deshalb)"],"reading2":{"title":"Müll trennen – eine deutsche Wissenschaft?","text":"Wer neu in Deutschland ist, wundert sich oft über die vielen Mülltonnen. In den meisten Häusern gibt es mindestens vier: die gelbe Tonne für Verpackungen aus Plastik und Metall, die blaue für Papier, die braune für Bioabfälle und die schwarze oder graue für den Restmüll. Glas bringt man zu großen Containern auf der Straße, getrennt nach Weiß-, Grün- und Braunglas. Warum ist das so kompliziert? Deutschland produziert pro Kopf sehr viel Verpackungsmüll. Deshalb hat man schon früh begonnen, Wertstoffe zu sammeln und zu recyceln. Aus altem Papier wird neues Papier, aus Bioabfällen entsteht Kompost oder Biogas. Wer den Müll nicht richtig trennt, verursacht Probleme: Die Sortieranlagen müssen mehr arbeiten, und manchmal müssen alle Mieter mehr Müllgebühren bezahlen. Deswegen achten Hausverwaltungen und Nachbarn genau darauf. Ein anderes typisch deutsches System ist das Pfand. Für viele Flaschen und Dosen bezahlt man beim Kauf 8 bis 25 Cent extra. Bringt man sie zurück in den Supermarkt, bekommt man das Geld wieder. Darum liegen in Deutschland vergleichsweise wenige Flaschen auf der Straße. Allerdings gibt es auch Kritik: Viele Menschen kaufen trotzdem zu viel Verpackung. Am besten wäre es also, Müll gar nicht erst entstehen zu lassen."},"dialog":[{"who":"Frau Lindner","de":"Junger Mann! Sie haben schon wieder den Karton in die schwarze Tonne geworfen!"},{"who":"Jonas","de":"Oh, Entschuldigung. Wohin gehört er denn?"},{"who":"Frau Lindner","de":"In die blaue Tonne, das ist doch Papier! Sonst bekommen wir Ärger mit der Hausverwaltung."},{"who":"Jonas","de":"Sie haben recht. Ich mache das sofort."},{"who":"Frau Lindner","de":"Und die Joghurtbecher gehören in die gelbe Tonne. Aber bitte leer!"},{"who":"Jonas","de":"Und die leeren Flaschen?"},{"who":"Frau Lindner","de":"Die mit Pfand bringen Sie in den Supermarkt. Deswegen bezahlen Sie ja das Pfand."},{"who":"Jonas","de":"Danke, Frau Lindner. Ohne Sie wäre ich verloren."}],"dq":[{"q":"In welche Tonne gehört der Karton?","a":"In die blaue Tonne (Papier)."},{"q":"Wohin gehören die Joghurtbecher?","a":"In die gelbe Tonne (leer)."},{"q":"Was macht man mit Pfandflaschen?","a":"Man bringt sie in den Supermarkt."}],"en":{"title":"Consequences: deshalb, deswegen, darum, sonst","theme":"Environment and traffic","expl":["**deshalb, deswegen, darum** (therefore, that\'s why) show a result. They are adverbs: in position 1 the verb follows directly: __Es regnet, deshalb nehme ich den Bus.__","Compare: **weil** gives the reason (subordinate clause), **deshalb** the result (main clause): __Ich nehme den Bus, weil es regnet. = Es regnet, deshalb nehme ich den Bus.__","**sonst** (otherwise) shows a negative result: __Beeil dich, sonst verpasst du den Zug.__"],"use":""},"check":[{"re":"\\\\b(deshalb|deswegen|darum|sonst|weil)\\\\b","label":"deshalb / deswegen / darum (+ verb right after)"}]},{"n":38,"pos":39,"level":"B1","title":"Zweiteilige Konnektoren","theme":"Medien und Internet","scene":"office","rec":[20,22,36,37],"expl":["Zweiteilige Konnektoren verbinden zwei Informationen elegant:","**sowohl … als auch** (both … and) · **nicht nur … sondern auch** (not only … but also) · **entweder … oder** (either … or) · **weder … noch** (neither … nor) · **zwar … aber** (it\'s true … but) · **je … desto** (the … the, siehe L42).","**weder … noch** ist schon negativ – **kein** zusätzliches nicht! **zwar … aber** ist perfekt für Vor- und Nachteile.","Wortstellung: Die Konnektoren stehen meist vor dem Satzteil, den sie betreffen: __Ich spreche **sowohl** Hindi **als auch** Englisch.__"],"use":"Prüfung Teil 2 (Präsentation): Vor- und Nachteile, Meinung – bringt höhere Punkte!","table":[["Konnektor","Bedeutung","Beispiel"],["sowohl … als auch","both … and","Ich nutze **sowohl** Instagram **als auch** WhatsApp."],["nicht nur … sondern auch","not only … but also","Das Handy ist **nicht nur** praktisch, **sondern auch** gefährlich."],["entweder … oder","either … or","**Entweder** lese ich Zeitung **oder** ich höre Podcasts."],["weder … noch","neither … nor","Er hat **weder** Facebook **noch** Instagram."],["zwar … aber","admittedly … but","Das Internet ist **zwar** nützlich, **aber** es macht süchtig."]],"examples":[{"de":"Ich lese Nachrichten sowohl online als auch in der Zeitung.","en":"I read news both online and in the newspaper."},{"de":"Soziale Medien sind nicht nur unterhaltsam, sondern auch informativ.","en":"Social media are not only entertaining but also informative."},{"de":"Entweder schaue ich eine Serie oder ich lese ein Buch.","en":"Either I watch a series or I read a book."},{"de":"Mein Opa hat weder ein Handy noch einen Computer.","en":"My grandpa has neither a mobile nor a computer."},{"de":"Das Smartphone ist zwar praktisch, aber man verliert viel Zeit.","en":"The smartphone is practical, but you lose a lot of time."},{"de":"Ravi telefoniert nicht nur mit seinen Eltern, sondern auch mit seiner Oma.","en":"Ravi calls not only his parents but also his grandma."},{"de":"Wir können entweder einen Film streamen oder ins Kino gehen.","en":"We can either stream a film or go to the cinema."},{"de":"Online-Shopping ist zwar bequem, aber schlecht für kleine Läden.","en":"Online shopping is convenient but bad for small shops."},{"de":"Weder Jonas noch Mia haben die E-Mail bekommen.","en":"Neither Jonas nor Mia got the email."},{"de":"Leila spricht sowohl Persisch als auch Deutsch fließend.","en":"Leila speaks both Persian and German fluently."},{"de":"Ich lese Nachrichten sowohl in der Zeitung als auch im Internet.","en":"I read the news both in the paper and online."},{"de":"Er hat weder einen Fernseher noch ein Radio.","en":"He has neither a TV nor a radio."},{"de":"Entweder wir streamen einen Film oder wir gehen ins Kino.","en":"Either we stream a film or we go to the cinema."},{"de":"Soziale Medien sind nicht nur unterhaltsam, sondern auch informativ.","en":"Social media are not only entertaining but also informative."},{"de":"Einerseits ist das Internet praktisch, andererseits macht es süchtig.","en":"On the one hand the internet is practical, on the other it\'s addictive."},{"de":"Je mehr ich am Handy bin, desto müder werde ich.","en":"The more I\'m on my phone, the more tired I get."},{"de":"Diese Nachricht ist eine Falschmeldung, teile sie nicht!","en":"This news is fake, don\'t share it!"},{"de":"Ich habe mein Streaming-Abo gekündigt.","en":"I\'ve cancelled my streaming subscription."},{"de":"Ich höre jeden Morgen einen Podcast auf Deutsch.","en":"I listen to a podcast in German every morning."},{"de":"Wie viele Stunden am Tag verbringst du vor dem Bildschirm?","en":"How many hours a day do you spend in front of a screen?"}],"vocab":[{"de":"die Medien (Pl.)","en":"media"},{"de":"soziale Netzwerke","en":"social networks"},{"de":"die Nachricht, -en","en":"news / message"},{"de":"die Zeitung, -en","en":"newspaper"},{"de":"die Serie, -n","en":"series"},{"de":"streamen","en":"to stream"},{"de":"das Smartphone, -s","en":"smartphone"},{"de":"die App, -s","en":"app"},{"de":"herunterladen","en":"to download"},{"de":"süchtig","en":"addicted"},{"de":"der Datenschutz","en":"data protection"},{"de":"die Informationsquelle, -n","en":"source of information"},{"de":"sowohl … als auch","en":"both … and"},{"de":"weder … noch","en":"neither … nor"},{"de":"entweder … oder","en":"either … or"},{"de":"nicht nur … sondern auch","en":"not only … but also"},{"de":"je … desto","en":"the … the"},{"de":"zwar … aber","en":"admittedly … but"},{"de":"einerseits … andererseits","en":"on the one hand … on the other hand"},{"de":"der Beitrag, ¨e","en":"post, contribution"},{"de":"teilen","en":"to share"},{"de":"liken","en":"to like (online)"},{"de":"der Kommentar, -e","en":"comment"},{"de":"die Falschmeldung, -en","en":"fake news"},{"de":"der Podcast, -s","en":"podcast"},{"de":"der Bildschirm, -e","en":"screen"},{"de":"die Werbung","en":"advertising"},{"de":"das Abonnement (Abo), -s","en":"subscription"},{"de":"kündigen","en":"to cancel (a subscription)"},{"de":"online / offline","en":"online / offline"}],"reading":"Ravi nutzt sowohl WhatsApp als auch Videoanrufe, um mit seiner Familie zu sprechen. Das Internet ist für ihn nicht nur praktisch, sondern auch wichtig gegen das Heimweh. Seine Oma hat zwar ein Smartphone, aber sie benutzt es kaum. Jonas dagegen hat weder Instagram noch TikTok. Er sagt: „Entweder ich lese ein Buch oder ich treffe Freunde. Soziale Medien sind zwar interessant, aber man verliert zu viel Zeit.“ Ravi findet: „Es kommt darauf an, wie man sie nutzt.“","tasks":[{"q":"Ich trinke ___ Tee ___ Kaffee. (both … and)","a":"sowohl / als auch"},{"q":"Er hat ___ Zeit ___ Geld. (neither … nor)","a":"weder / noch"},{"q":"___ kommst du mit ___ du bleibst hier.","a":"Entweder / oder"},{"q":"Das Auto ist ___ alt, ___ es fährt gut.","a":"zwar / aber"},{"q":"Sie ist ___ klug, ___ sehr nett. (not only … but also)","a":"nicht nur / sondern auch"},{"q":"Verbinde (weder … noch): Ich habe keinen Fernseher. Ich habe kein Radio.","a":"Ich habe weder einen Fernseher noch ein Radio."},{"q":"Fehler? „Ich esse weder Fleisch noch nicht Fisch.“","a":"Ich esse weder Fleisch noch Fisch."},{"q":"[Mix] Das Handy ist zwar ___ (teuer, Komp.) als das alte, aber es ist auch besser.","a":"teurer"},{"q":"[Mix] Wir können entweder ___ Kino gehen oder ___ Hause bleiben.","a":"ins / zu"},{"q":"[Mix] Soziale Medien sind nicht nur gut, sondern auch gefährlich, deshalb ___ man vorsichtig sein. (sollen, Rat)","a":"sollte"},{"q":"Er spricht ___ Englisch ___ Französisch. (beides)","a":"sowohl / als auch"},{"q":"Ich habe ___ Zeit ___ Geld. (nichts davon)","a":"weder / noch"},{"q":"___ du kommst mit, ___ du bleibst zu Hause.","a":"Entweder / oder"},{"q":"Sie ist ___ klug, ___ auch sehr nett.","a":"nicht nur / sondern"},{"q":"Je länger ich lerne, ___ besser verstehe ich.","a":"desto"},{"q":"Je ___ (viel) du übst, desto sicherer wirst du.","a":"mehr"},{"q":"___ ist die Stadt teuer, andererseits gibt es viele Jobs.","a":"Einerseits"},{"q":"Satzstellung nach desto: Je später es ist, desto müder ___ ich. (sein)","a":"bin"},{"q":"Verbinde: Er trinkt keinen Kaffee. Er trinkt keinen Tee. (weder … noch)","a":"Er trinkt weder Kaffee noch Tee."},{"q":"Fehler? „Je mehr ich lerne, desto ich weiß mehr.“","a":"Je mehr ich lerne, desto mehr weiß ich."}],"exam":[{"q":"Wie spricht Ravi mit seiner Familie?","a":"Über WhatsApp und Videoanrufe."},{"q":"Welche sozialen Medien hat Jonas?","a":"Keine (weder Instagram noch TikTok)."},{"q":"Was sagt Jonas über soziale Medien?","a":"Sie sind zwar interessant, aber man verliert zu viel Zeit."},{"q":"Ergänze: Ich lerne ___ mit Büchern ___ mit Apps. (both)","a":"sowohl / als auch"},{"q":"Ergänze: ___ rufe ich dich an ___ ich schreibe dir.","a":"Entweder / oder"},{"q":"Umformen (zwar … aber): Streaming ist billig. Es gibt zu viel Auswahl.","a":"Streaming ist zwar billig, aber es gibt zu viel Auswahl."},{"q":"Ergänze: Das Buch ist ___ spannend ___ lustig. (neither)","a":"weder / noch"},{"q":"Präsentieren Sie: „Soziale Medien – Vor- und Nachteile“ (mit zwar … aber, nicht nur … sondern auch).","a":"","m":"Soziale Medien sind zwar praktisch, aber sie kosten viel Zeit. Sie helfen nicht nur beim Kontakt mit Freunden, sondern auch bei der Jobsuche. Allerdings sind sie weder privat noch immer ehrlich."},{"q":"Welche Medien nutzen Sie und wofür?","a":"","m":"Ich nutze sowohl WhatsApp als auch Instagram. WhatsApp benutze ich für meine Familie, Instagram für Fotos. Nachrichten lese ich online."},{"q":"Sollten Kinder ein Smartphone haben? Diskutieren Sie.","a":"","m":"Kinder brauchen zwar ein Handy für Notfälle, aber kein Smartphone mit Internet. Ein Smartphone bringt nicht nur Spaß, sondern auch Gefahren."}],"speak":["Was machen die zwei am Computer? __Sie … entweder … oder …__","Wie nutzt du dein Handy? Benutze 3 zweiteilige Konnektoren.","Homeoffice: zwar … aber …","Wie haben sich die Medien seit deiner Kindheit geändert?"],"reading2":{"title":"Digital Detox – eine Woche ohne Smartphone","text":"Die Journalistin Sara Becker hat ein Experiment gemacht: eine Woche ganz ohne Smartphone. „Ich war weder auf Instagram noch auf WhatsApp. Ich habe mein Handy einfach in eine Schublade gelegt.“ Der erste Tag war schwierig. Sara griff ständig in ihre Tasche, obwohl das Handy gar nicht da war. Sie wusste weder, wie spät es war, noch, wie das Wetter wird. „Ich musste mir sogar einen Wecker kaufen!“ Am zweiten Tag merkte sie, wie oft sie früher gewartet hatte, ohne sich zu langweilen: Sie hatte einfach auf das Handy geschaut. Jetzt beobachtete sie in der U-Bahn die Menschen, las ein Buch oder dachte nach. Nicht nur ihre Konzentration wurde besser, sondern auch ihr Schlaf. „Je weniger Zeit ich vor dem Bildschirm verbrachte, desto ruhiger wurde ich.“ Natürlich gab es auch Probleme. Einerseits genoss sie die Ruhe, andererseits verpasste sie eine Einladung, die nur in einer Gruppe verschickt worden war. Und ohne Navigation verlief sie sich zweimal in der Stadt. Nach einer Woche nahm Sara das Handy wieder aus der Schublade. Ihr Fazit: „Ich will nicht ohne Smartphone leben. Aber ich nutze es jetzt bewusster. Entweder ich arbeite damit, oder es liegt in einem anderen Zimmer.“"},"dialog":[{"who":"Mia","de":"Hast du gehört? Morgen soll der Unterricht an der Uni ausfallen."},{"who":"Jonas","de":"Wer sagt das?"},{"who":"Mia","de":"Das steht in einem Beitrag, den alle teilen."},{"who":"Jonas","de":"Hm. Steht das sowohl auf der Webseite der Uni als auch in der offiziellen E-Mail?"},{"who":"Mia","de":"Weder noch, glaube ich. Nur in diesem Beitrag."},{"who":"Jonas","de":"Dann wäre ich vorsichtig. Je mehr Leute so etwas teilen, desto glaubwürdiger wirkt es. Aber es kann eine Falschmeldung sein."},{"who":"Mia","de":"Du hast recht. Entweder ich schreibe meiner Professorin, oder ich gehe einfach hin."}],"dq":[{"q":"Was soll morgen passieren?","a":"Der Unterricht an der Uni soll ausfallen."},{"q":"Wo steht die Information?","a":"Nur in einem Beitrag in den sozialen Medien (nicht auf der Webseite / in der E-Mail)."},{"q":"Was will Mia tun?","a":"Entweder ihrer Professorin schreiben oder einfach hingehen."}],"en":{"title":"Two-part connectors","theme":"Media and the internet","expl":["Two-part connectors link two pieces of information elegantly: **sowohl … als auch** (both … and), **nicht nur … sondern auch** (not only … but also), **entweder … oder** (either … or), **weder … noch** (neither … nor), **zwar … aber** (admittedly … but), **je … desto** (the more … the more).","**weder … noch** is already negative – don\'t add nicht: __Ich habe weder Zeit noch Geld.__"],"use":""},"check":[{"re":"\\\\b(zwar|nicht nur|sowohl|entweder|weder)\\\\b","label":"two-part connectors (zwar … aber, nicht nur … sondern auch)"}]},{"n":39,"pos":40,"level":"B1","title":"Das Passiv","theme":"Prozesse und Produktion","scene":"kitchen","rec":[6,17,35,37],"expl":["Im **Passiv** ist die **Handlung** wichtig, nicht die Person: __Das Brot **wird gebacken**.__","Form **Präsens:** **werden + Partizip II** · **Präteritum:** **wurde + Partizip II** · **Perfekt:** **ist + Partizip II + worden** · **mit Modalverb:** **muss + Partizip II + werden**.","Das **Akkusativ-Objekt** im Aktiv wird zum **Subjekt** (Nominativ) im Passiv: __Man repariert **den** Wagen → **Der** Wagen wird repariert.__","Die Person (falls wichtig) mit **von + Dativ**: __Das Essen wird **von meiner Mutter** gekocht.__"],"use":"Rezepte, Prozesse, Regeln, Nachrichten beschreiben; Präsentationen und Lesetexte.","table":[["Zeit","Aktiv","Passiv"],["Präsens","Man kocht den Reis.","Der Reis **wird gekocht**."],["Präteritum","Man baute das Haus 1900.","Das Haus **wurde** 1900 **gebaut**."],["Perfekt","Man hat das Auto repariert.","Das Auto **ist repariert worden**."],["Modalverb","Man muss den Müll trennen.","Der Müll **muss getrennt werden**."],["mit Person","Mein Vater kocht das Essen.","Das Essen wird **von meinem Vater** gekocht."]],"examples":[{"de":"Zuerst wird der Reis gewaschen.","en":"First the rice is washed."},{"de":"Dann werden die Zwiebeln geschnitten.","en":"Then the onions are chopped."},{"de":"Das Brandenburger Tor wurde 1791 gebaut.","en":"The Brandenburg Gate was built in 1791."},{"de":"In Deutschland wird viel Brot gegessen.","en":"A lot of bread is eaten in Germany."},{"de":"Der Müll wird jeden Dienstag abgeholt.","en":"The rubbish is collected every Tuesday."},{"de":"Das Paket ist schon geschickt worden.","en":"The parcel has already been sent."},{"de":"Hier darf nicht geraucht werden.","en":"Smoking is not allowed here."},{"de":"Das Essen wurde von Ravi gekocht.","en":"The food was cooked by Ravi."},{"de":"Die Formulare müssen unterschrieben werden.","en":"The forms must be signed."},{"de":"Tee wird in Indien seit Jahrhunderten getrunken.","en":"Tea has been drunk in India for centuries."},{"de":"Das Auto wird in Wolfsburg hergestellt.","en":"The car is made in Wolfsburg."},{"de":"Die Pakete werden morgen geliefert.","en":"The parcels will be delivered tomorrow."},{"de":"Der Brief wurde gestern abgeschickt.","en":"The letter was sent yesterday."},{"de":"Die Kartoffeln werden zuerst geschält.","en":"The potatoes are peeled first."},{"de":"Das Buch wurde von einer jungen Autorin geschrieben.","en":"The book was written by a young author."},{"de":"Hier wird nicht geraucht!","en":"There is no smoking here!"},{"de":"Die Firma wurde 1950 gegründet.","en":"The company was founded in 1950."},{"de":"Der Fehler wurde schnell entdeckt.","en":"The mistake was quickly discovered."},{"de":"Am Ende wird die Qualität kontrolliert.","en":"At the end the quality is checked."},{"de":"Wann wurde das Telefon erfunden?","en":"When was the telephone invented?"}],"vocab":[{"de":"herstellen","en":"to produce"},{"de":"die Produktion","en":"production"},{"de":"die Fabrik, -en","en":"factory"},{"de":"schneiden (geschnitten)","en":"to cut"},{"de":"braten (gebraten)","en":"to fry"},{"de":"würzen","en":"to season"},{"de":"mischen","en":"to mix"},{"de":"backen (gebacken)","en":"to bake"},{"de":"servieren","en":"to serve"},{"de":"bauen","en":"to build"},{"de":"reparieren","en":"to repair"},{"de":"liefern","en":"to deliver"},{"de":"werden + Partizip II","en":"passive"},{"de":"wurde + Partizip II","en":"passive (past)"},{"de":"von (+ Dat.)","en":"by (agent)"},{"de":"erfinden","en":"to invent"},{"de":"entdecken","en":"to discover"},{"de":"gründen","en":"to found"},{"de":"verkaufen","en":"to sell"},{"de":"verpacken","en":"to pack"},{"de":"transportieren","en":"to transport"},{"de":"kontrollieren","en":"to check"},{"de":"der Rohstoff, -e","en":"raw material"},{"de":"das Produkt, -e","en":"product"},{"de":"das Werk, -e","en":"plant, works"},{"de":"der Ablauf, ¨e","en":"process"},{"de":"die Maschine, -n","en":"machine"},{"de":"die Qualität","en":"quality"},{"de":"der Kunde, -n / die Kundin, -nen","en":"customer"},{"de":"hergestellt in","en":"made in"}],"reading":"So wird Masala Chai gemacht: Zuerst wird Wasser in einem Topf gekocht. Dann werden Ingwer, Kardamom und Zimt dazugegeben. Danach wird schwarzer Tee hinzugefügt. Nach drei Minuten wird Milch dazugegossen. Zum Schluss wird der Chai mit Zucker gesüßt und heiß serviert. Ravi erklärt Anna das Rezept. Anna sagt: „In Deutschland wird Tee meistens ohne Milch getrunken.“ Ravi lacht: „In Indien wird Chai überall verkauft – sogar im Zug!“","tasks":[{"q":"Präsens Passiv: Man trinkt hier viel Kaffee. → Hier ___ viel Kaffee ___.","a":"wird / getrunken"},{"q":"Präsens Passiv: Man schneidet die Tomaten. → Die Tomaten ___ ___.","a":"werden geschnitten"},{"q":"Präteritum Passiv: Man baute die Brücke 1950. → Die Brücke ___ 1950 ___.","a":"wurde / gebaut"},{"q":"Perfekt Passiv: Man hat den Brief geschickt. → Der Brief ___ ___ ___.","a":"ist geschickt worden"},{"q":"Modal Passiv: Man muss das Fenster schließen. → Das Fenster ___ ___ ___.","a":"muss geschlossen werden"},{"q":"Mit von: Die Ärztin untersucht den Patienten. → Der Patient ___ ___ ___ Ärztin untersucht.","a":"wird von der"},{"q":"Aktiv oder Passiv? „Ich werde Lehrer.“","a":"Aktiv (werden = become)"},{"q":"[Mix] Zuerst ___ die Zwiebeln geschnitten, danach ___ sie gebraten. (werden)","a":"werden / werden"},{"q":"[Mix] Der Tisch wurde ___ ___ Wand gestellt. (an, die)","a":"an die"},{"q":"[Mix] Das Paket konnte nicht geliefert werden, weil niemand zu Hause ___. (sein – Prät.)","a":"war"},{"q":"Passiv Präsens: Man repariert das Auto. → Das Auto ___ ___.","a":"wird repariert"},{"q":"Passiv Präsens: Man trennt den Müll. → Der Müll ___ ___.","a":"wird getrennt"},{"q":"Passiv Präsens: Man baut neue Häuser. → Neue Häuser ___ ___.","a":"werden gebaut"},{"q":"Passiv Präteritum: Man fand den Schlüssel. → Der Schlüssel ___ ___.","a":"wurde gefunden"},{"q":"Passiv Präteritum: Man gründete die Firma 1990. → Die Firma ___ 1990 ___.","a":"wurde / gegründet"},{"q":"Passiv mit von: Der Arzt untersucht den Patienten. → Der Patient wird ___ ___ Arzt untersucht.","a":"von dem"},{"q":"Passiv Präsens: Hier ___ Deutsch ___. (sprechen)","a":"wird / gesprochen"},{"q":"Aktiv oder Passiv? Das Paket ___ morgen geliefert.","a":"wird"},{"q":"Passiv mit Modalverb: Der Brief muss heute ___ ___. (schicken)","a":"geschickt werden"},{"q":"Fehler? „Das Haus wird 1900 gebaut wurde.“","a":"Das Haus wurde 1900 gebaut."}],"exam":[{"q":"Was wird zuerst gemacht?","a":"Wasser wird gekocht."},{"q":"Wann wird Milch dazugegeben?","a":"Nach drei Minuten."},{"q":"Wie wird Tee in Deutschland meistens getrunken?","a":"Ohne Milch."},{"q":"Passiv: Der Mechaniker repariert das Auto.","a":"Das Auto wird vom Mechaniker repariert."},{"q":"Passiv (Prät.): Man erfand das Telefon im 19. Jahrhundert.","a":"Das Telefon wurde im 19. Jahrhundert erfunden."},{"q":"Passiv (Modal): Man muss die Rechnung bezahlen.","a":"Die Rechnung muss bezahlt werden."},{"q":"Aktiv: Die Kinder werden von der Lehrerin abgeholt.","a":"Die Lehrerin holt die Kinder ab."},{"q":"Beschreiben Sie im Passiv ein Rezept aus Ihrem Land.","a":"","m":"Zuerst wird der Reis gewaschen. Dann werden die Zwiebeln geschnitten und in Öl gebraten. Danach werden die Gewürze dazugegeben. Zum Schluss wird alles zusammen gekocht."},{"q":"Wie wird in Ihrem Land ein Fest gefeiert?","a":"","m":"Diwali wird im Herbst gefeiert. Die Häuser werden mit Lichtern geschmückt. Es werden Süßigkeiten gegessen und Geschenke verteilt."},{"q":"Was wird in Ihrer Stadt / Ihrem Land produziert?","a":"","m":"In meiner Stadt werden Autos und Medikamente produziert. In meinem Land wird viel Tee angebaut."}],"speak":["Was wird in der Küche gemacht? __Das Gemüse wird …__","Wie wird ein Brot gebacken? Beschreibe den Prozess.","Was wird in deiner Familie am Wochenende gemacht?","Was muss vor einer Party gemacht werden?"],"reading2":{"title":"Wie wird Schokolade gemacht?","text":"Schokolade gehört zu den beliebtesten Süßigkeiten der Deutschen. Aber wie wird sie eigentlich hergestellt? Der wichtigste Rohstoff ist Kakao. Kakaobäume wachsen nur in tropischen Ländern, zum Beispiel in der Elfenbeinküste, in Ghana oder in Ecuador. Die Früchte werden mit der Hand geerntet und geöffnet. Dann werden die Kakaobohnen einige Tage fermentiert. Dabei entsteht das typische Aroma. Danach werden die Bohnen in der Sonne getrocknet und in Säcken nach Europa transportiert. In der Fabrik werden sie zuerst gereinigt und geröstet. Anschließend werden die Bohnen gebrochen und zu einer flüssigen Masse gemahlen. Für Milchschokolade wird diese Masse mit Zucker, Milchpulver und Kakaobutter gemischt. Die Mischung wird stundenlang gerührt, damit die Schokolade schön glatt wird. Dieser Schritt wurde 1879 von dem Schweizer Rodolphe Lindt erfunden. Zum Schluss wird die Schokolade in Formen gegossen, gekühlt und verpackt. Ein Problem wird oft vergessen: Auf vielen Kakaoplantagen werden die Arbeiter sehr schlecht bezahlt. Deshalb wird empfohlen, Schokolade mit einem Fairtrade-Siegel zu kaufen."},"dialog":[{"who":"Führerin","de":"Willkommen in unserer Brauerei! Hier wird seit 1832 Bier gebraut."},{"who":"Ravi","de":"Wie wird das Bier hergestellt?"},{"who":"Führerin","de":"Zuerst wird das Malz mit Wasser gemischt und erhitzt. Dann wird Hopfen dazugegeben."},{"who":"Mia","de":"Und wann kommt die Hefe dazu?"},{"who":"Führerin","de":"Nachdem die Flüssigkeit abgekühlt wurde. Dann gärt das Bier einige Wochen."},{"who":"Ravi","de":"Wird das Bier hier auch abgefüllt?"},{"who":"Führerin","de":"Ja, in der Halle nebenan werden täglich zwanzigtausend Flaschen abgefüllt."},{"who":"Mia","de":"Und wohin wird es geliefert?"},{"who":"Führerin","de":"Vor allem in die Region. Aber ein Teil wird sogar nach Japan exportiert."}],"dq":[{"q":"Seit wann wird in der Brauerei Bier gebraut?","a":"Seit 1832."},{"q":"Wann kommt die Hefe dazu?","a":"Nachdem die Flüssigkeit abgekühlt wurde."},{"q":"Wie viele Flaschen werden täglich abgefüllt?","a":"Zwanzigtausend."}],"en":{"title":"The passive voice","theme":"Processes and production","expl":["In the passive the **action** matters, not who does it: __Das Brot wird gebacken.__ = The bread is (being) baked.","Present: **werden + participle** · Past: **wurde + participle** · Perfekt: **ist + participle + worden** · With a modal verb: **muss + participle + werden**.","The accusative object of the active sentence becomes the subject of the passive: __Man repariert den Wagen. → Der Wagen wird repariert.__ The person doing it can be added with **von** + dative."],"use":""},"check":[{"re":"\\\\b(wird|werden|wurde|wurden)\\\\b[^.!?]*\\\\b(ge\\\\w+(t|en)|\\\\w+iert)\\\\b","label":"Passiv (wird/wurde + Partizip II)"}]},{"n":40,"pos":41,"level":"B1","title":"Genitiv und Präpositionen: wegen, trotz, während, statt","theme":"Nachrichten und Alltag","scene":"station","rec":[5,13,23,36,37],"expl":["Der **Genitiv** zeigt **Besitz**: __das Auto **des** Mannes, die Tasche **der** Frau__. Maskulin/neutral bekommen **-s/-es** am Nomen. Bei Namen: **Ravis** Wohnung. Umgangssprachlich oft **von + Dativ**: __das Auto von dem Mann__.","**Genitiv-Präpositionen:** **wegen** (because of), **trotz** (despite), **während** (during), **(an)statt** (instead of), **innerhalb/außerhalb** (inside/outside).","Adjektive im Genitiv enden fast immer auf **-en**: __wegen des schlecht**en** Wetters__.","Vergleiche: __wegen des Regens__ = __weil es regnet__ · __trotz des Regens__ = __obwohl es regnet__."],"use":"Nachrichten verstehen, formelle Texte, Gründe/Gegengründe kurz ausdrücken.","table":[["Fall","maskulin","feminin","neutral","Plural"],["Genitiv (bestimmt)","des Zug**es**","der Bahn","des Wetter**s**","der Züge"],["Genitiv (unbestimmt)","eines Mann**es**","einer Frau","eines Kind**es**","– (von + Dat.)"],["wegen","wegen des Streiks","wegen der Baustelle","wegen des Unfalls","wegen der Ferien"],["trotz","trotz des Regens","trotz der Kälte","trotz des Wetters","trotz der Probleme"],["während","während des Films","während der Fahrt","während des Essens","während der Ferien"]],"examples":[{"de":"Wegen des Streiks fahren heute keine Züge.","en":"Because of the strike no trains are running today."},{"de":"Trotz der Verspätung war Ravi pünktlich im Büro.","en":"Despite the delay Ravi was on time at the office."},{"de":"Während der Fahrt hat er ein Buch gelesen.","en":"During the journey he read a book."},{"de":"Das ist die Wohnung meines Bruders.","en":"That\'s my brother\'s flat."},{"de":"Statt eines Autos kaufe ich ein Fahrrad.","en":"Instead of a car I\'m buying a bike."},{"de":"Wegen des schlechten Wetters wurde das Konzert abgesagt.","en":"The concert was cancelled due to bad weather."},{"de":"Die Farbe des Mantels gefällt mir.","en":"I like the colour of the coat."},{"de":"Innerhalb einer Woche müssen Sie antworten.","en":"You must reply within a week."},{"de":"Leilas Praxis ist in der Nähe des Bahnhofs.","en":"Leila\'s practice is near the station."},{"de":"Trotz des Stresses ist er gut gelaunt.","en":"Despite the stress he\'s in a good mood."},{"de":"Wegen des Streiks fahren heute keine Züge.","en":"Because of the strike there are no trains today."},{"de":"Trotz des schlechten Wetters kamen viele Besucher.","en":"Despite the bad weather, many visitors came."},{"de":"Während der Bauarbeiten ist die Straße gesperrt.","en":"During the construction work the road is closed."},{"de":"Statt eines Busses fährt ein Taxi.","en":"A taxi runs instead of a bus."},{"de":"Innerhalb einer Woche müssen Sie antworten.","en":"You must reply within a week."},{"de":"Wegen eines Stromausfalls war das Kaufhaus geschlossen.","en":"Because of a power cut the department store was closed."},{"de":"Die Feuerwehr war schnell vor Ort.","en":"The fire brigade was quickly on the scene."},{"de":"Wegen des Unwetters gibt es eine Warnung.","en":"There\'s a warning because of the storm."},{"de":"Bitte beachten Sie die Umleitung.","en":"Please follow the diversion."},{"de":"Der Grund des Unfalls ist noch unklar.","en":"The cause of the accident is still unclear."}],"vocab":[{"de":"der Streik, -s","en":"strike"},{"de":"die Baustelle, -n","en":"construction site"},{"de":"der Unfall, ¨e","en":"accident"},{"de":"absagen","en":"to cancel"},{"de":"die Durchsage, -n","en":"announcement"},{"de":"der Fahrgast, ¨e","en":"passenger"},{"de":"der Ersatzverkehr","en":"replacement service"},{"de":"die Störung, -en","en":"disruption"},{"de":"die Kälte / die Hitze","en":"cold / heat"},{"de":"das Unwetter, -","en":"storm"},{"de":"die Nähe","en":"vicinity"},{"de":"gut gelaunt","en":"in a good mood"},{"de":"wegen (+ Gen.)","en":"because of"},{"de":"trotz (+ Gen.)","en":"despite"},{"de":"während (+ Gen.)","en":"during"},{"de":"statt / anstatt (+ Gen.)","en":"instead of"},{"de":"innerhalb (+ Gen.)","en":"within"},{"de":"außerhalb (+ Gen.)","en":"outside of"},{"de":"die Schlagzeile, -n","en":"headline"},{"de":"der Bericht, -e","en":"report"},{"de":"die Ursache, -n","en":"cause"},{"de":"die Polizei","en":"police"},{"de":"die Feuerwehr","en":"fire brigade"},{"de":"der Rettungsdienst","en":"ambulance service"},{"de":"verletzt","en":"injured"},{"de":"gesperrt","en":"closed (road)"},{"de":"die Umleitung, -en","en":"diversion"},{"de":"der Stromausfall, ¨e","en":"power cut"},{"de":"das Hochwasser","en":"flood"},{"de":"die Warnung, -en","en":"warning"}],"reading":"Durchsage am Bahnhof: „Liebe Fahrgäste, wegen eines Streiks fallen heute viele Züge aus. Wegen der Baustelle zwischen Berlin und Hamburg gibt es einen Ersatzverkehr mit Bussen. Wir bitten um Ihr Verständnis.“ Ravi ärgert sich. Trotz des Streiks muss er heute nach Hamburg fahren, denn der Termin seines Kunden ist wichtig. Er nimmt statt des Zuges einen Fernbus. Während der Fahrt bereitet er die Präsentation vor. Trotz der Probleme kommt er rechtzeitig an.","tasks":[{"q":"Das ist das Auto ___ Nachbarn. (der)","a":"des"},{"q":"Die Tasche ___ Lehrerin ist rot. (die)","a":"der"},{"q":"Wegen ___ Regens bleiben wir zu Hause. (der)","a":"des"},{"q":"Trotz ___ Kälte gehen wir spazieren. (die)","a":"der"},{"q":"Während ___ Essens spricht man nicht. (das)","a":"des"},{"q":"Umformen (wegen): Ich komme später, weil es einen Stau gibt.","a":"Wegen eines Staus komme ich später."},{"q":"Umformen (trotz): Obwohl es regnet, joggt er.","a":"Trotz des Regens joggt er."},{"q":"[Mix] Wegen ___ schlecht___ Wetters wurde das Spiel abgesagt.","a":"des schlechten"},{"q":"[Mix] Das ist die Wohnung ___ Freundin, ___ ich oft besuche. (mein-, Relativpronomen)","a":"meiner / die"},{"q":"[Mix] Statt ___ Taxis ___ ___ wir den Bus. (ein, nehmen – Perfekt)","a":"eines / haben genommen"},{"q":"___ des Regens bleiben wir zu Hause. (wegen/trotz)","a":"Wegen"},{"q":"___ der Kälte gehen wir schwimmen. (wegen/trotz)","a":"Trotz"},{"q":"Genitiv: wegen ___ Streiks (der)","a":"des"},{"q":"Genitiv: trotz ___ Hitze (die)","a":"der"},{"q":"Genitiv: während ___ Unterrichts (der)","a":"des"},{"q":"Genitiv: das Auto ___ Nachbarn (mein)","a":"meines"},{"q":"Genitiv: das Ende ___ Films (der)","a":"des"},{"q":"Statt ___ Kuchens nehme ich ein Eis. (ein)","a":"eines"},{"q":"Umformen: Weil es regnet, bleiben wir zu Hause. → ___ ___ Regens bleiben wir zu Hause.","a":"Wegen des"},{"q":"Fehler? „Wegen dem schlechten Wetter fällt das Fest aus.“ (schriftlich)","a":"Wegen des schlechten Wetters fällt das Fest aus."}],"exam":[{"q":"Warum fallen heute viele Züge aus?","a":"Wegen eines Streiks."},{"q":"Womit fährt Ravi statt mit dem Zug?","a":"Mit einem Fernbus."},{"q":"Was macht er während der Fahrt?","a":"Er bereitet die Präsentation vor."},{"q":"Ergänze: Wegen ___ Krankheit (meine) kann ich nicht kommen.","a":"meiner"},{"q":"Ergänze: Der Bruder ___ Freund___ (mein) ist Arzt.","a":"meines Freundes"},{"q":"Umformen (während): Als der Film lief, ist er eingeschlafen.","a":"Während des Films ist er eingeschlafen."},{"q":"Umformen (weil): Wegen der Hitze bleiben wir drinnen.","a":"Weil es heiß ist, bleiben wir drinnen."},{"q":"Sie hatten eine schwierige Reise. Erzählen Sie mit wegen, trotz, während.","a":"","m":"Wegen eines Streiks fuhr mein Zug nicht. Trotz des schlechten Wetters nahm ich ein Taxi. Während der Fahrt telefonierte ich mit meinem Chef."},{"q":"Was machen Sie während der Ferien?","a":"","m":"Während der Ferien besuche ich meine Familie. Ich schlafe lange und lese viel."},{"q":"Schreiben Sie eine Entschuldigungs-E-Mail: Sie kommen wegen … zu spät.","a":"","m":"Sehr geehrte Frau Lange, leider komme ich heute wegen eines Unfalls auf der Autobahn etwa 30 Minuten zu spät. Ich bitte um Entschuldigung. Mit freundlichen Grüßen, Ravi Sharma"}],"speak":["Hör dir die Durchsage an (Lesetext) und erkläre sie einem Freund.","Was machen die Leute während des Wartens?","Warum hat der Zug vielleicht Verspätung? __Wegen …__","Trotz welcher Probleme reist du gern?"],"reading2":{"title":"Lokalnachrichten","text":"Unwetter über Berlin: Wegen eines heftigen Gewitters ist es am Dienstagabend in mehreren Stadtteilen zu Problemen gekommen. Innerhalb einer Stunde fiel so viel Regen wie sonst in zwei Wochen. Zahlreiche Keller liefen voll, und die Feuerwehr musste über 300 Mal ausrücken. Während des Sturms stürzten mehrere Bäume auf Straßen und Gleise. Deshalb war der S-Bahn-Verkehr zwischen Ostkreuz und Erkner bis Mittwochmorgen unterbrochen. Statt der S-Bahn fuhren Ersatzbusse. Trotz des Chaos wurde niemand schwer verletzt. Eine Radfahrerin wurde von einem Ast leicht am Arm verletzt und vom Rettungsdienst behandelt. In Teilen von Köpenick gab es wegen eines umgestürzten Strommasts für etwa drei Stunden einen Stromausfall. Der Deutsche Wetterdienst hatte bereits am Nachmittag eine Warnung herausgegeben. Die Polizei bittet die Bürger, sich in den nächsten Tagen von Parks und Wäldern fernzuhalten, da wegen der beschädigten Bäume weiterhin Gefahr besteht. Für das Wochenende wird wieder sonniges Wetter erwartet."},"dialog":[{"who":"Durchsage","de":"Sehr geehrte Fahrgäste, wegen einer Signalstörung hat der RE1 nach Frankfurt (Oder) circa vierzig Minuten Verspätung."},{"who":"Ravi","de":"Vierzig Minuten! Ich habe um zehn einen Termin."},{"who":"Frau","de":"Sie können auch mit der S-Bahn fahren und in Erkner umsteigen."},{"who":"Durchsage","de":"Aufgrund von Bauarbeiten fährt die S-Bahn zwischen Ostkreuz und Erkner nicht. Bitte nutzen Sie den Ersatzverkehr mit Bussen."},{"who":"Ravi","de":"Na toll. Trotz der Bauarbeiten gibt es also keine schnelle Alternative."},{"who":"Frau","de":"Rufen Sie doch an und sagen Sie, dass Sie später kommen."},{"who":"Ravi","de":"Ja, das mache ich. Wegen der Bahn bin ich diese Woche schon zum zweiten Mal zu spät."}],"dq":[{"q":"Warum hat der RE1 Verspätung?","a":"Wegen einer Signalstörung."},{"q":"Warum fährt die S-Bahn nicht?","a":"Wegen Bauarbeiten."},{"q":"Was macht Ravi?","a":"Er ruft an und sagt, dass er später kommt."}],"en":{"title":"Genitive and the prepositions wegen, trotz, während, statt","theme":"News and everyday life","expl":["The **genitive** shows possession: __das Auto des Mannes, die Tasche der Frau__ (the man\'s car, the woman\'s bag). Masculine and neuter nouns add -s/-es. With names just add -s: __Ravis Wohnung__.","In everyday speech **von + dative** often replaces it: __das Auto von dem Mann__.","Genitive prepositions: **wegen** (because of), **trotz** (despite), **während** (during), **(an)statt** (instead of), innerhalb/außerhalb (inside/outside of)."],"use":""},"check":[{"re":"\\\\b(wegen|trotz|während|statt|anstatt)\\\\b","label":"wegen, trotz, während, statt (+ Genitiv)"}]},{"n":41,"pos":42,"level":"B1","title":"Futur I und die vielen Funktionen von werden","theme":"Zukunftspläne","scene":"classroom","rec":[11,25,28,29,39],"expl":["**Futur I** = **werden (Position 2) + Infinitiv (Ende)**: __Ich **werde** nach Indien **fliegen**.__ Oft reicht das **Präsens + Zeitangabe** (__Morgen fliege ich …__). Futur benutzt man für **Pläne, Versprechen, Vorhersagen** und **Vermutungen** (+ wohl): __Er **wird wohl** krank **sein**.__","**werden hat 4 Funktionen:** 1) Vollverb **werden** = become (__Ich werde Arzt.__) 2) **Futur** (__Ich werde lernen.__) 3) **Passiv** (__Das Haus wird gebaut.__) 4) **Konjunktiv II** würde (__Ich würde gern …__).","Im Nebensatz steht werden am Ende: __…, dass ich die Prüfung bestehen **werde**.__"],"use":"Prüfung: über Pläne und Zukunft sprechen, Versprechen, Vermutungen bei Bildern.","table":[["Funktion","Form","Beispiel"],["Vollverb (become)","werden + Nomen/Adjektiv","Ravi **wird** Teamleiter. Es **wird** kalt."],["Futur I","werden + Infinitiv","Ich **werde** im Mai **heiraten**."],["Vermutung","werden + wohl + Infinitiv","Sie **wird wohl** im Stau **stehen**."],["Passiv","werden + Partizip II","Der Reis **wird gekocht**."],["Konjunktiv II","würde + Infinitiv","Ich **würde** gern **kommen**."]],"examples":[{"de":"Ich werde nächstes Jahr die B2-Prüfung machen.","en":"I\'ll take the B2 exam next year."},{"de":"Es wird morgen regnen.","en":"It will rain tomorrow."},{"de":"Keine Sorge, ich werde dir helfen!","en":"Don\'t worry, I\'ll help you!"},{"de":"Leila wird bald Fachärztin.","en":"Leila will soon become a specialist."},{"de":"Jonas ist nicht da. Er wird wohl krank sein.","en":"Jonas isn\'t here. He\'s probably ill."},{"de":"Wir werden sehen.","en":"We\'ll see."},{"de":"In zehn Jahren werden Autos selbst fahren.","en":"In ten years cars will drive themselves."},{"de":"Ich hoffe, dass ich einen guten Job finden werde.","en":"I hope I\'ll find a good job."},{"de":"Das Projekt wird nächste Woche präsentiert.","en":"The project will be presented next week. (Passiv Präsens mit Zukunftsbedeutung)"},{"de":"Ich verspreche dir, dass ich pünktlich sein werde.","en":"I promise I\'ll be on time."},{"de":"Ich werde nächstes Jahr die B1-Prüfung machen.","en":"I will take the B1 exam next year."},{"de":"Es wird morgen regnen.","en":"It will rain tomorrow."},{"de":"Er wird wohl schon zu Hause sein.","en":"He\'ll probably be at home already."},{"de":"In Zukunft werden Roboter viele Arbeiten übernehmen.","en":"In future robots will take over a lot of work."},{"de":"Ich verspreche dir, ich werde pünktlich sein.","en":"I promise you, I\'ll be on time."},{"de":"Sie wird Ärztin.","en":"She is going to be a doctor."},{"de":"Was wirst du nach dem Studium machen?","en":"What will you do after your studies?"},{"de":"Das wird schon klappen!","en":"It\'ll work out!"},{"de":"Wir werden sehen.","en":"We\'ll see."},{"de":"Eines Tages werde ich mich selbstständig machen.","en":"One day I\'ll become self-employed."}],"vocab":[{"de":"die Zukunft","en":"future"},{"de":"der Plan, ¨e","en":"plan"},{"de":"planen","en":"to plan"},{"de":"versprechen","en":"to promise"},{"de":"die Vorhersage, -n","en":"forecast"},{"de":"vermuten","en":"to assume"},{"de":"wahrscheinlich","en":"probably"},{"de":"bald","en":"soon"},{"de":"in Zukunft","en":"in future"},{"de":"der Traumjob, -s","en":"dream job"},{"de":"selbstständig","en":"self-employed"},{"de":"heiraten","en":"to marry"},{"de":"werden (wird)","en":"will, to become"},{"de":"die Prognose, -n","en":"forecast"},{"de":"die Entwicklung, -en","en":"development"},{"de":"künstliche Intelligenz (KI)","en":"artificial intelligence"},{"de":"der Roboter, -","en":"robot"},{"de":"die Digitalisierung","en":"digitalisation"},{"de":"ersetzen","en":"to replace"},{"de":"entstehen","en":"to arise"},{"de":"sich entwickeln","en":"to develop"},{"de":"voraussichtlich","en":"probably, expected"},{"de":"vermutlich","en":"presumably"},{"de":"bestimmt","en":"certainly"},{"de":"eines Tages","en":"one day"},{"de":"in zehn Jahren","en":"in ten years"},{"de":"der Ruhestand","en":"retirement"},{"de":"die Familie gründen","en":"to start a family"},{"de":"sich selbstständig machen","en":"to become self-employed"},{"de":"der Vorsatz, ¨e","en":"resolution"}],"reading":"Frau Klein fragt am letzten Kurstag: „Was werdet ihr nach dem Kurs machen?“ Ravi antwortet: „Ich werde im Dezember die Prüfung machen und danach werde ich meine Eltern besuchen. Nächstes Jahr werde ich hoffentlich Teamleiter.“ Leila sagt: „Ich werde als Ärztin arbeiten. Aber zuerst muss mein Diplom anerkannt werden.“ Ein Teilnehmer fehlt. Frau Klein vermutet: „Er wird wohl noch schlafen!“ Alle lachen. „Ich bin sicher, dass ihr alle die Prüfung bestehen werdet.“","tasks":[{"q":"Futur: Ich fahre nach Paris. → Ich ___ nach Paris ___.","a":"werde / fahren"},{"q":"Futur: Wir lernen morgen. → Wir ___ morgen ___.","a":"werden / lernen"},{"q":"Vermutung: Er ist wohl zu Hause. → Er ___ wohl zu Hause ___.","a":"wird / sein"},{"q":"Funktion? „Sie wird Lehrerin.“","a":"Vollverb (become)"},{"q":"Funktion? „Die Tür wird geöffnet.“","a":"Passiv"},{"q":"Funktion? „Ich würde gern tanzen.“","a":"Konjunktiv II"},{"q":"Nebensatz: Ich glaube, dass es morgen ___ ___. (regnen, Futur)","a":"regnen wird"},{"q":"[Mix] Ich werde ___ ___ Prüfung gut vorbereiten. (sich, auf die)","a":"mich auf die"},{"q":"[Mix] Nachdem ich die Prüfung bestanden habe, ___ ich ___ Freunden feiern. (werden, mit mein-)","a":"werde / mit meinen"},{"q":"[Mix] Wenn ich mehr Geld ___, ___ ich ein Haus kaufen. (haben, werden – Konj. II)","a":"hätte / würde"},{"q":"Futur I: Ich ___ morgen anrufen.","a":"werde"},{"q":"Futur I: Du ___ das schaffen!","a":"wirst"},{"q":"Futur I: Es ___ bald regnen.","a":"wird"},{"q":"Futur I: Wir ___ im Sommer heiraten.","a":"werden"},{"q":"Futur I: ___ ihr zur Party kommen?","a":"Werdet"},{"q":"Futur I: Sie (Pl.) ___ uns besuchen.","a":"werden"},{"q":"Baue Futur I: ich / nächstes Jahr / nach Japan / fliegen","a":"Ich werde nächstes Jahr nach Japan fliegen."},{"q":"Vermutung: Er ist bestimmt krank. → Er ___ wohl krank ___.","a":"wird / sein"},{"q":"werden als Vollverb: Sie möchte Ärztin werden. → Sie ___ Ärztin.","a":"wird"},{"q":"Fehler? „Ich werde morgen gehe ins Kino.“","a":"Ich werde morgen ins Kino gehen."}],"exam":[{"q":"Was wird Ravi im Dezember machen?","a":"Die Prüfung machen."},{"q":"Was muss zuerst mit Leilas Diplom passieren?","a":"Es muss anerkannt werden."},{"q":"Was vermutet Frau Klein über den fehlenden Teilnehmer?","a":"Er wird wohl noch schlafen."},{"q":"Futur: Das Wetter wird schön. → morgen","a":"Das Wetter wird morgen schön (sein)."},{"q":"Vermutung: Wo ist Anna? (im Büro)","a":"Sie wird wohl im Büro sein."},{"q":"Ergänze: Ich verspreche, dass ich dich anrufen ___.","a":"werde"},{"q":"Bestimme die Funktion: „Das Essen wurde serviert.“","a":"Passiv (Präteritum)"},{"q":"Wie wird Ihr Leben in 10 Jahren aussehen?","a":"","m":"In zehn Jahren werde ich hoffentlich eine eigene Wohnung haben. Ich werde gut Deutsch sprechen. Vielleicht werde ich Kinder haben."},{"q":"Wie wird die Welt im Jahr 2050 sein? Machen Sie Vorhersagen.","a":"","m":"Im Jahr 2050 werden mehr Menschen in Städten leben. Autos werden selbst fahren. Wahrscheinlich wird es wärmer sein."},{"q":"Was werden Sie nach der B1-Prüfung machen?","a":"","m":"Nach der B1-Prüfung werde ich feiern. Dann werde ich mit B2 anfangen."}],"speak":["Was werden die Teilnehmer nach dem Kurs machen? (Vermutung)","Was wird wohl die Lehrerin sagen?","Mach 3 Versprechen: __Ich werde …__","Wie wird Berlin / Mumbai in 30 Jahren aussehen?"],"reading2":{"title":"Die Arbeitswelt von morgen","text":"Wie werden wir in zwanzig Jahren arbeiten? Diese Frage beschäftigt Wissenschaftler, Politiker und Unternehmen. Fest steht: Die Digitalisierung wird viele Berufe verändern. Experten erwarten, dass künstliche Intelligenz einfache Routineaufgaben übernehmen wird, zum Beispiel in der Buchhaltung, im Kundenservice oder in Lagern. Viele Menschen haben deshalb Angst, dass Maschinen sie ersetzen werden. Doch die meisten Forscher sind optimistischer. Sie glauben, dass gleichzeitig neue Berufe entstehen werden, die wir heute noch gar nicht kennen. Vor zwanzig Jahren gab es schließlich auch noch keine App-Entwickler oder Social-Media-Manager. Wichtiger als ein bestimmter Beruf wird in Zukunft die Fähigkeit sein, ständig Neues zu lernen. Auch der Arbeitsort wird sich verändern: Viele werden voraussichtlich teilweise von zu Hause arbeiten. Und die Menschen werden vermutlich länger arbeiten, weil die Gesellschaft älter wird. Manche Berufe werden aber bestimmt bleiben: Pflegekräfte, Erzieher oder Handwerker werden auch in Zukunft dringend gebraucht. „Ein Roboter wird keine Heizung reparieren und kein Kind trösten“, sagt die Zukunftsforscherin Anja Helm. Ihr Rat an junge Menschen: „Lernt Sprachen, lernt mit Technik umzugehen – und bleibt neugierig.“"},"dialog":[{"who":"Mia","de":"Was wirst du machen, wenn du mit dem Studium fertig bist?"},{"who":"Tomás","de":"Ich werde wahrscheinlich ein Jahr in Deutschland arbeiten. Und dann sehen wir weiter."},{"who":"Mia","de":"Wirst du nach Brasilien zurückgehen?"},{"who":"Tomás","de":"Vielleicht eines Tages. Meine Eltern werden langsam älter."},{"who":"Mia","de":"Ich werde bestimmt in Freiburg bleiben. Ich möchte Lehrerin werden."},{"who":"Tomás","de":"Du wirst eine super Lehrerin! Du erklärst so gut."},{"who":"Mia","de":"Danke! Und wer weiß, vielleicht werde ich dich in Brasilien besuchen."},{"who":"Tomás","de":"Das wirst du! Ich zeige dir dann São Paulo."}],"dq":[{"q":"Was wird Tomás nach dem Studium wahrscheinlich machen?","a":"Ein Jahr in Deutschland arbeiten."},{"q":"Warum denkt er an Brasilien?","a":"Seine Eltern werden älter."},{"q":"Was möchte Mia werden?","a":"Lehrerin."}],"en":{"title":"Future tense and the many uses of werden","theme":"Plans for the future","expl":["Future: **werden** (position 2) + **infinitive** (end): __Ich werde nach Indien fliegen.__ Often the present + a time word is enough: __Morgen fliege ich nach Indien.__","The future is used for plans, promises, predictions and guesses (+ wohl): __Er wird wohl krank sein.__ = He\'s probably ill.","**werden** has four jobs: become (__Ich werde Arzt.__), future (+ infinitive), passive (+ participle) and the würde-form (Konjunktiv II)."],"use":""},"check":[{"re":"\\\\b(werde|wirst|wird|werden|werdet)\\\\b[^.!?]*\\\\b\\\\w+(en|n)[.!?]?\\\\s*$|\\\\b(werde|wirst|wird|werden)\\\\b","label":"Futur I (werden + Infinitiv)"}]},{"n":42,"pos":43,"level":"B1","title":"je … desto + Abschluss: Eine Präsentation halten","theme":"Alles zusammen: Leben in Deutschland","scene":"classroom","rec":[17,21,22,25,33,36,37,38,40,41],"expl":["**je … desto/umso + Komparativ**: Der **je-Teil** ist ein **Nebensatz** (Verb am Ende), der **desto-Teil** hat **Inversion** (Verb direkt nach dem Komparativ): __**Je mehr** ich **übe**, **desto besser spreche** ich.__","Diese Lektion ist dein **Abschluss**: Eine B1-Präsentation (Goethe Teil 2) mit **allen** Strukturen. Folien: 1) Thema vorstellen 2) Eigene Erfahrung 3) Situation im Heimatland 4) Vor- und Nachteile + Meinung 5) Abschluss + Dank.","Pro Folie ca. 3–4 Sätze. Benutze **Konnektoren** (zuerst, außerdem, deshalb, obwohl, zwar … aber), **Perfekt/Präteritum** für Erfahrungen, **Komparativ** für Vergleiche, **Konjunktiv II** für Meinungen."],"use":"Prüfung Sprechen Teil 2 + 3 (Präsentation und Rückfragen).","table":[["Folie","Redemittel","Grammatik"],["1 Thema","Ich spreche heute über das Thema … Meine Präsentation hat drei Teile: …","zuerst, dann, zum Schluss"],["2 Erfahrung","Ich habe die Erfahrung gemacht, dass … Als ich nach Deutschland kam, …","Perfekt, als, dass"],["3 Heimatland","In Indien ist das anders: … Dort … mehr / weniger als hier.","Komparativ, Relativsatz"],["4 Vor-/Nachteile","Ein Vorteil ist, dass … Zwar …, aber … Meiner Meinung nach sollte man …","zwar…aber, sollte, obwohl"],["5 Abschluss","Zum Schluss möchte ich sagen: Je …, desto … Vielen Dank fürs Zuhören! Haben Sie Fragen?","je…desto"],["Rückfragen (Teil 3)","Danke für die Frage. Das ist eine gute Frage. Ich glaube, dass …","dass, weil"]],"examples":[{"de":"Je länger ich in Berlin wohne, desto besser gefällt es mir.","en":"The longer I live in Berlin, the more I like it."},{"de":"Je mehr man liest, desto größer wird der Wortschatz.","en":"The more you read, the bigger your vocabulary gets."},{"de":"Je früher du anfängst, umso schneller bist du fertig.","en":"The earlier you start, the sooner you\'re done."},{"de":"Je teurer die Wohnung ist, desto kleiner ist sie oft.","en":"The more expensive the flat, often the smaller it is."},{"de":"Ich spreche heute über das Thema „Allein leben“.","en":"Today I\'m talking about \\"living alone\\"."},{"de":"Als ich nach Deutschland kam, habe ich zum ersten Mal allein gewohnt.","en":"When I came to Germany I lived alone for the first time."},{"de":"In Indien wohnen junge Leute meistens bei ihren Eltern, bis sie heiraten.","en":"In India young people mostly live with their parents until they marry."},{"de":"Allein leben ist zwar ruhig, aber manchmal fühlt man sich einsam.","en":"Living alone is quiet, but sometimes you feel lonely."},{"de":"Meiner Meinung nach sollte jeder das einmal erleben.","en":"In my opinion everyone should experience it once."},{"de":"Vielen Dank fürs Zuhören. Haben Sie noch Fragen?","en":"Thank you for listening. Any questions?"},{"de":"Je öfter du sprichst, desto sicherer wirst du.","en":"The more often you speak, the more confident you get."},{"de":"Je früher wir losfahren, umso weniger Stau gibt es.","en":"The earlier we set off, the less traffic there is."},{"de":"Ich möchte euch heute mein Heimatland vorstellen.","en":"Today I\'d like to present my home country to you."},{"de":"Zunächst erzähle ich etwas über die Geschichte.","en":"First of all I\'ll tell you something about the history."},{"de":"Wie ihr auf dieser Folie sehen könnt, ist Indien sehr groß.","en":"As you can see on this slide, India is very big."},{"de":"Das bringt mich zum nächsten Punkt: dem Essen.","en":"That brings me to the next point: food."},{"de":"Abschließend möchte ich von meinen Erfahrungen berichten.","en":"Finally, I\'d like to report on my experiences."},{"de":"Zusammenfassend kann man sagen, dass es viele Gemeinsamkeiten gibt.","en":"In summary, one can say that there are many similarities."},{"de":"Je länger ich hier lebe, desto besser verstehe ich die Kultur.","en":"The longer I live here, the better I understand the culture."},{"de":"Vielen Dank für eure Aufmerksamkeit! Gibt es noch Fragen?","en":"Thank you for your attention! Any questions?"}],"vocab":[{"de":"die Präsentation, -en","en":"presentation"},{"de":"die Folie, -n","en":"slide"},{"de":"das Thema, Themen","en":"topic"},{"de":"die Erfahrung, -en","en":"experience"},{"de":"das Heimatland, ¨er","en":"home country"},{"de":"der Vorteil, -e / der Nachteil, -e","en":"advantage / disadvantage"},{"de":"einsam","en":"lonely"},{"de":"unabhängig","en":"independent"},{"de":"die Verantwortung","en":"responsibility"},{"de":"zusammenfassen","en":"to summarise"},{"de":"zuhören","en":"to listen"},{"de":"die Rückfrage, -n","en":"follow-up question"},{"de":"je … desto / umso","en":"the … the"},{"de":"die Gliederung, -en","en":"structure, outline"},{"de":"die Einleitung, -en","en":"introduction"},{"de":"der Hauptteil, -e","en":"main part"},{"de":"der Schluss","en":"conclusion"},{"de":"zunächst","en":"first of all"},{"de":"anschließend","en":"afterwards"},{"de":"abschließend","en":"finally, to conclude"},{"de":"Ich möchte euch heute … vorstellen.","en":"Today I\'d like to present … to you."},{"de":"Wie ihr auf der Folie sehen könnt, …","en":"As you can see on the slide, …"},{"de":"Das bringt mich zum nächsten Punkt.","en":"That brings me to the next point."},{"de":"Zusammenfassend kann man sagen, …","en":"In summary one can say …"},{"de":"Vielen Dank für eure Aufmerksamkeit.","en":"Thank you for your attention."},{"de":"Gibt es noch Fragen?","en":"Are there any more questions?"},{"de":"die Integration","en":"integration"},{"de":"der Alltag","en":"everyday life"},{"de":"die Gemeinsamkeit, -en","en":"similarity, common ground"},{"de":"der Unterschied, -e","en":"difference"}],"reading":"**Musterpräsentation (Ravi): „Allein leben – ja oder nein?“** Ich spreche heute über das Thema „Allein leben“. Zuerst erzähle ich von meiner Erfahrung, dann von der Situation in Indien, und zum Schluss sage ich meine Meinung. Als ich vor einem Jahr nach Berlin gekommen bin, habe ich zum ersten Mal allein gewohnt. Am Anfang war das schwer, weil ich weder kochen noch waschen konnte. In Indien ist das anders: Die meisten jungen Leute, die nicht verheiratet sind, wohnen bei ihren Eltern. Das ist nicht nur billiger, sondern man ist auch nie allein. Ein Vorteil vom Alleinleben ist, dass man unabhängig ist. Ein Nachteil ist, dass man sich manchmal einsam fühlt. Obwohl ich meine Familie vermisse, möchte ich diese Erfahrung nicht verlieren. Meiner Meinung nach sollte jeder junge Mensch einmal allein wohnen, denn je mehr Verantwortung man hat, desto schneller wird man erwachsen. Vielen Dank fürs Zuhören!","tasks":[{"q":"Je mehr ich schlafe, ___ fitter ___ ich. (sein)","a":"desto / bin"},{"q":"Je ___ (spät) es wird, desto ___ (müde) werde ich.","a":"später / müder"},{"q":"Verbinde: Man übt viel. Man spricht gut. (je … desto)","a":"Je mehr man übt, desto besser spricht man."},{"q":"Verbinde: Die Stadt ist groß. Das Leben ist teuer.","a":"Je größer die Stadt ist, desto teurer ist das Leben."},{"q":"Fehler? „Je mehr ich lerne, desto ich weiß mehr.“","a":"…, desto mehr weiß ich."},{"q":"Ergänze: Ein Vorteil ist, ___ man unabhängig ist.","a":"dass"},{"q":"Ergänze: Allein leben ist ___ ruhig, ___ manchmal einsam.","a":"zwar / aber"},{"q":"[Mix] Als ich nach Berlin ___ ___, konnte ich nicht kochen. (kommen, Perfekt)","a":"gekommen bin"},{"q":"[Mix] Die Leute, ___ ich hier kennengelernt habe, sind wie eine Familie.","a":"die"},{"q":"[Mix] Wegen ___ hoh___ Mieten wohnen viele Studenten in WGs.","a":"der hohen"},{"q":"Je mehr du liest, ___ mehr Wörter kennst du.","a":"desto"},{"q":"Je ___ (früh) du kommst, desto besser.","a":"früher"},{"q":"Je älter man wird, desto ___ ist man. (erfahren)","a":"erfahrener"},{"q":"Umformen: Du übst viel. Du wirst gut. → Je mehr du übst, desto ___ ___ du.","a":"besser wirst"},{"q":"Präsentation: ___ möchte ich über die Geschichte sprechen. (zuerst, formell)","a":"Zunächst"},{"q":"Präsentation: Das bringt mich zum nächsten ___.","a":"Punkt"},{"q":"Präsentation: ___ kann man sagen, dass … (zusammenfassen)","a":"Zusammenfassend"},{"q":"Präsentation: Vielen Dank für eure ___.","a":"Aufmerksamkeit"},{"q":"Satzstellung: Je länger der Film dauert, desto müder ___ ich. (werden)","a":"werde"},{"q":"Fehler? „Je mehr ich arbeite, desto ich bin müder.“","a":"Je mehr ich arbeite, desto müder bin ich."}],"exam":[{"q":"Wann hat Ravi zum ersten Mal allein gewohnt?","a":"Als er vor einem Jahr nach Berlin gekommen ist."},{"q":"Warum war es am Anfang schwer?","a":"Weil er weder kochen noch waschen konnte."},{"q":"Was ist Ravis Meinung?","a":"Jeder junge Mensch sollte einmal allein wohnen."},{"q":"Welche zwei Vorteile hat das Wohnen bei den Eltern (laut Text)?","a":"Es ist billiger und man ist nie allein."},{"q":"Bilde einen je…desto-Satz zum Thema Sport.","a":"z. B. Je mehr ich Sport mache, desto gesünder fühle ich mich."},{"q":"Halten Sie eine Präsentation (3 Min.): „Homeoffice – Vor- und Nachteile“.","a":"","m":"Mein Thema ist Homeoffice. Ich arbeite selbst zwei Tage pro Woche zu Hause. Ein Vorteil ist, dass man keine Zeit für den Weg braucht. Ein Nachteil ist, dass man die Kollegen selten sieht. In Indien ist Homeoffice in großen Firmen normal. Meiner Meinung nach ist eine Mischung am besten. Je flexibler die Arbeit ist, desto zufriedener sind die Mitarbeiter. Vielen Dank fürs Zuhören."},{"q":"Halten Sie eine Präsentation: „Kinder und Smartphones“.","a":"","m":"Mein Thema ist „Kinder und Smartphones“. Viele Kinder haben schon mit zehn Jahren ein Smartphone. Einerseits können Eltern ihre Kinder anrufen. Andererseits spielen Kinder oft zu lange. Meiner Meinung nach sollten Kinder erst mit zwölf ein Smartphone bekommen. Je später, desto besser. Danke!"},{"q":"Halten Sie eine Präsentation: „Online einkaufen oder im Geschäft?“","a":"","m":"Ich spreche über Online-Shopping. Ich kaufe oft online, weil es bequem ist. Außerdem sind die Preise oft niedriger. Aber im Geschäft kann man die Sachen anprobieren. Meiner Meinung nach ist das Geschäft besser für Kleidung und online besser für Technik."},{"q":"Geben Sie Ihrem Partner Feedback zu seiner Präsentation und stellen Sie eine Frage.","a":"","m":"Vielen Dank für deine Präsentation. Sie war gut strukturiert und deine Beispiele waren interessant. Ich habe eine Frage: Wie oft kaufst du selbst online?"},{"q":"Beantworten Sie eine Rückfrage zu Ihrer Präsentation: „Würden Sie wieder allein wohnen?“","a":"","m":"Gute Frage. Ja, ich würde wieder allein wohnen, weil ich Ruhe brauche. Aber ich würde gern näher bei meinen Freunden wohnen."}],"speak":["Halte eine Mini-Präsentation über deinen Deutschkurs mit allen 5 Folien.","Benutze mindestens: Perfekt, weil, obwohl, zwar … aber, Komparativ, Konjunktiv II, je … desto.","Nimm dich auf (3 Minuten), hör zu und prüfe: Verb auf Position 2? Verb am Ende im Nebensatz?","Gib Feedback: __Deine Präsentation war sehr interessant, weil … Ich habe eine Frage: …__"],"reading2":{"title":"Ravis Präsentation: Mein Weg nach Deutschland","text":"„Liebe Kursteilnehmer, liebe Frau Krüger, ich möchte euch heute erzählen, wie mein Leben in Deutschland in den letzten zwei Jahren war. Meine Präsentation hat drei Teile: zuerst meine Ankunft, dann die größten Schwierigkeiten und zum Schluss, was ich gelernt habe. Als ich vor zwei Jahren in Berlin ankam, sprach ich nur ein paar Sätze Deutsch. Ich wohnte in einer WG und arbeitete in einem englischsprachigen Team. Deshalb habe ich am Anfang wenig Deutsch gesprochen. Das bringt mich zum ersten Problem: Je weniger ich gesprochen habe, desto unsicherer wurde ich. Das zweite Problem war die Bürokratie. Für fast alles brauchte man einen Termin, ein Formular und viel Geduld. Wie ihr auf der Folie seht, habe ich im ersten Jahr elf Mal eine Behörde besucht! Das dritte Problem war das Wetter. Im November wird es hier schon um vier Uhr dunkel. Aber es gab auch viele schöne Erfahrungen. Meine Nachbarn, meine Mitbewohner und dieser Kurs haben mir sehr geholfen. Je mehr Menschen ich kennengelernt habe, desto mehr habe ich mich zu Hause gefühlt. Heute arbeite ich in einer deutschen Firma und spreche jeden Tag Deutsch. Zusammenfassend kann ich sagen: Der Anfang war schwer, aber es hat sich gelohnt. Mein Tipp: Habt keine Angst vor Fehlern. Vielen Dank für eure Aufmerksamkeit. Habt ihr noch Fragen?“"},"dialog":[{"who":"Aiko","de":"Danke, Ravi, das war sehr interessant. Darf ich eine Frage stellen?"},{"who":"Ravi","de":"Natürlich, gern."},{"who":"Aiko","de":"Was war für dich der wichtigste Moment beim Deutschlernen?"},{"who":"Ravi","de":"Ich glaube, als ich zum ersten Mal ein ganzes Telefonat mit dem Vermieter auf Deutsch geführt habe."},{"who":"Aiko","de":"Und was vermisst du am meisten aus Indien?"},{"who":"Ravi","de":"Das Essen und meine Familie. Aber je besser ich koche, desto weniger vermisse ich das Essen."},{"who":"Frau Krüger","de":"Sehr schön. Ravi, du hast frei gesprochen und deine Präsentation war klar gegliedert. Wirklich ausgezeichnet!"}],"dq":[{"q":"Was war für Ravi der wichtigste Moment beim Deutschlernen?","a":"Sein erstes ganzes Telefonat mit dem Vermieter auf Deutsch."},{"q":"Was vermisst Ravi am meisten?","a":"Das Essen und seine Familie."},{"q":"Was lobt Frau Krüger?","a":"Er hat frei gesprochen und die Präsentation war klar gegliedert."}],"en":{"title":"je … desto + final project: giving a presentation","theme":"Bringing it together: life in Germany","expl":["**je … desto/umso** + comparative = the more … the more. The je-part is a subordinate clause (verb at the end); the desto-part has the verb right after the comparative: __Je mehr ich übe, desto besser spreche ich.__","This lesson is your B1 final project: a presentation (Goethe B1 speaking part 2) using all the structures so far – topic, own experience, situation in your country, pros and cons, your opinion, conclusion."],"use":""},"check":[{"re":"\\\\bje\\\\b[^.!?]*\\\\b(desto|umso)\\\\b","label":"je … desto"},{"re":"\\\\b(zuerst|erstens|außerdem|einerseits|andererseits|zum schluss|meiner meinung nach)\\\\b","label":"presentation phrases (zuerst, außerdem, meiner Meinung nach)"}]},{"n":43,"pos":44,"level":"B2","title":"Konjunktiv I: indirekte Rede","theme":"Nachrichten und Berichte","scene":"office","rec":[21,32,35],"expl":["In Zeitungen, Berichten und Protokollen wird fremde Rede mit dem **Konjunktiv I** wiedergegeben. Er zeigt: __Das sagt jemand anderes – ich behaupte es nicht selbst.__","Bildung: Verbstamm + **-e, -est, -e, -en, -et, -en**. Am häufigsten ist die 3. Person: er **sei**, er **habe**, er **komme**, er **müsse**, er **werde**.","Wenn die Konjunktiv-I-Form gleich wie der Indikativ aussieht (meist im Plural: sie kommen), nimmt man **Konjunktiv II**: __sie **kämen**__ oder **würde + Infinitiv**.","Zeiten: Gegenwart → er **sei/habe/komme**; Vergangenheit → **habe/sei + Partizip II** (er habe gearbeitet, er sei gekommen); Zukunft → **werde + Infinitiv**."],"use":"Zeitungstexte verstehen, Aussagen neutral wiedergeben, Protokolle und Berichte schreiben.","table":[["Direkte Rede","Indirekte Rede (Konjunktiv I)","Hinweis"],["„Ich bin müde.“","Er sagt, er **sei** müde.","sein: sei, seist, sei, seien"],["„Ich habe keine Zeit.“","Sie erklärt, sie **habe** keine Zeit.","haben: habe, habest, habe"],["„Wir kommen später.“","Sie sagen, sie **kämen** später.","Plural = Indikativ → Konjunktiv II"],["„Ich habe den Bericht gelesen.“","Er behauptet, er **habe** den Bericht **gelesen**.","Vergangenheit"],["„Ich werde kündigen.“","Sie kündigte an, sie **werde kündigen**.","Zukunft"],["Frage: „Kommst du?“","Er fragte, **ob** sie **komme**.","indirekte Frage mit ob"]],"examples":[{"de":"Der Sprecher sagt, die Lage sei ernst.","en":"The spokesperson says the situation is serious."},{"de":"Die Firma teilt mit, sie habe die Preise gesenkt.","en":"The company announces it has lowered prices."},{"de":"Er behauptet, er wisse nichts davon.","en":"He claims he knows nothing about it."},{"de":"Die Ministerin erklärte, man werde die Regel prüfen.","en":"The minister said the rule would be examined."},{"de":"Laut Studie hätten viele Menschen Angst vor Veränderung.","en":"According to the study, many people fear change."},{"de":"Der Zeuge sagte aus, er sei um acht Uhr zu Hause gewesen.","en":"The witness stated he had been at home at eight."},{"de":"Sie fragte, ob das Projekt fertig sei.","en":"She asked whether the project was finished."},{"de":"Der Bericht hält fest, die Zahlen seien gestiegen.","en":"The report states the figures have risen."},{"de":"Er meinte, wir sollten noch warten.","en":"He said we should wait."},{"de":"Die Zeitung schreibt, der Streik dauere an.","en":"The paper writes the strike is continuing."},{"de":"Der Minister sagte, er sei mit dem Ergebnis zufrieden.","en":"The minister said he was satisfied with the result."},{"de":"Die Firma teilte mit, sie habe keine Kenntnis von dem Vorfall.","en":"The company stated it had no knowledge of the incident."},{"de":"Ein Sprecher betonte, man werde die Vorwürfe prüfen.","en":"A spokesperson stressed that the allegations would be examined."},{"de":"Laut Polizei sei niemand verletzt worden.","en":"According to the police, nobody was injured."},{"de":"Der Zeuge behauptete, er habe den Täter genau gesehen.","en":"The witness claimed he had seen the perpetrator clearly."},{"de":"Die Gewerkschaft fordert, die Löhne müssten steigen.","en":"The union demands that wages must rise."},{"de":"Sie fragte, ob die Lieferung pünktlich ankomme.","en":"She asked whether the delivery would arrive on time."},{"de":"Er sagte, sie hätten keine Zeit gehabt.","en":"He said they had had no time."},{"de":"Den Angaben zufolge wurde eine Einigung erzielt.","en":"According to the information, an agreement was reached."},{"de":"Die Ministerin räumte ein, es habe Fehler gegeben.","en":"The minister admitted there had been mistakes."}],"vocab":[{"de":"die indirekte Rede","en":"reported speech"},{"de":"mitteilen","en":"to announce, inform"},{"de":"behaupten","en":"to claim"},{"de":"erklären","en":"to state, explain"},{"de":"aussagen","en":"to testify"},{"de":"melden","en":"to report"},{"de":"zitieren","en":"to quote"},{"de":"die Quelle, -n","en":"source"},{"de":"laut (+ Dat./Gen.)","en":"according to"},{"de":"der Sprecher, -","en":"spokesperson"},{"de":"die Stellungnahme, -n","en":"statement"},{"de":"angeblich","en":"allegedly"},{"de":"er sei","en":"he is (Konj. I)"},{"de":"er habe","en":"he has (Konj. I)"},{"de":"er werde","en":"he will (Konj. I)"},{"de":"er könne","en":"he can (Konj. I)"},{"de":"er müsse","en":"he must (Konj. I)"},{"de":"die Pressemitteilung, -en","en":"press release"},{"de":"die Pressekonferenz, -en","en":"press conference"},{"de":"der Korrespondent, -en","en":"correspondent"},{"de":"die Agentur, -en","en":"(news) agency"},{"de":"bestätigen","en":"to confirm"},{"de":"dementieren","en":"to deny (officially)"},{"de":"betonen","en":"to emphasise"},{"de":"ankündigen","en":"to announce"},{"de":"einräumen","en":"to admit, to concede"},{"de":"warnen vor","en":"to warn of"},{"de":"fordern","en":"to demand"},{"de":"zufolge (nachgestellt, + Dat.)","en":"according to"},{"de":"nach eigenen Angaben","en":"by his/her own account"},{"de":"die Verhandlung, -en","en":"negotiation"},{"de":"die Einigung, -en","en":"agreement"}],"reading":"Pressemeldung: Die Stadtverwaltung teilt mit, ab Januar werde die Buslinie 100 häufiger fahren. Der Verkehrsdezernent erklärte, man habe die Fahrgastzahlen ausgewertet; sie seien im letzten Jahr deutlich gestiegen. Kritiker behaupten, das Geld fehle an anderer Stelle. Eine Anwohnerin sagte, sie nutze den Bus täglich und freue sich über den neuen Takt. Die Verwaltung betonte, weitere Linien würden geprüft.","tasks":[{"q":"Direkt → indirekt: „Ich bin krank.“ Er sagt, er ___ krank.","a":"sei"},{"q":"„Wir haben Zeit.“ Sie sagen, sie ___ Zeit. (Konj. II nötig)","a":"hätten"},{"q":"„Ich komme morgen.“ Sie schreibt, sie ___ morgen.","a":"komme"},{"q":"„Ich habe den Text gelesen.“ Er sagt, er ___ den Text gelesen.","a":"habe"},{"q":"„Ich bin gestern gefahren.“ Er sagt, er ___ gestern gefahren.","a":"sei"},{"q":"„Ich werde anrufen.“ Sie sagt, sie ___ anrufen.","a":"werde"},{"q":"Frage: „Hast du Zeit?“ Er fragte, ___ ich Zeit ___.","a":"ob / hätte"},{"q":"[Mix] Obwohl er sagte, er ___ beschäftigt, ___ er gekommen. (sein Konj. I; kommen Perfekt)","a":"sei / ist"},{"q":"[Mix] Wegen ___ schlecht___ Wetters, so der Bericht, sei das Fest abgesagt worden.","a":"des schlechten"},{"q":"[Mix] Setze ins Passiv Perfekt: Man hat die Regel geändert.","a":"Die Regel ist geändert worden."},{"q":"Indirekte Rede: Er sagt: „Ich bin krank.“ → Er sagt, er ___ krank.","a":"sei"},{"q":"Indirekte Rede: Sie sagt: „Ich habe keine Zeit.“ → Sie sagt, sie ___ keine Zeit.","a":"habe"},{"q":"Indirekte Rede: Er sagt: „Ich komme morgen.“ → Er sagt, er ___ morgen.","a":"komme"},{"q":"Indirekte Rede: Sie sagen: „Wir haben das Geld.“ → Sie sagen, sie ___ das Geld. (Ersatzform)","a":"hätten"},{"q":"Indirekte Rede: Er sagt: „Ich werde helfen.“ → Er sagt, er ___ helfen.","a":"werde"},{"q":"Indirekte Rede Vergangenheit: Sie sagt: „Ich habe ihn gesehen.“ → Sie sagt, sie ___ ihn gesehen.","a":"habe"},{"q":"Indirekte Rede Vergangenheit: Er sagt: „Ich bin gefahren.“ → Er sagt, er ___ gefahren.","a":"sei"},{"q":"Indirekte Frage: Er fragt: „Kommst du?“ → Er fragt, ___ ich ___.","a":"ob / komme"},{"q":"Indirekte Aufforderung: Sie sagt: „Warte!“ → Sie sagt, ich ___ warten.","a":"solle"},{"q":"Fehler? „Der Sprecher sagte, die Firma ist bankrott sei.“","a":"Der Sprecher sagte, die Firma sei bankrott."}],"exam":[{"q":"Wer fährt ab Januar häufiger?","a":"Die Buslinie 100."},{"q":"Was sagen die Kritiker?","a":"Das Geld fehle an anderer Stelle."},{"q":"Richtig oder falsch: Die Anwohnerin nutzt den Bus selten.","a":"Falsch – täglich."},{"q":"Konj. I: „Wir prüfen den Antrag.“ Die Behörde teilt mit, …","a":"… sie prüfe den Antrag."},{"q":"Konj. I: „Ich habe nichts gewusst.“ Er sagt, …","a":"… er habe nichts gewusst."},{"q":"Warum steht hier Konjunktiv II? „Sie sagen, sie kämen später.“","a":"Konjunktiv I „kommen“ wäre gleich dem Indikativ."},{"q":"Indirekte Frage: „Wann beginnt die Sitzung?“ Er wollte wissen, …","a":"… wann die Sitzung beginne."},{"q":"Geben Sie eine Nachricht von heute in indirekter Rede wieder (5 Sätze).","a":"","m":"Die Regierung teilte mit, die Preise seien gestiegen. Der Minister sagte, man habe einen Plan. Er erklärte, die Hilfe komme im Frühling. Experten meinen, das reiche nicht. Die Opposition sagt, die Regierung habe zu spät reagiert."},{"q":"Berichten Sie, was ein Kollege Ihnen gestern gesagt hat.","a":"","m":"Mein Kollege sagte, er sei krank gewesen. Er habe deshalb das Treffen verpasst. Er wolle die Präsentation am Montag halten."},{"q":"Warum benutzen Journalisten den Konjunktiv I? Erklären Sie.","a":"","m":"Journalisten benutzen den Konjunktiv I, um zu zeigen, dass sie eine fremde Aussage wiedergeben. So bleiben sie neutral und behaupten nichts selbst."}],"speak":["Lies die Pressemeldung und erzähle sie einem Kollegen weiter: __Die Verwaltung sagt, sie …__","Was sagen die Leute auf dem Bild vielleicht? Gib es indirekt wieder.","Berichte über ein Gespräch dieser Woche: __Meine Chefin meinte, …__","Wie würdest du eine Behauptung neutral wiedergeben, ohne ihr zuzustimmen?"],"reading2":{"title":"Tarifstreit bei der Bahn beigelegt","text":"Nach wochenlangen Verhandlungen haben sich die Deutsche Bahn und die Gewerkschaft der Lokführer auf einen neuen Tarifvertrag geeinigt. Wie beide Seiten am Freitag in einer gemeinsamen Pressekonferenz mitteilten, sollen die Löhne in zwei Stufen um insgesamt elf Prozent steigen. Außerdem werde die Wochenarbeitszeit für Schichtarbeiter schrittweise von 38 auf 36 Stunden reduziert. Der Gewerkschaftsvorsitzende sagte, man habe „ein historisches Ergebnis“ erreicht. Die Beschäftigten hätten lange genug auf eine faire Bezahlung gewartet. Ohne die Streiks wäre diese Einigung nicht möglich gewesen, betonte er. Die Personalvorständin der Bahn räumte ein, der Kompromiss sei für das Unternehmen teuer. Man sei jedoch froh, dass die Fahrgäste nun Planungssicherheit hätten. Weitere Streiks werde es bis zum Ende der Laufzeit nicht geben. Verbraucherschützer begrüßten die Einigung, warnten aber vor steigenden Ticketpreisen. Ein Sprecher des Fahrgastverbandes erklärte, die Kosten dürften nicht allein an die Kunden weitergegeben werden. Die Bahn wollte sich dazu zunächst nicht äußern. Nach Angaben des Unternehmens waren durch die Streiks in den vergangenen Monaten mehr als zwei Millionen Reisende betroffen. Der Vertrag soll rückwirkend zum ersten des Monats gelten und eine Laufzeit von 26 Monaten haben. Ökonomen zufolge könnte der Abschluss auch Signalwirkung für andere Branchen haben, in denen derzeit verhandelt wird."},"dialog":[{"who":"Moderatorin","de":"Frau Dr. Seidel, die Regierung sagt, die Inflation sei unter Kontrolle. Stimmt das?"},{"who":"Dr. Seidel","de":"Zum Teil. Die Zahlen sind zwar gesunken, aber viele Haushalte merken davon noch wenig."},{"who":"Moderatorin","de":"Der Finanzminister hat gestern erklärt, es werde keine weiteren Entlastungen geben."},{"who":"Dr. Seidel","de":"Das halte ich für problematisch. Er sagte ja auch, man müsse die Schulden reduzieren. Das ist richtig, aber nicht auf Kosten der Schwächsten."},{"who":"Moderatorin","de":"Kritiker behaupten, die Entlastungen hätten die Inflation sogar verstärkt."},{"who":"Dr. Seidel","de":"Einige Ökonomen sehen das so. Die Studienlage ist aber nicht eindeutig."},{"who":"Moderatorin","de":"Was würden Sie der Regierung raten?"},{"who":"Dr. Seidel","de":"Gezielte Hilfe für Menschen mit kleinen Einkommen statt Geld für alle."}],"dq":[{"q":"Was sagt die Regierung über die Inflation?","a":"Sie sei unter Kontrolle."},{"q":"Was hat der Finanzminister angekündigt?","a":"Es werde keine weiteren Entlastungen geben."},{"q":"Was rät Dr. Seidel?","a":"Gezielte Hilfe für Menschen mit kleinen Einkommen statt Geld für alle."}],"en":{"title":"Subjunctive I: reported speech","theme":"News and reports","expl":["Newspapers, reports and minutes use the **Konjunktiv I** to report what someone else said. It signals: \\"someone else says this – I\'m not claiming it myself\\".","Form: stem + -e, -est, -e, -en, -et, -en. Most common is the 3rd person: __er sei, er habe, er komme, er müsse, er werde__: __Der Minister sagt, er habe keine Zeit.__","If the Konjunktiv I looks the same as the normal form, use the Konjunktiv II instead: __Sie sagen, sie hätten keine Zeit.__"],"use":""},"check":[{"re":"\\\\b(sei|seien|habe|werde|könne|müsse|solle|wolle|gebe|komme|hätten|wären)\\\\b","label":"Konjunktiv I (er sei, sie habe …)"}]},{"n":44,"pos":45,"level":"B2","title":"Partizipien als Adjektive (Partizip I und II)","theme":"Produkte und Beschreibungen","scene":"shop","rec":[23,33,39],"expl":["**Partizip I** (Infinitiv + **d**) ist **aktiv und gleichzeitig**: __die **lachenden** Kinder__ = die Kinder, die lachen.","**Partizip II** ist **passiv oder abgeschlossen**: __der **reparierte** Wagen__ = der Wagen, der repariert wurde; __der **angekommene** Zug__ = der Zug, der angekommen ist.","Vor dem Nomen bekommen beide **Adjektivendungen**: das wartende Kind, mit dem reservierten Platz.","**Erweiterte Attribute**: Ergänzungen stehen **vor** dem Partizip: __der **seit Jahren in Berlin lebende** Kollege__ = der Kollege, der seit Jahren in Berlin lebt."],"use":"Nominaler Stil in Berichten, Produkttexten, Zeitungen – und das Auflösen solcher Sätze in Relativsätze beim Lesen.","table":[["Form","Bildung","Bedeutung","Relativsatz"],["Partizip I","lachen → lachend","aktiv, gleichzeitig","die lachenden Kinder = die Kinder, die lachen"],["Partizip II (transitiv)","reparieren → repariert","passiv, abgeschlossen","das reparierte Auto = das Auto, das repariert wurde"],["Partizip II (sein-Verb)","ankommen → angekommen","aktiv, abgeschlossen","der angekommene Zug = der Zug, der angekommen ist"],["Partizip I + zu","lösen → zu lösend","passiv, notwendig","die zu lösende Aufgabe = die Aufgabe, die gelöst werden muss"],["Erweitert","—","—","der gestern von uns geprüfte Antrag = der Antrag, den wir gestern geprüft haben"]],"examples":[{"de":"Die steigenden Preise belasten viele Haushalte.","en":"The rising prices burden many households."},{"de":"Das frisch gebackene Brot duftet.","en":"The freshly baked bread smells good."},{"de":"Wir suchen einen gut ausgebildeten Techniker.","en":"We\'re looking for a well-trained technician."},{"de":"Die zu prüfenden Unterlagen liegen auf dem Tisch.","en":"The documents to be checked are on the table."},{"de":"Der aus Indien stammende Tee ist sehr beliebt.","en":"The tea originating from India is very popular."},{"de":"Eine wachsende Zahl von Kunden bestellt online.","en":"A growing number of customers order online."},{"de":"Das im letzten Jahr eröffnete Café schließt wieder.","en":"The café opened last year is closing again."},{"de":"Die betroffenen Mitarbeiter wurden informiert.","en":"The affected employees were informed."},{"de":"Bitte beachten Sie die beigefügte Rechnung.","en":"Please note the attached invoice."},{"de":"Der vorliegende Bericht enthält alle Zahlen.","en":"The present report contains all figures."},{"de":"Die steigenden Mieten sind ein großes Problem.","en":"The rising rents are a big problem."},{"de":"Das reparierte Fahrrad fährt wieder gut.","en":"The repaired bike runs well again."},{"de":"Die lachenden Kinder spielten im Garten.","en":"The laughing children played in the garden."},{"de":"Bitte senden Sie das beschädigte Gerät zurück.","en":"Please send back the damaged device."},{"de":"Der seit Jahren geplante Umbau beginnt endlich.","en":"The renovation planned for years is finally starting."},{"de":"Die im Text genannten Zahlen sind veraltet.","en":"The figures mentioned in the text are outdated."},{"de":"Wir suchen gut ausgebildete Fachkräfte.","en":"We are looking for well-trained specialists."},{"de":"Das ist ein schnell wachsender Markt.","en":"That\'s a rapidly growing market."},{"de":"Die Rücksendung des fehlerhaften Produkts ist kostenlos.","en":"Returning the faulty product is free of charge."},{"de":"Die zu erledigenden Aufgaben stehen auf der Liste.","en":"The tasks to be done are on the list."}],"vocab":[{"de":"das Partizip, -ien","en":"participle"},{"de":"das Attribut, -e","en":"attribute"},{"de":"betreffen (betrifft)","en":"to concern, affect"},{"de":"beifügen","en":"to attach"},{"de":"vorliegen","en":"to be available, at hand"},{"de":"steigend / sinkend","en":"rising / falling"},{"de":"ausgebildet","en":"trained"},{"de":"geeignet","en":"suitable"},{"de":"enthalten (enthält)","en":"to contain"},{"de":"hinweisen auf","en":"to point out"},{"de":"der Hinweis, -e","en":"note, hint"},{"de":"gebraucht","en":"used, second-hand"},{"de":"die steigenden Preise","en":"the rising prices"},{"de":"das gestohlene Fahrrad","en":"the stolen bicycle"},{"de":"die zu erledigende Aufgabe","en":"the task to be done"},{"de":"die Gebrauchsanweisung, -en","en":"instructions for use"},{"de":"die Garantie, -n","en":"guarantee"},{"de":"der Hersteller, -","en":"manufacturer"},{"de":"die Inhaltsstoffe (Pl.)","en":"ingredients"},{"de":"das Haltbarkeitsdatum","en":"best-before date"},{"de":"umweltschonend","en":"environmentally friendly"},{"de":"wiederverwendbar","en":"reusable"},{"de":"recycelt","en":"recycled"},{"de":"handgefertigt","en":"handmade"},{"de":"energiesparend","en":"energy-saving"},{"de":"wasserdicht","en":"waterproof"},{"de":"leistungsstark","en":"powerful"},{"de":"die Bewertung, -en","en":"review, rating"},{"de":"die Reklamation, -en","en":"complaint"},{"de":"zurücksenden","en":"to send back"},{"de":"fehlerhaft","en":"faulty"},{"de":"beschädigt","en":"damaged"}],"reading":"Produktbeschreibung: Das neu entwickelte Modell richtet sich an anspruchsvolle Nutzer. Der eingebaute Akku hält bis zu 20 Stunden; die verwendeten Materialien stammen aus zertifizierter Produktion. Die im Set enthaltene Software erlaubt eine individuelle Einstellung. Für die zu erwartende hohe Nachfrage haben wir die Produktion erhöht. Kunden, die das im letzten Jahr verkaufte Vorgängermodell besitzen, erhalten einen Rabatt.","tasks":[{"q":"Relativsatz → Partizip: die Kinder, die spielen → die ___ Kinder","a":"spielenden"},{"q":"Relativsatz → Partizip: der Brief, der geschrieben wurde → der ___ Brief","a":"geschriebene"},{"q":"Partizip → Relativsatz: die steigenden Kosten → die Kosten, die ___","a":"steigen"},{"q":"Partizip → Relativsatz: das reparierte Rad → das Rad, das ___ ___ ___","a":"repariert worden ist"},{"q":"Bilde: die Aufgabe, die gelöst werden muss → die ___ ___ Aufgabe","a":"zu lösende"},{"q":"Endung: mit dem frisch gebacken___ Brot","a":"gebackenen"},{"q":"Erweitert: der Kollege, der seit 2019 in Bonn arbeitet → der ___ Kollege","a":"seit 2019 in Bonn arbeitende"},{"q":"[Mix] Die ___ (betreffen, Part. II) Kunden ___ informiert worden. (sein)","a":"betroffenen / sind"},{"q":"[Mix] Wegen ___ steigend___ Nachfrage wurde die Produktion erhöht.","a":"der steigenden"},{"q":"[Mix] Die Firma teilt mit, das Modell ___ gut verkauft worden. (Konj. I Passiv Perfekt)","a":"sei"},{"q":"Partizip I als Adjektiv: das Kind, das schläft → das ___ Kind","a":"schlafende"},{"q":"Partizip I als Adjektiv: die Preise, die steigen → die ___ Preise","a":"steigenden"},{"q":"Partizip II als Adjektiv: das Auto, das repariert wurde → das ___ Auto","a":"reparierte"},{"q":"Partizip II als Adjektiv: der Brief, der geschrieben wurde → der ___ Brief","a":"geschriebene"},{"q":"Partizip II als Adjektiv: die Tür, die geschlossen ist → die ___ Tür","a":"geschlossene"},{"q":"Endung: mit dem ___ Gerät (beschädigen, Partizip II)","a":"beschädigten"},{"q":"Endung: ein ___ Markt (wachsen, Partizip I)","a":"wachsender"},{"q":"Erweitertes Attribut: die Häuser, die im letzten Jahr gebaut wurden → die im letzten Jahr ___ Häuser","a":"gebauten"},{"q":"Gerundiv: die Aufgabe, die erledigt werden muss → die zu ___ Aufgabe","a":"erledigende"},{"q":"Fehler? „Die gestohlen Fahrräder wurden gefunden.“","a":"Die gestohlenen Fahrräder wurden gefunden."}],"exam":[{"q":"An wen richtet sich das Modell?","a":"An anspruchsvolle Nutzer."},{"q":"Woher stammen die Materialien?","a":"Aus zertifizierter Produktion."},{"q":"Wer bekommt einen Rabatt?","a":"Kunden mit dem Vorgängermodell."},{"q":"Partizip I oder II? „die ___ (warten) Gäste“","a":"wartenden"},{"q":"Partizip I oder II? „der ___ (verlieren) Schlüssel“","a":"verlorene"},{"q":"Löse auf: die zu bezahlende Rechnung","a":"die Rechnung, die bezahlt werden muss"},{"q":"Formuliere nominal: Der Zug, der aus Hamburg kommt, hat Verspätung.","a":"Der aus Hamburg kommende Zug hat Verspätung."},{"q":"Beschreiben Sie ein Produkt mit mindestens vier Partizipien.","a":"","m":"Das neue Smartphone hat einen leuchtenden Bildschirm und eine lang haltende Batterie. Das mitgelieferte Ladekabel ist kurz. Die verbesserte Kamera macht auch bei Nacht gute Fotos."},{"q":"Lesen Sie eine Nachricht und lösen Sie zwei Partizipialattribute in Relativsätze auf.","a":"","m":"„Der vor zwei Wochen gestartete Zug“ = der Zug, der vor zwei Wochen gestartet ist. „Die steigenden Preise“ = die Preise, die steigen."},{"q":"Wo begegnen Ihnen solche Konstruktionen im Alltag? Warum sind sie dort praktisch?","a":"","m":"Solche Konstruktionen findet man in Zeitungen, auf Produkten und in Anleitungen. Sie sind praktisch, weil sie viel Information kurz zusammenfassen."}],"speak":["Beschreibe die Szene mit Partizipien: __die einkaufenden Menschen, die geöffneten Regale …__","Beschreibe ein Gerät, das du besitzt (mindestens 3 Partizipien).","Erkläre einem A2-Lerner den Unterschied zwischen „der lesende Mann“ und „das gelesene Buch“.","Welche Produktwerbung überzeugt dich – und warum?"],"reading2":{"title":"Produkttest: Der Rucksack „Urban Pro“","text":"Gesucht wird ein Rucksack für den täglichen Weg ins Büro, der auch auf Reisen eine gute Figur macht. Der von einem Berliner Start-up entwickelte „Urban Pro“ verspricht genau das. Wir haben ihn vier Wochen lang getestet. Erster Eindruck: Das aus recycelten PET-Flaschen hergestellte Material wirkt hochwertig und ist angenehm leicht. Laut Hersteller ist der Rucksack wasserdicht. Bei einem einstündigen Spaziergang im strömenden Regen blieb der Inhalt tatsächlich trocken; nur die seitlichen, nicht verschließbaren Taschen wurden nass. Positiv fällt das gut durchdachte Innenleben auf: Ein gepolstertes Fach schützt den Laptop, ein im Rücken versteckter Reißverschluss erschwert Taschendieben die Arbeit. Die verstellbaren Schultergurte sind auch bei schwerem Gepäck bequem. Weniger überzeugend ist die Größe: Für Wochenendreisende ist das angegebene Volumen von 22 Litern knapp bemessen. Wer viel Kleidung mitnehmen will, sollte zur größeren Variante greifen. Auch der Preis von 149 Euro ist nicht gerade niedrig. Dafür gewährt das Unternehmen eine Garantie von fünf Jahren und repariert beschädigte Rucksäcke kostenlos. In Zeiten steigender Müllberge ist das ein überzeugendes Argument. Unser Fazit: Ein gut verarbeiteter, umweltschonend produzierter Rucksack für Pendler, der seinen Preis weitgehend rechtfertigt. Bewertung: vier von fünf Sternen."},"dialog":[{"who":"Kundendienst","de":"Kundenservice Elektro-Haus, mein Name ist Bauer. Was kann ich für Sie tun?"},{"who":"Jonas","de":"Guten Tag. Ich habe vor zwei Wochen einen Staubsauger bestellt. Das gelieferte Gerät ist beschädigt."},{"who":"Kundendienst","de":"Das tut mir leid. Was genau ist beschädigt?"},{"who":"Jonas","de":"Das Gehäuse hat einen Riss, und der mitgelieferte Akku lädt nicht."},{"who":"Kundendienst","de":"Verstehe. Haben Sie die Bestellnummer?"},{"who":"Jonas","de":"Ja, die steht auf der beigefügten Rechnung: 4471-B."},{"who":"Kundendienst","de":"Danke. Ich schicke Ihnen einen vorausgefüllten Rücksendeschein per E-Mail. Die Rücksendung ist für Sie kostenlos."},{"who":"Jonas","de":"Bekomme ich ein neues Gerät oder mein Geld zurück?"},{"who":"Kundendienst","de":"Wie Sie möchten. Ein Ersatzgerät könnten wir innerhalb von drei Tagen liefern."}],"dq":[{"q":"Was ist mit dem Staubsauger los?","a":"Das Gehäuse hat einen Riss und der Akku lädt nicht."},{"q":"Wo steht die Bestellnummer?","a":"Auf der beigefügten Rechnung."},{"q":"Wie schnell kann ein Ersatzgerät kommen?","a":"Innerhalb von drei Tagen."}],"en":{"title":"Participles used as adjectives","theme":"Products and descriptions","expl":["**Present participle** (infinitive + d) is active and simultaneous: __die lachenden Kinder__ = the laughing children (the children who are laughing).","**Past participle** is passive or completed: __der reparierte Wagen__ = the repaired car; __der angekommene Zug__ = the train that has arrived.","Before a noun both take normal adjective endings: __das wartende Kind, mit dem reparierten Wagen__."],"use":""},"check":[{"re":"\\\\b\\\\w+(end|ende|enden|ender|endes)\\\\s+[A-ZÄÖÜ]|\\\\bge\\\\w+(te|ten|ter|tes)\\\\s+[A-ZÄÖÜ]","label":"participles as adjectives (das wartende Kind, der reparierte Wagen)"}]},{"n":45,"pos":46,"level":"B2","title":"Nominalstil und Verbalstil","theme":"Berichte und Formulare","scene":"office","rec":[29,40,44],"expl":["Im **Nominalstil** trägt ein **Nomen** die Information, im **Verbalstil** ein **Verb**: __nach der **Prüfung** des Antrags__ ↔ __nachdem der Antrag **geprüft** worden ist__.","Typische Umformungen: **weil** → **wegen/aufgrund + Gen.** · **obwohl** → **trotz + Gen.** · **wenn/falls** → **bei + Dat.** · **nachdem** → **nach + Dat.** · **bevor** → **vor + Dat.** · **um … zu** → **zu/zwecks + Dat./Gen.** · **indem/dadurch, dass** → **durch + Akk.**","Nominalisierungen entstehen mit **-ung, -heit, -keit, -nis** oder als **Infinitiv-Nomen** (das Lesen).","Amtsdeutsch nutzt Nominalstil; **guter Text wechselt bewusst**: nominal für Kürze, verbal für Klarheit."],"use":"Formulare und Bescheide verstehen, formelle Texte schreiben, Sätze in der Prüfung umformen.","table":[["Verbalstil (Nebensatz)","Nominalstil (Präposition + Nomen)"],["weil das Wetter schlecht war","wegen des schlechten Wetters"],["obwohl es regnete","trotz des Regens"],["wenn Sie ankommen","bei Ihrer Ankunft"],["nachdem wir geprüft haben","nach der Prüfung"],["bevor die Sitzung beginnt","vor Beginn der Sitzung"],["indem man Energie spart","durch Energiesparen"],["um Kosten zu senken","zur Senkung der Kosten"]],"examples":[{"de":"Wegen des Streiks fallen Züge aus.","en":"Due to the strike trains are cancelled."},{"de":"Nach Prüfung Ihrer Unterlagen melden wir uns.","en":"After checking your documents we\'ll contact you."},{"de":"Bei Rückfragen wenden Sie sich an Frau Weber.","en":"For queries, please contact Ms Weber."},{"de":"Trotz mehrfacher Erinnerung ist die Zahlung offen.","en":"Despite repeated reminders the payment is outstanding."},{"de":"Zur Verbesserung der Qualität wurden Tests eingeführt.","en":"To improve quality, tests were introduced."},{"de":"Durch den Einsatz neuer Software sparen wir Zeit.","en":"By using new software we save time."},{"de":"Vor Beginn der Arbeiten wird informiert.","en":"Before the works begin, information is given."},{"de":"Die Erhöhung der Mieten belastet viele Familien.","en":"The rise in rents burdens many families."},{"de":"Nach seiner Rückkehr hat er sofort angerufen.","en":"After his return he called immediately."},{"de":"Mit der Einführung der Regel sank die Zahl der Unfälle.","en":"With the introduction of the rule the number of accidents fell."},{"de":"Nach Eingang Ihres Antrags beginnt die Bearbeitung.","en":"After receipt of your application, processing begins."},{"de":"Wenn Ihr Antrag eingegangen ist, beginnen wir mit der Bearbeitung.","en":"When your application has arrived, we begin processing."},{"de":"Bei Verlust der Karte informieren Sie uns bitte sofort.","en":"In case of loss of the card, please inform us immediately."},{"de":"Wenn Sie die Karte verlieren, informieren Sie uns bitte sofort.","en":"If you lose the card, please inform us immediately."},{"de":"Zur Beantragung des Ausweises benötigen Sie ein Foto.","en":"To apply for the ID card you need a photo."},{"de":"Aufgrund der hohen Nachfrage kommt es zu Verzögerungen.","en":"Due to high demand there are delays."},{"de":"Weil die Nachfrage hoch ist, kommt es zu Verzögerungen.","en":"Because demand is high, there are delays."},{"de":"Gegen diesen Bescheid kann innerhalb eines Monats Widerspruch eingelegt werden.","en":"An objection to this decision can be lodged within a month."},{"de":"Die Erstattung erfolgt nach Vorlage der Quittung.","en":"The refund is made upon presentation of the receipt."},{"de":"Bei Nichtbeachtung der Frist entfällt der Anspruch.","en":"If the deadline is not observed, the claim lapses."}],"vocab":[{"de":"der Bescheid, -e","en":"official notice"},{"de":"die Frist, -en","en":"deadline"},{"de":"der Einsatz, ¨e","en":"use, deployment"},{"de":"die Rückfrage, -n","en":"query"},{"de":"die Einführung, -en","en":"introduction"},{"de":"die Umsetzung, -en","en":"implementation"},{"de":"die Erhöhung / die Senkung","en":"increase / reduction"},{"de":"die Prüfung der Unterlagen","en":"checking the documents"},{"de":"sich wenden an","en":"to turn to, contact"},{"de":"erfolgen","en":"to take place, occur"},{"de":"gelten (gilt)","en":"to be valid"},{"de":"beantragen","en":"to apply for"},{"de":"die Antragstellung","en":"submission of an application"},{"de":"die Bearbeitung","en":"processing"},{"de":"die Genehmigung, -en","en":"approval, permit"},{"de":"die Ablehnung, -en","en":"rejection"},{"de":"der Widerspruch, ¨e","en":"objection, appeal"},{"de":"die Zustellung","en":"delivery (of a letter)"},{"de":"die Kenntnisnahme","en":"acknowledgement"},{"de":"die Inanspruchnahme","en":"use, claiming"},{"de":"die Vorlage","en":"presentation (of documents)"},{"de":"die Erstattung, -en","en":"refund, reimbursement"},{"de":"die Berechtigung","en":"entitlement"},{"de":"fristgerecht","en":"within the deadline"},{"de":"ordnungsgemäß","en":"properly"},{"de":"unverzüglich","en":"without delay"},{"de":"vorbehaltlich (+ Gen.)","en":"subject to"},{"de":"aufgrund (+ Gen.)","en":"due to"},{"de":"infolge (+ Gen.)","en":"as a result of"},{"de":"bei Nichtbeachtung","en":"in case of non-compliance"},{"de":"gemäß (+ Dat.)","en":"in accordance with"},{"de":"zwecks (+ Gen.)","en":"for the purpose of"}],"reading":"Aus einem Bescheid: „Nach Prüfung Ihres Antrags teilen wir Ihnen mit, dass die Förderung ab dem 1. März gewährt wird. Voraussetzung ist die fristgerechte Einreichung der fehlenden Unterlagen. Bei Nichteinhaltung der Frist erfolgt eine Ablehnung. Zur Vermeidung von Rückfragen bitten wir um vollständige Angaben. Trotz hoher Antragszahlen bearbeiten wir Ihren Vorgang zügig.“","tasks":[{"q":"Verbal → nominal: weil es geregnet hat → ___ des Regens","a":"wegen"},{"q":"Verbal → nominal: nachdem wir angekommen sind → nach ___ Ankunft","a":"unserer"},{"q":"Nominal → verbal: bei Rückfragen → wenn Sie ___ ___","a":"Fragen haben"},{"q":"Nominal → verbal: trotz des Staus → obwohl ___ ___ Stau ___","a":"es einen / gab"},{"q":"Verbal → nominal: um die Kosten zu senken → ___ ___ der Kosten","a":"zur Senkung"},{"q":"Nominalisiere: Man führte die Regel ein. → die ___ der Regel","a":"Einführung"},{"q":"Nominal → verbal: durch den Einsatz von Technik → indem man Technik ___","a":"einsetzt"},{"q":"[Mix] ___ Einreichung der Unterlagen wird der Antrag geprüft. (nach + Dat.)","a":"Nach"},{"q":"[Mix] Der Bescheid teilt mit, die Förderung ___ gewährt. (Konj. I Passiv)","a":"werde"},{"q":"[Mix] Die ___ (fehlen, Part. I) Unterlagen müssen ___ (nachreichen) werden.","a":"fehlenden / nachgereicht"},{"q":"Nominal → verbal: nach Ihrer Ankunft → nachdem Sie ___ ___","a":"angekommen sind"},{"q":"Nominal → verbal: bei Regen → wenn es ___","a":"regnet"},{"q":"Nominal → verbal: wegen der Erkrankung des Kollegen → weil der Kollege ___ ___","a":"erkrankt ist"},{"q":"Nominal → verbal: zur Verbesserung der Qualität → um die Qualität ___ ___","a":"zu verbessern"},{"q":"Nominal → verbal: trotz der hohen Kosten → obwohl die Kosten hoch ___","a":"sind"},{"q":"Verbal → nominal: bevor die Sitzung beginnt → vor ___ ___ ___","a":"Beginn der Sitzung"},{"q":"Verbal → nominal: weil das Wetter schlecht ist → wegen ___ ___ Wetters","a":"des schlechten"},{"q":"Verbal → nominal: wenn Sie den Vertrag kündigen → bei ___ ___ Vertrags","a":"Kündigung des"},{"q":"Verbal → nominal: während wir renovieren → während ___ ___","a":"der Renovierung"},{"q":"Nominalisierung: beantragen → die ___","a":"Beantragung"}],"exam":[{"q":"Ab wann wird die Förderung gewährt?","a":"Ab dem 1. März."},{"q":"Was passiert bei Nichteinhaltung der Frist?","a":"Eine Ablehnung."},{"q":"Warum bittet die Behörde um vollständige Angaben?","a":"Zur Vermeidung von Rückfragen."},{"q":"Nominal: Weil die Preise steigen, sparen viele.","a":"Wegen steigender Preise sparen viele."},{"q":"Verbal: Nach Abschluss der Arbeiten öffnet das Bad.","a":"Nachdem die Arbeiten abgeschlossen sind, öffnet das Bad."},{"q":"Nominal: Wenn Sie umziehen, melden Sie sich um.","a":"Bei einem Umzug melden Sie sich um."},{"q":"Verbal: zur Verbesserung der Luftqualität","a":"um die Luftqualität zu verbessern"},{"q":"Schreiben Sie drei Sätze aus einem Formular in einfaches Deutsch um.","a":"","m":"„Bei Nichteinhaltung der Frist erfolgt eine Ablehnung.“ → Wenn Sie die Frist nicht einhalten, wird der Antrag abgelehnt. „Nach Prüfung der Unterlagen“ → Nachdem wir die Unterlagen geprüft haben. „Zur Vermeidung von Rückfragen“ → Damit wir nicht nachfragen müssen."},{"q":"Erklären Sie einem Freund einen Behördenbrief mündlich in Verbalstil.","a":"","m":"Also, in dem Brief steht: Du musst bis zum 1. März alle Unterlagen schicken. Wenn du das nicht machst, lehnen sie den Antrag ab. Danach prüfen sie alles und schicken dir eine Antwort."},{"q":"Wann ist Nominalstil sinnvoll, wann stört er? Begründen Sie.","a":"","m":"Nominalstil ist sinnvoll in Formularen und Berichten, weil er kurz und präzise ist. Im Gespräch stört er, weil er schwer und unpersönlich klingt."}],"speak":["Erkläre den Bescheid aus dem Lesetext in einfachen Worten.","Beschreibe deinen Arbeitsablauf zuerst verbal, dann nominal.","Was ärgert dich an Amtsdeutsch?","Formuliere drei Schilder/Hinweise im Nominalstil (z. B. „Kein Zutritt während der Arbeiten“)."],"reading2":{"title":"Ein Brief vom Amt – und seine Übersetzung","text":"Leila hat Post bekommen. Im Briefkasten liegt ein Schreiben der Familienkasse. Sie liest: „Sehr geehrte Frau Ahmadi, nach Prüfung Ihres Antrags auf Kindergeld vom 3. März teilen wir Ihnen mit, dass eine abschließende Entscheidung aufgrund fehlender Unterlagen derzeit nicht möglich ist. Zur weiteren Bearbeitung ist die Vorlage einer Geburtsurkunde Ihres Kindes in beglaubigter Übersetzung erforderlich. Wir bitten um Einreichung innerhalb von vier Wochen nach Zustellung dieses Schreibens. Bei Nichtbeachtung dieser Frist erfolgt eine Ablehnung des Antrags. Gegen diese Entscheidung ist die Einlegung eines Einspruchs möglich.“ Leila versteht die Wörter, aber die Sätze sind kompliziert. Ihre Nachbarin Anna hilft ihr, den Brief in normales Deutsch zu „übersetzen“: „Sie haben deinen Antrag auf Kindergeld geprüft. Sie können noch nicht entscheiden, weil Unterlagen fehlen. Damit sie weitermachen können, musst du die Geburtsurkunde deiner Tochter schicken – übersetzt und beglaubigt. Das musst du tun, bevor vier Wochen vorbei sind. Wenn du die Frist nicht einhältst, lehnen sie den Antrag ab.“ Leila lacht erleichtert. „Warum schreiben sie das nicht gleich so?“ Anna zuckt mit den Schultern: „Im Nominalstil klingt alles offizieller. Und mit vielen Substantiven kann man sehr viel Information in einen Satz packen.“ Am nächsten Tag lässt Leila die Urkunde bei einem vereidigten Übersetzer übersetzen und schickt sie per Einschreiben ab. Drei Wochen später kommt der Bescheid: Das Kindergeld wurde bewilligt."},"dialog":[{"who":"Anna","de":"Und, hast du den Brief verstanden?"},{"who":"Leila","de":"Teilweise. Was bedeutet „nach erfolgter Prüfung“?"},{"who":"Anna","de":"Das heißt einfach: nachdem sie es geprüft haben."},{"who":"Leila","de":"Und „bei Nichtvorlage der Unterlagen“?"},{"who":"Anna","de":"Wenn du die Unterlagen nicht schickst."},{"who":"Leila","de":"Ah. Warum schreiben Behörden so kompliziert?"},{"who":"Anna","de":"Weil der Nominalstil kurz und genau ist – zumindest für Juristen. Für alle anderen ist er ein Rätsel."},{"who":"Leila","de":"Dann brauche ich in Zukunft eine Übersetzung von Behördendeutsch in normales Deutsch."}],"dq":[{"q":"Was bedeutet „nach erfolgter Prüfung“?","a":"Nachdem sie es geprüft haben."},{"q":"Was bedeutet „bei Nichtvorlage der Unterlagen“?","a":"Wenn man die Unterlagen nicht schickt."},{"q":"Warum schreiben Behörden im Nominalstil?","a":"Weil er kurz und genau ist (für Juristen)."}],"en":{"title":"Nominal style and verbal style","theme":"Reports and forms","expl":["In the **nominal style** a noun carries the information, in the **verbal style** a verb: __nach der Prüfung des Antrags__ ↔ __nachdem der Antrag geprüft worden ist__ (after the application has been checked).","Typical conversions: weil → wegen/aufgrund + gen., obwohl → trotz + gen., wenn/falls → bei + dat., nachdem → nach + dat., bevor → vor + dat., um … zu → zur + dat.","Official texts prefer the nominal style; speech prefers the verbal style."],"use":""},"check":[{"re":"\\\\b(nachdem|weil|wenn|bevor|um)\\\\b|\\\\b(wegen|nach|vor|bei|zur|zum)\\\\b","label":"turning nominal style into verbal style (or the reverse)"}]},{"n":46,"pos":47,"level":"B2","title":"Passiv-Ersatzformen","theme":"Regeln und Anleitungen","scene":"kitchen","rec":[39,44,45],"expl":["Statt des Passivs mit **werden** gibt es kürzere Formen mit gleicher Bedeutung:","**man + Aktiv**: __Man repariert das Gerät nicht mehr.__ · **sich lassen + Infinitiv** (= kann … werden): __Das Gerät **lässt sich** leicht reparieren.__","**sein + zu + Infinitiv** (= muss/kann … werden): __Die Formulare **sind** bis Freitag **abzugeben**.__","**Adjektive auf -bar / -lich** (= kann … werden): __Der Text ist **lesbar**. Das ist **machbar**. Die Frist ist **unabänderlich**.__","**es gibt + zu + Infinitiv**, **bleiben + zu**: __Es bleibt **abzuwarten**.__"],"use":"Anleitungen, Regeln, Hausordnungen, Produkttexte – und Abwechslung im Stil.","table":[["Passiv","Ersatzform","Bedeutung"],["Das kann repariert werden.","Das lässt sich reparieren. / Das ist reparierbar.","Möglichkeit"],["Das muss heute erledigt werden.","Das ist heute zu erledigen.","Notwendigkeit"],["Die Tür kann nicht geöffnet werden.","Die Tür lässt sich nicht öffnen.","Möglichkeit (negativ)"],["Hier darf nicht geraucht werden.","Hier ist das Rauchen nicht gestattet. / Man raucht hier nicht.","Verbot"],["Der Antrag kann online gestellt werden.","Der Antrag ist online zu stellen. (Pflicht!)","Achtung: Bedeutung verschiebt sich"]],"examples":[{"de":"Das Problem lässt sich schnell lösen.","en":"The problem can be solved quickly."},{"de":"Die Rechnung ist bis zum 15. zu bezahlen.","en":"The invoice is to be paid by the 15th."},{"de":"Diese Datei ist leider nicht lesbar.","en":"This file is unfortunately not readable."},{"de":"Der Fehler ließ sich nicht wiederholen.","en":"The error could not be reproduced."},{"de":"Es bleibt abzuwarten, ob die Regel hilft.","en":"It remains to be seen whether the rule helps."},{"de":"Die Maschine lässt sich einfach bedienen.","en":"The machine is easy to operate."},{"de":"Alle Angaben sind vollständig auszufüllen.","en":"All details are to be filled in completely."},{"de":"Diese Ausgaben sind vermeidbar.","en":"These expenses are avoidable."},{"de":"Man sollte den Vertrag genau lesen.","en":"One should read the contract carefully."},{"de":"Die Tür ist verschlossen zu halten.","en":"The door is to be kept locked."},{"de":"Das Formular ist bis Freitag auszufüllen.","en":"The form must be filled in by Friday."},{"de":"Das Problem lässt sich leicht lösen.","en":"The problem can be solved easily."},{"de":"Die Schrift ist kaum lesbar.","en":"The writing is barely legible."},{"de":"Dieser Fleck ist nicht zu entfernen.","en":"This stain can\'t be removed."},{"de":"Man darf das Gerät nicht in Wasser tauchen.","en":"You mustn\'t immerse the device in water."},{"de":"Das ist eine verständliche Reaktion.","en":"That\'s an understandable reaction."},{"de":"Die Batterie ist vor Gebrauch vollständig aufzuladen.","en":"The battery must be fully charged before use."},{"de":"Der Termin lässt sich leider nicht verschieben.","en":"Unfortunately the appointment can\'t be postponed."},{"de":"Die Kosten sind vom Mieter zu tragen.","en":"The costs are to be borne by the tenant."},{"de":"Er bekam das Paket direkt nach Hause geliefert.","en":"He got the parcel delivered straight to his home."}],"vocab":[{"de":"gestattet / untersagt","en":"permitted / prohibited"},{"de":"die Anleitung, -en","en":"instructions"},{"de":"bedienen","en":"to operate, serve"},{"de":"vermeidbar","en":"avoidable"},{"de":"machbar","en":"feasible"},{"de":"zumutbar","en":"reasonable (to expect)"},{"de":"verfügbar","en":"available"},{"de":"löschen","en":"to delete, extinguish"},{"de":"einhalten (hält ein)","en":"to comply with"},{"de":"die Vorschrift, -en","en":"regulation"},{"de":"abwarten","en":"to wait and see"},{"de":"das Verbot, -e","en":"ban"},{"de":"lässt sich + Infinitiv","en":"can be done"},{"de":"sein + zu + Infinitiv","en":"must / can be done"},{"de":"-bar (lesbar, machbar)","en":"-able"},{"de":"-lich (verständlich)","en":"-ible / -able"},{"de":"man","en":"one, you, people"},{"de":"bekommen + Partizip II","en":"to get something done (passive)"},{"de":"das Gerät, -e","en":"device, appliance"},{"de":"der Akku, -s","en":"rechargeable battery"},{"de":"aufladen","en":"to charge"},{"de":"der Stecker, -","en":"plug"},{"de":"die Steckdose, -n","en":"socket"},{"de":"die Fernbedienung, -en","en":"remote control"},{"de":"einstellen","en":"to set, to adjust"},{"de":"zurücksetzen","en":"to reset"},{"de":"die Werkseinstellung, -en","en":"factory setting"},{"de":"das Passwort, ¨er","en":"password"},{"de":"die Sicherheitshinweise (Pl.)","en":"safety instructions"},{"de":"ausschließlich","en":"exclusively"},{"de":"unsachgemäß","en":"improper"},{"de":"die Haftung","en":"liability"}],"reading":"Hausordnung (Auszug): Der Müll ist getrennt zu entsorgen. Die Haustür ist ab 22 Uhr geschlossen zu halten. Lärm lässt sich nicht immer vermeiden, doch Rücksicht ist selbstverständlich. Reparaturen sind dem Hausmeister zu melden; kleinere Schäden lassen sich oft sofort beheben. Das Abstellen von Fahrrädern im Treppenhaus ist nicht gestattet. Fragen sind an die Verwaltung zu richten.","tasks":[{"q":"Passiv → sich lassen: Das kann leicht gemacht werden.","a":"Das lässt sich leicht machen."},{"q":"Passiv → sein + zu: Die Formulare müssen abgegeben werden.","a":"Die Formulare sind abzugeben."},{"q":"Passiv → -bar: Der Plan kann umgesetzt werden.","a":"Der Plan ist umsetzbar."},{"q":"Ersatzform → Passiv: Das lässt sich reparieren.","a":"Das kann repariert werden."},{"q":"Ersatzform → Passiv: Die Tür ist geschlossen zu halten.","a":"Die Tür muss geschlossen gehalten werden."},{"q":"man-Form: Hier darf nicht geparkt werden.","a":"Hier parkt man nicht. / Man darf hier nicht parken."},{"q":"Notwendigkeit oder Möglichkeit? „Das ist zu klären.“","a":"Notwendigkeit (muss geklärt werden)"},{"q":"[Mix] ___ Vermeidung von Lärm sind Fenster zu schließen. (Nominalstil)","a":"Zur"},{"q":"[Mix] Die ___ (melden, Part. II) Schäden lassen ___ schnell beheben.","a":"gemeldeten / sich"},{"q":"[Mix] Der Vermieter sagt, der Müll ___ getrennt zu entsorgen. (Konj. I von sein)","a":"sei"},{"q":"Ersatzform: Das Problem kann gelöst werden. → Das Problem lässt sich ___.","a":"lösen"},{"q":"Ersatzform: Das Formular muss ausgefüllt werden. → Das Formular ist ___.","a":"auszufüllen"},{"q":"Ersatzform: Der Text kann gelesen werden. → Der Text ist ___. (Adjektiv)","a":"lesbar"},{"q":"Ersatzform: Das Fenster kann nicht geöffnet werden. → Das Fenster lässt sich nicht ___.","a":"öffnen"},{"q":"Ersatzform: Die Regel muss beachtet werden. → Die Regel ist ___ ___.","a":"zu beachten"},{"q":"Ersatzform: Das kann man nicht ändern. → Das ist nicht ___ ___.","a":"zu ändern"},{"q":"Ersatzform mit man: Das Gerät darf nicht nass werden. → ___ darf das Gerät nicht nass machen.","a":"Man"},{"q":"Passiv: Die Batterien sind zu wechseln. → Die Batterien müssen ___ ___.","a":"gewechselt werden"},{"q":"-bar: Das kann man essen. → Das ist ___.","a":"essbar"},{"q":"Fehler? „Das Problem lässt sich nicht lösen werden.“","a":"Das Problem lässt sich nicht lösen."}],"exam":[{"q":"Wie ist der Müll zu entsorgen?","a":"Getrennt."},{"q":"Was ist im Treppenhaus verboten?","a":"Das Abstellen von Fahrrädern."},{"q":"Wem sind Reparaturen zu melden?","a":"Dem Hausmeister."},{"q":"Formuliere mit „sich lassen“: Die Software kann schnell installiert werden.","a":"Die Software lässt sich schnell installieren."},{"q":"Formuliere mit „sein + zu“: Die Unterlagen müssen unterschrieben werden.","a":"Die Unterlagen sind zu unterschreiben."},{"q":"Adjektiv auf -bar: Das kann nicht bezahlt werden.","a":"Das ist unbezahlbar."},{"q":"Was bedeutet: „Es bleibt abzuwarten.“","a":"Man muss noch sehen, wie es ausgeht."},{"q":"Schreiben Sie fünf Regeln für Ihren Arbeitsplatz mit Ersatzformen.","a":"","m":"Die Tür ist abends abzuschließen. Man trinkt im Labor keinen Kaffee. Der Drucker lässt sich nur mit Karte benutzen. Pausen sind im Kalender einzutragen. Private Anrufe sind nicht erlaubt."},{"q":"Erklären Sie mündlich eine Geräteanleitung (mit „lässt sich“).","a":"","m":"Das Gerät lässt sich ganz einfach einschalten: Du drückst diesen Knopf. Der Wassertank lässt sich herausnehmen und leicht reinigen."},{"q":"Welche Regeln in Deutschland finden Sie sinnvoll, welche zu streng?","a":"","m":"Die Mülltrennung finde ich sinnvoll. Die Ruhezeiten am Sonntag finde ich manchmal zu streng, weil man nicht einmal staubsaugen darf."}],"speak":["Erkläre die Küchenregeln auf dem Bild mit „ist zu …“ und „lässt sich …“.","Beschreibe, wie sich ein Gerät bei dir zu Hause bedienen lässt.","Formuliere drei Hausordnungspunkte für deine Wohnung.","Was lässt sich in deinem Alltag leicht verbessern?"],"reading2":{"title":"Bedienungsanleitung: Smarter Heizkörperthermostat „ThermoCasa“","text":"Wichtige Sicherheitshinweise: Das Gerät ist ausschließlich für den Gebrauch in geschlossenen Räumen bestimmt. Es ist vor Feuchtigkeit und direkter Sonneneinstrahlung zu schützen. Bei unsachgemäßer Montage übernimmt der Hersteller keine Haftung. Installation: Der Thermostat lässt sich ohne Werkzeug an fast allen gängigen Heizkörpern montieren. Zunächst ist der alte Thermostatkopf abzuschrauben. Dazu ist der Heizkörper auf Stufe 5 zu drehen, damit sich der Kopf leichter lösen lässt. Anschließend ist der passende Adapter aufzusetzen; welcher Adapter benötigt wird, ist der beiliegenden Tabelle zu entnehmen. Die Batterien sind vor dem ersten Gebrauch einzulegen. Achten Sie dabei auf die richtige Polung. Einrichtung: Das Gerät lässt sich bequem über die kostenlose App steuern. Dafür ist zunächst ein Benutzerkonto anzulegen. Das Passwort sollte mindestens zwölf Zeichen lang sein. Die Raumtemperatur ist anschließend für jeden Tag individuell einstellbar. Erkennt der Thermostat ein geöffnetes Fenster, wird die Heizung automatisch heruntergeregelt. Fehlerbehebung: Reagiert das Gerät nicht, sind zunächst die Batterien zu überprüfen. Sollte sich das Problem dadurch nicht beheben lassen, kann das Gerät auf die Werkseinstellungen zurückgesetzt werden: Halten Sie dazu beide Tasten zehn Sekunden lang gedrückt. Persönliche Einstellungen sind danach leider nicht wiederherstellbar. Entsorgung: Altgeräte und Batterien dürfen nicht über den Hausmüll entsorgt werden. Sie sind bei den kommunalen Sammelstellen abzugeben."},"dialog":[{"who":"Ravi","de":"Jonas, mein neuer Thermostat lässt sich nicht mit der App verbinden."},{"who":"Jonas","de":"Hast du schon die Batterien überprüft?"},{"who":"Ravi","de":"Ja, die sind neu. In der Anleitung steht, das Gerät sei dann zurückzusetzen."},{"who":"Jonas","de":"Und? Lässt es sich zurücksetzen?"},{"who":"Ravi","de":"Ich habe beide Tasten gedrückt, aber es passiert nichts."},{"who":"Jonas","de":"Wie lange? Man muss sie zehn Sekunden gedrückt halten, das ist leicht zu übersehen."},{"who":"Ravi","de":"Oh. Ich habe nur drei Sekunden gedrückt. Moment … jetzt blinkt es!"},{"who":"Jonas","de":"Siehst du. Das Problem war lösbar – mit ein bisschen Geduld."}],"dq":[{"q":"Was ist Ravis Problem?","a":"Der Thermostat lässt sich nicht mit der App verbinden."},{"q":"Was steht in der Anleitung?","a":"Man muss das Gerät zurücksetzen."},{"q":"Was hat Ravi falsch gemacht?","a":"Er hat die Tasten nur drei statt zehn Sekunden gedrückt."}],"en":{"title":"Alternatives to the passive","theme":"Rules and instructions","expl":["Shorter forms with the same meaning as the werden-passive: **man** + active (__Man repariert das Gerät nicht mehr.__), **sich lassen** + infinitive = can be done (__Das Gerät lässt sich leicht reparieren.__), **sein + zu** + infinitive = must/can be done (__Die Formulare sind bis Freitag abzugeben.__), adjectives in **-bar / -lich** (__reparierbar, verständlich__)."],"use":""},"check":[{"re":"\\\\b(lässt sich|lassen sich|ist zu|sind zu|man)\\\\b|\\\\b\\\\w+(bar|lich)\\\\b","label":"passive alternatives (lässt sich, ist zu …, man, -bar)"}]},{"n":47,"pos":48,"level":"B2","title":"Konnektoren B2: falls, sofern, indem, sodass, anstatt dass","theme":"Bedingungen und Folgen","scene":"classroom","rec":[21,29,36,37],"expl":["**Bedingung:** **wenn / falls / sofern** (+ Nebensatz), **bei + Dat.** (nominal), **sonst** (negative Folge). __**Falls** es regnet, bleiben wir zu Hause.__","**Mittel/Weg:** **indem** (= dadurch, dass) antwortet auf **Wie?/Wodurch?**: __Man spart Energie, **indem** man kürzer duscht.__","**Folge:** **sodass** (Folge im Nebensatz), **so … dass**, **derart, dass**, **infolgedessen**. __Es regnete stark, **sodass** das Spiel ausfiel.__","**Alternative:** **anstatt dass / anstatt … zu**, **statt**; **Einschränkung:** **außer wenn, es sei denn**."],"use":"Argumentieren, Vorschläge begründen, Prozesse erklären – wichtig für Schreiben Teil 2 und Präsentationen.","table":[["Bedeutung","Konnektor","Beispiel"],["Bedingung","falls, sofern, wenn","**Sofern** Sie einverstanden sind, beginnen wir."],["Bedingung (nominal)","bei + Dat.","**Bei** Regen fällt das Fest aus."],["negative Bedingung","sonst, andernfalls","Beeil dich, **sonst** verpassen wir den Zug."],["Mittel","indem, dadurch, dass","Er hilft, **indem** er zuhört."],["Folge","sodass, so … dass","Der Text war so schwer, **dass** niemand ihn verstand."],["Alternative","anstatt … zu / anstatt dass","**Anstatt zu** klagen, sollten wir handeln."],["Ausnahme","außer wenn, es sei denn","Wir kommen, **es sei denn**, es schneit."]],"examples":[{"de":"Falls Sie Fragen haben, rufen Sie mich an.","en":"If you have questions, call me."},{"de":"Sofern das Budget reicht, kaufen wir neue Geräte.","en":"Provided the budget is enough, we\'ll buy new devices."},{"de":"Man lernt Vokabeln, indem man sie täglich wiederholt.","en":"You learn vocabulary by repeating it daily."},{"de":"Der Zug hatte Verspätung, sodass wir das Meeting verpassten.","en":"The train was late, so we missed the meeting."},{"de":"Es war so kalt, dass der See zufror.","en":"It was so cold that the lake froze."},{"de":"Anstatt zu diskutieren, sollten wir abstimmen.","en":"Instead of discussing, we should vote."},{"de":"Wir fahren morgen, es sei denn, das Wetter wird schlechter.","en":"We\'ll go tomorrow unless the weather gets worse."},{"de":"Bei Nichtgefallen können Sie die Ware zurückgeben.","en":"If you don\'t like it, you can return the goods."},{"de":"Beeilen Sie sich, andernfalls schließt der Schalter.","en":"Hurry up, otherwise the counter closes."},{"de":"Er verbesserte seine Noten, indem er regelmäßig übte.","en":"He improved his marks by practising regularly."},{"de":"Falls es regnet, findet das Fest in der Halle statt.","en":"If it rains, the party will take place in the hall."},{"de":"Sofern Sie einverstanden sind, schicken wir den Vertrag.","en":"Provided you agree, we\'ll send the contract."},{"de":"Man spart Energie, indem man die Heizung herunterdreht.","en":"You save energy by turning down the heating."},{"de":"Es regnete so stark, dass die Straßen überflutet wurden.","en":"It rained so heavily that the streets were flooded."},{"de":"Er ging, ohne dass es jemand bemerkte.","en":"He left without anyone noticing."},{"de":"Anstatt dass er sich entschuldigte, schrie er herum.","en":"Instead of apologising, he shouted around."},{"de":"Wir kommen, es sei denn, das Wetter ist schlecht.","en":"We\'ll come unless the weather is bad."},{"de":"Je nachdem, wie viel es kostet, buchen wir das Hotel.","en":"Depending on how much it costs, we\'ll book the hotel."},{"de":"Er kann kaum laufen, geschweige denn Fußball spielen.","en":"He can hardly walk, let alone play football."},{"de":"Soweit ich weiß, ist das Büro heute geschlossen.","en":"As far as I know, the office is closed today."}],"vocab":[{"de":"die Bedingung, -en","en":"condition"},{"de":"die Voraussetzung, -en","en":"prerequisite"},{"de":"die Folge, -n","en":"consequence"},{"de":"das Mittel, -","en":"means"},{"de":"abstimmen","en":"to vote"},{"de":"zurückgeben","en":"to return"},{"de":"einverstanden sein","en":"to agree"},{"de":"andernfalls","en":"otherwise"},{"de":"vorausgesetzt, dass","en":"provided that"},{"de":"je nachdem, ob","en":"depending on whether"},{"de":"zufrieren","en":"to freeze over"},{"de":"die Ausnahme, -n","en":"exception"},{"de":"falls","en":"in case, if"},{"de":"sofern","en":"provided that"},{"de":"soweit","en":"as far as"},{"de":"indem","en":"by (doing)"},{"de":"sodass / so … dass","en":"so that (result)"},{"de":"anstatt dass","en":"instead of"},{"de":"ohne dass","en":"without"},{"de":"je nachdem (ob/wie)","en":"depending on whether/how"},{"de":"es sei denn","en":"unless"},{"de":"geschweige denn","en":"let alone"},{"de":"insofern","en":"in that respect"},{"de":"dadurch, dass","en":"by (the fact) that"},{"de":"die Kündigungsfrist, -en","en":"notice period"},{"de":"die Versicherung, -en","en":"insurance"},{"de":"der Schaden, ¨","en":"damage"},{"de":"haften für","en":"to be liable for"},{"de":"der Vertrag, ¨e","en":"contract"},{"de":"verlängern","en":"to extend"},{"de":"das Kleingedruckte","en":"the small print"},{"de":"rechtzeitig","en":"in good time"}],"reading":"Aus einer Kursinfo: Der Kurs findet statt, sofern sich mindestens acht Personen anmelden. Sie sichern sich einen Platz, indem Sie die Anmeldung bis Freitag abschicken. Bei Absage erstatten wir die Gebühr vollständig. Die Räume sind klein, sodass wir die Gruppengröße begrenzen. Anstatt schriftliche Tests zu schreiben, arbeiten wir mit Präsentationen. Bitte kommen Sie pünktlich, andernfalls stören Sie die Gruppe.","tasks":[{"q":"___ es regnet, bleiben wir zu Hause. (Bedingung, formell)","a":"Falls"},{"q":"Man spart Zeit, ___ man Aufgaben plant.","a":"indem"},{"q":"Es war so laut, ___ ich nichts verstand.","a":"dass"},{"q":"Der Bus fiel aus, ___ wir zu Fuß gingen.","a":"sodass"},{"q":"___ zu warten, rief er sofort an.","a":"Anstatt"},{"q":"Wir fahren, ___ ___ ___, es schneit. (Ausnahme)","a":"es sei denn"},{"q":"Nominal: Wenn es regnet, … → ___ Regen …","a":"Bei"},{"q":"[Mix] ___ Sie einverstanden sind, ___ wir sofort. (sofern; beginnen)","a":"Sofern / beginnen"},{"q":"[Mix] Der Kurs finde statt, ___ sich acht Personen anmeldeten. (indirekte Rede)","a":"sofern"},{"q":"[Mix] Die Gebühr ___ vollständig ___ (erstatten, Passiv Präsens).","a":"wird / erstattet"},{"q":"___ du Hilfe brauchst, ruf mich an. (falls/indem)","a":"Falls"},{"q":"Er hält sich fit, ___ er jeden Tag läuft. (indem/sodass)","a":"indem"},{"q":"Es war so laut, ___ ich nicht schlafen konnte.","a":"dass"},{"q":"Sie verließ den Raum, ___ ___ jemand es merkte.","a":"ohne dass"},{"q":"Wir fahren morgen, es ___ ___, es schneit.","a":"sei denn"},{"q":"Verbinde mit indem: Man lernt Vokabeln. Man wiederholt sie täglich.","a":"Man lernt Vokabeln, indem man sie täglich wiederholt."},{"q":"Verbinde mit sodass: Der Zug hatte Verspätung. Ich verpasste den Anschluss.","a":"Der Zug hatte Verspätung, sodass ich den Anschluss verpasste."},{"q":"Verbinde mit sofern: Wir helfen gern. Wir haben Zeit.","a":"Wir helfen gern, sofern wir Zeit haben."},{"q":"___ ich weiß, ist er schon abgereist. (soweit/sofern)","a":"Soweit"},{"q":"Fehler? „Er sparte Geld, indem er kochte selbst.“","a":"Er sparte Geld, indem er selbst kochte."}],"exam":[{"q":"Wann findet der Kurs statt?","a":"Wenn sich mindestens acht Personen anmelden."},{"q":"Wie sichert man sich einen Platz?","a":"Indem man die Anmeldung bis Freitag abschickt."},{"q":"Warum ist die Gruppe klein?","a":"Weil die Räume klein sind."},{"q":"Verbinde mit indem: Er hat abgenommen. Er isst weniger Zucker.","a":"Er hat abgenommen, indem er weniger Zucker isst."},{"q":"Verbinde mit sodass: Es schneite stark. Die Schule fiel aus.","a":"Es schneite stark, sodass die Schule ausfiel."},{"q":"Verbinde mit anstatt … zu: Er lernt nicht. Er spielt.","a":"Anstatt zu lernen, spielt er."},{"q":"Ersetze „wenn“ durch „falls“ und erkläre den Unterschied.","a":"Falls betont, dass die Bedingung unsicher ist."},{"q":"Erklären Sie, wie man in Ihrem Beruf ein Problem löst (mit indem, sodass).","a":"","m":"In meinem Beruf löst man ein Problem, indem man zuerst die Ursache sucht. Wir testen jede Änderung, sodass keine neuen Fehler entstehen. Falls es nicht klappt, fragen wir das Team."},{"q":"Nennen Sie drei Bedingungen für gutes Lernen (falls/sofern/vorausgesetzt).","a":"","m":"Man lernt gut, sofern man regelmäßig übt. Falls man müde ist, sollte man eine Pause machen. Vorausgesetzt, man hat ein klares Ziel, lernt man schneller."},{"q":"Diskutieren Sie: Sollte man Tests durch Präsentationen ersetzen?","a":"","m":"Präsentationen sind sinnvoll, indem sie das freie Sprechen trainieren. Falls man aber nur Präsentationen macht, lernt man die Grammatik weniger genau. Ich finde eine Mischung am besten."}],"speak":["Erkläre eine Kursregel mit falls / sofern / andernfalls.","Wie lernst du am besten? Antworte mit __indem …__","Was passiert, wenn du zu spät kommst? (sodass / sonst)","Was machst du anstatt fernzusehen?"],"reading2":{"title":"Der Handyvertrag – das Kleingedruckte lesen lohnt sich","text":"Tomás wollte eigentlich nur einen günstigeren Handytarif. Im Laden versprach ihm der Verkäufer: „Sie zahlen nur 9,99 Euro im Monat, sofern Sie den Vertrag heute abschließen.“ Tomás unterschrieb, ohne dass er die Vertragsbedingungen genau gelesen hatte. Drei Monate später kam die erste Überraschung: Die Rechnung war doppelt so hoch. Es stellte sich heraus, dass der günstige Preis nur in den ersten drei Monaten galt. Danach kostete der Tarif 24,99 Euro. Außerdem hatte der Verkäufer ihm eine Zusatzoption für Musikstreaming verkauft, die automatisch kostenpflichtig wurde, falls man sie nicht innerhalb von vier Wochen kündigte. Tomás war wütend. Er fragte Leila um Rat, die ihm empfahl, sich an die Verbraucherzentrale zu wenden. Die Beraterin dort erklärte ihm, dass er die Zusatzoption zwar bezahlen müsse, er aber einiges tun könne, indem er sofort schriftlich kündige. Seit einer Gesetzesänderung können Verbraucher nach Ablauf der Mindestlaufzeit monatlich kündigen, sodass sie nicht mehr automatisch für ein weiteres Jahr gebunden sind. Die erste Laufzeit von 24 Monaten musste Tomás allerdings einhalten, es sei denn, der Anbieter hätte ihn nachweislich falsch beraten. Das ließ sich jedoch nicht beweisen, da es keine Zeugen gab. Tomás’ Fazit: „Ich unterschreibe nie wieder etwas, ohne das Kleingedruckte zu lesen. Und falls mir jemand ein Angebot macht, das nur heute gilt, gehe ich erst recht nach Hause und denke nach.“"},"dialog":[{"who":"Beraterin","de":"Verbraucherzentrale, guten Tag. Worum geht es?"},{"who":"Tomás","de":"Ich habe einen Handyvertrag abgeschlossen, und jetzt ist die Rechnung viel höher als versprochen."},{"who":"Beraterin","de":"Haben Sie die Vertragsunterlagen vor sich? Sofern der höhere Preis dort steht, ist er leider gültig."},{"who":"Tomás","de":"Er steht im Kleingedruckten. Kann ich trotzdem etwas tun?"},{"who":"Beraterin","de":"Sie können Zusatzoptionen kündigen, indem Sie dem Anbieter schriftlich mitteilen, dass Sie sie nicht mehr wünschen."},{"who":"Tomás","de":"Und den ganzen Vertrag?"},{"who":"Beraterin","de":"Nach Ablauf der Mindestlaufzeit können Sie monatlich kündigen, es sei denn, Sie verlängern ihn ausdrücklich."},{"who":"Tomás","de":"Gut. Und falls der Anbieter nicht reagiert?"},{"who":"Beraterin","de":"Dann melden Sie sich wieder bei uns, sodass wir Ihnen einen Musterbrief schicken können."}],"dq":[{"q":"Wann ist der höhere Preis leider gültig?","a":"Sofern er in den Vertragsunterlagen steht."},{"q":"Wie kann Tomás Zusatzoptionen kündigen?","a":"Indem er dem Anbieter schriftlich mitteilt, dass er sie nicht mehr wünscht."},{"q":"Wann kann er monatlich kündigen?","a":"Nach Ablauf der Mindestlaufzeit."}],"en":{"title":"B2 connectors: falls, sofern, indem, sodass, anstatt dass","theme":"Conditions and consequences","expl":["Condition: **wenn / falls / sofern** (if, provided that): __Falls es regnet, bleiben wir zu Hause.__","Means: **indem** answers \\"how? by what means?\\": __Man spart Energie, indem man kürzer duscht.__ = You save energy by taking shorter showers.","Result: **sodass** / **so … dass** (so that, so … that): __Es regnete stark, sodass das Spiel ausfiel.__ Alternative: **anstatt dass** (instead of) with different subjects."],"use":""},"check":[{"re":"\\\\b(falls|sofern|indem|sodass|so dass|anstatt dass|vorausgesetzt)\\\\b","label":"falls, sofern, indem, sodass"}]},{"n":48,"pos":49,"level":"B2","title":"Funktionsverbgefüge und feste Verbindungen","theme":"Beruf und Verwaltung","scene":"office","rec":[31,45,46],"expl":["**Funktionsverbgefüge** sind feste Nomen-Verb-Verbindungen: __eine Entscheidung **treffen**__ (= entscheiden), __in Betracht **ziehen**__ (= erwägen), __zur Verfügung **stellen**__ (= bereitstellen).","Das Verb trägt kaum eigene Bedeutung; das **Nomen** trägt den Inhalt. Sie klingen **formell** und sind in Berichten, E-Mails und Verträgen sehr häufig.","Achte auf die feste **Präposition und den Artikel**: __in Frage stellen__ (ohne Artikel), __zur Verfügung stehen__ (zu der), __in Kraft treten__.","Lerne sie wie Vokabeln – als ganze Einheit mit Verb, Nomen und Präposition."],"use":"Formelle E-Mails, Berichte, Präsentationen; Lesetexte in Prüfungen.","table":[["Funktionsverbgefüge","einfaches Verb","Beispiel"],["eine Entscheidung treffen","entscheiden","Wir **treffen** morgen eine **Entscheidung**."],["in Betracht ziehen","erwägen","Wir **ziehen** diese Lösung **in Betracht**."],["zur Verfügung stellen/stehen","bereitstellen","Die Daten **stehen** Ihnen **zur Verfügung**."],["in Kraft treten","gültig werden","Das Gesetz **tritt** im Mai **in Kraft**."],["Rücksicht nehmen auf","rücksichtsvoll sein","Bitte **nehmen** Sie **Rücksicht auf** die Nachbarn."],["zur Sprache bringen","ansprechen","Ich **bringe** das Thema **zur Sprache**."],["in Anspruch nehmen","nutzen","Er **nimmt** Beratung **in Anspruch**."],["Bezug nehmen auf","sich beziehen auf","Ich **nehme Bezug auf** Ihr Schreiben."]],"examples":[{"de":"Wir müssen heute eine Entscheidung treffen.","en":"We have to make a decision today."},{"de":"Ich nehme Bezug auf unser Telefonat vom Montag.","en":"I refer to our phone call on Monday."},{"de":"Die Unterlagen stehen ab morgen zur Verfügung.","en":"The documents are available from tomorrow."},{"de":"Diese Möglichkeit ziehen wir ernsthaft in Betracht.","en":"We are seriously considering this option."},{"de":"Die neue Regelung tritt am 1. Juli in Kraft.","en":"The new rule comes into force on 1 July."},{"de":"Bitte nehmen Sie Rücksicht auf die anderen Gäste.","en":"Please be considerate of the other guests."},{"de":"Er hat die Beratung in Anspruch genommen.","en":"He made use of the consultation."},{"de":"Ich möchte das Problem im Meeting zur Sprache bringen.","en":"I\'d like to raise the problem in the meeting."},{"de":"Das stellt unsere Planung in Frage.","en":"That calls our planning into question."},{"de":"Wir setzen uns mit Ihnen in Verbindung.","en":"We will get in touch with you."},{"de":"Wir müssen bis Freitag eine Entscheidung treffen.","en":"We have to make a decision by Friday."},{"de":"Für Fragen stehe ich Ihnen gern zur Verfügung.","en":"I\'m happy to be available for any questions."},{"de":"Diese Lösung kommt für uns nicht in Frage.","en":"This solution is not an option for us."},{"de":"Haben Sie in Betracht gezogen, den Vertrag zu verlängern?","en":"Have you considered extending the contract?"},{"de":"Bitte nehmen Sie Rücksicht auf die Nachbarn.","en":"Please be considerate of the neighbours."},{"de":"In der Sitzung brachte sie das Problem zur Sprache.","en":"In the meeting she raised the problem."},{"de":"Er übernahm die volle Verantwortung für den Fehler.","en":"He took full responsibility for the mistake."},{"de":"Ich setze mich morgen mit dem Kunden in Verbindung.","en":"I\'ll get in touch with the customer tomorrow."},{"de":"Das Team steht unter großem Druck.","en":"The team is under a lot of pressure."},{"de":"Gib mir bitte Bescheid, wenn du fertig bist.","en":"Please let me know when you\'re finished."}],"vocab":[{"de":"die Regelung, -en","en":"regulation, arrangement"},{"de":"das Schreiben, -","en":"letter (formal)"},{"de":"die Beratung, -en","en":"consultation"},{"de":"die Frist einhalten","en":"to meet the deadline"},{"de":"in Kraft treten","en":"to come into force"},{"de":"Stellung nehmen zu","en":"to comment on"},{"de":"Kritik üben an","en":"to criticise"},{"de":"eine Rolle spielen","en":"to play a role"},{"de":"Abstand nehmen von","en":"to refrain from"},{"de":"zur Kenntnis nehmen","en":"to take note of"},{"de":"Maßnahmen ergreifen","en":"to take measures"},{"de":"Wert legen auf","en":"to attach importance to"},{"de":"eine Entscheidung treffen","en":"to make a decision"},{"de":"in Anspruch nehmen","en":"to make use of"},{"de":"zur Verfügung stehen","en":"to be available"},{"de":"zur Verfügung stellen","en":"to make available"},{"de":"in Frage kommen","en":"to be an option"},{"de":"in Betracht ziehen","en":"to consider"},{"de":"einen Antrag stellen","en":"to submit an application"},{"de":"eine Frage stellen","en":"to ask a question"},{"de":"Rücksicht nehmen auf","en":"to show consideration for"},{"de":"Einfluss nehmen auf","en":"to influence"},{"de":"zum Ausdruck bringen","en":"to express"},{"de":"zur Sprache bringen","en":"to raise (a topic)"},{"de":"in Gang setzen","en":"to set in motion"},{"de":"zu Ende bringen","en":"to complete"},{"de":"Bescheid geben","en":"to let know"},{"de":"einen Vorschlag machen","en":"to make a suggestion"},{"de":"Verantwortung übernehmen","en":"to take responsibility"},{"de":"unter Druck stehen","en":"to be under pressure"},{"de":"in Verbindung setzen mit","en":"to get in touch with"}],"reading":"E-Mail: „Sehr geehrte Frau Brandt, ich nehme Bezug auf Ihr Schreiben vom 3. Mai. Wir haben Ihre Anfrage zur Kenntnis genommen und ziehen Ihren Vorschlag in Betracht. Bevor wir eine Entscheidung treffen, möchten wir weitere Angebote einholen. Sollten Rückfragen bestehen, stehen wir Ihnen gern zur Verfügung. Wir setzen uns spätestens nächste Woche mit Ihnen in Verbindung und legen Wert auf eine schnelle Klärung.“","tasks":[{"q":"Setze ein: eine Entscheidung ___","a":"treffen"},{"q":"Setze ein: in Betracht ___","a":"ziehen"},{"q":"Setze ein: zur Verfügung ___ (etwas anbieten)","a":"stellen"},{"q":"Setze ein: in Kraft ___","a":"treten"},{"q":"Setze ein: Rücksicht ___ auf","a":"nehmen"},{"q":"Einfaches Verb: „Wir treffen eine Entscheidung.“","a":"Wir entscheiden."},{"q":"Formell: „Wir nutzen Ihr Angebot.“","a":"Wir nehmen Ihr Angebot in Anspruch."},{"q":"[Mix] Sobald das Gesetz ___ Kraft ___, ___ die alte Regel nicht mehr. (treten; gelten)","a":"in / tritt / gilt"},{"q":"[Mix] Wir nehmen Bezug ___ Ihr Schreiben ___ 3. Mai.","a":"auf / vom"},{"q":"[Mix] Der Kollege sagte, er ___ das Thema zur Sprache bringen. (Konj. I von werden)","a":"werde"},{"q":"eine Entscheidung ___ (treffen/machen)","a":"treffen"},{"q":"eine Frage ___ (stellen/machen)","a":"stellen"},{"q":"zur Verfügung ___ (stehen/liegen)","a":"stehen"},{"q":"in Betracht ___ (ziehen/nehmen)","a":"ziehen"},{"q":"Rücksicht ___ auf (nehmen/geben)","a":"nehmen"},{"q":"zur Sprache ___ (bringen/stellen)","a":"bringen"},{"q":"Verantwortung ___ (übernehmen/machen)","a":"übernehmen"},{"q":"Umformen: Wir entscheiden morgen. → Wir ___ morgen eine Entscheidung.","a":"treffen"},{"q":"Umformen: Sie beantragt ein Visum. → Sie ___ einen Antrag auf ein Visum.","a":"stellt"},{"q":"Fehler? „Er hat eine Entscheidung gemacht.“","a":"Er hat eine Entscheidung getroffen."}],"exam":[{"q":"Worauf nimmt die E-Mail Bezug?","a":"Auf das Schreiben vom 3. Mai."},{"q":"Was macht die Firma vor der Entscheidung?","a":"Sie holt weitere Angebote ein."},{"q":"Wann meldet sich die Firma?","a":"Spätestens nächste Woche."},{"q":"Formell formulieren: „Wir überlegen das.“","a":"Wir ziehen das in Betracht."},{"q":"Formell formulieren: „Wir kritisieren den Plan.“","a":"Wir üben Kritik an dem Plan."},{"q":"Einfaches Verb: „Er nimmt Abstand von dem Vertrag.“","a":"Er verzichtet auf den Vertrag."},{"q":"Richtig oder falsch: „Ich mache eine Entscheidung.“","a":"Falsch – man trifft eine Entscheidung."},{"q":"Schreiben Sie eine formelle E-Mail (80 Wörter) mit vier Funktionsverbgefügen.","a":"","m":"Sehr geehrte Frau Lange, ich möchte Bezug auf Ihre Anfrage nehmen. Wir stellen Ihnen die Unterlagen gern zur Verfügung. Bitte treffen Sie bis Freitag eine Entscheidung. Für Rückfragen stehe ich Ihnen gern zur Verfügung. Mit freundlichen Grüßen, Ravi Sharma"},{"q":"Sprechen Sie 2 Minuten über eine Entscheidung im Beruf – formell.","a":"","m":"Im letzten Jahr mussten wir eine wichtige Entscheidung treffen. Wir haben verschiedene Lösungen in Betracht gezogen. Am Ende haben wir das Projekt zum Abschluss gebracht."},{"q":"Wann klingt Amtsdeutsch unpassend? Nennen Sie Beispiele.","a":"","m":"Amtsdeutsch klingt unpassend unter Freunden. „Ich nehme Ihre Einladung zur Kenntnis“ klingt kalt. Besser ist: „Danke, ich komme gern!“"}],"speak":["Formuliere die Bildsituation formell: __Die Kollegen treffen eine Entscheidung …__","Sag drei Sätze aus deinem Beruf mit Funktionsverbgefügen.","Übersetze deine letzte E-Mail in formelles Deutsch.","Wie klingt derselbe Inhalt freundlich-informell?"],"reading2":{"title":"Protokoll der Teamsitzung","text":"Teilnehmende: Frau Lange (Leitung), Herr Sharma, Frau Öztürk, Herr Brandt. Protokoll: Herr Brandt. TOP 1 – Projekt „Smart Home“: Frau Lange teilte mit, dass der Kunde Änderungen am Design in Auftrag gegeben habe. Das Team stehe deshalb unter erheblichem Zeitdruck. Herr Sharma brachte zur Sprache, dass die ursprüngliche Planung keine Puffer vorgesehen habe. Er machte den Vorschlag, externe Unterstützung in Anspruch zu nehmen. Frau Öztürk gab zu bedenken, dass dies das Budget belaste. Nach kurzer Diskussion wurde vereinbart, zunächst eine interne Lösung in Betracht zu ziehen. Frau Lange wird sich mit der Personalabteilung in Verbindung setzen, um zu klären, ob Kolleginnen und Kollegen aus anderen Abteilungen zur Verfügung stehen. Eine endgültige Entscheidung soll bis Mittwoch getroffen werden. TOP 2 – Homeoffice-Regelung: Herr Brandt brachte zum Ausdruck, dass die aktuelle Regelung zu unflexibel sei. Frau Lange betonte, die Geschäftsführung lege großen Wert auf persönliche Zusammenarbeit, sei aber für Vorschläge offen. Herr Sharma übernimmt die Verantwortung dafür, bis zur nächsten Sitzung ein Konzept auszuarbeiten. TOP 3 – Verschiedenes: Frau Öztürk gab Bescheid, dass sie ab Mitte des Monats für zwei Wochen Urlaub in Anspruch nehmen werde. Herr Sharma übernimmt ihre Vertretung. Die nächste Sitzung findet am kommenden Montag um 10 Uhr statt."},"dialog":[{"who":"Frau Lange","de":"Herr Sharma, haben Sie schon eine Entscheidung zum Homeoffice-Konzept getroffen?"},{"who":"Ravi","de":"Ich habe zwei Varianten ausgearbeitet. Beide kommen meiner Meinung nach in Frage."},{"who":"Frau Lange","de":"Stellen Sie sie bitte kurz vor."},{"who":"Ravi","de":"Variante A: zwei feste Bürotage für alle. Variante B: Jedes Team trifft die Entscheidung selbst."},{"who":"Frau Lange","de":"Bei Variante B hätten die Teams mehr Einfluss. Aber die Geschäftsführung legt Wert auf Einheitlichkeit."},{"who":"Ravi","de":"Das habe ich in Betracht gezogen. Deshalb würde ich Variante A empfehlen, mit Ausnahmen in Notfällen."},{"who":"Frau Lange","de":"Gut. Bringen Sie das bitte in der nächsten Sitzung zur Sprache."}],"dq":[{"q":"Wie viele Varianten hat Ravi ausgearbeitet?","a":"Zwei."},{"q":"Was ist Variante B?","a":"Jedes Team entscheidet selbst."},{"q":"Welche Variante empfiehlt Ravi?","a":"Variante A (zwei feste Bürotage, mit Ausnahmen in Notfällen)."}],"en":{"title":"Noun–verb phrases and fixed combinations","theme":"Work and administration","expl":["Noun–verb phrases (**Funktionsverbgefüge**) are fixed combinations of a noun and a weak verb: __eine Entscheidung treffen__ (= entscheiden, to make a decision), __in Betracht ziehen__ (to consider), __zur Verfügung stellen__ (to provide).","The verb carries hardly any meaning – the noun carries the content. They sound formal and are very common in reports, emails and contracts."],"use":""},"check":[{"re":"\\\\b(treffen|stellen|nehmen|bringen|ziehen|kommen|führen|leisten|stehen|geben|setzen)\\\\b","label":"noun–verb phrases (eine Entscheidung treffen, zur Verfügung stellen)"}]},{"n":49,"pos":50,"level":"B2","title":"Subjektive Modalverben: Vermutungen ausdrücken","theme":"Vermuten und Schlussfolgern","scene":"city","rec":[11,25,41],"expl":["Modalverben haben eine **zweite, subjektive Bedeutung**: Sie zeigen, **wie sicher** der Sprecher ist.","**muss** = fast sicher (logischer Schluss): __Er **muss** krank sein.__ · **dürfte** = wahrscheinlich, vorsichtig: __Das **dürfte** stimmen.__","**könnte/kann** = möglich · **mag** = zugestanden möglich · **will** = jemand **behauptet** über sich selbst: __Er **will** nichts gewusst haben.__ · **soll** = andere behaupten: __Sie **soll** sehr streng sein.__","Vergangenheit: **Modalverb + Partizip II + haben/sein**: __Er **muss** den Zug **verpasst haben**.__ Alternativen ohne Modalverb: **wohl, vermutlich, offenbar, anscheinend, werden + wohl**."],"use":"Bilder beschreiben, Hypothesen formulieren, höflich distanziert berichten.","table":[["Form","Sicherheit","Beispiel"],["muss","~95 % sicher","Sie **muss** im Stau stehen."],["dürfte","~75 %, vorsichtig","Das **dürfte** teuer werden."],["könnte / kann","möglich","Er **könnte** krank sein."],["mag","eingeräumt möglich","Das **mag** stimmen, aber …"],["kann nicht","ausgeschlossen","Das **kann** nicht wahr **sein**."],["will (+ P II)","Eigenbehauptung","Er **will** alles allein gemacht **haben**."],["soll (+ P II)","Fremdbehauptung","Sie **soll** befördert worden **sein**."]],"examples":[{"de":"Er muss den Bus verpasst haben.","en":"He must have missed the bus."},{"de":"Das dürfte etwa zwei Stunden dauern.","en":"That will probably take about two hours."},{"de":"Sie könnte im Büro geblieben sein.","en":"She might have stayed at the office."},{"de":"Das kann nicht stimmen.","en":"That can\'t be right."},{"de":"Er will den Bericht nicht bekommen haben.","en":"He claims he didn\'t receive the report."},{"de":"Die Firma soll Probleme haben.","en":"The company is said to have problems."},{"de":"Das mag ungewöhnlich sein, ist aber erlaubt.","en":"That may be unusual, but it\'s allowed."},{"de":"Sie wird wohl noch im Meeting sein.","en":"She\'s probably still in the meeting."},{"de":"Offenbar hat niemand die E-Mail gelesen.","en":"Apparently nobody read the email."},{"de":"Anscheinend ist der Server ausgefallen.","en":"Apparently the server crashed."},{"de":"Er muss krank sein, er sieht sehr blass aus.","en":"He must be ill, he looks very pale."},{"de":"Sie dürfte schon zu Hause sein.","en":"She is probably home already."},{"de":"Das kann ein Missverständnis gewesen sein.","en":"That could have been a misunderstanding."},{"de":"Der Schauspieler soll sehr reich sein.","en":"The actor is said to be very rich."},{"de":"Er will den Unfall nicht gesehen haben.","en":"He claims not to have seen the accident."},{"de":"Sie wird wohl im Stau stehen.","en":"She\'s probably stuck in traffic."},{"de":"Er mag recht haben, aber ich bin anderer Meinung.","en":"He may be right, but I disagree."},{"de":"Der Dieb muss durch das Fenster gekommen sein.","en":"The thief must have come through the window."},{"de":"Das Paket dürfte morgen ankommen.","en":"The parcel should arrive tomorrow."},{"de":"Man kann nicht ausschließen, dass es ein Fehler war.","en":"One can\'t rule out that it was a mistake."}],"vocab":[{"de":"die Vermutung, -en","en":"assumption"},{"de":"vermuten","en":"to assume"},{"de":"offenbar / anscheinend","en":"apparently"},{"de":"vermutlich","en":"presumably"},{"de":"ausgeschlossen","en":"out of the question"},{"de":"der Hinweis, -e","en":"clue"},{"de":"schlussfolgern","en":"to conclude"},{"de":"zweifeln an","en":"to doubt"},{"de":"behaupten","en":"to claim"},{"de":"eindeutig","en":"clear, unambiguous"},{"de":"der Verdacht","en":"suspicion"},{"de":"nachweisen","en":"to prove"},{"de":"müssen (Vermutung)","en":"must (≈ certainly)"},{"de":"dürfte","en":"is likely to"},{"de":"können (Vermutung)","en":"could, might"},{"de":"mögen (Vermutung)","en":"may (concessive)"},{"de":"sollen (Gerücht)","en":"is said to"},{"de":"wollen (Behauptung)","en":"claims to"},{"de":"werden … wohl","en":"probably will"},{"de":"höchstwahrscheinlich","en":"most probably"},{"de":"womöglich","en":"possibly"},{"de":"zweifellos","en":"undoubtedly"},{"de":"das Indiz, -ien","en":"circumstantial evidence"},{"de":"der Zeuge, -n / die Zeugin, -nen","en":"witness"},{"de":"die Spur, -en","en":"trace, clue"},{"de":"das Alibi, -s","en":"alibi"},{"de":"der Täter, -","en":"perpetrator"},{"de":"verdächtig","en":"suspicious"},{"de":"das Gerücht, -e","en":"rumour"},{"de":"die Schlussfolgerung, -en","en":"conclusion"},{"de":"ausschließen","en":"to rule out"},{"de":"widerlegen","en":"to refute"}],"reading":"Im Büro: Der Server ist seit dem Morgen nicht erreichbar. „Das muss an dem Update liegen“, meint Mia. Jonas widerspricht: „Das dürfte eher ein Netzwerkproblem sein; das Update soll gut getestet worden sein.“ Ravi ergänzt: „Der Techniker will die Leitung gestern geprüft haben. Trotzdem könnte ein Kabel locker sein.“ Am Nachmittag ist klar: Das Kabel war es nicht – anscheinend hatte jemand die Firewall geändert.","tasks":[{"q":"Fast sicher: Er ___ im Stau stehen.","a":"muss"},{"q":"Vorsichtige Vermutung: Das ___ stimmen.","a":"dürfte"},{"q":"Möglichkeit: Sie ___ krank sein.","a":"könnte"},{"q":"Ausgeschlossen: Das ___ nicht wahr sein.","a":"kann"},{"q":"Fremdbehauptung: Die Firma ___ Probleme haben.","a":"soll"},{"q":"Eigenbehauptung: Er ___ nichts gewusst haben.","a":"will"},{"q":"Vergangenheit: Sie muss den Termin ___ ___. (vergessen)","a":"vergessen haben"},{"q":"[Mix] Anscheinend ___ die E-Mail nicht ___ worden. (lesen, Passiv Perfekt)","a":"ist / gelesen"},{"q":"[Mix] Er sagt, er ___ die Leitung geprüft. (Konj. I von haben)","a":"habe"},{"q":"[Mix] Das Problem ___ ___ (sich lösen lassen), sobald das Kabel getauscht ist.","a":"lässt sich lösen"},{"q":"Vermutung (sehr sicher): Er ist bestimmt zu Hause. → Er ___ zu Hause sein.","a":"muss"},{"q":"Vermutung (wahrscheinlich): Sie ist wahrscheinlich krank. → Sie ___ krank sein.","a":"dürfte"},{"q":"Vermutung (möglich): Vielleicht hat er recht. → Er ___ recht haben.","a":"könnte"},{"q":"Gerücht: Man sagt, er ist reich. → Er ___ reich sein.","a":"soll"},{"q":"Behauptung: Er behauptet, er war zu Hause. → Er ___ zu Hause gewesen sein.","a":"will"},{"q":"Vergangenheit: Sie ist bestimmt schon gegangen. → Sie muss schon gegangen ___.","a":"sein"},{"q":"Vergangenheit: Er hat es wahrscheinlich vergessen. → Er dürfte es vergessen ___.","a":"haben"},{"q":"Futur: Er ist wohl müde. → Er ___ wohl müde sein.","a":"wird"},{"q":"Objektiv oder subjektiv? „Er muss früh aufstehen, weil er um sechs arbeitet.“ (o/s)","a":"o"},{"q":"Fehler? „Er soll gestern im Kino war.“","a":"Er soll gestern im Kino gewesen sein."}],"exam":[{"q":"Was vermutet Mia?","a":"Dass es am Update liegt."},{"q":"Was behauptet der Techniker über sich?","a":"Er habe die Leitung geprüft."},{"q":"Was war die Ursache?","a":"Anscheinend eine Änderung an der Firewall."},{"q":"Formuliere mit „dürfte“: Wahrscheinlich kostet es 200 Euro.","a":"Das dürfte 200 Euro kosten."},{"q":"Formuliere mit „soll“: Andere sagen, er sei umgezogen.","a":"Er soll umgezogen sein."},{"q":"Formuliere mit „muss“ (Vergangenheit): Sicher hat sie den Zug verpasst.","a":"Sie muss den Zug verpasst haben."},{"q":"Unterschied: „Er will es gemacht haben.“ vs. „Er soll es gemacht haben.“","a":"will = eigene Behauptung; soll = Behauptung anderer"},{"q":"Beschreiben Sie ein Foto und stellen Sie fünf Vermutungen an.","a":"","m":"Die Frau auf dem Foto dürfte etwa 40 sein. Sie muss gerade von der Arbeit kommen. Sie könnte Ärztin sein. Das Wetter dürfte kalt sein. Sie wird wohl müde sein."},{"q":"Ein Kollege fehlt ohne Nachricht. Äußern Sie Vermutungen höflich.","a":"","m":"Herr Klein ist noch nicht da. Er könnte im Stau stehen. Vielleicht dürfte er krank sein. Er wird wohl gleich anrufen."},{"q":"Warum sind vorsichtige Formulierungen im Beruf wichtig?","a":"","m":"Vorsichtige Formulierungen sind wichtig, weil man nicht unhöflich wirken will. Sie lassen Raum für andere Meinungen."}],"speak":["Stelle fünf Vermutungen zur Straßenszene an (muss, dürfte, könnte, soll, will).","Dein Paket ist nicht angekommen. Was könnte passiert sein?","Was dürfte sich in deinem Beruf in zehn Jahren ändern?","Wie sagst du höflich, dass du an einer Behauptung zweifelst?"],"reading2":{"title":"Der rätselhafte Fall im Treppenhaus","text":"Am Montagmorgen fand Frau Lindner vor ihrer Wohnungstür einen Blumenstrauß. Kein Zettel, kein Name. „Das muss ein Irrtum sein“, dachte sie zuerst. „Wer sollte mir schon Blumen schenken?“ Sie klingelte bei Anna Weber. Anna betrachtete die Blumen genau. „Rosen und Lavendel – die dürften ziemlich teuer gewesen sein. Und sie sind frisch, sie können erst heute Morgen gekauft worden sein.“ Frau Lindner ging im Kopf die Verdächtigen durch. Der junge Mann aus dem zweiten Stock? Er will sie letzte Woche gar nicht gegrüßt haben, als sie sich über die laute Musik beschwert hatte. Ein schlechtes Gewissen könnte ein Motiv sein. Oder Herr Kaya? Er soll früher in seinem Gemüseladen auch Blumen verkauft haben. Anna fand eine weitere Spur: Auf der Treppe lag ein Kassenbon von einem Blumenladen in der Schönhauser Allee, gekauft um 7:42 Uhr. „Um diese Zeit muss der Täter schon unterwegs gewesen sein. Jonas schläft bis neun, der scheidet also aus.“ Am Nachmittag löste sich das Rätsel. Paul, Annas Sohn, kam von der Schule nach Hause und fragte: „Haben Sie meine Blumen gefunden, Frau Lindner? Sie haben mir doch letzte Woche bei den Mathehausaufgaben geholfen.“ Frau Lindner war sprachlos. „Ich muss wohl vergessen haben, wie nett junge Leute sein können“, sagte sie später – und backte Paul einen Kuchen."},"dialog":[{"who":"Jonas","de":"Hast du gehört? Der Bäcker an der Ecke soll schließen."},{"who":"Mia","de":"Wirklich? Woher weißt du das?"},{"who":"Jonas","de":"Frau Lindner hat es erzählt. Der Besitzer will in Rente gehen."},{"who":"Mia","de":"Das kann aber auch nur ein Gerücht sein. Frau Lindner erzählt viel."},{"who":"Jonas","de":"Stimmt. Aber im Schaufenster hängt ein Zettel „Nachfolger gesucht“."},{"who":"Mia","de":"Dann dürfte es stimmen. Das wäre schade, das Brot ist so gut."},{"who":"Jonas","de":"Vielleicht findet sich ja ein Nachfolger. Das Geschäft muss eigentlich gut laufen, es ist immer voll."}],"dq":[{"q":"Was soll mit dem Bäcker passieren?","a":"Er soll schließen."},{"q":"Warum will der Besitzer aufhören?","a":"Er will in Rente gehen."},{"q":"Was hängt im Schaufenster?","a":"Ein Zettel „Nachfolger gesucht“."}],"en":{"title":"Modal verbs for guesses (how sure are you?)","theme":"Guessing and concluding","expl":["Modal verbs have a second meaning: they show **how sure the speaker is**. **muss** = almost certain (__Er muss krank sein.__ = He must be ill), **dürfte** = probably, **könnte / kann** = possibly, **mag** = may well be.","**will** = someone claims something about themselves (__Er will nichts gewusst haben.__ = He claims he knew nothing), **soll** = people say, it\'s reported (__Sie soll reich sein.__ = She\'s said to be rich)."],"use":""},"check":[{"re":"\\\\b(muss|müsste|dürfte|könnte|kann|mag|wird wohl|soll|will)\\\\b","label":"modal verbs for guesses (muss, dürfte, könnte)"}]},{"n":50,"pos":51,"level":"B2","title":"Konjunktiv II der Vergangenheit und irreale Vergleiche","theme":"Rückblick und Bedauern","scene":"party","rec":[25,34,49],"expl":["**Irreale Vergangenheit**: **hätte/wäre + Partizip II**: __**Hätte** ich das **gewusst**, **wäre** ich früher **gekommen**.__ (Ich wusste es nicht.)","Mit Modalverb steht der **doppelte Infinitiv**: __Ich **hätte** früher kommen **können/müssen/sollen**.__","Bedingungssätze ohne **wenn** beginnen mit dem Verb: __**Wäre** ich reicher, würde ich …__","**Irreale Vergleiche**: **als ob / als wenn + Konjunktiv II** (Verb am Ende) oder **als + Konjunktiv II** direkt: __Er tut so, **als ob** er alles **wüsste**. / Er tut so, **als wüsste** er alles.__","**Irreale Wünsche**: __**Wenn** ich nur mehr Zeit **hätte**! **Hätte** ich doch besser aufgepasst!__"],"use":"Bedauern ausdrücken, Kritik höflich formulieren, über verpasste Chancen sprechen – typisch für B2-Diskussionen.","table":[["Funktion","Struktur","Beispiel"],["Irreale Bedingung (Vergangenheit)","hätte/wäre + P II","Wenn ich Zeit **gehabt hätte**, **wäre** ich **gekommen**."],["mit Modalverb","hätte + Inf. + Modal-Inf.","Ich **hätte** anrufen **sollen**."],["ohne wenn","Verb zuerst","**Hättest** du gefragt, **hätte** ich geholfen."],["irrealer Vergleich","als ob + Konj. II (Ende)","Sie sieht aus, **als ob** sie krank **wäre**."],["irrealer Wunsch","Wenn … nur/doch + Konj. II","**Wenn** ich das **nur gewusst hätte**!"],["höfliche Kritik","hätte … können/sollen","Du **hättest** Bescheid sagen **können**."]],"examples":[{"de":"Wenn ich früher aufgestanden wäre, hätte ich den Zug erreicht.","en":"If I had got up earlier I\'d have caught the train."},{"de":"Ich hätte dich gern angerufen, aber mein Akku war leer.","en":"I\'d have liked to call you, but my battery was dead."},{"de":"Du hättest mir das sagen müssen.","en":"You should have told me."},{"de":"Hätte ich das gewusst, wäre ich zu Hause geblieben.","en":"Had I known that, I\'d have stayed home."},{"de":"Er tut so, als ob er alles verstanden hätte.","en":"He acts as if he had understood everything."},{"de":"Sie sieht aus, als hätte sie nicht geschlafen.","en":"She looks as if she hadn\'t slept."},{"de":"Wenn wir nur mehr Zeit gehabt hätten!","en":"If only we had had more time!"},{"de":"An deiner Stelle hätte ich abgesagt.","en":"In your position I\'d have cancelled."},{"de":"Beinahe wäre der Vertrag gescheitert.","en":"The contract almost failed."},{"de":"Das hätte auch schiefgehen können.","en":"That could have gone wrong too."},{"de":"Wenn ich früher losgefahren wäre, hätte ich den Zug erreicht.","en":"If I had left earlier, I would have caught the train."},{"de":"Hätte ich das gewusst, wäre ich nicht gekommen.","en":"Had I known that, I wouldn\'t have come."},{"de":"Du hättest mich anrufen sollen!","en":"You should have called me!"},{"de":"Ich hätte gern Medizin studiert.","en":"I would have liked to study medicine."},{"de":"Er tut so, als ob er nichts gehört hätte.","en":"He acts as if he hadn\'t heard anything."},{"de":"Sie sieht aus, als wäre sie die ganze Nacht wach gewesen.","en":"She looks as if she had been awake all night."},{"de":"Wir hätten fast den Flug verpasst.","en":"We almost missed the flight."},{"de":"Ohne deine Hilfe hätte ich es nicht geschafft.","en":"Without your help I wouldn\'t have managed it."},{"de":"Ich bereue nichts, aber manches würde ich heute anders machen.","en":"I regret nothing, but I\'d do some things differently today."},{"de":"Um ein Haar wäre der Unfall passiert.","en":"The accident very nearly happened."}],"vocab":[{"de":"bedauern","en":"to regret"},{"de":"das Bedauern","en":"regret"},{"de":"verpassen","en":"to miss"},{"de":"beinahe / fast","en":"almost"},{"de":"scheitern","en":"to fail"},{"de":"schiefgehen","en":"to go wrong"},{"de":"die Chance, -n","en":"chance"},{"de":"zugeben (gibt zu)","en":"to admit"},{"de":"vorwerfen (wirft vor)","en":"to reproach"},{"de":"der Vorwurf, ¨e","en":"reproach"},{"de":"rückblickend","en":"in retrospect"},{"de":"im Nachhinein","en":"in hindsight"},{"de":"hätte … gemacht","en":"would have done"},{"de":"wäre … gegangen","en":"would have gone"},{"de":"hätte … machen sollen","en":"should have done"},{"de":"hätte … können","en":"could have"},{"de":"als ob / als wenn + Konj. II","en":"as if"},{"de":"als + Konj. II (Verb vorn)","en":"as if"},{"de":"an deiner Stelle hätte ich …","en":"in your place I would have …"},{"de":"wenn ich das gewusst hätte","en":"if I had known that"},{"de":"die Reue","en":"regret, remorse"},{"de":"bereuen","en":"to regret"},{"de":"die Gelegenheit verpassen","en":"to miss the opportunity"},{"de":"die falsche Entscheidung","en":"the wrong decision"},{"de":"der Umweg, -e","en":"detour"},{"de":"der Zufall, ¨e","en":"coincidence"},{"de":"das Schicksal","en":"fate"},{"de":"glücklicherweise","en":"fortunately"},{"de":"ansonsten","en":"otherwise"},{"de":"um ein Haar","en":"by a hair\'s breadth"},{"de":"wenigstens","en":"at least"},{"de":"sich ärgern über","en":"to be annoyed about"}],"reading":"Nach der Feier: „Schade, dass Leila nicht da war“, sagt Anna. „Wenn wir sie früher eingeladen hätten, wäre sie sicher gekommen.“ Ravi gibt zu: „Ich hätte ihr schreiben sollen; ich habe es im Stress vergessen.“ Jonas lacht: „Du tust immer so, als ob du alles allein organisieren müsstest. Hättest du gefragt, hätte ich geholfen.“ Anna meint: „Im Nachhinein ist man klüger. Beinahe hätten wir auch den Kuchen vergessen!“","tasks":[{"q":"Wenn ich Zeit ___ ___, wäre ich gekommen. (haben)","a":"gehabt hätte"},{"q":"Du ___ mir helfen ___. (können, Vorwurf)","a":"hättest / können"},{"q":"___ ich das gewusst, wäre ich geblieben. (ohne wenn)","a":"Hätte"},{"q":"Er tut so, als ob er müde ___. (sein)","a":"wäre"},{"q":"Sie sieht aus, als ___ sie geweint. (haben)","a":"hätte"},{"q":"Irrealer Wunsch: Ich habe nicht gelernt. → Wenn ich ___ ___ ___!","a":"doch gelernt hätte"},{"q":"An deiner Stelle ___ ich abgesagt.","a":"hätte"},{"q":"[Mix] Wenn der Zug pünktlich ___ ___, ___ wir den Termin geschafft. (sein; haben)","a":"gewesen wäre / hätten"},{"q":"[Mix] Er behauptet, er ___ nichts davon gewusst. (Konj. I)","a":"habe"},{"q":"[Mix] Anstatt zu warten, ___ er sofort ___ ___. (anrufen, Konj. II Vergangenheit)","a":"hätte / anrufen sollen"},{"q":"Irreal Vergangenheit: Ich hatte keine Zeit, deshalb kam ich nicht. → Wenn ich Zeit gehabt ___, ___ ich gekommen.","a":"hätte / wäre"},{"q":"Irreal Vergangenheit: Er hat nicht gelernt. → Wenn er gelernt ___, hätte er bestanden.","a":"hätte"},{"q":"Ohne wenn: Wenn ich das gewusst hätte, … → ___ ich das gewusst, …","a":"Hätte"},{"q":"Vorwurf: Warum hast du nicht angerufen? → Du ___ anrufen sollen!","a":"hättest"},{"q":"Modalverb Vergangenheit: Ich musste es tun (irreal). → Ich ___ es tun müssen.","a":"hätte"},{"q":"Wunsch: Ich habe nicht studiert. → Ich ___ gern studiert.","a":"hätte"},{"q":"als ob: Er tut so, als ob er krank ___. (sein, Gegenwart)","a":"wäre"},{"q":"als ob Vergangenheit: Sie tut so, als ob sie nichts gesehen ___.","a":"hätte"},{"q":"als + Verb: Er sieht aus, als ___ er nicht geschlafen. (haben)","a":"hätte"},{"q":"Fehler? „Wenn ich früher gegangen hätte, hätte ich den Bus bekommen.“","a":"Wenn ich früher gegangen wäre, hätte ich den Bus bekommen."}],"exam":[{"q":"Warum war Leila nicht da?","a":"Sie wurde zu spät/nicht eingeladen."},{"q":"Was gibt Ravi zu?","a":"Dass er ihr hätte schreiben sollen."},{"q":"Was sagt Jonas über Ravi?","a":"Er tue so, als ob er alles allein organisieren müsste."},{"q":"Umformen: Ich hatte keine Zeit, deshalb kam ich nicht.","a":"Wenn ich Zeit gehabt hätte, wäre ich gekommen."},{"q":"Umformen (Vorwurf): Du hast nicht Bescheid gesagt.","a":"Du hättest Bescheid sagen können/sollen."},{"q":"Umformen (als ob): Er ist nicht der Chef, aber er verhält sich so.","a":"Er verhält sich, als ob er der Chef wäre."},{"q":"Ohne „wenn“: Wenn ich das gewusst hätte, …","a":"Hätte ich das gewusst, …"},{"q":"Erzählen Sie von einer verpassten Chance (5 Sätze im Konjunktiv II der Vergangenheit).","a":"","m":"Ich hätte nach dem Abitur ein Jahr im Ausland verbringen können. Wenn ich das gemacht hätte, wäre mein Englisch besser. Ich hätte mehr Mut haben sollen. Hätte ich das Stipendium angenommen, wäre ich nach Kanada gegangen. Heute bereue ich das ein bisschen."},{"q":"Kritisieren Sie höflich das Verhalten eines Kollegen.","a":"","m":"Es wäre schön gewesen, wenn du mich vorher informiert hättest. Du hättest mich auch fragen können."},{"q":"Was hätten Sie in Ihrem Leben anders gemacht? Warum?","a":"","m":"Ich hätte früher mit Deutsch anfangen sollen. Dann wäre der Umzug leichter gewesen."}],"speak":["Die Party ist vorbei: Was hättet ihr anders machen können?","Erzähle von einem Tag, an dem beinahe etwas schiefgegangen wäre.","Formuliere drei höfliche Vorwürfe mit „hättest … können“.","Wenn du noch einmal 18 wärst – was würdest du anders machen?"],"reading2":{"title":"„Ich hätte damals …“ – Leserinnen und Leser erzählen","text":"Wir haben gefragt: Welche Entscheidung würden Sie heute anders treffen? Hier eine Auswahl der Antworten. Bernd, 58: „Mit 20 bekam ich das Angebot, für ein Jahr in Kanada zu arbeiten. Ich habe abgelehnt, weil meine damalige Freundin nicht mitwollte. Ein halbes Jahr später hat sie sich getrennt. Hätte ich das Angebot angenommen, wäre mein Leben wohl ganz anders verlaufen. Aber vielleicht hätte ich dann meine Frau nie kennengelernt. Insofern bereue ich es nicht wirklich.“ Sevgi, 34: „Ich hätte früher auf meinen Körper hören sollen. Jahrelang habe ich gearbeitet, als ob ich keine Pausen bräuchte. Erst nach einem Burn-out habe ich verstanden, dass ich mich hätte schützen müssen. Heute arbeite ich Teilzeit und bin viel glücklicher.“ Lukas, 27: „Wenn ich in der Schule mehr Englisch gelernt hätte, hätte ich mir später viel Stress erspart. Im Studium musste ich alles nachholen.“ Margarete, 81: „Ich habe immer gedacht, ich hätte noch Zeit. Ich hätte meine Schwester öfter besuchen sollen, bevor sie krank wurde. Mein Rat an junge Leute: Wartet nicht auf den perfekten Moment.“ Die Psychologin Dr. Weiß kommentiert: „Interessant ist, dass Menschen langfristig eher bereuen, was sie nicht getan haben, als ihre Fehler. Wer etwas versucht und scheitert, hat wenigstens etwas gelernt.“"},"dialog":[{"who":"Mia","de":"Ich habe die Prüfung leider nicht bestanden."},{"who":"Leila","de":"Oh nein. Was ist passiert?"},{"who":"Mia","de":"Ich hätte mehr lernen müssen. Und ich hätte nicht bis drei Uhr nachts Serien schauen sollen."},{"who":"Leila","de":"Das klingt, als ob du dir große Vorwürfe machen würdest."},{"who":"Mia","de":"Ja. Wenn ich früher angefangen hätte, wäre es bestimmt besser gelaufen."},{"who":"Leila","de":"Vielleicht. Aber im Nachhinein ist man immer klüger. Du kannst sie doch wiederholen, oder?"},{"who":"Mia","de":"Ja, im März. Diesmal mache ich einen Lernplan."},{"who":"Leila","de":"Siehst du. Dann war es wenigstens eine gute Lektion."}],"dq":[{"q":"Warum hat Mia die Prüfung nicht bestanden?","a":"Sie hat zu wenig gelernt (und zu lange Serien geschaut)."},{"q":"Wann kann sie die Prüfung wiederholen?","a":"Im März."},{"q":"Was macht sie diesmal anders?","a":"Sie macht einen Lernplan."}],"en":{"title":"Past subjunctive and unreal comparisons","theme":"Looking back and regret","expl":["Unreal past: **hätte/wäre + participle**: __Hätte ich das gewusst, wäre ich früher gekommen.__ = If I had known, I would have come earlier (but I didn\'t know).","With a modal verb you get a double infinitive: __Ich hätte früher kommen können / müssen / sollen.__ = I could / should have come earlier.","Unreal comparisons: **als ob / als wenn** + Konjunktiv II: __Er tut so, als ob er alles wüsste.__ = He acts as if he knew everything."],"use":""},"check":[{"re":"\\\\b(hätte|hätten|wäre|wären)\\\\b[^.!?]*\\\\b(ge\\\\w+(t|en)|\\\\w+iert)\\\\b|\\\\bals (ob|wenn)\\\\b","label":"hätte/wäre + Partizip II, als ob"}]},{"n":62,"pos":52,"level":"B2","title":"Passiv mit Modalverben und Zustandspassiv","theme":"Baustelle und Reparaturen","scene":"apartment","rec":[39,46],"expl":["Mit einem **Modalverb** bildet man das Passiv so: Modalverb (Position 2) + **Partizip II + werden** (Ende): __Die Heizung muss repariert werden.__ Im Nebensatz steht das Modalverb ganz am Ende: __…, weil die Heizung repariert werden muss.__","In der Vergangenheit steht das Modalverb im Präteritum: __Der Antrag konnte nicht bearbeitet werden.__ Im Perfekt (selten, eher schriftlich) entsteht ein doppelter Infinitiv: __Das Formular hat nicht gefunden werden können.__ Hier gilt: haben + … + Partizip II + werden + Modalverb.","Das **Zustandspassiv** (sein + Partizip II) beschreibt nicht den Vorgang, sondern das **Ergebnis**: __Die Tür wird geschlossen__ (jemand schließt sie gerade) – __Die Tür ist geschlossen__ (sie ist jetzt zu). Typisch auf Schildern und in Berichten: __Das Geschäft ist geöffnet. Der Fehler ist behoben.__"],"use":"Prüfung B2, Schreiben: Beschwerden, Berichte und Anleitungen („Die Mängel müssen bis Freitag beseitigt werden.“).","table":[["Form","Aktiv","Passiv"],["Präsens + Modalverb","Man muss das Dach reparieren.","Das Dach **muss repariert werden**."],["Präteritum + Modalverb","Man konnte den Fehler nicht finden.","Der Fehler **konnte** nicht **gefunden werden**."],["Nebensatz","…, weil man die Wand streichen soll.","…, weil die Wand **gestrichen werden soll**."],["Vorgangspassiv","Man öffnet das Geschäft um neun.","Das Geschäft **wird** um neun **geöffnet**."],["Zustandspassiv","(Ergebnis)","Das Geschäft **ist** jetzt **geöffnet**."]],"examples":[{"de":"Die Fenster müssen dringend erneuert werden.","en":"The windows urgently need to be replaced."},{"de":"Der Schaden kann erst nächste Woche behoben werden.","en":"The damage can\'t be repaired until next week."},{"de":"Der Aufzug darf während der Arbeiten nicht benutzt werden.","en":"The lift must not be used during the work."},{"de":"Das Wasser sollte vorher abgestellt werden.","en":"The water should be turned off beforehand."},{"de":"Die Wohnung konnte nicht rechtzeitig übergeben werden.","en":"The flat could not be handed over on time."},{"de":"Ich weiß nicht, ob das bis Montag erledigt werden kann.","en":"I don\'t know whether this can be done by Monday."},{"de":"Die Straße ist seit gestern gesperrt.","en":"The road has been closed since yesterday."},{"de":"Der Fehler ist inzwischen behoben.","en":"The fault has now been fixed."},{"de":"Die Tür war abgeschlossen, als wir ankamen.","en":"The door was locked when we arrived."},{"de":"Alle Zimmer sind frisch gestrichen.","en":"All the rooms are freshly painted."},{"de":"Die Rechnung muss innerhalb von zwei Wochen bezahlt werden.","en":"The invoice must be paid within two weeks."},{"de":"Hier darf nicht geparkt werden.","en":"Parking is not allowed here."},{"de":"Die Arbeiten sollen bis Ende Mai abgeschlossen sein.","en":"The work is supposed to be completed by the end of May."},{"de":"Der Vertrag ist bereits unterschrieben.","en":"The contract is already signed."},{"de":"Das hätte früher geprüft werden müssen.","en":"That should have been checked earlier."}],"vocab":[{"de":"der Mangel, ¨","en":"defect"},{"de":"beseitigen","en":"to remove, to eliminate"},{"de":"beheben","en":"to fix, to remedy"},{"de":"erneuern","en":"to renew, to replace"},{"de":"abstellen","en":"to turn off (water, gas)"},{"de":"sperren","en":"to close off, to block"},{"de":"abschließen","en":"to lock; to complete"},{"de":"der Handwerkertermin, -e","en":"tradesperson\'s appointment"},{"de":"die Hausverwaltung, -en","en":"property management"},{"de":"der Schimmel","en":"mould"},{"de":"die Feuchtigkeit","en":"damp, humidity"},{"de":"undicht","en":"leaking"},{"de":"die Mietminderung, -en","en":"rent reduction"},{"de":"fristgerecht","en":"by the deadline"},{"de":"die Baustelle, -n","en":"construction site"},{"de":"der Lärm","en":"noise"},{"de":"übergeben","en":"to hand over"},{"de":"die Abnahme, -n","en":"(official) acceptance, inspection"},{"de":"der Kostenvoranschlag, ¨e","en":"cost estimate"},{"de":"in Auftrag geben","en":"to commission"}],"reading":"Liebe Mieterinnen und Mieter, wie bereits angekündigt, muss das Dach unseres Hauses in den kommenden Wochen vollständig erneuert werden. Bei der letzten Prüfung wurden mehrere undichte Stellen entdeckt, die nicht länger aufgeschoben werden können. Die Arbeiten beginnen am 3. Juni und sollen bis Ende Juli abgeschlossen sein. Während dieser Zeit ist der Hof teilweise gesperrt. Fahrräder müssen deshalb im Keller abgestellt werden. Der Aufzug kann an einzelnen Tagen nicht benutzt werden; diese Tage werden rechtzeitig im Treppenhaus bekannt gegeben. Wir bitten um Verständnis, dass werktags zwischen 7 und 17 Uhr mit Lärm gerechnet werden muss. Die Dachgeschosswohnungen müssen vor Beginn der Arbeiten von den Handwerkern besichtigt werden. Bitte vereinbaren Sie dafür bis zum 20. Mai einen Termin mit der Hausverwaltung. Bereits bekannte Feuchtigkeitsschäden in den oberen Wohnungen werden im Anschluss an die Dacharbeiten behoben. Sollten Ihnen weitere Mängel auffallen, teilen Sie uns diese bitte schriftlich mit, damit sie in die Planung einbezogen werden können. Die Kosten der Sanierung werden nicht auf die Miete umgelegt. Mit freundlichen Grüßen, Ihre Hausverwaltung Schmidt & Partner","tasks":[{"q":"Passiv mit Modalverb: Man muss die Heizung reparieren. → Die Heizung muss ___ ___.","a":"repariert werden"},{"q":"Passiv mit Modalverb: Man kann das Problem lösen. → Das Problem kann ___ ___.","a":"gelöst werden"},{"q":"Passiv mit Modalverb: Man darf hier nicht rauchen. → Hier darf nicht ___ ___.","a":"geraucht werden"},{"q":"Passiv mit Modalverb, Präteritum: Man konnte den Schlüssel nicht finden. → Der Schlüssel konnte nicht ___ ___.","a":"gefunden werden"},{"q":"Nebensatz: …, weil die Wand ___ ___ ___. (streichen, müssen)","a":"gestrichen werden muss"},{"q":"Nebensatz: Ich weiß nicht, ob das heute ___ ___ ___. (erledigen, können)","a":"erledigt werden kann"},{"q":"Zustandspassiv: Jemand hat die Tür geschlossen. → Die Tür ___ ___.","a":"ist geschlossen"},{"q":"Zustandspassiv: Man hat den Fehler behoben. → Der Fehler ___ ___.","a":"ist behoben"},{"q":"Vorgang oder Zustand? „Das Geschäft wird um 9 Uhr geöffnet.“ (V/Z)","a":"V"},{"q":"Vorgang oder Zustand? „Das Geschäft ist bis 20 Uhr geöffnet.“ (V/Z)","a":"Z"},{"q":"Vergangenheit, irreal: Das ___ früher geprüft werden müssen.","a":"hätte"},{"q":"Fehler? „Die Rechnung muss bezahlt werden muss.“","a":"Die Rechnung muss bezahlt werden."}],"exam":[{"q":"Was muss erneuert werden?","a":"Das Dach."},{"q":"Wann sollen die Arbeiten abgeschlossen sein?","a":"Ende Juli."},{"q":"Wo müssen die Fahrräder abgestellt werden?","a":"Im Keller."},{"q":"Wann muss mit Lärm gerechnet werden?","a":"Werktags zwischen 7 und 17 Uhr."},{"q":"Bis wann soll man einen Termin vereinbaren?","a":"Bis zum 20. Mai."},{"q":"Werden die Kosten auf die Miete umgelegt?","a":"Nein."},{"q":"Passiv: Man muss die Mängel schnell beseitigen.","a":"Die Mängel müssen schnell beseitigt werden."},{"q":"Schreiben Sie eine Beschwerde an Ihre Hausverwaltung über eine kaputte Heizung (100 Wörter).","a":"","m":"Sehr geehrte Damen und Herren, seit einer Woche ist die Heizung in meiner Wohnung kaputt. Die Wohnung ist sehr kalt. Die Heizung muss dringend repariert werden. Ich habe schon zweimal angerufen, aber es ist nichts passiert. Bitte schicken Sie bis Freitag einen Techniker. Mit freundlichen Grüßen, Aiko Tanaka"},{"q":"Beschreiben Sie, was in Ihrer Wohnung renoviert werden müsste.","a":"","m":"In meiner Wohnung müsste das Bad renoviert werden. Die Fenster müssten ausgetauscht werden. Außerdem sollte die Küche neu gestrichen werden."},{"q":"Erklären Sie den Unterschied zwischen „Das Fenster wird geöffnet“ und „Das Fenster ist geöffnet“.","a":"","m":"„Das Fenster wird geöffnet“ beschreibt den Vorgang: Jemand öffnet es gerade. „Das Fenster ist geöffnet“ beschreibt den Zustand: Es ist offen."}],"speak":["Was muss in dieser Wohnung gemacht werden? __Die Wand muss … werden.__","Spielt ein Telefonat mit der Hausverwaltung: Ein Mangel muss behoben werden.","Was darf in deinem Haus nicht gemacht werden? Nenne Regeln.","Beschreibe den Zustand: __Die Fenster sind …, die Tür ist …__"],"dialog":[{"who":"Leila","de":"Guten Tag, hier ist Leila Ahmadi aus der Goethestraße 12. Ich rufe wegen der Feuchtigkeit in meinem Bad an."},{"who":"Herr Brandt","de":"Ja, Frau Ahmadi. Der Schaden ist uns bekannt. Er soll nach den Dacharbeiten behoben werden."},{"who":"Leila","de":"Das ist erst im August! An der Wand ist schon Schimmel. Das muss sofort geprüft werden."},{"who":"Herr Brandt","de":"Verstehe. Ich kann einen Handwerker schicken, aber der Termin kann frühestens nächste Woche vereinbart werden."},{"who":"Leila","de":"Gut. Und wenn der Schimmel bis dahin größer wird?"},{"who":"Herr Brandt","de":"Dann sollten Sie Fotos machen. Alles muss dokumentiert werden, falls später über eine Mietminderung gesprochen wird."},{"who":"Leila","de":"In Ordnung. Ich schicke Ihnen die Fotos heute noch per E-Mail."}],"dq":[{"q":"Warum ruft Leila an?","a":"Wegen der Feuchtigkeit (Schimmel) in ihrem Bad."},{"q":"Wann kann der Handwerkertermin frühestens sein?","a":"Nächste Woche."},{"q":"Was soll Leila tun?","a":"Fotos machen (alles dokumentieren) und sie per E-Mail schicken."}],"en":{"title":"Passive with modal verbs and the state passive","theme":"Building site and repairs","expl":["Passive with a modal verb: modal (position 2) + **participle + werden** (end): __Die Heizung muss repariert werden.__ = The heating must be repaired. In a subordinate clause the modal is the very last word: __…, weil die Heizung repariert werden muss.__","The **state passive** (sein + participle) describes the result, not the process: __Die Tür wird geöffnet__ (someone is opening it) vs. __Die Tür ist geöffnet__ (it is open)."],"use":""},"check":[{"re":"\\\\b(muss|müssen|soll|sollte|kann|könnte)\\\\b[^.!?]*\\\\b(ge\\\\w+(t|en)|\\\\w+iert) werden\\\\b|\\\\b(ist|sind) \\\\w*ge\\\\w+(t|en)\\\\b","label":"Passiv mit Modalverb (muss repariert werden) / Zustandspassiv"}]},{"n":63,"pos":53,"level":"B2","title":"Relativsätze mit wer, was, wo(r)- und Präposition","theme":"Wer wagt, gewinnt","scene":"party","rec":[33],"expl":["**wer** leitet einen Relativsatz ohne Bezugswort ein und bedeutet „jeder, der“: __Wer früh aufsteht, hat mehr vom Tag.__ Oft folgt im Hauptsatz **der**: __Wer zu spät kommt, den bestraft das Leben.__ Der Kasus von wer/der richtet sich nach dem jeweiligen Satz: __Wem die Arbeit gefällt, der bleibt.__","**was** steht nach **alles, etwas, nichts, vieles, das, das Einzige** und nach **Superlativen**: __Das ist alles, was ich weiß. Das ist das Beste, was mir passiert ist.__ Bezieht sich der Relativsatz auf den **ganzen Satz**, steht ebenfalls **was**: __Er hat die Prüfung bestanden, was mich sehr freut.__","Mit Präposition wird **was** zu **wo(r) + Präposition**: __Es gibt nichts, worüber ich mich mehr freue.__ __Er kam pünktlich, womit niemand gerechnet hatte.__ Für Orte steht **wo**, für Richtungen **wohin/woher**: __die Stadt, wo ich wohne; das Land, woher sie kommt__."],"use":"Prüfung B2, Schreiben und Sprechen: Meinungen begründen, Sprichwörter, Zusammenfassungen („…, was zeigt, dass …“).","table":[["Einleitung","Wann?","Beispiel"],["wer … (der)","„jeder, der“","**Wer** viel liest, **der** schreibt besser."],["was","nach alles, nichts, etwas, das Beste","Das ist **alles**, **was** ich habe."],["was","bezieht sich auf den ganzen Satz","Er kam zu spät, **was** mich ärgerte."],["wo(r) + Präp.","was mit Präposition","Das ist etwas, **worauf** ich mich freue."],["wo / wohin / woher","Ort / Richtung","die Stadt, **wo** ich geboren bin"]],"examples":[{"de":"Wer Deutsch lernen will, muss viel sprechen.","en":"Anyone who wants to learn German has to speak a lot."},{"de":"Wer nicht wagt, der nicht gewinnt.","en":"Nothing ventured, nothing gained."},{"de":"Wem das nicht gefällt, der kann gehen.","en":"Anyone who doesn\'t like it can leave."},{"de":"Wen du einlädst, ist deine Sache.","en":"Whom you invite is your business."},{"de":"Das ist alles, was ich dazu sagen kann.","en":"That\'s all I can say about it."},{"de":"Es gibt nichts, was sie nicht weiß.","en":"There\'s nothing she doesn\'t know."},{"de":"Das Beste, was du tun kannst, ist abwarten.","en":"The best thing you can do is wait."},{"de":"Er hat sich entschuldigt, was ich sehr fair finde.","en":"He apologised, which I think is very fair."},{"de":"Sie hat die Stelle bekommen, worüber sich alle freuen.","en":"She got the job, which everyone is happy about."},{"de":"Das ist etwas, woran ich mich nie gewöhnen werde.","en":"That\'s something I\'ll never get used to."},{"de":"Es regnete den ganzen Tag, weshalb wir zu Hause blieben.","en":"It rained all day, which is why we stayed at home."},{"de":"In der Stadt, wo ich aufgewachsen bin, gibt es kein Kino.","en":"In the town where I grew up there is no cinema."},{"de":"Das Land, woher meine Eltern kommen, ist sehr groß.","en":"The country my parents come from is very big."},{"de":"Vieles, was in der Zeitung steht, stimmt nicht.","en":"Much of what is in the paper isn\'t true."},{"de":"Das Einzige, was fehlt, ist die Unterschrift.","en":"The only thing missing is the signature."}],"vocab":[{"de":"das Sprichwort, ¨er","en":"proverb"},{"de":"wagen","en":"to dare"},{"de":"die Redewendung, -en","en":"idiom"},{"de":"aufgeben","en":"to give up"},{"de":"das Risiko, Risiken","en":"risk"},{"de":"der Mut","en":"courage"},{"de":"die Geduld","en":"patience"},{"de":"ernten","en":"to harvest, to reap"},{"de":"säen","en":"to sow"},{"de":"der Schein","en":"appearance"},{"de":"trügen","en":"to deceive"},{"de":"das Einzige","en":"the only thing"},{"de":"weshalb","en":"which is why"},{"de":"wodurch","en":"as a result of which"},{"de":"worüber","en":"about which"},{"de":"womit","en":"with which"},{"de":"woran","en":"on which, of which"},{"de":"die Erkenntnis, -se","en":"realisation"},{"de":"erstaunlich","en":"astonishing"},{"de":"bedauerlich","en":"regrettable"}],"reading":"Sprichwörter sind kleine Lebensweisheiten, die oft mit „wer“ oder „was“ beginnen. „Wer A sagt, muss auch B sagen“ bedeutet: Wer etwas anfängt, sollte es auch zu Ende bringen. „Was Hänschen nicht lernt, lernt Hans nimmermehr“ behauptet, dass man das, was man als Kind nicht lernt, als Erwachsener kaum noch lernen kann – eine These, die die moderne Forschung allerdings widerlegt hat. Viele Menschen lernen noch mit sechzig eine neue Sprache, was zeigt, dass das Gehirn ein Leben lang lernfähig bleibt. „Wer zuletzt lacht, lacht am besten“ tröstet alle, die zunächst verlieren. Und „Was du heute kannst besorgen, das verschiebe nicht auf morgen“ ist das, was Eltern ihren Kindern am liebsten sagen, wenn die Hausaufgaben warten. Interessant ist, dass manche Sprichwörter einander widersprechen: „Wer nicht wagt, der nicht gewinnt“ ermutigt zum Risiko, während „Vorsicht ist die Mutter der Porzellankiste“ genau das Gegenteil empfiehlt. Das Einzige, worauf man sich bei Sprichwörtern verlassen kann, ist also, dass es für jede Situation eines gibt. Für Deutschlernende sind sie trotzdem wertvoll: Wer sie im richtigen Moment verwendet, klingt sofort natürlicher, wodurch man im Gespräch oft Sympathie gewinnt.","tasks":[{"q":"___ zu spät kommt, muss draußen warten. (wer/was)","a":"Wer"},{"q":"Das ist alles, ___ ich weiß. (das/was)","a":"was"},{"q":"Es gibt nichts, ___ ich mehr hasse als Lügen.","a":"was"},{"q":"Das ist das Schönste, ___ ich je gesehen habe.","a":"was"},{"q":"Er hat bestanden, ___ mich sehr freut. (das/was)","a":"was"},{"q":"Es gibt etwas, ___ ich mich freue. (worauf/auf das)","a":"worauf"},{"q":"Das ist das Einzige, ___ ich mich erinnern kann. (woran/an was)","a":"woran"},{"q":"Die Stadt, ___ ich wohne, ist klein.","a":"wo"},{"q":"___ man vertraut, dem erzählt man alles. (wer im Dativ)","a":"Wem"},{"q":"Es regnete, ___ wir zu Hause blieben. (weshalb/was)","a":"weshalb"},{"q":"Verbinde: Er hat angerufen. Darüber habe ich mich gefreut.","a":"Er hat angerufen, worüber ich mich gefreut habe."},{"q":"Fehler? „Das ist alles, das ich habe.“","a":"Das ist alles, was ich habe."}],"exam":[{"q":"Was bedeutet „Wer A sagt, muss auch B sagen“?","a":"Wer etwas anfängt, sollte es auch zu Ende bringen."},{"q":"Welche These hat die Forschung widerlegt?","a":"Dass man als Erwachsener kaum noch lernen kann (Was Hänschen nicht lernt …)."},{"q":"Welche zwei Sprichwörter widersprechen einander?","a":"„Wer nicht wagt, der nicht gewinnt“ und „Vorsicht ist die Mutter der Porzellankiste“."},{"q":"Warum sind Sprichwörter für Lernende wertvoll?","a":"Man klingt natürlicher und gewinnt Sympathie."},{"q":"Ergänzen Sie: Das ist das Beste, ___ du tun kannst.","a":"was"},{"q":"Ergänzen Sie: ___ viel arbeitet, braucht Pausen.","a":"Wer"},{"q":"Verbinden Sie mit „was“: Sie kam pünktlich. Das hat mich überrascht.","a":"Sie kam pünktlich, was mich überrascht hat."},{"q":"Erklären Sie ein Sprichwort aus Ihrer Muttersprache auf Deutsch.","a":"","m":"In Hindi sagt man: „Ein Tropfen nach dem anderen füllt den Topf.“ Das bedeutet: Wer jeden Tag ein bisschen macht, erreicht viel."},{"q":"Welches deutsche Sprichwort gefällt Ihnen am besten? Warum?","a":"","m":"Mir gefällt „Wer rastet, der rostet“. Es bedeutet: Wer sich nicht bewegt, wird alt und schwach. Das ist etwas, woran ich oft denke."},{"q":"Schreiben Sie fünf Sätze über Ihr Leben mit „Das Beste, was …“, „Alles, was …“, „Wer …“.","a":"","m":"Das Beste, was mir passiert ist, war mein Umzug. Alles, was ich hier gelernt habe, hilft mir. Wer Deutsch lernt, braucht Geduld. Das ist etwas, worauf ich stolz bin. Vieles, was neu war, ist jetzt normal."}],"speak":["Erkläre einem Freund: __Wer …, der …__ – drei Lebensweisheiten.","Was ist das Beste, was dir dieses Jahr passiert ist?","Gibt es etwas, worauf du stolz bist? Worüber ärgerst du dich?","Diskutiert: Ist „Wer nicht wagt, der nicht gewinnt“ ein guter Rat?"],"dialog":[{"who":"Tomás","de":"Ich weiß nicht, ob ich mich für das Stipendium in Wien bewerben soll. Die Chancen sind klein."},{"who":"Aiko","de":"Wer sich nicht bewirbt, bekommt es garantiert nicht."},{"who":"Tomás","de":"Stimmt. Aber das ist alles, was ich gerade nicht brauche: noch eine Absage."},{"who":"Aiko","de":"Eine Absage ist nichts, wovor man Angst haben muss. Das Schlimmste, was passieren kann, ist ein Nein."},{"who":"Tomás","de":"Du hast recht. Und es gibt ja einiges, worauf ich stolz sein kann."},{"who":"Aiko","de":"Genau! Wer A sagt, muss auch B sagen – du hast doch schon alle Unterlagen."},{"who":"Tomás","de":"Okay, ich schicke sie heute Abend ab. Worüber ich mich wirklich freuen würde, wäre ein bisschen Glück."}],"dq":[{"q":"Wofür will sich Tomás bewerben?","a":"Für ein Stipendium in Wien."},{"q":"Was ist laut Aiko das Schlimmste, was passieren kann?","a":"Ein Nein (eine Absage)."},{"q":"Wann schickt Tomás die Unterlagen ab?","a":"Heute Abend."}],"en":{"title":"Relative clauses with wer, was and wo(r) + preposition","theme":"Who dares, wins","expl":["**wer** starts a relative clause without a noun and means \\"whoever / anyone who\\": __Wer früh aufsteht, hat mehr vom Tag.__","**was** follows alles, etwas, nichts, das, superlatives and whole sentences: __Das ist alles, was ich weiß.__ __Er kam pünktlich, was mich überraschte.__","With a preposition and was, use **wo(r)** + preposition: __Das ist etwas, worüber ich oft nachdenke.__"],"use":""},"check":[{"re":"\\\\b(wer|was|wo(r)?(an|auf|über|für|von|mit))\\\\b","label":"wer / was / wo(r)- + preposition"}]},{"n":64,"pos":54,"level":"B2","title":"Nomen, Verben und Adjektive mit festen Präpositionen","theme":"Engagement und Interessen","scene":"office","rec":[31],"expl":["Nicht nur Verben, auch **Nomen** und **Adjektive** haben feste Präpositionen, die man mitlernen muss: __die Angst **vor**, das Interesse **an**, stolz **auf**, zufrieden **mit**__. Oft passt die Präposition des Nomens zu der des Verbs: sich interessieren **für** → das Interesse **an** (!), sich freuen **über** → die Freude **über**.","Bei **auf, über, an, in, vor, unter** entscheidet die feste Verbindung den Kasus, nicht „wo/wohin“: __warten auf + Akk.__, __teilnehmen an + Dat.__, __Angst vor + Dat.__, __abhängig von + Dat.__ Lernen Sie deshalb immer: Präposition + Kasus.","Statt einer Sache kann ein ganzer Satz folgen. Dann steht ein **da(r)-Wort** als Platzhalter: __Ich bin stolz **darauf**, dass ich bestanden habe.__ __Sie hat Angst **davor**, allein zu reisen.__ In Fragen nach Sachen: **wo(r)- + Präposition** (Worauf? Wovor?), nach Personen: Präposition + **wen/wem** (Auf wen? Vor wem?)."],"use":"Prüfung B2: Präzise Formulierungen in Beschwerden, Bewerbungen und Diskussionen („Ich bin mit … nicht einverstanden.“).","table":[["Typ","Beispiel","Kasus"],["Verb","sich bewerben **um** eine Stelle","Akk."],["Verb","abhängen **von** dem Wetter","Dat."],["Nomen","die Angst **vor** der Prüfung","Dat."],["Nomen","die Bitte **um** Hilfe","Akk."],["Adjektiv","stolz **auf** den Erfolg","Akk."],["Adjektiv","zufrieden **mit** dem Ergebnis","Dat."],["Adjektiv","verantwortlich **für** das Projekt","Akk."]],"examples":[{"de":"Sie hat großes Interesse an Politik.","en":"She has a great interest in politics."},{"de":"Ich habe keine Lust auf Streit.","en":"I\'m not in the mood for an argument."},{"de":"Er ist sehr stolz auf seine Tochter.","en":"He is very proud of his daughter."},{"de":"Wir sind mit dem Service nicht zufrieden.","en":"We are not satisfied with the service."},{"de":"Die Angst vor Fehlern blockiert viele Lernende.","en":"The fear of mistakes blocks many learners."},{"de":"Sie ist für die Organisation verantwortlich.","en":"She is responsible for the organisation."},{"de":"Der Erfolg hängt von vielen Faktoren ab.","en":"The success depends on many factors."},{"de":"Ich bin davon überzeugt, dass wir es schaffen.","en":"I\'m convinced that we\'ll manage it."},{"de":"Er hat sich um die Stelle beworben.","en":"He applied for the job."},{"de":"Die Kinder sind neugierig auf das Geschenk.","en":"The children are curious about the present."},{"de":"Sie ist mit einem Arzt verheiratet.","en":"She is married to a doctor."},{"de":"Bist du an einem Praktikum interessiert?","en":"Are you interested in an internship?"},{"de":"Ich bin dir sehr dankbar für deine Hilfe.","en":"I\'m very grateful to you for your help."},{"de":"Wir haben uns über die Kosten informiert.","en":"We found out about the costs."},{"de":"Worauf bist du am meisten stolz?","en":"What are you most proud of?"}],"vocab":[{"de":"das Interesse an (+ Dat.)","en":"interest in"},{"de":"die Angst vor (+ Dat.)","en":"fear of"},{"de":"die Freude über (+ Akk.)","en":"joy about"},{"de":"die Bitte um (+ Akk.)","en":"request for"},{"de":"die Lust auf (+ Akk.)","en":"desire for, fancy"},{"de":"der Wunsch nach (+ Dat.)","en":"wish for"},{"de":"die Sorge um (+ Akk.)","en":"worry about"},{"de":"die Kritik an (+ Dat.)","en":"criticism of"},{"de":"die Teilnahme an (+ Dat.)","en":"participation in"},{"de":"die Voraussetzung für (+ Akk.)","en":"requirement for"},{"de":"stolz auf (+ Akk.)","en":"proud of"},{"de":"zufrieden mit (+ Dat.)","en":"satisfied with"},{"de":"abhängig von (+ Dat.)","en":"dependent on"},{"de":"verantwortlich für (+ Akk.)","en":"responsible for"},{"de":"interessiert an (+ Dat.)","en":"interested in"},{"de":"neugierig auf (+ Akk.)","en":"curious about"},{"de":"dankbar für (+ Akk.)","en":"grateful for"},{"de":"überzeugt von (+ Dat.)","en":"convinced of"},{"de":"enttäuscht von (+ Dat.)","en":"disappointed by"},{"de":"bekannt für (+ Akk.)","en":"known for"}],"reading":"Ehrenamt in Deutschland: Fast jeder dritte Mensch in Deutschland engagiert sich freiwillig – im Sportverein, bei der Feuerwehr, in der Flüchtlingshilfe oder in der Nachbarschaft. Was motiviert die Menschen dazu? Eine Befragung zeigt: Die meisten haben Freude an der Arbeit mit anderen Menschen und den Wunsch nach einer sinnvollen Aufgabe. Viele sind stolz darauf, etwas für die Gesellschaft zu tun. Für jüngere Freiwillige ist außerdem die Möglichkeit wichtig, Erfahrungen zu sammeln, die für die spätere Bewerbung nützlich sind. Trotzdem klagen viele Vereine über einen Mangel an Nachwuchs. Junge Leute haben zwar Interesse an einem Engagement, aber häufig keine Lust auf feste Verpflichtungen über Jahre. Die Bereitschaft zu kurzen Projekten ist dagegen groß. Viele Organisationen haben sich darauf eingestellt und bieten flexible Einsätze an, etwa einen Nachmittag pro Monat. Ein weiteres Problem ist die Bürokratie: Ehrenamtliche Vorstände sind für Finanzen, Versicherungen und Datenschutz verantwortlich, und viele sind von der Menge an Formularen enttäuscht. Fachleute fordern deshalb mehr Unterstützung durch den Staat. Wer selbst aktiv werden möchte, kann sich bei den Freiwilligenagenturen der Städte über Angebote informieren.","tasks":[{"q":"Sie hat Angst ___ Hunden.","a":"vor"},{"q":"Ich habe großes Interesse ___ Kunst.","a":"an"},{"q":"Er ist stolz ___ seine Arbeit.","a":"auf"},{"q":"Wir sind ___ dem Hotel zufrieden.","a":"mit"},{"q":"Das hängt ___ Wetter ab.","a":"vom"},{"q":"Sie ist ___ das Projekt verantwortlich.","a":"für"},{"q":"Ich habe keine Lust ___ Kino.","a":"auf"},{"q":"da-Wort: Ich bin stolz ___, dass ich bestanden habe.","a":"darauf"},{"q":"da-Wort: Er hat Angst ___, allein zu fliegen.","a":"davor"},{"q":"Frage (Sache): ___ bist du zufrieden? – Mit dem Ergebnis.","a":"Womit"},{"q":"Frage (Person): ___ ___ bist du verheiratet? – Mit Jonas.","a":"Mit wem"},{"q":"Fehler? „Ich habe Interesse für Musik.“","a":"Ich habe Interesse an Musik."}],"exam":[{"q":"Wie viele Menschen engagieren sich in Deutschland freiwillig?","a":"Fast jeder Dritte."},{"q":"Was motiviert die meisten Freiwilligen?","a":"Freude an der Arbeit mit Menschen und der Wunsch nach einer sinnvollen Aufgabe."},{"q":"Worüber klagen viele Vereine?","a":"Über einen Mangel an Nachwuchs."},{"q":"Was haben junge Leute oft nicht?","a":"Lust auf feste Verpflichtungen über Jahre."},{"q":"Wofür sind ehrenamtliche Vorstände verantwortlich?","a":"Für Finanzen, Versicherungen und Datenschutz."},{"q":"Ergänzen Sie: Ich bin ___ dem Ergebnis enttäuscht.","a":"von"},{"q":"Ergänzen Sie: Er hat sich ___ die Stelle beworben.","a":"um"},{"q":"Worauf sind Sie in Ihrem Leben stolz? (5 Sätze)","a":"","m":"Ich bin stolz auf meine Familie. Ich bin auch stolz auf mein Studium. Besonders stolz bin ich darauf, dass ich in Deutschland arbeite. Ich bin zufrieden mit meinem Deutsch. Ich bin dankbar für meine Freunde."},{"q":"Würden Sie sich ehrenamtlich engagieren? Wofür und warum?","a":"","m":"Ja, ich würde mich gern für Kinder engagieren. Ich habe großes Interesse an Bildung, deshalb würde ich bei Hausaufgaben helfen."},{"q":"Schreiben Sie eine kurze Bewerbung für ein Ehrenamt.","a":"","m":"Sehr geehrte Damen und Herren, ich interessiere mich für Ihr Projekt und möchte mich als Lesepate engagieren. Ich habe Erfahrung mit Kindern und Freude an Sprachen. Mit freundlichen Grüßen"}],"speak":["Wofür interessierst du dich? Wovor hast du Angst? Worauf freust du dich?","Erzähl von einem Ehrenamt, das du kennst.","Wovon hängt deine Zufriedenheit im Job ab?","Spielt ein Gespräch: Bewerbung als Freiwilliger."],"dialog":[{"who":"Herr Vogel","de":"Schön, dass Sie Interesse an der Hausaufgabenhilfe haben, Herr Sharma. Was ist Ihre Motivation?"},{"who":"Ravi","de":"Ich bin sehr dankbar für die Hilfe, die ich selbst bekommen habe, als ich nach Deutschland kam. Davon möchte ich etwas zurückgeben."},{"who":"Herr Vogel","de":"Wie viel Zeit hätten Sie?"},{"who":"Ravi","de":"Das hängt von meinen Projekten ab. Ein Nachmittag pro Woche wäre realistisch."},{"who":"Herr Vogel","de":"Das reicht völlig. Haben Sie Erfahrung mit Kindern?"},{"who":"Ravi","de":"Mit meinem Neffen. Und ich bin davon überzeugt, dass ich gut erklären kann, vor allem Mathe."},{"who":"Herr Vogel","de":"Wunderbar. Wir suchen genau jemanden, der für Mathe verantwortlich ist."}],"dq":[{"q":"Woran hat Ravi Interesse?","a":"An der Hausaufgabenhilfe."},{"q":"Wovon hängt seine Zeit ab?","a":"Von seinen Projekten."},{"q":"Wofür soll Ravi verantwortlich sein?","a":"Für Mathe."}],"en":{"title":"Nouns, verbs and adjectives with fixed prepositions","theme":"Commitment and interests","expl":["Not only verbs but also nouns and adjectives have fixed prepositions you have to learn with them: __die Angst vor (fear of), das Interesse an (interest in), stolz auf (proud of), zufrieden mit (satisfied with)__.","The noun often – but not always – has the same preposition as the verb: sich freuen über → __die Freude über__, but sich interessieren für → __das Interesse an__ (!)."],"use":""},"check":[{"re":"\\\\b(stolz auf|interesse an|angst vor|zufrieden mit|engagieren für|freude über|bereit zu|verantwortlich für|abhängig von)\\\\b","label":"fixed prepositions (stolz auf, zufrieden mit …)"}]},{"n":65,"pos":55,"level":"B2","title":"Formelle Briefe und E-Mails: Anfrage, Beschwerde, Bitte","theme":"Schriftverkehr","scene":"office","rec":[45,48],"expl":["Formelle Texte haben feste Teile: **Betreff** (ohne „Betreff:“ im Text, kurz und konkret), **Anrede** (__Sehr geehrte Frau Lange,__ / __Sehr geehrte Damen und Herren,__), **Einleitung** mit dem Anlass, **Hauptteil**, **Bitte oder Forderung**, **Schluss** (__Mit freundlichen Grüßen__, ohne Komma danach). Nach der Anrede mit Komma geht es **klein** weiter.","Typische Formulierungen: Anlass – __ich wende mich an Sie, weil …__, __mit Bezug auf Ihr Schreiben vom …__; Anfrage – __ich würde gern wissen, ob …__, __könnten Sie mir bitte mitteilen, …__; Beschwerde – __leider muss ich Ihnen mitteilen, dass …__, __ich erwarte, dass …__, __ich bitte Sie, den Betrag bis zum … zu erstatten__.","Der Ton bleibt auch bei Ärger **sachlich**: Fakten (Datum, Nummer, Betrag), dann die Folge, dann eine klare, erfüllbare Forderung mit Frist. Konjunktiv II macht Bitten höflich (__Ich wäre Ihnen dankbar, wenn …__), Nominalstil macht Texte offiziell (__nach Erhalt der Ware__)."],"use":"Prüfung B2 Schreiben Teil 2 (telc/Goethe): formelle E-Mail mit vier Inhaltspunkten, ca. 150 Wörter.","table":[["Teil","Neutral","Formell"],["Anrede","Hallo Frau Lange,","Sehr geehrte Frau Lange,"],["Anlass","Ich schreibe wegen …","Ich wende mich an Sie, da …"],["Bitte","Können Sie …?","Ich wäre Ihnen dankbar, wenn Sie … könnten."],["Beschwerde","Das finde ich nicht gut.","Leider entspricht dies nicht der vereinbarten Leistung."],["Forderung","Bitte zahlen Sie zurück.","Ich bitte Sie, mir den Betrag bis zum … zu erstatten."],["Schluss","Viele Grüße","Mit freundlichen Grüßen"]],"examples":[{"de":"Sehr geehrte Damen und Herren, ich wende mich an Sie, weil meine Bestellung nicht angekommen ist.","en":"Dear Sir or Madam, I am writing to you because my order has not arrived."},{"de":"Mit Bezug auf Ihr Schreiben vom 3. Mai möchte ich Folgendes klarstellen.","en":"With reference to your letter of 3 May, I would like to clarify the following."},{"de":"Ich würde gern wissen, ob der Kurs noch freie Plätze hat.","en":"I would like to know whether the course still has places available."},{"de":"Könnten Sie mir bitte mitteilen, bis wann ich mich anmelden muss?","en":"Could you please tell me by when I have to register?"},{"de":"Leider muss ich Ihnen mitteilen, dass das Gerät defekt ist.","en":"Unfortunately I have to inform you that the device is faulty."},{"de":"Ich wäre Ihnen dankbar, wenn Sie mir die Unterlagen zuschicken könnten.","en":"I would be grateful if you could send me the documents."},{"de":"Ich bitte Sie, mir den Betrag bis zum 15. Juni zu erstatten.","en":"I ask you to refund the amount to me by 15 June."},{"de":"Andernfalls sehe ich mich gezwungen, rechtliche Schritte einzuleiten.","en":"Otherwise I shall be forced to take legal action."},{"de":"Im Anhang finden Sie eine Kopie der Rechnung.","en":"Please find attached a copy of the invoice."},{"de":"Für Rückfragen stehe ich Ihnen gern zur Verfügung.","en":"I am happy to answer any further questions."},{"de":"Vielen Dank im Voraus für Ihre Bemühungen.","en":"Thank you in advance for your efforts."},{"de":"Ich freue mich auf Ihre Antwort.","en":"I look forward to your reply."},{"de":"Mit freundlichen Grüßen","en":"Yours sincerely"},{"de":"Bitte entschuldigen Sie die verspätete Antwort.","en":"Please excuse the late reply."},{"de":"Wie telefonisch besprochen, sende ich Ihnen den Vertrag.","en":"As discussed on the phone, I am sending you the contract."}],"vocab":[{"de":"der Betreff, -e","en":"subject line"},{"de":"die Anrede, -n","en":"salutation"},{"de":"der Anhang, ¨e","en":"attachment"},{"de":"die Bestellnummer, -n","en":"order number"},{"de":"die Kundennummer, -n","en":"customer number"},{"de":"die Rückerstattung, -en","en":"refund"},{"de":"erstatten","en":"to refund"},{"de":"die Gutschrift, -en","en":"credit note"},{"de":"die Mahnung, -en","en":"reminder (payment)"},{"de":"die Frist setzen","en":"to set a deadline"},{"de":"rechtliche Schritte","en":"legal action"},{"de":"die Rückfrage, -n","en":"query"},{"de":"umgehend","en":"promptly"},{"de":"bedauerlicherweise","en":"regrettably"},{"de":"entsprechen (+ Dat.)","en":"to correspond to"},{"de":"ausstehend","en":"outstanding"},{"de":"bestätigen","en":"to confirm"},{"de":"die Bemühung, -en","en":"effort"},{"de":"im Voraus","en":"in advance"},{"de":"zur Kenntnis nehmen","en":"to take note of"}],"reading":"Betreff: Beschwerde über Sprachkurs „Deutsch B2 intensiv“ – Rückerstattung der Kursgebühr Sehr geehrte Damen und Herren, ich wende mich an Sie, da der oben genannte Kurs, für den ich mich am 2. September angemeldet und die Gebühr von 480 Euro überwiesen habe, nicht der Beschreibung auf Ihrer Webseite entspricht. Laut Ihrer Ausschreibung sollten maximal zwölf Teilnehmende in einer Gruppe lernen. Tatsächlich waren wir jedoch von Anfang an 19 Personen, sodass kaum Gelegenheit zum Sprechen bestand. Darüber hinaus fiel der Unterricht an drei von zwölf Terminen ohne Ersatz aus, da keine Vertretung für die erkrankte Lehrkraft gefunden werden konnte. Die versprochenen Prüfungssimulationen haben gar nicht stattgefunden. Ich habe diese Mängel bereits am 30. September mündlich im Sekretariat angesprochen, bisher jedoch keine Reaktion erhalten. Ich bitte Sie daher, mir einen angemessenen Teil der Kursgebühr, mindestens jedoch die Kosten für die drei ausgefallenen Termine in Höhe von 120 Euro, bis zum 31. Oktober auf das Ihnen bekannte Konto zu erstatten. Alternativ wäre ich auch mit einem kostenlosen Platz in einem Folgekurs einverstanden, sofern die Gruppengröße eingehalten wird. Eine Kopie der Anmeldebestätigung sowie der Überweisung finden Sie im Anhang. Für Rückfragen stehe ich Ihnen gern zur Verfügung. Mit freundlichen Grüßen Aiko Tanaka","tasks":[{"q":"Formelle Anrede (Name unbekannt): Sehr geehrte ___ und ___,","a":"Damen / Herren"},{"q":"Formelle Anrede: ___ ___ Frau Lange,","a":"Sehr geehrte"},{"q":"Schlussformel: Mit freundlichen ___","a":"Grüßen"},{"q":"Anlass: Ich ___ mich an Sie, weil … (wenden)","a":"wende"},{"q":"Bitte höflich: Ich wäre Ihnen ___, wenn Sie mir helfen könnten.","a":"dankbar"},{"q":"Anhang: Im ___ finden Sie die Rechnung.","a":"Anhang"},{"q":"Bezug: Mit ___ auf Ihr Schreiben vom 3. Mai …","a":"Bezug"},{"q":"Forderung: Ich bitte Sie, den Betrag bis Freitag ___ ___. (erstatten)","a":"zu erstatten"},{"q":"Formeller: „Können Sie mir sagen, …?“ → ___ Sie mir bitte mitteilen, …?","a":"Könnten"},{"q":"Register: „Das war eine Katastrophe.“ → sachlich: Das entsprach leider nicht der ___.","a":"Beschreibung"},{"q":"Nach der Anrede mit Komma schreibt man ___ weiter. (groß/klein)","a":"klein"},{"q":"Fehler? „Sehr geehrte Herr Müller,“","a":"Sehr geehrter Herr Müller,"}],"exam":[{"q":"Wofür hat sich Aiko angemeldet?","a":"Für den Kurs „Deutsch B2 intensiv“."},{"q":"Wie viele Teilnehmende waren versprochen, wie viele waren es?","a":"Maximal zwölf; es waren 19."},{"q":"Wie oft ist der Unterricht ausgefallen?","a":"An drei von zwölf Terminen."},{"q":"Wie viel Geld fordert Aiko mindestens zurück?","a":"120 Euro."},{"q":"Welche Alternative bietet sie an?","a":"Einen kostenlosen Platz in einem Folgekurs (mit eingehaltener Gruppengröße)."},{"q":"Was liegt der E-Mail bei?","a":"Eine Kopie der Anmeldebestätigung und der Überweisung."},{"q":"Formulieren Sie formell: „Schicken Sie mir das Formular!“","a":"Ich wäre Ihnen dankbar, wenn Sie mir das Formular schicken könnten."},{"q":"Schreiben Sie eine Anfrage an eine Sprachschule (Preis, Termine, Prüfung, Gruppengröße).","a":"","m":"Sehr geehrte Damen und Herren, ich interessiere mich für einen B2-Kurs an Ihrer Sprachschule. Könnten Sie mir bitte mitteilen, was der Kurs kostet und wann er beginnt? Außerdem würde ich gern wissen, ob man am Ende eine Prüfung machen kann und wie groß die Gruppen sind. Mit freundlichen Grüßen, Ravi Sharma"},{"q":"Schreiben Sie eine Beschwerde über eine verspätete Lieferung (ca. 150 Wörter).","a":"","m":"Sehr geehrte Damen und Herren, am 3. Oktober habe ich bei Ihnen einen Schreibtisch bestellt. Die Lieferung war für den 10. Oktober angekündigt. Leider habe ich den Tisch bis heute nicht erhalten. Ich habe zweimal angerufen, aber niemand konnte mir helfen. Ich bitte Sie, den Tisch bis spätestens Freitag zu liefern. Andernfalls trete ich vom Vertrag zurück. Mit freundlichen Grüßen, Aiko Tanaka"},{"q":"Antworten Sie als Firma auf Aikos Beschwerde.","a":"","m":"Sehr geehrte Frau Tanaka, vielen Dank für Ihre Nachricht. Wir bitten um Entschuldigung für die Verspätung. Ihr Schreibtisch wird am Donnerstag geliefert. Als kleine Entschädigung erhalten Sie einen Gutschein über 20 Euro. Mit freundlichen Grüßen, Ihr Kundenservice"}],"speak":["Ruf bei einer Firma an und beschwere dich höflich, aber bestimmt.","Formuliere drei Bitten formell und neutral.","Was gehört in jede formelle E-Mail? Erkläre es einem Freund.","Spielt: Kundenservice und verärgerter Kunde – findet eine Lösung."],"dialog":[{"who":"Aiko","de":"Leila, kannst du meine Beschwerde lesen? Ich will nicht zu unhöflich klingen."},{"who":"Leila","de":"Klar. Der Anfang ist gut: Du nennst Datum, Kurs und Betrag. Das ist wichtig."},{"who":"Aiko","de":"Und hier habe ich geschrieben: „Das war eine Katastrophe.“"},{"who":"Leila","de":"Das würde ich streichen. Schreib lieber sachlich: „Der Kurs entsprach nicht der Beschreibung.“"},{"who":"Aiko","de":"Okay. Soll ich eine Frist setzen?"},{"who":"Leila","de":"Ja, unbedingt, aber eine realistische. Zwei Wochen sind üblich. Und biete eine Alternative an, das wirkt kooperativ."},{"who":"Aiko","de":"Gut. Und am Ende „Mit freundlichen Grüßen“ mit Komma?"},{"who":"Leila","de":"Nein, ohne Komma. Und darunter nur dein Name."}],"dq":[{"q":"Was findet Leila am Anfang gut?","a":"Aiko nennt Datum, Kurs und Betrag."},{"q":"Was soll Aiko statt „Das war eine Katastrophe“ schreiben?","a":"„Der Kurs entsprach nicht der Beschreibung.“"},{"q":"Wie lange ist eine übliche Frist?","a":"Zwei Wochen."}],"en":{"title":"Formal letters and emails: enquiry, complaint, request","theme":"Correspondence","expl":["Formal texts have fixed parts: subject line (short and specific), greeting (__Sehr geehrte Frau Lange,__ / __Sehr geehrte Damen und Herren,__), introduction with the reason for writing, main part, request or demand, closing (__Mit freundlichen Grüßen__ – no comma after it).","After the greeting and its comma, the first word continues in **lower case** (unless it\'s a noun or Sie). Use Sie and indirect, polite forms: __Ich wäre Ihnen dankbar, wenn …__"],"use":""},"check":[{"re":"\\\\b(sehr geehrte|mit freundlichen grüßen|ich würde mich freuen|ich wäre ihnen dankbar|bitte|könnten sie)\\\\b","label":"formal letter phrases (Sehr geehrte …, Mit freundlichen Grüßen)"}]},{"n":66,"pos":56,"level":"B2","title":"Konnektoren für Zeit, Art und Weise: indem, wobei, solange, sobald, kaum","theme":"Prozesse beschreiben","scene":"classroom","rec":[34,47],"expl":["**indem** beschreibt das **Mittel**: __Man lernt Wörter, indem man sie oft wiederholt.__ (Frage: Wie?) **dadurch, dass** betont dasselbe stärker: __Dadurch, dass er jeden Tag liest, hat er seinen Wortschatz vergrößert.__","**wobei** fügt einen begleitenden Umstand oder eine Einschränkung hinzu: __Die Preise steigen, wobei Lebensmittel besonders betroffen sind.__ **solange** bedeutet „während der ganzen Zeit“ oder „unter der Bedingung“: __Solange du Fieber hast, bleibst du zu Hause.__ **sobald** = „direkt, wenn“: __Sobald ich Bescheid weiß, melde ich mich.__","**kaum dass** / **kaum … (als)** zeigt, dass etwas sofort danach passiert: __Kaum war er zu Hause, klingelte das Telefon.__ **sooft** = „jedes Mal, wenn“: __Sooft ich ihn besuche, kocht er für mich.__ Alle sind Subjunktionen: Das Verb steht am **Ende** des Nebensatzes."],"use":"Prüfung B2: Abläufe, Methoden und Bedingungen beschreiben, Grafiken kommentieren, Ratschläge begründen.","table":[["Konnektor","Bedeutung","Beispiel"],["indem","Mittel (wie?)","Er spart Geld, **indem** er selbst kocht."],["dadurch, dass","Mittel (betont)","**Dadurch, dass** er selbst kocht, spart er Geld."],["wobei","Begleitumstand / Einschränkung","Wir kamen an, **wobei** es schon dunkel war."],["solange","Dauer / Bedingung","**Solange** es regnet, bleiben wir drin."],["sobald","sofort danach","**Sobald** ich ankomme, rufe ich an."],["sooft","jedes Mal, wenn","**Sooft** sie kommt, bringt sie Blumen mit."]],"examples":[{"de":"Man kann Strom sparen, indem man Geräte ganz ausschaltet.","en":"You can save electricity by switching devices off completely."},{"de":"Indem sie jeden Tag Podcasts hört, verbessert sie ihr Hörverstehen.","en":"By listening to podcasts every day, she improves her listening."},{"de":"Dadurch, dass die Bahn streikte, kamen viele zu spät.","en":"Because the railway was on strike, many arrived late."},{"de":"Die Mieten steigen, wobei die Unterschiede zwischen den Städten groß sind.","en":"Rents are rising, although the differences between cities are large."},{"de":"Er erzählte von seiner Reise, wobei er viele Fotos zeigte.","en":"He talked about his trip, showing lots of photos as he did so."},{"de":"Solange du hier wohnst, gelten meine Regeln.","en":"As long as you live here, my rules apply."},{"de":"Solange die Ampel rot ist, darfst du nicht gehen.","en":"As long as the light is red, you mustn\'t go."},{"de":"Sobald die Ergebnisse da sind, informieren wir Sie.","en":"As soon as the results are in, we\'ll inform you."},{"de":"Kaum hatte das Konzert begonnen, fiel der Strom aus.","en":"The concert had hardly begun when the power went out."},{"de":"Sooft ich Oma besuche, backt sie Kuchen.","en":"Whenever I visit Grandma, she bakes cake."},{"de":"Er verbesserte seine Aussprache, indem er Sätze nachsprach.","en":"He improved his pronunciation by repeating sentences."},{"de":"Wir können morgen wandern, sofern es nicht regnet.","en":"We can go hiking tomorrow, provided it doesn\'t rain."},{"de":"Sobald du fertig bist, können wir gehen.","en":"As soon as you\'re ready, we can go."},{"de":"Die Lösung ist einfach, wobei sie natürlich Geld kostet.","en":"The solution is simple, although it costs money, of course."},{"de":"Je nachdem, wie das Wetter ist, grillen wir oder gehen essen.","en":"Depending on the weather, we\'ll barbecue or go out to eat."}],"vocab":[{"de":"das Verfahren, -","en":"procedure, method"},{"de":"der Ablauf, ¨e","en":"sequence, process"},{"de":"der Schritt, -e","en":"step"},{"de":"die Methode, -n","en":"method"},{"de":"die Vorgehensweise, -n","en":"approach"},{"de":"wiederholen","en":"to repeat"},{"de":"verbessern","en":"to improve"},{"de":"die Effizienz","en":"efficiency"},{"de":"der Aufwand","en":"effort"},{"de":"sparen","en":"to save"},{"de":"der Verbrauch","en":"consumption"},{"de":"senken","en":"to lower"},{"de":"ausschalten","en":"to switch off"},{"de":"der Standby-Modus","en":"standby mode"},{"de":"die Dauer","en":"duration"},{"de":"die Bedingung, -en","en":"condition"},{"de":"gelten","en":"to apply, to be valid"},{"de":"unmittelbar","en":"immediately"},{"de":"gleichzeitig","en":"at the same time"},{"de":"anschließend","en":"subsequently"}],"reading":"Wie lernt man am effizientesten Vokabeln? Die Gedächtnisforschung hat darauf einige klare Antworten. Am wirksamsten ist das sogenannte verteilte Wiederholen: Man festigt ein neues Wort, indem man es nicht zehnmal an einem Abend, sondern über mehrere Tage verteilt wiederholt, wobei die Abstände immer größer werden. Sobald man ein Wort sicher kennt, kann man es länger ruhen lassen; solange man unsicher ist, sollte es öfter wiederkommen. Genau nach diesem Prinzip arbeiten digitale Karteikarten. Ein zweiter Faktor ist das aktive Abrufen. Dadurch, dass man versucht, sich an das Wort zu erinnern, bevor man die Lösung sieht, wird die Erinnerung stärker als durch bloßes Lesen. Wer also eine Karte umdreht, ohne vorher nachzudenken, verschenkt einen großen Teil des Lerneffekts. Drittens hilft Kontext: Man behält Wörter besser, indem man sie in ganzen Sätzen lernt, wobei persönliche Beispiele besonders gut funktionieren. „Ich habe Angst vor Spinnen“ bleibt länger im Kopf als die Übersetzung „Angst = fear“. Und schließlich spielt der Schlaf eine Rolle: Sooft man kurz vor dem Schlafen wiederholt, profitiert man von der nächtlichen Verarbeitung im Gehirn. Kaum hat man diese Methoden ein paar Wochen ausprobiert, merkt man den Unterschied.","tasks":[{"q":"Man lernt eine Sprache, ___ man sie spricht. (indem/wobei)","a":"indem"},{"q":"___ du Fieber hast, bleibst du im Bett. (solange/sobald)","a":"Solange"},{"q":"___ ich zu Hause bin, rufe ich dich an. (sobald/solange)","a":"Sobald"},{"q":"Wir fuhren los, ___ es schon dunkel war. (wobei/indem)","a":"wobei"},{"q":"___ ich ihn sehe, lacht er. (sooft/sobald)","a":"Sooft"},{"q":"Kaum ___ er eingeschlafen, klingelte der Wecker. (war/hatte)","a":"war"},{"q":"Verbinde mit indem: Er spart Geld. Er fährt mit dem Rad.","a":"Er spart Geld, indem er mit dem Rad fährt."},{"q":"Verbinde mit dadurch, dass: Sie trainiert täglich. Sie ist fit geworden.","a":"Dadurch, dass sie täglich trainiert, ist sie fit geworden."},{"q":"Verbinde mit sobald: Der Film ist zu Ende. Wir gehen essen.","a":"Sobald der Film zu Ende ist, gehen wir essen."},{"q":"Frage nach dem Mittel: ___ kann man Energie sparen? – Indem man das Licht ausmacht.","a":"Wie"},{"q":"Satzstellung: Ich melde mich, sobald ich mehr ___. (wissen)","a":"weiß"},{"q":"Fehler? „Er hat abgenommen, indem er hat Sport gemacht.“","a":"Er hat abgenommen, indem er Sport gemacht hat."}],"exam":[{"q":"Was ist verteiltes Wiederholen?","a":"Wörter über mehrere Tage mit immer größeren Abständen wiederholen."},{"q":"Wann sollte ein Wort öfter wiederkommen?","a":"Solange man unsicher ist."},{"q":"Warum ist aktives Abrufen wichtig?","a":"Dadurch wird die Erinnerung stärker als durch bloßes Lesen."},{"q":"Welche Sätze bleiben besonders gut im Kopf?","a":"Persönliche Beispielsätze."},{"q":"Welche Rolle spielt der Schlaf?","a":"Wiederholen vor dem Schlafen nutzt die nächtliche Verarbeitung."},{"q":"Verbinden Sie mit indem: Sie lernt Wörter. Sie schreibt sie auf Karten.","a":"Sie lernt Wörter, indem sie sie auf Karten schreibt."},{"q":"Ergänzen Sie: ___ der Zug ankommt, steigen wir aus.","a":"Sobald"},{"q":"Wie lernen Sie Vokabeln? Beschreiben Sie Ihre Methode mit indem, sobald und solange.","a":"","m":"Ich lerne Vokabeln, indem ich sie auf Karten schreibe. Sobald ich ein neues Wort höre, notiere ich es. Solange ich ein Wort nicht sicher kann, wiederhole ich es jeden Tag."},{"q":"Beschreiben Sie, wie man in Deutschland eine Wohnung findet (Schritt für Schritt).","a":"","m":"Zuerst sucht man im Internet, wobei man schnell reagieren muss. Sobald man eine Anzeige findet, schreibt man eine Nachricht. Dann besichtigt man die Wohnung. Man unterschreibt den Vertrag, sobald alles klar ist."},{"q":"Geben Sie Tipps zum Energiesparen mit „indem“ und „dadurch, dass“.","a":"","m":"Man spart Energie, indem man kürzer duscht. Dadurch, dass man die Heizung nachts herunterdreht, sinken die Kosten. Man spart auch Strom, indem man Geräte ganz ausschaltet."}],"speak":["Wie kann man gesund bleiben? Antworte mit __indem …__","Was machst du, sobald du nach Hause kommst?","Erkläre einen Ablauf (Kaffee kochen, Wäsche waschen) mit Konnektoren.","Solange …, …: Nenne drei Regeln aus deiner Familie."],"dialog":[{"who":"Paul","de":"Mama, wie kann ich mir die Englischvokabeln besser merken?"},{"who":"Anna","de":"Indem du sie jeden Tag ein bisschen wiederholst, nicht alles am Abend vor dem Test."},{"who":"Paul","de":"Aber das dauert so lange!"},{"who":"Anna","de":"Nur fünf Minuten am Tag. Sobald du ein Wort dreimal richtig hattest, kommt es seltener."},{"who":"Paul","de":"Und wenn ich es vergesse?"},{"who":"Anna","de":"Dann kommt es wieder öfter dran. Solange du es nicht sicher kannst, übst du es eben weiter."},{"who":"Paul","de":"Okay. Kann ich das mit der App machen?"},{"who":"Anna","de":"Klar, wobei du die Antwort immer erst laut sagen solltest, bevor du die Karte umdrehst."}],"dq":[{"q":"Wie soll Paul Vokabeln lernen?","a":"Indem er sie jeden Tag ein bisschen wiederholt."},{"q":"Wann kommt ein Wort seltener?","a":"Sobald er es dreimal richtig hatte."},{"q":"Was soll er vor dem Umdrehen der Karte tun?","a":"Die Antwort laut sagen."}],"en":{"title":"Connectors for time and manner: indem, wobei, solange, sobald, kaum","theme":"Describing processes","expl":["**indem** = by (doing): __Man lernt Wörter, indem man sie oft wiederholt.__ **dadurch, dass** says the same more strongly.","**wobei** adds an accompanying detail or a restriction (whereby, although). **solange** = as long as, **sobald** = as soon as: __Sobald ich ankomme, rufe ich an.__ **kaum** = hardly / no sooner … than: __Kaum war er da, ging es los.__"],"use":""},"check":[{"re":"\\\\b(indem|wobei|solange|sobald|kaum|dadurch, dass)\\\\b","label":"indem, sobald, solange, dadurch, dass"}]},{"n":67,"pos":57,"level":"B2","title":"Diskutieren: Meinung, Zustimmung, Widerspruch, Kompromiss","theme":"Stadt der Zukunft","scene":"city","rec":[42,47],"expl":["In einer Diskussion braucht man vier Gruppen von Ausdrücken: **Meinung äußern** (__Meiner Meinung nach …, Ich bin der Ansicht, dass …, Ich halte es für wichtig, dass …__), **zustimmen** (__Da stimme ich Ihnen zu. Das sehe ich genauso.__), **widersprechen** (__Da bin ich anderer Meinung. Das überzeugt mich nicht, weil …__) und **einen Kompromiss vorschlagen** (__Wie wäre es, wenn …? Könnten wir uns darauf einigen, dass …?__).","Höfliches Widersprechen hat oft zwei Schritte: Zuerst etwas anerkennen, dann einschränken – __Sie haben insofern recht, als …, aber …__ / __Das ist ein wichtiger Punkt. Trotzdem …__ So bleibt das Gespräch sachlich.","Wichtig sind auch **Rückfragen** (__Wie meinen Sie das genau?__), **Unterbrechen** (__Darf ich kurz etwas dazu sagen?__) und **das Wort zurückholen** (__Lassen Sie mich bitte ausreden.__). In der Prüfung zählt nicht, wer „gewinnt“, sondern dass man reagiert, begründet und am Ende gemeinsam eine Lösung findet."],"use":"Prüfung B2 Sprechen Teil 2/3: Diskussion und gemeinsame Planung mit einer Partnerin / einem Partner.","table":[["Funktion","Ausdruck"],["Meinung","Ich bin der Ansicht, dass … / Meiner Meinung nach …"],["Zustimmung","Da haben Sie völlig recht. / Das sehe ich genauso."],["Teilweise Zustimmung","Im Prinzip ja, aber … / Sie haben insofern recht, als …"],["Widerspruch","Da bin ich anderer Meinung. / Das überzeugt mich nicht."],["Rückfrage","Wie meinen Sie das? / Können Sie ein Beispiel nennen?"],["Kompromiss","Könnten wir uns darauf einigen, dass …? / Wie wäre es, wenn …?"]],"examples":[{"de":"Ich bin der Ansicht, dass Autos aus der Innenstadt verschwinden sollten.","en":"I am of the opinion that cars should disappear from the city centre."},{"de":"Meiner Meinung nach brauchen wir mehr Radwege.","en":"In my opinion we need more cycle paths."},{"de":"Ich halte es für wichtig, dass auch ältere Menschen mobil bleiben.","en":"I think it\'s important that older people also stay mobile."},{"de":"Da stimme ich Ihnen voll und ganz zu.","en":"I agree with you completely."},{"de":"Das sehe ich genauso.","en":"I see it the same way."},{"de":"Im Prinzip ja, aber das ist zu teuer.","en":"In principle yes, but that\'s too expensive."},{"de":"Da bin ich ganz anderer Meinung.","en":"I have a completely different opinion on that."},{"de":"Das überzeugt mich nicht, weil es keine Alternativen gibt.","en":"That doesn\'t convince me because there are no alternatives."},{"de":"Wie meinen Sie das genau?","en":"What exactly do you mean by that?"},{"de":"Können Sie dafür ein Beispiel nennen?","en":"Can you give an example of that?"},{"de":"Darf ich kurz etwas dazu sagen?","en":"May I say something about that?"},{"de":"Lassen Sie mich bitte ausreden.","en":"Please let me finish."},{"de":"Wie wäre es, wenn wir mit einem Testjahr beginnen?","en":"How about starting with a trial year?"},{"de":"Könnten wir uns darauf einigen, dass Lieferverkehr erlaubt bleibt?","en":"Could we agree that delivery traffic remains allowed?"},{"de":"Gut, dann halten wir fest: Wir probieren es ein Jahr lang aus.","en":"Good, then let\'s note: we\'ll try it for a year."}],"vocab":[{"de":"die Ansicht, -en","en":"view"},{"de":"die Auffassung, -en","en":"opinion"},{"de":"der Standpunkt, -e","en":"standpoint"},{"de":"überzeugen","en":"to convince"},{"de":"überzeugend","en":"convincing"},{"de":"zustimmen (+ Dat.)","en":"to agree with"},{"de":"widersprechen (+ Dat.)","en":"to contradict"},{"de":"einwenden","en":"to object"},{"de":"der Einwand, ¨e","en":"objection"},{"de":"der Kompromiss, -e","en":"compromise"},{"de":"sich einigen auf","en":"to agree on"},{"de":"festhalten","en":"to note, to record"},{"de":"abwägen","en":"to weigh up"},{"de":"die autofreie Innenstadt","en":"car-free city centre"},{"de":"der Lieferverkehr","en":"delivery traffic"},{"de":"die Fußgängerzone, -n","en":"pedestrian zone"},{"de":"die Lebensqualität","en":"quality of life"},{"de":"der Einzelhandel","en":"retail trade"},{"de":"die Anbindung, -en","en":"(transport) connection"},{"de":"die Testphase, -n","en":"trial phase"}],"reading":"Soll die Innenstadt autofrei werden? Diese Frage spaltet derzeit die Bürgerinnen und Bürger von Neustadt. Die Stadtverwaltung plant, den Autoverkehr im historischen Zentrum ab dem nächsten Frühjahr weitgehend zu verbieten. Nur Busse, Taxis, Lieferfahrzeuge zu bestimmten Zeiten und Menschen mit Behinderung sollen noch hineinfahren dürfen. Befürworter sind der Ansicht, dass die Lebensqualität dadurch deutlich steigen würde: weniger Lärm, sauberere Luft, mehr Platz für Cafés, Bäume und spielende Kinder. Sie verweisen auf Städte wie Kopenhagen oder Ljubljana, wo ähnliche Maßnahmen erfolgreich waren. Der Einzelhandel sieht das anders. Viele Geschäftsleute befürchten, dass Kundinnen und Kunden aus dem Umland ausbleiben, wenn sie nicht mehr bis vor die Tür fahren können, und lieber in Einkaufszentren am Stadtrand einkaufen. Auch der Seniorenbeirat äußert Bedenken: Für ältere Menschen sei der Weg von einem Parkhaus am Rand oft zu weit. Die Stadt hat deshalb einen Kompromiss vorgeschlagen: eine einjährige Testphase, kostenlose Shuttlebusse von den Parkhäusern ins Zentrum und eine wissenschaftliche Begleitung, die Umsätze, Luftqualität und Zufriedenheit misst. Ob das die Kritiker überzeugt, soll eine Bürgerversammlung im November zeigen.","tasks":[{"q":"Meinung: Meiner ___ nach ist das zu teuer.","a":"Meinung"},{"q":"Meinung: Ich bin der ___, dass …","a":"Ansicht"},{"q":"Zustimmung: Das sehe ich ___.","a":"genauso"},{"q":"Zustimmung: Da ___ ich Ihnen zu. (stimmen)","a":"stimme"},{"q":"Widerspruch: Da bin ich anderer ___.","a":"Meinung"},{"q":"Widerspruch: Das ___ mich nicht. (überzeugen)","a":"überzeugt"},{"q":"Teilweise: Sie haben ___ recht, als …","a":"insofern"},{"q":"Rückfrage: Wie ___ Sie das genau?","a":"meinen"},{"q":"Unterbrechen: ___ ich kurz etwas dazu sagen?","a":"Darf"},{"q":"Kompromiss: Könnten wir uns ___ einigen, dass …?","a":"darauf"},{"q":"Kompromiss: Wie ___ es, wenn wir es testen?","a":"wäre"},{"q":"Fehler? „Ich bin der Meinung nach, dass es gut ist.“","a":"Ich bin der Meinung, dass es gut ist."}],"exam":[{"q":"Was plant die Stadtverwaltung?","a":"Den Autoverkehr im historischen Zentrum weitgehend zu verbieten."},{"q":"Wer darf noch hineinfahren?","a":"Busse, Taxis, Lieferfahrzeuge zu bestimmten Zeiten und Menschen mit Behinderung."},{"q":"Welche Vorteile nennen die Befürworter?","a":"Weniger Lärm, sauberere Luft, mehr Platz."},{"q":"Was befürchtet der Einzelhandel?","a":"Dass Kunden aus dem Umland ausbleiben."},{"q":"Welche Bedenken hat der Seniorenbeirat?","a":"Der Weg vom Parkhaus ist für ältere Menschen zu weit."},{"q":"Woraus besteht der Kompromiss?","a":"Einjährige Testphase, kostenlose Shuttlebusse, wissenschaftliche Begleitung."},{"q":"Widersprechen Sie höflich: „Autos gehören in die Stadt.“","a":"","m":"Da bin ich anderer Meinung. Ich verstehe, dass viele Menschen ein Auto brauchen. Aber die Autos machen die Städte laut und gefährlich. Meiner Meinung nach brauchen wir mehr Platz für Fußgänger."},{"q":"Diskutieren Sie: Sollte Ihre Stadt autofrei werden? Nennen Sie zwei Argumente dafür und dagegen.","a":"","m":"Ich bin der Ansicht, dass eine autofreie Innenstadt Vorteile hat: Die Luft wird besser und es gibt mehr Platz. Andererseits haben Geschäfte Angst, Kunden zu verlieren. Außerdem brauchen ältere Menschen gute Busse."},{"q":"Planen Sie mit einem Partner ein autofreies Stadtfest und einigen Sie sich auf drei Punkte.","a":"","m":"Ich schlage vor, dass wir die Hauptstraße für einen Tag sperren. – Einverstanden. Wie wäre es mit Musik? – Gute Idee. Und wir einigen uns darauf, dass es Fahrräder zum Ausleihen gibt."},{"q":"Fassen Sie die Diskussion zwischen Frau Krämer und Herrn Yıldız zusammen.","a":"","m":"Frau Krämer ist der Ansicht, dass Autos die Innenstadt zerstören. Herr Yıldız meint dagegen, die Geschäfte bräuchten Kunden mit dem Auto. Am Ende einigen sie sich auf einen Kompromiss."}],"speak":["Diskutiert zu zweit: Homeoffice für alle – ja oder nein?","Widersprich höflich in zwei Schritten: anerkennen, dann einschränken.","Unterbrich höflich und hol dir das Wort zurück.","Einigt euch auf einen Kompromiss für ein Klassenfest."],"dialog":[{"who":"Moderatorin","de":"Frau Krämer, Sie haben ein Modegeschäft in der Altstadt. Was halten Sie von der autofreien Innenstadt?"},{"who":"Frau Krämer","de":"Ehrlich gesagt überzeugt mich das nicht. Viele meiner Kundinnen kommen mit dem Auto aus dem Umland."},{"who":"Herr Yıldız","de":"Darf ich kurz etwas dazu sagen? In Kopenhagen sind die Umsätze nach der Umstellung gestiegen."},{"who":"Frau Krämer","de":"Lassen Sie mich bitte ausreden. Kopenhagen hat ein ganz anderes Radwegenetz als wir."},{"who":"Herr Yıldız","de":"Da haben Sie insofern recht, als wir noch Radwege bauen müssen. Aber genau deshalb brauchen wir die Testphase."},{"who":"Moderatorin","de":"Gibt es einen Punkt, auf den Sie sich einigen könnten?"},{"who":"Frau Krämer","de":"Wenn die Shuttlebusse wirklich kostenlos und häufig fahren, wäre ich bereit, es ein Jahr zu versuchen."},{"who":"Herr Yıldız","de":"Damit kann ich gut leben."}],"dq":[{"q":"Warum ist Frau Krämer skeptisch?","a":"Viele Kundinnen kommen mit dem Auto aus dem Umland."},{"q":"Welches Beispiel nennt Herr Yıldız?","a":"Kopenhagen (die Umsätze sind gestiegen)."},{"q":"Unter welcher Bedingung stimmt Frau Krämer zu?","a":"Wenn die Shuttlebusse kostenlos und häufig fahren."}],"en":{"title":"Discussing: opinion, agreement, disagreement, compromise","theme":"City of the future","expl":["In a discussion you need four groups of phrases: **giving your opinion** (__Meiner Meinung nach … Ich bin der Ansicht, dass …__), **agreeing** (__Da stimme ich Ihnen zu. Das sehe ich genauso.__), **disagreeing** (__Da bin ich anderer Meinung. Das überzeugt mich nicht, weil …__) and **finding a compromise** (__Wie wäre es, wenn wir … Könnten wir uns darauf einigen, dass …__)."],"use":""},"check":[{"re":"\\\\b(meiner meinung nach|ich bin der ansicht|da stimme ich|das sehe ich|da bin ich anderer meinung|einerseits|andererseits|kompromiss|einigen)\\\\b","label":"discussion phrases (Meiner Meinung nach …, Da stimme ich zu …)"}]},{"n":51,"pos":58,"level":"C1","title":"Erweiterte Attribute und komplexe Relativsätze","theme":"Fachtexte lesen","scene":"classroom","rec":[33,44,45],"expl":["C1-Texte packen viel Information **vor** das Nomen: __der **in den letzten Jahren stark gestiegene** Energiebedarf__. Beim Lesen löst man das rückwärts auf: Artikel → Partizip → Rest → Relativsatz (__der Energiebedarf, der in den letzten Jahren stark gestiegen ist__).","**Relativsätze C1:** Präposition + Relativpronomen (__das Thema, **über das** wir sprachen__), **wo(r)-Formen** für Sachen (__das Thema, **worüber** wir sprachen__), **was** nach das/alles/nichts/etwas/Superlativ (__alles, **was** ich weiß__), **wer** = derjenige, der; Genitiv **dessen/deren** (__der Autor, **dessen** Buch …__).","Relativsätze können auch einen **ganzen Satz** kommentieren: __Er kam zu spät, **was** alle störte.__"],"use":"Fachartikel, Studien, Verträge verstehen; präzise schreiben ohne Satzketten.","table":[["Struktur","Beispiel","Auflösung"],["erweitertes Partizipialattribut","die vom Ausschuss geprüften Anträge","die Anträge, die der Ausschuss geprüft hat"],["Partizip I + zu","die zu erwartenden Kosten","die Kosten, die erwartet werden müssen"],["Präposition + Relativpronomen","die Frage, auf die niemand antwortete","—"],["wo(r)- (Sachen)","das Thema, worüber wir sprachen","über das"],["Genitiv","die Firma, deren Gewinne sinken","—"],["was (Satzbezug)","Er schwieg, was mich überraschte.","—"],["wer … der","Wer zu spät kommt, den bestraft das Leben.","derjenige, der"]],"examples":[{"de":"Die von der Regierung beschlossenen Maßnahmen treten im Juli in Kraft.","en":"The measures decided by the government come into force in July."},{"de":"Der seit Jahren diskutierte Vorschlag wurde erneut abgelehnt.","en":"The proposal discussed for years was rejected again."},{"de":"Das ist ein Problem, für das es keine einfache Lösung gibt.","en":"That\'s a problem for which there is no simple solution."},{"de":"Alles, was wir wissen, stammt aus einer Quelle.","en":"Everything we know comes from one source."},{"de":"Der Autor, dessen Studie wir zitieren, arbeitet in Leipzig.","en":"The author whose study we quote works in Leipzig."},{"de":"Wer sich bewirbt, sollte die Frist beachten.","en":"Whoever applies should note the deadline."},{"de":"Sie sagte nichts, was mich beunruhigte.","en":"She said nothing, which worried me."},{"de":"Die zu klärenden Fragen stehen auf der Agenda.","en":"The questions to be clarified are on the agenda."},{"de":"Das Verfahren, mit dessen Hilfe wir messen, ist neu.","en":"The method with the help of which we measure is new."},{"de":"Die Kollegen, denen wir danken, haben viel geleistet.","en":"The colleagues whom we thank achieved a lot."},{"de":"Die von der Universität Leipzig durchgeführte Studie bestätigt diesen Befund.","en":"The study carried out by the University of Leipzig confirms this finding."},{"de":"Die an der Untersuchung beteiligten Personen wurden zufällig ausgewählt.","en":"The persons involved in the investigation were selected at random."},{"de":"Der im Jahr 2019 erschienene Bericht wird häufig zitiert.","en":"The report published in 2019 is frequently cited."},{"de":"Die in Abbildung 3 dargestellten Werte sind signifikant.","en":"The values shown in Figure 3 are significant."},{"de":"Ein seit Jahren diskutiertes Problem ist der Fachkräftemangel.","en":"A problem discussed for years is the shortage of skilled workers."},{"de":"Die Daten, auf deren Grundlage die Berechnung erfolgte, sind öffentlich.","en":"The data on the basis of which the calculation was made are public."},{"de":"Die von vielen Experten vertretene These ließ sich nicht belegen.","en":"The thesis advocated by many experts could not be proven."},{"de":"Die zu prüfenden Unterlagen liegen der Kommission vor.","en":"The documents to be examined have been submitted to the commission."},{"de":"Der Zusammenhang zwischen Schlaf und Gedächtnis ist gut erforscht.","en":"The connection between sleep and memory is well researched."},{"de":"Hinsichtlich der Kosten gibt es noch offene Fragen.","en":"With regard to the costs there are still open questions."}],"vocab":[{"de":"der Ausschuss, ¨e","en":"committee"},{"de":"beschließen","en":"to decide, pass"},{"de":"erneut","en":"again"},{"de":"die Agenda","en":"agenda"},{"de":"zitieren","en":"to quote"},{"de":"beunruhigen","en":"to worry"},{"de":"das Verfahren, -","en":"procedure, method"},{"de":"leisten","en":"to achieve, perform"},{"de":"die Frist beachten","en":"to observe the deadline"},{"de":"ablehnen","en":"to reject"},{"de":"klären","en":"to clarify"},{"de":"umfassen","en":"to comprise"},{"de":"die Studie, -n","en":"study"},{"de":"die Untersuchung, -en","en":"investigation, examination"},{"de":"die Stichprobe, -n","en":"sample"},{"de":"der Befund, -e","en":"finding"},{"de":"die Hypothese, -n","en":"hypothesis"},{"de":"belegen","en":"to prove, to document"},{"de":"widerlegen","en":"to refute"},{"de":"auswerten","en":"to evaluate (data)"},{"de":"erheben (Daten)","en":"to collect (data)"},{"de":"signifikant","en":"significant"},{"de":"repräsentativ","en":"representative"},{"de":"die Fachzeitschrift, -en","en":"academic journal"},{"de":"die Abbildung, -en","en":"figure, illustration"},{"de":"der Zusammenhang, ¨e","en":"connection, correlation"},{"de":"die Wechselwirkung, -en","en":"interaction"},{"de":"maßgeblich","en":"decisive, significant"},{"de":"hinsichtlich (+ Gen.)","en":"with regard to"},{"de":"im Hinblick auf","en":"with regard to"},{"de":"sich beziehen auf","en":"to refer to"},{"de":"die Fachsprache, -n","en":"technical language"}],"reading":"Aus einem Fachartikel: Die im vergangenen Jahr veröffentlichte Studie, deren Ergebnisse inzwischen mehrfach bestätigt wurden, untersucht den Zusammenhang zwischen Schlafdauer und Konzentration. Die von den Forschenden befragten Personen, unter denen auch Schichtarbeiter waren, berichteten über deutliche Leistungsunterschiede. Was die Autoren besonders betonen, ist die Rolle regelmäßiger Schlafzeiten. Die noch zu prüfende Frage lautet, wie stark einzelne Faktoren wirken.","tasks":[{"q":"Auflösen: die vom Team geprüften Daten → die Daten, die ___ ___ ___ ___","a":"das Team geprüft hat"},{"q":"Auflösen: die zu zahlenden Gebühren → die Gebühren, die ___ ___ ___","a":"gezahlt werden müssen"},{"q":"Nominal: die Studie, die letztes Jahr erschien → die ___ ___ Studie","a":"letztes Jahr erschienene"},{"q":"Relativpronomen: das Projekt, an ___ wir arbeiten","a":"dem"},{"q":"wo-Form: das Thema, ___ wir gesprochen haben (über)","a":"worüber"},{"q":"Genitiv: die Autorin, ___ Buch wir lesen","a":"deren"},{"q":"Satzbezug: Er kam nicht, ___ uns überraschte.","a":"was"},{"q":"[Mix] Alles, ___ nicht geklärt ___ (sein), kommt auf die Agenda.","a":"was / ist"},{"q":"[Mix] Die Ergebnisse ___ mehrfach bestätigt ___ (werden, Passiv Perfekt).","a":"sind / worden"},{"q":"[Mix] Die Autoren betonen, die Schlafzeiten ___ entscheidend. (Konj. I von sein)","a":"seien"},{"q":"Attribut: die Studie, die 2020 veröffentlicht wurde → die 2020 ___ Studie","a":"veröffentlichte"},{"q":"Attribut: die Teilnehmer, die an der Studie teilnahmen → die an der Studie ___ Teilnehmer","a":"teilnehmenden"},{"q":"Attribut: das Problem, das seit Jahren diskutiert wird → das seit Jahren ___ Problem","a":"diskutierte"},{"q":"Attribut: die Werte, die in der Tabelle dargestellt sind → die in der Tabelle ___ Werte","a":"dargestellten"},{"q":"Auflösen: der von der Firma entwickelte Motor → der Motor, ___ von der Firma entwickelt ___ ___","a":"der / worden ist"},{"q":"Auflösen: die schnell steigenden Preise → die Preise, die schnell ___","a":"steigen"},{"q":"Relativsatz mit Präposition: die Daten, ___ ___ Grundlage wir rechnen (deren/auf)","a":"auf deren"},{"q":"Relativsatz: die Forscherin, ___ Ergebnisse überraschten","a":"deren"},{"q":"Gerundiv: die Fragen, die noch geklärt werden müssen → die noch zu ___ Fragen","a":"klärenden"},{"q":"Fehler? „Die gestern veröffentlichten Studie ist interessant.“","a":"Die gestern veröffentlichte Studie ist interessant."}],"exam":[{"q":"Was untersucht die Studie?","a":"Den Zusammenhang zwischen Schlafdauer und Konzentration."},{"q":"Wer wurde befragt?","a":"Personen, darunter Schichtarbeiter."},{"q":"Was betonen die Autoren besonders?","a":"Die Rolle regelmäßiger Schlafzeiten."},{"q":"Auflösen: die in Berlin lebenden Studierenden","a":"die Studierenden, die in Berlin leben"},{"q":"Verdichten: der Bericht, den wir gestern erhalten haben","a":"der gestern erhaltene Bericht"},{"q":"Relativsatz mit Präposition: Das ist die Kollegin. Ich arbeite mit ihr.","a":"Das ist die Kollegin, mit der ich arbeite."},{"q":"Was oder das? „Er hat alles verstanden, ___ ich gesagt habe.“","a":"was"},{"q":"Fassen Sie einen Fachtext in drei Sätzen mit erweiterten Attributen zusammen.","a":"","m":"Der Text beschreibt den in den letzten Jahren stark gestiegenen Energiebedarf. Die von der Regierung geplanten Maßnahmen sollen ihn senken. Die bisher erzielten Ergebnisse sind gering."},{"q":"Erklären Sie mündlich einen komplexen Satz aus Ihrem Beruf in einfachen Worten.","a":"","m":"In meinem Beruf heißt es: „Die nach dem Update aufgetretenen Fehler wurden behoben.“ Einfach gesagt: Nach dem Update gab es Fehler. Jetzt sind sie repariert."},{"q":"Warum bevorzugen Fachtexte Attribute statt Relativsätze?","a":"","m":"Fachtexte bevorzugen Attribute, weil sie viel Information kompakt vor dem Nomen bündeln. Der Text wird dadurch kürzer, aber schwerer zu lesen."}],"speak":["Erkläre den Lesetext einem B1-Lerner in einfachen Sätzen.","Beschreibe deinen Arbeitsplatz mit drei erweiterten Attributen.","Formuliere drei Relativsätze mit Präpositionen über deine Stadt.","Was macht einen Text schwer lesbar? Begründe."],"reading2":{"title":"Schlaf und Lernen – was die Forschung sagt","text":"Dass ausreichender Schlaf für das Lernen von zentraler Bedeutung ist, gilt in der Gedächtnisforschung inzwischen als gesichert. Eine in einer renommierten Fachzeitschrift veröffentlichte Studie hat diesen Zusammenhang nun genauer untersucht. Die an der Untersuchung teilnehmenden 120 Studierenden mussten am Abend eine Liste mit 40 Wortpaaren einer ihnen unbekannten Sprache lernen. Anschließend wurden sie in zwei Gruppen aufgeteilt: Die eine Gruppe schlief normal, die andere wurde die ganze Nacht wach gehalten und durfte erst in der darauffolgenden Nacht schlafen. Die nach drei Tagen durchgeführte Abfrage ergab einen deutlichen Unterschied. Die Teilnehmenden der ersten Gruppe erinnerten sich an durchschnittlich 28 Wortpaare, die der zweiten Gruppe lediglich an 19. Der in der Nachholnacht gewonnene Schlaf konnte den Verlust also nicht ausgleichen. Die Forschenden erklären dies mit Prozessen, die vor allem im sogenannten Tiefschlaf ablaufen: Die tagsüber im Hippocampus zwischengespeicherten Informationen werden in dieser Phase wiederholt aktiviert und in die Großhirnrinde übertragen, wo sie langfristig verankert werden. Bemerkenswert ist ein weiterer Befund: Bei den Teilnehmenden, die vor dem Einschlafen die gelernten Wörter noch einmal kurz wiederholt hatten, fiel der Lerneffekt am stärksten aus. Die Autorinnen und Autoren räumen allerdings ein, dass die Stichprobe hinsichtlich Alter und Bildungsstand nicht repräsentativ sei. Ob sich die Ergebnisse auf ältere Menschen oder auf komplexere Lerninhalte übertragen lassen, müsse in weiteren Studien geprüft werden. Für Prüfungskandidaten lässt sich dennoch eine klare Empfehlung ableiten: Die oft praktizierte Nachtschicht vor der Prüfung ist eher kontraproduktiv."},"dialog":[{"who":"Moderator","de":"Professor Lehmann, Ihre Studie zeigt, dass Schlaf für das Gedächtnis entscheidend ist. Was ist neu daran?"},{"who":"Prof. Lehmann","de":"Neu ist vor allem, dass der in der folgenden Nacht nachgeholte Schlaf den Verlust nicht kompensiert. Das hatten viele angenommen."},{"who":"Moderator","de":"Welche Rolle spielt dabei der Tiefschlaf?"},{"who":"Prof. Lehmann","de":"Eine maßgebliche. In dieser Phase werden die tagsüber aufgenommenen Informationen gewissermaßen neu abgespielt und dauerhaft gespeichert."},{"who":"Moderator","de":"Ihre Kritiker sagen, die Stichprobe sei zu klein."},{"who":"Prof. Lehmann","de":"Hundertzwanzig Personen sind für ein Laborexperiment durchaus üblich. Aber es stimmt, dass wir nur junge Erwachsene untersucht haben."},{"who":"Moderator","de":"Was raten Sie Schülerinnen und Schülern vor einer Prüfung?"},{"who":"Prof. Lehmann","de":"Am Abend vorher das Wichtigste kurz wiederholen – und dann schlafen gehen. Die Nacht durchzulernen ist der schlechteste Plan."}],"dq":[{"q":"Was ist laut Prof. Lehmann neu an der Studie?","a":"Dass nachgeholter Schlaf den Verlust nicht kompensiert."},{"q":"Was passiert im Tiefschlaf?","a":"Die tagsüber aufgenommenen Informationen werden neu abgespielt und dauerhaft gespeichert."},{"q":"Was ist die Schwäche der Studie?","a":"Es wurden nur junge Erwachsene untersucht."}],"en":{"title":"Extended attributes and complex relative clauses","theme":"Reading specialist texts","expl":["C1 texts pack a lot of information **in front of the noun**: __der in den letzten Jahren stark gestiegene Energiebedarf__ = the energy demand that has risen sharply in recent years.","To read it, unpack it: article → noun → turn the participle phrase into a relative clause: __der Energiebedarf, der in den letzten Jahren stark gestiegen ist__.","C1 relative clauses also use a preposition + relative pronoun (__das Thema, über das wir sprachen__) and the genitive dessen/deren."],"use":""},"check":[{"re":"\\\\b(der|die|das|den|dem|des)\\\\s+(\\\\w+\\\\s+){1,5}\\\\w+(ten|ende|enden|te|ene|enen)\\\\s+[A-ZÄÖÜ]","label":"an extended attribute (der stark gestiegene Bedarf)"}]},{"n":52,"pos":59,"level":"C1","title":"Modalpartikeln: doch, mal, ja, eben, wohl, halt","theme":"Gesprächston treffen","scene":"family","rec":[12,26,49],"expl":["**Modalpartikeln** ändern nicht den Inhalt, sondern die **Haltung** des Sprechers. Sie stehen **im Mittelfeld**, nie am Satzanfang, und sind unbetont.","**doch** = Widerspruch/Erinnerung („du weißt es ja“), **mal** = lockert Aufforderungen, **ja** = Selbstverständlichkeit oder Warnung (betont), **eben/halt** = resignierte Feststellung, **wohl** = Vermutung, **bloß/nur** = Dringlichkeit, **denn** = freundliches Interesse in Fragen, **schon** = beruhigend, **etwa** = Zweifel/Vorwurf in Fragen.","Ohne Partikeln klingt Deutsch korrekt, aber **hart**; mit ihnen klingt es natürlich."],"use":"Natürlich sprechen, Nuancen verstehen, Filme und Alltagsgespräche folgen.","table":[["Partikel","Wirkung","Beispiel"],["denn","freundliches Interesse (Frage)","Was machst du **denn** hier?"],["mal","lockert Aufforderung","Komm **mal** her."],["doch","Erinnerung, Widerspruch","Das weißt du **doch**!"],["ja","Selbstverständlichkeit / Warnung","Das ist **ja** klar. · Mach das **ja** nicht!"],["eben / halt","so ist es nun mal","Dann müssen wir **eben** warten."],["wohl","Vermutung","Er ist **wohl** krank."],["bloß / nur","Dringlichkeit, Sorge","Wo ist **bloß** mein Schlüssel?"],["schon","beruhigend","Das wird **schon** klappen."],["etwa","Zweifel, Vorwurf","Hast du das **etwa** vergessen?"]],"examples":[{"de":"Wie heißt du denn?","en":"What\'s your name then? (friendly)"},{"de":"Setz dich doch!","en":"Do sit down!"},{"de":"Das ist ja unglaublich!","en":"That\'s really unbelievable!"},{"de":"Dann machen wir es eben morgen.","en":"Then we\'ll just do it tomorrow."},{"de":"Er wird wohl im Stau stehen.","en":"He\'s probably stuck in traffic."},{"de":"Sag bloß nichts davon!","en":"Don\'t you dare say anything about it!"},{"de":"Das schaffst du schon.","en":"You\'ll manage all right."},{"de":"Hast du etwa nicht angerufen?","en":"Don\'t tell me you didn\'t call?"},{"de":"Komm doch mal vorbei!","en":"Do drop by sometime!"},{"de":"Das ist halt so in Deutschland.","en":"That\'s just how it is in Germany."},{"de":"Was ist denn hier los?","en":"What\'s going on here then?"},{"de":"Wo ist bloß mein Schlüssel?","en":"Where on earth is my key?"},{"de":"Hast du etwa schon wieder vergessen, einzukaufen?","en":"Don\'t tell me you forgot to go shopping again?"},{"de":"Keine Sorge, das wird schon.","en":"Don\'t worry, it\'ll be fine."},{"de":"Wie heißt du eigentlich?","en":"What\'s your name, by the way?"},{"de":"Nimm dir ruhig noch ein Stück Kuchen!","en":"Go ahead, have another piece of cake!"},{"de":"Ich muss eh noch zur Post.","en":"I have to go to the post office anyway."},{"de":"Kannst du mal eben das Fenster zumachen?","en":"Could you just close the window?"},{"de":"Das ist halt so, da kann man nichts machen.","en":"That\'s just the way it is, nothing you can do."},{"de":"Mach das ja nicht noch einmal!","en":"Don\'t you dare do that again!"}],"vocab":[{"de":"die Modalpartikel, -n","en":"modal particle"},{"de":"die Haltung, -en","en":"attitude"},{"de":"unbetont / betont","en":"unstressed / stressed"},{"de":"der Vorwurf, ¨e","en":"reproach"},{"de":"die Aufforderung, -en","en":"request, prompt"},{"de":"locker","en":"relaxed"},{"de":"selbstverständlich","en":"self-evident"},{"de":"beruhigen","en":"to reassure"},{"de":"die Nuance, -n","en":"nuance"},{"de":"wirken","en":"to have an effect, seem"},{"de":"klingen","en":"to sound"},{"de":"der Ton, ¨e","en":"tone"},{"de":"denn (Frage)","en":"(friendly interest in questions)"},{"de":"bloß / nur","en":"(urgency, worry)"},{"de":"etwa","en":"(doubt, reproach in questions)"},{"de":"schon","en":"(reassurance)"},{"de":"eigentlich","en":"(by the way; topic change)"},{"de":"ruhig","en":"(permission: go ahead)"},{"de":"eh / sowieso","en":"anyway"},{"de":"mal eben","en":"just quickly"},{"de":"na ja","en":"well …"},{"de":"ach so","en":"oh, I see"},{"de":"echt","en":"really (colloquial)"},{"de":"quasi","en":"more or less"},{"de":"genervt","en":"annoyed"},{"de":"gelassen","en":"calm, relaxed"},{"de":"die Ungeduld","en":"impatience"},{"de":"die Ermutigung, -en","en":"encouragement"},{"de":"die Zustimmung","en":"agreement"},{"de":"der Unterton, -e","en":"undertone"},{"de":"höflich","en":"polite"},{"de":"schroff","en":"brusque"}],"reading":"Am Küchentisch: „Wo sind denn meine Schlüssel?“ – „Die liegen doch auf dem Tisch!“ – „Da habe ich schon geschaut. Wo sind sie bloß?“ – „Dann nimm eben meine.“ – „Du hast sie ja gestern benutzt, oder?“ – „Nein! Jetzt mach mal langsam.“ Später: „Sie waren halt in der Jacke. Das war ja klar.“ – „Siehst du, ich hab\'s doch gesagt. Das wird schon wieder.“","tasks":[{"q":"Freundliche Frage: Wie spät ist es ___?","a":"denn"},{"q":"Lockere Bitte: Gib mir ___ das Salz.","a":"mal"},{"q":"Erinnerung: Das habe ich dir ___ gesagt!","a":"doch"},{"q":"Resignation: Dann fahren wir ___ später.","a":"eben"},{"q":"Vermutung: Sie ist ___ schon zu Hause.","a":"wohl"},{"q":"Warnung: Vergiss das ___ nicht!","a":"ja"},{"q":"Beruhigung: Das klappt ___.","a":"schon"},{"q":"[Mix] Wo ist ___ die Rechnung, die ich gestern ___ habe? (bloß; bekommen)","a":"bloß / bekommen"},{"q":"[Mix] Wir haben ___ gestern darüber gesprochen, oder? (Partikel für Selbstverständlichkeit)","a":"ja"},{"q":"[Mix] Komm ___ ___ vorbei, wenn du Zeit hast. (zwei Partikeln)","a":"doch mal"},{"q":"Freundliches Interesse: Was machst du ___ hier?","a":"denn"},{"q":"Ungeduld/Sorge: Wo bleibt er ___?","a":"bloß"},{"q":"Vorwurf: Hast du ___ mein Handy benutzt?","a":"etwa"},{"q":"Beruhigung: Keine Panik, das klappt ___.","a":"schon"},{"q":"Erlaubnis: Komm ___ rein, die Tür ist offen.","a":"ruhig"},{"q":"Resignation: Das ist ___ so. (halt/doch)","a":"halt"},{"q":"Bekanntes: Du weißt ___, dass ich keine Zeit habe.","a":"doch"},{"q":"Themenwechsel: Woher kommst du ___?","a":"eigentlich"},{"q":"Aufforderung abschwächen: Gib mir ___ den Stift.","a":"mal"},{"q":"Zwei Partikeln: Ruf ___ ___ an! (Ermunterung)","a":"doch mal"}],"exam":[{"q":"Wo waren die Schlüssel am Ende?","a":"In der Jacke."},{"q":"Welche Partikel zeigt Resignation im Text?","a":"eben / halt"},{"q":"Welche Partikel zeigt Ungeduld bei der Suche?","a":"bloß"},{"q":"Fügen Sie eine Partikel ein: „Komm her.“ (freundlich)","a":"Komm mal her."},{"q":"Was ändert sich? „Das ist klar.“ → „Das ist ja klar.“","a":"Es klingt selbstverständlich/erstaunt."},{"q":"Welche Partikel passt: „Hast du ___ alles vergessen?“ (Vorwurf)","a":"etwa"},{"q":"Warum stehen Modalpartikeln nie auf Position 1?","a":"Sie sind unbetont und gehören ins Mittelfeld."},{"q":"Führen Sie ein kurzes Alltagsgespräch mit mindestens fünf Partikeln.","a":"","m":"Komm doch mal rein! – Danke. Du hast ja eine schöne Wohnung. – Na ja, sie ist halt klein. – Das ist doch egal. – Stimmt eben. Möchtest du denn einen Tee?"},{"q":"Erklären Sie einem B1-Lerner den Unterschied zwischen „Komm!“ und „Komm doch mal!“.","a":"","m":"„Komm!“ ist ein direkter Befehl. „Komm doch mal!“ ist eine freundliche Einladung. „doch“ und „mal“ machen den Satz weicher."},{"q":"Wo benutzen Sie in Ihrer Muttersprache ähnliche Wörter?","a":"","m":"Im Hindi benutze ich Wörter wie „na“ oder „to“, um einen Satz freundlicher zu machen. Sie funktionieren ähnlich wie „doch“ oder „mal“."}],"speak":["Spiele die Küchenszene nach – mit Partikeln.","Bitte jemanden dreimal um dasselbe: neutral, freundlich, dringend.","Reagiere resigniert auf schlechte Nachrichten (eben/halt).","Beruhige einen nervösen Freund vor der Prüfung."],"reading2":{"title":"Kleine Wörter, große Wirkung","text":"Modalpartikeln gehören zu den schwierigsten Kapiteln für Deutschlernende – und zu den wichtigsten. In Grammatikbüchern werden sie oft nur am Rande behandelt, im gesprochenen Deutsch sind sie dagegen allgegenwärtig. Wer sie weglässt, spricht zwar korrekt, klingt aber schnell unhöflich, kühl oder wie ein Lehrbuch. Ein Beispiel: Der Satz „Komm her!“ wirkt wie ein Befehl. „Komm mal her!“ ist schon deutlich freundlicher, „Komm doch mal her!“ klingt fast wie eine Einladung. Die Wörter verändern nicht den Inhalt, sondern die Beziehung zwischen den Sprechenden. Ähnlich verhält es sich mit Fragen. „Wie heißt du?“ ist neutral, beinahe wie in einem Formular. „Wie heißt du denn?“ signalisiert Interesse, im Gespräch mit einem Kind wirkt es warm. Eine besondere Herausforderung besteht darin, dass viele Partikeln mehrere Funktionen haben. „Ja“ ist ein Antwortwort, im Satz „Das ist ja interessant!“ drückt es Überraschung aus, im Satz „Mach das ja nicht!“ – betont gesprochen – eine Drohung. „Doch“ kann einer Verneinung widersprechen („Kommst du nicht? – Doch!“), an etwas Bekanntes erinnern („Du weißt doch, dass …“) oder eine Aufforderung verstärken („Setz dich doch!“). Hinzu kommt, dass Partikeln sich kombinieren lassen: „Ruf doch mal an!“, „Das ist ja eben das Problem.“ Linguisten empfehlen Lernenden deshalb, Partikeln nicht isoliert zu lernen, sondern in typischen Situationen: beim Bitten, beim Trösten, beim Widersprechen, beim Sich-Wundern. Wer viel Alltagsdeutsch hört, etwa in Serien oder Podcasts, entwickelt mit der Zeit ein Gefühl dafür. Und ein Trost: Auch Muttersprachler können meist nicht erklären, warum sie „halt“ statt „eben“ sagen. Sie wissen es einfach."},"dialog":[{"who":"Mia","de":"Na, wie war denn dein Vorstellungsgespräch?"},{"who":"Tomás","de":"Ach, ganz okay, glaube ich. Ich war halt total nervös."},{"who":"Mia","de":"Das ist doch normal. Hast du etwa wieder zu schnell gesprochen?"},{"who":"Tomás","de":"Ein bisschen. Aber die Chefin war echt nett. Sie hat gesagt: „Nehmen Sie sich ruhig Zeit.“"},{"who":"Mia","de":"Siehst du! Das klappt schon."},{"who":"Tomás","de":"Hoffentlich. Wann melden die sich bloß?"},{"who":"Mia","de":"Jetzt warte doch erst mal ab. Du hast das Gespräch ja erst seit zwei Stunden hinter dir!"}],"dq":[{"q":"Wie fühlte sich Tomás im Gespräch?","a":"Er war total nervös."},{"q":"Was sagte die Chefin?","a":"„Nehmen Sie sich ruhig Zeit.“"},{"q":"Welche Partikel zeigt Tomás\' Ungeduld in „Wann melden die sich bloß?“","a":"bloß"}],"en":{"title":"Modal particles: doch, mal, ja, eben, wohl, halt","theme":"Finding the right tone","expl":["Modal particles don\'t change the content, they show the **speaker\'s attitude**. They sit in the middle of the sentence, never at the start, and are unstressed.","**doch** = contradiction or reminder (\\"you know\\"), **mal** = softens a request (__Komm mal her!__), **ja** = obvious, or a warning when stressed, **eben / halt** = that\'s just how it is, **wohl** = probably, **bloß / nur** = urgency (__Pass bloß auf!__)."],"use":""},"check":[{"re":"\\\\b(doch|mal|ja|eben|halt|wohl|bloß|schon|denn)\\\\b","label":"modal particles (doch, mal, ja, halt …)"}]},{"n":53,"pos":60,"level":"C1","title":"Textkohäsion: Konzessiv, Adversativ, Konsekutiv","theme":"Argumentieren auf C1","scene":"office","rec":[36,37,47],"expl":["Auf C1 verbindet man Gedanken präzise:","**Konzessiv** (Einräumung): **obwohl, obgleich, wenngleich, auch wenn, zwar … jedoch, trotz allem, ungeachtet + Gen.**","**Adversativ** (Gegensatz): **während, wohingegen, hingegen, dagegen, im Gegensatz dazu, vielmehr**","**Konsekutiv** (Folge): **sodass, folglich, infolgedessen, somit, demnach, mithin**","**Kausal/final gehoben**: **zumal, da, angesichts + Gen., zwecks + Gen., damit**","Wortstellung beachten: **Nebensatz-Konnektoren** (obwohl, während, sodass) → Verb ans Ende; **Adverbien** (folglich, hingegen, somit) → Verb direkt danach; **Präpositionen** (ungeachtet, angesichts) → Nomen im Genitiv."],"use":"Erörterung, Stellungnahme, Präsentationen, wissenschaftliche Texte.","table":[["Typ","Nebensatz","Adverb","Präposition"],["Konzessiv","obwohl, wenngleich","trotzdem, dennoch, gleichwohl","trotz, ungeachtet + Gen."],["Adversativ","während, wohingegen","hingegen, dagegen, vielmehr","im Gegensatz zu + Dat."],["Konsekutiv","sodass, so … dass","folglich, somit, infolgedessen","infolge + Gen."],["Kausal","weil, da, zumal","nämlich, denn (Pos. 0)","wegen, aufgrund, angesichts + Gen."],["Final","damit, um … zu","—","zwecks, zu + Dat."]],"examples":[{"de":"Wenngleich die Kosten steigen, bleibt die Nachfrage hoch.","en":"Although costs are rising, demand remains high."},{"de":"Die Zahlen sinken, wohingegen die Erwartungen unverändert bleiben.","en":"The figures are falling, whereas expectations remain unchanged."},{"de":"Die Maschine war defekt; folglich verzögerte sich die Lieferung.","en":"The machine was faulty; consequently the delivery was delayed."},{"de":"Angesichts der aktuellen Lage verschieben wir die Investition.","en":"In view of the current situation we are postponing the investment."},{"de":"Ungeachtet aller Kritik hält die Firma am Kurs fest.","en":"Regardless of all criticism the company sticks to its course."},{"de":"Zwar ist die Methode teuer, jedoch liefert sie genaue Ergebnisse.","en":"The method is expensive, but it delivers precise results."},{"de":"Das Angebot ist begrenzt, somit steigen die Preise.","en":"Supply is limited, hence prices rise."},{"de":"Im Gegensatz zu früheren Studien fanden wir keinen Effekt.","en":"In contrast to earlier studies we found no effect."},{"de":"Wir prüfen den Vorschlag, zumal die Frist bald abläuft.","en":"We\'re examining the proposal, especially as the deadline is approaching."},{"de":"Vielmehr sollte man die Ursachen bekämpfen.","en":"Rather, one should tackle the causes."},{"de":"Die Maßnahme ist teuer, dennoch halten viele sie für notwendig.","en":"The measure is expensive, yet many consider it necessary."},{"de":"Wenngleich die Idee überzeugt, bleibt die Umsetzung schwierig.","en":"Although the idea is convincing, implementation remains difficult."},{"de":"Das Angebot ist attraktiv, zumal die Kosten gering sind.","en":"The offer is attractive, especially since the costs are low."},{"de":"In der Stadt sind die Mieten gestiegen, wohingegen sie auf dem Land stabil blieben.","en":"In the city rents have risen, whereas they remained stable in the country."},{"de":"Die Firma hat Verluste gemacht; infolgedessen werden Stellen abgebaut.","en":"The company made losses; as a result jobs are being cut."},{"de":"Ungeachtet der Kritik hält die Regierung an ihrem Plan fest.","en":"Regardless of the criticism, the government is sticking to its plan."},{"de":"Die Studie ist klein, somit sind die Ergebnisse nur begrenzt aussagekräftig.","en":"The study is small, thus the results are of limited significance."},{"de":"Man könnte einwenden, dass dies zu teuer sei.","en":"One could object that this would be too expensive."},{"de":"Dieses Argument lässt sich leicht entkräften.","en":"This argument can easily be refuted."},{"de":"Junge Menschen nutzen eher digitale Medien, ältere hingegen lesen häufiger Zeitung.","en":"Young people tend to use digital media, older people, on the other hand, read newspapers more often."}],"vocab":[{"de":"die Erörterung, -en","en":"discursive essay"},{"de":"die Einräumung, -en","en":"concession"},{"de":"der Gegensatz, ¨e","en":"contrast"},{"de":"die Verzögerung, -en","en":"delay"},{"de":"festhalten an","en":"to stick to"},{"de":"begrenzt","en":"limited"},{"de":"ablaufen (läuft ab)","en":"to expire"},{"de":"bekämpfen","en":"to combat"},{"de":"die Ursache, -n","en":"cause"},{"de":"unverändert","en":"unchanged"},{"de":"die Lage, -n","en":"situation"},{"de":"die Gewichtung, -en","en":"weighting"},{"de":"dennoch","en":"nevertheless"},{"de":"gleichwohl","en":"nonetheless"},{"de":"wenngleich","en":"albeit, although"},{"de":"zumal","en":"especially since"},{"de":"insofern als","en":"insofar as"},{"de":"wohingegen","en":"whereas"},{"de":"hingegen","en":"on the other hand"},{"de":"demgegenüber","en":"in contrast"},{"de":"folglich","en":"consequently"},{"de":"infolgedessen","en":"as a result"},{"de":"demzufolge","en":"accordingly"},{"de":"somit","en":"thus"},{"de":"ungeachtet (+ Gen.)","en":"regardless of"},{"de":"nichtsdestotrotz","en":"nonetheless"},{"de":"das Gegenargument, -e","en":"counter-argument"},{"de":"die These, -n","en":"thesis"},{"de":"die Abwägung, -en","en":"weighing up"},{"de":"überzeugend","en":"convincing"},{"de":"einwenden","en":"to object"},{"de":"entkräften","en":"to invalidate (an argument)"}],"reading":"Aus einer Stellungnahme: Zwar hat die Stadt den Radverkehr ausgebaut, jedoch fehlen sichere Abstellplätze. Während in den Außenbezirken neue Wege entstanden sind, blieb das Zentrum weitgehend unverändert. Angesichts steigender Nutzerzahlen ist das problematisch; folglich fordern Verbände ein Gesamtkonzept. Ungeachtet der Kosten sollte die Stadt handeln, zumal Fördermittel zur Verfügung stehen. Im Gegensatz zu anderen Städten fehlt bislang eine klare Priorisierung.","tasks":[{"q":"Konzessiv (Nebensatz): ___ die Kosten hoch sind, lohnt sich das Projekt.","a":"Obwohl"},{"q":"Konzessiv (Adverb): Die Kosten sind hoch. ___ lohnt sich das Projekt.","a":"Trotzdem"},{"q":"Adversativ: Die Preise steigen, ___ die Löhne stagnieren.","a":"während"},{"q":"Konsekutiv (Adverb): Die Nachfrage sank; ___ wurden Stellen gestrichen.","a":"folglich"},{"q":"Präposition + Genitiv: ___ der Kritik hält er am Plan fest.","a":"Ungeachtet"},{"q":"Kausal gehoben: Wir handeln jetzt, ___ die Frist abläuft.","a":"zumal"},{"q":"zwar … jedoch: Das Auto ist teuer. Es ist sparsam.","a":"Zwar ist das Auto teuer, jedoch ist es sparsam."},{"q":"[Mix] ___ steigender Nutzerzahlen ist ein Konzept ___ (erstellen, sein+zu).","a":"Angesichts / zu erstellen"},{"q":"[Mix] Die Verbände fordern, die Stadt ___ handeln. (Konj. I von sollen)","a":"solle"},{"q":"[Mix] Die ___ (ausbauen, Part. II) Wege liegen in den Außenbezirken.","a":"ausgebauten"},{"q":"Konzessiv: Er ist krank. ___ geht er zur Arbeit. (dennoch/folglich)","a":"Dennoch"},{"q":"Konsekutiv: Der Umsatz sank; ___ wurden Stellen gestrichen. (infolgedessen/wohingegen)","a":"infolgedessen"},{"q":"Adversativ: Sie liebt Kaffee, ___ er Tee bevorzugt. (wohingegen/zumal)","a":"wohingegen"},{"q":"Begründung (zusätzlich): Ich bleibe zu Hause, ___ es regnet. (zumal/somit)","a":"zumal"},{"q":"Konzessiv: ___ das Wetter schlecht war, fand das Fest statt. (wenngleich/infolgedessen)","a":"Wenngleich"},{"q":"Präposition + Genitiv: ___ der Bedenken wurde das Projekt gestartet.","a":"Ungeachtet"},{"q":"Satzstellung: Die Kosten sind hoch, dennoch ___ sich das Projekt. (lohnen)","a":"lohnt"},{"q":"Umformen mit obwohl → wenngleich: Obwohl die Idee gut ist, fehlt das Geld. → ___ die Idee gut ist, fehlt das Geld.","a":"Wenngleich"},{"q":"somit oder hingegen? Alle Bedingungen sind erfüllt, ___ kann der Vertrag unterschrieben werden.","a":"somit"},{"q":"Fehler? „Er war müde, dennoch er arbeitete weiter.“","a":"Er war müde, dennoch arbeitete er weiter."}],"exam":[{"q":"Was fehlt trotz des Ausbaus?","a":"Sichere Abstellplätze."},{"q":"Was fordern die Verbände?","a":"Ein Gesamtkonzept."},{"q":"Warum sollte die Stadt handeln?","a":"Weil Fördermittel zur Verfügung stehen."},{"q":"Umformen (Adverb → Nebensatz): Die Preise steigen; folglich sparen viele.","a":"Die Preise steigen, sodass viele sparen."},{"q":"Umformen (Nebensatz → Präposition): Obwohl es regnete, fuhren wir.","a":"Trotz des Regens fuhren wir."},{"q":"Umformen (adversativ): Im Norden regnet es. Im Süden scheint die Sonne.","a":"Im Norden regnet es, wohingegen im Süden die Sonne scheint."},{"q":"Wortstellung prüfen: „Folglich wir haben abgesagt.“","a":"Folglich haben wir abgesagt."},{"q":"Schreiben Sie eine Stellungnahme (100 Wörter) mit je einem konzessiven, adversativen und konsekutiven Konnektor.","a":"","m":"Zwar ist Homeoffice praktisch, jedoch fehlt vielen der Kontakt zu Kollegen. Während junge Mitarbeiter flexibel arbeiten wollen, bevorzugen ältere häufig das Büro. Viele Firmen bieten folglich ein Mischmodell an. Obwohl es Kosten spart, muss die Technik stimmen. Somit ist eine klare Regelung notwendig."},{"q":"Präsentieren Sie zwei Seiten eines Themas mit „zwar … jedoch“.","a":"","m":"Zwar sind Elektroautos leiser und sauberer, jedoch ist ihre Herstellung energieintensiv. Zwar sinken die Preise, jedoch fehlen noch viele Ladestationen."},{"q":"Welche Konnektoren wirken zu formell im Gespräch?","a":"","m":"Im Gespräch wirken „infolgedessen“, „mithin“ und „wohingegen“ zu formell. Man sagt eher „deshalb“, „also“ oder „aber“."}],"speak":["Argumentiere für und gegen Homeoffice (zwar … jedoch, hingegen, folglich).","Vergleiche zwei Städte mit adversativen Konnektoren.","Räume einen Kritikpunkt ein und widersprich trotzdem.","Formuliere eine Konsequenz aus dem Lesetext."],"reading2":{"title":"Erörterung: Sollte die Vier-Tage-Woche zur Regel werden?","text":"Seit einigen Jahren wird in Deutschland über die Einführung der Vier-Tage-Woche diskutiert. Befürworter versprechen sich davon zufriedenere und gesündere Beschäftigte, Kritiker befürchten hingegen Einbußen bei der Wirtschaftsleistung. Im Folgenden sollen beide Positionen gegeneinander abgewogen werden. Für eine Verkürzung der Arbeitszeit spricht zunächst, dass Erschöpfung und psychische Erkrankungen in den vergangenen Jahren deutlich zugenommen haben. Ein zusätzlicher freier Tag könnte hier entlastend wirken. Pilotprojekte in Großbritannien und Deutschland deuten darauf hin, dass die Produktivität kaum sinkt, zumal konzentrierte Arbeit in kürzerer Zeit oft effizienter ist. Darüber hinaus könnten Arbeitgeber, die eine Vier-Tage-Woche anbieten, im Wettbewerb um Fachkräfte punkten. Dennoch dürfen die Gegenargumente nicht unterschätzt werden. In Branchen wie der Pflege, dem Handel oder dem Handwerk lässt sich die Arbeit nicht beliebig verdichten. Ein Krankenhaus muss rund um die Uhr besetzt sein; infolgedessen würde eine kürzere Arbeitszeit dort zusätzliches Personal erfordern, das ohnehin knapp ist. Wenngleich die Ergebnisse der Pilotprojekte ermutigend sind, nahmen daran überwiegend Büro- und Dienstleistungsunternehmen teil, sodass sie nur bedingt verallgemeinerbar sind. Zudem besteht die Gefahr, dass die gleiche Arbeit in weniger Zeit erledigt werden muss, was den Stress eher erhöhen als verringern würde. Wägt man die Argumente ab, so erscheint eine flächendeckende, gesetzlich vorgeschriebene Vier-Tage-Woche derzeit wenig realistisch. Gleichwohl spricht vieles dafür, flexible Modelle dort zu fördern, wo sie praktikabel sind. Nicht die Zahl der Arbeitstage sollte im Mittelpunkt stehen, sondern die Frage, wie Arbeit so gestaltet werden kann, dass Menschen ihr langfristig gewachsen sind."},"dialog":[{"who":"Moderatorin","de":"Herr Krause, Sie sind gegen die Vier-Tage-Woche. Warum?"},{"who":"Herr Krause","de":"Weil wir uns das schlicht nicht leisten können, zumal uns schon heute Hunderttausende Fachkräfte fehlen."},{"who":"Frau Arslan","de":"Das Argument greift zu kurz. Gerade weil Fachkräfte fehlen, müssen Arbeitgeber attraktiver werden."},{"who":"Herr Krause","de":"Attraktiv schon, aber nicht um jeden Preis. Ein Handwerksbetrieb mit fünf Leuten kann nicht einfach einen Tag schließen."},{"who":"Frau Arslan","de":"Das verlangt auch niemand. Wohingegen es in vielen Büros problemlos ginge."},{"who":"Moderatorin","de":"Gibt es denn einen Kompromiss?"},{"who":"Frau Arslan","de":"Ich denke schon. Flexible Modelle, die von Branche zu Branche unterschiedlich sind."},{"who":"Herr Krause","de":"Dem könnte ich mich anschließen, sofern es freiwillig bleibt."}],"dq":[{"q":"Welches Argument nennt Herr Krause?","a":"Wir können es uns nicht leisten, weil schon jetzt viele Fachkräfte fehlen."},{"q":"Wie reagiert Frau Arslan?","a":"Gerade weil Fachkräfte fehlen, müssen Arbeitgeber attraktiver werden."},{"q":"Worauf können sich beide einigen?","a":"Auf flexible Modelle je nach Branche, sofern sie freiwillig sind."}],"en":{"title":"Text cohesion: concessive, adversative, consecutive","theme":"Arguing at C1","expl":["At C1 you connect ideas precisely. **Concession**: obwohl, obgleich, wenngleich, auch wenn, zwar … jedoch, ungeachtet + gen. **Contrast**: während, wohingegen, hingegen, dagegen, vielmehr. **Result**: sodass, folglich, infolgedessen, somit, demnach.","Watch the word order: conjunctions like obwohl send the verb to the end; adverbs like folglich in position 1 take the verb straight after them."],"use":""},"check":[{"re":"\\\\b(obwohl|obgleich|wenngleich|zwar|jedoch|hingegen|wohingegen|dagegen|folglich|infolgedessen|somit|demnach|sodass)\\\\b","label":"concessive / adversative / consecutive connectors"}]},{"n":54,"pos":61,"level":"C1","title":"Nominalisierung, unpersönliche Konstruktionen und „es“","theme":"Wissenschaftlicher Stil","scene":"classroom","rec":[45,46,51],"expl":["Wissenschaftliche und formelle Texte vermeiden persönliche Formen: statt __ich zeige__ → __es wird gezeigt / im Folgenden wird gezeigt / die Untersuchung zeigt__.","**Unpersönliche Mittel:** Passiv, **man**, **es lässt sich zeigen**, **es ist davon auszugehen**, **Nominalisierung** (die Untersuchung, der Nachweis), **Funktionsverbgefüge** (Bezug nehmen auf).","**„es“ hat mehrere Rollen:** echtes Subjekt (__Es regnet__), Platzhalter auf Position 1 (__**Es** wurden viele Fragen gestellt__ → ohne Vorfeld: __Viele Fragen wurden gestellt__), Korrelat zu Nebensätzen (__**Es** ist wichtig, **dass** …__), fester Bestandteil (__es gibt, es geht um, es handelt sich um__).","**Gehobene Verben:** erfolgen, vorliegen, sich ergeben, bestehen in, zurückzuführen sein auf."],"use":"Hausarbeiten, Berichte, Gutachten, C1-Schreibaufgaben.","table":[["Persönlich","Unpersönlich / wissenschaftlich"],["Ich untersuche den Effekt.","Der Effekt **wird untersucht**. / Die vorliegende Arbeit **untersucht** den Effekt."],["Wir haben herausgefunden, dass …","Es **hat sich gezeigt**, dass … / Die Ergebnisse **legen nahe**, dass …"],["Man kann das leicht zeigen.","Das **lässt sich** leicht **zeigen**."],["Wir nehmen an, dass …","**Es ist davon auszugehen**, dass …"],["Die Kosten sind gestiegen, weil …","Der Kostenanstieg **ist zurückzuführen auf** …"],["Ich schreibe über …","**Gegenstand** dieser Arbeit **ist** …"]],"examples":[{"de":"Im Folgenden wird der Zusammenhang dargestellt.","en":"In the following, the connection is presented."},{"de":"Es hat sich gezeigt, dass die Methode robust ist.","en":"It has been shown that the method is robust."},{"de":"Die Untersuchung beruht auf 200 Interviews.","en":"The study is based on 200 interviews."},{"de":"Daraus ergibt sich eine klare Empfehlung.","en":"From this a clear recommendation follows."},{"de":"Es ist davon auszugehen, dass die Zahlen weiter steigen.","en":"It can be assumed the figures will keep rising."},{"de":"Der Anstieg ist auf mehrere Faktoren zurückzuführen.","en":"The increase is attributable to several factors."},{"de":"Es liegen bislang keine belastbaren Daten vor.","en":"To date no robust data are available."},{"de":"Gegenstand der Arbeit ist die Wirkung von Lärm.","en":"The subject of the paper is the effect of noise."},{"de":"Es wurde eine Befragung durchgeführt.","en":"A survey was conducted."},{"de":"Dabei handelt es sich um einen Sonderfall.","en":"This is a special case."},{"de":"Es gilt, die Ursachen genauer zu untersuchen.","en":"It is necessary to examine the causes more closely."},{"de":"Bei dem Phänomen handelt es sich um einen weltweiten Trend.","en":"The phenomenon is a worldwide trend."},{"de":"Es ist davon auszugehen, dass die Zahlen weiter steigen.","en":"It can be assumed that the figures will continue to rise."},{"de":"Anhand von drei Beispielen soll dies verdeutlicht werden.","en":"This will be illustrated by means of three examples."},{"de":"Im Rahmen der Untersuchung wurden 500 Personen befragt.","en":"Within the framework of the investigation, 500 people were interviewed."},{"de":"Die Durchführung der Befragung erfolgte im Frühjahr.","en":"The survey was carried out in spring."},{"de":"Es zeigt sich, dass jüngere Befragte anders antworten.","en":"It becomes apparent that younger respondents answer differently."},{"de":"Es bleibt abzuwarten, ob sich der Trend fortsetzt.","en":"It remains to be seen whether the trend will continue."},{"de":"Die Ergebnisse lassen sich mithilfe einer Grafik darstellen.","en":"The results can be presented with the help of a chart."},{"de":"In Bezug auf das Alter ergaben sich keine Unterschiede.","en":"With regard to age, no differences emerged."}],"vocab":[{"de":"die vorliegende Arbeit","en":"the present paper"},{"de":"darstellen","en":"to present, depict"},{"de":"beruhen auf","en":"to be based on"},{"de":"sich ergeben aus","en":"to result from"},{"de":"zurückzuführen sein auf","en":"to be attributable to"},{"de":"die Befragung, -en","en":"survey"},{"de":"belastbar","en":"robust, reliable"},{"de":"der Gegenstand, ¨e","en":"subject, object"},{"de":"nahelegen","en":"to suggest"},{"de":"bislang","en":"to date"},{"de":"der Sonderfall, ¨e","en":"special case"},{"de":"im Folgenden","en":"in the following"},{"de":"es gilt, … zu …","en":"it is necessary to …"},{"de":"es handelt sich um","en":"it is a matter of"},{"de":"es ist davon auszugehen, dass","en":"it can be assumed that"},{"de":"es lässt sich feststellen, dass","en":"it can be stated that"},{"de":"es zeigt sich, dass","en":"it becomes apparent that"},{"de":"es bleibt abzuwarten, ob","en":"it remains to be seen whether"},{"de":"die Erhebung, -en","en":"survey, data collection"},{"de":"die Fragestellung, -en","en":"research question"},{"de":"die Methodik","en":"methodology"},{"de":"die Auswertung, -en","en":"evaluation"},{"de":"die Erkenntnis, -se","en":"insight, finding"},{"de":"der Forschungsstand","en":"state of research"},{"de":"die Literatur","en":"(academic) literature"},{"de":"herausarbeiten","en":"to work out"},{"de":"untermauern","en":"to support (with evidence)"},{"de":"verdeutlichen","en":"to illustrate"},{"de":"in Bezug auf","en":"with regard to"},{"de":"im Rahmen (+ Gen.)","en":"within the framework of"},{"de":"anhand (+ Gen.)","en":"on the basis of"},{"de":"mithilfe (+ Gen.)","en":"with the help of"}],"reading":"Aus einer Hausarbeit: Gegenstand der vorliegenden Arbeit ist der Einfluss von Homeoffice auf die Produktivität. Zunächst wird der Forschungsstand dargestellt; anschließend werden die Ergebnisse einer eigenen Befragung präsentiert. Es hat sich gezeigt, dass die Effekte stark von der Tätigkeit abhängen. Der beobachtete Produktivitätsgewinn ist vor allem auf weniger Unterbrechungen zurückzuführen. Es ist jedoch davon auszugehen, dass soziale Faktoren langfristig eine größere Rolle spielen. Belastbare Langzeitdaten liegen bislang nicht vor.","tasks":[{"q":"Unpersönlich: Ich zeige im Folgenden … → Im Folgenden ___ ___ …","a":"wird gezeigt"},{"q":"Unpersönlich: Wir nehmen an, dass … → Es ist ___ ___, dass …","a":"davon auszugehen"},{"q":"Unpersönlich: Man kann das beweisen. → Das ___ ___ ___.","a":"lässt sich beweisen"},{"q":"Nominalisieren: Die Kosten steigen. → der ___ der Kosten","a":"Anstieg"},{"q":"Formell: Die Ursache ist die Hitze. → Das Problem ist ___ die Hitze ___.","a":"auf / zurückzuführen"},{"q":"es-Funktion bestimmen: „Es regnet.“","a":"echtes Subjekt"},{"q":"es-Funktion bestimmen: „Es wurden Fragen gestellt.“","a":"Platzhalter im Vorfeld"},{"q":"[Mix] ___ liegen bislang keine Daten ___. (es; vorliegen)","a":"Es / vor"},{"q":"[Mix] Die Autorin schreibt, die Effekte ___ von der Tätigkeit ab. (Konj. I von abhängen)","a":"hingen"},{"q":"[Mix] Die ___ (beobachten, Part. II) Unterschiede sind ___ (erklären, sein+zu).","a":"beobachteten / zu erklären"},{"q":"Nominalisieren: Die Daten wurden im Mai erhoben. → Die ___ der Daten erfolgte im Mai.","a":"Erhebung"},{"q":"Nominalisieren: Man wertete die Ergebnisse aus. → Die ___ der Ergebnisse …","a":"Auswertung"},{"q":"Unpersönlich: Man kann annehmen, dass … → Es ist davon ___, dass …","a":"auszugehen"},{"q":"Unpersönlich: Wir müssen die Ursachen prüfen. → Es ___, die Ursachen zu prüfen.","a":"gilt"},{"q":"Unpersönlich: Man weiß noch nicht, ob … → Es bleibt ___, ob …","a":"abzuwarten"},{"q":"Präposition: ___ von Beispielen wird gezeigt, dass … (anhand/aufgrund)","a":"Anhand"},{"q":"Präposition: ___ der Studie wurden 500 Personen befragt. (Im Rahmen/Mithilfe)","a":"Im Rahmen"},{"q":"„es“ als Platzhalter: ___ handelt sich um ein neues Phänomen.","a":"Es"},{"q":"Passiv statt man: Man befragte 200 Personen. → 200 Personen ___ ___.","a":"wurden befragt"},{"q":"Fehler? „Es handelt sich über ein Problem.“","a":"Es handelt sich um ein Problem."}],"exam":[{"q":"Was ist Gegenstand der Arbeit?","a":"Der Einfluss von Homeoffice auf die Produktivität."},{"q":"Worauf ist der Produktivitätsgewinn zurückzuführen?","a":"Auf weniger Unterbrechungen."},{"q":"Was fehlt bislang?","a":"Belastbare Langzeitdaten."},{"q":"Formeller: „Ich habe 50 Leute gefragt.“","a":"Es wurde eine Befragung von 50 Personen durchgeführt."},{"q":"Formeller: „Das kommt vom Wetter.“","a":"Das ist auf das Wetter zurückzuführen."},{"q":"Persönlicher: „Daraus ergibt sich eine Empfehlung.“","a":"Daraus leiten wir eine Empfehlung ab."},{"q":"Wann darf „es“ wegfallen?","a":"Wenn ein anderes Element auf Position 1 steht (Es wurden Fragen gestellt → Fragen wurden gestellt)."},{"q":"Schreiben Sie eine Einleitung (60 Wörter) für eine Arbeit zu Ihrem Fachgebiet.","a":"","m":"Die vorliegende Arbeit befasst sich mit der Digitalisierung kleiner Unternehmen. Im Folgenden wird untersucht, welche Hindernisse bestehen. Es ist davon auszugehen, dass vor allem Kosten und fehlendes Wissen eine Rolle spielen. Abschließend werden Lösungsansätze diskutiert."},{"q":"Fassen Sie eine Studie unpersönlich zusammen.","a":"","m":"In der Studie wurden 500 Personen befragt. Es zeigte sich, dass die Mehrheit täglich mehrere Stunden online verbringt. Ein Zusammenhang mit Schlafproblemen ließ sich nachweisen."},{"q":"Wann ist der persönliche Stil besser als der unpersönliche?","a":"","m":"Der persönliche Stil ist besser in E-Mails an Kollegen, in Präsentationen und in Erfahrungsberichten, weil er direkter und lebendiger wirkt."}],"speak":["Stelle den Lesetext in zwei Minuten wissenschaftlich vor.","Formuliere dieselbe Aussage dreimal: persönlich, neutral, formell.","Erkläre ein Ergebnis aus deinem Beruf mit „Es hat sich gezeigt, dass …“.","Welche Rolle spielt Objektivität in deinem Fach?"],"reading2":{"title":"Aus einer Seminararbeit: Mehrsprachigkeit im Berufsalltag","text":"Die vorliegende Arbeit befasst sich mit der Frage, welche Rolle Mehrsprachigkeit im Berufsalltag internationaler Unternehmen in Deutschland spielt. Im Mittelpunkt steht dabei die Nutzung des Deutschen neben dem Englischen als Unternehmenssprache. Zunächst wird der aktuelle Forschungsstand dargestellt. Anschließend werden die Methodik sowie die Ergebnisse einer im Rahmen dieser Arbeit durchgeführten Befragung erläutert. Zur Datenerhebung wurde ein Online-Fragebogen eingesetzt, der von 214 Beschäftigten aus zwölf Unternehmen beantwortet wurde. Die Auswertung erfolgte mithilfe deskriptiver Statistik. Bereits ein erster Blick auf die Daten verdeutlicht die Diskrepanz zwischen offizieller und tatsächlicher Sprachpraxis: Obwohl in neun der zwölf Unternehmen Englisch als Konzernsprache festgelegt ist, gaben 68 Prozent der Befragten an, im informellen Austausch mit Kolleginnen und Kollegen überwiegend Deutsch zu verwenden. Es zeigt sich zudem, dass mangelnde Deutschkenntnisse in Bezug auf die soziale Integration als hinderlich empfunden werden. So berichten Beschäftigte ohne Deutschkenntnisse signifikant häufiger davon, sich bei Gesprächen in der Kaffeeküche oder bei Betriebsfeiern ausgeschlossen zu fühlen. Für die berufliche Leistung hingegen scheint die Sprache eine geringere Rolle zu spielen; hier ließen sich keine nennenswerten Unterschiede feststellen. Es ist allerdings davon auszugehen, dass die Ergebnisse durch die Art der Stichprobe beeinflusst sind, da vor allem Beschäftigte aus der IT-Branche teilgenommen haben. Abschließend lässt sich festhalten, dass Englisch zwar die formale Zusammenarbeit ermöglicht, Deutsch jedoch für das Zugehörigkeitsgefühl von erheblicher Bedeutung bleibt. Es gilt daher, Sprachangebote am Arbeitsplatz nicht als Zusatzleistung, sondern als Teil der Personalentwicklung zu verstehen."},"dialog":[{"who":"Betreuerin","de":"Frau Ahmadi, ich habe Ihre Gliederung gelesen. Die Fragestellung ist gut, aber noch zu breit."},{"who":"Leila","de":"Was würden Sie vorschlagen?"},{"who":"Betreuerin","de":"Konzentrieren Sie sich auf einen Aspekt, etwa auf die Kommunikation zwischen Ärzten und Pflegepersonal."},{"who":"Leila","de":"Das wäre machbar. Ich könnte im Rahmen meiner Arbeit im Krankenhaus Interviews führen."},{"who":"Betreuerin","de":"Sehr gut. Achten Sie aber darauf, dass Sie die Methodik sauber begründen. Es handelt sich ja um eine qualitative Untersuchung."},{"who":"Leila","de":"Wie viele Interviews wären angemessen?"},{"who":"Betreuerin","de":"Acht bis zehn reichen. Wichtiger ist eine gründliche Auswertung anhand klarer Kategorien."},{"who":"Leila","de":"Verstanden. Ich überarbeite die Gliederung bis nächste Woche."}],"dq":[{"q":"Was kritisiert die Betreuerin?","a":"Die Fragestellung ist noch zu breit."},{"q":"Worauf soll Leila sich konzentrieren?","a":"Auf die Kommunikation zwischen Ärzten und Pflegepersonal."},{"q":"Wie viele Interviews reichen?","a":"Acht bis zehn."}],"en":{"title":"Nominalisation, impersonal constructions and \\"es\\"","theme":"Academic style","expl":["Academic and formal texts avoid personal forms: instead of __ich zeige__ → __es wird gezeigt / im Folgenden wird gezeigt / die Untersuchung zeigt__.","Impersonal tools: passive, man, __es lässt sich zeigen__, __es ist davon auszugehen, dass__, nominalisation (__die Untersuchung, der Nachweis__) and noun–verb phrases (__Bezug nehmen auf__).","**es** can be a placeholder subject that disappears when something else takes position 1: __Es kamen viele Gäste. → Viele Gäste kamen.__"],"use":""},"check":[{"re":"\\\\b(es wird|wird gezeigt|lässt sich|es ist davon auszugehen|im folgenden|die untersuchung|der vorliegende|man)\\\\b","label":"impersonal style (es wird gezeigt, im Folgenden …)"}]},{"n":55,"pos":62,"level":"C1","title":"Präzision: Wortfelder, Kollokationen und Synonyme","theme":"Wortschatzarbeit","scene":"city","rec":[22,44,53],"expl":["Auf C1 zählt nicht Menge, sondern **Präzision**: Welches Wort passt zu welchem Kontext?","**Kollokationen** sind feste Partner: __eine Entscheidung **treffen** (nicht machen), Maßnahmen **ergreifen**, Kritik **üben**, einen Termin **wahrnehmen**, ein Problem **beheben**, Interesse **wecken**__.","**Synonyme unterscheiden sich im Register und in der Nuance**: __groß – erheblich – gewaltig__; __schnell – zügig – rasant__; __sagen – äußern – behaupten – betonen__.","**Wortfamilien** helfen: prüfen → die Prüfung, der Prüfer, prüfbar, überprüfen, nachprüfen. Bei Verben mit Vorsilbe verschiebt sich die Bedeutung: __suchen – besuchen – versuchen – untersuchen__."],"use":"Genauer schreiben und sprechen, typische Wortwahlfehler vermeiden.","table":[["Falsch üblich","Richtig (Kollokation)","Bereich"],["eine Entscheidung machen","eine Entscheidung **treffen**","Beruf"],["Kritik machen","Kritik **üben**","Diskussion"],["einen Termin machen (ok) / haben","einen Termin **wahrnehmen** (formell)","Verwaltung"],["ein Problem machen","ein Problem **lösen / beheben**","Technik"],["Maßnahmen machen","Maßnahmen **ergreifen**","Politik"],["Aufmerksamkeit geben","Aufmerksamkeit **schenken**","Allgemein"],["eine Frage machen","eine Frage **stellen**","Allgemein"],["Interesse machen","Interesse **wecken**","Marketing"]],"examples":[{"de":"Wir müssen geeignete Maßnahmen ergreifen.","en":"We have to take suitable measures."},{"de":"Der Bericht übt deutliche Kritik an dem Verfahren.","en":"The report clearly criticises the procedure."},{"de":"Bitte schenken Sie dem Hinweis Beachtung.","en":"Please pay attention to the note."},{"de":"Der Fehler konnte schnell behoben werden.","en":"The error could be fixed quickly."},{"de":"Die Kampagne weckte großes Interesse.","en":"The campaign aroused great interest."},{"de":"Die Kosten fallen erheblich ins Gewicht.","en":"The costs carry considerable weight."},{"de":"Er äußerte sich zurückhaltend zu den Plänen.","en":"He commented cautiously on the plans."},{"de":"Die Zahlen weichen deutlich voneinander ab.","en":"The figures differ significantly."},{"de":"Das Angebot richtet sich an Fachkräfte.","en":"The offer is aimed at skilled workers."},{"de":"Wir legen großen Wert auf Pünktlichkeit.","en":"We attach great importance to punctuality."},{"de":"Die Regierung muss endlich Maßnahmen ergreifen.","en":"The government must finally take measures."},{"de":"Der Bericht wirft eine Reihe von Fragen auf.","en":"The report raises a number of questions."},{"de":"Die Opposition übte scharfe Kritik an dem Gesetz.","en":"The opposition sharply criticised the law."},{"de":"Die Technikerin konnte das Problem schnell beheben.","en":"The technician was able to fix the problem quickly."},{"de":"Im Praktikum habe ich wertvolle Erfahrungen gesammelt.","en":"During the internship I gained valuable experience."},{"de":"Für eine Einigung müssen beide Seiten einen Kompromiss eingehen.","en":"For an agreement both sides must make a compromise."},{"de":"Der Vorschlag fand bei den Mitarbeitern großen Anklang.","en":"The proposal met with great approval among the staff."},{"de":"Die Verspätung hatte zur Folge, dass viele den Anschluss verpassten.","en":"The delay resulted in many missing their connection."},{"de":"Für die schöne Lage nehmen wir die hohe Miete in Kauf.","en":"We accept the high rent for the nice location."},{"de":"Mit dem neuen Konzept soll Abhilfe geschaffen werden.","en":"The new concept is intended to provide a remedy."}],"vocab":[{"de":"die Kollokation, -en","en":"collocation"},{"de":"das Register, -","en":"register (style level)"},{"de":"die Nuance, -n","en":"nuance"},{"de":"abweichen von","en":"to deviate from"},{"de":"sich richten an","en":"to be aimed at"},{"de":"Beachtung schenken","en":"to pay attention"},{"de":"beheben","en":"to fix, remedy"},{"de":"ergreifen","en":"to take (measures)"},{"de":"zurückhaltend","en":"reserved, cautious"},{"de":"gewaltig","en":"enormous"},{"de":"zügig","en":"swift"},{"de":"erheblich","en":"considerable"},{"de":"eine Frage aufwerfen","en":"to raise a question"},{"de":"ein Problem beheben","en":"to fix a problem"},{"de":"Kritik üben","en":"to criticise"},{"de":"Bedenken äußern","en":"to voice concerns"},{"de":"eine Lösung erarbeiten","en":"to work out a solution"},{"de":"einen Beitrag leisten","en":"to make a contribution"},{"de":"Maßnahmen ergreifen","en":"to take measures"},{"de":"Anforderungen erfüllen","en":"to meet requirements"},{"de":"einen Kompromiss eingehen","en":"to make a compromise"},{"de":"eine Krise bewältigen","en":"to overcome a crisis"},{"de":"Vertrauen gewinnen","en":"to gain trust"},{"de":"Fortschritte erzielen","en":"to make progress"},{"de":"Erfahrungen sammeln","en":"to gain experience"},{"de":"Wissen erwerben","en":"to acquire knowledge"},{"de":"eine Gelegenheit ergreifen","en":"to seize an opportunity"},{"de":"Interesse wecken","en":"to arouse interest"},{"de":"in Kauf nehmen","en":"to accept (a disadvantage)"},{"de":"zur Folge haben","en":"to result in"},{"de":"Abhilfe schaffen","en":"to provide a remedy"},{"de":"Anklang finden","en":"to meet with approval"}],"reading":"Aus einem Projektbericht: Das Team hat geeignete Maßnahmen ergriffen, um die Verzögerungen zu beheben. Zunächst wurde eine Bestandsaufnahme durchgeführt; anschließend traf die Leitung eine Entscheidung über die Prioritäten. Kritik übten die Kunden vor allem an der Kommunikation. Daher legt das Team künftig großen Wert auf regelmäßige Rückmeldungen. Die Ergebnisse weichen zwar noch vom Plan ab, doch die Tendenz ist eindeutig positiv.","tasks":[{"q":"Kollokation: eine Entscheidung ___","a":"treffen"},{"q":"Kollokation: Maßnahmen ___","a":"ergreifen"},{"q":"Kollokation: Kritik ___ an","a":"üben"},{"q":"Kollokation: ein Problem ___","a":"beheben / lösen"},{"q":"Kollokation: Wert ___ auf","a":"legen"},{"q":"Kollokation: eine Frage ___","a":"stellen"},{"q":"Präziser als „groß“ (formell): Die Kosten sind ___.","a":"erheblich"},{"q":"[Mix] Die Leitung ___ eine Entscheidung ___ (treffen, Perfekt).","a":"hat / getroffen"},{"q":"[Mix] Die Ergebnisse, ___ vom Plan abweichen, werden geprüft. (Relativpronomen)","a":"die"},{"q":"[Mix] ___ der Verzögerungen wurden Maßnahmen ergriffen. (Genitivpräposition)","a":"Angesichts / Wegen"},{"q":"Kollokation: Maßnahmen ___ (ergreifen/machen)","a":"ergreifen"},{"q":"Kollokation: einen Beitrag ___ (leisten/geben)","a":"leisten"},{"q":"Kollokation: Kritik ___ an (üben/machen)","a":"üben"},{"q":"Kollokation: Erfahrungen ___ (sammeln/machen, formeller)","a":"sammeln"},{"q":"Kollokation: eine Krise ___ (bewältigen/lösen)","a":"bewältigen"},{"q":"Kollokation: Interesse ___ (wecken/bringen)","a":"wecken"},{"q":"Kollokation: Fortschritte ___ (erzielen/bekommen)","a":"erzielen"},{"q":"Register: „kriegen“ formell →","a":"erhalten"},{"q":"Synonym (stärker): eine spürbare Verbesserung → eine ___ Verbesserung (erhebliche/leichte)","a":"erhebliche"},{"q":"Fehler? „Wir müssen eine Entscheidung machen.“","a":"Wir müssen eine Entscheidung treffen."}],"exam":[{"q":"Warum übten die Kunden Kritik?","a":"Wegen der Kommunikation."},{"q":"Was macht das Team künftig?","a":"Es legt Wert auf regelmäßige Rückmeldungen."},{"q":"Wie ist die Tendenz?","a":"Eindeutig positiv."},{"q":"Verbessern: „Wir haben eine Entscheidung gemacht.“","a":"Wir haben eine Entscheidung getroffen."},{"q":"Verbessern: „Er hat Kritik gemacht.“","a":"Er hat Kritik geübt."},{"q":"Synonym mit höherem Register für „sagen“ (vorsichtig):","a":"sich äußern"},{"q":"Unterschied: untersuchen – versuchen – besuchen","a":"to investigate – to try – to visit"},{"q":"Schreiben Sie fünf Sätze aus Ihrem Beruf mit typischen Kollokationen.","a":"","m":"Wir müssen schnell Maßnahmen ergreifen. Der Chef hat eine Entscheidung getroffen. Ich nehme morgen einen Termin beim Kunden wahr. Wir beheben das Problem bis Freitag. Unser Produkt soll Interesse wecken."},{"q":"Ersetzen Sie in einem eigenen Text fünf vage Wörter durch präzise.","a":"","m":"„Das ist ein großes Problem“ → „Das ist ein gravierendes Problem.“ „Wir machen eine Entscheidung“ → „Wir treffen eine Entscheidung.“ „Die Sache ist gut“ → „Die Lösung ist überzeugend.“"},{"q":"Welche Wortwahlfehler machen Sie am häufigsten?","a":"","m":"Ich sage oft „machen“, wo ein genaueres Verb passt, zum Beispiel „eine Pause machen“ statt „eine Pause einlegen“ im formellen Text."}],"speak":["Beschreibe die Stadtszene mit möglichst präzisen Verben.","Erzähle von einem Projekt mit fünf Kollokationen.","Formuliere dieselbe Kritik dreimal: direkt, neutral, diplomatisch.","Welche deutschen Wörter verwechselst du oft? Erkläre den Unterschied."],"reading2":{"title":"Wortschatz präzise wählen: Warum „machen“ nicht immer reicht","text":"In der Alltagssprache lässt sich vieles mit wenigen Verben ausdrücken. Man macht eine Pause, macht einen Fehler, macht einen Vorschlag. Wer jedoch auf C1-Niveau schreibt, wird schnell merken, dass solche Allzweckverben in anspruchsvollen Texten blass und ungenau wirken. Prüferinnen und Prüfer achten deshalb besonders auf feste Wortverbindungen, sogenannte Kollokationen. Eine Kollokation ist eine typische Kombination von Wörtern, die Muttersprachler intuitiv verwenden: Man trifft eine Entscheidung, man stellt eine Frage, man leistet einen Beitrag. Grammatisch wären auch andere Verben denkbar, doch sie klingen falsch. Wer „eine Entscheidung macht“, wird zwar verstanden, verrät sich aber als Lernender, vermutlich weil er aus dem Englischen übersetzt. Ebenso wichtig ist die Unterscheidung zwischen Synonymen, die sich in Bedeutung oder Stil unterscheiden. „Bekommen“, „erhalten“ und „kriegen“ bedeuten im Kern dasselbe, gehören aber unterschiedlichen Registern an: „Kriegen“ ist umgangssprachlich, „erhalten“ eher formell. In einem Bewerbungsschreiben wirkt „Ich habe Ihre Antwort gekriegt“ daher unangemessen. Auch scheinbar gleichbedeutende Adjektive können feine Unterschiede aufweisen: Eine „erhebliche“ Verbesserung ist deutlicher als eine „spürbare“, eine „gewaltige“ Herausforderung größer als eine „beträchtliche“. Wie lässt sich dieser Wortschatz aufbauen? Bewährt hat sich, Wörter nie isoliert, sondern stets mit ihren typischen Partnern zu lernen: nicht nur „Kritik“, sondern „Kritik üben an“, nicht nur „Maßnahme“, sondern „Maßnahmen ergreifen“. Einsprachige Wörterbücher wie das Digitale Wörterbuch der deutschen Sprache zeigen zu jedem Wort häufige Verbindungen aus echten Texten. Wer beim Lesen von Zeitungsartikeln gezielt auf solche Kombinationen achtet und sie notiert, erweitert seinen aktiven Wortschatz deutlich schneller als mit herkömmlichen Vokabellisten."},"dialog":[{"who":"Aiko","de":"Leila, kannst du mal meinen Text lesen? Ich habe das Gefühl, dass er irgendwie einfach klingt."},{"who":"Leila","de":"Klar. Hier schreibst du: „Die Firma hat viele Probleme gemacht, um die Krise zu stoppen.“"},{"who":"Aiko","de":"Ist das falsch?"},{"who":"Leila","de":"Nicht falsch, aber unpräzise. Besser wäre: „Die Firma hat zahlreiche Maßnahmen ergriffen, um die Krise zu bewältigen.“"},{"who":"Aiko","de":"Ah, „Maßnahmen ergreifen“ und „eine Krise bewältigen“. Das klingt viel professioneller."},{"who":"Leila","de":"Und hier: „Die Idee hat den Mitarbeitern gut gefallen.“ Da könntest du sagen: „Die Idee fand großen Anklang.“"},{"who":"Aiko","de":"Wo lernt man solche Ausdrücke?"},{"who":"Leila","de":"Beim Zeitungslesen. Ich schreibe mir jede Woche zehn Kollokationen auf."}],"dq":[{"q":"Was ist an Aikos erstem Satz problematisch?","a":"Er ist unpräzise (nicht falsch)."},{"q":"Wie lautet Leilas Verbesserung?","a":"„Die Firma hat zahlreiche Maßnahmen ergriffen, um die Krise zu bewältigen.“"},{"q":"Wie lernt Leila solche Ausdrücke?","a":"Beim Zeitungslesen; sie notiert jede Woche zehn Kollokationen."}],"en":{"title":"Precision: word fields, collocations and synonyms","theme":"Vocabulary work","expl":["At C1 what counts is not quantity but **precision**: which word fits which context?","**Collocations** are fixed partners: __eine Entscheidung treffen__ (not machen), __Maßnahmen ergreifen__ (take measures), __Kritik üben__ (criticise), __einen Termin wahrnehmen__ (keep an appointment), __ein Problem beheben__ (fix a problem).","Synonyms differ in **register and nuance**: groß – riesig – gewaltig – beträchtlich are not interchangeable."],"use":""},"check":[{"re":"\\\\b(treffen|ergreifen|üben|wahrnehmen|beheben|wecken|erheben|leisten|einlegen|stellen)\\\\b","label":"collocations (eine Entscheidung treffen, Maßnahmen ergreifen …)"}]},{"n":56,"pos":63,"level":"C1","title":"Textsorten: Erörterung, Zusammenfassung, Stellungnahme","theme":"Schreiben auf C1","scene":"office","rec":[42,53,54],"expl":["**Zusammenfassung:** Einleitungssatz mit Textsorte, Autor, Titel, Thema; dann die Hauptaussagen **in eigenen Worten**, im **Präsens**, ohne Beispiele und ohne eigene Meinung; **indirekte Rede** für Aussagen des Autors.","**Erörterung:** Einleitung (Thema, Relevanz) → Argumente pro mit Beleg und Beispiel → Argumente contra → Abwägung → eigener Standpunkt.","**Stellungnahme:** Bezug auf den Anlass → eigene Position → zwei bis drei begründete Argumente → Vorschlag/Forderung → höflicher Schluss.","Struktur sichtbar machen mit **Gliederungssignalen**: __zunächst, darüber hinaus, andererseits, abschließend, zusammenfassend__."],"use":"C1-Schreibprüfung, Hausarbeiten, Leserbriefe, berufliche Stellungnahmen.","table":[["Funktion","Redemittel"],["Einleitung (Zusammenfassung)","In dem Artikel „…“ von … (erschienen am …) geht es um …"],["Hauptaussage","Der Autor vertritt die Ansicht, dass … · Laut Text …"],["Pro","Dafür spricht, dass … · Ein wichtiges Argument ist …"],["Contra","Dagegen lässt sich einwenden, dass … · Kritiker führen an, dass …"],["Abwägen","Einerseits … andererseits … · Zwar …, jedoch …"],["Eigene Position","Meines Erachtens … · Ich vertrete den Standpunkt, dass …"],["Beispiel/Beleg","Dies zeigt sich daran, dass … · Ein Beispiel hierfür ist …"],["Schluss","Zusammenfassend lässt sich sagen, dass … · Abschließend fordere ich …"]],"examples":[{"de":"In dem Artikel geht es um die Folgen der Digitalisierung für kleine Betriebe.","en":"The article deals with the consequences of digitalisation for small businesses."},{"de":"Der Autor vertritt die Ansicht, dass Weiterbildung entscheidend sei.","en":"The author takes the view that further training is decisive."},{"de":"Dafür spricht, dass Betriebe mit Schulungen seltener Fachkräfte verlieren.","en":"In favour of this is that companies with training lose skilled workers less often."},{"de":"Dagegen lässt sich einwenden, dass die Kosten hoch sind.","en":"Against this one can object that the costs are high."},{"de":"Einerseits spart Technik Zeit, andererseits erfordert sie Einarbeitung.","en":"On the one hand technology saves time, on the other it requires training."},{"de":"Meines Erachtens überwiegen die Vorteile deutlich.","en":"In my view the advantages clearly predominate."},{"de":"Dies zeigt sich daran, dass viele Betriebe bereits investieren.","en":"This is shown by the fact that many companies are already investing."},{"de":"Zusammenfassend lässt sich sagen, dass beide Seiten Argumente haben.","en":"In summary, both sides have arguments."},{"de":"Abschließend fordere ich eine bessere Förderung.","en":"Finally, I call for better funding."},{"de":"Aus den genannten Gründen halte ich den Vorschlag für sinnvoll.","en":"For the reasons given I consider the proposal sensible."},{"de":"Eingangs möchte ich die zentrale Frage skizzieren.","en":"At the beginning I would like to outline the central question."},{"de":"Im Folgenden werden die wichtigsten Argumente dargestellt.","en":"In what follows the most important arguments are presented."},{"de":"Des Weiteren ist zu berücksichtigen, dass die Kosten steigen.","en":"Furthermore it has to be taken into account that the costs are rising."},{"de":"Nicht zuletzt spielt auch der Umweltschutz eine Rolle.","en":"Not least, environmental protection also plays a role."},{"de":"Der Verfasser vertritt die These, dass Bildung der Schlüssel sei.","en":"The author advocates the thesis that education is the key."},{"de":"Zusammenfassend lässt sich sagen, dass die Vorteile überwiegen.","en":"In summary one can say that the advantages outweigh."},{"de":"In Anbetracht der Umstände ist dies ein gutes Ergebnis.","en":"In view of the circumstances this is a good result."},{"de":"Vor diesem Hintergrund erscheint die Entscheidung nachvollziehbar.","en":"Against this background the decision seems understandable."},{"de":"Meines Erachtens greift diese Argumentation zu kurz.","en":"In my opinion this line of argument falls short."},{"de":"Es sei darauf hingewiesen, dass die Daten veraltet sind.","en":"It should be pointed out that the data are outdated."}],"vocab":[{"de":"die Erörterung, -en","en":"discursive essay"},{"de":"die Zusammenfassung, -en","en":"summary"},{"de":"die Stellungnahme, -n","en":"position statement"},{"de":"der Beleg, -e","en":"evidence"},{"de":"anführen","en":"to cite, put forward"},{"de":"einwenden","en":"to object"},{"de":"abwägen","en":"to weigh up"},{"de":"überwiegen","en":"to predominate"},{"de":"meines Erachtens","en":"in my opinion"},{"de":"der Anlass, ¨e","en":"occasion, reason"},{"de":"die Forderung, -en","en":"demand"},{"de":"gliedern","en":"to structure"},{"de":"die These, -n","en":"thesis"},{"de":"die Antithese, -n","en":"antithesis"},{"de":"die Synthese, -n","en":"synthesis"},{"de":"die Leserschaft","en":"readership"},{"de":"der Kommentar, -e","en":"commentary"},{"de":"die Rezension, -en","en":"review"},{"de":"die Inhaltsangabe, -n","en":"summary of content"},{"de":"der Leserbrief, -e","en":"letter to the editor"},{"de":"die Kernaussage, -n","en":"key statement"},{"de":"die Argumentationskette, -n","en":"chain of argument"},{"de":"die Überleitung, -en","en":"transition"},{"de":"eingangs","en":"at the beginning"},{"de":"im Folgenden","en":"in what follows"},{"de":"des Weiteren","en":"furthermore"},{"de":"nicht zuletzt","en":"not least"},{"de":"abschließend","en":"in conclusion"},{"de":"es sei darauf hingewiesen, dass","en":"it should be pointed out that"},{"de":"der Verfasser / die Verfasserin","en":"the author"},{"de":"in Anbetracht (+ Gen.)","en":"in view of"},{"de":"vor diesem Hintergrund","en":"against this background"}],"reading":"Leserbrief: „Mit Interesse habe ich Ihren Artikel vom 12. Mai gelesen. Der Autor vertritt die Ansicht, dass kostenloser Nahverkehr die Städte entlasten würde. Dafür spricht, dass Familien entlastet und Emissionen gesenkt würden. Dagegen lässt sich jedoch einwenden, dass ohne Ausbau der Strecken volle Busse niemanden überzeugen. Meines Erachtens sollte zunächst in Kapazität investiert werden; erst danach ist eine Preisreform sinnvoll. Abschließend fordere ich eine transparente Kostenrechnung.“","tasks":[{"q":"Redemittel Einleitung: In dem Artikel „…“ ___ ___ ___ …","a":"geht es um"},{"q":"Redemittel Pro: ___ ___, dass die Kosten sinken.","a":"Dafür spricht"},{"q":"Redemittel Contra: ___ ___ ___ ___, dass die Qualität leidet.","a":"Dagegen lässt sich einwenden"},{"q":"Redemittel Meinung: ___ ___ überwiegen die Vorteile.","a":"Meines Erachtens"},{"q":"Redemittel Schluss: ___ lässt sich sagen, dass …","a":"Zusammenfassend"},{"q":"Indirekte Rede: „Die Preise sinken“, schreibt der Autor. → Der Autor schreibt, die Preise ___.","a":"sänken / würden sinken"},{"q":"Reihenfolge Erörterung: Meinung / Contra / Einleitung / Pro / Schluss","a":"Einleitung, Pro, Contra, Meinung, Schluss"},{"q":"[Mix] ___ des hohen Aufwands ist der Plan ___ (umsetzen, sein+zu).","a":"Trotz / umzusetzen"},{"q":"[Mix] Der Autor betont, kostenloser Nahverkehr ___ die Städte entlasten. (Konj. I von werden)","a":"werde"},{"q":"[Mix] Die ___ (senken, Part. II) Emissionen sprechen für den Vorschlag.","a":"gesenkten"},{"q":"Einleitung: ___ möchte ich die Frage kurz umreißen. (Eingangs/Abschließend)","a":"Eingangs"},{"q":"Überleitung: ___ ___ werden die Argumente dargestellt. (im Folgenden)","a":"Im Folgenden"},{"q":"Ergänzung: Des ___ ist zu bedenken, dass …","a":"Weiteren"},{"q":"Gewichtung: Nicht ___ spielt das Geld eine Rolle.","a":"zuletzt"},{"q":"Eigene Meinung: Meines ___ ist das falsch.","a":"Erachtens"},{"q":"Schluss: ___ lässt sich sagen, dass … (zusammenfassen)","a":"Zusammenfassend"},{"q":"Einräumen: Diese Bedenken sind ___ berechtigt. Gleichwohl … (durchaus/niemals)","a":"durchaus"},{"q":"Hinweis: Es sei darauf ___, dass …","a":"hingewiesen"},{"q":"Kontext: Vor diesem ___ erscheint die Entscheidung logisch.","a":"Hintergrund"},{"q":"Fehler? „Meiner Erachtens ist die These falsch.“","a":"Meines Erachtens ist die These falsch."}],"exam":[{"q":"Worum geht es im Leserbrief?","a":"Um kostenlosen Nahverkehr."},{"q":"Welches Gegenargument nennt der Schreiber?","a":"Ohne Streckenausbau überzeugen volle Busse niemanden."},{"q":"Was fordert er abschließend?","a":"Eine transparente Kostenrechnung."},{"q":"Nennen Sie drei Gliederungssignale für den Hauptteil.","a":"z. B. zunächst, darüber hinaus, andererseits"},{"q":"Formulieren Sie einen Einleitungssatz für eine Zusammenfassung.","a":"z. B. In dem Artikel „…“ von … geht es um …"},{"q":"Was gehört NICHT in eine Zusammenfassung?","a":"Eigene Meinung, Beispiele, wörtliche Zitate"},{"q":"Schreiben Sie eine Stellungnahme (120 Wörter) zu: „Sollten Firmen vier Tage pro Woche arbeiten?“","a":"","m":"Eine Viertagewoche hat Vorteile. Zunächst sind die Mitarbeiter erholter und motivierter. Darüber hinaus wird die Firma für Bewerber attraktiver. Andererseits ist sie nicht in jeder Branche möglich, etwa in Krankenhäusern. Meines Erachtens sollten Firmen das Modell testen, bevor sie entscheiden."},{"q":"Fassen Sie den Lesetext in drei Sätzen zusammen (indirekte Rede).","a":"","m":"In dem Text geht es um die Viertagewoche. Der Autor berichtet, viele Firmen hätten gute Erfahrungen gemacht. Er betont jedoch, das Modell passe nicht zu jeder Branche."},{"q":"Erörtern Sie mündlich: Studiengebühren – ja oder nein?","a":"","m":"Einerseits sind Studiengebühren gerecht, weil Akademiker später mehr verdienen. Andererseits schrecken sie Kinder aus ärmeren Familien ab. Abschließend bin ich gegen Studiengebühren."},{"q":"Welche Textsorte fällt Ihnen schwer? Warum?","a":"","m":"Die Erörterung fällt mir schwer, weil ich beide Seiten ausgewogen darstellen muss."}],"speak":["Halte eine 3-Minuten-Erörterung zu „Homeoffice für alle?“.","Fasse eine Nachricht von heute in vier Sätzen zusammen.","Formuliere eine höfliche, aber klare Forderung an eine Behörde.","Wie strukturierst du deine Argumente, wenn du wenig Zeit hast?"],"reading2":{"title":"Musterlösung: Stellungnahme zu einem Leserbrief","text":"Aufgabe: In einem Leserbrief fordert ein Leser, Smartphones an Schulen vollständig zu verbieten. Nehmen Sie Stellung. In seinem Leserbrief vom 12. März vertritt Herr Dietrich die These, Smartphones hätten an Schulen nichts verloren und sollten daher vollständig verboten werden. Er begründet dies vor allem mit der mangelnden Konzentration der Schülerinnen und Schüler sowie mit der Zunahme von Cybermobbing. Diese Bedenken sind meines Erachtens durchaus berechtigt. Zahlreiche Lehrkräfte berichten, dass Benachrichtigungen den Unterricht stören und Pausen zunehmend schweigend vor dem Bildschirm verbracht werden. Auch der Zusammenhang zwischen ständiger Erreichbarkeit und Mobbing ist gut dokumentiert. Insofern ist der Wunsch nach klaren Regeln nachvollziehbar. Gleichwohl halte ich ein generelles Verbot für den falschen Weg. Erstens gehört der verantwortungsvolle Umgang mit digitalen Medien zu den Kompetenzen, die Schule vermitteln sollte. Ein Verbot verlagert dieses Lernen lediglich in den unbeaufsichtigten Raum außerhalb der Schule. Zweitens lassen sich Smartphones sinnvoll im Unterricht einsetzen, etwa für Recherchen, Vokabeltrainer oder Lernvideos. Drittens ist ein vollständiges Verbot in der Praxis kaum durchsetzbar und führt erfahrungsgemäß eher zu heimlicher Nutzung. Vor diesem Hintergrund plädiere ich für einen Mittelweg: Während des Unterrichts sollten Smartphones grundsätzlich ausgeschaltet bleiben, es sei denn, die Lehrkraft setzt sie gezielt ein. Für die Pausen könnten Schulen handyfreie Zonen einrichten, ohne die Nutzung ganz zu untersagen. Nicht zuletzt sollte Medienbildung fest im Lehrplan verankert werden. Abschließend lässt sich festhalten: Herr Dietrich benennt reale Probleme, doch seine Lösung greift zu kurz. Nicht das Gerät ist das Problem, sondern der Umgang damit – und diesen können Kinder nur lernen, wenn man ihn ihnen beibringt."},"dialog":[{"who":"Prüferin","de":"Sie haben in Ihrer Stellungnahme einen Mittelweg vorgeschlagen. Können Sie das kurz begründen?"},{"who":"Kandidat","de":"Gern. Ein Verbot löst das Problem meines Erachtens nicht, es verschiebt es nur."},{"who":"Prüferin","de":"Aber wäre ein Verbot nicht zumindest einfacher umzusetzen?"},{"who":"Kandidat","de":"Auf den ersten Blick ja. Allerdings zeigen Erfahrungen aus anderen Ländern, dass viele Schüler die Geräte dann heimlich nutzen."},{"who":"Prüferin","de":"Welches Argument halten Sie für das stärkste?"},{"who":"Kandidat","de":"Dass Medienkompetenz gelernt werden muss. Und wo, wenn nicht in der Schule?"},{"who":"Prüferin","de":"Danke. Das war gut strukturiert und überzeugend."}],"dq":[{"q":"Was schlägt der Kandidat vor?","a":"Einen Mittelweg statt eines Verbots."},{"q":"Warum ist ein Verbot laut Kandidat problematisch?","a":"Es verschiebt das Problem nur; viele Schüler nutzen die Geräte dann heimlich."},{"q":"Welches Argument hält er für das stärkste?","a":"Dass Medienkompetenz (in der Schule) gelernt werden muss."}],"en":{"title":"Text types: argumentative essay, summary, statement","theme":"Writing at C1","expl":["**Summary**: an opening sentence with text type, author, title and topic; then the main points in your own words, in the present tense, without examples or your own opinion; reported speech for the author\'s claims.","**Argumentative essay (Erörterung)**: introduction (topic, relevance) → arguments for, with evidence and examples → arguments against → weighing up → your own position.","**Statement (Stellungnahme)**: your clear position from the start, supported by arguments, and a conclusion or recommendation."],"use":""},"check":[{"re":"\\\\b(zunächst|darüber hinaus|andererseits|einerseits|zusammenfassend|abschließend|meines erachtens|in dem artikel|geht es um)\\\\b","label":"text structure signals (zunächst, darüber hinaus, abschließend)"}]},{"n":68,"pos":64,"level":"C1","title":"Redewiedergabe im Bericht: Konjunktiv I, Ersatzformen und redeeinleitende Verben","theme":"Medien und Politik","scene":"office","rec":[43,51],"expl":["In Berichten trennt man die **eigene Aussage** von der **wiedergegebenen**: Der **Konjunktiv I** signalisiert „Das hat jemand gesagt – ich gebe es neutral wieder“. __Der Minister erklärte, die Lage sei stabil.__ Ist der Konjunktiv I mit dem Indikativ identisch (meist in der 1. Person Singular und im Plural), steht der **Konjunktiv II**: __Sie sagten, sie hätten (nicht: haben) keine Informationen.__","Präzision entsteht durch das **redeeinleitende Verb**: __behaupten__ (Zweifel), __einräumen/zugeben__ (Zugeständnis), __betonen/unterstreichen__ (Gewicht), __bestreiten/dementieren__ (Verneinung), __kritisieren, warnen, fordern, ankündigen, versichern__. Das Verb bewertet die Aussage – oft wichtiger als der Konjunktiv.","Weitere Mittel der Distanz: **sollen** (__Der Politiker soll Geld angenommen haben.__ = Es wird behauptet), **wollen** (__Er will nichts gewusst haben.__ = Er behauptet es selbst), Präpositionen wie **laut, zufolge, nach Angaben** und **angeblich, vermeintlich**. Für die Vergangenheit: __er habe gesagt / sei gegangen__; für die Zukunft: __er werde kommen__."],"use":"Prüfung C1: Zusammenfassungen von Texten und Hörbeiträgen, Berichte, Protokolle, Zitate in Erörterungen.","table":[["Mittel","Funktion","Beispiel"],["Konjunktiv I","neutrale Wiedergabe","Er sagte, er **habe** keine Zeit."],["Konjunktiv II (Ersatz)","wenn K I = Indikativ","Sie sagten, sie **hätten** keine Zeit."],["sollen + Inf.","Gerücht, fremde Behauptung","Er **soll** reich **sein**."],["wollen + Inf.","eigene Behauptung","Er **will** es nicht **gewusst haben**."],["laut / zufolge","Quelle nennen","**Laut** Polizei … / Der Studie **zufolge** …"],["behaupten / einräumen / bestreiten","Bewertung der Aussage","Er **räumte ein**, Fehler gemacht zu haben."]],"examples":[{"de":"Die Ministerin erklärte, die Reform werde im Januar in Kraft treten.","en":"The minister stated that the reform would come into force in January."},{"de":"Der Sprecher betonte, es habe keine Absprachen gegeben.","en":"The spokesperson stressed there had been no agreements."},{"de":"Die Opposition behauptet, die Zahlen seien geschönt.","en":"The opposition claims the figures have been embellished."},{"de":"Der Konzern bestreitet, von den Mängeln gewusst zu haben.","en":"The corporation denies having known about the defects."},{"de":"Er räumte ein, dass er die Frist versäumt habe.","en":"He admitted that he had missed the deadline."},{"de":"Die Anwohner fordern, der Lärm müsse reduziert werden.","en":"The residents demand that the noise must be reduced."},{"de":"Die Polizei warnte, die Straßen könnten glatt sein.","en":"The police warned that the roads could be slippery."},{"de":"Laut Wetterdienst wird es am Wochenende stürmisch.","en":"According to the weather service it will be stormy at the weekend."},{"de":"Einem Bericht der Zeitung zufolge sollen 200 Stellen wegfallen.","en":"According to a newspaper report, 200 jobs are to be cut."},{"de":"Der Politiker soll Spenden nicht angegeben haben.","en":"The politician is alleged not to have declared donations."},{"de":"Der Verdächtige will zur Tatzeit zu Hause gewesen sein.","en":"The suspect claims to have been at home at the time of the crime."},{"de":"Die Firma versicherte, alle Kunden würden entschädigt.","en":"The company assured that all customers would be compensated."},{"de":"Sie fragte, ob die Daten sicher gespeichert würden.","en":"She asked whether the data would be stored securely."},{"de":"Die Studierenden kündigten an, sie würden weiter protestieren.","en":"The students announced they would continue to protest."},{"de":"Nach Angaben der Veranstalter kamen 10.000 Menschen.","en":"According to the organisers, 10,000 people came."}],"vocab":[{"de":"redeeinleitend","en":"introducing speech"},{"de":"die Redewiedergabe","en":"reported speech"},{"de":"wiedergeben","en":"to reproduce, to report"},{"de":"das Zitat, -e","en":"quotation"},{"de":"behaupten","en":"to claim"},{"de":"bestreiten","en":"to deny, to dispute"},{"de":"dementieren","en":"to deny officially"},{"de":"einräumen","en":"to concede"},{"de":"unterstreichen","en":"to underline, to stress"},{"de":"versichern","en":"to assure"},{"de":"ankündigen","en":"to announce"},{"de":"mutmaßlich","en":"alleged, presumed"},{"de":"angeblich","en":"supposedly"},{"de":"vermeintlich","en":"supposed (wrongly)"},{"de":"die Stellungnahme, -n","en":"statement"},{"de":"die Gegendarstellung, -en","en":"correction (press)"},{"de":"die Quelle, -n","en":"source"},{"de":"die Distanzierung","en":"distancing"},{"de":"der Wortlaut","en":"exact wording"},{"de":"sinngemäß","en":"in essence, roughly"}],"reading":"Ein Beispiel für die Redewiedergabe in einem Nachrichtentext: Im Streit um die geplante Erweiterung des Flughafens hat die Landesregierung am Dienstag erstmals Fehler eingeräumt. Der Verkehrsminister sagte vor Journalisten, man habe die Bürgerinnen und Bürger zu spät beteiligt. Dies werde sich ändern. Künftig solle es vor jeder größeren Entscheidung öffentliche Anhörungen geben. Zugleich betonte er, an der Erweiterung selbst halte die Regierung fest; ohne zusätzliche Kapazitäten drohten der Region erhebliche wirtschaftliche Nachteile. Die Bürgerinitiative „Ruhiger Himmel“ reagierte zurückhaltend. Ihre Sprecherin erklärte, die Ankündigung komme reichlich spät und ändere nichts an den grundsätzlichen Problemen. Die Regierung habe Gutachten zur Lärmbelastung über Monate zurückgehalten. Das Ministerium bestreitet dies. Es seien lediglich vorläufige Daten gewesen, die man noch habe prüfen müssen. Einem Bericht des Regionalsenders zufolge sollen interne Unterlagen jedoch belegen, dass die Ergebnisse bereits im Frühjahr vorlagen. Der Minister will davon nach eigenen Angaben nichts gewusst haben. Die Opposition fordert nun einen Untersuchungsausschuss. Ein Sprecher der Fluggesellschaften warnte unterdessen, weitere Verzögerungen würden Arbeitsplätze gefährden. Die Entscheidung über die Erweiterung soll im kommenden Jahr fallen.","tasks":[{"q":"Indirekt: „Ich habe keine Zeit.“ → Er sagte, er ___ keine Zeit.","a":"habe"},{"q":"Indirekt (Ersatzform): „Wir haben keine Zeit.“ → Sie sagten, sie ___ keine Zeit.","a":"hätten"},{"q":"Indirekt: „Die Lage ist stabil.“ → Sie erklärte, die Lage ___ stabil.","a":"sei"},{"q":"Indirekt Vergangenheit: „Ich bin nicht dort gewesen.“ → Er sagte, er ___ nicht dort gewesen.","a":"sei"},{"q":"Indirekt Zukunft: „Wir werden helfen.“ → Sie versprachen, sie ___ helfen. (Ersatzform)","a":"würden"},{"q":"Gerücht: Man sagt, er ist bestochen worden. → Er ___ bestochen worden sein.","a":"soll"},{"q":"Eigene Behauptung: Er sagt, er war krank. → Er ___ krank gewesen sein.","a":"will"},{"q":"Quelle: ___ Polizei gab es keine Verletzten.","a":"Laut"},{"q":"Quelle nachgestellt: Dem Bericht ___ ist die Zahl gestiegen.","a":"zufolge"},{"q":"Verb wählen (Zugeständnis): Er ___ ein, einen Fehler gemacht zu haben.","a":"räumte"},{"q":"Verb wählen (Verneinung): Die Firma ___ die Vorwürfe. (bestreiten, Präteritum)","a":"bestritt"},{"q":"Fehler? „Er sagte, er sei gestern zu Hause gewesen sei.“","a":"Er sagte, er sei gestern zu Hause gewesen."}],"exam":[{"q":"Welchen Fehler hat die Landesregierung eingeräumt?","a":"Die Bürger zu spät beteiligt zu haben."},{"q":"Was soll es künftig geben?","a":"Öffentliche Anhörungen vor größeren Entscheidungen."},{"q":"Was wirft die Bürgerinitiative der Regierung vor?","a":"Gutachten zur Lärmbelastung zurückgehalten zu haben."},{"q":"Wie reagiert das Ministerium?","a":"Es bestreitet es; es seien vorläufige Daten gewesen."},{"q":"Was fordert die Opposition?","a":"Einen Untersuchungsausschuss."},{"q":"Wovor warnen die Fluggesellschaften?","a":"Weitere Verzögerungen würden Arbeitsplätze gefährden."},{"q":"Geben Sie wieder: Die Ministerin sagt: „Wir haben alles richtig gemacht.“","a":"Die Ministerin sagt, sie hätten alles richtig gemacht."},{"q":"Fassen Sie eine aktuelle Nachricht in indirekter Rede zusammen (120 Wörter).","a":"","m":"Die Ministerin erklärte, die Inflation sei gesunken. Sie betonte, die Regierung habe die richtigen Maßnahmen ergriffen. Kritiker bestritten das. Sie forderten, die Hilfen müssten verlängert werden."},{"q":"Erklären Sie den Unterschied zwischen „Er sagte, er sei krank“ und „Er sagte, er ist krank“.","a":"","m":"„Er sagte, er sei krank“ gibt die Aussage neutral wieder; der Sprecher bewertet sie nicht. „Er sagte, er ist krank“ ist umgangssprachlich und klingt, als ob der Sprecher es selbst glaubt."},{"q":"Schreiben Sie ein kurzes Protokoll eines Gesprächs mit drei redeeinleitenden Verben.","a":"","m":"Herr Klein betonte, das Projekt sei im Zeitplan. Frau Ali räumte ein, das Budget sei knapp. Beide forderten ein weiteres Treffen im Mai."}],"speak":["Berichte, was ein Freund dir gestern erzählt hat – im Konjunktiv I.","Gib eine Nachricht aus dem Radio mit „laut“, „zufolge“ und „sollen“ wieder.","Spielt eine Pressekonferenz: Eine Person spricht, die andere fasst zusammen.","Welche redeeinleitenden Verben zeigen Zweifel? Erkläre mit Beispielen."],"dialog":[{"who":"Moderator","de":"Herr Weiß, die Bürgerinitiative behauptet, die Regierung habe Gutachten zurückgehalten. Was sagen Sie dazu?"},{"who":"Herr Weiß","de":"Das weise ich entschieden zurück. Es handelte sich um vorläufige Zahlen."},{"who":"Moderator","de":"Laut einem Bericht des Regionalsenders lagen die Ergebnisse aber schon im Frühjahr vor."},{"who":"Herr Weiß","de":"Ich kenne den Bericht. Er stützt sich auf anonyme Quellen. Der Minister hat versichert, er habe die Daten erst im Herbst gesehen."},{"who":"Moderator","de":"Sie räumen aber ein, dass die Bürger zu spät beteiligt wurden?"},{"who":"Herr Weiß","de":"Ja, das haben wir selbstkritisch eingestanden. Daraus ziehen wir Konsequenzen."}],"dq":[{"q":"Was behauptet die Bürgerinitiative?","a":"Die Regierung habe Gutachten zurückgehalten."},{"q":"Worauf stützt sich der Bericht des Regionalsenders laut Herrn Weiß?","a":"Auf anonyme Quellen."},{"q":"Was räumt Herr Weiß ein?","a":"Dass die Bürger zu spät beteiligt wurden."}],"en":{"title":"Reporting speech: subjunctive I, alternatives and reporting verbs","theme":"Media and politics","expl":["In reports you separate your own statements from the ones you are passing on. The **Konjunktiv I** signals \\"someone said this – I\'m reporting it neutrally\\": __Der Minister erklärte, die Lage sei stabil.__","If the Konjunktiv I is identical to the normal form (mostly 1st person singular and the plural), use the Konjunktiv II: __Sie sagten, sie hätten keine Zeit.__","Vary the reporting verbs to show nuance: behaupten (claim), betonen (stress), einräumen (concede), bestreiten (deny), kritisieren, fordern (demand)."],"use":""},"check":[{"re":"\\\\b(sei|seien|habe|hätten|wäre|werde|könne)\\\\b|\\\\b(betonte|erklärte|räumte|bestritt|kritisierte|forderte|behauptete|teilte)\\\\b","label":"Konjunktiv I and reporting verbs (betonte, räumte ein …)"}]},{"n":69,"pos":65,"level":"C1","title":"Präfixverben: trennbar oder untrennbar (über-, um-, unter-, durch-, wieder-)","theme":"Bedeutung entscheidet","scene":"classroom","rec":[10,51],"expl":["Die Präfixe **durch-, über-, um-, unter-, wider-, wieder-** können **trennbar** oder **untrennbar** sein – und dann ändert sich die **Bedeutung**. Trennbar ist meist die **wörtliche, räumliche** Bedeutung, betont auf dem Präfix: __Er **setzt** uns mit der Fähre **über**.__ Untrennbar ist meist die **übertragene** Bedeutung, betont auf dem Verb: __Sie **übersetzt** den Text.__","Die Form zeigt den Unterschied: trennbar → Partizip mit **-ge-** in der Mitte und **zu** dazwischen (__übergesetzt, überzusetzen__); untrennbar → **ohne ge-** und zu davor (__übersetzt, zu übersetzen__). Beispiele: __umfahren__ (trennbar: umstoßen mit dem Auto – __Er hat das Schild umgefahren.__; untrennbar: um etwas herumfahren – __Wir haben den Stau umfahren.__).","Weitere wichtige Paare: __wiederholen__ (zurückholen, trennbar) / __wiederholen__ (noch einmal machen, untrennbar); __unterhalten__ (darunterhalten) / __sich unterhalten__ (sprechen); __durchschauen__ (hindurchsehen) / __durchschauen__ (jemanden erkennen); __übergehen zu__ (wechseln) / __übergehen__ (ignorieren). Im Wörterbuch markiert ein Strich oder Betonungszeichen die Trennbarkeit."],"use":"C1 Wortschatz und Präzision: Fachtexte verstehen, Missverständnisse vermeiden, Prüfung Sprachbausteine.","table":[["Verb","trennbar (wörtlich)","untrennbar (übertragen)"],["übersetzen","Er setzt uns ans andere Ufer über.","Sie übersetzt den Roman."],["umfahren","Er hat das Schild umgefahren.","Wir haben den Stau umfahren."],["wiederholen","Ich hole mein Buch wieder.","Wir wiederholen die Lektion."],["durchschauen","Er schaut durch das Fenster durch.","Ich habe ihn durchschaut."],["unterstellen","Wir stellen uns unter (Regen).","Er unterstellt mir Absicht."],["übergehen","Sie geht zum nächsten Thema über.","Man hat mich bei der Beförderung übergangen."]],"examples":[{"de":"Die Lehrerin wiederholt die Regel noch einmal.","en":"The teacher repeats the rule once more."},{"de":"Kannst du mir das Buch morgen wiederholen? – Nein: wiederbringen!","en":"Can you fetch the book back for me tomorrow? – No: bring it back!"},{"de":"Er hat den Brief ins Englische übersetzt.","en":"He translated the letter into English."},{"de":"Der Fährmann hat uns übergesetzt.","en":"The ferryman took us across."},{"de":"Wir haben den Stau großräumig umfahren.","en":"We bypassed the traffic jam over a wide area."},{"de":"Ein Lkw hat die Ampel umgefahren.","en":"A lorry knocked down the traffic light."},{"de":"Sie hat seine Absichten sofort durchschaut.","en":"She saw through his intentions immediately."},{"de":"Bei Regen haben wir uns unter einer Brücke untergestellt.","en":"When it rained, we sheltered under a bridge."},{"de":"Er unterstellt mir, dass ich gelogen habe.","en":"He insinuates that I lied."},{"de":"Man hat sie bei der Beförderung übergangen.","en":"She was passed over for promotion."},{"de":"Lassen Sie uns zum nächsten Punkt übergehen.","en":"Let\'s move on to the next point."},{"de":"Wir haben uns den ganzen Abend unterhalten.","en":"We chatted all evening."},{"de":"Die Firma unterhält zwei Büros in Asien.","en":"The company maintains two offices in Asia."},{"de":"Der Plan ist schwer zu durchschauen.","en":"The plan is hard to see through."},{"de":"Sie hat den ganzen Tag durchgearbeitet.","en":"She worked through the whole day."}],"vocab":[{"de":"übersetzen (untrennbar)","en":"to translate"},{"de":"übersetzen (trennbar)","en":"to ferry across"},{"de":"umfahren (untrennbar)","en":"to drive around, to bypass"},{"de":"umfahren (trennbar)","en":"to knock down (with a vehicle)"},{"de":"umgehen mit","en":"to deal with"},{"de":"umgehen (untrennbar)","en":"to circumvent"},{"de":"durchschauen (untrennbar)","en":"to see through"},{"de":"durchlesen (trennbar)","en":"to read through"},{"de":"unterhalten (untrennbar)","en":"to entertain; to maintain"},{"de":"sich unterstellen (trennbar)","en":"to take shelter"},{"de":"unterstellen (untrennbar)","en":"to insinuate"},{"de":"übergehen zu (trennbar)","en":"to move on to"},{"de":"übergehen (untrennbar)","en":"to pass over, to ignore"},{"de":"überlegen (untrennbar)","en":"to consider"},{"de":"überziehen (untrennbar)","en":"to overdraw"},{"de":"widersprechen (untrennbar)","en":"to contradict"},{"de":"widerspiegeln (trennbar)","en":"to reflect"},{"de":"wiedersehen (trennbar)","en":"to see again"},{"de":"die Betonung, -en","en":"stress, emphasis"},{"de":"das Präfix, -e","en":"prefix"}],"reading":"Warum ist Deutsch manchmal so schwierig? Ein schönes Beispiel liefert ein kleiner Unfall, über den eine Lokalzeitung berichtete: „Ein Fahranfänger hat am Montagabend auf der Umgehungsstraße ein Verkehrsschild umgefahren. Er wollte nach eigenen Angaben eine Baustelle umfahren, verlor dabei jedoch die Kontrolle über sein Auto.“ Für Muttersprachler ist der Text völlig klar, für Lernende ein Rätsel: Dasselbe Verb bedeutet einmal „niederfahren“ und einmal „um etwas herumfahren“. Den Unterschied hört man an der Betonung – UMfahren gegenüber umFAHren – und man sieht ihn an der Form: „umgefahren“ mit ge- in der Mitte, „umfahren“ ohne ge-. Ähnlich geht es mit vielen anderen Verben. Wer einen Text „übersetzt“, überträgt ihn in eine andere Sprache; wer Menschen „übersetzt“, bringt sie mit dem Boot ans andere Ufer. Wer sich mit Kollegen „unterhält“, spricht mit ihnen; wer eine Familie „unterhält“, bezahlt für ihren Lebensunterhalt. Eine Faustregel hilft: Die trennbare Variante ist meist räumlich und konkret, die untrennbare eher abstrakt. Ganz zuverlässig ist die Regel aber nicht. Darum lohnt es sich, solche Verben im Wörterbuch nachzuschlagen und sie immer mit einem Beispielsatz zu lernen, statt die Bedeutung zu raten.","tasks":[{"q":"Partizip: Sie hat den Text ins Deutsche ___. (übersetzen, Sprache)","a":"übersetzt"},{"q":"Partizip: Der Fährmann hat uns ___. (übersetzen, Ufer)","a":"übergesetzt"},{"q":"Partizip: Ein Auto hat die Laterne ___. (umfahren, niederfahren)","a":"umgefahren"},{"q":"Partizip: Wir haben den Stau ___. (umfahren, herum)","a":"umfahren"},{"q":"Partizip: Ich habe seinen Trick sofort ___. (durchschauen)","a":"durchschaut"},{"q":"zu-Infinitiv: Es ist schwer, diesen Text zu ___. (übersetzen, Sprache)","a":"übersetzen"},{"q":"zu-Infinitiv: Es war unmöglich, das Schild nicht ___. (umfahren, niederfahren)","a":"umzufahren"},{"q":"Präsens: Die Lehrerin ___ die Regel. (wiederholen, noch einmal)","a":"wiederholt"},{"q":"Präsens: Wir ___ jetzt zum nächsten Punkt ___. (übergehen)","a":"gehen / über"},{"q":"Bedeutung: „Er unterstellt mir Absicht.“ = Er behauptet, ich habe es ___ gemacht.","a":"absichtlich"},{"q":"Bedeutung: „Bei Regen stellen wir uns unter.“ = Wir suchen ___. (Schutz/Arbeit)","a":"Schutz"},{"q":"Fehler? „Ich habe den Brief übergesetzt.“ (Sprache gemeint)","a":"Ich habe den Brief übersetzt."}],"exam":[{"q":"Was hat der Fahranfänger umgefahren?","a":"Ein Verkehrsschild."},{"q":"Was wollte er umfahren?","a":"Eine Baustelle."},{"q":"Woran erkennt man den Unterschied in der Aussprache?","a":"An der Betonung (UMfahren / umFAHren)."},{"q":"Woran erkennt man ihn in der Schrift?","a":"Am Partizip: mit ge- in der Mitte (trennbar) oder ohne ge- (untrennbar)."},{"q":"Welche Faustregel nennt der Text?","a":"Trennbar = räumlich/konkret, untrennbar = abstrakt."},{"q":"Bilden Sie zwei Sätze mit „unterhalten“ in zwei Bedeutungen.","a":"","m":"Wir haben uns lange über Politik unterhalten. Die Firma unterhält drei Filialen in Bayern."},{"q":"Erklären Sie den Unterschied: „Sie hat die Prüfung wiederholt“ / „Sie hat ihr Fahrrad wiedergeholt“.","a":"","m":"„Sie hat die Prüfung wiederholt“ bedeutet, sie hat sie noch einmal gemacht. „Sie hat ihr Fahrrad wiedergeholt“ bedeutet, sie hat es zurückgeholt."},{"q":"Schreiben Sie eine kurze Geschichte mit umfahren (beide Bedeutungen).","a":"","m":"Der Fahrer wollte den Stau umfahren. Er fuhr zu schnell und fuhr fast ein Schild um. Am Ende umfuhr er die Stadt und kam pünktlich an."},{"q":"Welche Verben in Ihrer Muttersprache haben zwei Bedeutungen? Vergleichen Sie.","a":"","m":"Im Englischen hat „to run“ viele Bedeutungen, ähnlich wie „übergehen“ im Deutschen, das je nach Betonung etwas anderes bedeutet."},{"q":"Nennen Sie drei untrennbare Verben mit über- und erklären Sie sie.","a":"","m":"Übersetzen: einen Text in eine andere Sprache bringen. Überlegen: über etwas nachdenken. Übernehmen: eine Aufgabe annehmen."}],"speak":["Sprich die Paare laut und betone richtig: UMfahren/umFAHren, ÜBERsetzen/überSETZen.","Erkläre einem Lernenden den Unterschied zwischen „durchschauen“ und „durchlesen“.","Erzähl eine Situation, in der du jemanden durchschaut hast.","Bilde mit deinem Partner Sätze mit „unterhalten“, „übergehen“ und „umgehen“."],"dialog":[{"who":"Tomás","de":"Leila, was ist der Unterschied zwischen „Ich habe ihn durchschaut“ und „Ich habe durchgeschaut“?"},{"who":"Leila","de":"Das erste ist untrennbar und bedeutet: Ich habe verstanden, was er wirklich will."},{"who":"Tomás","de":"Und das zweite?"},{"who":"Leila","de":"Trennbar, ganz wörtlich: Du hast durch etwas hindurchgesehen, zum Beispiel durch ein Fernglas."},{"who":"Tomás","de":"Und wie höre ich das?"},{"who":"Leila","de":"An der Betonung. Bei trennbaren Verben betont man das Präfix: DURCHgeschaut. Bei untrennbaren das Verb: durchSCHAUT."},{"who":"Tomás","de":"Puh. Gibt es noch mehr davon?"},{"who":"Leila","de":"Viele. Am besten lernst du jedes Paar mit einem Beispielsatz."}],"dq":[{"q":"Was bedeutet „Ich habe ihn durchschaut“?","a":"Ich habe verstanden, was er wirklich will."},{"q":"Woran hört man den Unterschied?","a":"An der Betonung."},{"q":"Was empfiehlt Leila?","a":"Jedes Paar mit einem Beispielsatz zu lernen."}],"en":{"title":"Prefix verbs: separable or not (über-, um-, unter-, durch-, wieder-)","theme":"Meaning decides","expl":["The prefixes durch-, über-, um-, unter-, wider- and wieder- can be **separable or inseparable – and the meaning changes**.","Separable is usually the **literal, physical** meaning, stressed on the prefix: __Er setzt uns mit der Fähre über.__ (he ferries us across). Inseparable is usually the **figurative** meaning, stressed on the verb: __Sie übersetzt den Text.__ (she translates the text).","More pairs: __UMfahren__ (knock down: __Er fährt das Schild um.__) vs. __umFAHRen__ (drive around: __Er umfährt den Stau.__), __WIEDERholen__ (fetch back) vs. __wiederHOLen__ (repeat)."],"use":""},"check":[{"re":"\\\\b(unterhalten|umfahren|übersetzen|wiederholen|wiederholt|durchsuchen|übergehen|unterstellen)\\\\b","label":"prefix verbs with two meanings"}]},{"n":70,"pos":66,"level":"C1","title":"Grafiken und Statistiken versprachlichen","theme":"Zahlen und Trends","scene":"office","rec":[54],"expl":["Eine Grafikbeschreibung folgt drei Schritten: **Einleitung** (Thema, Quelle, Zeitraum, Art der Grafik: __Das Säulendiagramm zeigt … Die Daten stammen vom Statistischen Bundesamt und beziehen sich auf die Jahre 2015 bis 2024.__), **Hauptteil** (wichtigste Entwicklungen, Höchst- und Tiefstwerte, Vergleiche) und **Schluss** (Zusammenfassung, mögliche Gründe, eigene Einschätzung).","Für Entwicklungen braucht man präzise Verben: **steigen, zunehmen, wachsen, sich erhöhen** (um 5 % auf 40 %), **sinken, abnehmen, zurückgehen, sich verringern**, **gleich bleiben, stagnieren, schwanken**, **sich verdoppeln/halbieren**. Merke: **um** = Differenz, **auf** = Endwert, **von … auf** = Anfang und Ende.","Für Anteile und Vergleiche: __Knapp die Hälfte / gut ein Drittel / etwa jeder Vierte__, __der Anteil liegt bei …__, __im Vergleich zu …__, __während … , …__, __an erster Stelle steht …__. Vorsicht mit Ursachen: Eine Grafik zeigt meist nur Zahlen, keine Gründe – formulieren Sie Vermutungen mit __vermutlich, dürfte, lässt sich darauf zurückführen, dass …__."],"use":"Prüfung C1 (telc/Goethe/TestDaF): Grafik beschreiben und Ergebnisse diskutieren, schriftlich und mündlich.","table":[["Entwicklung","Verb","Beispiel"],["nach oben","steigen, zunehmen","Der Anteil **stieg von** 20 % **auf** 35 %."],["nach unten","sinken, zurückgehen","Die Zahl **ging um** 10 % **zurück**."],["gleich","stagnieren, konstant bleiben","Die Preise **blieben** nahezu **konstant**."],["unregelmäßig","schwanken","Die Werte **schwankten** zwischen 5 und 8 %."],["stark","sich verdoppeln, sprunghaft ansteigen","Die Nachfrage **hat sich verdoppelt**."],["Rang","an erster/letzter Stelle stehen","**An erster Stelle steht** das Fahrrad."]],"examples":[{"de":"Das Diagramm zeigt die Entwicklung der Mietpreise in deutschen Großstädten.","en":"The chart shows the development of rents in large German cities."},{"de":"Die Daten stammen vom Statistischen Bundesamt.","en":"The data come from the Federal Statistical Office."},{"de":"Die Zahl der E-Autos ist seit 2020 stark gestiegen.","en":"The number of electric cars has risen sharply since 2020."},{"de":"Der Anteil stieg von 12 auf 25 Prozent.","en":"The share rose from 12 to 25 per cent."},{"de":"Die Arbeitslosigkeit ging um zwei Prozentpunkte zurück.","en":"Unemployment fell by two percentage points."},{"de":"Die Preise sind nahezu konstant geblieben.","en":"Prices remained almost constant."},{"de":"Die Besucherzahlen schwankten stark.","en":"Visitor numbers fluctuated strongly."},{"de":"Knapp die Hälfte der Befragten nutzt täglich das Fahrrad.","en":"Just under half of the respondents cycle every day."},{"de":"Etwa jeder Vierte arbeitet im Homeoffice.","en":"About one in four works from home."},{"de":"Im Vergleich zum Vorjahr hat sich der Umsatz verdoppelt.","en":"Compared with the previous year, sales have doubled."},{"de":"An erster Stelle steht das Auto, gefolgt vom öffentlichen Nahverkehr.","en":"The car is in first place, followed by public transport."},{"de":"Während die Zahl in Städten zunahm, sank sie auf dem Land.","en":"While the number increased in cities, it fell in rural areas."},{"de":"Den Höchststand erreichte der Wert im Jahr 2022.","en":"The value reached its peak in 2022."},{"de":"Dies lässt sich vermutlich auf die gestiegenen Energiepreise zurückführen.","en":"This can presumably be attributed to the increased energy prices."},{"de":"Zusammenfassend lässt sich ein deutlicher Aufwärtstrend feststellen.","en":"In summary, a clear upward trend can be observed."}],"vocab":[{"de":"das Säulendiagramm, -e","en":"bar chart (vertical)"},{"de":"das Balkendiagramm, -e","en":"bar chart (horizontal)"},{"de":"das Kreisdiagramm, -e","en":"pie chart"},{"de":"das Liniendiagramm, -e","en":"line graph"},{"de":"die Tabelle, -n","en":"table"},{"de":"der Prozentpunkt, -e","en":"percentage point"},{"de":"der Anteil, -e","en":"share"},{"de":"der Höchststand","en":"peak"},{"de":"der Tiefststand","en":"low point"},{"de":"der Aufwärtstrend","en":"upward trend"},{"de":"der Abwärtstrend","en":"downward trend"},{"de":"zunehmen","en":"to increase"},{"de":"zurückgehen","en":"to decline"},{"de":"stagnieren","en":"to stagnate"},{"de":"schwanken","en":"to fluctuate"},{"de":"sich verdoppeln","en":"to double"},{"de":"sich halbieren","en":"to halve"},{"de":"die Befragten (Pl.)","en":"respondents"},{"de":"der Vergleichszeitraum","en":"comparison period"},{"de":"die Erhebung, -en","en":"survey"}],"reading":"Musterbeschreibung: Das Liniendiagramm mit dem Titel „Verkehrsmittel auf dem Weg zur Arbeit“ zeigt, wie sich die Nutzung von Auto, öffentlichem Nahverkehr und Fahrrad in einer deutschen Großstadt zwischen 2014 und 2024 entwickelt hat. Die Daten stammen aus einer jährlichen Befragung der Stadtverwaltung unter rund 5.000 Berufstätigen. Auffällig ist zunächst der Rückgang des Autos: Während 2014 noch knapp die Hälfte der Befragten (48 Prozent) mit dem eigenen Pkw zur Arbeit fuhr, waren es 2024 nur noch 31 Prozent – ein Minus von 17 Prozentpunkten. Gleichzeitig hat sich der Anteil des Fahrrads mehr als verdoppelt, nämlich von 11 auf 24 Prozent. Den stärksten Anstieg verzeichnete das Rad zwischen 2020 und 2021, was vermutlich mit der Pandemie und dem Ausbau neuer Radwege zusammenhängt. Der öffentliche Nahverkehr schwankte über den gesamten Zeitraum zwischen 30 und 38 Prozent; einem deutlichen Einbruch im Jahr 2020 folgte eine Erholung, und 2024 erreichte er mit 38 Prozent seinen Höchststand. Ein möglicher Grund dafür dürfte das bundesweite Monatsticket sein. Zusammenfassend lässt sich ein klarer Trend weg vom Auto hin zu umweltfreundlicheren Verkehrsmitteln feststellen. Ob sich diese Entwicklung fortsetzt, hängt allerdings davon ab, ob die Stadt weiter in Infrastruktur investiert. Zu berücksichtigen ist zudem, dass die Befragung nur Berufstätige erfasst; über den Freizeitverkehr sagt die Grafik nichts aus.","tasks":[{"q":"Von 20 % ___ 30 %: Der Anteil stieg ___ 20 ___ 30 %.","a":"von / auf"},{"q":"Differenz: Die Zahl sank ___ 5 %.","a":"um"},{"q":"Endwert: Der Preis stieg ___ 3 Euro.","a":"auf"},{"q":"Verb: Die Werte blieben gleich. → Die Werte ___. (stagnieren)","a":"stagnierten"},{"q":"Verb: 10 → 20: Die Zahl hat sich ___.","a":"verdoppelt"},{"q":"Verb: 40 → 20: Der Wert hat sich ___.","a":"halbiert"},{"q":"Anteil: 48 % = ___ die Hälfte (knapp/gut)","a":"knapp"},{"q":"Anteil: 26 % = etwa jeder ___","a":"Vierte"},{"q":"Rang: An erster ___ steht das Auto.","a":"Stelle"},{"q":"Vermutung: Das ___ sich auf die Preise zurückführen. (lassen)","a":"lässt"},{"q":"Einleitung: Die Daten ___ vom Statistischen Bundesamt. (stammen)","a":"stammen"},{"q":"Fehler? „Die Zahl ist um 30 % gestiegen auf.“","a":"Die Zahl ist auf 30 % gestiegen."}],"exam":[{"q":"Was zeigt das Liniendiagramm?","a":"Die Nutzung von Auto, Nahverkehr und Fahrrad auf dem Weg zur Arbeit (2014–2024)."},{"q":"Woher stammen die Daten?","a":"Aus einer jährlichen Befragung der Stadtverwaltung unter rund 5.000 Berufstätigen."},{"q":"Wie hat sich der Anteil des Fahrrads entwickelt?","a":"Er hat sich mehr als verdoppelt (von 11 auf 24 %)."},{"q":"Wann stieg das Fahrrad am stärksten?","a":"Zwischen 2020 und 2021."},{"q":"Was ist ein möglicher Grund für den Höchststand des Nahverkehrs?","a":"Das bundesweite Monatsticket."},{"q":"Welche Einschränkung der Befragung nennt der Text?","a":"Sie erfasst nur Berufstätige, nicht den Freizeitverkehr."},{"q":"Beschreiben Sie: 2015: 30 %, 2025: 45 %.","a":"Der Anteil ist von 30 auf 45 Prozent gestiegen (um 15 Prozentpunkte)."},{"q":"Beschreiben Sie eine Grafik Ihrer Wahl in 150 Wörtern (Einleitung, Hauptteil, Schluss).","a":"","m":"Das Säulendiagramm zeigt den Fleischkonsum in Deutschland von 2015 bis 2024. Die Daten stammen vom Statistischen Bundesamt. Im Jahr 2015 aß jeder Deutsche etwa 60 Kilogramm Fleisch. Seitdem ist der Konsum stetig gesunken. 2024 erreichte er mit 52 Kilogramm einen Tiefststand. Insgesamt ist ein klarer Rückgang zu erkennen. Es ist zu erwarten, dass sich dieser Trend fortsetzt."},{"q":"Vergleichen Sie die Entwicklung mit Ihrem Heimatland.","a":"","m":"Im Vergleich zu Deutschland steigt der Fleischkonsum in Indien leicht an, er ist aber insgesamt deutlich niedriger."},{"q":"Welche Gründe könnte es für einen Rückgang des Fleischkonsums geben? Formulieren Sie vorsichtig.","a":"","m":"Ein Grund könnte sein, dass mehr Menschen auf ihre Gesundheit achten. Möglicherweise spielt auch der Klimaschutz eine Rolle. Es ist anzunehmen, dass höhere Preise ebenfalls wichtig sind."}],"speak":["Beschreibe eine erfundene Grafik über die Handynutzung von Jugendlichen.","Nenne drei Entwicklungen mit steigen, sinken und schwanken.","Formuliere Vermutungen über Gründe – vorsichtig und präzise.","Vergleicht zu zweit zwei Grafiken und diskutiert die Unterschiede."],"dialog":[{"who":"Prüferin","de":"Bitte beschreiben Sie kurz die wichtigste Entwicklung in Ihrer Grafik."},{"who":"Aiko","de":"Die Grafik zeigt, dass der Anteil des Autos von 48 auf 31 Prozent gesunken ist, also um 17 Prozentpunkte."},{"who":"Prüferin","de":"Und welches Verkehrsmittel hat am meisten zugelegt?"},{"who":"Aiko","de":"Das Fahrrad. Sein Anteil hat sich mehr als verdoppelt."},{"who":"Prüferin","de":"Woran könnte das liegen?"},{"who":"Aiko","de":"Die Grafik nennt keine Gründe, aber vermutlich spielen neue Radwege und die Pandemie eine Rolle."},{"who":"Prüferin","de":"Ist das in Ihrem Heimatland ähnlich?"},{"who":"Aiko","de":"In Tokio ist der Nahverkehr seit Jahren an erster Stelle. Das Auto spielt dort eine viel kleinere Rolle."}],"dq":[{"q":"Um wie viele Prozentpunkte ist der Anteil des Autos gesunken?","a":"Um 17 Prozentpunkte."},{"q":"Welches Verkehrsmittel hat am meisten zugelegt?","a":"Das Fahrrad."},{"q":"Was steht in Tokio an erster Stelle?","a":"Der Nahverkehr."}],"en":{"title":"Describing graphs and statistics","theme":"Numbers and trends","expl":["A graph description has three steps. **Introduction**: topic, source, period and type of chart: __Das Säulendiagramm zeigt … Die Daten stammen vom Statistischen Bundesamt.__","**Main part**: the most important developments, highest and lowest values, comparisons: __ist um 5 % gestiegen, hat sich verdoppelt, erreichte einen Höchststand__.","**Conclusion**: a summary and, if asked, your interpretation or a forecast."],"use":""},"check":[{"re":"\\\\b(zeigt|stieg|sank|gestiegen|gesunken|prozent|anteil|im vergleich|verdoppelt|höchststand|tiefststand|ist zu erkennen)\\\\b","label":"graph language (stieg, sank, im Vergleich zu …)"}]},{"n":71,"pos":67,"level":"C1","title":"Wortbildung: Komposita, Ableitungen, Nominalisierung","theme":"Wörter verstehen, ohne sie zu kennen","scene":"classroom","rec":[54,55],"expl":["Deutsch bildet neue Wörter vor allem durch **Komposition** (Zusammensetzung): Das **letzte** Wort bestimmt Bedeutung und **Genus**: __die Haustür__ (eine Tür), __der Türschlüssel__ (ein Schlüssel). Zwischen den Teilen stehen oft **Fugenelemente** (-s-, -es-, -n-, -en-, -er-): __Arbeitszeit, Liebesbrief, Sonnenbrille, Kinderwagen__. Wer das Grundwort erkennt, versteht auch lange Wörter: __Kraftfahrzeughaftpflichtversicherung__ = eine Versicherung.","**Ableitungen** mit Suffixen zeigen die Wortart: **-ung, -heit, -keit, -schaft, -ion, -tät** → feminine Nomen; **-er, -ling, -ismus** → maskulin; **-chen, -lein, -ment, -um** → neutral. Adjektive: **-bar** (möglich: lesbar), **-los** (ohne: arbeitslos), **-haft, -ig, -lich, -isch**. Präfixe verändern die Bedeutung: **un-** (Gegenteil), **miss-** (falsch), **ver-** (oft „falsch“ oder „weg“: verlaufen, verschwenden), **er-** (Erfolg: erreichen).","**Nominalisierung**: Fast jedes Verb wird mit dem Artikel **das** zum Nomen (__das Lesen, das Autofahren__), Adjektive werden mit der/die/das zu Personen oder Abstrakta (__der Kranke, das Gute__). In wissenschaftlichen Texten führt das zu dichten Ausdrücken, die man durch Auflösen in Sätze leichter versteht."],"use":"C1 Lese- und Hörverstehen: unbekannte Wörter erschließen; Schreiben: präzise und abwechslungsreich formulieren.","table":[["Mittel","Regel","Beispiele"],["Kompositum","Grundwort am Ende bestimmt Genus","die Haus**tür**, der Tür**schlüssel**"],["Fugen-s","oft nach -ung, -heit, -keit, -ion","Wohnung**s**markt, Gesundheit**s**system"],["-ung/-heit/-keit","feminin, abstrakt","die Lösung, die Freiheit, die Möglichkeit"],["-bar / -los","möglich / ohne","lesbar, essbar / arbeitslos, kostenlos"],["un- / miss-","Gegenteil / falsch","unklar / Missverständnis"],["Nominalisierung","das + Infinitiv","das Lernen, beim Autofahren"]],"examples":[{"de":"Die Arbeitszeitverkürzung wird seit Jahren diskutiert.","en":"The reduction of working hours has been discussed for years."},{"de":"Der Wohnungsmarkt in Großstädten ist angespannt.","en":"The housing market in big cities is tight."},{"de":"Das Gesundheitssystem steht unter Druck.","en":"The health system is under pressure."},{"de":"Diese Schrift ist kaum lesbar.","en":"This writing is barely legible."},{"de":"Der Eintritt ist kostenlos.","en":"Admission is free."},{"de":"Das war ein unglückliches Missverständnis.","en":"That was an unfortunate misunderstanding."},{"de":"Er hat sich im Wald verlaufen.","en":"He got lost in the forest."},{"de":"Wir sollten keine Lebensmittel verschwenden.","en":"We shouldn\'t waste food."},{"de":"Beim Autofahren telefoniert man nicht.","en":"You don\'t make phone calls while driving."},{"de":"Das Lernen fällt mir abends schwerer.","en":"Learning is harder for me in the evening."},{"de":"Die Kranken wurden sofort versorgt.","en":"The sick were treated immediately."},{"de":"Ich wünsche dir alles Gute.","en":"I wish you all the best."},{"de":"Die Erreichbarkeit der Mitarbeiter ist geregelt.","en":"The availability of employees is regulated."},{"de":"Die Unvereinbarkeit der Positionen wurde deutlich.","en":"The incompatibility of the positions became clear."},{"de":"Die Nachhaltigkeitsberichte großer Firmen sind oft schwer verständlich.","en":"The sustainability reports of large companies are often hard to understand."}],"vocab":[{"de":"die Wortbildung","en":"word formation"},{"de":"das Kompositum, Komposita","en":"compound"},{"de":"das Grundwort, ¨er","en":"head word (of a compound)"},{"de":"das Bestimmungswort, ¨er","en":"modifier"},{"de":"das Fugenelement, -e","en":"linking element"},{"de":"die Ableitung, -en","en":"derivation"},{"de":"das Suffix, -e","en":"suffix"},{"de":"das Präfix, -e","en":"prefix"},{"de":"die Nominalisierung, -en","en":"nominalisation"},{"de":"erschließen","en":"to work out (meaning)"},{"de":"zerlegen","en":"to break down"},{"de":"verständlich","en":"understandable"},{"de":"missverstehen","en":"to misunderstand"},{"de":"verlaufen (sich)","en":"to get lost"},{"de":"verschwenden","en":"to waste"},{"de":"erreichbar","en":"reachable"},{"de":"unvereinbar","en":"incompatible"},{"de":"kostenlos","en":"free of charge"},{"de":"fehlerhaft","en":"faulty"},{"de":"die Zusammensetzung, -en","en":"composition"}],"reading":"Mark Twain spottete einst, manche deutschen Wörter seien so lang, dass sie eine Perspektive hätten. Tatsächlich ist die Fähigkeit, beliebig lange Zusammensetzungen zu bilden, eine Besonderheit des Deutschen. Ein berühmtes Beispiel war das „Rindfleischetikettierungsüberwachungsaufgabenübertragungsgesetz“, das in Mecklenburg-Vorpommern bis 2013 galt. Was wie ein Ungetüm aussieht, ist bei näherem Hinsehen ganz logisch: Es handelt sich um ein Gesetz, das die Übertragung der Aufgaben zur Überwachung der Etikettierung von Rindfleisch regelt. Wer solche Wörter verstehen will, sollte sie von hinten nach vorne lesen. Das letzte Element, das Grundwort, nennt die Sache und bestimmt den Artikel; alle vorderen Teile präzisieren sie. Ähnlich hilfreich ist die Kenntnis von Suffixen. Ein Wort auf „-keit“ ist feminin und abstrakt, ein Adjektiv auf „-bar“ beschreibt eine Möglichkeit, eines auf „-los“ einen Mangel. So erschließt sich „Unverzichtbarkeit“ fast von selbst: „verzichten“ heißt auf etwas nicht mehr bestehen, „-bar“ macht daraus eine Möglichkeit, „un-“ verneint sie, und „-keit“ macht das Ganze zu einem Nomen – die Eigenschaft, dass man auf etwas nicht verzichten kann. Wer diese Bausteine kennt, muss nicht jedes Wort einzeln lernen, sondern kann einen großen Teil des Wortschatzes ableiten. Für das Leseverstehen auf C1-Niveau ist diese Strategie oft wichtiger als jede Vokabelliste.","tasks":[{"q":"Genus: ___ Haustür (Grundwort: die Tür)","a":"die"},{"q":"Genus: ___ Türschlüssel (Grundwort: der Schlüssel)","a":"der"},{"q":"Genus: ___ Handschuh (Grundwort: der Schuh)","a":"der"},{"q":"Fugenelement: Wohnung + Markt → der Wohnung___markt","a":"s"},{"q":"Fugenelement: Sonne + Brille → die Sonne___brille","a":"n"},{"q":"Suffix: möglich zu lesen → ___","a":"lesbar"},{"q":"Suffix: ohne Arbeit → ___","a":"arbeitslos"},{"q":"Präfix: nicht klar → ___","a":"unklar"},{"q":"Nomen: frei → die ___","a":"Freiheit"},{"q":"Nomen: möglich → die ___","a":"Möglichkeit"},{"q":"Nominalisierung: Ich fahre gern Auto. → Das ___ macht mir Spaß.","a":"Autofahren"},{"q":"Fehler? „Das Hausnummer ist falsch.“","a":"Die Hausnummer ist falsch."}],"exam":[{"q":"Was spottete Mark Twain?","a":"Manche deutschen Wörter seien so lang, dass sie eine Perspektive hätten."},{"q":"Was regelte das lange Gesetz?","a":"Die Übertragung der Aufgaben zur Überwachung der Etikettierung von Rindfleisch."},{"q":"Wie liest man lange Komposita am besten?","a":"Von hinten nach vorne."},{"q":"Was bestimmt das Grundwort?","a":"Die Sache und den Artikel (Genus)."},{"q":"Was bedeutet „Unverzichtbarkeit“?","a":"Die Eigenschaft, dass man auf etwas nicht verzichten kann."},{"q":"Zerlegen Sie „Lebensmittelverschwendung“ und erklären Sie die Bedeutung.","a":"Leben + Mittel = Lebensmittel; Verschwendung = das Verschwenden → das Verschwenden von Lebensmitteln."},{"q":"Bilden Sie fünf Komposita mit „Arbeit“ als Bestimmungswort.","a":"","m":"Arbeitszeit, Arbeitsplatz, Arbeitsvertrag, Arbeitgeber, Arbeitsamt."},{"q":"Erklären Sie die Bedeutung von „-bar“, „-los“ und „un-“ mit je zwei Beispielen.","a":"","m":"„-bar“ bedeutet „kann gemacht werden“: lesbar, machbar. „-los“ bedeutet „ohne“: arbeitslos, hilflos. „un-“ bedeutet „nicht“: unklar, unmöglich."},{"q":"Finden Sie in einem Zeitungsartikel drei lange Wörter und zerlegen Sie sie.","a":"","m":"Krankenversicherungsbeitrag = Kranken + Versicherung + Beitrag. Wohnungsmarkt = Wohnung + Markt. Geschwindigkeitsbegrenzung = Geschwindigkeit + Begrenzung."},{"q":"Vergleichen Sie die Wortbildung im Deutschen mit Ihrer Muttersprache.","a":"","m":"Im Deutschen schreibt man Komposita zusammen. Im Englischen schreibt man sie oft getrennt, zum Beispiel „health insurance“ statt „Krankenversicherung“."}],"speak":["Erfinde ein langes Kompositum und lass deinen Partner es erklären.","Erkläre „Kindergartenplatz“, „Mietpreisbremse“ und „Umweltschutzorganisation“.","Welche Suffixe machen Nomen feminin? Nenne Beispiele.","Spielt: Einer sagt ein Verb, der andere bildet Nomen und Adjektive daraus."],"dialog":[{"who":"Aiko","de":"Leila, was bedeutet „Fahrgastrechteverordnung“? Das Wort steht auf meinem Bahnticket."},{"who":"Leila","de":"Lies es von hinten: „Verordnung“ – eine Vorschrift. Wofür? Für „Rechte“. Wessen Rechte? Der „Fahrgäste“."},{"who":"Aiko","de":"Also eine Vorschrift über die Rechte der Fahrgäste."},{"who":"Leila","de":"Genau. Zum Beispiel, dass man bei Verspätung Geld zurückbekommt."},{"who":"Aiko","de":"Und „Erstattungsfähigkeit“?"},{"who":"Leila","de":"„Erstatten“ ist zurückzahlen, „-fähig“ heißt möglich, „-keit“ macht ein Nomen daraus. Ob etwas zurückgezahlt werden kann."},{"who":"Aiko","de":"Das ist ja wie ein Puzzle!"}],"dq":[{"q":"Wie soll man lange Wörter lesen?","a":"Von hinten nach vorne."},{"q":"Was ist eine „Fahrgastrechteverordnung“?","a":"Eine Vorschrift über die Rechte der Fahrgäste."},{"q":"Was bedeutet „Erstattungsfähigkeit“?","a":"Ob etwas zurückgezahlt werden kann."}],"en":{"title":"Word formation: compounds, derivations, nominalisation","theme":"Understanding words you don\'t know","expl":["German builds new words mainly by **compounding**: the **last word decides the meaning and the gender**: __die Haustür__ (a door), __der Türschlüssel__ (a key).","Between the parts there are often linking letters (-s-, -es-, -n-, -en-, -er-): __Arbeitszeit, Liebesbrief, Sonnenbrille, Kinderwagen__.","Prefixes and suffixes change meaning and word class: un- (not), -bar (-able), -los (-less), -ung / -heit / -keit (nouns). If you know the root, you can understand words you have never seen."],"use":""},"check":[{"re":"\\\\b\\\\w{12,}\\\\b","label":"long compound words"}]},{"n":57,"pos":68,"level":"C2","title":"Register und Idiomatik: von gehoben bis umgangssprachlich","theme":"Sprachgefühl","scene":"party","rec":[52,55,56],"expl":["Auf C2 wählt man das **Register** bewusst: gehoben/schriftsprachlich (__erörtern, seitens, obliegen__), neutral (__besprechen, von, gehören zu__), umgangssprachlich (__durchkauen, von wegen, gehört ihm halt__).","Dieselbe Aussage klingt je nach Register völlig anders: __Ich bitte um Mitteilung.__ – __Sag mir bitte Bescheid.__ – __Sag mal an!__","**Idiome** sind register- und kontextgebunden: __den Nagel auf den Kopf treffen__ (neutral), __ins Gras beißen__ (salopp), __das Zeitliche segnen__ (gehoben/ironisch).","Warnsignale für Fehlgriffe: Idiome in Sachtexten, Amtsdeutsch in privaten Mails, Jugendsprache im Bewerbungsschreiben."],"use":"Sicher zwischen Situationen wechseln, Nuancen erkennen, Texte stilistisch überarbeiten.","table":[["Umgangssprachlich","Neutral","Gehoben / formell"],["Das geht gar nicht.","Das ist nicht in Ordnung.","Dies ist nicht hinnehmbar."],["Ich meld mich.","Ich melde mich.","Ich werde mich mit Ihnen in Verbindung setzen."],["Das kostet \'ne Stange Geld.","Das ist teuer.","Damit sind erhebliche Kosten verbunden."],["Keine Ahnung.","Das weiß ich nicht.","Hierzu liegen mir keine Informationen vor."],["Mach hin!","Beeil dich bitte.","Ich bitte um zügige Bearbeitung."],["Der ist voll gut.","Der ist sehr gut.","Dies ist von hoher Qualität."]],"examples":[{"de":"Damit sind erhebliche Kosten verbunden.","en":"Considerable costs are associated with this."},{"de":"Hierzu liegen mir derzeit keine Informationen vor.","en":"I currently have no information on this."},{"de":"Ich erlaube mir, Sie an den Termin zu erinnern.","en":"I take the liberty of reminding you of the appointment."},{"de":"Das trifft den Nagel auf den Kopf.","en":"That hits the nail on the head."},{"de":"Er hat den Bericht schnell durchgekaut.","en":"He quickly ploughed through the report. (colloquial)"},{"de":"Von wegen einfach – das war die Hölle!","en":"Easy, my foot – that was hell! (colloquial)"},{"de":"Seitens der Behörde bestehen keine Bedenken.","en":"On the part of the authority there are no objections."},{"de":"Wir sollten nicht das Kind mit dem Bade ausschütten.","en":"We shouldn\'t throw the baby out with the bathwater."},{"de":"Das ist im Großen und Ganzen gelungen.","en":"On the whole that worked out."},{"de":"Es obliegt der Leitung, darüber zu entscheiden.","en":"It is incumbent on the management to decide."},{"de":"Ich habe keinen Bock auf diese Party.","en":"I don\'t fancy this party at all."},{"de":"Mitnichten ist dies eine leichte Aufgabe.","en":"By no means is this an easy task."},{"de":"Für das Konzert mussten wir ganz schön blechen.","en":"We had to cough up quite a bit for the concert."},{"de":"Er geht mir mit seinen Fragen total auf den Keks.","en":"He really gets on my nerves with his questions."},{"de":"Ich habe die Nase voll von den ständigen Verspätungen.","en":"I\'m fed up with the constant delays."},{"de":"Mit dieser Bemerkung ist sie ins Fettnäpfchen getreten.","en":"She put her foot in it with that remark."},{"de":"Hör auf, um den heißen Brei herumzureden!","en":"Stop beating about the bush!"},{"de":"Du hast den Nagel auf den Kopf getroffen.","en":"You\'ve hit the nail on the head."},{"de":"Wir sollten die Steuererklärung nicht länger auf die lange Bank schieben.","en":"We shouldn\'t put off the tax return any longer."},{"de":"Hast du Tomaten auf den Augen? Das Schild ist doch riesig!","en":"Are you blind? The sign is huge!"}],"vocab":[{"de":"das Register, -","en":"register"},{"de":"gehoben","en":"elevated, formal"},{"de":"salopp","en":"casual"},{"de":"die Umgangssprache","en":"colloquial language"},{"de":"hinnehmbar","en":"acceptable"},{"de":"Bedenken haben","en":"to have reservations"},{"de":"obliegen","en":"to be incumbent on"},{"de":"sich erlauben","en":"to take the liberty"},{"de":"die Anrede, -n","en":"form of address"},{"de":"angemessen","en":"appropriate"},{"de":"die Wendung, -en","en":"phrase, idiom"},{"de":"überarbeiten","en":"to revise"},{"de":"geziemend","en":"seemly (elevated)"},{"de":"beschwerlich","en":"arduous"},{"de":"die Obrigkeit","en":"authorities (elevated, dated)"},{"de":"mitnichten","en":"by no means (elevated)"},{"de":"fürwahr","en":"indeed (archaic)"},{"de":"abkratzen","en":"to kick the bucket (vulgar)"},{"de":"pennen","en":"to sleep (colloquial)"},{"de":"die Kohle","en":"dough, cash (colloquial)"},{"de":"blechen","en":"to cough up (money) (colloquial)"},{"de":"der Kumpel, -","en":"mate (colloquial)"},{"de":"krass","en":"extreme, awesome (youth language)"},{"de":"Bock haben auf","en":"to fancy (colloquial)"},{"de":"jemandem auf den Keks gehen","en":"to get on someone\'s nerves"},{"de":"die Nase voll haben","en":"to be fed up"},{"de":"ins Fettnäpfchen treten","en":"to put one\'s foot in it"},{"de":"etwas auf die lange Bank schieben","en":"to put something off"},{"de":"jemandem reinen Wein einschenken","en":"to tell someone the plain truth"},{"de":"den Nagel auf den Kopf treffen","en":"to hit the nail on the head"},{"de":"um den heißen Brei herumreden","en":"to beat about the bush"},{"de":"Tomaten auf den Augen haben","en":"to be blind to the obvious"}],"reading":"Drei Fassungen derselben Nachricht. Privat: „Hey, ich schaff\'s morgen nicht, sorry! Machen wir Freitag?“ Neutral: „Hallo Anna, leider klappt es morgen nicht. Passt dir Freitag?“ Formell: „Sehr geehrte Frau Berger, leider muss ich den morgigen Termin absagen. Ich bitte um Verständnis und schlage Freitag als Ausweichtermin vor.“ Alle drei sind korrekt – unpassend wird es erst, wenn man sie vertauscht.","tasks":[{"q":"Formeller: „Ich sag dir Bescheid.“","a":"Ich werde Sie informieren / in Kenntnis setzen."},{"q":"Formeller: „Das geht nicht.“","a":"Das ist leider nicht möglich."},{"q":"Umgangssprachlicher: „Das ist sehr teuer.“","a":"Das kostet \'ne Stange Geld."},{"q":"Register bestimmen: „Hierzu liegen keine Daten vor.“","a":"gehoben/formell"},{"q":"Register bestimmen: „Keine Ahnung.“","a":"umgangssprachlich"},{"q":"Idiom erklären: „auf dem Holzweg sein“","a":"sich irren / auf dem falschen Weg sein"},{"q":"Idiom erklären: „etwas auf die lange Bank schieben“","a":"etwas aufschieben"},{"q":"[Mix] ___ der Behörde bestehen keine Bedenken. (gehobene Präposition)","a":"Seitens"},{"q":"[Mix] Es ___ der Leitung, darüber ___ ___. (obliegen; entscheiden)","a":"obliegt / zu entscheiden"},{"q":"[Mix] Schreibe formell: „Sag mal, wann kommst du?“","a":"Dürfte ich fragen, wann Sie kommen?"},{"q":"Umgangssprache → neutral: pennen →","a":"schlafen"},{"q":"Umgangssprache → neutral: die Kohle → das ___","a":"Geld"},{"q":"Umgangssprache → neutral: blechen →","a":"bezahlen"},{"q":"Umgangssprache → neutral: Ich habe keinen Bock. → Ich habe keine ___.","a":"Lust"},{"q":"Redewendung: Ich habe die ___ voll. (= Ich habe genug.)","a":"Nase"},{"q":"Redewendung: Er redet um den heißen ___ herum.","a":"Brei"},{"q":"Redewendung: Du hast den Nagel auf den ___ getroffen.","a":"Kopf"},{"q":"Redewendung: etwas auf die lange ___ schieben","a":"Bank"},{"q":"Gehoben → neutral: mitnichten →","a":"keineswegs"},{"q":"Register? „Ich bedaure das Versäumnis zutiefst.“ (gehoben/salopp)","a":"gehoben"}],"exam":[{"q":"Welche drei Fassungen zeigt der Text?","a":"Privat, neutral, formell."},{"q":"Wann wird es unpassend?","a":"Wenn man die Register vertauscht."},{"q":"Welches Wort im formellen Text drückt Höflichkeit aus?","a":"„Ich bitte um Verständnis“."},{"q":"Überarbeiten Sie: „Wir haben das Ding halt verschoben.“ (formell)","a":"Der Termin wurde verschoben."},{"q":"Überarbeiten Sie: „Es wird um Kenntnisnahme gebeten.“ (privat)","a":"Schau dir das bitte kurz an."},{"q":"Nennen Sie ein Idiom für „etwas genau treffen“.","a":"den Nagel auf den Kopf treffen"},{"q":"Warum sind Idiome in Sachtexten riskant?","a":"Sie wirken unpräzise und stilistisch unpassend."},{"q":"Schreiben Sie dieselbe Absage in drei Registern.","a":"","m":"Formell: Bedauerlicherweise ist es mir nicht möglich, an der Sitzung teilzunehmen. Neutral: Leider kann ich morgen nicht zum Treffen kommen. Umgangssprachlich: Sorry, morgen klappt\'s bei mir nicht."},{"q":"Analysieren Sie eine E-Mail aus Ihrem Alltag: Welches Register hat sie?","a":"","m":"Die E-Mail meiner Vermieterin ist formell: Sie benutzt „Sehr geehrter Herr“, den Konjunktiv und Nominalstil wie „zur Kenntnisnahme“."},{"q":"Welche Register beherrschen Sie im Deutschen schon sicher, welche nicht?","a":"","m":"Den neutralen Stil beherrsche ich sicher. Formelle Briefe gelingen mir meistens. Umgangssprache und Dialekt verstehe ich oft noch nicht."}],"speak":["Sag dreimal ab: bei Freunden, bei Kollegen, beim Amt.","Erzähle eine Anekdote und verwende drei Idiome passend.","Übersetze einen Amtssatz spontan in Alltagssprache.","Wann ist zu viel Höflichkeit unhöflich?"],"reading2":{"title":"Ein Ereignis, drei Register","text":"Wie stark das Register die Wirkung einer Aussage bestimmt, zeigt sich, wenn man denselben Sachverhalt in verschiedenen Stilebenen wiedergibt. Angenommen, ein Mitarbeiter hat einen wichtigen Termin verpasst. In der gehobenen Schriftsprache, etwa in einem offiziellen Entschuldigungsschreiben, könnte es heißen: „Ich bedaure zutiefst, dass ich den vereinbarten Termin aufgrund eines bedauerlichen Versehens nicht wahrnehmen konnte, und bitte Sie, mein Versäumnis zu entschuldigen. Selbstverständlich stehe ich Ihnen für einen Ersatztermin jederzeit zur Verfügung.“ Die Sprache ist distanziert, nominal und höflich bis an die Grenze der Unterwürfigkeit. Im neutralen Standarddeutsch, wie man es einem Kollegen am Telefon sagen würde, klingt dasselbe deutlich direkter: „Tut mir leid, ich habe den Termin vergessen. Können wir einen neuen ausmachen?“ Unter Freunden schließlich wird der Ton salopp: „Mist, das Meeting hab ich total verpennt! Peinlich, oder?“ Hier fallen Endungen weg, Kraftausdrücke und Modewörter tauchen auf, und gerade die Selbstironie schafft Nähe. Für fortgeschrittene Lernende liegt die eigentliche Herausforderung nicht darin, diese Varianten zu verstehen, sondern sie situationsgerecht einzusetzen. Wer im Gespräch mit der Vorgesetzten „verpennt“ sagt, wirkt respektlos; wer im Freundeskreis von einem „bedauerlichen Versehen“ spricht, erntet bestenfalls Gelächter. Besonders tückisch sind Redewendungen. Ihr Reiz liegt in der Bildhaftigkeit, doch nicht jede passt in jeden Kontext. „Jemandem reinen Wein einschenken“ ist in einer Besprechung durchaus angemessen, „jemandem auf den Keks gehen“ eher nicht. Ein guter Indikator ist die Frage, ob man den Ausdruck in einer seriösen Tageszeitung lesen würde. Lautet die Antwort Nein, gehört er in die Kaffeeküche, nicht in die E-Mail an die Geschäftsführung."},"dialog":[{"who":"Tomás","de":"Leila, ich habe meinem Chef geschrieben: „Ich hab null Bock auf das Meeting.“ War das zu krass?"},{"who":"Leila","de":"Wie bitte? Das hast du nicht wirklich geschrieben!"},{"who":"Tomás","de":"Doch … Er hat bisher nicht geantwortet."},{"who":"Leila","de":"Da bist du aber ganz schön ins Fettnäpfchen getreten. „Bock haben“ sagt man unter Freunden, aber nicht zum Chef."},{"who":"Tomás","de":"Und was hätte ich schreiben sollen?"},{"who":"Leila","de":"Zum Beispiel: „Leider sehe ich mich nicht in der Lage, an dem Meeting teilzunehmen.“ Oder neutral: „Leider kann ich nicht am Meeting teilnehmen.“"},{"who":"Tomás","de":"Okay, ich schreibe ihm sofort eine Entschuldigung. Ganz gehoben."},{"who":"Leila","de":"Nicht übertreiben! Sonst klingt es ironisch. Neutral und ehrlich reicht völlig."}],"dq":[{"q":"Was hat Tomás seinem Chef geschrieben?","a":"„Ich hab null Bock auf das Meeting.“"},{"q":"Was wäre eine neutrale Formulierung?","a":"„Leider kann ich nicht am Meeting teilnehmen.“"},{"q":"Warum soll Tomás nicht übertreiben?","a":"Sonst klingt es ironisch."}],"en":{"title":"Register and idiom: from formal to colloquial","theme":"A feel for language","expl":["At C2 you choose the **register** deliberately: formal/written (__erörtern, seitens, obliegen__), neutral (__besprechen, von, gehören zu__) or colloquial (__durchkauen, von wegen, halt__).","The same message sounds completely different: __Ich bitte um Mitteilung.__ – __Sag mir bitte Bescheid.__ – __Sag mal Bescheid, ja?__ (all = \\"Please let me know\\").","Idioms bring colour but must match the situation: what\'s witty in a conversation can be out of place in a report."],"use":""},"check":[{"re":"\\\\b(leider|bedauerlicherweise|sorry|schade|ich muss absagen|kann ich nicht)\\\\b","label":"register variety (bedauerlicherweise / leider / sorry)"}]},{"n":58,"pos":69,"level":"C2","title":"Komplexe Satzstrukturen: Partizipialsätze, Ellipsen, Inversion","theme":"Stil und Rhythmus","scene":"office","rec":[51,53,54],"expl":["**Partizipialsätze** verkürzen Nebensätze: __**In Berlin angekommen**, rief er sofort an.__ (= Nachdem er in Berlin angekommen war …) · __**Auf die Kritik reagierend**, änderte die Firma den Plan.__","**Infinitivkonstruktionen** ersetzen dass-Sätze: __**Ohne** lange **zu zögern**, unterschrieb sie.__","**Ellipsen** lassen Bekanntes weg – typisch für Titel, Notizen, Dialoge: __Ende der Debatte. Kein Kommentar. Warum auch?__","**Inversion zur Betonung**: Wichtiges auf Position 1: __**Nur selten** gelingt ein solcher Wurf.__ · __**So groß** war die Enttäuschung, dass …__","**Vorfeld bewusst wählen**: Was dort steht, ist Thema oder Kontrast – das steuert den Textfluss (Thema-Rhema)."],"use":"Literarisch und journalistisch schreiben, Rhythmus variieren, dichte Texte entschlüsseln.","table":[["Struktur","Beispiel","Aufgelöst"],["Partizip II-Satz","**Gut vorbereitet**, ging sie in die Prüfung.","Weil sie gut vorbereitet war, …"],["Partizip I-Satz","**Lachend** verließ er den Raum.","Er lachte, während er den Raum verließ."],["Infinitiv mit ohne/statt","**Ohne zu fragen**, nahm er das Auto.","Er fragte nicht und nahm …"],["Ellipse","Kein Grund zur Panik.","Es gibt keinen Grund zur Panik."],["Inversion (Betonung)","**Kaum** hatte er begonnen, klingelte das Telefon.","Als er kaum begonnen hatte, …"],["Vorfeld-Kontrast","**Dieses Argument** halte ich für schwach.","Ich halte dieses Argument für schwach."]],"examples":[{"de":"Vom Erfolg überrascht, plante das Team eine zweite Auflage.","en":"Surprised by the success, the team planned a second edition."},{"de":"Kaum angekommen, musste sie schon wieder los.","en":"Hardly having arrived, she had to leave again."},{"de":"Ohne lange zu überlegen, sagte er zu.","en":"Without thinking long, he agreed."},{"de":"Nur wenige wissen, wie das Verfahren wirklich funktioniert.","en":"Only few know how the procedure really works."},{"de":"So überzeugend war der Vortrag, dass niemand widersprach.","en":"So convincing was the talk that nobody objected."},{"de":"Kein Wort über die Kosten.","en":"Not a word about the costs."},{"de":"Gestern noch Favorit, heute ausgeschieden.","en":"Yesterday still the favourite, today knocked out."},{"de":"Auf lange Sicht betrachtet, lohnt sich die Investition.","en":"Viewed in the long run, the investment pays off."},{"de":"Ausgerechnet am Freitag fiel der Strom aus.","en":"Of all days, the power failed on Friday."},{"de":"Was die Kosten betrifft, so sind sie kalkulierbar.","en":"As far as the costs are concerned, they are calculable."},{"de":"Kaum dass er angekommen war, klingelte das Telefon.","en":"No sooner had he arrived than the phone rang."},{"de":"In Berlin angekommen, suchte sie sich sofort eine Wohnung.","en":"Having arrived in Berlin, she immediately looked for a flat."},{"de":"Vom Lärm geweckt, stand er auf.","en":"Woken by the noise, he got up."},{"de":"So schwierig die Aufgabe auch sein mag, wir lösen sie.","en":"However difficult the task may be, we\'ll solve it."},{"de":"Sei es aus Angst, sei es aus Bequemlichkeit – er schwieg.","en":"Be it out of fear or out of convenience – he remained silent."},{"de":"Er spricht kaum Englisch, geschweige denn Chinesisch.","en":"He hardly speaks English, let alone Chinese."},{"de":"Wie dem auch sei, wir müssen eine Entscheidung treffen.","en":"Be that as it may, we have to make a decision."},{"de":"Nicht der Preis ist das Problem, sondern die Qualität.","en":"It\'s not the price that\'s the problem, but the quality."},{"de":"Gestern Abend, nach einem langen Tag im Büro, kam er endlich nach Hause.","en":"Last night, after a long day at the office, he finally came home."},{"de":"Er hat mehr verdient als erwartet.","en":"He earned more than expected. (Vergleich im Nachfeld)"}],"vocab":[{"de":"die Ellipse, -n","en":"ellipsis"},{"de":"die Betonung, -en","en":"emphasis"},{"de":"der Vortrag, ¨e","en":"talk, lecture"},{"de":"zusagen","en":"to agree, accept"},{"de":"ausscheiden","en":"to drop out"},{"de":"kalkulierbar","en":"calculable"},{"de":"ausgerechnet","en":"of all things"},{"de":"die Auflage, -n","en":"edition, requirement"},{"de":"widersprechen","en":"to contradict"},{"de":"verdichten","en":"to condense"},{"de":"der Rhythmus","en":"rhythm"},{"de":"knapp","en":"concise, scarce"},{"de":"kaum dass","en":"no sooner had … than"},{"de":"geschweige denn","en":"let alone"},{"de":"von … ganz zu schweigen","en":"not to mention …"},{"de":"ob … oder","en":"whether … or"},{"de":"sei es … sei es","en":"be it … or"},{"de":"wie dem auch sei","en":"be that as it may"},{"de":"so … auch","en":"however … may"},{"de":"die Inversion, -en","en":"inversion"},{"de":"der Partizipialsatz, ¨e","en":"participial clause"},{"de":"das Satzgefüge, -","en":"complex sentence"},{"de":"die Satzklammer, -n","en":"sentence bracket"},{"de":"das Vorfeld","en":"first position (before the verb)"},{"de":"das Mittelfeld","en":"middle field"},{"de":"das Nachfeld","en":"final field (after the bracket)"},{"de":"die Ausklammerung","en":"moving elements after the bracket"},{"de":"das Stilmittel, -","en":"stylistic device"},{"de":"die Wiederholung, -en","en":"repetition"},{"de":"der Spannungsbogen, ¨","en":"arc of suspense"},{"de":"die Prägnanz","en":"conciseness"},{"de":"gestelzt","en":"stilted"}],"reading":"Aus einer Reportage: „Kaum eröffnet, schon überlaufen. Das kleine Café in der Seitenstraße, von zwei Schwestern geführt, zieht seit Wochen Gäste aus der ganzen Stadt an. Ohne große Werbung, allein durch Empfehlungen, ist es bekannt geworden. Gefragt nach dem Geheimnis, lacht die ältere Schwester: ‚Guter Kaffee. Mehr nicht.‘ Was die Zukunft betrifft, so bleiben beide vorsichtig: Expansion? Vorerst nicht.“","tasks":[{"q":"Auflösen: Gut vorbereitet, ging sie in die Prüfung.","a":"Weil sie gut vorbereitet war, ging sie in die Prüfung."},{"q":"Auflösen: Kaum angekommen, musste er wieder los.","a":"Kaum war er angekommen, musste er wieder los."},{"q":"Verdichten: Weil er vom Erfolg überrascht war, plante er mehr.","a":"Vom Erfolg überrascht, plante er mehr."},{"q":"Verdichten: Er fragte nicht und nahm das Auto.","a":"Ohne zu fragen, nahm er das Auto."},{"q":"Ellipse auflösen: Kein Grund zur Sorge.","a":"Es gibt keinen Grund zur Sorge."},{"q":"Betonung: Ich halte dieses Argument für schwach. (Argument betonen)","a":"Dieses Argument halte ich für schwach."},{"q":"Inversion: Der Vortrag war so gut, dass alle blieben.","a":"So gut war der Vortrag, dass alle blieben."},{"q":"[Mix] ___ nach dem Geheimnis, lacht sie. (fragen, Part. II)","a":"Gefragt"},{"q":"[Mix] Das Café, ___ zwei Schwestern geführt, ist beliebt. (Partizip + von)","a":"von"},{"q":"[Mix] Was die Kosten ___, so sind sie tragbar. (betreffen)","a":"betrifft"},{"q":"Partizipialsatz: Nachdem sie in Berlin angekommen war, rief sie an. → In Berlin ___, rief sie an.","a":"angekommen"},{"q":"Partizipialsatz: Weil er vom Lärm geweckt worden war, stand er auf. → Vom Lärm ___, stand er auf.","a":"geweckt"},{"q":"kaum dass: Er war gerade eingeschlafen, da klingelte es. → Kaum ___ er eingeschlafen war, klingelte es.","a":"dass"},{"q":"Konzessiv: Auch wenn es schwer ist … → So schwer es ___ ist, …","a":"auch"},{"q":"geschweige denn: Er kann nicht laufen, ___ ___ rennen.","a":"geschweige denn"},{"q":"Vorfeld (Ursache betonen): Die Firma schloss wegen der Krise. → Wegen der Krise ___ die Firma.","a":"schloss"},{"q":"Vorfeld (Handlung betonen): Er hat das Buch nie gelesen. → Gelesen ___ er das Buch nie.","a":"hat"},{"q":"sei es … sei es: ___ es aus Zeitmangel, sei es aus Desinteresse – er kam nicht.","a":"Sei"},{"q":"Konnektor: Wie dem ___ sei, wir fangen an.","a":"auch"},{"q":"Fehler? „Kaum dass er war angekommen, rief er an.“","a":"Kaum dass er angekommen war, rief er an."}],"exam":[{"q":"Wie wurde das Café bekannt?","a":"Durch Empfehlungen, ohne große Werbung."},{"q":"Was ist das Geheimnis laut der Schwester?","a":"Guter Kaffee."},{"q":"Planen sie eine Expansion?","a":"Vorerst nicht."},{"q":"Nennen Sie zwei Wirkungen von Ellipsen.","a":"Tempo, Betonung/Verdichtung"},{"q":"Wann wirken Partizipialsätze unpassend?","a":"In einfachen Alltagstexten oder gesprochener Sprache"},{"q":"Formulieren Sie mit Inversion: Er hatte kaum begonnen, als es klingelte.","a":"Kaum hatte er begonnen, klingelte es."},{"q":"Verdichten Sie: Nachdem sie das Ergebnis gesehen hatte, änderte sie den Plan.","a":"Das Ergebnis gesehen habend / Nach Sichtung des Ergebnisses änderte sie den Plan."},{"q":"Schreiben Sie einen Reportage-Absatz (80 Wörter) mit Ellipse, Partizipialsatz und Inversion.","a":"","m":"Sechs Uhr morgens. Der Markt erwacht. Kisten voller Mangos werden abgeladen, Händler rufen ihre Preise, irgendwo zischt eine Kaffeemaschine. Am Stand angekommen, packt die alte Frau ihre Waren aus: Tomaten, Kräuter, Eier vom eigenen Hof. Nie hat sie einen Markttag verpasst. Vierzig Jahre lang. Bei Regen, bei Hitze, bei Schnee. Ihre Kunden kennt sie mit Namen, ihre Geschichten auch. Gefragt, warum sie nicht aufhöre, lacht sie nur. Dann wiegt sie die nächsten Tomaten ab."},{"q":"Lesen Sie einen Absatz laut und variieren Sie den Rhythmus.","a":"","m":"Langsam und ruhig: „Der Abend war still.“ Dann schnell: „Plötzlich klingelte das Telefon!“ So entsteht Spannung."},{"q":"Welche Wirkung hat ein sehr kurzer Satz nach mehreren langen?","a":"","m":"Ein sehr kurzer Satz nach langen Sätzen wirkt wie ein Schlag. Er betont eine wichtige Aussage und erzeugt Spannung."}],"speak":["Erzähle den Café-Text frei, mit knappem Rhythmus.","Beschreibe deinen Tag in fünf Ellipsen.","Betone drei verschiedene Satzteile durch die Vorfeldwahl.","Wann klingt Verdichtung elegant, wann gekünstelt?"],"reading2":{"title":"Stilübung: Ein Satz, viele Möglichkeiten","text":"Die deutsche Satzstellung gilt als streng, doch gerade die feste Verbposition eröffnet erstaunliche stilistische Freiräume. Das Vorfeld, also die Position vor dem konjugierten Verb, kann fast jedes Satzglied aufnehmen – und was dort steht, erhält besonderes Gewicht. Man vergleiche: „Die Ministerin hat den Bericht gestern nach heftiger Kritik zurückgezogen.“ Neutral, sachlich, das Subjekt im Vorfeld. „Gestern hat die Ministerin den Bericht nach heftiger Kritik zurückgezogen“ rückt den Zeitpunkt in den Vordergrund, etwa als Anschluss an eine vorherige Meldung. „Nach heftiger Kritik hat die Ministerin den Bericht gestern zurückgezogen“ betont die Ursache. Und „Zurückgezogen hat die Ministerin den Bericht erst nach heftiger Kritik“ legt den Fokus auf die Handlung selbst, oft mit einem kritischen Unterton. Ebenso wirkungsvoll sind Partizipialkonstruktionen, die einen Nebensatz verdichten: Aus „Nachdem sie in Berlin angekommen war, rief sie ihre Mutter an“ wird „In Berlin angekommen, rief sie ihre Mutter an“. Der Satz gewinnt an Tempo und Prägnanz, verliert allerdings an Präzision, denn das zeitliche Verhältnis wird nur angedeutet. In literarischen Texten finden sich zudem Ellipsen, also bewusst unvollständige Sätze: „Ein Knall. Dann Stille. Niemand rührte sich.“ Solche Fragmente erzeugen Spannung, weil sie den Leser zwingen, die Lücken selbst zu füllen. Wer diese Mittel einsetzt, sollte jedoch Maß halten. Ein Text, der ausschließlich aus Inversionen und Partizipialsätzen besteht, wirkt schnell gestelzt. Guter Stil entsteht durch Abwechslung: kurze Sätze neben langen, einfache Hauptsätze neben kunstvollen Satzgefügen. Oder, wie es ein Schreiblehrer formulierte: Der Rhythmus eines Textes ist wie der Atem eines Menschen – nur wer ihn variiert, wirkt lebendig."},"dialog":[{"who":"Lektorin","de":"Ihr Manuskript gefällt mir, aber einige Sätze sind schwer lesbar."},{"who":"Autor","de":"Zum Beispiel?"},{"who":"Lektorin","de":"Hier: „Der von der seit Jahren mit finanziellen Problemen kämpfenden Firma entlassene Mitarbeiter klagte.“"},{"who":"Autor","de":"Zugegeben, das ist etwas verschachtelt."},{"who":"Lektorin","de":"Etwas? Teilen Sie es auf: „Die Firma kämpft seit Jahren mit Geldproblemen. Ein entlassener Mitarbeiter klagte.“"},{"who":"Autor","de":"Dann geht aber die Verdichtung verloren."},{"who":"Lektorin","de":"Wie dem auch sei – Verständlichkeit geht vor. Und im dritten Kapitel könnten Sie mehr mit kurzen Sätzen arbeiten. Gerade in der Verfolgungsjagd."},{"who":"Autor","de":"Sie meinen Ellipsen? „Schritte. Ein Schatten. Dann nichts.“"},{"who":"Lektorin","de":"Genau so."}],"dq":[{"q":"Was kritisiert die Lektorin?","a":"Einige Sätze sind schwer lesbar (zu verschachtelt)."},{"q":"Was schlägt sie für den langen Satz vor?","a":"Ihn in zwei Sätze aufzuteilen."},{"q":"Wo soll der Autor kurze Sätze verwenden?","a":"Im dritten Kapitel, in der Verfolgungsjagd."}],"en":{"title":"Complex sentence structures: participle clauses, ellipsis, inversion","theme":"Style and rhythm","expl":["**Participle clauses** shorten subordinate clauses: __In Berlin angekommen, rief er sofort an.__ (= After he had arrived in Berlin …).","**Infinitive constructions** replace dass-clauses: __Ohne lange zu zögern, unterschrieb sie.__","**Ellipsis** leaves out what\'s known – typical in titles, notes and speech. **Inversion** puts the important element first for emphasis: __Nie hätte ich das gedacht.__"],"use":""},"check":[{"re":"^\\\\s*\\\\w+[^.!?]{0,40}(gekommen|angekommen|geworden|reagierend|gesehen|angelangt),|^\\\\s*(nie|selten|kaum|erst)\\\\s+\\\\w+","label":"participle clause or inversion"}]},{"n":59,"pos":70,"level":"C2","title":"Nuancen: Hedging, Ironie, Intensivierung","theme":"Zwischen den Zeilen","scene":"party","rec":[49,52,57],"expl":["C2 heißt: **Zwischentöne** treffen.","**Abschwächen (Hedging):** __eher, tendenziell, vergleichsweise, in gewisser Hinsicht, nicht ganz unproblematisch, dürfte, scheint … zu sein, soweit ich sehe__","**Verstärken:** __ausgesprochen, überaus, ausgesprochen gut, durchaus, gerade(zu), bei Weitem, ohne Frage, nicht zuletzt__","**Litotes (Untertreibung durch Verneinung):** __nicht schlecht = sehr gut__, __nicht uninteressant__, __kein geringer Betrag__","**Ironie** entsteht durch Kontrast zwischen Aussage und Kontext, oft mit Partikeln: __Na, das ist ja **großartig** gelaufen.__ Im Schriftlichen ist Ironie riskant – sie braucht klare Signale.","**Distanz markieren:** __angeblich, vermeintlich, so genannte, „…“__"],"use":"Diplomatisch formulieren, Kritik dosieren, Texte und Gesprächstöne richtig deuten.","table":[["Wirkung","Mittel","Beispiel"],["abschwächen","eher, tendenziell, dürfte","Das Ergebnis ist **eher** überraschend."],["stark abschwächen","nicht ganz un-…","Der Plan ist **nicht ganz unproblematisch**."],["verstärken","ausgesprochen, überaus","Die Lösung ist **ausgesprochen** elegant."],["verstärken (Kontrast)","durchaus, sehr wohl","Das ist **durchaus** möglich."],["Untertreibung","nicht schlecht, kein geringer","**Kein geringer** Aufwand."],["Distanz","angeblich, vermeintlich, so genannt","Die **vermeintliche** Lösung schuf neue Probleme."],["Ironie","Partikel + Kontext","Das hat ja **wunderbar** funktioniert."]],"examples":[{"de":"Das Argument ist nicht ganz unberechtigt.","en":"The argument is not entirely unjustified."},{"de":"Die Zahlen dürften eher optimistisch sein.","en":"The figures are likely to be rather optimistic."},{"de":"Das Konzept überzeugt durchaus, in Teilen jedoch nicht.","en":"The concept is quite convincing, though not in parts."},{"de":"Der Aufwand war alles andere als gering.","en":"The effort was anything but small."},{"de":"Soweit ich sehe, fehlen belastbare Daten.","en":"As far as I can see, robust data are missing."},{"de":"Die vermeintliche Abkürzung kostete uns zwei Stunden.","en":"The supposed shortcut cost us two hours."},{"de":"Ihr Vorschlag ist überaus hilfreich.","en":"Your suggestion is extremely helpful."},{"de":"Na, das war ja ein voller Erfolg.","en":"Well, that was a complete success. (ironic)"},{"de":"Nicht zuletzt deshalb ist die Kritik berechtigt.","en":"Not least for that reason the criticism is justified."},{"de":"In gewisser Hinsicht haben beide Seiten recht.","en":"In a certain sense both sides are right."},{"de":"Das Ergebnis ist durchaus ausbaufähig.","en":"There is definitely room for improvement in the result."},{"de":"Ihre Präsentation war nicht ganz unproblematisch.","en":"Your presentation was not entirely without problems."},{"de":"Das ist, gelinde gesagt, eine Überraschung.","en":"That is, to put it mildly, a surprise."},{"de":"Na, das hast du ja wieder großartig hingekriegt!","en":"Well, you\'ve done a brilliant job again! (ironic)"},{"de":"Der Vorschlag ist nicht uninteressant.","en":"The proposal is not uninteresting."},{"de":"Die Kommunikation lief suboptimal.","en":"Communication was less than ideal."},{"de":"Das Konzept ist schlichtweg genial.","en":"The concept is simply brilliant."},{"de":"Sie hat es ihm durch die Blume gesagt.","en":"She told him in a roundabout way."},{"de":"Unter Umständen könnte man die Frist verlängern.","en":"Under certain circumstances the deadline could be extended."},{"de":"Das ist keineswegs selbstverständlich.","en":"That is by no means a matter of course."}],"vocab":[{"de":"abschwächen","en":"to soften, tone down"},{"de":"verstärken","en":"to intensify"},{"de":"die Untertreibung, -en","en":"understatement"},{"de":"berechtigt","en":"justified"},{"de":"die Abkürzung, -en","en":"shortcut, abbreviation"},{"de":"dosieren","en":"to measure out"},{"de":"diplomatisch","en":"diplomatic"},{"de":"missverständlich","en":"ambiguous"},{"de":"der Unterton, ¨e","en":"undertone"},{"de":"zwischen den Zeilen","en":"between the lines"},{"de":"andeuten","en":"to hint at"},{"de":"die Zurückhaltung","en":"restraint"},{"de":"gewissermaßen","en":"to a certain extent"},{"de":"gewiss","en":"certainly"},{"de":"tendenziell","en":"tendentially, tend to"},{"de":"unter Umständen","en":"possibly, under certain circumstances"},{"de":"in gewisser Hinsicht","en":"in a certain respect"},{"de":"nicht ganz unproblematisch","en":"not entirely unproblematic"},{"de":"ausbaufähig","en":"with room for improvement"},{"de":"suboptimal","en":"less than ideal"},{"de":"bemerkenswert","en":"remarkable"},{"de":"schlichtweg","en":"simply, downright"},{"de":"ausgesprochen","en":"decidedly"},{"de":"überaus","en":"extremely"},{"de":"keineswegs","en":"by no means"},{"de":"geradezu","en":"virtually, downright"},{"de":"die Ironie","en":"irony"},{"de":"der Euphemismus, Euphemismen","en":"euphemism"},{"de":"die Litotes","en":"litotes (understatement by negation)"},{"de":"die Andeutung, -en","en":"hint, insinuation"},{"de":"etwas durch die Blume sagen","en":"to say something in a roundabout way"},{"de":"jemandem etwas unterstellen","en":"to insinuate something about someone"}],"reading":"Feedbackgespräch: „Ihr Entwurf ist nicht ganz unproblematisch, in Teilen aber ausgesprochen gelungen. Die Struktur überzeugt durchaus; die Datenlage dürfte hingegen eher dünn sein. Soweit ich sehe, fehlt eine Quelle für die zentrale Zahl – kein geringes Problem, wenn der Text veröffentlicht wird. Ich würde vorschlagen, diesen Punkt zu ergänzen. Ansonsten: nicht schlecht für einen ersten Entwurf.“","tasks":[{"q":"Abschwächen: Das ist falsch. → Das ist ___ ___ ___.","a":"nicht ganz richtig"},{"q":"Abschwächen mit Modalverb: Es kostet 500 Euro. → Es ___ etwa 500 Euro kosten.","a":"dürfte"},{"q":"Verstärken: Das ist gut. → Das ist ___ gut.","a":"ausgesprochen"},{"q":"Litotes: Das ist sehr gut. → Das ist ___ ___.","a":"nicht schlecht"},{"q":"Distanz: Die Lösung half nicht. → Die ___ Lösung half nicht.","a":"vermeintliche"},{"q":"Ironisch: Alles ging schief. → Das hat ja ___ geklappt.","a":"wunderbar"},{"q":"Diplomatisch ablehnen: „Nein.“","a":"Das halte ich in dieser Form für schwierig."},{"q":"[Mix] ___ ich sehe, fehlen Daten, ___ belastbar sind. (soweit; Relativpronomen)","a":"Soweit / die"},{"q":"[Mix] Die Datenlage ___ eher dünn sein, ___ die Struktur überzeugt. (dürfen Konj. II; adversativ)","a":"dürfte / wohingegen"},{"q":"[Mix] Es ist davon ___, dass Kritik ___ (kommen, Futur).","a":"auszugehen / kommen wird"},{"q":"Abschwächen: Das ist schlecht. → Das ist ___. (Euphemismus: Es gibt Raum für Verbesserung.)","a":"ausbaufähig"},{"q":"Litotes: Das ist interessant. → Das ist nicht ___.","a":"uninteressant"},{"q":"Euphemismus: Die Firma entlässt Mitarbeiter. → Die Firma ___ Stellen ab. (bauen)","a":"baut"},{"q":"Verstärken: Das ist ___ genial. (schlichtweg/kaum)","a":"schlichtweg"},{"q":"Zeugnis-Code (sehr gut): stets zu unserer ___ Zufriedenheit","a":"vollsten"},{"q":"Zeugnis-Code: „bemühte sich“ bedeutet: Er hatte ___ Erfolg. (keinen/großen)","a":"keinen"},{"q":"Hedging: Das könnte ___ ___ problematisch sein. (unter Umständen)","a":"unter Umständen"},{"q":"Ironie erkennen: „Super, schon wieder Stau!“ meint der Sprecher wörtlich? (ja/nein)","a":"nein"},{"q":"durch die ___ sagen (= indirekt)","a":"Blume"},{"q":"Fehler? „Kaum ein Textsorte ist so typisch deutsch.“","a":"Kaum eine Textsorte ist so typisch deutsch."}],"exam":[{"q":"Wie bewertet der Sprecher die Struktur?","a":"Sie überzeugt durchaus."},{"q":"Was fehlt im Entwurf?","a":"Eine Quelle für die zentrale Zahl."},{"q":"Ist „nicht schlecht“ hier negativ?","a":"Nein – es ist Lob durch Untertreibung."},{"q":"Schwächen Sie ab: „Ihr Plan funktioniert nicht.“","a":"Ihr Plan ist in dieser Form vermutlich schwer umsetzbar."},{"q":"Verstärken Sie: „Das war hilfreich.“","a":"Das war überaus hilfreich."},{"q":"Welche Signale braucht schriftliche Ironie?","a":"Kontext, Partikeln, ggf. Anführungszeichen – sonst missverständlich."},{"q":"Was bedeutet „kein geringer Aufwand“?","a":"Ein sehr großer Aufwand."},{"q":"Geben Sie schriftlich kritisches Feedback zu einem Text – diplomatisch, aber klar.","a":"","m":"Der Text ist insgesamt gut lesbar und durchaus überzeugend. Die Einleitung erscheint mir jedoch etwas lang. An einigen Stellen dürfte eine klarere Struktur helfen. Die Argumente im Mittelteil sind nicht ganz unproblematisch, da Belege fehlen."},{"q":"Formulieren Sie dieselbe Ablehnung dreimal: direkt, neutral, sehr vorsichtig.","a":"","m":"Direkt: Das machen wir nicht. Neutral: Das ist leider nicht möglich. Sehr vorsichtig: Ich fürchte, das dürfte im Moment eher schwierig werden."},{"q":"Wo in Ihrer Kultur ist Untertreibung üblich? Vergleichen Sie.","a":"","m":"In Indien sagt man selten direkt „nein“. Man sagt eher „Mal sehen“ oder „Vielleicht später“. In Deutschland ist man direkter."}],"speak":["Gib Feedback zum Bild – erst lobend, dann kritisch, dann diplomatisch.","Sag dreimal „nein“, jedes Mal höflicher.","Erzähle etwas ironisch – und dann sachlich.","Wie erkennst du Ironie im Deutschen?"],"reading2":{"title":"Das Arbeitszeugnis – eine Geheimsprache","text":"Kaum eine Textsorte veranschaulicht die Kunst des Andeutens so gut wie das deutsche Arbeitszeugnis. Da Arbeitgeber gesetzlich verpflichtet sind, ein „wohlwollendes“ Zeugnis auszustellen, dürfen sie keine offen negativen Formulierungen verwenden. Über Jahrzehnte hat sich deshalb ein Code entwickelt, in dem scheinbar positive Aussagen sehr unterschiedliche Bewertungen transportieren. Der bekannteste Maßstab betrifft die Zufriedenheit: „Er erledigte die ihm übertragenen Aufgaben stets zu unserer vollsten Zufriedenheit“ entspricht der Note „sehr gut“. Fehlt das Wort „stets“, ist es nur noch „gut“. „Zu unserer Zufriedenheit“ bedeutet „befriedigend“, „im Großen und Ganzen zu unserer Zufriedenheit“ dagegen „ausreichend“ – obwohl kein einziges negatives Wort fällt. Noch subtiler sind Formulierungen, die durch das wirken, was sie verschweigen. Wird bei einer Führungskraft nur das Verhältnis zu den Kollegen gelobt, nicht aber das zu den Vorgesetzten, liegt die Vermutung nahe, dass es dort Konflikte gab. Und der Satz „Sie trug durch ihre Geselligkeit zur Verbesserung des Betriebsklimas bei“ kann, je nach Kontext, ein harmloses Lob oder eine diskrete Anspielung auf übermäßige Feierlaune sein. Kritiker halten dieses System für überholt. Es benachteilige Menschen, die den Code nicht kennen, etwa Zugewanderte, und führe dazu, dass Zeugnisse kaum noch aussagekräftig seien, da ohnehin fast alle „sehr gut“ oder „gut“ ausfielen. Befürworter wenden ein, das Zeugnis sei gerade wegen seiner Feinheiten ein differenziertes Instrument. Für Bewerberinnen und Bewerber gilt in jedem Fall: Ein Zeugnis sollte man nicht nur lesen, sondern entschlüsseln – oder von jemandem prüfen lassen, der die Sprache zwischen den Zeilen beherrscht."},"dialog":[{"who":"Ravi","de":"Leila, mein alter Chef hat mir ein Zeugnis geschrieben. Hier steht: „Herr Sharma bemühte sich, die Aufgaben zu unserer Zufriedenheit zu erledigen.“ Klingt doch gut, oder?"},{"who":"Leila","de":"Hm. Ehrlich gesagt: Das ist keineswegs ein gutes Zeugnis."},{"who":"Ravi","de":"Wieso? Da steht nichts Negatives."},{"who":"Leila","de":"„Bemühte sich“ bedeutet: Er hat es versucht, aber nicht geschafft. Und ohne „vollsten“ und „stets“ ist das eher eine Drei."},{"who":"Ravi","de":"Das ist ja geradezu absurd! Ich war einer der Besten im Team."},{"who":"Leila","de":"Dann solltest du um eine Korrektur bitten. Du hast ein Recht auf ein wahres und wohlwollendes Zeugnis."},{"who":"Ravi","de":"Gut, dass du mir das gesagt hast. Ich hätte es sonst einfach so verschickt."}],"dq":[{"q":"Was steht in Ravis Zeugnis?","a":"Er bemühte sich, die Aufgaben zu unserer Zufriedenheit zu erledigen."},{"q":"Was bedeutet „bemühte sich“?","a":"Er hat es versucht, aber nicht geschafft."},{"q":"Was soll Ravi tun?","a":"Um eine Korrektur bitten."}],"en":{"title":"Nuance: hedging, irony, intensifying","theme":"Reading between the lines","expl":["C2 means hitting the **in-between tones**. **Hedging**: eher, tendenziell, vergleichsweise, in gewisser Hinsicht, nicht ganz unproblematisch, dürfte, scheint … zu sein.","**Intensifying**: ausgesprochen, überaus, durchaus, geradezu, bei Weitem, ohne Frage, nicht zuletzt.","**Litotes** (understatement): __nicht ganz unbegründet__ = quite justified. **Irony** says the opposite of what\'s meant – recognisable from context and tone."],"use":""},"check":[{"re":"\\\\b(eher|tendenziell|vergleichsweise|gewisser|nicht ganz|dürfte|scheint|möglicherweise|durchaus|ausgesprochen)\\\\b","label":"hedging and intensifying (eher, nicht ganz unproblematisch, durchaus)"}]},{"n":72,"pos":71,"level":"C2","title":"Literarische Texte analysieren: Erzählperspektive und Stilmittel","theme":"Literatur lesen","scene":"park","rec":[57,58],"expl":["Bei der Analyse literarischer Texte fragt man nicht nur **was** erzählt wird, sondern **wie**. Zentral ist die **Erzählperspektive**: Ein **Ich-Erzähler** erzählt aus eigener Sicht und ist begrenzt glaubwürdig; ein **auktorialer Erzähler** weiß alles, kommentiert und greift vor; ein **personaler Erzähler** bleibt in der Sicht einer Figur, ohne zu kommentieren. Mittel der Innensicht sind **innerer Monolog** und **erlebte Rede** (__Morgen würde sie es ihm sagen. Morgen ganz bestimmt.__ – Gedanken in der 3. Person und im Präteritum).","**Stilmittel** erzeugen Wirkung: **Metapher** (übertragene Bedeutung: __ein Meer aus Tränen__), **Vergleich** (mit wie/als ob), **Personifikation** (__der Wind flüstert__), **Anapher** (Wiederholung am Satzanfang), **Klimax** (Steigerung), **Ellipse**, **Antithese** (Gegensatz), **rhetorische Frage**, **Ironie**. Nicht das Benennen zählt, sondern die **Funktion**: Was bewirkt das Mittel an dieser Stelle?","Für die Interpretation braucht man vorsichtige, belegte Formulierungen: __Dies lässt sich als … deuten. Die Wiederholung unterstreicht … (Z. 12). Auffällig ist … Der Text legt nahe, dass …__ Zitate werden mit Zeilenangabe belegt und in die eigene Sprache eingebettet."],"use":"C2 (Goethe-Zertifikat C2 / Hochschule): literarische und essayistische Texte verstehen, interpretieren und darüber schreiben.","table":[["Begriff","Erklärung","Beispiel"],["Ich-Erzähler","subjektiv, begrenzt","„Ich wusste nicht, dass sie log.“"],["auktorial","allwissend, kommentiert","„Er ahnte nicht, dass dies sein letzter Sommer sein würde.“"],["erlebte Rede","Gedanken, 3. Pers., Präteritum","„Warum rief er nicht an? Hatte er es vergessen?“"],["Metapher","übertragene Bedeutung","„Die Stadt war ein Käfig.“"],["Anapher","Wiederholung am Satzanfang","„Kein Licht. Kein Laut. Kein Mensch.“"],["Antithese","Gegensatz","„Draußen der Sommer, drinnen die Kälte.“"]],"examples":[{"de":"Der Text ist aus der Sicht eines Ich-Erzählers verfasst.","en":"The text is written from the perspective of a first-person narrator."},{"de":"Der auktoriale Erzähler kommentiert das Geschehen aus der Distanz.","en":"The omniscient narrator comments on events from a distance."},{"de":"Durch die erlebte Rede erhält der Leser Einblick in die Gedanken der Figur.","en":"Through free indirect speech the reader gains insight into the character\'s thoughts."},{"de":"Die Metapher „Käfig“ verdeutlicht das Gefühl der Enge.","en":"The metaphor \\"cage\\" illustrates the feeling of confinement."},{"de":"Die Anapher in Zeile 4 bis 6 verstärkt die Eindringlichkeit.","en":"The anaphora in lines 4 to 6 intensifies the urgency."},{"de":"Dies lässt sich als Ausdruck innerer Zerrissenheit deuten.","en":"This can be interpreted as an expression of inner conflict."},{"de":"Auffällig ist der Wechsel vom Präteritum ins Präsens.","en":"What is striking is the switch from the past tense to the present."},{"de":"Der Text legt nahe, dass die Erzählerin ihre Entscheidung bereut.","en":"The text suggests that the narrator regrets her decision."},{"de":"Die kurzen, elliptischen Sätze erzeugen Spannung.","en":"The short, elliptical sentences create suspense."},{"de":"Die Natur wird personifiziert und spiegelt die Stimmung der Figur.","en":"Nature is personified and mirrors the character\'s mood."},{"de":"Der offene Schluss lässt mehrere Deutungen zu.","en":"The open ending allows several interpretations."},{"de":"Mit der rhetorischen Frage bezieht die Autorin den Leser ein.","en":"With the rhetorical question the author involves the reader."},{"de":"Die Ironie liegt im Widerspruch zwischen Worten und Handlung.","en":"The irony lies in the contradiction between words and action."},{"de":"Der Titel kann doppeldeutig verstanden werden.","en":"The title can be understood ambiguously."},{"de":"Sprachlich fällt die Häufung von Verben der Bewegung auf.","en":"Linguistically, the accumulation of verbs of motion is striking."}],"vocab":[{"de":"die Erzählperspektive, -n","en":"narrative perspective"},{"de":"der Ich-Erzähler, -","en":"first-person narrator"},{"de":"der auktoriale Erzähler","en":"omniscient narrator"},{"de":"der personale Erzähler","en":"third-person limited narrator"},{"de":"die erlebte Rede","en":"free indirect speech"},{"de":"der innere Monolog","en":"interior monologue"},{"de":"das Stilmittel, -","en":"stylistic device"},{"de":"die Metapher, -n","en":"metaphor"},{"de":"die Personifikation, -en","en":"personification"},{"de":"die Anapher, -n","en":"anaphora"},{"de":"die Klimax","en":"climax (gradation)"},{"de":"die Antithese, -n","en":"antithesis"},{"de":"die Deutung, -en","en":"interpretation"},{"de":"deuten als","en":"to interpret as"},{"de":"das Leitmotiv, -e","en":"leitmotif"},{"de":"der Wendepunkt, -e","en":"turning point"},{"de":"der offene Schluss","en":"open ending"},{"de":"doppeldeutig","en":"ambiguous"},{"de":"die Zerrissenheit","en":"inner conflict"},{"de":"eindringlich","en":"urgent, forceful"}],"reading":"Textauszug (eigene Kurzgeschichte, Anfang): „Der Zug hatte Verspätung, wie immer. Marta stand am Bahnsteig, den Koffer zwischen den Füßen, und zählte die Tauben auf dem Dach. Sieben. Acht. Eine flog davon. Warum war sie eigentlich hier? Sie hatte doch beschlossen, nicht zurückzufahren. Nie wieder in dieses Dorf, nie wieder an diesen Tisch, nie wieder in dieses Schweigen. Und jetzt? Jetzt stand sie da und wartete auf den Zug, der sie genau dorthin bringen würde. Der Wind zerrte an ihrem Mantel, als wollte er sie zurückhalten.“ – Interpretation: Der Auszug ist aus personaler Perspektive erzählt; der Leser bleibt eng bei Marta, ohne dass ein Erzähler kommentiert. Durch die erlebte Rede („Warum war sie eigentlich hier?“) erhält man unmittelbaren Einblick in ihre Zweifel. Die Anapher „nie wieder … nie wieder … nie wieder“ unterstreicht die Entschiedenheit eines früheren Entschlusses, der durch die folgende Frage „Und jetzt?“ sofort relativiert wird; diese Antithese von Vorsatz und Handlung bildet den Kern des Konflikts. Das Zählen der Tauben in elliptischen Sätzen lässt sich als Versuch deuten, sich von den eigenen Gedanken abzulenken. Die Personifikation des Windes, der „sie zurückhalten“ will, spiegelt Martas inneren Widerstand. Auffällig ist auch das unscheinbare „wie immer“ im ersten Satz: Es deutet an, dass die Reise kein Einzelfall ist und Marta diesen Weg schon oft gegangen ist. Der Auszug legt somit nahe, dass es um eine ambivalente Beziehung zur Herkunft geht – um das Bedürfnis, sich zu lösen, und die Unfähigkeit, es wirklich zu tun.","tasks":[{"q":"Perspektive: „Ich hatte keine Ahnung, was er dachte.“ → ___-Erzähler","a":"Ich"},{"q":"Perspektive: Ein Erzähler weiß alles und kommentiert: ___","a":"auktorial"},{"q":"Gedanken in 3. Person, Präteritum: „Warum rief er nicht an?“ → erlebte ___","a":"Rede"},{"q":"Stilmittel: „Die Stadt war ein Käfig.“ →","a":"Metapher"},{"q":"Stilmittel: „Der Wind flüsterte.“ →","a":"Personifikation"},{"q":"Stilmittel: „Kein Licht. Kein Laut. Kein Mensch.“ →","a":"Anapher"},{"q":"Stilmittel: „Draußen Sommer, drinnen Winter.“ →","a":"Antithese"},{"q":"Stilmittel: „Er rannte wie ein gejagtes Tier.“ →","a":"Vergleich"},{"q":"Interpretation: Dies lässt sich ___ Zeichen der Angst deuten.","a":"als"},{"q":"Interpretation: Der Text legt ___, dass …","a":"nahe"},{"q":"Beleg: Die Wiederholung (Z. 5) ___ die Dringlichkeit. (unterstreichen)","a":"unterstreicht"},{"q":"Fehler? „Die Metapher zeigt, dass der Autor eine Metapher benutzt.“ → Funktion fehlt: Was ___ die Metapher? (bewirken)","a":"bewirkt"}],"exam":[{"q":"Wo steht Marta?","a":"Am Bahnsteig."},{"q":"Was zählt sie?","a":"Die Tauben auf dem Dach."},{"q":"Was hatte Marta beschlossen?","a":"Nicht mehr zurückzufahren."},{"q":"Welche Funktion hat die Anapher „nie wieder“?","a":"Sie unterstreicht die Entschiedenheit des früheren Entschlusses."},{"q":"Wie wird der Wind dargestellt?","a":"Personifiziert – als wollte er sie zurückhalten."},{"q":"Was deutet „wie immer“ an?","a":"Dass die Reise kein Einzelfall ist."},{"q":"Formulieren Sie eine Deutung des Titels „Rückfahrt“ für diesen Auszug.","a":"","m":"Der Titel „Rückfahrt“ deutet nicht nur auf die Zugfahrt nach Hause hin, sondern auch auf eine Reise in die Vergangenheit. Die Figur kehrt innerlich zu ihrer Kindheit zurück."},{"q":"Schreiben Sie eine Interpretation eines Gedichts Ihrer Wahl (250 Wörter).","a":"","m":"Das Gedicht beschreibt einen Herbsttag. Der Sprecher bleibt distanziert. Die Metapher der fallenden Blätter steht für das Altern. Wiederholungen erzeugen einen ruhigen Rhythmus. Insgesamt wirkt der Text melancholisch, aber auch versöhnlich."},{"q":"Setzen Sie die Geschichte fort, ohne die Erzählperspektive zu wechseln.","a":"","m":"Sie sah aus dem Fenster. Die Felder flogen vorbei, und sie dachte an ihre Mutter. Hatte sie damals wirklich nichts gesagt? Der Zug wurde langsamer."},{"q":"Vergleichen Sie zwei Erzählperspektiven und ihre Wirkung auf den Leser.","a":"","m":"Ein Ich-Erzähler wirkt nah und subjektiv; der Leser fühlt mit. Ein auktorialer Erzähler schafft Distanz und Überblick."}],"speak":["Beschreibe einem Freund, worum es im Auszug geht – und was zwischen den Zeilen steht.","Nenne drei Stilmittel im Text und erkläre ihre Wirkung.","Diskutiert: Warum fährt Marta trotzdem zurück?","Erzähl eine Szene aus deinem Leben in erlebter Rede."],"dialog":[{"who":"Dozentin","de":"Welche Erzählperspektive liegt im Auszug vor?"},{"who":"Leila","de":"Eine personale. Wir sehen alles aus Martas Sicht, aber in der dritten Person."},{"who":"Dozentin","de":"Woran machen Sie das fest?"},{"who":"Leila","de":"Es gibt keinen Kommentar eines Erzählers, und die Fragen wie „Warum war sie eigentlich hier?“ sind erlebte Rede."},{"who":"Dozentin","de":"Gut. Und welche Funktion hat die dreifache Wiederholung „nie wieder“?"},{"who":"Leila","de":"Sie zeigt, wie fest Marta sich vorgenommen hatte, nicht zurückzukehren. Umso stärker wirkt dann der Bruch mit „Und jetzt?“."},{"who":"Dozentin","de":"Sehr schön. Sie benennen nicht nur das Mittel, sondern auch seine Wirkung. Genau das erwartet man auf diesem Niveau."}],"dq":[{"q":"Welche Erzählperspektive erkennt Leila?","a":"Eine personale Erzählperspektive."},{"q":"Woran erkennt sie die erlebte Rede?","a":"An Fragen wie „Warum war sie eigentlich hier?“ (ohne Erzählerkommentar)."},{"q":"Was lobt die Dozentin?","a":"Dass Leila nicht nur das Mittel, sondern auch seine Wirkung nennt."}],"en":{"title":"Analysing literary texts: narrative perspective and stylistic devices","theme":"Reading literature","expl":["Analysing literature asks not only **what** is told but **how**. Key is the **narrative perspective**: a first-person narrator tells from their own point of view and is only partly reliable; an omniscient (auktorial) narrator knows everything and comments; a figural (personal) narrator stays inside one character without commenting.","Stylistic devices: metaphor, comparison, repetition, contrast, irony, inner monologue, time jumps. Always say **what effect** a device has."],"use":""},"check":[{"re":"\\\\b(erzähler|perspektive|metapher|vergleich|wirkt|symbol|deutet|ironie|stilmittel)\\\\b","label":"analysis terms (Erzähler, Perspektive, Metapher, wirkt …)"}]},{"n":73,"pos":72,"level":"C2","title":"Fachsprache Recht und Verwaltung verstehen","theme":"Verträge, Bescheide, Gesetze","scene":"office","rec":[45,57],"expl":["Juristische Texte wirken schwer, folgen aber festen Mustern. Typisch sind **Nominalstil** (__nach Ablauf der Frist__), **Passiv und Passiversatz** (__ist zu entrichten, kann verlangt werden__), **Konditionalsätze ohne wenn** (__Erfolgt die Zahlung nicht fristgerecht, …__ = Wenn die Zahlung nicht … erfolgt) und **Verweise** (__gemäß § 3 Abs. 2__, __im Sinne dieses Vertrages__).","Viele Alltagswörter haben eine **Fachbedeutung**: __Besitz__ (tatsächliche Herrschaft) ≠ __Eigentum__ (rechtliche Zugehörigkeit); __Kündigung__ (Beendigung eines Vertrags); __unverzüglich__ (= ohne schuldhaftes Zögern); __Frist__ (Zeitraum), __Termin__ (Zeitpunkt). Modalverben sind präzise: **muss** (Pflicht), **soll** (in der Regel Pflicht, Ausnahmen möglich), **kann** (Ermessen), **darf nicht** (Verbot).","Lesestrategie: zuerst **wer** (Parteien), **was** (Pflicht/Recht), **wann** (Frist), **was passiert sonst** (Rechtsfolge). Lange Sätze zerlegt man, indem man den Hauptsatz sucht und Nominalgruppen in Nebensätze auflöst. Für schriftliche Antworten an Behörden: sachlich, mit Aktenzeichen, Datum und klarer Bitte."],"use":"C2/Beruf: Mietverträge, Arbeitsverträge, Bescheide und AGB verstehen; Widerspruch formulieren; Beratungsgespräche führen.","table":[["Rechtssprache","Alltagssprache"],["Erfolgt die Zahlung nicht fristgerecht, …","Wenn Sie nicht rechtzeitig zahlen, …"],["Die Kosten sind vom Mieter zu tragen.","Der Mieter muss die Kosten bezahlen."],["unverzüglich","sofort, ohne unnötige Verzögerung"],["gemäß § 5 Abs. 1","so wie es in Paragraf 5, Absatz 1 steht"],["Der Widerspruch ist binnen eines Monats einzulegen.","Sie müssen innerhalb eines Monats widersprechen."],["Die Kündigung bedarf der Schriftform.","Man muss schriftlich kündigen."]],"examples":[{"de":"Erfolgt die Zahlung nicht innerhalb von 14 Tagen, wird eine Mahngebühr fällig.","en":"If payment is not made within 14 days, a reminder fee becomes due."},{"de":"Die Kündigung bedarf der Schriftform.","en":"Notice of termination must be given in writing."},{"de":"Die Kosten sind vom Mieter zu tragen.","en":"The costs are to be borne by the tenant."},{"de":"Gegen diesen Bescheid kann binnen eines Monats Widerspruch eingelegt werden.","en":"An objection to this decision can be lodged within one month."},{"de":"Der Arbeitnehmer hat Anspruch auf 30 Tage Erholungsurlaub.","en":"The employee is entitled to 30 days of annual leave."},{"de":"Schäden sind dem Vermieter unverzüglich anzuzeigen.","en":"Damage must be reported to the landlord without delay."},{"de":"Die Regelung gilt vorbehaltlich einer anderslautenden Vereinbarung.","en":"The regulation applies unless otherwise agreed."},{"de":"Im Sinne dieses Vertrages gelten als Nebenkosten …","en":"For the purposes of this contract, ancillary costs are …"},{"de":"Gemäß § 3 Absatz 2 ist die Untervermietung nur mit Zustimmung zulässig.","en":"According to Section 3(2), subletting is only permitted with consent."},{"de":"Der Vertrag verlängert sich stillschweigend um ein Jahr.","en":"The contract is tacitly extended by one year."},{"de":"Unberührt hiervon bleibt das Recht zur außerordentlichen Kündigung.","en":"The right to extraordinary termination remains unaffected."},{"de":"Hiermit lege ich gegen den Bescheid vom 3. März fristgerecht Widerspruch ein.","en":"I hereby lodge an objection to the decision of 3 March within the deadline."},{"de":"Sollte eine Bestimmung unwirksam sein, bleibt der übrige Vertrag gültig.","en":"Should any provision be invalid, the rest of the contract remains valid."},{"de":"Der Besitzer einer Sache ist nicht unbedingt ihr Eigentümer.","en":"The possessor of a thing is not necessarily its owner."},{"de":"Die Behörde soll den Antrag innerhalb von drei Monaten bescheiden.","en":"The authority shall decide on the application within three months."}],"vocab":[{"de":"der Paragraf (§), -en","en":"section (of a law)"},{"de":"der Absatz (Abs.), ¨e","en":"subsection, paragraph"},{"de":"das Aktenzeichen, -","en":"file reference"},{"de":"der Bescheid, -e","en":"official decision"},{"de":"der Widerspruch, ¨e","en":"objection, appeal"},{"de":"der Anspruch, ¨e","en":"entitlement, claim"},{"de":"die Rechtsfolge, -n","en":"legal consequence"},{"de":"die Schriftform","en":"written form"},{"de":"unverzüglich","en":"without undue delay"},{"de":"binnen (+ Dat./Gen.)","en":"within"},{"de":"gemäß (+ Dat.)","en":"in accordance with"},{"de":"vorbehaltlich (+ Gen.)","en":"subject to"},{"de":"unberührt bleiben","en":"to remain unaffected"},{"de":"der Besitz","en":"possession"},{"de":"das Eigentum","en":"ownership, property"},{"de":"die Untervermietung","en":"subletting"},{"de":"außerordentlich","en":"extraordinary"},{"de":"stillschweigend","en":"tacit(ly)"},{"de":"unwirksam","en":"invalid, ineffective"},{"de":"die Allgemeinen Geschäftsbedingungen (AGB)","en":"terms and conditions"}],"reading":"Auszug aus einem Mietvertrag mit Erläuterung: „§ 7 Schönheitsreparaturen. (1) Die Schönheitsreparaturen während der Mietzeit übernimmt der Mieter. (2) Sie sind fachgerecht auszuführen, soweit der Zustand der Räume dies erfordert. (3) Starre Fristen werden nicht vereinbart.“ Was bedeutet das? Absatz 1 legt fest, wer zuständig ist: Der Mieter muss zum Beispiel streichen oder tapezieren. Absatz 2 enthält zwei wichtige Einschränkungen. „Fachgerecht“ heißt nicht, dass ein Maler beauftragt werden muss, sondern dass die Arbeit ordentlich sein muss. Und „soweit der Zustand dies erfordert“ bedeutet: nur wenn es wirklich nötig ist, nicht nach einem festen Kalender. Absatz 3 ist eine Folge der Rechtsprechung des Bundesgerichtshofs, der Klauseln mit starren Fristen – etwa „alle drei Jahre Küche und Bad“ – für unwirksam erklärt hat. Wäre eine solche Klausel im Vertrag enthalten, müsste der Mieter in der Regel gar nicht renovieren. Ein weiteres Beispiel aus dem Vertrag: „§ 12 Kündigung. Die Kündigung bedarf der Schriftform. Sie ist spätestens am dritten Werktag eines Kalendermonats für den Ablauf des übernächsten Monats zulässig.“ Übersetzt: Eine E-Mail genügt nicht, nötig ist ein unterschriebener Brief. Wer bis zum 3. März kündigt, muss bis Ende Mai Miete zahlen; wer erst am 4. März kündigt, bis Ende Juni. Solche Formulierungen wirken umständlich, sind aber präzise, und genau darauf kommt es im Streitfall an.","tasks":[{"q":"Alltagssprache: „Die Kosten sind vom Mieter zu tragen.“ → Der Mieter ___ die Kosten bezahlen.","a":"muss"},{"q":"Alltagssprache: „Die Kündigung bedarf der Schriftform.“ → Man muss ___ kündigen.","a":"schriftlich"},{"q":"Wenn-Satz: „Erfolgt die Zahlung nicht, …“ → ___ die Zahlung nicht erfolgt, …","a":"Wenn"},{"q":"Rechtssprache: innerhalb eines Monats → ___ eines Monats","a":"binnen"},{"q":"Rechtssprache: wie es in § 5 steht → ___ § 5","a":"gemäß"},{"q":"Bedeutung: „unverzüglich“ = ohne unnötige ___","a":"Verzögerung"},{"q":"Unterschied: Wer eine Wohnung mietet, hat den ___, aber nicht das Eigentum.","a":"Besitz"},{"q":"Modalverb: Pflicht ohne Ausnahme → „muss“; Pflicht mit möglichen Ausnahmen → „___“","a":"soll"},{"q":"Modalverb: Die Behörde ___ entscheiden (Ermessen).","a":"kann"},{"q":"Widerspruch: Hiermit ___ ich Widerspruch gegen den Bescheid ein. (einlegen)","a":"lege"},{"q":"Kündigungsfrist: Kündigung am 3. März → Miete zahlen bis Ende ___.","a":"Mai"},{"q":"Fehler? „Gemäß des Vertrags muss ich zahlen.“","a":"Gemäß dem Vertrag muss ich zahlen."}],"exam":[{"q":"Wer übernimmt laut § 7 die Schönheitsreparaturen?","a":"Der Mieter."},{"q":"Was bedeutet „fachgerecht“ hier?","a":"Die Arbeit muss ordentlich sein; man muss keinen Maler beauftragen."},{"q":"Warum gibt es keine starren Fristen?","a":"Der Bundesgerichtshof hat solche Klauseln für unwirksam erklärt."},{"q":"Genügt eine E-Mail zur Kündigung?","a":"Nein, es braucht einen unterschriebenen Brief (Schriftform)."},{"q":"Bis wann muss man zahlen, wenn man am 4. März kündigt?","a":"Bis Ende Juni."},{"q":"Übersetzen Sie in Alltagssprache: „Schäden sind unverzüglich anzuzeigen.“","a":"Schäden müssen sofort gemeldet werden."},{"q":"Schreiben Sie einen Widerspruch gegen einen Bescheid (Aktenzeichen, Datum, Begründung, Bitte).","a":"","m":"Aktenzeichen 123/45 – Bescheid vom 1. März 2026. Sehr geehrte Damen und Herren, hiermit lege ich fristgerecht Widerspruch gegen den oben genannten Bescheid ein. Meine Einkünfte wurden falsch berechnet; die Belege liegen bei. Ich bitte um erneute Prüfung. Mit freundlichen Grüßen"},{"q":"Erklären Sie einem Freund die wichtigsten Punkte seines Arbeitsvertrags in einfacher Sprache.","a":"","m":"Also: Du hast drei Monate Probezeit. In der Zeit kann man mit zwei Wochen kündigen. Du hast 28 Tage Urlaub. Überstunden werden bezahlt oder mit Freizeit ausgeglichen."},{"q":"Vergleichen Sie Rechtssprache im Deutschen und in Ihrer Muttersprache.","a":"","m":"Im Deutschen benutzt man in der Rechtssprache viele Nomen und das Passiv. Im Englischen sind Gesetzestexte ebenfalls kompliziert, aber anders aufgebaut."},{"q":"Warum sind juristische Texte so formuliert? Nehmen Sie Stellung.","a":"","m":"Juristische Texte sind so formuliert, weil sie eindeutig sein müssen. Allerdings versteht sie dadurch kaum jemand ohne Hilfe. Meiner Meinung nach sollten Behörden mehr einfache Sprache benutzen."}],"speak":["Erkläre den Unterschied zwischen Besitz und Eigentum mit einem Beispiel.","„Übersetze“ einen Satz aus einem Vertrag in Alltagssprache.","Spielt eine Mieterberatung: ein Problem, eine Klausel, eine Lösung.","Was würdest du in einem Arbeitsvertrag zuerst prüfen? Warum?"],"dialog":[{"who":"Beraterin","de":"Herr Sharma, Ihr Vermieter verlangt, dass Sie beim Auszug alle Räume streichen. Was steht in Ihrem Vertrag?"},{"who":"Ravi","de":"Hier: „Der Mieter hat die Räume spätestens alle fünf Jahre zu renovieren.“"},{"who":"Beraterin","de":"Das ist eine starre Frist. Solche Klauseln sind nach der Rechtsprechung unwirksam."},{"who":"Ravi","de":"Das heißt, ich muss gar nicht streichen?"},{"who":"Beraterin","de":"In der Regel nicht. Es sei denn, Sie haben die Wohnung beschädigt oder zum Beispiel knallrot gestrichen."},{"who":"Ravi","de":"Nein, die Wände sind weiß. Was soll ich jetzt tun?"},{"who":"Beraterin","de":"Antworten Sie schriftlich, nennen Sie das Datum seines Schreibens und verweisen Sie auf die Unwirksamkeit der Klausel. Ich gebe Ihnen einen Musterbrief."}],"dq":[{"q":"Was verlangt der Vermieter?","a":"Dass Ravi beim Auszug alle Räume streicht."},{"q":"Warum ist die Klausel unwirksam?","a":"Es ist eine starre Frist (alle fünf Jahre)."},{"q":"Was soll Ravi tun?","a":"Schriftlich antworten, das Datum nennen und auf die Unwirksamkeit verweisen."}],"en":{"title":"Understanding legal and administrative language","theme":"Contracts, notices, laws","expl":["Legal texts look hard but follow fixed patterns: nominal style (__nach Ablauf der Frist__ = after the deadline expires), passive and passive alternatives (__ist zu entrichten__ = must be paid), conditions without wenn (__Erfolgt die Zahlung nicht fristgerecht, …__ = If payment is not made on time …) and references (__gemäß § 3 Abs. 2__ = according to section 3, paragraph 2).","Read the main clause first, then unpack the conditions and exceptions one by one."],"use":""},"check":[{"re":"\\\\b(bescheid|aktenzeichen|widerspruch|gemäß|frist|hiermit|fristgerecht|begründung)\\\\b","label":"legal / administrative terms (Bescheid, Frist, hiermit, gemäß …)"}]},{"n":60,"pos":73,"level":"C2","title":"Prüfungsfinale: Vortrag, Diskussion, Textproduktion","theme":"Alles zusammen","scene":"classroom","rec":[42,53,56,58],"expl":["Die C2-Prüfung (Goethe C2 / telc C2) verlangt: **Zusammenfassen** (Lesen/Hören → eigener Text), **Vortrag** (strukturiert, 3–5 Min.), **Diskussion** (Position halten, auf Gegenargumente eingehen), **Textproduktion** (Erörterung oder Kommentar, klar gegliedert, stilistisch sicher).","Bewertet werden: **Erfüllung der Aufgabe, Kohärenz, Wortschatzbreite und -präzision, grammatische Vielfalt, Register**.","Strategie: 2 Minuten planen (These, drei Stützen, Gegenargument, Schluss), Signale setzen (__erstens, ferner, gleichwohl, abschließend__), auf Einwände eingehen (__Sie sprechen einen wichtigen Punkt an; dennoch …__), am Ende **zusammenfassen und pointieren**."],"use":"Prüfungstag, Fachvorträge, Meetings, Bewerbungsgespräche auf höchstem Niveau.","table":[["Phase","Redemittel"],["These setzen","Ich vertrete die Auffassung, dass … · Meine zentrale These lautet: …"],["Gliedern","Erstens … zweitens … ferner … abschließend"],["Belegen","Dies belegt eine Studie von … · Hierfür spricht, dass …"],["Einräumen","Zugegeben: … · Das mag zutreffen, gleichwohl …"],["Widersprechen","Dem möchte ich entgegenhalten, dass … · Das greift meines Erachtens zu kurz."],["Nachfragen","Habe ich Sie richtig verstanden, dass …? · Worauf stützen Sie diese Annahme?"],["Zusammenfassen","Fasse ich zusammen: … · Unterm Strich bleibt festzuhalten: …"],["Pointieren","Entscheidend ist letztlich nicht …, sondern …"]],"examples":[{"de":"Meine zentrale These lautet: Bildung entscheidet über Teilhabe.","en":"My central thesis is: education determines participation."},{"de":"Zugegeben, die Kosten sind hoch; gleichwohl überwiegt der Nutzen.","en":"Admittedly the costs are high; nevertheless the benefit predominates."},{"de":"Dem möchte ich entgegenhalten, dass die Datenlage dünn ist.","en":"To that I would counter that the data are thin."},{"de":"Das greift meines Erachtens zu kurz.","en":"In my view that falls short."},{"de":"Worauf stützen Sie diese Annahme?","en":"What do you base this assumption on?"},{"de":"Unterm Strich bleibt festzuhalten, dass beide Wege gangbar sind.","en":"On balance it should be noted that both routes are viable."},{"de":"Entscheidend ist letztlich nicht die Technik, sondern die Organisation.","en":"Ultimately what matters is not the technology but the organisation."},{"de":"Ich würde die Frage gern etwas differenzierter betrachten.","en":"I\'d like to look at the question in a more differentiated way."},{"de":"Erlauben Sie mir, das an einem Beispiel zu verdeutlichen.","en":"Allow me to illustrate that with an example."},{"de":"Damit komme ich zum Schluss meiner Ausführungen.","en":"With that I come to the end of my remarks."},{"de":"Ich gebe Ihnen insofern recht, als die Kosten gestiegen sind.","en":"I agree with you insofar as costs have risen."},{"de":"Da muss ich Ihnen entschieden widersprechen.","en":"I must strongly disagree with you there."},{"de":"Darf ich kurz einhaken?","en":"May I just come in here?"},{"de":"Lassen Sie mich bitte ausreden.","en":"Please let me finish."},{"de":"Das ist ein berechtigter Einwand, den ich ernst nehme.","en":"That\'s a fair objection that I take seriously."},{"de":"Um auf Ihren Punkt zurückzukommen: Die Zahlen sprechen eine andere Sprache.","en":"To come back to your point: the figures tell a different story."},{"de":"Ich möchte zu bedenken geben, dass nicht alle davon profitieren.","en":"I\'d ask you to consider that not everyone benefits from it."},{"de":"Er führte vor allem ökologische Argumente ins Feld.","en":"He mainly put forward ecological arguments."},{"de":"Lassen Sie mich das kurz relativieren.","en":"Let me put that into perspective briefly."},{"de":"Mein Fazit lautet daher: Wir brauchen beides.","en":"My conclusion is therefore: we need both."}],"vocab":[{"de":"die Auffassung, -en","en":"view, opinion"},{"de":"die Ausführungen (Pl.)","en":"remarks"},{"de":"entgegenhalten","en":"to counter"},{"de":"zu kurz greifen","en":"to fall short"},{"de":"sich stützen auf","en":"to be based on"},{"de":"gangbar","en":"viable"},{"de":"pointieren","en":"to make a point sharply"},{"de":"die Teilhabe","en":"participation"},{"de":"der Nutzen","en":"benefit"},{"de":"differenziert","en":"differentiated"},{"de":"zutreffen","en":"to be true, apply"},{"de":"festhalten","en":"to note, state"},{"de":"die Diskussionsleitung","en":"chairing the discussion"},{"de":"das Plädoyer, -s","en":"plea, closing argument"},{"de":"die Replik, -en","en":"reply, rejoinder"},{"de":"der Einwand, ¨e","en":"objection"},{"de":"die Gegenposition, -en","en":"opposing position"},{"de":"einlenken","en":"to give way, to compromise"},{"de":"zuspitzen","en":"to bring to a head; to sharpen"},{"de":"relativieren","en":"to put into perspective"},{"de":"auf etwas eingehen","en":"to address something"},{"de":"etwas ins Feld führen","en":"to put forward (an argument)"},{"de":"etwas zu bedenken geben","en":"to ask someone to consider something"},{"de":"einen Standpunkt vertreten","en":"to hold a position"},{"de":"Ich gebe Ihnen insofern recht, als …","en":"I agree with you insofar as …"},{"de":"Da muss ich Ihnen widersprechen.","en":"I have to disagree with you there."},{"de":"Lassen Sie mich ausreden.","en":"Let me finish."},{"de":"Darf ich kurz einhaken?","en":"May I just come in here?"},{"de":"Um auf Ihren Punkt zurückzukommen, …","en":"To come back to your point, …"},{"de":"Das ist ein berechtigter Einwand.","en":"That\'s a fair objection."},{"de":"die Schlussfolgerung, -en","en":"conclusion"},{"de":"das Fazit, -s","en":"conclusion, summary"}],"reading":"Prüfungsmitschnitt (Auszug): „Meine zentrale These lautet: Kurzarbeit hat in der Krise Arbeitsplätze gesichert. Erstens zeigen die Zahlen einen deutlich geringeren Stellenabbau; zweitens blieb Fachwissen in den Betrieben; ferner konnten Unternehmen schneller wieder hochfahren. Zugegeben, das Instrument ist teuer und kann Strukturwandel verzögern – dem möchte ich entgegenhalten, dass die Alternativkosten höher gewesen wären. Unterm Strich bleibt festzuhalten: Entscheidend ist nicht die Existenz des Instruments, sondern seine zeitliche Begrenzung.“","tasks":[{"q":"These setzen: ___ ___ ___ lautet: Sprache schafft Zugang.","a":"Meine zentrale These"},{"q":"Einräumen: ___, das Verfahren ist teuer; ___ lohnt es sich.","a":"Zugegeben / gleichwohl"},{"q":"Widersprechen: ___ möchte ich ___, dass die Studie alt ist.","a":"Dem / entgegenhalten"},{"q":"Gliedern: erstens, zweitens, ___, abschließend","a":"ferner"},{"q":"Nachfragen: ___ ___ Sie diese Annahme?","a":"Worauf stützen"},{"q":"Zusammenfassen: ___ ___ bleibt festzuhalten, dass …","a":"Unterm Strich"},{"q":"Pointieren: Entscheidend ist nicht X, ___ Y.","a":"sondern"},{"q":"[Mix] Der Prüfling betont, das Instrument ___ Arbeitsplätze gesichert. (Konj. I Perfekt von haben)","a":"habe"},{"q":"[Mix] ___ der hohen Kosten überwiegt der Nutzen. (Genitivpräposition, konzessiv)","a":"Trotz"},{"q":"[Mix] Die ___ (sichern, Part. II) Arbeitsplätze sind ___ (belegen, sein+zu).","a":"gesicherten / zu belegen"},{"q":"Zustimmen mit Einschränkung: Ich gebe Ihnen ___ recht, als …","a":"insofern"},{"q":"Widersprechen: Da muss ich Ihnen ___.","a":"widersprechen"},{"q":"Unterbrechen: Darf ich kurz ___?","a":"einhaken"},{"q":"Sich wehren: Lassen Sie mich bitte ___.","a":"ausreden"},{"q":"Anerkennen: Das ist ein ___ Einwand.","a":"berechtigter"},{"q":"Zurückkommen: Um auf Ihren Punkt ___, …","a":"zurückzukommen"},{"q":"Argumente: Er führte wirtschaftliche Gründe ins ___.","a":"Feld"},{"q":"Bedenken: Ich möchte zu ___ geben, dass …","a":"bedenken"},{"q":"Schluss: Mein ___ lautet: Wir brauchen beides.","a":"Fazit"},{"q":"Fehler? „Ich gebe Ihnen recht insofern, dass die Zahlen stimmen.“","a":"Ich gebe Ihnen insofern recht, als die Zahlen stimmen."}],"exam":[{"q":"Welche These vertritt der Prüfling?","a":"Kurzarbeit hat Arbeitsplätze gesichert."},{"q":"Welche drei Argumente nennt er?","a":"Geringerer Stellenabbau, Fachwissen blieb, schnelleres Hochfahren."},{"q":"Welchen Einwand räumt er ein?","a":"Das Instrument ist teuer und kann den Strukturwandel verzögern."},{"q":"Formulieren Sie ein Gegenargument zu seiner These.","a":"","m":"Dem kann man entgegenhalten, dass Technik allein keine Probleme löst. Entscheidend ist, wie Menschen sie einsetzen."},{"q":"Fassen Sie den Auszug in zwei Sätzen zusammen (indirekte Rede).","a":"","m":"Der Autor vertritt die Ansicht, Bildung sei der Schlüssel zur Integration. Er betont, ohne Sprache sei Teilhabe kaum möglich."},{"q":"Nennen Sie zwei Redemittel, um höflich zu widersprechen.","a":"","m":"„Da möchte ich widersprechen …“ und „Ich sehe das etwas anders, denn …“."},{"q":"Wie strukturieren Sie einen 4-Minuten-Vortrag? Skizzieren Sie die Gliederung.","a":"","m":"Einleitung mit Frage und Thema, dann Gliederung. Hauptteil: drei Argumente mit Beispielen, ein Gegenargument. Schluss: Fazit und Ausblick."},{"q":"Halten Sie einen Vortrag: „Künstliche Intelligenz im Beruf – Chance oder Risiko?“","a":"","m":"Künstliche Intelligenz verändert die Arbeitswelt grundlegend. Einerseits übernimmt sie Routineaufgaben, sodass Menschen sich auf kreative Arbeit konzentrieren können. Andererseits drohen in manchen Berufen Stellen wegzufallen. Darüber hinaus stellen sich Fragen des Datenschutzes. Meines Erachtens ist KI eine Chance, sofern wir rechtzeitig in Weiterbildung investieren."},{"q":"Schreiben Sie einen Kommentar (150 Wörter) zu einem aktuellen Thema.","a":"","m":"Die Viertagewoche wird immer häufiger diskutiert. Befürworter betonen, sie steigere die Zufriedenheit. Kritiker geben zu bedenken, dass nicht jede Branche mitmachen könne. Meines Erachtens sollte man das Modell zunächst testen. Abschließend bleibt festzuhalten, dass Flexibilität wichtiger ist als starre Regeln."},{"q":"Diskutieren Sie mit einem Partner und gehen Sie dreimal auf Gegenargumente ein.","a":"","m":"Ich verstehe Ihr Argument, sehe aber einen anderen Punkt. Zwar haben Sie recht, was die Kosten angeht, jedoch überwiegen die Vorteile. Darüber hinaus gebe ich zu bedenken, dass sich die Investition langfristig lohnt."}],"speak":["Halte einen 3-Minuten-Vortrag zu einem Thema deines Fachs – mit These, drei Stützen, Einwand, Schluss.","Reagiere auf drei Gegenargumente, ohne deine Position aufzugeben.","Fasse einen gehörten Beitrag zusammen und bewerte ihn.","Nimm dich auf: Wo fehlt Präzision, wo Register, wo Struktur?"],"reading2":{"title":"Vortrag: Sprache als Schlüssel zur Teilhabe – Abschlussrede im C2-Kurs","text":"„Sehr geehrte Damen und Herren, liebe Mitlernende, als ich vor vier Jahren meinen ersten Deutschkurs besuchte, bestand mein Wortschatz aus etwa zwanzig Wörtern, von denen ich die Hälfte falsch aussprach. Heute darf ich vor Ihnen über eine Frage sprechen, die mich seither begleitet: Inwiefern ist Sprache der Schlüssel zur gesellschaftlichen Teilhabe? Gemeinhin wird diese Frage schnell bejaht. Wer die Sprache des Landes beherrscht, findet leichter Arbeit, versteht Behördenbriefe und kann sich politisch einbringen. Das ist zweifellos richtig. Doch ich möchte die These ein wenig zuspitzen: Sprache ist nicht nur ein Schlüssel, sie ist auch eine Tür, die von beiden Seiten geöffnet werden muss. Lassen Sie mich das an einem Beispiel verdeutlichen. In meinem ersten Jahr in Berlin habe ich mich nach Kräften bemüht, Deutsch zu sprechen. Allzu oft antwortete man mir jedoch auf Englisch, gut gemeint, aber mit der Folge, dass ich kaum Gelegenheit zum Üben hatte. Teilhabe setzt also nicht nur Lernbereitschaft voraus, sondern auch Geduld auf Seiten der Gesellschaft. Man könnte einwenden, dies sei eine Frage der Höflichkeit und nicht der Integrationspolitik. Ich gebe Ihnen insofern recht, als niemand verpflichtet ist, langsamer zu sprechen. Dennoch zeigen Studien, dass Zugewanderte, die regelmäßig Kontakt zu Muttersprachlern haben, die Sprache deutlich schneller erwerben. Sprachförderung endet folglich nicht im Kursraum. Sie findet in Vereinen statt, am Arbeitsplatz, im Treppenhaus. Ein weiterer Aspekt wird häufig übersehen: Sprache ist nie nur Werkzeug, sie ist auch Identität. Wer Deutsch lernt, gibt seine Erstsprache nicht auf. Mehrsprachigkeit sollte daher nicht als Defizit, sondern als Ressource betrachtet werden – für den Einzelnen ebenso wie für die Gesellschaft. Mein Fazit lautet deshalb: Ja, Sprache ist der Schlüssel zur Teilhabe. Aber ein Schlüssel nützt wenig, wenn niemand die Tür öffnet. Ich danke Ihnen allen, die mir in den vergangenen vier Jahren die Tür geöffnet haben – und Ihnen für Ihre Aufmerksamkeit.“"},"dialog":[{"who":"Moderatorin","de":"Vielen Dank für Ihren Vortrag. Herr Dr. Hahn, Sie sehen das etwas anders?"},{"who":"Dr. Hahn","de":"Teilweise. Ich gebe Ihnen insofern recht, als Kontakt wichtig ist. Aber Sie verlagern die Verantwortung zu sehr auf die Gesellschaft."},{"who":"Leila","de":"Darf ich kurz einhaken? Ich spreche ja von beiden Seiten, nicht nur von einer."},{"who":"Dr. Hahn","de":"Lassen Sie mich bitte ausreden. Der Staat bietet Integrationskurse an. Wer sie nutzt, hat sehr gute Chancen."},{"who":"Leila","de":"Das ist ein berechtigter Einwand. Allerdings enden diese Kurse meist auf B1-Niveau, und für viele Berufe reicht das nicht."},{"who":"Dr. Hahn","de":"Da muss ich Ihnen zustimmen. Die Finanzierung höherer Kurse ist tatsächlich ausbaufähig."},{"who":"Moderatorin","de":"Dann haben wir ja doch einen gemeinsamen Nenner gefunden."}],"dq":[{"q":"Was wirft Dr. Hahn Leila vor?","a":"Sie verlagere die Verantwortung zu sehr auf die Gesellschaft."},{"q":"Welches Argument bringt Leila zu den Integrationskursen?","a":"Sie enden meist auf B1-Niveau, das reicht für viele Berufe nicht."},{"q":"Worin stimmen beide am Ende überein?","a":"Die Finanzierung höherer Kurse ist ausbaufähig."}],"en":{"title":"Final exam: talk, discussion, writing","theme":"Bringing it all together","expl":["The C2 exam (Goethe C2 / telc C2) asks you to **summarise** (reading/listening → your own text), give a **talk** (structured, 3–5 minutes), **discuss** (hold your position and respond to counter-arguments) and **write** (an argumentative essay or commentary, clearly structured and stylistically confident).","Assessed: task fulfilment, coherence, range of vocabulary, accuracy and register. This lesson brings together everything from A1 to C2."],"use":""},"check":[{"re":"\\\\b(einerseits|andererseits|zunächst|darüber hinaus|abschließend|meines erachtens|ich gebe zu bedenken|zwar)\\\\b","label":"structure and argument phrases"}]}]');
